func rubyString(value string) *object.EmeraldValue {
	str := &object.EmeraldValue{Type: object.ValueString, Data: value, Class: R.Classes["String"]}
	if stringEncodings != nil {
		stringEncodings[str] = defaultExternalEncoding
	}
	return str
}

func EnvObject() *object.EmeraldValue {
	if envObject != nil {
		return envObject
	}
	env := &object.RHash{Pairs: make(map[*object.EmeraldValue]*object.EmeraldValue), Keys: []*object.EmeraldValue{}}
	for _, entry := range os.Environ() {
		key, value, ok := strings.Cut(entry, "=")
		if !ok {
			continue
		}
		keyValue := rubyString(key)
		env.Pairs[keyValue] = rubyString(value)
		env.Keys = append(env.Keys, keyValue)
	}
	envObject = &object.EmeraldValue{Type: object.ValueHash, Data: env, Class: R.Classes["Hash"]}
	return envObject
}

func envString(name string) (string, bool) {
	if val, ok := hashLookup(valueToHashMap(EnvObject()), rubyString(name)); ok && val != nil && val.Type == object.ValueString {
		return val.Data.(string), true
	}
	return "", false
}

func EnvString(name string) (string, bool) {
	return envString(name)
}

func envCoerceKey(value *object.EmeraldValue) (string, *object.EmeraldValue) {
	key, ok, viaToStr, errVal := evalCoerceToString(value)
	if errVal != nil {
		return "", errVal
	}
	if !ok {
		return "", conversionTypeErrorToStringForMode(value, viaToStr)
	}
	return key, nil
}

func StdoutObject() *object.EmeraldValue {
	if stdoutObject != nil {
		return stdoutObject
	}
	stdoutObject = standardIOObject(1, "w")
	return stdoutObject
}

func StderrObject() *object.EmeraldValue {
	if stderrObject != nil {
		return stderrObject
	}
	stderrObject = standardIOObject(2, "w")
	return stderrObject
}

func StdinObject() *object.EmeraldValue {
	if stdinObject != nil {
		return stdinObject
	}
	stdinObject = standardIOObject(0, "r")
	return stdinObject
}

func standardIOObject(fd int64, mode string) *object.EmeraldValue {
	ioValue := newIOShimValue("IO")
	if data := ioShim(ioValue); data != nil {
		if ioDataByFd != nil {
			oldFD := data.fd
			delete(ioDataByFd, oldFD)
			ioDataByFd[fd] = data
		}
		data.fd = fd
		data.hostStandard = fd >= 0 && fd <= 2
		data.mode = mode
		data.encodingExplicit = false
		data.readClosed = false
		data.writeClosed = false
		data.sync = fd == 2
	}
	return ioValue
}

