func classNew(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	cls, ok := receiver.Data.(*object.Class)
	if !ok {
		return typeError("uninitialized class")
	}
	if classIsSingletonValueClass(cls) {
		return NewNoMethodError("undefined method `new'")
	}
	if cls.Name == "Float" || cls.Name == "Rational" {
		return NewNoMethodError("undefined method `new' for " + cls.Name + ":Class")
	}
	if cls != R.Classes["Struct"] && R.Classes["Struct"] != nil && classInheritsFrom(cls, R.Classes["Struct"]) && structFieldsForClass(cls) == nil {
		return structClassNew(receiver, args...)
	}
	if cls.IsSingleton {
		return typeError("can't create instance of singleton class")
	}
	if cls.Name == "Class" {
		superClass := R.Classes["Object"]
		if len(args) > 0 {
			if args[0] == nil || args[0].Type != object.ValueClass {
				return typeError("superclass must be an instance of Class")
			}
			superClass = args[0].Data.(*object.Class)
			if superClass.IsSingleton {
				return typeError("can't make subclass of singleton class")
			}
		}
		newClass := object.NewClass("")
		newClass.SuperClass = superClass
		classValue := &object.EmeraldValue{
			Type:  object.ValueClass,
			Data:  newClass,
			Class: R.Classes["Class"],
		}
		trackObjectSpaceValue(classValue)
		NotifyClassInherited(&object.EmeraldValue{Type: object.ValueClass, Data: superClass, Class: R.Classes["Class"]}, classValue)
		if CurrentBlockValue != nil && CurrentBlockValue() != nil && CallMethod != nil {
			result := CallMethod(classValue, "__exec_class_body__")
			if result != nil && result.Type == object.ValueException {
				return result
			}
		}
		return classValue
	}
	if classInheritsFrom(cls, R.Classes["Exception"]) {
		message := classToS(cls)
		if len(args) > 0 {
			if s, ok := args[0].Data.(string); ok {
				message = s
			} else {
				message = args[0].Inspect()
			}
		}
		obj := newExceptionObject(cls, message)
		if len(args) > 0 {
			if exc, ok := obj.Data.(*object.RException); ok {
				exc.MessageValue = args[0]
			}
		}
		call := CallMethodBypass
		if call == nil {
			call = CallMethod
		}
		if call != nil && classHasMethod(cls, "initialize") {
			if result := call(obj, "initialize", args...); result != nil && result.Type == object.ValueException && result != obj {
				return result
			}
		}
		return obj
	}
	if classInheritsFrom(cls, R.Classes["String"]) {
		obj := &object.EmeraldValue{Type: object.ValueString, Data: "", Class: cls}
		SetStringEncoding(obj, "BINARY")
		if classHasMethod(cls, "initialize") {
			call := CallMethodBypass
			if call == nil {
				call = CallMethod
			}
			if call != nil {
				if result := call(obj, "initialize", args...); result != nil && result.Type == object.ValueException {
					return result
				}
			}
		}
		return obj
	}
	if classInheritsFrom(cls, R.Classes["Regexp"]) {
		obj := &object.EmeraldValue{Type: object.ValueRegexp, Data: &object.RRegexp{Options: "__uninitialized__"}, Class: cls}
		call := CallMethodBypass
		if call == nil {
			call = CallMethod
		}
		if call != nil {
			if result := call(obj, "initialize", args...); result != nil && result.Type == object.ValueException {
				return result
			}
		}
		return obj
	}
	if classInheritsFrom(cls, R.Classes["Array"]) {
		obj := &object.EmeraldValue{
			Type:  object.ValueArray,
			Data:  []*object.EmeraldValue{},
			Class: cls,
		}
		if CallMethod != nil && classHasMethod(cls, "initialize") {
			result := CallMethod(obj, "initialize", args...)
			if result != nil && result.Type == object.ValueException {
				return result
			}
		}
		return obj
	}
	if classInheritsFrom(cls, R.Classes["Hash"]) {
		obj := emptyHashValue()
		obj.Class = cls
		result := (*object.EmeraldValue)(nil)
		if _, owner, ok := cls.GetMethodWithOwner("initialize"); ok && owner != nil && owner != R.Classes["Hash"] {
			call := CallMethodBypass
			if call == nil {
				call = CallMethod
			}
			if call != nil {
				result = call(obj, "initialize", args...)
			}
		} else {
			result = hashInitialize(obj, args...)
		}
		if result != nil && result.Type == object.ValueException {
			return result
		}
		return obj
	}
	if classInheritsFrom(cls, R.Classes["Range"]) {
		return rangeClassNewWithClass(cls, args...)
	}
	if classInheritsFrom(cls, R.Classes["Set"]) {
		obj := &object.EmeraldValue{Type: object.ValueObject, Data: object.NewObject(cls), Class: cls}
		result := setInitialize(obj, args...)
		if result != nil && result.Type == object.ValueException {
			return result
		}
		return obj
	}
	obj := &object.EmeraldValue{
		Type:  object.ValueObject,
		Data:  object.NewObject(cls),
		Class: cls,
	}
	trackObjectSpaceValue(obj)
	if cls.Name == "BasicObject" {
		if len(args) > 0 {
			return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 0)", len(args)))
		}
		return obj
	}
	if CallMethod != nil && classHasMethod(cls, "initialize") {
		call := CallMethodBypass
		if call == nil {
			call = CallMethod
		}
		previousBlockResult := LastBlockResult
		hasBlock := CurrentBlockValue != nil && CurrentBlockValue() != nil
		if hasBlock {
			LastBlockResult = nil
		}
		result := call(obj, "initialize", args...)
		if result != nil && result.Type == object.ValueException {
			if hasBlock {
				LastBlockResult = previousBlockResult
			}
			return result
		}
		if hasBlock && LastBlockResult != nil {
			blockResult := LastBlockResult
			LastBlockResult = previousBlockResult
			return blockResult
		}
		if hasBlock {
			LastBlockResult = previousBlockResult
		}
	}
	populateObjectIvarsFromKeywordHash(obj, args...)
	if classInheritsFrom(cls, R.Classes["Thread"]) {
		if _, ok := obj.Data.(*threadData); !ok {
			return threadError("uninitialized thread")
		}
	}
	return obj
}

func NotifyClassInherited(superValue, childValue *object.EmeraldValue) {
	if superValue == nil || childValue == nil || superValue.Type != object.ValueClass || childValue.Type != object.ValueClass {
		return
	}
	superClass := superValue.Data.(*object.Class)
	child := childValue.Data.(*object.Class)
	classHierarchyMu.Lock()
	found := false
	for _, existing := range superClass.DirectSubclasses {
		if existing == child {
			found = true
			break
		}
	}
	if !found && !child.IsSingleton {
		superClass.DirectSubclasses = append(superClass.DirectSubclasses, child)
	}
	classHierarchyMu.Unlock()
	if CallMethodWithoutBlockBypass != nil && receiverHasCallableMethod(superValue, "inherited") {
		_ = CallMethodWithoutBlockBypass(superValue, "inherited", childValue)
	}
}

func classSubclasses(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 0 {
		return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 0)", len(args)))
	}
	class, ok := receiver.Data.(*object.Class)
	if !ok {
		return &object.EmeraldValue{Type: object.ValueArray, Data: []*object.EmeraldValue{}, Class: R.Classes["Array"]}
	}
	classHierarchyMu.Lock()
	children := append([]*object.Class(nil), class.DirectSubclasses...)
	classHierarchyMu.Unlock()
	result := make([]*object.EmeraldValue, 0, len(children))
	seen := map[*object.Class]bool{}
	for _, child := range children {
		if child == nil || child.IsSingleton || seen[child] {
			continue
		}
		seen[child] = true
		result = append(result, &object.EmeraldValue{Type: object.ValueClass, Data: child, Class: R.Classes["Class"]})
	}
	return &object.EmeraldValue{Type: object.ValueArray, Data: result, Class: R.Classes["Array"]}
}

func classAllocate(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 0 {
		return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 0)", len(args)))
	}
	cls, ok := receiver.Data.(*object.Class)
	if !ok {
		return R.NilVal
	}
	if cls.IsSingleton {
		return typeError("can't create instance of singleton class")
	}
	if cls.Name == "MatchData" {
		return NewNoMethodError("undefined method `allocate' for MatchData:Class")
	}
	if classIsSingletonValueClass(cls) || classHasUndefinedAllocator(cls) {
		return typeError("allocator undefined for " + cls.Name)
	}
	if classInheritsFrom(cls, R.Classes["Array"]) {
		return &object.EmeraldValue{
			Type:  object.ValueArray,
			Data:  []*object.EmeraldValue{},
			Class: cls,
		}
	}
	if classInheritsFrom(cls, R.Classes["Hash"]) {
		obj := emptyHashValue()
		obj.Class = cls
		return obj
	}
	if classInheritsFrom(cls, R.Classes["String"]) {
		obj := &object.EmeraldValue{Type: object.ValueString, Data: "", Class: cls}
		SetStringEncoding(obj, "BINARY")
		return obj
	}
	if classInheritsFrom(cls, R.Classes["Range"]) {
		return &object.EmeraldValue{
			Type:  object.ValueRange,
			Data:  &object.RRange{},
			Class: cls,
		}
	}
	if classInheritsFrom(cls, R.Classes["Regexp"]) {
		return &object.EmeraldValue{Type: object.ValueRegexp, Data: &object.RRegexp{Options: "__uninitialized__"}, Class: cls}
	}
	return &object.EmeraldValue{
		Type:  object.ValueObject,
		Data:  object.NewObject(cls),
		Class: cls,
	}
}

func classIsSingletonValueClass(cls *object.Class) bool {
	return cls != nil && (cls.Name == "FalseClass" || cls.Name == "TrueClass" || cls.Name == "NilClass")
}

func classHasUndefinedAllocator(cls *object.Class) bool {
	return cls != nil && (cls.Name == "Enumerator::ArithmeticSequence" || cls.Name == "Float")
}

func rangeClassNewWithClass(cls *object.Class, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) < 2 || len(args) > 3 {
		return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 2..3)", len(args)))
	}
	startValue := args[0]
	endValue := args[1]
	startMissing := false
	endMissing := false
	if startValue != nil && endValue != nil && startValue.Type != object.ValueNil && endValue.Type != object.ValueNil {
		if errVal := rangeValidateComparableEndpoints(startValue, endValue); errVal != nil {
			return errVal
		}
	}
	exclusive := false
	if len(args) >= 3 {
		exclusive = isTruthy(args[2])
	}
	r := rangeDataFromValues(startValue, endValue, startMissing, endMissing, exclusive)
	return &object.EmeraldValue{
		Type:   object.ValueRange,
		Data:   r,
		Class:  cls,
		Frozen: cls == R.Classes["Range"],
	}
}

func rangeValidateComparableEndpoints(startValue, endValue *object.EmeraldValue) *object.EmeraldValue {
	if startValue == nil || endValue == nil {
		return nil
	}
	if startValue == endValue {
		return nil
	}
	if CallMethod != nil && startValue.Class != nil && receiverHasCallableMethod(startValue, "<=>") {
		cmp := CallMethod(startValue, "<=>", endValue)
		if cmp != nil && cmp.Type == object.ValueException {
			return cmp
		}
		if cmp == nil || cmp.Type == object.ValueNil {
			return NewArgumentError("bad value for range")
		}
		if cmp.Type != object.ValueInteger {
			return NewArgumentError("bad value for range")
		}
		return nil
	}
	if _, ok := rangeCompareValues(startValue, endValue); !ok {
		return NewArgumentError("bad value for range")
	}
	return nil
}

func rangeDataFromValues(startValue, endValue *object.EmeraldValue, startMissing, endMissing, exclusive bool) *object.RRange {
	var start, end int64
	var startRaw, endRaw float64
	startFloat := false
	endFloat := false
	if !startMissing && startValue != nil {
		if n, ok := startValue.Data.(int64); ok {
			start = n
			startRaw = float64(n)
		} else if n, ok := startValue.Data.(float64); ok {
			start = int64(n)
			startRaw = n
			startFloat = true
		}
	}
	if !endMissing && endValue != nil {
		if n, ok := endValue.Data.(int64); ok {
			end = n
			endRaw = float64(n)
		} else if n, ok := endValue.Data.(float64); ok {
			end = int64(n)
			endRaw = n
			endFloat = true
		}
	}
	if startMissing {
		startValue = nil
	}
	if endMissing {
		endValue = nil
	}
	return &object.RRange{
		Start:        start,
		End:          end,
		StartValue:   startValue,
		EndValue:     endValue,
		StartFloat:   startFloat,
		EndFloat:     endFloat,
		StartRaw:     startRaw,
		EndRaw:       endRaw,
		StartMissing: startMissing,
		EndMissing:   endMissing,
		Exclusive:    exclusive,
	}
}

func classHasMethod(class *object.Class, name string) bool {
	if class == nil {
		return false
	}
	if name == "initialize" {
		method, owner, ok := class.GetMethodWithOwner(name)
		if !ok {
			return false
		}
		if owner != nil && owner.Name == "BasicObject" && class.Name != "BasicObject" {
			return false
		}
		return method != nil
	}
	_, ok := class.GetMethod(name)
	return ok
}

func moduleClassNew(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	module := object.NewModule("")
	class := R.Classes["Module"]
	if receiver != nil && receiver.Type == object.ValueClass {
		if receiverClass, ok := receiver.Data.(*object.Class); ok && receiverClass != nil && classInheritsFrom(receiverClass, R.Classes["Module"]) {
			class = receiverClass
		}
	}
	moduleValue := &object.EmeraldValue{
		Type:  object.ValueModule,
		Data:  module,
		Class: class,
	}
	trackObjectSpaceValue(moduleValue)
	call := CallMethodBypass
	if call == nil {
		call = CallMethod
	}
	if call != nil {
		result := call(moduleValue, "initialize", args...)
		if result != nil && result.Type == object.ValueException {
			return result
		}
	}
	return moduleValue
}

func moduleInitialize(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 0 {
		return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 0)", len(args)))
	}
	if CurrentBlockValue != nil && CurrentBlockValue() != nil && CallMethod != nil {
		return CallMethod(receiver, "__exec_class_body__")
	}
	return R.NilVal
}

func populateObjectIvarsFromKeywordHash(value *object.EmeraldValue, args ...*object.EmeraldValue) {
	if value == nil || len(args) == 0 || args[0] == nil || args[0].Type != object.ValueHash {
		return
	}
	obj, ok := value.Data.(*object.Object)
	if !ok {
		return
	}
	for key, val := range valueToHashMap(args[0]) {
		switch specName(key) {
		case "name":
			if existing := obj.GetInstanceVar("@name"); existing == nil || existing.Type == object.ValueNil {
				obj.SetInstanceVar("@name", val)
			}
		case "offset":
			if existing := obj.GetInstanceVar("@offset"); existing == nil || existing.Type == object.ValueNil {
				obj.SetInstanceVar("@offset", val)
			}
		}
	}
}

func structClassNew(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	parent, ok := receiver.Data.(*object.Class)
	if !ok {
		return typeError("uninitialized class")
	}
	if parent != R.Classes["Struct"] && structFieldsForClass(parent) != nil {
		return classNew(receiver, args...)
	}
	structClass := object.NewClass("")
	structClass.SuperClass = parent

	fieldArgs := args
	constantName := ""
	if len(fieldArgs) > 0 && fieldArgs[len(fieldArgs)-1] != nil && fieldArgs[len(fieldArgs)-1].Type == object.ValueHash {
		options := valueToHashMap(fieldArgs[len(fieldArgs)-1])
		if len(options) > 0 {
			for key, value := range options {
				if specName(key) != "keyword_init" {
					return typeError("unknown keyword: " + specName(key))
				}
				if value == nil || value.Type == object.ValueNil {
					structClass.StructKeywordInit = 0
				} else if isTruthy(value) {
					structClass.StructKeywordInit = 1
				} else {
					structClass.StructKeywordInit = 2
				}
			}
			fieldArgs = fieldArgs[:len(fieldArgs)-1]
		}
	}
	if len(fieldArgs) > 0 {
		first := fieldArgs[0]
		if first == nil || first.Type == object.ValueNil {
			fieldArgs = fieldArgs[1:]
		} else if first.Type == object.ValueString || (first.Type != object.ValueSymbol && receiverHasCallableMethod(first, "to_str")) {
			if first.Type != object.ValueString {
				first = CallMethod(first, "to_str")
			}
			if first == nil || first.Type != object.ValueString {
				return typeError("no implicit conversion into String")
			}
			constantName = first.Data.(string)
			if constantName == "" || constantName[0] < 'A' || constantName[0] > 'Z' {
				return newRuntimeException(R.Classes["NameError"], "identifier "+constantName+" needs to be constant")
			}
			fieldArgs = fieldArgs[1:]
			parentName := classToS(parent)
			if parentName == "" || strings.HasPrefix(parentName, "#<") {
				parentName = "Struct"
			}
			structClass.Name = parentName + "::" + constantName
		}
	}
	fields := make([]string, 0, len(fieldArgs))
	seen := map[string]bool{}
	for _, arg := range fieldArgs {
		name := structFieldName(arg)
		if name == "" {
			return typeError("wrong member name")
		}
		if seen[name] {
			return NewArgumentError("duplicate member: " + name)
		}
		seen[name] = true
		fields = append(fields, name)
		field := name
		index := len(fields) - 1
		structClass.DefineMethod(field, &object.Method{
			Name:  field,
			Arity: 0,
			Fn: func(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
				return structValueAt(receiver, index)
			},
		})
		structClass.DefineMethod(field+"=", &object.Method{
			Name:  field + "=",
			Arity: 1,
			Fn: func(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
				if len(args) == 0 {
					return R.NilVal
				}
				if receiver.Frozen {
					return frozenError("can't modify frozen Struct")
				}
				if obj, ok := receiver.Data.(*object.Object); ok && index < len(obj.StructValues) {
					obj.StructValues[index] = args[0]
				}
				return args[0]
			},
		})
	}
	structClass.StructFields = append([]string{}, fields...)
	if !stringSliceContains(fields, "select") {
		structClass.DefineMethod("select", &object.Method{
			Name:  "select",
			Arity: -1,
			Fn: func(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
				return structSelectWithFields(receiver, fields, args...)
			},
		})
	}

	result := &object.EmeraldValue{
		Type:  object.ValueClass,
		Data:  structClass,
		Class: R.Classes["Class"],
	}
	structClass.DefineClassMethod("members", &object.Method{Name: "members", Fn: structClassMembers, Arity: 0})
	structClass.DefineClassMethod("keyword_init?", &object.Method{Name: "keyword_init?", Fn: structClassKeywordInit, Arity: 0})
	structClass.DefineClassMethod("[]", &object.Method{Name: "[]", Fn: classNew, Arity: -1})
	if constantName != "" {
		parent.DefineConstant(constantName, result)
		AssignConstantName(receiver, constantName, result)
	}
	if CurrentBlockValue != nil && CurrentBlockValue() != nil && CallBlockWithSelf != nil {
		blockResult := CallBlockWithSelf(CurrentBlockValue(), result, result)
		if blockResult != nil && blockResult.Type == object.ValueException {
			return blockResult
		}
	}
	return result
}

func structFieldsForClass(class *object.Class) []string {
	for current := class; current != nil; current = current.SuperClass {
		if current.StructFields != nil {
			return current.StructFields
		}
	}
	return nil
}

func structKeywordModeForClass(class *object.Class) int {
	for current := class; current != nil; current = current.SuperClass {
		if current.StructFields != nil {
			return current.StructKeywordInit
		}
	}
	return 0
}

func structValueAt(receiver *object.EmeraldValue, index int) *object.EmeraldValue {
	if obj, ok := receiver.Data.(*object.Object); ok && index >= 0 && index < len(obj.StructValues) {
		if obj.StructValues[index] != nil {
			return obj.StructValues[index]
		}
	}
	return R.NilVal
}

func structInitialize(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	obj, ok := receiver.Data.(*object.Object)
	if !ok {
		return R.NilVal
	}
	fields := structFieldsForClass(receiver.Class)
	obj.StructValues = make([]*object.EmeraldValue, len(fields))
	for i := range obj.StructValues {
		obj.StructValues[i] = R.NilVal
	}
	mode := structKeywordModeForClass(receiver.Class)
	if mode == 1 {
		if len(args) == 0 {
			return R.NilVal
		}
		if len(args) != 1 || args[0] == nil || args[0].Type != object.ValueHash {
			return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 0)", len(args)))
		}
		fieldIndex := map[string]int{}
		for i, field := range fields {
			fieldIndex[field] = i
		}
		unknown := []string{}
		for key, value := range valueToHashMap(args[0]) {
			name := dataKeyName(key)
			if index, found := fieldIndex[name]; found {
				obj.StructValues[index] = value
			} else {
				unknown = append(unknown, name)
			}
		}
		if len(unknown) > 0 {
			sort.Strings(unknown)
			return NewArgumentError("unknown keywords: " + strings.Join(unknown, ", "))
		}
		return R.NilVal
	}
	values := append([]*object.EmeraldValue(nil), args...)
	if len(values) > 0 && dataEmptyHashArg(values[len(values)-1]) && Ruby2KeywordHash(values[len(values)-1]) {
		values = values[:len(values)-1]
	} else if len(values) == 1 && values[0] != nil && values[0].Type == object.ValueHash && Ruby2KeywordHash(values[0]) {
		entries := valueToHashMap(values[0])
		fieldIndex := map[string]int{}
		for i, field := range fields {
			fieldIndex[field] = i
		}
		named := make([]*object.EmeraldValue, len(fields))
		for i := range named {
			named[i] = R.NilVal
		}
		allKnown := true
		for key, value := range entries {
			index, found := fieldIndex[dataKeyName(key)]
			if !found {
				allKnown = false
				break
			}
			named[index] = value
		}
		if allKnown {
			values = named
		}
	}
	if len(values) > len(fields) {
		return NewArgumentError("struct size differs")
	}
	copy(obj.StructValues, values)
	return R.NilVal
}

func structClassMembers(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	class, _ := receiver.Data.(*object.Class)
	fields := structFieldsForClass(class)
	result := make([]*object.EmeraldValue, len(fields))
	for i, field := range fields {
		result[i] = rubySymbol(field)
	}
	return &object.EmeraldValue{Type: object.ValueArray, Data: result, Class: R.Classes["Array"]}
}

func structClassKeywordInit(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	class, _ := receiver.Data.(*object.Class)
	switch structKeywordModeForClass(class) {
	case 1:
		return R.TrueVal
	case 2:
		return R.FalseVal
	default:
		return R.NilVal
	}
}

func structMembers(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	fields := structFieldsForClass(receiver.Class)
	result := make([]*object.EmeraldValue, len(fields))
	for i, field := range fields {
		result[i] = rubySymbol(field)
	}
	return &object.EmeraldValue{Type: object.ValueArray, Data: result, Class: R.Classes["Array"]}
}

func structIndex(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 1 {
		return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 1)", len(args)))
	}
	fields := structFieldsForClass(receiver.Class)
	index := -1
	switch args[0].Type {
	case object.ValueInteger:
		index = int(args[0].Data.(int64))
		if index < 0 {
			index += len(fields)
		}
		if index < 0 || index >= len(fields) {
			return newRuntimeException(R.Classes["IndexError"], "offset out of range")
		}
	case object.ValueString, object.ValueSymbol:
		name := specName(args[0])
		for i, field := range fields {
			if field == name {
				index = i
				break
			}
		}
		if index < 0 {
			return NewNameError("no member '" + name + "' in struct")
		}
	default:
		return typeError("no implicit conversion into Integer")
	}
	return structValueAt(receiver, index)
}

func structIndexSet(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 2 {
		return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 2)", len(args)))
	}
	if receiver.Frozen {
		return frozenError("can't modify frozen Struct")
	}
	value := structIndex(receiver, args[0])
	if value != nil && value.Type == object.ValueException {
		return value
	}
	fields := structFieldsForClass(receiver.Class)
	index := -1
	if args[0].Type == object.ValueInteger {
		index = int(args[0].Data.(int64))
		if index < 0 {
			index += len(fields)
		}
	} else {
		name := specName(args[0])
		for i, field := range fields {
			if field == name {
				index = i
				break
			}
		}
	}
	if obj, ok := receiver.Data.(*object.Object); ok && index >= 0 && index < len(obj.StructValues) {
		obj.StructValues[index] = args[1]
	}
	return args[1]
}

func structToA(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	values := structValuesForFields(receiver, structFieldsForClass(receiver.Class))
	return &object.EmeraldValue{Type: object.ValueArray, Data: values, Class: R.Classes["Array"]}
}

func structLength(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return newInt(int64(len(structFieldsForClass(receiver.Class))))
}

func structEach(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 0 {
		return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 0)", len(args)))
	}
	values := structValuesForFields(receiver, structFieldsForClass(receiver.Class))
	if BlockGivenCheck == nil || !BlockGivenCheck() || CurrentBlockValue == nil || CallBlockWithArgs == nil {
		return newSizedGeneratorEnumerator(int64(len(values)), func() ([]*object.EmeraldValue, *object.EmeraldValue) {
			return append([]*object.EmeraldValue(nil), values...), nil
		})
	}
	block := CurrentBlockValue()
	for _, value := range values {
		result := CallBlockWithArgs(block, value)
		if result != nil && result.Type == object.ValueException {
			return result
		}
	}
	return receiver
}

func structEachPair(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 0 {
		return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 0)", len(args)))
	}
	fields := structFieldsForClass(receiver.Class)
	pairs := make([]*object.EmeraldValue, len(fields))
	for i, field := range fields {
		pairs[i] = &object.EmeraldValue{Type: object.ValueArray, Data: []*object.EmeraldValue{rubySymbol(field), structValueAt(receiver, i)}, Class: R.Classes["Array"]}
	}
	if BlockGivenCheck == nil || !BlockGivenCheck() || CurrentBlockValue == nil || CallBlockWithArgs == nil {
		return newSizedGeneratorEnumerator(int64(len(pairs)), func() ([]*object.EmeraldValue, *object.EmeraldValue) {
			return append([]*object.EmeraldValue(nil), pairs...), nil
		})
	}
	block := CurrentBlockValue()
	for _, pair := range pairs {
		values := pair.Data.([]*object.EmeraldValue)
		result := CallBlockWithArgs(block, values...)
		if result != nil && result.Type == object.ValueException {
			return result
		}
	}
	return receiver
}

func structValuesAt(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	values := structValuesForFields(receiver, structFieldsForClass(receiver.Class))
	result := []*object.EmeraldValue{}
	for _, arg := range args {
		if arg == nil {
			return typeError("no implicit conversion into Integer")
		}
		if arg.Type == object.ValueInteger {
			raw := int(arg.Data.(int64))
			index := raw
			if index < 0 {
				index += len(values)
			}
			if index < 0 {
				return newRuntimeException(R.Classes["IndexError"], fmt.Sprintf("offset %d too small for struct(size:%d)", raw, len(values)))
			}
			if index >= len(values) {
				return newRuntimeException(R.Classes["IndexError"], fmt.Sprintf("offset %d too large for struct(size:%d)", raw, len(values)))
			}
			result = append(result, values[index])
			continue
		}
		if arg.Type != object.ValueRange {
			return typeError("no implicit conversion of " + arg.TypeName() + " into Integer")
		}
		rangeValue := arg.Data.(*object.RRange)
		start := 0
		end := len(values) - 1
		if !rangeValue.StartMissing {
			startValue, valueOK := rangeValue.StartValue.(*object.EmeraldValue)
			parsed, ok := valueToInteger(startValue)
			if !valueOK || !ok {
				return typeError("no implicit conversion into Integer")
			}
			start = int(parsed)
			if start < 0 {
				start += len(values)
			}
			if start < 0 {
				return newRuntimeException(R.Classes["RangeError"], arg.Inspect()+" out of range")
			}
		}
		if !rangeValue.EndMissing {
			endValue, valueOK := rangeValue.EndValue.(*object.EmeraldValue)
			parsed, ok := valueToInteger(endValue)
			if !valueOK || !ok {
				return typeError("no implicit conversion into Integer")
			}
			end = int(parsed)
			if end < 0 {
				end += len(values)
			}
			if rangeValue.Exclusive {
				end--
			}
		}
		for index := start; index <= end; index++ {
			if index >= 0 && index < len(values) {
				result = append(result, values[index])
			} else {
				result = append(result, R.NilVal)
			}
		}
	}
	return &object.EmeraldValue{Type: object.ValueArray, Data: result, Class: R.Classes["Array"]}
}

func structToH(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 0 {
		return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 0)", len(args)))
	}
	result := emptyHashValue()
	fields := structFieldsForClass(receiver.Class)
	for i, field := range fields {
		key := rubySymbol(field)
		value := structValueAt(receiver, i)
		if BlockGivenCheck != nil && BlockGivenCheck() && CurrentBlockValue != nil && CallBlockWithArgs != nil {
			pairValue := CallBlockWithArgs(CurrentBlockValue(), key, value)
			if pairValue != nil && pairValue.Type == object.ValueException {
				return pairValue
			}
			pair, errVal := arrayToHPair(pairValue, i)
			if errVal != nil {
				return errVal
			}
			hashIndexSet(result, pair[0], pair[1])
		} else {
			hashIndexSet(result, key, value)
		}
	}
	return result
}

func structDig(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 0 {
		return NewArgumentError("wrong number of arguments (given 0, expected 1+)")
	}
	value := structDigFirst(receiver, args[0])
	if value == nil || value.Type == object.ValueException || len(args) == 1 || value.Type == object.ValueNil {
		return value
	}
	if CallMethod == nil || !receiverHasCallableMethod(value, "dig") {
		return typeError(value.TypeName() + " does not have #dig method")
	}
	return CallMethod(value, "dig", args[1:]...)
}

func structDigFirst(receiver, key *object.EmeraldValue) *object.EmeraldValue {
	fields := structFieldsForClass(receiver.Class)
	if key == nil {
		return R.NilVal
	}
	if key.Type == object.ValueInteger {
		index := int(key.Data.(int64))
		if index < 0 {
			index += len(fields)
		}
		if index < 0 || index >= len(fields) {
			return R.NilVal
		}
		return structValueAt(receiver, index)
	}
	if key.Type == object.ValueString || key.Type == object.ValueSymbol {
		name := specName(key)
		for index, field := range fields {
			if field == name {
				return structValueAt(receiver, index)
			}
		}
		return R.NilVal
	}
	return typeError("no implicit conversion into Integer")
}

func structFieldName(value *object.EmeraldValue) string {
	if value == nil {
		return ""
	}
	switch value.Type {
	case object.ValueSymbol, object.ValueString:
		if s, ok := value.Data.(string); ok {
			return strings.TrimPrefix(s, "@")
		}
	}
	return ""
}

func structEqual(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return structEqualMode(receiver, args, false)
}

func structEql(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return structEqualMode(receiver, args, true)
}

func structEqualMode(receiver *object.EmeraldValue, args []*object.EmeraldValue, strict bool) *object.EmeraldValue {
	if len(args) == 0 || args[0] == nil || receiver.Class != args[0].Class {
		return R.FalseVal
	}
	if receiver == args[0] {
		return R.TrueVal
	}
	mode := R.FalseVal
	if strict {
		mode = R.TrueVal
	}
	pair := [3]*object.EmeraldValue{receiver, args[0], mode}
	if structEqualityStack[pair] {
		return R.TrueVal
	}
	structEqualityStack[pair] = true
	defer delete(structEqualityStack, pair)
	fields := structFieldsForClass(receiver.Class)
	for index := range fields {
		leftValue := structValueAt(receiver, index)
		rightValue := structValueAt(args[0], index)
		equal := false
		if strict {
			if leftValue == rightValue {
				equal = true
			} else if CallMethod != nil && receiverHasCallableMethod(leftValue, "eql?") {
				result := CallMethod(leftValue, "eql?", rightValue)
				equal = result != nil && result.Type != object.ValueException && isTruthy(result)
			} else {
				equal = leftValue.Equals(rightValue)
			}
		} else {
			equal = valuesEqualWithRubyFallback(leftValue, rightValue)
		}
		if !equal {
			return R.FalseVal
		}
	}
	return R.TrueVal
}

func structHash(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if structHashStack[receiver] {
		return newInt(0x53545255)
	}
	structHashStack[receiver] = true
	defer delete(structHashStack, receiver)
	hasher := fnv.New64a()
	if receiver.Class != nil {
		_, _ = hasher.Write([]byte(receiver.Class.Name))
		_, _ = hasher.Write([]byte(fmt.Sprintf(":%p", receiver.Class)))
	}
	for _, value := range structValuesForFields(receiver, structFieldsForClass(receiver.Class)) {
		hash := int64(0)
		if value != nil && value.Class == receiver.Class && isTruthy(structEql(receiver, value)) {
			hash = 0x53545255
		} else if value != nil && CallMethod != nil && receiverHasCallableMethod(value, "hash") {
			result := CallMethod(value, "hash")
			if result != nil && result.Type == object.ValueInteger {
				hash = result.Data.(int64)
			}
		}
		_, _ = hasher.Write([]byte(fmt.Sprintf(":%d", hash)))
	}
	return newInt(int64(hasher.Sum64()))
}

func structInspect(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	name := ""
	if receiver != nil && receiver.Class != nil && receiver.Class.Name != "" && !strings.HasPrefix(receiver.Class.Name, "#<") {
		name = receiver.Class.Name + " "
	}
	if structInspectStack[receiver] {
		return rubyString("#<struct " + strings.TrimSpace(name) + ":...>")
	}
	structInspectStack[receiver] = true
	defer delete(structInspectStack, receiver)
	fields := structFieldsForClass(receiver.Class)
	parts := make([]string, len(fields))
	for index, field := range fields {
		value := structValueAt(receiver, index)
		text := "nil"
		if value == receiver {
			className := strings.TrimSpace(name)
			if className != "" {
				className += ":"
			}
			text = "#<struct " + className + "...>"
		} else if value != nil {
			if classInheritsFrom(value.Class, R.Classes["Struct"]) {
				text = structInspect(value).Data.(string)
			} else {
				text = value.Inspect()
			}
		}
		parts[index] = field + "=" + text
	}
	return rubyString("#<struct " + name + strings.Join(parts, ", ") + ">")
}

func dataEqual(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return dataEqualMode(receiver, args, false)
}

func dataEql(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return dataEqualMode(receiver, args, true)
}

func dataEqualMode(receiver *object.EmeraldValue, args []*object.EmeraldValue, strict bool) *object.EmeraldValue {
	if len(args) != 1 || args[0] == nil || receiver.Class != args[0].Class {
		return R.FalseVal
	}
	if receiver == args[0] {
		return R.TrueVal
	}
	mode := R.FalseVal
	if strict {
		mode = R.TrueVal
	}
	pair := [3]*object.EmeraldValue{receiver, args[0], mode}
	if structEqualityStack[pair] {
		return R.TrueVal
	}
	structEqualityStack[pair] = true
	defer delete(structEqualityStack, pair)
	left, leftOK := receiver.Data.(*object.Object)
	right, rightOK := args[0].Data.(*object.Object)
	if !leftOK || !rightOK {
		return R.FalseVal
	}
	for _, field := range dataFieldsForClass(receiver.Class) {
		leftValue := left.GetInstanceVar("@" + field)
		rightValue := right.GetInstanceVar("@" + field)
		if leftValue == nil {
			leftValue = R.NilVal
		}
		if rightValue == nil {
			rightValue = R.NilVal
		}
		equal := valuesEqualWithRubyFallback(leftValue, rightValue)
		if strict && leftValue != rightValue {
			result := CallMethod(leftValue, "eql?", rightValue)
			equal = result != nil && result.Type != object.ValueException && isTruthy(result)
		}
		if !equal {
			return R.FalseVal
		}
	}
	return R.TrueVal
}

func structSelectWithFields(receiver *object.EmeraldValue, fields []string, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) > 0 {
		return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 0)", len(args)))
	}
	values := structValuesForFields(receiver, fields)
	if BlockGivenCheck == nil || !BlockGivenCheck() || CallBlock == nil {
		return newSizedGeneratorEnumerator(int64(len(values)), func() ([]*object.EmeraldValue, *object.EmeraldValue) {
			return append([]*object.EmeraldValue(nil), structValuesForFields(receiver, fields)...), nil
		})
	}
	selected := make([]*object.EmeraldValue, 0, len(values))
	for _, value := range values {
		predicate := CallBlock(value)
		if LastBlockResult != nil {
			result := LastBlockResult
			LastBlockResult = nil
			return result
		}
		if predicate != nil && predicate.Type == object.ValueException {
			return predicate
		}
		if isTruthy(predicate) {
			selected = append(selected, value)
		}
	}
	return &object.EmeraldValue{
		Type:  object.ValueArray,
		Data:  selected,
		Class: R.Classes["Array"],
	}
}

type dataFieldList []string

func dataClassDefine(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	fields := make([]string, 0, len(args))
	seen := map[string]bool{}
	for _, arg := range args {
		name := structFieldName(arg)
		if name == "" {
			return typeError("wrong member name")
		}
		if seen[name] {
			return NewArgumentError("duplicate member: " + name)
		}
		seen[name] = true
		fields = append(fields, name)
	}

	dataClass := object.NewClass("")
	dataClass.SuperClass = R.Classes["Data"]
	dataClass.SetInstanceVar("@__rgo_data_fields", &object.EmeraldValue{Type: object.ValueObject, Data: dataFieldList(fields), Class: R.Classes["Object"]})
	dataClass.DefineClassMethod("new", &object.Method{Name: "new", Fn: dataClassNew, Arity: -1})
	dataClass.DefineClassMethod("[]", &object.Method{Name: "[]", Fn: dataClassNew, Arity: -1})
	dataClass.DefineClassMethod("members", &object.Method{Name: "members", Fn: dataClassMembers, Arity: 0})
	dataClass.DefineMethod("initialize", &object.Method{Name: "initialize", Fn: dataInitialize, Arity: -1, Visibility: "private"})
	dataClass.DefineMethod("to_h", &object.Method{Name: "to_h", Fn: dataToH, Arity: 0})
	dataClass.DefineMethod("with", &object.Method{Name: "with", Fn: dataWith, Arity: -1})
	dataClass.DefineMethod("inspect", &object.Method{Name: "inspect", Fn: dataInspect, Arity: 0})
	dataClass.DefineMethod("to_s", &object.Method{Name: "to_s", Fn: dataInspect, Arity: 0})
	dataClass.DefineMethod("==", &object.Method{Name: "==", Fn: dataEqual, Arity: 1})
	dataClass.DefineMethod("eql?", &object.Method{Name: "eql?", Fn: dataEql, Arity: 1})
	dataClass.DefineMethod("hash", &object.Method{Name: "hash", Fn: dataHash, Arity: 0})
	for _, field := range fields {
		field := field
		dataClass.DefineMethod(field, &object.Method{
			Name:  field,
			Arity: 0,
			Fn: func(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
				if obj, ok := receiver.Data.(*object.Object); ok {
					if val := obj.GetInstanceVar("@" + field); val != nil {
						return val
					}
				}
				return R.NilVal
			},
		})
	}

	classValue := &object.EmeraldValue{Type: object.ValueClass, Data: dataClass, Class: R.Classes["Class"]}
	if CurrentBlockValue != nil && CurrentBlockValue() != nil && CallMethod != nil {
		if result := CallMethod(classValue, "__exec_class_body__"); result != nil && result.Type == object.ValueException {
			return result
		}
	}
	return classValue
}

func dataClassNew(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	cls, ok := receiver.Data.(*object.Class)
	if !ok {
		return typeError("uninitialized class")
	}
	obj := &object.EmeraldValue{
		Type:  object.ValueObject,
		Data:  object.NewObject(cls),
		Class: cls,
	}
	initializeArgs := args
	if method, _, found := cls.GetMethodWithOwner("initialize"); found {
		if _, native := method.Fn.(func(*object.EmeraldValue, ...*object.EmeraldValue) *object.EmeraldValue); !native {
			initializeArgs = []*object.EmeraldValue{dataKeywordArguments(dataFieldsForClass(cls), args)}
		}
	}
	call := CallMethodBypass
	if call == nil {
		call = CallMethod
	}
	var result *object.EmeraldValue
	if call != nil {
		result = call(obj, "initialize", initializeArgs...)
	} else {
		result = dataInitialize(obj, initializeArgs...)
	}
	if result != nil && result.Type == object.ValueException {
		return result
	}
	obj.Frozen = true
	return obj
}

func dataKeywordArguments(fields []string, args []*object.EmeraldValue) *object.EmeraldValue {
	result := emptyHashValue()
	if len(args) > 0 && dataEmptyHashArg(args[len(args)-1]) && Ruby2KeywordHash(args[len(args)-1]) {
		args = args[:len(args)-1]
	}
	if normalized := dataNormalizeValues(fields, args); normalized != nil {
		for _, field := range fields {
			hashIndexSet(result, rubySymbol(field), normalized[field])
		}
	} else if len(args) == 1 && args[0] != nil && args[0].Type == object.ValueHash {
		for key, value := range valueToHashMap(args[0]) {
			hashIndexSet(result, rubySymbol(dataKeyName(key)), value)
		}
	} else if len(args) == len(fields) {
		for index, field := range fields {
			hashIndexSet(result, rubySymbol(field), args[index])
		}
	} else {
		for _, arg := range args {
			if arg == nil || arg.Type != object.ValueHash {
				continue
			}
			for key, value := range valueToHashMap(arg) {
				hashIndexSet(result, rubySymbol(dataKeyName(key)), value)
			}
		}
	}
	MarkRuby2KeywordHash(result)
	return result
}

func dataFieldsForClass(cls *object.Class) []string {
	for current := cls; current != nil; current = current.SuperClass {
		if val := current.GetInstanceVar("@__rgo_data_fields"); val != nil {
			if fields, ok := val.Data.(dataFieldList); ok {
				return []string(fields)
			}
		}
	}
	return nil
}

func dataClassMembers(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	cls, _ := receiver.Data.(*object.Class)
	fields := dataFieldsForClass(cls)
	values := make([]*object.EmeraldValue, 0, len(fields))
	for _, field := range fields {
		values = append(values, rubySymbol(field))
	}
	return &object.EmeraldValue{Type: object.ValueArray, Data: values, Class: R.Classes["Array"]}
}

func dataMembers(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	fields := dataFieldsForClass(receiver.Class)
	values := make([]*object.EmeraldValue, 0, len(fields))
	for _, field := range fields {
		values = append(values, rubySymbol(field))
	}
	return &object.EmeraldValue{Type: object.ValueArray, Data: values, Class: R.Classes["Array"]}
}

func dataDeconstruct(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	fields := dataFieldsForClass(receiver.Class)
	values := make([]*object.EmeraldValue, 0, len(fields))
	obj, _ := receiver.Data.(*object.Object)
	for _, field := range fields {
		value := R.NilVal
		if obj != nil {
			if stored := obj.GetInstanceVar("@" + field); stored != nil {
				value = stored
			}
		}
		values = append(values, value)
	}
	return &object.EmeraldValue{Type: object.ValueArray, Data: values, Class: R.Classes["Array"]}
}

func dataInitialize(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	obj, ok := receiver.Data.(*object.Object)
	if !ok {
		return R.NilVal
	}
	fields := dataFieldsForClass(receiver.Class)
	if len(args) > 0 && dataEmptyHashArg(args[len(args)-1]) && Ruby2KeywordHash(args[len(args)-1]) {
		args = args[:len(args)-1]
	}
	values := dataNormalizeValues(fields, args)
	if values != nil {
		// values normalized below
	} else if len(args) == 1 && args[0] != nil && args[0].Type == object.ValueHash {
		values = map[string]*object.EmeraldValue{}
		for key, val := range valueToHashMap(args[0]) {
			values[dataKeyName(key)] = val
		}
	} else {
		if len(args) != len(fields) {
			return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected %d)", len(args), len(fields)))
		}
		values = map[string]*object.EmeraldValue{}
		for i, field := range fields {
			values[field] = args[i]
		}
	}
	fieldSet := map[string]bool{}
	for _, field := range fields {
		fieldSet[field] = true
	}
	for key := range values {
		if !fieldSet[key] {
			return NewArgumentError("unknown keyword: :" + key)
		}
	}
	for _, field := range fields {
		val, ok := values[field]
		if !ok {
			return NewArgumentError("missing keyword: " + field)
		}
		obj.SetInstanceVar("@"+field, val)
	}
	return R.NilVal
}

func dataNormalizeValues(fields []string, args []*object.EmeraldValue) map[string]*object.EmeraldValue {
	if len(args) > 0 && dataEmptyHashArg(args[len(args)-1]) {
		args = args[:len(args)-1]
	}
	if len(args) == 0 || len(args) != len(fields) {
		return nil
	}
	values := map[string]*object.EmeraldValue{}
	fieldSet := map[string]bool{}
	for _, field := range fields {
		fieldSet[field] = true
	}
	for _, arg := range args {
		if arg == nil || arg.Type != object.ValueHash {
			return nil
		}
		entries := valueToHashMap(arg)
		if len(entries) != 1 {
			return nil
		}
		for key, value := range entries {
			name := dataKeyName(key)
			if !fieldSet[name] {
				return nil
			}
			values[name] = value
		}
	}
	return values
}

func dataEmptyHashArg(value *object.EmeraldValue) bool {
	if value == nil || value.Type != object.ValueHash {
		return false
	}
	hash := valueToHashMap(value)
	return len(hash) == 0
}

func dataKeyName(value *object.EmeraldValue) string {
	return strings.TrimPrefix(specName(value), ":")
}

func dataToH(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	result := emptyHashValue()
	obj, ok := receiver.Data.(*object.Object)
	if !ok {
		return result
	}
	fields := dataFieldsForClass(receiver.Class)
	for i, field := range fields {
		key := rubySymbol(field)
		value := obj.GetInstanceVar("@" + field)
		if value == nil {
			value = R.NilVal
		}
		if BlockGivenCheck != nil && BlockGivenCheck() && CallBlockWithArgs != nil {
			pairValue := CallBlockWithArgs(CurrentBlockValue(), key, value)
			if pairValue != nil && pairValue.Type == object.ValueException {
				return pairValue
			}
			pair, errVal := arrayToHPair(pairValue, i)
			if errVal != nil {
				return errVal
			}
			hashIndexSet(result, pair[0], pair[1])
			continue
		}
		hashIndexSet(result, key, value)
	}
	return result
}

func dataWith(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 0 {
		return receiver
	}
	for _, arg := range args {
		if arg == nil || arg.Type != object.ValueHash {
			return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 0)", len(args)))
		}
	}
	obj, ok := receiver.Data.(*object.Object)
	if !ok {
		return receiver
	}
	fields := dataFieldsForClass(receiver.Class)
	values := emptyHashValue()
	for _, field := range fields {
		value := obj.GetInstanceVar("@" + field)
		if value == nil {
			value = R.NilVal
		}
		hashIndexSet(values, rubySymbol(field), value)
	}
	for _, updates := range args {
		for key, value := range valueToHashMap(updates) {
			hashIndexSet(values, rubySymbol(dataKeyName(key)), value)
		}
	}
	classValue := &object.EmeraldValue{Type: object.ValueClass, Data: receiver.Class, Class: R.Classes["Class"]}
	return dataClassNew(classValue, values)
}

func dataHash(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	hasher := fnv.New64a()
	if receiver.Class != nil {
		_, _ = hasher.Write([]byte(fmt.Sprintf("%s:%p", receiver.Class.Name, receiver.Class)))
	}
	obj, _ := receiver.Data.(*object.Object)
	for _, field := range dataFieldsForClass(receiver.Class) {
		value := R.NilVal
		if obj != nil {
			if item := obj.GetInstanceVar("@" + field); item != nil {
				value = item
			}
		}
		hash := int64(0)
		if CallMethod != nil && receiverHasCallableMethod(value, "hash") {
			if result := CallMethod(value, "hash"); result != nil && result.Type == object.ValueInteger {
				hash = result.Data.(int64)
			}
		}
		_, _ = hasher.Write([]byte(fmt.Sprintf(":%d", hash)))
	}
	return newInt(int64(hasher.Sum64()))
}

func dataInspect(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	parts := []string{}
	if receiver != nil && receiver.Class != nil {
		name := classToS(receiver.Class)
		if name != "" && !strings.HasPrefix(name, "#<") {
			parts = append(parts, name)
		}
	}
	obj, _ := receiver.Data.(*object.Object)
	fields := dataFieldsForClass(receiver.Class)
	for _, field := range fields {
		value := R.NilVal
		if obj != nil {
			if got := obj.GetInstanceVar("@" + field); got != nil {
				value = got
			}
		}
		inspect := "nil"
		if value == receiver {
			className := "Data"
			if receiver != nil && receiver.Class != nil {
				className = classToS(receiver.Class)
			}
			inspect = "#<data " + className + ":...>"
		} else if value != nil {
			inspect = value.Inspect()
		}
		parts = append(parts, field+"="+inspect)
	}
	body := strings.Join(parts, " ")
	if len(fields) > 0 && len(parts) > 1 {
		prefix := parts[0]
		if !strings.Contains(prefix, "=") {
			body = prefix + " " + strings.Join(parts[1:], ", ")
		} else {
			body = strings.Join(parts, ", ")
		}
	}
	return rubyString("#<data " + body + ">")
}

func structValuesForFields(receiver *object.EmeraldValue, fields []string) []*object.EmeraldValue {
	values := make([]*object.EmeraldValue, 0, len(fields))
	obj, ok := receiver.Data.(*object.Object)
	if !ok {
		return values
	}
	for index := range fields {
		var value *object.EmeraldValue
		if index < len(obj.StructValues) {
			value = obj.StructValues[index]
		}
		if value == nil {
			value = R.NilVal
		}
		values = append(values, value)
	}
	return values
}

func stringSliceContains(values []string, target string) bool {
	for _, value := range values {
		if value == target {
			return true
		}
	}
	return false
}

func isTruthy(val *object.EmeraldValue) bool {
	return val != nil && val.IsTruthy()
}

