func defineRubyBuiltinConstants(objectClass *object.Class) {
	defineCoreClassConstants(objectClass)

	version := frozenRubyConstantString(RubyCompatibilityVersion)
	platform := runtime.GOOS + "-" + runtime.GOARCH
	objectClass.DefineConstant("RUBY_VERSION", version)
	objectClass.DefineConstant("RUBY_PATCHLEVEL", &object.EmeraldValue{Type: object.ValueInteger, Data: int64(0), Class: R.Classes["Integer"]})
	objectClass.DefineConstant("RUBY_COPYRIGHT", frozenRubyConstantString("ruby - Copyright (C) 1993-2026 ruby core team"))
	objectClass.DefineConstant("RUBY_DESCRIPTION", frozenRubyConstantString("ruby "+RubyCompatibilityVersion+" (rgo) ["+platform+"]"))
	objectClass.DefineConstant("RUBY_ENGINE", frozenRubyConstantString("ruby"))
	objectClass.DefineConstant("RUBY_ENGINE_VERSION", version)
	objectClass.DefineConstant("RUBY_PLATFORM", frozenRubyConstantString(platform))
	objectClass.DefineConstant("RUBY_RELEASE_DATE", frozenRubyConstantString("2026-06-23"))
	objectClass.DefineConstant("RUBY_REVISION", frozenRubyConstantString("rgo"))
	objectClass.DefineConstant("STDOUT", stdIOConstant(1, "w"))
	objectClass.DefineConstant("STDERR", stdIOConstant(2, "w"))
	objectClass.DefineConstant("STDIN", stdIOConstant(0, "r"))
	objectClass.DefineConstant("ENV", EnvObject())
	installObjectSpace(objectClass)
	mathModule := object.NewModule("Math")
	mathDomainErrorClass := object.NewClass("Math::DomainError")
	mathDomainErrorClass.SuperClass = R.Classes["StandardError"]
	mathModule.Constants["DomainError"] = &object.EmeraldValue{Type: object.ValueClass, Data: mathDomainErrorClass, Class: R.Classes["Class"]}
	mathModule.Constants["PI"] = newFloat(math.Pi)
	mathModule.Constants["E"] = newFloat(math.E)
	installMathMethods(mathModule)
	R.Classes["Math::DomainError"] = mathDomainErrorClass
	objectClass.DefineConstant("Math", &object.EmeraldValue{Type: object.ValueModule, Data: mathModule, Class: R.Classes["Module"]})
	objectClass.DefineConstant("TOLERANCE", &object.EmeraldValue{Type: object.ValueFloat, Data: float64(0.00003), Class: R.Classes["Float"]})
	objectClass.DefineConstant("TIME_TOLERANCE", &object.EmeraldValue{Type: object.ValueFloat, Data: float64(1.0), Class: R.Classes["Float"]})

	specVersionClass := object.NewClass("SpecVersion")
	specVersionClass.DefineMethod("initialize", &object.Method{Name: "initialize", Fn: specVersionInitialize, Arity: 1})
	specVersionClass.DefineMethod("<=>", &object.Method{Name: "<=>", Fn: specVersionCompare, Arity: 1})
	specVersionClass.DefineMethod("<", &object.Method{Name: "<", Fn: specVersionLessThan, Arity: 1})
	specVersionClass.DefineMethod(">", &object.Method{Name: ">", Fn: specVersionGreaterThan, Arity: 1})
	specVersionVal := &object.EmeraldValue{Type: object.ValueClass, Data: specVersionClass, Class: R.Classes["Class"]}
	objectClass.DefineConstant("SpecVersion", specVersionVal)

	fullRubyVersionVal := &object.EmeraldValue{
		Type:  object.ValueObject,
		Data:  &object.Object{Class: specVersionClass, InstanceVars: map[string]*object.EmeraldValue{"@version": version}},
		Class: specVersionClass,
	}

	versionGuardModule := object.NewModule("VersionGuard")
	versionGuardModule.Constants["FULL_RUBY_VERSION"] = fullRubyVersionVal
	versionGuardVal := &object.EmeraldValue{Type: object.ValueModule, Data: versionGuardModule, Class: R.Classes["Module"]}
	objectClass.DefineConstant("VersionGuard", versionGuardVal)
	platformGuardModule := object.NewModule("PlatformGuard")
	platformGuardModule.Constants["POINTER_SIZE"] = newInt(int64(strconv.IntSize))
	platformGuardVal := &object.EmeraldValue{Type: object.ValueModule, Data: platformGuardModule, Class: R.Classes["Module"]}
	objectClass.DefineConstant("PlatformGuard", platformGuardVal)
	platformGuardSingleton := methodSingletonClass(platformGuardVal)
	if platformGuardSingleton != nil && platformGuardSingleton.Type == object.ValueClass {
		cls := platformGuardSingleton.Data.(*object.Class)
		cls.DefineMethod("standard?", &object.Method{Name: "standard?", Arity: 0, Fn: func(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
			return R.TrueVal
		}})
		cls.DefineMethod("implementation?", &object.Method{Name: "implementation?", Arity: -1, Fn: func(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
			if len(args) == 0 || args[0] == nil || args[0].Type != object.ValueSymbol {
				return R.FalseVal
			}
			if args[0].Data.(string) == "ruby" {
				return R.TrueVal
			}
			return R.FalseVal
		}})
	}
	installCGIModule(objectClass)
}

func defineCoreClassConstants(objectClass *object.Class) {
	if objectClass == nil {
		return
	}
	for name, class := range R.Classes {
		if class == nil || name == "" || strings.Contains(name, "::") {
			continue
		}
		r, _ := utf8.DecodeRuneInString(name)
		if !unicode.IsUpper(r) {
			continue
		}
		objectClass.DefineConstant(name, &object.EmeraldValue{Type: object.ValueClass, Data: class, Class: R.Classes["Class"]})
	}
}

func specVersionInitialize(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) < 1 || args[0].Type != object.ValueString {
		return newRuntimeException(R.Classes["ArgumentError"], "SpecVersion requires a string argument")
	}
	switch receiver.Type {
	case object.ValueObject:
		receiver.Data.(*object.Object).SetInstanceVar("@version", args[0])
	case object.ValueClass:
		receiver.Data.(*object.Class).SetInstanceVar("@version", args[0])
	}
	return R.NilVal
}

func specVersionCompare(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) < 1 {
		return newRuntimeException(R.Classes["ArgumentError"], "wrong number of arguments")
	}
	other := args[0]
	var otherVersion string
	if other.Type == object.ValueObject {
		otherObj := other.Data.(*object.Object)
		v := otherObj.InstanceVars["@version"]
		if v == nil || v.Type != object.ValueString {
			return R.NilVal
		}
		otherVersion = v.Data.(string)
	} else if other.Type == object.ValueClass {
		otherClass := other.Data.(*object.Class)
		v := otherClass.GetInstanceVar("@version")
		if v == nil || v.Type != object.ValueString {
			return R.NilVal
		}
		otherVersion = v.Data.(string)
	} else if other.Type == object.ValueString {
		otherVersion = other.Data.(string)
	} else {
		return R.NilVal
	}
	var myVersion string
	switch receiver.Type {
	case object.ValueObject:
		myObj := receiver.Data.(*object.Object)
		v := myObj.InstanceVars["@version"]
		if v == nil || v.Type != object.ValueString {
			return R.NilVal
		}
		myVersion = v.Data.(string)
	case object.ValueClass:
		myClass := receiver.Data.(*object.Class)
		v := myClass.GetInstanceVar("@version")
		if v == nil || v.Type != object.ValueString {
			return R.NilVal
		}
		myVersion = v.Data.(string)
	default:
		return R.NilVal
	}
	if myVersion < otherVersion {
		return &object.EmeraldValue{Type: object.ValueInteger, Data: int64(-1), Class: R.Classes["Integer"]}
	}
	if myVersion > otherVersion {
		return &object.EmeraldValue{Type: object.ValueInteger, Data: int64(1), Class: R.Classes["Integer"]}
	}
	return &object.EmeraldValue{Type: object.ValueInteger, Data: int64(0), Class: R.Classes["Integer"]}
}

func specVersionLessThan(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	cmp := specVersionCompare(receiver, args...)
	if cmp == nil || cmp.Type == object.ValueNil {
		return R.NilVal
	}
	if cmp.Type == object.ValueException {
		return cmp
	}
	if cmp.Data.(int64) < 0 {
		return R.TrueVal
	}
	return R.FalseVal
}

func specVersionGreaterThan(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	cmp := specVersionCompare(receiver, args...)
	if cmp == nil || cmp.Type == object.ValueNil {
		return R.NilVal
	}
	if cmp.Type == object.ValueException {
		return cmp
	}
	if cmp.Data.(int64) > 0 {
		return R.TrueVal
	}
	return R.FalseVal
}

func stdIOConstant(fd int64, mode string) *object.EmeraldValue {
	switch fd {
	case 0:
		return StdinObject()
	case 1:
		return StdoutObject()
	case 2:
		return StderrObject()
	default:
		return standardIOObject(fd, mode)
	}
}

func installObjectSpace(objectClass *object.Class) {
	weakMapClass := object.NewClass("ObjectSpace::WeakMap")
	weakMapClass.SuperClass = R.Classes["Object"]
	weakKeyMapClass := object.NewClass("ObjectSpace::WeakKeyMap")
	weakKeyMapClass.SuperClass = R.Classes["Object"]
	installWeakMapMethods(weakMapClass, false)
	installWeakMapMethods(weakKeyMapClass, true)
	R.Classes["ObjectSpace::WeakMap"] = weakMapClass
	R.Classes["ObjectSpace::WeakKeyMap"] = weakKeyMapClass
	module := object.NewModule("ObjectSpace")
	module.DefineMethod("garbage_collect", &object.Method{Name: "garbage_collect", Fn: objectSpaceGarbageCollect, Arity: -1})
	module.DefineMethod("each_object", &object.Method{Name: "each_object", Fn: objectSpaceEachObject, Arity: -1})
	module.DefineMethod("define_finalizer", &object.Method{Name: "define_finalizer", Fn: objectSpaceDefineFinalizer, Arity: -1})
	module.DefineMethod("undefine_finalizer", &object.Method{Name: "undefine_finalizer", Fn: objectSpaceUndefineFinalizer, Arity: 1})
	module.Constants["WeakMap"] = &object.EmeraldValue{Type: object.ValueClass, Data: weakMapClass, Class: R.Classes["Class"]}
	module.Constants["WeakKeyMap"] = &object.EmeraldValue{Type: object.ValueClass, Data: weakKeyMapClass, Class: R.Classes["Class"]}
	objectClass.DefineConstant("ObjectSpace", &object.EmeraldValue{Type: object.ValueModule, Data: module, Class: R.Classes["Module"]})
}

func objectSpaceGarbageCollect(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return gcStart(receiver, args...)
}

func objectSpaceEachObject(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	var target *object.Class
	if len(args) > 0 && args[0] != nil && args[0].Type == object.ValueClass {
		target = args[0].Data.(*object.Class)
	}
	values := make([]*object.EmeraldValue, 0)
	seen := make(map[any]bool)
	for _, value := range objectSpaceTracked {
		if value == nil || !objectSpaceMatches(value, target) {
			continue
		}
		identity := value.Data
		if seen[identity] {
			continue
		}
		seen[identity] = true
		values = append(values, value)
	}
	if BlockGivenCheck != nil && BlockGivenCheck() && CurrentBlockValue != nil && CurrentBlockValue() != nil {
		block := CurrentBlockValue()
		for _, value := range values {
			if result := CallBlockWithArgs(block, value); result != nil && result.Type == object.ValueException {
				return result
			}
		}
		return newInt(int64(len(values)))
	}
	enumerator := newStaticEnumerator(values)
	if data, ok := enumerator.Data.(*enumeratorData); ok {
		data.eachFunc = func() *object.EmeraldValue {
			if CurrentBlockValue != nil && CurrentBlockValue() != nil {
				block := CurrentBlockValue()
				for _, value := range values {
					CallBlockWithArgs(block, value)
				}
			}
			return newInt(int64(len(values)))
		}
	}
	return enumerator
}

func objectSpaceMatches(value *object.EmeraldValue, target *object.Class) bool {
	if target == nil {
		return weakMapCollectable(value)
	}
	if value.Type == object.ValueClass {
		candidate := value.Data.(*object.Class)
		if target == R.Classes["Class"] {
			return !candidate.IsSingleton || candidate.SingletonOwner != nil
		}
		if target == R.Classes["Module"] {
			return false
		}
		if target.IsSingleton {
			return objectSpaceClassValueMatchesSingletonTarget(candidate, target)
		}
	}
	if value.Type == object.ValueModule {
		return target == R.Classes["Module"]
	}
	return value.Class != nil && classInheritsFrom(value.Class, target)
}

func objectSpaceClassValueMatchesSingletonTarget(candidate, target *object.Class) bool {
	if candidate == nil || target == nil || target.SingletonOwner == nil || target.SingletonOwner.Type != object.ValueClass {
		return false
	}
	targetOwner, ok := target.SingletonOwner.Data.(*object.Class)
	if !ok || targetOwner == nil {
		return false
	}
	if !candidate.IsSingleton {
		return classInheritsFrom(candidate, targetOwner)
	}
	owner := candidate.SingletonOwner
	if owner == nil || owner.Type == object.ValueClass || owner.Class == nil {
		return false
	}
	return classInheritsFrom(owner.Class, targetOwner)
}

func objectSpaceDefineFinalizer(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 0 || !weakMapCollectable(args[0]) {
		return NewArgumentError("cannot define finalizer for immediate value")
	}
	objectValue := args[0]
	var handler *object.EmeraldValue
	if len(args) > 1 {
		handler = args[1]
	} else if CurrentBlockValue != nil {
		handler = CurrentBlockValue()
	}
	if handler == nil || !isCallableValue(handler) {
		return NewArgumentError("wrong type of finalizer")
	}
	for _, existing := range objectSpaceFinalizers[objectValue] {
		if finalizerEquivalent(existing, handler) {
			return &object.EmeraldValue{Type: object.ValueArray, Data: []*object.EmeraldValue{newInt(0), existing}, Class: R.Classes["Array"]}
		}
	}
	objectSpaceFinalizers[objectValue] = append(objectSpaceFinalizers[objectValue], handler)
	return &object.EmeraldValue{Type: object.ValueArray, Data: []*object.EmeraldValue{newInt(0), handler}, Class: R.Classes["Array"]}
}

func finalizerEquivalent(left, right *object.EmeraldValue) bool {
	if left == right {
		return true
	}
	if left == nil || right == nil || left.Type != object.ValueProc || right.Type != object.ValueProc {
		return false
	}
	leftProc, lok := left.Data.(*object.Proc)
	rightProc, rok := right.Data.(*object.Proc)
	return lok && rok && leftProc.Fn == rightProc.Fn && leftProc.Binding == rightProc.Binding && leftProc.Native == nil && rightProc.Native == nil
}

func objectSpaceUndefineFinalizer(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 0 {
		return R.NilVal
	}
	if args[0] != nil && args[0].Frozen {
		return NewFrozenError("can't modify frozen object")
	}
	delete(objectSpaceFinalizers, args[0])
	return args[0]
}

