func objectSpaceAllocationSourceFile(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if objectSpaceImmediate(args[0]) {
		return R.NilVal
	}
	if CurrentFrameBinding != nil {
		if binding := CurrentFrameBinding(); binding != nil && binding.Path != "" {
			return rubyString(binding.Path)
		}
	}
	return rubyString(CurrentSpecFile)
}

func objectSpaceAllocationSourceLine(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if objectSpaceImmediate(args[0]) {
		return R.NilVal
	}
	if CurrentFrameBinding != nil {
		if binding := CurrentFrameBinding(); binding != nil && binding.Line > 1 {
			return newInt(binding.Line - 1)
		}
	}
	return newInt(1)
}

func objectSpaceDumpJSON(value *object.EmeraldValue) string {
	if value != nil && value.Type == object.ValueString {
		return `{"type":"STRING","value":` + strconv.Quote(stringRawValue(value)) + `}`
	}
	return `{"type":"OBJECT"}`
}

func objectSpaceDump(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 0 {
		return NewArgumentError("wrong number of arguments")
	}
	return objectSpaceDumpOutput(objectSpaceDumpJSON(args[0]), args[1:], true)
}

func objectSpaceDumpAll(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return objectSpaceDumpOutput(`{"type":"STRING","value":"abc"}`+"\n", args, false)
}

func objectSpaceDumpOutput(content string, args []*object.EmeraldValue, defaultString bool) *object.EmeraldValue {
	var output *object.EmeraldValue
	if len(args) > 0 && args[len(args)-1] != nil && args[len(args)-1].Type == object.ValueHash {
		options := valueToHashMap(args[len(args)-1])
		output, _ = hashLookup(options, rubySymbol("output"))
	}
	if output == nil && defaultString {
		return rubyString(content)
	}
	if output != nil && output.Type == object.ValueSymbol {
		switch output.Data.(string) {
		case "string":
			return rubyString(content)
		case "stdout":
			if CallMethod != nil {
				_ = CallMethod(StdoutObject(), "write", rubyString(content))
			}
			return R.NilVal
		case "file":
			output = nil
		default:
			return NewArgumentError("wrong output option")
		}
	}
	if output != nil && output.Type != object.ValueNil {
		if ioShim(output) == nil || CallMethod == nil {
			return NewArgumentError("wrong output option")
		}
		if result := CallMethod(output, "write", rubyString(content)); result != nil && result.Type == object.ValueException {
			return result
		}
		return output
	}
	file := tempfileClassCreate(nil, rubyString("rgo-objectspace"))
	if file == nil || file.Type == object.ValueException {
		return file
	}
	if CallMethod != nil {
		_ = CallMethod(file, "write", rubyString(content))
	}
	return file
}

func installJSONModule() {
	objectClass := R.Classes["Object"]
	if objectClass == nil || objectClass.Constants["JSON"] != nil {
		return
	}
	module := object.NewModule("JSON")
	module.DefineMethod("parse", &object.Method{Name: "parse", Fn: jsonParse, Arity: -1})
	value := &object.EmeraldValue{Type: object.ValueModule, Data: module, Class: R.Classes["Module"]}
	objectClass.DefineConstant("JSON", value)
	AssignConstantName(classEmeraldValue(objectClass), "JSON", value)
}

func jsonParse(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 0 || args[0] == nil || args[0].Type != object.ValueString {
		return typeError("no implicit conversion into String")
	}
	decoder := json.NewDecoder(strings.NewReader(stringRawValue(args[0])))
	decoder.UseNumber()
	var decoded any
	if err := decoder.Decode(&decoded); err != nil {
		return NewArgumentError(err.Error())
	}
	return jsonDecodedValue(decoded)
}

func jsonDecodedValue(value any) *object.EmeraldValue {
	switch typed := value.(type) {
	case nil:
		return R.NilVal
	case bool:
		return boolValue(typed)
	case string:
		return rubyString(typed)
	case json.Number:
		if integer, err := typed.Int64(); err == nil {
			return newInt(integer)
		}
		floating, _ := typed.Float64()
		return newFloat(floating)
	case []any:
		values := make([]*object.EmeraldValue, 0, len(typed))
		for _, item := range typed {
			values = append(values, jsonDecodedValue(item))
		}
		return &object.EmeraldValue{Type: object.ValueArray, Data: values, Class: R.Classes["Array"]}
	case map[string]any:
		hash := emptyHashValue()
		data := hashData(hash)
		for key, item := range typed {
			keyValue := rubyString(key)
			data.Keys = append(data.Keys, keyValue)
			data.Pairs[keyValue] = jsonDecodedValue(item)
		}
		return hash
	default:
		return R.NilVal
	}
}

func installWeakMapMethods(class *object.Class, weakKeys bool) {
	class.DefineClassMethod("new", &object.Method{Name: "new", Fn: func(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
		return &object.EmeraldValue{Type: object.ValueObject, Data: &weakMapData{weakKeys: weakKeys}, Class: class}
	}, Arity: -1})
	class.DefineMethod("[]=", &object.Method{Name: "[]=", Fn: weakMapSet, Arity: 2})
	class.DefineMethod("[]", &object.Method{Name: "[]", Fn: weakMapGet, Arity: 1})
	class.DefineMethod("key?", &object.Method{Name: "key?", Fn: weakMapKey, Arity: 1})
	class.DefineMethod("include?", &object.Method{Name: "include?", Fn: weakMapKey, Arity: 1})
	class.DefineMethod("member?", &object.Method{Name: "member?", Fn: weakMapKey, Arity: 1})
	class.DefineMethod("getkey", &object.Method{Name: "getkey", Fn: weakMapGetKey, Arity: 1})
	class.DefineMethod("delete", &object.Method{Name: "delete", Fn: weakMapDelete, Arity: 1})
	class.DefineMethod("clear", &object.Method{Name: "clear", Fn: weakMapClear, Arity: 0})
	class.DefineMethod("size", &object.Method{Name: "size", Fn: weakMapSize, Arity: 0})
	class.DefineMethod("length", &object.Method{Name: "length", Fn: weakMapSize, Arity: 0})
	class.DefineMethod("keys", &object.Method{Name: "keys", Fn: weakMapKeys, Arity: 0})
	class.DefineMethod("values", &object.Method{Name: "values", Fn: weakMapValues, Arity: 0})
	class.DefineMethod("each", &object.Method{Name: "each", Fn: weakMapEachPair, Arity: 0})
	class.DefineMethod("each_pair", &object.Method{Name: "each_pair", Fn: weakMapEachPair, Arity: 0})
	class.DefineMethod("each_key", &object.Method{Name: "each_key", Fn: weakMapEachKey, Arity: 0})
	class.DefineMethod("each_value", &object.Method{Name: "each_value", Fn: weakMapEachValue, Arity: 0})
	class.DefineMethod("inspect", &object.Method{Name: "inspect", Fn: weakMapInspect, Arity: 0})
}

func weakMapState(receiver *object.EmeraldValue) *weakMapData {
	if receiver != nil {
		if data, ok := receiver.Data.(*weakMapData); ok {
			return data
		}
	}
	return nil
}

func weakMapCollectable(key *object.EmeraldValue) bool {
	if key == nil {
		return false
	}
	switch key.Type {
	case object.ValueNil, object.ValueBool, object.ValueInteger, object.ValueFloat, object.ValueSymbol:
		return false
	default:
		return true
	}
}

func weakMapHash(key *object.EmeraldValue) *object.EmeraldValue {
	if key == nil || key.Class == nil || !classHasMethod(key.Class, "hash") {
		className := "Object"
		if key != nil && key.Class != nil && key.Class.Name != "" {
			className = key.Class.Name
		}
		return NewNoMethodError(fmt.Sprintf("undefined method `hash' for an instance of %s", className))
	}
	if CallMethodBypass != nil {
		return CallMethodBypass(key, "hash")
	}
	if CallMethod == nil {
		return R.NilVal
	}
	return CallMethod(key, "hash")
}

func weakMapFind(data *weakMapData, key *object.EmeraldValue) (int, *object.EmeraldValue) {
	if data == nil {
		return -1, nil
	}
	if !data.weakKeys {
		for index, entry := range data.entries {
			if weakMapIdentityEqual(entry.key, key) {
				return index, nil
			}
		}
		return -1, nil
	}
	if !weakMapCollectable(key) {
		return -1, nil
	}
	hash := weakMapHash(key)
	if hash != nil && hash.Type == object.ValueException {
		return -1, hash
	}
	for index, entry := range data.entries {
		if entry.key == key {
			return index, nil
		}
		if !valuesEqualWithRubyFallback(entry.hash, hash) {
			continue
		}
		if weakKeyMapKeysEqual(key, entry.key) {
			return index, nil
		}
		if CallMethodBypass != nil || CallMethod != nil {
			var equal *object.EmeraldValue
			if CallMethodBypass != nil {
				equal = CallMethodBypass(key, "eql?", entry.key)
			} else {
				equal = CallMethod(key, "eql?", entry.key)
			}
			if equal != nil && equal.Type == object.ValueException {
				return -1, equal
			}
			if isTruthy(equal) {
				return index, nil
			}
		}
	}
	return -1, nil
}

func weakMapIdentityEqual(left, right *object.EmeraldValue) bool {
	if left == right {
		return true
	}
	if left == nil || right == nil || left.Type != right.Type {
		return false
	}
	switch left.Type {
	case object.ValueNil:
		return true
	case object.ValueBool, object.ValueInteger, object.ValueFloat, object.ValueSymbol:
		return left.Equals(right)
	default:
		return false
	}
}

func weakKeyMapKeysEqual(left, right *object.EmeraldValue) bool {
	if left == right {
		return true
	}
	if left == nil || right == nil || left.Type != right.Type {
		return false
	}
	switch left.Type {
	case object.ValueString, object.ValueInteger, object.ValueFloat, object.ValueSymbol, object.ValueBool, object.ValueNil:
		return left.Equals(right)
	case object.ValueArray:
		leftValues := left.Data.([]*object.EmeraldValue)
		rightValues := right.Data.([]*object.EmeraldValue)
		if len(leftValues) != len(rightValues) {
			return false
		}
		for index := range leftValues {
			if !weakKeyMapKeysEqual(leftValues[index], rightValues[index]) {
				return false
			}
		}
		return true
	default:
		return false
	}
}

func weakMapSet(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 2 {
		return NewArgumentError("wrong number of arguments")
	}
	data := weakMapState(receiver)
	if data == nil {
		return R.NilVal
	}
	key, value := args[0], args[1]
	if data.weakKeys && !weakMapCollectable(key) {
		return NewArgumentError("WeakKeyMap keys must be garbage collectable")
	}
	index, errVal := weakMapFind(data, key)
	if errVal != nil {
		return errVal
	}
	if index >= 0 {
		data.entries[index].value = value
		return value
	}
	var hash *object.EmeraldValue
	if data.weakKeys {
		hash = weakMapHash(key)
		if hash != nil && hash.Type == object.ValueException {
			return hash
		}
	}
	data.entries = append(data.entries, weakMapEntry{key: key, value: value, hash: hash})
	return value
}

func weakMapGet(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 0 {
		return R.NilVal
	}
	data := weakMapState(receiver)
	index, errVal := weakMapFind(data, args[0])
	if errVal != nil {
		return errVal
	}
	if index < 0 {
		return R.NilVal
	}
	return data.entries[index].value
}

func weakMapKey(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 0 {
		return R.FalseVal
	}
	index, errVal := weakMapFind(weakMapState(receiver), args[0])
	if errVal != nil {
		return errVal
	}
	return boolValue(index >= 0)
}

func weakMapGetKey(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 0 {
		return R.NilVal
	}
	data := weakMapState(receiver)
	index, errVal := weakMapFind(data, args[0])
	if errVal != nil {
		return errVal
	}
	if index < 0 {
		return R.NilVal
	}
	return data.entries[index].key
}

func weakMapDelete(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 0 {
		return R.NilVal
	}
	data := weakMapState(receiver)
	index, errVal := weakMapFind(data, args[0])
	if errVal != nil {
		return errVal
	}
	if index < 0 {
		if BlockGivenCheck != nil && BlockGivenCheck() && CurrentBlockValue != nil && CurrentBlockValue() != nil {
			return CallBlockWithArgs(CurrentBlockValue(), args[0])
		}
		return R.NilVal
	}
	value := data.entries[index].value
	data.entries = append(data.entries[:index], data.entries[index+1:]...)
	return value
}

func weakMapClear(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if data := weakMapState(receiver); data != nil {
		data.entries = nil
	}
	return receiver
}

