func weakMapEachPair(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return weakMapEach(receiver, 0)
}

func weakMapEachKey(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return weakMapEach(receiver, 1)
}

func weakMapEachValue(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return weakMapEach(receiver, 2)
}

func weakMapEach(receiver *object.EmeraldValue, mode int) *object.EmeraldValue {
	data := weakMapState(receiver)
	if data == nil || len(data.entries) == 0 {
		return receiver
	}
	if BlockGivenCheck == nil || !BlockGivenCheck() || CurrentBlockValue == nil || CurrentBlockValue() == nil {
		return newRuntimeException(R.Classes["LocalJumpError"], "no block given")
	}
	block := CurrentBlockValue()
	for _, entry := range data.entries {
		switch mode {
		case 1:
			CallBlockWithArgs(block, entry.key)
		case 2:
			CallBlockWithArgs(block, entry.value)
		default:
			CallBlockWithArgs(block, entry.key, entry.value)
		}
	}
	return receiver
}

func weakMapInspect(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data := weakMapState(receiver)
	if data == nil {
		return rubyString(fmt.Sprintf("#<%s:%p>", receiver.Class.Name, receiver))
	}
	if data.weakKeys {
		return rubyString(fmt.Sprintf("#<ObjectSpace::WeakKeyMap:%p size=%d>", receiver, len(data.entries)))
	}
	if len(data.entries) == 0 {
		return rubyString(fmt.Sprintf("#<ObjectSpace::WeakMap:%p>", receiver))
	}
	parts := make([]string, 0, len(data.entries))
	for _, entry := range data.entries {
		parts = append(parts, entry.key.Inspect()+" => "+entry.value.Inspect())
	}
	return rubyString(fmt.Sprintf("#<ObjectSpace::WeakMap:%p: %s>", receiver, strings.Join(parts, ", ")))
}

func installGCModule(objectClass *object.Class) {
	if objectClass == nil {
		return
	}
	if existing, ok := objectClass.Constants["GC"]; ok && existing != nil && existing.Type == object.ValueModule {
		return
	}
	gcModule := object.NewModule("GC")
	gcModule.DefineMethod("auto_compact", &object.Method{Name: "auto_compact", Fn: gcAutoCompactGet, Arity: 0})
	gcModule.DefineMethod("auto_compact=", &object.Method{Name: "auto_compact=", Fn: gcAutoCompactSet, Arity: 1})
	gcModule.DefineMethod("config", &object.Method{Name: "config", Fn: gcConfig, Arity: -1})
	gcModule.DefineMethod("count", &object.Method{Name: "count", Fn: gcCount, Arity: 0})
	gcModule.DefineMethod("disable", &object.Method{Name: "disable", Fn: gcDisable, Arity: 0})
	gcModule.DefineMethod("enable", &object.Method{Name: "enable", Fn: gcEnable, Arity: 0})
	gcModule.DefineMethod("garbage_collect", &object.Method{Name: "garbage_collect", Fn: gcStart, Arity: -1})
	gcModule.DefineMethod("measure_total_time", &object.Method{Name: "measure_total_time", Fn: gcMeasureTotalTimeGet, Arity: 0})
	gcModule.DefineMethod("measure_total_time=", &object.Method{Name: "measure_total_time=", Fn: gcMeasureTotalTimeSet, Arity: 1})
	gcModule.DefineMethod("start", &object.Method{Name: "start", Fn: gcStart, Arity: -1})
	gcModule.DefineMethod("stat", &object.Method{Name: "stat", Fn: gcStat, Arity: -1})
	gcModule.DefineMethod("stress", &object.Method{Name: "stress", Fn: gcStressGet, Arity: 0})
	gcModule.DefineMethod("stress=", &object.Method{Name: "stress=", Fn: gcStressSet, Arity: 1})
	gcModule.DefineMethod("total_time", &object.Method{Name: "total_time", Fn: gcTotalTime, Arity: 0})
	profilerModule := object.NewModule("GC::Profiler")
	profilerModule.DefineMethod("clear", &object.Method{Name: "clear", Fn: gcProfilerClear, Arity: 0})
	profilerModule.DefineMethod("disable", &object.Method{Name: "disable", Fn: gcProfilerDisable, Arity: 0})
	profilerModule.DefineMethod("enable", &object.Method{Name: "enable", Fn: gcProfilerEnable, Arity: 0})
	profilerModule.DefineMethod("enabled?", &object.Method{Name: "enabled?", Fn: gcProfilerEnabledPredicate, Arity: 0})
	profilerModule.DefineMethod("report", &object.Method{Name: "report", Fn: gcProfilerReport, Arity: 0})
	profilerModule.DefineMethod("total_time", &object.Method{Name: "total_time", Fn: gcProfilerTotalTime, Arity: 0})
	profilerModule.DefineMethod("result", &object.Method{Name: "result", Fn: gcProfilerResult, Arity: 0})
	profilerValue := &object.EmeraldValue{Type: object.ValueModule, Data: profilerModule, Class: R.Classes["Module"]}
	gcModule.Constants["Profiler"] = profilerValue
	gcValue := &object.EmeraldValue{Type: object.ValueModule, Data: gcModule, Class: R.Classes["Module"]}
	objectClass.DefineConstant("GC", gcValue)
	AssignConstantName(&object.EmeraldValue{Type: object.ValueClass, Data: objectClass, Class: R.Classes["Class"]}, "GC", gcValue)
}

