func gcConfig(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) > 1 {
		return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 0..1)", len(args)))
	}
	if len(args) == 1 && args[0] != nil && args[0].Type != object.ValueNil {
		if args[0].Type != object.ValueHash {
			return NewArgumentError("expected keyword arguments")
		}
		data := hashData(args[0])
		if data != nil {
			for key, value := range data.Pairs {
				name := ""
				if key != nil && (key.Type == object.ValueSymbol || key.Type == object.ValueString) {
					name = key.Data.(string)
				}
				if name == "implementation" {
					return NewArgumentError(`Attempting to set read-only key "Implementation"`)
				}
				if _, known := gcConfigValues[name]; known {
					gcConfigValues[name] = isTruthy(value)
				}
			}
		}
	}
	return gcConfigSnapshot()
}

func gcConfigSnapshot() *object.EmeraldValue {
	result := emptyHashValue()
	hashIndexSet(result, rubySymbol("implementation"), rubyString("default"))
	keys := make([]string, 0, len(gcConfigValues))
	for key := range gcConfigValues {
		keys = append(keys, key)
	}
	sort.Strings(keys)
	for _, key := range keys {
		hashIndexSet(result, rubySymbol(key), boolValue(gcConfigValues[key]))
	}
	return result
}

func gcStat(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) > 1 {
		return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 0..1)", len(args)))
	}
	stats := map[string]int64{
		"count":                   gcCountValue,
		"major_gc_count":          gcMajorCountValue,
		"heap_free_slots":         0,
		"total_allocated_objects": int64(len(objectSpaceTracked)),
	}
	if len(args) == 1 && args[0] != nil && args[0].Type != object.ValueNil {
		switch args[0].Type {
		case object.ValueSymbol:
			name := args[0].Data.(string)
			value, ok := stats[name]
			if !ok {
				return NewArgumentError("unknown key: " + name)
			}
			return newInt(value)
		case object.ValueHash:
			for name, value := range stats {
				hashIndexSet(args[0], rubySymbol(name), newInt(value))
			}
			return args[0]
		default:
			return typeError("non-hash or symbol given")
		}
	}
	result := emptyHashValue()
	keys := []string{"count", "major_gc_count", "heap_free_slots", "total_allocated_objects"}
	for _, name := range keys {
		hashIndexSet(result, rubySymbol(name), newInt(stats[name]))
	}
	return result
}

