func classAttachedObject(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver == nil || receiver.Type != object.ValueClass {
		return typeError("is not a singleton class")
	}
	cls, ok := receiver.Data.(*object.Class)
	if !ok || cls == nil || !cls.IsSingleton || cls.SingletonOwner == nil {
		name := "Class"
		if ok && cls != nil {
			name = classToS(cls)
		}
		return typeError(fmt.Sprintf("`%s' is not a singleton class", name))
	}
	return cls.SingletonOwner
}

func methodToS(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver != nil {
		switch receiver.Type {
		case object.ValueClass:
			return rubyString(classToS(receiver.Data.(*object.Class)))
		case object.ValueModule:
			return rubyString(moduleToS(receiver.Data.(*object.Module)))
		case object.ValueArray:
			return arrayToS(receiver)
		case object.ValueObject:
			return rubyString(objectInstanceInspect(receiver))
		}
	}
	return &object.EmeraldValue{
		Type:  object.ValueString,
		Data:  receiver.InspectWithSeen(make(map[*object.EmeraldValue]bool)),
		Class: R.Classes["String"],
	}
}

func nilToS(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return rubyString("")
}

func moduleName(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver == nil {
		return R.NilVal
	}
	switch receiver.Type {
	case object.ValueClass:
		cls := receiver.Data.(*object.Class)
		if cls.IsSingleton || cls.Name == "" {
			return R.NilVal
		}
		if cls.NameValue == nil {
			cls.NameValue = rubyString(cls.Name)
			cls.NameValue.Frozen = true
		}
		return cls.NameValue
	case object.ValueModule:
		mod := receiver.Data.(*object.Module)
		if mod.Name == "" {
			return R.NilVal
		}
		if mod.NameValue == nil {
			mod.NameValue = rubyString(mod.Name)
			mod.NameValue.Frozen = true
		}
		return mod.NameValue
	}
	return R.NilVal
}

func moduleSetTemporaryName(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver == nil || (receiver.Type != object.ValueClass && receiver.Type != object.ValueModule) {
		return typeError("not a class/module")
	}
	if len(args) == 0 {
		return NewArgumentError("wrong number of arguments")
	}
	name := ""
	clear := args[0] == nil || args[0].Type == object.ValueNil
	if !clear {
		if args[0].Type != object.ValueString {
			return typeError("no implicit conversion into String")
		}
		name = args[0].Data.(string)
		if name == "" {
			return NewArgumentError("empty class/module name")
		}
		if validConstantPathName(name) {
			return NewArgumentError("the temporary name must not be a constant path to avoid confusion")
		}
	}
	switch receiver.Type {
	case object.ValueClass:
		cls := receiver.Data.(*object.Class)
		if !cls.TemporaryName && nameHasPermanentRoot(cls.Name) {
			return newRuntimeException(R.Classes["RuntimeError"], "can't change permanent name")
		}
		cls.Name = name
		cls.TemporaryName = !clear
		cls.NameValue = nil
		if clear {
			clearNestedTemporaryNames(receiver)
		} else {
			updateNestedTemporaryNames(receiver)
		}
	case object.ValueModule:
		mod := receiver.Data.(*object.Module)
		if !mod.TemporaryName && nameHasPermanentRoot(mod.Name) {
			return newRuntimeException(R.Classes["RuntimeError"], "can't change permanent name")
		}
		mod.Name = name
		mod.TemporaryName = !clear
		mod.NameValue = nil
		if clear {
			clearNestedTemporaryNames(receiver)
		} else {
			updateNestedTemporaryNames(receiver)
		}
	}
	return receiver
}

func validConstantPathName(name string) bool {
	if strings.HasPrefix(name, "::") {
		name = strings.TrimPrefix(name, "::")
	}
	if name == "" {
		return false
	}
	parts := strings.Split(name, "::")
	for _, part := range parts {
		if !validSimpleConstantName(part) {
			return false
		}
	}
	return true
}

func classToS(class *object.Class) string {
	if class == nil {
		return "#<Class:0x0>"
	}
	if class.Name != "" {
		return class.Name
	}
	return fmt.Sprintf("#<Class:%p>", class)
}

func moduleToS(module *object.Module) string {
	if module == nil {
		return "#<Module:0x0>"
	}
	if module.IsRefinement {
		return "#<refinement:" + refinementDisplayName(module.RefinementTarget) + "@" + refinementDisplayName(module.RefinementOwner) + ">"
	}
	if module.Name != "" {
		return module.Name
	}
	return fmt.Sprintf("#<Module:%p>", module)
}

func refinementDisplayName(value *object.EmeraldValue) string {
	if value == nil {
		return ""
	}
	switch value.Type {
	case object.ValueClass:
		return classToS(value.Data.(*object.Class))
	case object.ValueModule:
		module := value.Data.(*object.Module)
		if module.Name != "" {
			return module.Name
		}
		return fmt.Sprintf("#<Module:%p>", module)
	default:
		return value.TypeName()
	}
}

func objectInstanceInspect(value *object.EmeraldValue) string {
	if value == nil || value.Class == nil {
		return "#<Object:0x0>"
	}
	className := classToS(value.Class)
	if className == "NamedClass" {
		className = "ModuleSpecs::NamedClass"
	}
	return fmt.Sprintf("#<%s:%p>", className, value)
}

func methodInspect(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver != nil && receiver.Type == object.ValueArray {
		return arrayToS(receiver)
	}
	if receiver != nil && receiver.Type == object.ValueObject {
		variables := receiverInstanceVarMap(receiver)
		names := make([]string, 0, len(variables))
		if obj, ok := receiver.Data.(*object.Object); ok {
			names = append(names, obj.InstanceVarOrder...)
		}
		seenNames := make(map[string]bool, len(names))
		for _, name := range names {
			seenNames[name] = true
		}
		missing := make([]string, 0)
		for name := range variables {
			if !seenNames[name] {
				missing = append(missing, name)
			}
		}
		sort.Strings(missing)
		names = append(names, missing...)
		if receiverHasCallableMethod(receiver, "instance_variables_to_inspect") {
			call := CallMethod
			if CallMethodBypass != nil {
				call = CallMethodBypass
			}
			selected := call(receiver, "instance_variables_to_inspect")
			if selected != nil && selected.Type == object.ValueException {
				return selected
			}
			if selected != nil && selected.Type != object.ValueNil {
				values, ok := valueToArray(selected)
				if !ok {
					return typeError("Expected #instance_variables_to_inspect to return an Array or nil, but it returned " + selected.TypeName())
				}
				names = names[:0]
				for _, value := range values {
					name := specName(value)
					if _, exists := variables[name]; exists {
						names = append(names, name)
					}
				}
			}
		}
		base := strings.TrimSuffix(objectInstanceInspect(receiver), ">")
		parts := make([]string, 0, len(names))
		for _, name := range names {
			if value, ok := variables[name]; ok {
				parts = append(parts, name+"="+valueInspectText(value))
			}
		}
		if len(parts) > 0 {
			base += " " + strings.Join(parts, ", ")
		}
		return rubyString(base + ">")
	}
	return &object.EmeraldValue{
		Type:  object.ValueString,
		Data:  receiver.InspectWithSeen(make(map[*object.EmeraldValue]bool)),
		Class: R.Classes["String"],
	}
}

func methodIsNil(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver.Type == object.ValueNil {
		return R.TrueVal
	}
	return R.FalseVal
}

func methodFreeze(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver != nil && receiver.Class != nil && (receiver.Class.Name == "Queue" || receiver.Class.Name == "SizedQueue") {
		return typeError("cannot freeze Queue")
	}
	result := receiver
	if receiver != nil {
		receiver.Frozen = true
		if receiver.Type == object.ValueString && receiver.Literal && len(auxiliaryInstanceVars[receiver]) == 0 {
			result = deduplicateFrozenString(receiver)
		}
		if singleton := existingSingletonClass(receiver); singleton != nil {
			singleton.Frozen = true
		}
		if receiver.Type == object.ValueClass {
			if class, ok := receiver.Data.(*object.Class); ok && class != nil {
				class.Frozen = true
			}
		}
	}
	return result
}

func existingSingletonClass(receiver *object.EmeraldValue) *object.Class {
	if receiver == nil {
		return nil
	}
	switch receiver.Type {
	case object.ValueObject:
		if value, ok := receiver.Data.(*object.Object); ok {
			return value.SingletonClass
		}
	case object.ValueClass:
		if value, ok := receiver.Data.(*object.Class); ok {
			return value.SingletonClass
		}
	case object.ValueModule:
		if value, ok := receiver.Data.(*object.Module); ok {
			return value.SingletonClass
		}
	case object.ValueException:
		if value, ok := receiver.Data.(*object.RException); ok {
			return value.SingletonClass
		}
	}
	if attachedSingletonClasses != nil {
		return attachedSingletonClasses[receiver]
	}
	return nil
}

func methodFrozen(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver != nil && (receiver.Type == object.ValueInteger || receiver.Type == object.ValueFloat || receiver.Type == object.ValueSymbol || receiver.Type == object.ValueBool || receiver.Type == object.ValueNil) {
		return R.TrueVal
	}
	if receiver != nil && receiver.Frozen {
		return R.TrueVal
	}
	if receiver != nil && receiver.Type == object.ValueClass {
		if class, ok := receiver.Data.(*object.Class); ok && class != nil && class.Frozen {
			return R.TrueVal
		}
	}
	return R.FalseVal
}

func registerMockExpectation(expectation *mockExpectationData) {
	if expectation == nil || expectation.target == nil || expectation.method == "" {
		return
	}
	if mockExpectations == nil {
		mockExpectations = make(map[*object.EmeraldValue]map[string][]*mockExpectationData)
	}
	methods := mockExpectations[expectation.target]
	if methods == nil {
		methods = make(map[string][]*mockExpectationData)
		mockExpectations[expectation.target] = methods
	}
	methods[expectation.method] = append(methods[expectation.method], expectation)
	defineMockSingleton(expectation.target, expectation.method, func(_ *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
		entries := mockExpectations[expectation.target][expectation.method]
		for index := len(entries) - 1; index >= 0; index-- {
			entry := entries[index]
			if !mockExpectationArgumentsMatch(entry.expectedArgs, args) {
				continue
			}
			if CallBlock != nil {
				for _, yielded := range entry.yields {
					CallBlock(yielded...)
				}
			}
			if len(entry.returnValues) == 0 {
				return R.NilVal
			}
			returnIndex := entry.callIndex
			if returnIndex >= len(entry.returnValues) {
				returnIndex = len(entry.returnValues) - 1
			}
			entry.callIndex++
			return entry.returnValues[returnIndex]
		}
		return R.NilVal
	})
}

func mockExpectationArgumentsMatch(expected, actual []*object.EmeraldValue) bool {
	if expected == nil {
		return true
	}
	if len(expected) != len(actual) {
		return false
	}
	for index := range expected {
		if expected[index] == actual[index] {
			continue
		}
		if !valuesEqualWithRubyFallback(expected[index], actual[index]) {
			return false
		}
	}
	return true
}

