func ioStubWrite(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	written := int64(0)
	current, _ := receiver.Data.(string)
	for _, arg := range args {
		text := ""
		if arg != nil {
			text = arg.Inspect()
			if arg.Type == object.ValueString {
				text = arg.Data.(string)
			}
		}
		current += text
		written += int64(len(text))
	}
	receiver.Data = current
	return &object.EmeraldValue{Type: object.ValueInteger, Data: written, Class: R.Classes["Integer"]}
}

func ioStubPuts(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 0 {
		return ioStubWrite(receiver, rubyString("\n"))
	}
	for _, arg := range args {
		text := ""
		if arg != nil {
			text = arg.Inspect()
			if arg.Type == object.ValueString {
				text = arg.Data.(string)
			}
		}
		ioStubWrite(receiver, rubyString(text+"\n"))
	}
	return R.NilVal
}

func defineMockSingleton(target *object.EmeraldValue, method string, fn func(*object.EmeraldValue, ...*object.EmeraldValue) *object.EmeraldValue) {
	defineMockSingletonWithArity(target, method, -1, fn)
}

func defineMockSingletonWithArity(target *object.EmeraldValue, method string, arity int, fn func(*object.EmeraldValue, ...*object.EmeraldValue) *object.EmeraldValue) {
	if target == nil {
		return
	}

	methodFn := &object.Method{Name: method, Arity: arity, Fn: fn}

	switch target.Type {
	case object.ValueObject:
		obj, ok := target.Data.(*object.Object)
		if !ok || obj == nil || obj.SingletonMethods == nil {
			if InstallNativeSingletonMethod != nil {
				mockRestores = append(mockRestores, InstallNativeSingletonMethod(target, method, methodFn))
			}
			return
		}
		previous, hadPrevious := obj.SingletonMethods[method]
		obj.SingletonMethods[method] = methodFn
		mockRestores = append(mockRestores, func() {
			if hadPrevious {
				obj.SingletonMethods[method] = previous
			} else {
				delete(obj.SingletonMethods, method)
			}
		})
	case object.ValueClass, object.ValueModule:
		singleton := methodSingletonClass(target)
		if singleton == nil || singleton.Data == nil {
			return
		}
		singletonClass, ok := singleton.Data.(*object.Class)
		if !ok || singletonClass == nil || singletonClass.Methods == nil {
			return
		}
		previous, hadPrevious := singletonClass.Methods[method]
		singletonClass.Methods[method] = methodFn
		mockRestores = append(mockRestores, func() {
			if hadPrevious {
				singletonClass.Methods[method] = previous
			} else {
				delete(singletonClass.Methods, method)
			}
		})
	default:
		if InstallNativeSingletonMethod != nil {
			mockRestores = append(mockRestores, InstallNativeSingletonMethod(target, method, methodFn))
		}
	}
}

