func moduleFunction(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver == nil || receiver.Type != object.ValueModule {
		return typeError("module_function must be called for modules")
	}
	if len(args) == 0 {
		setCurrentMethodVisibility(receiver, "module_function")
		return R.NilVal
	}
	names, errVal := classMethodNamesFromValues(args...)
	if errVal != nil {
		return errVal
	}
	singleton := methodSingletonClass(receiver)
	if singleton == nil || singleton.Type != object.ValueClass {
		return R.NilVal
	}
	singletonClass := singleton.Data.(*object.Class)
	for _, name := range names {
		method, _, ok := lookupInstanceMethodWithOwner(receiver, name)
		if !ok {
			return NewNameError("undefined method `" + name + "'")
		}
		copy := *method
		copy.Name = name
		copy.Visibility = "public"
		copy.Owner = singleton
		singletonClass.Methods[name] = &copy
		setNamedMethodVisibility(receiver, name, "private")
		if hook := NotifySingletonMethodAdded(receiver, name); hook != nil && hook.Type == object.ValueException {
			return hook
		}
	}
	if len(args) == 1 && args[0] != nil && args[0].Type != object.ValueArray {
		return &object.EmeraldValue{Type: object.ValueSymbol, Data: names[0], Class: R.Classes["Symbol"]}
	}
	return symbolArray(names...)
}

func methodSingletonClass(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return SingletonClass(receiver)
}

func SingletonClass(receiver *object.EmeraldValue) *object.EmeraldValue {
	if receiver == nil {
		return R.NilVal
	}
	switch receiver.Type {
	case object.ValueBool, object.ValueNil:
		if receiver.Class != nil {
			return &object.EmeraldValue{Type: object.ValueClass, Data: receiver.Class, Class: R.Classes["Class"]}
		}
	case object.ValueInteger, object.ValueFloat, object.ValueSymbol:
		return NewTypeError("can't define singleton")
	case object.ValueString:
		if receiver.Frozen {
			return NewTypeError("can't define singleton")
		}
	}
	name := singletonClassName(receiver)
	if name == "" {
		return R.NilVal
	}
	var class *object.Class
	switch receiver.Type {
	case object.ValueObject:
		obj, ok := receiver.Data.(*object.Object)
		if !ok {
			class = attachedSingletonClasses[receiver]
			if class == nil {
				class = object.NewClass(name)
				class.SingletonOwner = receiver
				class.SuperClass = receiver.Class
				attachedSingletonClasses[receiver] = class
			}
			break
		}
		class = obj.SingletonClass
		if class == nil {
			class = object.NewClass(name)
			class.SingletonOwner = receiver
			class.SuperClass = receiver.Class
			obj.SingletonClass = class
		}
	case object.ValueClass:
		cls := receiver.Data.(*object.Class)
		class = cls.SingletonClass
		if class == nil {
			class = object.NewClass(name)
			class.SingletonOwner = receiver
			for methodName, method := range cls.ClassMethods {
				class.Methods[methodName] = method
			}
			cls.SingletonClass = class
		}
		if class.SuperClass == nil && cls.SuperClass != nil {
			superSingleton := methodSingletonClass(&object.EmeraldValue{
				Type:  object.ValueClass,
				Data:  cls.SuperClass,
				Class: R.Classes["Class"],
			})
			if superSingleton != nil && superSingleton.Data != nil {
				if superClass, ok := superSingleton.Data.(*object.Class); ok && superClass != nil {
					class.SuperClass = superClass
				}
			}
		}
	case object.ValueModule:
		mod := receiver.Data.(*object.Module)
		class = mod.SingletonClass
		if class == nil {
			class = object.NewClass(name)
			class.SingletonOwner = receiver
			mod.SingletonClass = class
		}
	case object.ValueException:
		exc := receiver.Data.(*object.RException)
		class = exc.SingletonClass
		if class == nil {
			class = object.NewClass(name)
			class.SingletonOwner = receiver
			class.SuperClass = receiver.Class
			exc.SingletonClass = class
		}
	default:
		class = attachedSingletonClasses[receiver]
		if class == nil {
			class = object.NewClass(name)
			class.SingletonOwner = receiver
			class.SuperClass = receiver.Class
			attachedSingletonClasses[receiver] = class
		}
	}
	class.IsSingleton = true
	if receiver.Frozen {
		class.Frozen = true
	}
	if class.SuperClass == nil {
		class.SuperClass = R.Classes["Class"]
	}
	result := &object.EmeraldValue{Type: object.ValueClass, Data: class, Class: R.Classes["Class"], Frozen: class.Frozen}
	trackObjectSpaceValue(result)
	return result
}

func trackObjectSpaceValue(value *object.EmeraldValue) {
	if value == nil {
		return
	}
	for _, existing := range objectSpaceTracked {
		if existing == value || existing.Data == value.Data {
			return
		}
	}
	objectSpaceTracked = append(objectSpaceTracked, value)
}

func AttachedSingletonClass(receiver *object.EmeraldValue) *object.Class {
	return existingSingletonClass(receiver)
}

func cloneSingletonClass(orig *object.Class, owner *object.EmeraldValue) *object.Class {
	if orig == nil {
		return nil
	}
	clone := object.NewClass(orig.Name)
	clone.NameValue = orig.NameValue
	clone.TemporaryName = orig.TemporaryName
	clone.SuperClass = orig.SuperClass
	clone.IsSingleton = orig.IsSingleton
	clone.Frozen = orig.Frozen
	clone.SingletonOwner = owner
	for name, method := range orig.Methods {
		clone.Methods[name] = method
	}
	for name, constant := range orig.Constants {
		clone.Constants[name] = constant
	}
	for name, private := range orig.PrivateConstants {
		clone.PrivateConstants[name] = private
	}
	for name, deprecated := range orig.DeprecatedConstants {
		clone.DeprecatedConstants[name] = deprecated
	}
	for name, path := range orig.Autoloads {
		clone.Autoloads[name] = path
	}
	for name, classVar := range orig.ClassVars {
		clone.ClassVars[name] = classVar
	}
	for name, method := range orig.ClassMethods {
		clone.ClassMethods[name] = method
	}
	for name, ivar := range orig.InstanceVars {
		clone.InstanceVars[name] = ivar
	}
	clone.IncludedModules = append([]*object.Module{}, orig.IncludedModules...)
	clone.PrependedModules = append([]*object.Module{}, orig.PrependedModules...)
	return clone
}

func singletonClassName(receiver *object.EmeraldValue) string {
	switch receiver.Type {
	case object.ValueClass:
		return "#<Class:" + classToS(receiver.Data.(*object.Class)) + ">"
	case object.ValueModule:
		return "#<Class:" + moduleToS(receiver.Data.(*object.Module)) + ">"
	default:
		if receiver.Class != nil {
			return "#<Class:" + objectInstanceInspect(receiver) + ">"
		}
	}
	return ""
}

func methodInstanceVariableSet(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) < 2 {
		return newRuntimeException(R.Classes["ArgumentError"], "wrong number of arguments")
	}
	name := specName(args[0])
	if name == "" {
		return typeError("nil is not a symbol nor a string")
	}
	if !validInstanceVariableName(name) {
		return NewNameError("`" + name + "' is not allowed as an instance variable name")
	}
	if result := setDynamicInstanceVar(receiver, name, args[1]); result != nil {
		return result
	}
	return args[1]
}

func methodInstanceVariableGet(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) < 1 {
		return newRuntimeException(R.Classes["ArgumentError"], "wrong number of arguments")
	}
	name := specName(args[0])
	if name == "" {
		return typeError("nil is not a symbol nor a string")
	}
	if !validInstanceVariableName(name) {
		return NewNameError("`" + name + "' is not allowed as an instance variable name")
	}
	value := DynamicInstanceVar(receiver, name)
	if value == nil {
		return R.NilVal
	}
	return value
}

func methodInstanceVariableDefined(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) < 1 {
		return newRuntimeException(R.Classes["ArgumentError"], "wrong number of arguments")
	}
	name := specName(args[0])
	if name == "" {
		return typeError("nil is not a symbol nor a string")
	}
	if !strings.HasPrefix(name, "@") {
		name = "@" + name
	}
	vars := receiverInstanceVarMap(receiver)
	if _, ok := vars[name]; ok {
		return R.TrueVal
	}
	return R.FalseVal
}

func methodInstanceVariables(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	vars := receiverInstanceVarMap(receiver)
	names := make([]string, 0, len(vars))
	seen := make(map[string]bool, len(vars))
	if receiver != nil && receiver.Type == object.ValueObject {
		if obj, ok := receiver.Data.(*object.Object); ok {
			for _, name := range obj.InstanceVarOrder {
				if _, exists := vars[name]; exists && !seen[name] {
					names = append(names, name)
					seen[name] = true
				}
			}
		}
	}
	missing := make([]string, 0, len(vars)-len(names))
	for name := range vars {
		if !seen[name] {
			missing = append(missing, name)
		}
	}
	sort.Strings(missing)
	names = append(names, missing...)

	result := make([]*object.EmeraldValue, 0, len(names))
	for _, name := range names {
		result = append(result, &object.EmeraldValue{Type: object.ValueSymbol, Data: name, Class: R.Classes["Symbol"]})
	}
	return &object.EmeraldValue{Type: object.ValueArray, Data: result, Class: R.Classes["Array"]}
}

func methodRemoveInstanceVariable(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) < 1 {
		return newRuntimeException(R.Classes["ArgumentError"], "wrong number of arguments")
	}
	name := specName(args[0])
	if name == "" {
		return typeError("nil is not a symbol nor a string")
	}
	if !validInstanceVariableName(name) {
		return NewNameError("`" + name + "' is not allowed as an instance variable name")
	}
	if attrWriteFrozen(receiver) {
		return instanceVariableFrozenError(receiver)
	}

	vars := receiverInstanceVarMap(receiver)
	if value, ok := vars[name]; ok {
		delete(vars, name)
		return value
	}
	return NewNameError("instance variable " + name + " not defined")
}

func validInstanceVariableName(name string) bool {
	if len(name) < 2 || name[0] != '@' {
		return false
	}
	first := rune(name[1])
	if first >= '0' && first <= '9' {
		return false
	}
	return true
}

func receiverInstanceVarMap(receiver *object.EmeraldValue) map[string]*object.EmeraldValue {
	if receiver == nil {
		return map[string]*object.EmeraldValue{}
	}
	switch receiver.Type {
	case object.ValueObject:
		if obj, ok := receiver.Data.(*object.Object); ok {
			return obj.InstanceVars
		}
	case object.ValueHash:
		if hash := hashData(receiver); hash != nil {
			if hash.InstanceVars == nil {
				hash.InstanceVars = make(map[string]*object.EmeraldValue)
			}
			return hash.InstanceVars
		}
	case object.ValueException:
		if exc, ok := receiver.Data.(*object.RException); ok {
			if exc.InstanceVars == nil {
				exc.InstanceVars = make(map[string]*object.EmeraldValue)
			}
			return exc.InstanceVars
		}
	case object.ValueProc:
		if proc, ok := receiver.Data.(*object.Proc); ok {
			if proc.InstanceVars == nil {
				proc.InstanceVars = make(map[string]*object.EmeraldValue)
			}
			return proc.InstanceVars
		}
	case object.ValueClass:
		if cls, ok := receiver.Data.(*object.Class); ok {
			return cls.InstanceVars
		}
	case object.ValueModule:
		if mod, ok := receiver.Data.(*object.Module); ok {
			return mod.InstanceVars
		}
	}
	if auxiliaryInstanceVars == nil {
		auxiliaryInstanceVars = make(map[*object.EmeraldValue]map[string]*object.EmeraldValue)
	}
	variables := auxiliaryInstanceVars[receiver]
	if variables == nil {
		variables = make(map[string]*object.EmeraldValue)
		auxiliaryInstanceVars[receiver] = variables
	}
	return variables
}

func methodDup(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver == nil {
		return R.NilVal
	}
	if classInheritsFrom(receiverEffectiveClass(receiver), R.Classes["Numeric"]) {
		return receiver
	}
	switch receiver.Type {
	case object.ValueString:
		result := duplicateStringValue(receiver, false, false)
		if initResult := callStringInitializeCopy(result, receiver); initResult != nil {
			return initResult
		}
		return result
	case object.ValueHash:
		if receiver == envObject {
			return typeError("Cannot dup ENV, use ENV.to_h to get a copy of ENV as a hash")
		}
		return &object.EmeraldValue{Type: object.ValueHash, Data: cloneRHash(hashData(receiver)), Class: receiver.Class}
	case object.ValueRegexp:
		duplicate := *receiver
		duplicate.Frozen = false
		duplicate.Literal = false
		result := &duplicate
		if variables := auxiliaryInstanceVars[receiver]; len(variables) > 0 {
			copied := make(map[string]*object.EmeraldValue, len(variables))
			for name, value := range variables {
				copied[name] = value
			}
			auxiliaryInstanceVars[result] = copied
		}
		return result
	case object.ValueException:
		orig, ok := receiver.Data.(*object.RException)
		if !ok {
			return &object.EmeraldValue{Type: object.ValueException, Data: receiver.Data, Class: receiver.Class}
		}
		dup := *orig
		dup.SingletonClass = nil
		if orig.InstanceVars != nil {
			dup.InstanceVars = make(map[string]*object.EmeraldValue, len(orig.InstanceVars))
			for name, value := range orig.InstanceVars {
				dup.InstanceVars[name] = value
			}
		}
		if orig.NoMethodArgs != nil {
			dup.NoMethodArgs = append([]*object.EmeraldValue{}, orig.NoMethodArgs...)
		}
		result := &object.EmeraldValue{Type: object.ValueException, Data: &dup, Class: receiver.Class}
		call := CallMethodBypass
		if call == nil {
			call = CallMethod
		}
		if call != nil && receiverHasCallableMethod(result, "initialize_dup") {
			if initialized := call(result, "initialize_dup", receiver); initialized != nil && initialized.Type == object.ValueException {
				return initialized
			}
		}
		return result
	case object.ValueProc:
		result := duplicateProcValue(receiver, false)
		if CallMethodBypass != nil && receiverHasCallableMethod(result, "initialize_dup") {
			if initialized := CallMethodBypass(result, "initialize_dup", receiver); initialized != nil && initialized.Type == object.ValueException {
				return initialized
			}
		}
		return result
	case object.ValueMatchData:
		original, ok := matchDataPayload(receiver)
		if !ok {
			return &object.EmeraldValue{Type: object.ValueMatchData, Data: receiver.Data, Class: receiver.Class}
		}
		duplicate := *original
		duplicate.Matches = append([]string(nil), original.Matches...)
		duplicate.Indices = append([]int(nil), original.Indices...)
		duplicate.NameOrder = append([]string(nil), original.NameOrder...)
		duplicate.Names = make(map[string][]int, len(original.Names))
		for name, indices := range original.Names {
			duplicate.Names[name] = append([]int(nil), indices...)
		}
		result := &object.EmeraldValue{Type: object.ValueMatchData, Data: &duplicate, Class: receiver.Class}
		if variables := auxiliaryInstanceVars[receiver]; variables != nil {
			copied := make(map[string]*object.EmeraldValue, len(variables))
			for name, value := range variables {
				copied[name] = value
			}
			auxiliaryInstanceVars[result] = copied
		}
		return result
	case object.ValueMethod:
		original, ok := receiver.Data.(*object.Method)
		if !ok || original == nil {
			return &object.EmeraldValue{Type: object.ValueMethod, Data: receiver.Data, Class: receiver.Class}
		}
		duplicate := *original
		result := &object.EmeraldValue{Type: object.ValueMethod, Data: &duplicate, Class: receiver.Class}
		if variables := auxiliaryInstanceVars[receiver]; variables != nil {
			copied := make(map[string]*object.EmeraldValue, len(variables))
			for name, value := range variables {
				copied[name] = value
			}
			auxiliaryInstanceVars[result] = copied
		}
		if finalizers := objectSpaceFinalizers[receiver]; len(finalizers) > 0 {
			objectSpaceFinalizers[result] = append([]*object.EmeraldValue(nil), finalizers...)
		}
		return result
	case object.ValueObject:
		orig, ok := receiver.Data.(*object.Object)
		if !ok {
			switch data := receiver.Data.(type) {
			case *ioShimData:
				if data.closed {
					return newRuntimeException(R.Classes["IOError"], "closed stream")
				}
				cloned := *data
				rootFD := data.fd
				if data.dupSourceFD >= 0 {
					rootFD = data.dupSourceFD
				}
				data.dupSourceFD = rootFD
				cloned.fd = nextIOFd
				nextIOFd++
				cloned.dupSourceFD = rootFD
				cloned.closed = false
				cloned.closeOnExec = true
				cloned.autoclose = true
				if ioDataByFd != nil {
					ioDataByFd[cloned.fd] = &cloned
				}
				return &object.EmeraldValue{Type: object.ValueObject, Data: &cloned, Class: receiver.Class}
			case *processStatusData:
				cloned := *data
				return &object.EmeraldValue{Type: object.ValueObject, Data: &cloned, Class: receiver.Class}
			case *stringScannerData:
				cloned := *data
				cloned.lastMatches = append([]string(nil), data.lastMatches...)
				if data.lastNames != nil {
					cloned.lastNames = make(map[string]int, len(data.lastNames))
					for name, index := range data.lastNames {
						cloned.lastNames[name] = index
					}
				}
				return &object.EmeraldValue{Type: object.ValueObject, Data: &cloned, Class: receiver.Class}
			default:
				return &object.EmeraldValue{Type: object.ValueObject, Data: data, Class: receiver.Class}
			}
		}
		dup := object.NewObject(orig.Class)
		dup.StructValues = append([]*object.EmeraldValue(nil), orig.StructValues...)
		for name, value := range orig.InstanceVars {
			dup.InstanceVars[name] = value
		}
		for name, value := range orig.ClassVars {
			dup.ClassVars[name] = value
		}
		result := &object.EmeraldValue{Type: object.ValueObject, Data: dup, Class: receiver.Class}
		call := CallMethod
		if CallMethodBypass != nil {
			call = CallMethodBypass
		}
		if call != nil && receiverHasCallableMethod(result, "initialize_dup") {
			if initialized := call(result, "initialize_dup", receiver); initialized != nil && initialized.Type == object.ValueException {
				return initialized
			}
		}
		return result
	case object.ValueModule:
		orig := receiver.Data.(*object.Module)
		dup := object.NewModule(orig.Name)
		dup.TemporaryName = orig.TemporaryName
		dup.IsRefinement = orig.IsRefinement
		dup.RefinementTarget = orig.RefinementTarget
		dup.RefinementOwner = orig.RefinementOwner
		for name, method := range orig.Methods {
			dup.Methods[name] = method
		}
		for name, constant := range orig.Constants {
			dup.Constants[name] = constant
		}
		for name, path := range orig.Autoloads {
			dup.Autoloads[name] = path
		}
		for name, private := range orig.PrivateConstants {
			dup.PrivateConstants[name] = private
		}
		for name, classVar := range orig.ClassVars {
			dup.ClassVars[name] = classVar
		}
		for name, ivar := range orig.InstanceVars {
			if name == "@__rgo_singleton_instance" {
				continue
			}
			dup.InstanceVars[name] = ivar
		}
		dup.Parent = orig.Parent
		dup.IncludedModules = append([]*object.Module{}, orig.IncludedModules...)
		dup.PrependedModules = append([]*object.Module{}, orig.PrependedModules...)
		dup.ClassVarOrder = append([]string{}, orig.ClassVarOrder...)
		result := &object.EmeraldValue{Type: object.ValueModule, Data: dup, Class: R.Classes["Module"]}
		dup.SingletonClass = cloneSingletonClass(orig.SingletonClass, result)
		return result
	case object.ValueClass:
		orig := receiver.Data.(*object.Class)
		if orig.Name == "BasicObject" && orig.SuperClass == nil {
			return typeError("can't copy the root class")
		}
		dup := object.NewClass("")
		dup.TemporaryName = orig.TemporaryName
		dup.SuperClass = orig.SuperClass
		if orig.StructFields != nil {
			dup.StructFields = append([]string{}, orig.StructFields...)
		}
		dup.StructKeywordInit = orig.StructKeywordInit
		dup.DirectSubclasses = append([]*object.Class(nil), orig.DirectSubclasses...)
		for name, method := range orig.Methods {
			dup.Methods[name] = method
		}
		for name, method := range orig.ClassMethods {
			dup.ClassMethods[name] = method
		}
		for name, constant := range orig.Constants {
			dup.Constants[name] = constant
		}
		for name, path := range orig.Autoloads {
			dup.Autoloads[name] = path
		}
		for name, private := range orig.PrivateConstants {
			dup.PrivateConstants[name] = private
		}
		for name, classVar := range orig.ClassVars {
			dup.ClassVars[name] = classVar
		}
		for name, ivar := range orig.InstanceVars {
			if name == "@__rgo_singleton_instance" {
				continue
			}
			dup.InstanceVars[name] = ivar
		}
		dup.IncludedModules = append([]*object.Module{}, orig.IncludedModules...)
		dup.PrependedModules = append([]*object.Module{}, orig.PrependedModules...)
		dup.ClassVarOrder = append([]string{}, orig.ClassVarOrder...)
		result := &object.EmeraldValue{Type: object.ValueClass, Data: dup, Class: R.Classes["Class"]}
		dup.SingletonClass = cloneSingletonClass(orig.SingletonClass, result)
		return result
	}
	return receiver
}

func methodClone(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver == nil {
		return R.NilVal
	}
	frozen, explicitFreeze, keywordHash, errVal := cloneFreezeOptions(receiver, args...)
	if errVal != nil {
		return errVal
	}
	if classInheritsFrom(receiverEffectiveClass(receiver), R.Classes["Numeric"]) {
		if explicitFreeze && !frozen {
			return NewArgumentError("can't unfreeze Numeric")
		}
		return receiver
	}
	if receiver.Type == object.ValueString {
		result := duplicateStringValue(receiver, false, true)
		if initResult := callInitializeClone(result, receiver, explicitFreeze, keywordHash); initResult != nil {
			return initResult
		}
		result.Frozen = frozen
		return result
	}
	if receiver.Type == object.ValueProc {
		result := duplicateProcValue(receiver, false)
		if initResult := callInitializeClone(result, receiver, explicitFreeze, keywordHash); initResult != nil {
			return initResult
		}
		result.Frozen = frozen
		return result
	}
	if receiver.Type != object.ValueObject {
		if receiver == envObject {
			return typeError("Cannot clone ENV, use ENV.to_h to get a copy of ENV as a hash")
		}
		result := methodDup(receiver, args...)
		if result != nil {
			result.Frozen = frozen
		}
		return result
	}
	orig, ok := receiver.Data.(*object.Object)
	if !ok {
		switch data := receiver.Data.(type) {
		case *processStatusData:
			cloned := *data
			result := &object.EmeraldValue{Type: object.ValueObject, Data: &cloned, Class: receiver.Class}
			if initResult := callInitializeClone(result, receiver, explicitFreeze, keywordHash); initResult != nil {
				return initResult
			}
			result.Frozen = frozen
			return result
		default:
			result := &object.EmeraldValue{Type: object.ValueObject, Data: data, Class: receiver.Class}
			if initResult := callInitializeClone(result, receiver, explicitFreeze, keywordHash); initResult != nil {
				return initResult
			}
			result.Frozen = frozen
			return result
		}
	}
	clone := object.NewObject(orig.Class)
	clone.StructValues = append([]*object.EmeraldValue(nil), orig.StructValues...)
	for name, value := range orig.InstanceVars {
		clone.InstanceVars[name] = value
	}
	for name, value := range orig.ClassVars {
		clone.ClassVars[name] = value
	}
	for name, method := range orig.SingletonMethods {
		clone.SingletonMethods[name] = method
	}
	result := &object.EmeraldValue{Type: object.ValueObject, Data: clone, Class: receiver.Class}
	clone.SingletonClass = cloneSingletonClass(orig.SingletonClass, result)
	if initResult := callInitializeClone(result, receiver, explicitFreeze, keywordHash); initResult != nil {
		return initResult
	}
	result.Frozen = frozen
	return result
}

func duplicateStringValue(receiver *object.EmeraldValue, frozen, copySingleton bool) *object.EmeraldValue {
	duplicate := *receiver
	duplicate.Frozen = frozen
	result := &duplicate
	SetStringEncoding(result, stringEncodingName(receiver))
	if payload, ok := packedPointerStrings[receiver]; ok {
		packedPointerStrings[result] = payload
	}
	if variables := auxiliaryInstanceVars[receiver]; len(variables) > 0 {
		copyVariables := make(map[string]*object.EmeraldValue, len(variables))
		for name, value := range variables {
			copyVariables[name] = value
		}
		auxiliaryInstanceVars[result] = copyVariables
	}
	if copySingleton {
		if singleton := existingSingletonClass(receiver); singleton != nil {
			attachedSingletonClasses[result] = cloneSingletonClass(singleton, result)
		}
	}
	return result
}

func duplicateProcValue(receiver *object.EmeraldValue, frozen bool) *object.EmeraldValue {
	source := receiver.Data.(*object.Proc)
	copyData := *source
	if copyData.Origin == nil {
		copyData.Origin = source
	}
	copyData.InstanceVars = make(map[string]*object.EmeraldValue, len(source.InstanceVars))
	for name, value := range source.InstanceVars {
		copyData.InstanceVars[name] = value
	}
	result := &object.EmeraldValue{Type: object.ValueProc, Data: &copyData, Class: receiver.Class, Frozen: frozen}
	if finalizers := objectSpaceFinalizers[receiver]; len(finalizers) > 0 {
		objectSpaceFinalizers[result] = append([]*object.EmeraldValue(nil), finalizers...)
	}
	return result
}

func callStringInitializeCopy(copy, original *object.EmeraldValue) *object.EmeraldValue {
	if CallMethodBypass == nil || !receiverHasCallableMethod(copy, "initialize_copy") {
		return nil
	}
	result := CallMethodBypass(copy, "initialize_copy", original)
	if result != nil && result.Type == object.ValueException {
		return result
	}
	return nil
}

func cloneRHash(source *object.RHash) *object.RHash {
	clone := &object.RHash{Pairs: make(map[*object.EmeraldValue]*object.EmeraldValue), Keys: []*object.EmeraldValue{}, Hashes: make(map[*object.EmeraldValue]int64), InstanceVars: make(map[string]*object.EmeraldValue)}
	if source == nil {
		return clone
	}
	for key, value := range source.Pairs {
		clone.Pairs[key] = value
	}
	for key, code := range source.Hashes {
		clone.Hashes[key] = code
	}
	clone.Keys = append(clone.Keys, source.Keys...)
	clone.Default = source.Default
	clone.DefaultProc = source.DefaultProc
	clone.CompareByIdentity = source.CompareByIdentity
	for name, value := range source.InstanceVars {
		clone.InstanceVars[name] = value
	}
	return clone
}

func cloneFreezeOptions(receiver *object.EmeraldValue, args ...*object.EmeraldValue) (bool, bool, *object.EmeraldValue, *object.EmeraldValue) {
	if len(args) == 0 {
		return receiver != nil && receiver.Frozen, false, nil, nil
	}
	if len(args) != 1 || args[0] == nil || args[0].Type != object.ValueHash || !Ruby2KeywordHash(args[0]) {
		return false, false, nil, NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 0)", len(args)))
	}
	kwargs := valueToHashMap(args[0])
	var freezeValue *object.EmeraldValue
	found := false
	for key, value := range kwargs {
		if specName(key) == "freeze" {
			freezeValue = value
			found = true
			continue
		}
		return false, false, nil, NewArgumentError("unknown keyword: " + specName(key))
	}
	if !found || freezeValue == nil || freezeValue.Type == object.ValueNil {
		return receiver != nil && receiver.Frozen, found, args[0], nil
	}
	if freezeValue == R.TrueVal || (freezeValue.Type == object.ValueBool && freezeValue.Data == true) {
		return true, true, args[0], nil
	}
	if freezeValue == R.FalseVal || (freezeValue.Type == object.ValueBool && freezeValue.Data == false) {
		return false, true, args[0], nil
	}
	return false, false, nil, NewArgumentError("unexpected value for freeze: " + freezeValue.TypeName())
}

func callInitializeClone(clone, original *object.EmeraldValue, explicitFreeze bool, keywordHash *object.EmeraldValue) *object.EmeraldValue {
	if CallMethod == nil || !receiverHasCallableMethod(clone, "initialize_clone") {
		if receiverHasCallableMethod(clone, "initialize_copy") {
			call := CallMethod
			if CallMethodBypass != nil {
				call = CallMethodBypass
			}
			result := call(clone, "initialize_copy", original)
			if result != nil && result.Type == object.ValueException {
				return result
			}
		}
		return nil
	}
	args := []*object.EmeraldValue{original}
	if explicitFreeze && keywordHash != nil {
		args = append(args, keywordHash)
	}
	call := CallMethod
	if CallMethodBypass != nil {
		call = CallMethodBypass
	}
	result := call(clone, "initialize_clone", args...)
	if result != nil && result.Type == object.ValueException {
		return result
	}
	return nil
}

func moduleConstMissing(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	name := ""
	if len(args) > 0 {
		name = specName(args[0])
		if name == "" && args[0].Type == object.ValueString {
			name = args[0].Data.(string)
		}
	}
	prefix := ""
	switch receiver.Type {
	case object.ValueClass:
		className := classToS(receiver.Data.(*object.Class))
		if className != "Object" {
			prefix = className + "::"
		}
	case object.ValueModule:
		moduleName := moduleToS(receiver.Data.(*object.Module))
		if moduleName != "" {
			prefix = moduleName + "::"
		}
	}
	return NewNameErrorWithDetails("uninitialized constant "+prefix+name, receiver, name)
}

func moduleAutoload(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) < 2 {
		return NewArgumentError("wrong number of arguments")
	}
	if receiver != nil && receiver.Frozen {
		return frozenError("can't modify frozen class/module")
	}
	name, errVal := constNameFromValue(args[0])
	if errVal != nil {
		return errVal
	}
	if !validSimpleConstantName(name) {
		return NewNameError("wrong constant name " + name)
	}
	path, errVal := autoloadPathFromValue(args[1])
	if errVal != nil {
		return errVal
	}
	if path == "" {
		return NewArgumentError("empty file name")
	}
	if featureRequired(path) || loadingFeatures[path] {
		return R.NilVal
	}
	setAutoload(receiver, name, path)
	RecordConstantLocation(receiver, name, true)
	if result := NotifyConstAdded(receiver, name); result != nil && result.Type == object.ValueException {
		return result
	}
	return R.NilVal
}

func moduleAutoloadRelative(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return autoloadRelativeOn(receiver, args...)
}

func builtinAutoload(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return moduleAutoload(kernelAutoloadTarget(), args...)
}

func builtinAutoloadPredicate(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return moduleAutoloadPredicate(kernelAutoloadTarget(), args...)
}

func builtinAutoloadRelative(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return autoloadRelativeOn(kernelAutoloadTarget(), args...)
}

func kernelAutoloadTarget() *object.EmeraldValue {
	if CurrentFrameBinding != nil {
		if binding := CurrentFrameBinding(); binding != nil {
			for i := len(binding.ClassStack) - 1; i >= 0; i-- {
				target := binding.ClassStack[i]
				if i == len(binding.ClassStack)-1 && autoloadDynamicSingletonContext(target, binding.Self) {
					continue
				}
				if target != nil && (target.Type == object.ValueClass || target.Type == object.ValueModule) {
					return target
				}
			}
		}
	}
	return objectClassValue()
}

func autoloadDynamicSingletonContext(target, receiver *object.EmeraldValue) bool {
	if target == nil || receiver == nil || target.Type != object.ValueClass {
		return false
	}
	class, _ := target.Data.(*object.Class)
	if class == nil || !class.IsSingleton || class.SingletonOwner == nil {
		return false
	}
	owner := class.SingletonOwner
	return owner == receiver || owner.Type == receiver.Type && owner.Data == receiver.Data
}

func autoloadRelativeOn(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) < 2 {
		return NewArgumentError("wrong number of arguments")
	}
	if receiver != nil && receiver.Frozen {
		return frozenError("can't modify frozen class/module")
	}
	name, errVal := constNameFromValue(args[0])
	if errVal != nil {
		return errVal
	}
	if !validSimpleConstantName(name) {
		return NewNameError("wrong constant name " + name)
	}
	path, errVal := autoloadRelativePathFromValue(args[1])
	if errVal != nil {
		return errVal
	}
	if path == "" {
		return NewArgumentError("empty file name")
	}
	sourcePath := autoloadRelativeSourcePath()
	if sourcePath == "" {
		return newRuntimeException(R.Classes["LoadError"], "autoload_relative called without file context")
	}
	normalizedArg := filepath.FromSlash(strings.ReplaceAll(path, "\\", "/"))
	resolvedPath := normalizedArg
	if !filepath.IsAbs(normalizedArg) {
		resolvedPath = filepath.Join(filepath.Dir(sourcePath), normalizedArg)
	}
	resolvedPath = filepath.Clean(resolvedPath)
	if featureRequired(resolvedPath) || loadingFeatures[resolvedPath] {
		return R.NilVal
	}
	setAutoload(receiver, name, resolvedPath)
	RecordConstantLocation(receiver, name, true)
	return R.NilVal
}

func objectClassValue() *object.EmeraldValue {
	return &object.EmeraldValue{Type: object.ValueClass, Data: R.Classes["Object"], Class: R.Classes["Class"], Frozen: R.Classes["Object"].Frozen}
}

func autoloadRelativeSourcePath() string {
	path := ""
	if CurrentFrameBinding != nil {
		if binding := CurrentFrameBinding(); binding != nil && binding.Path != "" {
			path = binding.Path
		}
	}
	if path == "" {
		path = CurrentSpecFile
	}
	path = strings.TrimSpace(path)
	if path == "" || strings.HasPrefix(path, "(eval") {
		return ""
	}
	return filepath.Clean(filepath.FromSlash(strings.ReplaceAll(path, "\\", "/")))
}

func autoloadRelativePathFromValue(value *object.EmeraldValue) (string, *object.EmeraldValue) {
	if value == nil || value.Type == object.ValueNil {
		return "", typeError("no implicit conversion into String")
	}
	if value.Type == object.ValueString {
		return value.Data.(string), nil
	}
	if CallMethod != nil && receiverHasCallableMethod(value, "to_path") {
		coerced := CallMethod(value, "to_path")
		if coerced != nil && coerced.Type == object.ValueException {
			return "", coerced
		}
		if coerced != nil && coerced.Type == object.ValueString {
			return coerced.Data.(string), nil
		}
		return "", typeError("no implicit conversion into String")
	}
	if CallMethod != nil && receiverHasCallableMethod(value, "to_str") {
		coerced := CallMethod(value, "to_str")
		if coerced != nil && coerced.Type == object.ValueException {
			return "", coerced
		}
		if coerced != nil && coerced.Type == object.ValueString {
			return coerced.Data.(string), nil
		}
	}
	return "", typeError("no implicit conversion into String")
}

func moduleAutoloadPredicate(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 0 {
		return R.NilVal
	}
	name, errVal := constNameFromValue(args[0])
	if errVal != nil {
		return errVal
	}
	inherit := true
	if len(args) > 1 {
		inherit = args[1] != nil && args[1].IsTruthy()
	}
	if path, ok := lookupAutoload(receiver, name, inherit); ok {
		if FeatureLoadingByCurrentThread(path) {
			return R.NilVal
		}
		return rubyString(path)
	}
	return R.NilVal
}

func autoloadPathFromValue(value *object.EmeraldValue) (string, *object.EmeraldValue) {
	if value == nil {
		return "", typeError("no implicit conversion of nil into String")
	}
	if value.Type == object.ValueString {
		return value.Data.(string), nil
	}
	if CallMethod == nil || !receiverHasCallableMethod(value, "to_path") {
		return "", typeError("no implicit conversion into String")
	}
	coerced := CallMethod(value, "to_path")
	if coerced != nil && coerced.Type == object.ValueException {
		return "", coerced
	}
	if coerced == nil || coerced.Type != object.ValueString {
		return "", typeError("no implicit conversion into String")
	}
	return coerced.Data.(string), nil
}

func setAutoload(receiver *object.EmeraldValue, name, path string) {
	clearFormerAutoload(receiver, name)
	switch receiver.Type {
	case object.ValueClass:
		receiver.Data.(*object.Class).Autoloads[name] = path
	case object.ValueModule:
		receiver.Data.(*object.Module).Autoloads[name] = path
	}
	autoloadRegistrations = append(autoloadRegistrations, autoloadRegistration{receiver: receiver, name: name, path: path})
}

func removeAutoloadsForLoadedFeature(path string) {
	resolved := normalizedAutoloadFeature(path)
	kept := autoloadRegistrations[:0]
	for _, registration := range autoloadRegistrations {
		current, ok := DirectAutoloadPath(registration.receiver, registration.name)
		if !ok {
			continue
		}
		if normalizedAutoloadFeature(current) == resolved {
			CompleteAutoload(registration.receiver, registration.name)
			continue
		}
		kept = append(kept, registration)
	}
	autoloadRegistrations = kept
}

func CompleteAutoload(receiver *object.EmeraldValue, name string) {
	if receiver == nil {
		return
	}
	hasConstant := false
	switch receiver.Type {
	case object.ValueClass:
		_, hasConstant = receiver.Data.(*object.Class).Constants[name]
	case object.ValueModule:
		_, hasConstant = receiver.Data.(*object.Module).Constants[name]
	}
	RemoveAutoload(receiver, name)
	if hasConstant {
		clearFormerAutoload(receiver, name)
	} else {
		key := receiver.Data
		if formerAutoloadNames[key] == nil {
			formerAutoloadNames[key] = make(map[string]bool)
		}
		formerAutoloadNames[key][name] = true
	}
}

func ClearFormerAutoload(receiver *object.EmeraldValue, name string) {
	clearFormerAutoload(receiver, name)
}

func clearFormerAutoload(receiver *object.EmeraldValue, name string) {
	if receiver != nil && formerAutoloadNames[receiver.Data] != nil {
		delete(formerAutoloadNames[receiver.Data], name)
	}
}

func formerAutoload(receiver *object.EmeraldValue, name string) bool {
	return receiver != nil && formerAutoloadNames[receiver.Data] != nil && formerAutoloadNames[receiver.Data][name]
}

func normalizedAutoloadFeature(path string) string {
	if ResolveRequirePath != nil {
		if resolved := ResolveRequirePath(path); resolved != "" {
			path = resolved
		}
	}
	return filepath.Clean(path)
}

func lookupAutoload(receiver *object.EmeraldValue, name string, inherit bool) (string, bool) {
	switch receiver.Type {
	case object.ValueClass:
		for class := receiver.Data.(*object.Class); class != nil; class = class.SuperClass {
			if path, ok := class.Autoloads[name]; ok {
				return path, true
			}
			if !inherit {
				break
			}
			seen := make(map[*object.Module]bool)
			for i := len(class.IncludedModules) - 1; i >= 0; i-- {
				if path, ok := lookupAutoloadInModule(class.IncludedModules[i], name, seen); ok {
					return path, true
				}
			}
		}
	case object.ValueModule:
		module := receiver.Data.(*object.Module)
		if path, ok := module.Autoloads[name]; ok || !inherit {
			return path, ok
		}
		return lookupAutoloadInModule(module, name, make(map[*object.Module]bool))
	}
	return "", false
}

func lookupAutoloadInModule(module *object.Module, name string, seen map[*object.Module]bool) (string, bool) {
	if module == nil || seen[module] {
		return "", false
	}
	seen[module] = true
	if path, ok := module.Autoloads[name]; ok {
		return path, true
	}
	for i := len(module.IncludedModules) - 1; i >= 0; i-- {
		if path, ok := lookupAutoloadInModule(module.IncludedModules[i], name, seen); ok {
			return path, true
		}
	}
	return lookupAutoloadInModule(module.Parent, name, seen)
}

func RemoveAutoload(receiver *object.EmeraldValue, name string) {
	switch receiver.Type {
	case object.ValueClass:
		class := receiver.Data.(*object.Class)
		delete(class.Autoloads, name)
		delete(class.AutoloadLocations, name)
	case object.ValueModule:
		module := receiver.Data.(*object.Module)
		delete(module.Autoloads, name)
		delete(module.AutoloadLocations, name)
	}
}

func DirectAutoloadPath(receiver *object.EmeraldValue, name string) (string, bool) {
	return lookupAutoload(receiver, name, false)
}

func AutoloadPath(receiver *object.EmeraldValue, name string, inherit bool) (string, bool) {
	return lookupAutoload(receiver, name, inherit)
}

func moduleConstSet(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) < 2 {
		return newRuntimeException(R.Classes["ArgumentError"], "wrong number of arguments")
	}
	if receiver != nil && receiver.Frozen {
		return frozenError("can't modify frozen class/module")
	}
	name, errVal := constNameFromValue(args[0])
	if errVal != nil {
		return errVal
	}
	if !validSimpleConstantName(name) {
		return NewNameError("wrong constant name " + name)
	}
	switch receiver.Type {
	case object.ValueClass:
		clearFormerAutoload(receiver, name)
		delete(receiver.Data.(*object.Class).Autoloads, name)
		receiver.Data.(*object.Class).DefineConstant(name, args[1])
	case object.ValueModule:
		clearFormerAutoload(receiver, name)
		delete(receiver.Data.(*object.Module).Autoloads, name)
		receiver.Data.(*object.Module).DefineConstant(name, args[1])
	default:
		return typeError("not a class/module")
	}
	AssignConstantName(receiver, name, args[1])
	if SetConstantName != nil {
		SetConstantName(receiver, name, args[1])
	}
	RecordConstantLocation(receiver, name, false)
	if result := NotifyConstAdded(receiver, name); result != nil && result.Type == object.ValueException {
		return result
	}
	return args[1]
}

func moduleRemoveConst(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 0 {
		return argumentError("wrong number of arguments")
	}
	name, errVal := constNameFromValue(args[0])
	if errVal != nil {
		return errVal
	}
	if !validSimpleConstantName(name) {
		return NewNameError("wrong constant name " + name)
	}
	switch receiver.Type {
	case object.ValueClass:
		class := receiver.Data.(*object.Class)
		if value, ok := class.Constants[name]; ok {
			delete(class.Constants, name)
			clearFormerAutoload(receiver, name)
			delete(class.Autoloads, name)
			delete(class.ConstantLocations, name)
			delete(class.AutoloadLocations, name)
			delete(class.PrivateConstants, name)
			delete(class.DeprecatedConstants, name)
			if RemoveConstantName != nil {
				RemoveConstantName(receiver, name)
			}
			return value
		}
		if _, ok := class.Autoloads[name]; ok {
			delete(class.Autoloads, name)
			delete(class.AutoloadLocations, name)
			if RemoveConstantName != nil {
				RemoveConstantName(receiver, name)
			}
			return R.NilVal
		}
		if formerAutoload(receiver, name) {
			clearFormerAutoload(receiver, name)
			return R.NilVal
		}
	case object.ValueModule:
		module := receiver.Data.(*object.Module)
		if value, ok := module.Constants[name]; ok {
			delete(module.Constants, name)
			clearFormerAutoload(receiver, name)
			delete(module.Autoloads, name)
			delete(module.ConstantLocations, name)
			delete(module.AutoloadLocations, name)
			delete(module.PrivateConstants, name)
			delete(module.DeprecatedConstants, name)
			if RemoveConstantName != nil {
				RemoveConstantName(receiver, name)
			}
			return value
		}
		if _, ok := module.Autoloads[name]; ok {
			delete(module.Autoloads, name)
			delete(module.AutoloadLocations, name)
			if RemoveConstantName != nil {
				RemoveConstantName(receiver, name)
			}
			return R.NilVal
		}
		if formerAutoload(receiver, name) {
			clearFormerAutoload(receiver, name)
			return R.NilVal
		}
	default:
		return typeError("not a class/module")
	}
	return NewNameError("constant " + name + " not defined")
}

func constNameFromValue(value *object.EmeraldValue) (string, *object.EmeraldValue) {
	if value == nil {
		return "", typeError("no implicit conversion into String")
	}
	switch value.Type {
	case object.ValueString, object.ValueSymbol:
		if name, ok := value.Data.(string); ok {
			return name, nil
		}
		return "", nil
	default:
		if CallMethod == nil {
			return "", typeError("no implicit conversion into String")
		}
		if !receiverHasCallableMethod(value, "to_str") {
			return "", typeError("no implicit conversion into String")
		}
		coerced := CallMethod(value, "to_str")
		if coerced != nil && coerced.Type == object.ValueException {
			return "", coerced
		}
		if coerced == nil || coerced.Type != object.ValueString {
			return "", typeError("no implicit conversion into String")
		}
		return coerced.Data.(string), nil
	}
}

func validSimpleConstantName(name string) bool {
	if name == "" || strings.Contains(name, "::") {
		return false
	}
	runes := []rune(name)
	if len(runes) == 0 || !unicode.IsUpper(runes[0]) {
		return false
	}
	for _, r := range runes[1:] {
		if unicode.IsLetter(r) || unicode.IsDigit(r) || r == '_' {
			continue
		}
		return false
	}
	return true
}

func AssignConstantName(container *object.EmeraldValue, constName string, value *object.EmeraldValue) {
	assignConstantName(container, constName, value, map[*object.EmeraldValue]bool{})
}

func RecordConstantLocation(container *object.EmeraldValue, name string, autoload bool) {
	if container == nil || name == "" {
		return
	}
	path := CurrentSpecFile
	line := int64(1)
	if CurrentFrameBinding != nil {
		if binding := CurrentFrameBinding(); binding != nil {
			if binding.Path != "" {
				path = binding.Path
			}
			if binding.Line > 0 {
				line = binding.Line
			}
		}
	}
	if path == "" {
		return
	}
	location := object.ConstantLocation{Path: path, Line: line}
	switch container.Type {
	case object.ValueClass:
		class := container.Data.(*object.Class)
		if class.ConstantLocations == nil {
			class.ConstantLocations = make(map[string]object.ConstantLocation)
		}
		if class.AutoloadLocations == nil {
			class.AutoloadLocations = make(map[string]object.ConstantLocation)
		}
		if autoload {
			class.AutoloadLocations[name] = location
		} else {
			class.ConstantLocations[name] = location
			delete(class.AutoloadLocations, name)
		}
	case object.ValueModule:
		module := container.Data.(*object.Module)
		if module.ConstantLocations == nil {
			module.ConstantLocations = make(map[string]object.ConstantLocation)
		}
		if module.AutoloadLocations == nil {
			module.AutoloadLocations = make(map[string]object.ConstantLocation)
		}
		if autoload {
			module.AutoloadLocations[name] = location
		} else {
			module.ConstantLocations[name] = location
			delete(module.AutoloadLocations, name)
		}
	}
}

func assignConstantName(container *object.EmeraldValue, constName string, value *object.EmeraldValue, visited map[*object.EmeraldValue]bool) {
	if value == nil {
		return
	}
	prefix := ""
	if container != nil {
		switch container.Type {
		case object.ValueClass:
			class := container.Data.(*object.Class)
			if class != nil && class.Name != "Object" {
				prefix = classToS(class)
			}
		case object.ValueModule:
			prefix = moduleToS(container.Data.(*object.Module))
		}
	}
	fullName := constName
	if prefix != "" {
		fullName = prefix + "::" + constName
	}
	assignValueName(value, fullName, visited)
}

func assignValueName(value *object.EmeraldValue, name string, visited map[*object.EmeraldValue]bool) {
	if value == nil || visited[value] {
		return
	}
	visited[value] = true
	oldName := ""
	switch value.Type {
	case object.ValueClass:
		cls := value.Data.(*object.Class)
		if cls.IsSingleton {
			return
		}
		oldName = cls.Name
		oldAnonymous := oldName == "" || strings.HasPrefix(oldName, "#<")
		shouldAssign := cls.Name == "" || (strings.HasPrefix(cls.Name, "#<") && (cls.NameValue == nil || nameHasPermanentRoot(name))) || (cls.TemporaryName && nameHasPermanentRoot(name)) || (!cls.TemporaryName && !strings.Contains(cls.Name, "::") && strings.Contains(name, "::"))
		if shouldAssign {
			cls.Name = name
			cls.NameValue = nil
			cls.TemporaryName = false
		}
		for childName, child := range cls.Constants {
			if (oldAnonymous || shouldAssign) && childName != "" {
				assignConstantName(value, childName, child, visited)
			}
		}
	case object.ValueModule:
		mod := value.Data.(*object.Module)
		oldName = mod.Name
		oldAnonymous := oldName == "" || strings.HasPrefix(oldName, "#<")
		shouldAssign := mod.Name == "" || (strings.HasPrefix(mod.Name, "#<") && (mod.NameValue == nil || nameHasPermanentRoot(name))) || (mod.TemporaryName && nameHasPermanentRoot(name)) || (!mod.TemporaryName && !strings.Contains(mod.Name, "::") && strings.Contains(name, "::"))
		if shouldAssign {
			mod.Name = name
			mod.NameValue = nil
			mod.TemporaryName = false
		}
		for childName, child := range mod.Constants {
			if (oldAnonymous || shouldAssign) && childName != "" {
				assignConstantName(value, childName, child, visited)
			}
		}
	}
}

func nameHasPermanentRoot(name string) bool {
	if strings.HasPrefix(name, "#<") || name == "" {
		return false
	}
	root := strings.Split(name, "::")[0]
	return validSimpleConstantName(root)
}

func updateNestedTemporaryNames(container *object.EmeraldValue) {
	if container == nil {
		return
	}
	var constants map[string]*object.EmeraldValue
	switch container.Type {
	case object.ValueClass:
		constants = container.Data.(*object.Class).Constants
	case object.ValueModule:
		constants = container.Data.(*object.Module).Constants
	default:
		return
	}
	for name, value := range constants {
		if value == nil {
			continue
		}
		switch value.Type {
		case object.ValueClass:
			cls := value.Data.(*object.Class)
			if cls.TemporaryName || cls.Name == "" || strings.HasPrefix(cls.Name, "#<") {
				assignConstantName(container, name, value, map[*object.EmeraldValue]bool{})
			}
		case object.ValueModule:
			mod := value.Data.(*object.Module)
			if mod.TemporaryName || mod.Name == "" || strings.HasPrefix(mod.Name, "#<") {
				assignConstantName(container, name, value, map[*object.EmeraldValue]bool{})
			}
		}
	}
}

func clearNestedTemporaryNames(container *object.EmeraldValue) {
	if container == nil {
		return
	}
	var constants map[string]*object.EmeraldValue
	switch container.Type {
	case object.ValueClass:
		constants = container.Data.(*object.Class).Constants
	case object.ValueModule:
		constants = container.Data.(*object.Module).Constants
	default:
		return
	}
	for _, value := range constants {
		switch value.Type {
		case object.ValueClass:
			cls := value.Data.(*object.Class)
			if !nameHasPermanentRoot(cls.Name) {
				cls.Name = ""
				cls.TemporaryName = false
				cls.NameValue = nil
				clearNestedTemporaryNames(value)
			}
		case object.ValueModule:
			mod := value.Data.(*object.Module)
			if !nameHasPermanentRoot(mod.Name) {
				mod.Name = ""
				mod.TemporaryName = false
				mod.NameValue = nil
				clearNestedTemporaryNames(value)
			}
		}
	}
}

func moduleConstGet(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 0 {
		return newRuntimeException(R.Classes["ArgumentError"], "wrong number of arguments")
	}
	name, errVal := constNameFromValue(args[0])
	if errVal != nil {
		return errVal
	}
	if !validConstantPathName(name) || (args[0].Type == object.ValueSymbol && strings.Contains(name, "::")) {
		return NewNameError("wrong constant name " + name)
	}
	inherit := true
	if len(args) > 1 {
		inherit = args[1] != nil && args[1].IsTruthy()
	}
	parts := strings.Split(strings.TrimPrefix(name, "::"), "::")
	current := receiver
	if strings.HasPrefix(name, "::") {
		current = objectClassValue()
	}
	for index, part := range parts {
		allowTopLevel := index == 0 && !strings.HasPrefix(name, "::")
		value, ok, lookupErr := lookupConstGetValue(current, part, inherit && index == 0, allowTopLevel)
		if lookupErr != nil {
			return lookupErr
		}
		if !ok {
			if CallMethodBypass != nil {
				if result := CallMethodBypass(current, "const_missing", &object.EmeraldValue{Type: object.ValueSymbol, Data: part, Class: R.Classes["Symbol"]}); result != nil {
					return result
				}
			}
			return NewNameErrorWithDetails("uninitialized constant "+part, current, part)
		}
		if index == len(parts)-1 {
			return value
		}
		if value == nil || (value.Type != object.ValueClass && value.Type != object.ValueModule) {
			return typeError(part + " does not refer to class/module")
		}
		current = value
	}
	return R.NilVal
}

func lookupConstGetValue(receiver *object.EmeraldValue, name string, inherit, allowTopLevel bool) (*object.EmeraldValue, bool, *object.EmeraldValue) {
	if value, ok := lookupConstValue(receiver, name, inherit); ok {
		return value, true, nil
	}
	if path, ok := lookupAutoload(receiver, name, inherit); ok && CallMethod != nil {
		autoloadRequireDepth++
		result := CallMethod(R.Main, "require", rubyString(path))
		autoloadRequireDepth--
		if result != nil && result.Type == object.ValueException {
			return nil, false, result
		}
		if value, found := lookupConstValue(receiver, name, inherit); found {
			CompleteAutoload(receiver, name)
			return value, true, nil
		}
		CompleteAutoload(receiver, name)
	}
	objectReceiver := objectClassValue()
	if allowTopLevel && inherit && receiver != nil && receiver.Data != objectReceiver.Data {
		if value, ok, errVal := lookupConstGetValue(objectReceiver, name, true, false); ok || errVal != nil {
			return value, ok, errVal
		}
	}
	if receiver != nil && receiver.Type == object.ValueClass && receiver.Data == R.Classes["Object"] && GetConstantName != nil {
		if value := GetConstantName(name); value != nil {
			return value, true, nil
		}
	}
	return nil, false, nil
}

func lookupConstValue(receiver *object.EmeraldValue, name string, inherit bool) (*object.EmeraldValue, bool) {
	if receiver == nil {
		return nil, false
	}
	switch receiver.Type {
	case object.ValueClass:
		for class := receiver.Data.(*object.Class); class != nil; class = class.SuperClass {
			if value, ok := class.Constants[name]; ok {
				return value, true
			}
			if inherit {
				if value, ok := lookupConstInModules(class.IncludedModules, name, map[*object.Module]bool{}); ok {
					return value, true
				}
			} else {
				break
			}
		}
	case object.ValueModule:
		module := receiver.Data.(*object.Module)
		if value, ok := module.Constants[name]; ok {
			return value, true
		}
		if inherit {
			return lookupConstInModules(module.IncludedModules, name, map[*object.Module]bool{})
		}
	}
	return nil, false
}

func lookupConstInModules(modules []*object.Module, name string, seen map[*object.Module]bool) (*object.EmeraldValue, bool) {
	for index := len(modules) - 1; index >= 0; index-- {
		module := modules[index]
		if module == nil || seen[module] {
			continue
		}
		seen[module] = true
		if value, ok := module.Constants[name]; ok {
			return value, true
		}
		if value, ok := lookupConstInModules(module.IncludedModules, name, seen); ok {
			return value, true
		}
	}
	return nil, false
}

func moduleConstSourceLocation(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 0 {
		return NewArgumentError("wrong number of arguments")
	}
	name, errVal := constNameFromValue(args[0])
	if errVal != nil {
		return errVal
	}
	if !validConstantPathName(name) || (args[0].Type == object.ValueSymbol && strings.Contains(name, "::")) {
		return NewNameError("wrong constant name " + name)
	}
	inherit := true
	if len(args) > 1 {
		inherit = args[1] != nil && args[1].IsTruthy()
	}
	absolute := strings.HasPrefix(name, "::")
	parts := strings.Split(strings.TrimPrefix(name, "::"), "::")
	current := receiver
	if absolute {
		current = objectClassValue()
	}
	for index, part := range parts {
		allowTopLevel := index == 0 && !absolute
		location, value, found := lookupConstLocation(current, part, inherit && index == 0, allowTopLevel)
		if !found {
			return R.NilVal
		}
		if index == len(parts)-1 {
			if location.Path == "" {
				return &object.EmeraldValue{Type: object.ValueArray, Data: []*object.EmeraldValue{}, Class: R.Classes["Array"]}
			}
			return sourceLocationArray(location.Path, location.Line)
		}
		if value == nil || (value.Type != object.ValueClass && value.Type != object.ValueModule) {
			return R.NilVal
		}
		current = value
	}
	return R.NilVal
}

func lookupConstLocation(receiver *object.EmeraldValue, name string, inherit, allowTopLevel bool) (object.ConstantLocation, *object.EmeraldValue, bool) {
	if receiver == nil {
		return object.ConstantLocation{}, nil, false
	}
	switch receiver.Type {
	case object.ValueClass:
		for class := receiver.Data.(*object.Class); class != nil; class = class.SuperClass {
			if value, ok := class.Constants[name]; ok {
				return class.ConstantLocations[name], value, true
			}
			if _, ok := class.Autoloads[name]; ok {
				return class.AutoloadLocations[name], nil, true
			}
			if inherit {
				if location, value, ok := lookupConstLocationInModules(class.IncludedModules, name, map[*object.Module]bool{}); ok {
					return location, value, true
				}
			} else {
				break
			}
		}
	case object.ValueModule:
		module := receiver.Data.(*object.Module)
		if value, ok := module.Constants[name]; ok {
			return module.ConstantLocations[name], value, true
		}
		if _, ok := module.Autoloads[name]; ok {
			return module.AutoloadLocations[name], nil, true
		}
		if inherit {
			if location, value, ok := lookupConstLocationInModules(module.IncludedModules, name, map[*object.Module]bool{}); ok {
				return location, value, true
			}
		}
	}
	objectReceiver := objectClassValue()
	if allowTopLevel && inherit && receiver.Data != objectReceiver.Data {
		return lookupConstLocation(objectReceiver, name, true, false)
	}
	if receiver.Type == object.ValueClass && receiver.Data == R.Classes["Object"] && GetConstantName != nil {
		if value := GetConstantName(name); value != nil {
			return object.ConstantLocation{}, value, true
		}
	}
	return object.ConstantLocation{}, nil, false
}

func lookupConstLocationInModules(modules []*object.Module, name string, seen map[*object.Module]bool) (object.ConstantLocation, *object.EmeraldValue, bool) {
	for index := len(modules) - 1; index >= 0; index-- {
		module := modules[index]
		if module == nil || seen[module] {
			continue
		}
		seen[module] = true
		if value, ok := module.Constants[name]; ok {
			return module.ConstantLocations[name], value, true
		}
		if _, ok := module.Autoloads[name]; ok {
			return module.AutoloadLocations[name], nil, true
		}
		if location, value, ok := lookupConstLocationInModules(module.IncludedModules, name, seen); ok {
			return location, value, true
		}
	}
	return object.ConstantLocation{}, nil, false
}

func moduleConstDefined(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 0 {
		return R.FalseVal
	}
	name, errVal := constNameFromValue(args[0])
	if errVal != nil {
		return errVal
	}
	if !validConstantPathName(name) {
		return NewNameError("wrong constant name " + name)
	}
	inherit := true
	if len(args) > 1 {
		inherit = args[1] != nil && args[1].IsTruthy()
	}
	if strings.Contains(name, "::") {
		return boolValue(scopedConstantDefined(receiver, name, inherit))
	}
	if _, found := lookupConstValue(receiver, name, inherit); found || autoloadDefined(receiver, name, inherit) {
		return R.TrueVal
	}
	if inherit && receiver != nil && receiver.Type == object.ValueModule {
		objectReceiver := objectClassValue()
		if _, found := lookupConstValue(objectReceiver, name, true); found || autoloadDefined(objectReceiver, name, true) {
			return R.TrueVal
		}
	}
	return R.FalseVal
}

func scopedConstantDefined(receiver *object.EmeraldValue, name string, inherit bool) bool {
	absolute := strings.HasPrefix(name, "::")
	parts := strings.Split(strings.TrimPrefix(name, "::"), "::")
	current := receiver
	for index, part := range parts {
		var value *object.EmeraldValue
		var ok bool
		if absolute && index == 0 {
			if GetConstantName != nil {
				value = GetConstantName(part)
				ok = value != nil
			}
		} else {
			value, ok = lookupDefinedConstantValue(current, part, inherit)
		}
		if !ok {
			return false
		}
		if index == len(parts)-1 {
			return true
		}
		if value == nil || (value.Type != object.ValueClass && value.Type != object.ValueModule) {
			return false
		}
		current = value
	}
	return false
}

func lookupDefinedConstantValue(receiver *object.EmeraldValue, name string, inherit bool) (*object.EmeraldValue, bool) {
	if receiver == nil {
		return nil, false
	}
	switch receiver.Type {
	case object.ValueClass:
		for class := receiver.Data.(*object.Class); class != nil; class = class.SuperClass {
			if value, ok := class.Constants[name]; ok {
				return value, true
			}
			if !inherit {
				break
			}
		}
	case object.ValueModule:
		for module := receiver.Data.(*object.Module); module != nil; module = module.Parent {
			if value, ok := module.Constants[name]; ok {
				return value, true
			}
			if !inherit {
				break
			}
		}
	}
	return nil, false
}

func moduleConstants(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	inherit := true
	if len(args) > 0 {
		inherit = args[0] != nil && args[0].IsTruthy()
	}
	if len(args) == 0 && receiver != nil && receiver.Type == object.ValueClass {
		if class, ok := receiver.Data.(*object.Class); ok && class != nil && class.Name == "Module" {
			receiver = &object.EmeraldValue{Type: object.ValueClass, Data: R.Classes["Object"], Class: R.Classes["Class"]}
		}
	}
	names := map[string]bool{}
	collectConstants(receiver, names, inherit)
	values := make([]*object.EmeraldValue, 0, len(names))
	for name := range names {
		symbol := &object.EmeraldValue{Type: object.ValueSymbol, Data: name, Class: R.Classes["Symbol"]}
		if encoding := ConstantNameEncoding(receiver, name); encoding != "" {
			SetSymbolEncoding(symbol, encoding)
		}
		values = append(values, symbol)
	}
	sort.Slice(values, func(i, j int) bool {
		return values[i].Data.(string) < values[j].Data.(string)
	})
	return &object.EmeraldValue{Type: object.ValueArray, Data: values, Class: R.Classes["Array"]}
}

func constantDefined(receiver *object.EmeraldValue, name string, inherit bool) bool {
	switch receiver.Type {
	case object.ValueClass:
		for class := receiver.Data.(*object.Class); class != nil; class = class.SuperClass {
			if _, ok := class.Constants[name]; ok {
				return true
			}
			if !inherit {
				break
			}
		}
	case object.ValueModule:
		module := receiver.Data.(*object.Module)
		for module != nil {
			if _, ok := module.Constants[name]; ok {
				return true
			}
			if !inherit {
				break
			}
			module = module.Parent
		}
	}
	return false
}

func autoloadDefined(receiver *object.EmeraldValue, name string, inherit bool) bool {
	path, ok := lookupAutoload(receiver, name, inherit)
	return ok && !FeatureLoadingByCurrentThread(path)
}

func collectConstants(receiver *object.EmeraldValue, names map[string]bool, inherit bool) {
	switch receiver.Type {
	case object.ValueClass:
		start := receiver.Data.(*object.Class)
		for class := start; class != nil; class = class.SuperClass {
			if class.Name == "Object" && class != start {
				break
			}
			for name := range class.Constants {
				if !class.PrivateConstants[name] {
					names[name] = true
				}
			}
			for name := range class.Autoloads {
				names[name] = true
			}
			for name := range formerAutoloadNames[class] {
				names[name] = true
			}
			if inherit {
				collectIncludedModuleConstants(class.PrependedModules, names)
				collectIncludedModuleConstants(class.IncludedModules, names)
			}
			if !inherit {
				break
			}
		}
	case object.ValueModule:
		module := receiver.Data.(*object.Module)
		for module != nil {
			for name := range module.Constants {
				if !module.PrivateConstants[name] {
					names[name] = true
				}
			}
			for name := range module.Autoloads {
				names[name] = true
			}
			for name := range formerAutoloadNames[module] {
				names[name] = true
			}
			if inherit {
				collectIncludedModuleConstants(module.PrependedModules, names)
				collectIncludedModuleConstants(module.IncludedModules, names)
			}
			if !inherit {
				break
			}
			module = module.Parent
		}
	}
}

func collectIncludedModuleConstants(modules []*object.Module, names map[string]bool) {
	for _, module := range modules {
		if module == nil {
			continue
		}
		for name := range module.Constants {
			if !module.PrivateConstants[name] {
				names[name] = true
			}
		}
		for name := range module.Autoloads {
			names[name] = true
		}
		collectIncludedModuleConstants(module.PrependedModules, names)
		collectIncludedModuleConstants(module.IncludedModules, names)
	}
}

func modulePrivateConstant(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return setConstantVisibility(receiver, true, args...)
}

func modulePublicConstant(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return setConstantVisibility(receiver, false, args...)
}

func moduleDeprecateConstant(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	for _, arg := range args {
		name := specName(arg)
		if name == "" && arg.Type == object.ValueString {
			name = arg.Data.(string)
		}
		if name == "" || !constantDefinedDirectly(receiver, name) {
			return newRuntimeException(R.Classes["NameError"], "constant "+name+" not defined")
		}
		switch receiver.Type {
		case object.ValueClass:
			receiver.Data.(*object.Class).DeprecatedConstants[name] = true
		case object.ValueModule:
			receiver.Data.(*object.Module).DeprecatedConstants[name] = true
		default:
			return typeError("not a class/module")
		}
	}
	return receiver
}

func setConstantVisibility(receiver *object.EmeraldValue, private bool, args ...*object.EmeraldValue) *object.EmeraldValue {
	for _, arg := range args {
		name := specName(arg)
		if name == "" && arg.Type == object.ValueString {
			name = arg.Data.(string)
		}
		if name == "" || !constantDefinedDirectly(receiver, name) {
			return newRuntimeException(R.Classes["NameError"], "constant "+name+" not defined")
		}
		switch receiver.Type {
		case object.ValueClass:
			if private {
				receiver.Data.(*object.Class).PrivateConstants[name] = true
			} else {
				delete(receiver.Data.(*object.Class).PrivateConstants, name)
			}
		case object.ValueModule:
			if private {
				receiver.Data.(*object.Module).PrivateConstants[name] = true
			} else {
				delete(receiver.Data.(*object.Module).PrivateConstants, name)
			}
		}
	}
	return R.NilVal
}

func constantDefinedDirectly(receiver *object.EmeraldValue, name string) bool {
	switch receiver.Type {
	case object.ValueClass:
		class := receiver.Data.(*object.Class)
		if _, ok := class.Constants[name]; ok {
			return true
		}
		_, ok := class.Autoloads[name]
		return ok
	case object.ValueModule:
		module := receiver.Data.(*object.Module)
		if _, ok := module.Constants[name]; ok {
			return true
		}
		_, ok := module.Autoloads[name]
		return ok
	}
	return false
}

func attrNamesFromValues(args ...*object.EmeraldValue) ([]string, *object.EmeraldValue) {
	names := make([]string, 0, len(args))
	for _, arg := range args {
		if arg == nil {
			return nil, typeError("nil is not a symbol nor a string")
		}
		switch arg.Type {
		case object.ValueString, object.ValueSymbol:
			name := specName(arg)
			if name != "" {
				names = append(names, name)
			}
		default:
			if CallMethod == nil {
				return nil, typeError("no implicit conversion into String")
			}
			if !receiverHasCallableMethod(arg, "to_str") {
				return nil, typeError("no implicit conversion into String")
			}
			coerced := CallMethod(arg, "to_str")
			if coerced != nil && coerced.Type == object.ValueException {
				return nil, coerced
			}
			if coerced == nil || coerced.Type != object.ValueString {
				return nil, typeError("no implicit conversion into String")
			}
			names = append(names, coerced.Data.(string))
		}
	}
	return names, nil
}

func attrMethodNames(names []string, reader bool, writer bool) []string {
	methods := make([]string, 0, len(names)*2)
	for _, name := range names {
		if reader {
			methods = append(methods, name)
		}
		if writer {
			methods = append(methods, name+"=")
		}
	}
	return methods
}

func symbolArray(names ...string) *object.EmeraldValue {
	values := make([]*object.EmeraldValue, 0, len(names))
	for _, name := range names {
		values = append(values, &object.EmeraldValue{Type: object.ValueSymbol, Data: name, Class: R.Classes["Symbol"]})
	}
	return &object.EmeraldValue{Type: object.ValueArray, Data: values, Class: R.Classes["Array"]}
}

func moduleInstanceMethods(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver != nil && receiver.Type == object.ValueModule {
		module := receiver.Data.(*object.Module)
		if module.IsRefinement && module.RefinementTarget != nil {
			return moduleMethodsForVisibility(module.RefinementTarget, "", includeInheritedMethods(args...))
		}
	}
	return moduleMethodsForVisibility(receiver, "", includeInheritedMethods(args...))
}

func moduleUndefinedInstanceMethods(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	names := []string{}
	if receiver != nil {
		var methods map[string]*object.Method
		switch receiver.Type {
		case object.ValueClass:
			methods = receiver.Data.(*object.Class).Methods
		case object.ValueModule:
			methods = receiver.Data.(*object.Module).Methods
		}
		for name, method := range methods {
			if isUndefinedMethod(method) {
				names = append(names, name)
			}
		}
	}
	sort.Strings(names)
	return symbolArray(names...)
}

func modulePublicInstanceMethods(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return moduleMethodsForVisibility(receiver, "public", includeInheritedMethods(args...))
}

func moduleProtectedInstanceMethods(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return moduleMethodsForVisibility(receiver, "protected", includeInheritedMethods(args...))
}

func modulePrivateInstanceMethods(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return moduleMethodsForVisibility(receiver, "private", includeInheritedMethods(args...))
}

func moduleInstanceMethod(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 0 {
		return NewArgumentError("wrong number of arguments")
	}
	names, errVal := attrNamesFromValues(args[0])
	if errVal != nil {
		return errVal
	}
	if len(names) == 0 {
		return NewNameError("undefined method")
	}
	name := names[0]
	if ActiveRefinedInstanceMethod != nil {
		if method, ok := ActiveRefinedInstanceMethod(receiver, name); ok && !isUndefinedMethod(method) {
			copy := *method
			copy.Receiver = nil
			return &object.EmeraldValue{Type: object.ValueMethod, Data: &copy, Class: R.Classes["UnboundMethod"]}
		}
	}
	method, owner, ok := lookupInstanceMethodWithOwner(receiver, name)
	if !ok || isUndefinedMethod(method) {
		return NewNameError("undefined method `" + name + "'")
	}
	copy := *method
	copy.Owner = owner
	copy.DispatchOwner = methodImplementationOwner(&copy)
	copy.Receiver = nil
	return &object.EmeraldValue{Type: object.ValueMethod, Data: &copy, Class: R.Classes["UnboundMethod"]}
}

func modulePublicInstanceMethod(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 0 {
		return NewArgumentError("wrong number of arguments")
	}
	if args[0] == nil || (args[0].Type != object.ValueString && args[0].Type != object.ValueSymbol) {
		return typeError("wrong argument type")
	}
	name := specName(args[0])
	method, owner, ok := lookupInstanceMethodWithOwner(receiver, name)
	if !ok || isUndefinedMethod(method) || methodVisibility(method) != "public" {
		return NewNameError("undefined method `" + name + "'")
	}
	copy := *method
	copy.Owner = owner
	copy.DispatchOwner = methodImplementationOwner(&copy)
	copy.Receiver = nil
	return &object.EmeraldValue{Type: object.ValueMethod, Data: &copy, Class: R.Classes["UnboundMethod"]}
}

func classVariableName(value *object.EmeraldValue) (string, *object.EmeraldValue) {
	names, errVal := attrNamesFromValues(value)
	if errVal != nil {
		return "", errVal
	}
	if len(names) == 0 || !strings.HasPrefix(names[0], "@@") || len(names[0]) <= 2 {
		return "", NewNameError("wrong class variable name")
	}
	return names[0], nil
}

func moduleClassVariableSet(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) < 2 {
		return NewArgumentError("wrong number of arguments")
	}
	if receiver != nil && receiver.Frozen {
		return frozenError("can't modify frozen class/module")
	}
	name, errVal := classVariableName(args[0])
	if errVal != nil {
		return errVal
	}
	SetClassVariable(receiver, name, args[1])
	return args[1]
}

func moduleClassVariableGet(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 0 {
		return NewArgumentError("wrong number of arguments")
	}
	name, errVal := classVariableName(args[0])
	if errVal != nil {
		return errVal
	}
	if value, errVal, ok := LookupClassVariableWithError(receiver, name); errVal != nil {
		return errVal
	} else if ok {
		return value
	}
	return NewNameErrorWithDetails("uninitialized class variable "+name, receiver, name)
}

func moduleClassVariableDefined(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 0 {
		return R.FalseVal
	}
	name, errVal := classVariableName(args[0])
	if errVal != nil {
		return errVal
	}
	if _, ok := LookupClassVariable(receiver, name); ok {
		return R.TrueVal
	}
	return R.FalseVal
}

func moduleRemoveClassVariable(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 0 {
		return NewArgumentError("wrong number of arguments")
	}
	name, errVal := classVariableName(args[0])
	if errVal != nil {
		return errVal
	}
	var vars map[string]*object.EmeraldValue
	switch receiver.Type {
	case object.ValueClass:
		vars = receiver.Data.(*object.Class).ClassVars
	case object.ValueModule:
		vars = receiver.Data.(*object.Module).ClassVars
	default:
		return NewNameErrorWithDetails("class variable "+name+" not defined", receiver, name)
	}
	value, ok := vars[name]
	if !ok {
		return NewNameErrorWithDetails("class variable "+name+" not defined", receiver, name)
	}
	delete(vars, name)
	return value
}

func moduleClassVariables(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) > 1 {
		return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 0..1)", len(args)))
	}
	inherit := true
	if len(args) == 1 {
		inherit = isTruthy(args[0])
	}
	seen := map[string]bool{}
	names := []string{}
	switch receiver.Type {
	case object.ValueClass:
		collectClassVariableNamesOrdered(receiver.Data.(*object.Class), inherit, seen, &names)
	case object.ValueModule:
		collectModuleClassVariableNamesOrdered(receiver.Data.(*object.Module), inherit, seen, &names)
	default:
		return &object.EmeraldValue{Type: object.ValueArray, Data: []*object.EmeraldValue{}, Class: R.Classes["Array"]}
	}
	values := make([]*object.EmeraldValue, 0, len(names))
	for _, name := range names {
		values = append(values, &object.EmeraldValue{Type: object.ValueSymbol, Data: name, Class: R.Classes["Symbol"]})
	}
	return &object.EmeraldValue{Type: object.ValueArray, Data: values, Class: R.Classes["Array"]}
}

func appendOrderedClassVariableNames(order []string, variables map[string]*object.EmeraldValue, seen map[string]bool, names *[]string) {
	for _, name := range order {
		if _, exists := variables[name]; exists && !seen[name] {
			seen[name] = true
			*names = append(*names, name)
		}
	}
	leftovers := make([]string, 0)
	for name := range variables {
		if !seen[name] {
			leftovers = append(leftovers, name)
		}
	}
	sort.Strings(leftovers)
	for _, name := range leftovers {
		seen[name] = true
		*names = append(*names, name)
	}
}

func collectClassVariableNamesOrdered(class *object.Class, inherit bool, seen map[string]bool, names *[]string) {
	for cls := class; cls != nil; cls = cls.SuperClass {
		appendOrderedClassVariableNames(cls.ClassVarOrder, cls.ClassVars, seen, names)
		if !cls.IsSingleton && cls.SingletonClass != nil {
			appendOrderedClassVariableNames(cls.SingletonClass.ClassVarOrder, cls.SingletonClass.ClassVars, seen, names)
		}
		if !inherit {
			break
		}
	}
}

func collectModuleClassVariableNamesOrdered(module *object.Module, inherit bool, seen map[string]bool, names *[]string) {
	if module == nil {
		return
	}
	appendOrderedClassVariableNames(module.ClassVarOrder, module.ClassVars, seen, names)
	if inherit && module.Parent != nil {
		collectModuleClassVariableNamesOrdered(module.Parent, true, seen, names)
	}
}

func collectClassVariableNames(class *object.Class, inherit bool, names map[string]bool) {
	for cls := class; cls != nil; cls = cls.SuperClass {
		for name := range cls.ClassVars {
			names[name] = true
		}
		if !cls.IsSingleton && cls.SingletonClass != nil {
			for name := range cls.SingletonClass.ClassVars {
				names[name] = true
			}
		}
		for _, mod := range cls.IncludedModules {
			collectModuleClassVariableNames(mod, true, names)
		}
		if !inherit {
			break
		}
	}
}

func collectModuleClassVariableNames(module *object.Module, inherit bool, names map[string]bool) {
	if module == nil {
		return
	}
	for name := range module.ClassVars {
		names[name] = true
	}
	for _, included := range module.IncludedModules {
		collectModuleClassVariableNames(included, true, names)
	}
	if inherit && module.Parent != nil {
		collectModuleClassVariableNames(module.Parent, true, names)
	}
}

func SetClassVariable(receiver *object.EmeraldValue, name string, value *object.EmeraldValue) {
	if receiver == nil {
		return
	}
	switch receiver.Type {
	case object.ValueClass:
		class := receiver.Data.(*object.Class)
		if !setExistingClassClassVariable(class, name, value) {
			if _, exists := class.ClassVars[name]; !exists {
				class.ClassVarOrder = append(class.ClassVarOrder, name)
			}
			class.ClassVars[name] = value
		}
	case object.ValueModule:
		module := receiver.Data.(*object.Module)
		if !setExistingModuleClassVariable(module, name, value) {
			if _, exists := module.ClassVars[name]; !exists {
				module.ClassVarOrder = append(module.ClassVarOrder, name)
			}
			module.ClassVars[name] = value
		}
	case object.ValueObject:
		obj, ok := receiver.Data.(*object.Object)
		if !ok {
			return
		}
		if obj.ClassVars == nil {
			obj.ClassVars = make(map[string]*object.EmeraldValue)
		}
		obj.ClassVars[name] = value
	}
}

func setExistingClassClassVariable(class *object.Class, name string, value *object.EmeraldValue) bool {
	for cls := class; cls != nil; cls = cls.SuperClass {
		if _, ok := cls.ClassVars[name]; ok {
			cls.ClassVars[name] = value
			return true
		}
		for _, mod := range cls.IncludedModules {
			if setExistingModuleClassVariable(mod, name, value) {
				return true
			}
		}
	}
	return false
}

func setExistingModuleClassVariable(module *object.Module, name string, value *object.EmeraldValue) bool {
	if module == nil {
		return false
	}
	if _, ok := module.ClassVars[name]; ok {
		module.ClassVars[name] = value
		return true
	}
	for _, included := range module.IncludedModules {
		if setExistingModuleClassVariable(included, name, value) {
			return true
		}
	}
	if module.Parent != nil {
		return setExistingModuleClassVariable(module.Parent, name, value)
	}
	return false
}

func LookupClassVariable(receiver *object.EmeraldValue, name string) (*object.EmeraldValue, bool) {
	value, errVal, ok := LookupClassVariableWithError(receiver, name)
	if errVal != nil {
		return nil, false
	}
	return value, ok
}

func LookupClassVariableWithError(receiver *object.EmeraldValue, name string) (*object.EmeraldValue, *object.EmeraldValue, bool) {
	if receiver == nil {
		return nil, nil, false
	}
	switch receiver.Type {
	case object.ValueClass:
		return lookupClassClassVariableWithError(receiver.Data.(*object.Class), name)
	case object.ValueModule:
		value, ok := lookupModuleClassVariable(receiver.Data.(*object.Module), name)
		return value, nil, ok
	case object.ValueObject:
		obj, ok := receiver.Data.(*object.Object)
		if !ok {
			return nil, nil, false
		}
		if value, ok := obj.ClassVars[name]; ok {
			return value, nil, true
		}
		return lookupClassClassVariableWithError(obj.Class, name)
	}
	return nil, nil, false
}

func lookupClassClassVariable(class *object.Class, name string) (*object.EmeraldValue, bool) {
	value, errVal, ok := lookupClassClassVariableWithError(class, name)
	if errVal != nil {
		return nil, false
	}
	return value, ok
}

func lookupClassClassVariableWithError(class *object.Class, name string) (*object.EmeraldValue, *object.EmeraldValue, bool) {
	var foundClass *object.Class
	var foundValue *object.EmeraldValue
	for cls := class; cls != nil; cls = cls.SuperClass {
		if value, ok := cls.ClassVars[name]; ok {
			if foundClass != nil {
				msg := fmt.Sprintf("class variable %s of %s is overtaken by %s", name, classToS(foundClass), classToS(cls))
				return nil, newRuntimeException(R.Classes["RuntimeError"], msg), false
			}
			foundClass = cls
			foundValue = value
		}
		if cls.IsSingleton && cls.SingletonOwner != nil {
			if value, ownerName, ok := lookupAttachedOwnerClassVariable(cls.SingletonOwner, name); ok {
				if foundClass != nil {
					msg := fmt.Sprintf("class variable %s of %s is overtaken by %s", name, classToS(foundClass), ownerName)
					return nil, newRuntimeException(R.Classes["RuntimeError"], msg), false
				}
				foundClass = cls
				foundValue = value
			}
		}
		if !cls.IsSingleton && cls.SingletonClass != nil {
			if value, ok := cls.SingletonClass.ClassVars[name]; ok {
				if foundClass != nil && foundClass != cls {
					msg := fmt.Sprintf("class variable %s of %s is overtaken by %s", name, classToS(foundClass), classToS(cls))
					return nil, newRuntimeException(R.Classes["RuntimeError"], msg), false
				}
				foundClass = cls
				foundValue = value
			}
		}
		for _, mod := range cls.IncludedModules {
			if value, ok := lookupModuleClassVariable(mod, name); ok {
				return value, nil, true
			}
		}
	}
	if foundClass != nil {
		return foundValue, nil, true
	}
	return nil, nil, false
}

func lookupAttachedOwnerClassVariable(owner *object.EmeraldValue, name string) (*object.EmeraldValue, string, bool) {
	if owner == nil {
		return nil, "", false
	}
	switch owner.Type {
	case object.ValueClass:
		cls := owner.Data.(*object.Class)
		for current := cls; current != nil; current = current.SuperClass {
			if value, ok := current.ClassVars[name]; ok {
				return value, classToS(current), true
			}
			for _, mod := range current.IncludedModules {
				if value, ok := lookupModuleClassVariable(mod, name); ok {
					return value, moduleToS(mod), true
				}
			}
		}
	case object.ValueModule:
		mod := owner.Data.(*object.Module)
		if value, ok := lookupModuleClassVariable(mod, name); ok {
			return value, moduleToS(mod), true
		}
	}
	return nil, "", false
}

func lookupModuleClassVariable(module *object.Module, name string) (*object.EmeraldValue, bool) {
	if module == nil {
		return nil, false
	}
	if value, ok := module.ClassVars[name]; ok {
		return value, true
	}
	for _, included := range module.IncludedModules {
		if value, ok := lookupModuleClassVariable(included, name); ok {
			return value, true
		}
	}
	if module.Parent != nil {
		return lookupModuleClassVariable(module.Parent, name)
	}
	return nil, false
}

func moduleAliasMethod(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 1 && args[0] != nil && args[0].Type == object.ValueArray {
		args = args[0].Data.([]*object.EmeraldValue)
	}
	if len(args) < 2 {
		return NewArgumentError("wrong number of arguments")
	}
	names, errVal := attrNamesFromValues(args[0], args[1])
	if errVal != nil {
		return errVal
	}
	if receiver != nil && receiver.Frozen {
		return frozenError("can't modify frozen class/module")
	}
	newName, oldName := names[0], names[1]
	if strings.HasPrefix(newName, "$") && strings.HasPrefix(oldName, "$") {
		AliasGlobalVariable(newName, oldName)
		return &object.EmeraldValue{Type: object.ValueSymbol, Data: newName, Class: R.Classes["Symbol"]}
	}
	if receiver == nil || (receiver.Type != object.ValueClass && receiver.Type != object.ValueModule) {
		return NewTypeError("not a class/module")
	}
	method, implementationOwner, ok := lookupInstanceMethodWithOwner(receiver, oldName)
	if !ok && receiver.Type == object.ValueModule {
		module := receiver.Data.(*object.Module)
		if module.IsRefinement && module.RefinementTarget != nil {
			method, _, ok = lookupInstanceMethodWithOwner(module.RefinementTarget, oldName)
		}
	}
	if !ok {
		return NewNameError("undefined method `" + oldName + "'")
	}
	method = resolveVisibilityAliasForCopy(oldName, method)
	copy := *method
	dispatchOwner := copy.DispatchOwner
	if dispatchOwner == nil {
		dispatchOwner = copy.Owner
	}
	if dispatchOwner == nil {
		dispatchOwner = implementationOwner
	}
	if copy.OriginalName == "" {
		copy.OriginalName = oldName
	}
	copy.Name = newName
	copy.Owner = receiver
	copy.DispatchOwner = dispatchOwner
	if isAlwaysPrivateMethodName(newName) {
		copy.Visibility = "private"
	}
	switch receiver.Type {
	case object.ValueClass:
		receiver.Data.(*object.Class).Methods[newName] = &copy
	case object.ValueModule:
		receiver.Data.(*object.Module).Methods[newName] = &copy
	default:
		return typeError("not a class/module")
	}
	if hook := callMethodAddedHook(receiver, newName); hook != nil && hook.Type == object.ValueException {
		return hook
	}
	return &object.EmeraldValue{Type: object.ValueSymbol, Data: newName, Class: R.Classes["Symbol"]}
}

func resolveVisibilityAliasForCopy(name string, method *object.Method) *object.Method {
	if method == nil || method.VisibilityAliasStart == nil {
		return method
	}
	actual, ok := methodAfterClass(method.VisibilityAliasStart, name)
	if !ok || actual == nil {
		return method
	}
	copy := *actual
	copy.Visibility = method.Visibility
	return &copy
}

func methodAfterClass(class *object.Class, name string) (*object.Method, bool) {
	if class == nil {
		return nil, false
	}
	for index := len(class.IncludedModules) - 1; index >= 0; index-- {
		if method, _, ok := lookupModuleMethodWithOwner(class.IncludedModules[index], name); ok {
			return method, true
		}
	}
	if class.SuperClass != nil {
		method, _, ok := class.SuperClass.GetMethodWithOwner(name)
		return method, ok
	}
	return nil, false
}

func AliasMethod(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return moduleAliasMethod(receiver, args...)
}

func isAlwaysPrivateMethodName(name string) bool {
	switch name {
	case "initialize", "initialize_copy", "initialize_clone", "initialize_dup", "respond_to_missing?":
		return true
	default:
		return false
	}
}

func ResolveGlobalAlias(name string) string {
	if name == "" || globalVariableAliases == nil {
		return name
	}
	seen := make(map[string]bool)
	current := name
	for {
		next, ok := globalVariableAliases[current]
		if !ok || next == "" || next == current {
			return current
		}
		if seen[current] {
			return current
		}
		seen[current] = true
		current = next
	}
}

func AliasGlobalVariable(newName string, toName string) {
	if newName == "" || toName == "" {
		return
	}
	if globalVariableAliases == nil {
		globalVariableAliases = make(map[string]string)
	}
	globalVariableAliases[newName] = ResolveGlobalAlias(toName)
}

func installEnglishGlobalAliases() {
	aliases := map[string]string{
		"$ERROR_INFO":              "$!",
		"$ERROR_POSITION":          "$@",
		"$FS":                      "$;",
		"$FIELD_SEPARATOR":         "$;",
		"$OFS":                     "$,",
		"$OUTPUT_FIELD_SEPARATOR":  "$,",
		"$RS":                      "$/",
		"$INPUT_RECORD_SEPARATOR":  "$/",
		"$ORS":                     "$\\",
		"$OUTPUT_RECORD_SEPARATOR": "$\\",
		"$INPUT_LINE_NUMBER":       "$.",
		"$NR":                      "$.",
		"$LAST_READ_LINE":          "$_",
		"$DEFAULT_OUTPUT":          "$>",
		"$DEFAULT_INPUT":           "$<",
		"$PID":                     "$$",
		"$PROCESS_ID":              "$$",
		"$CHILD_STATUS":            "$?",
		"$LAST_MATCH_INFO":         "$~",
		"$ARGV":                    "$*",
		"$MATCH":                   "$&",
		"$PREMATCH":                "$`",
		"$POSTMATCH":               "$'",
		"$LAST_PAREN_MATCH":        "$+",
	}
	for name, target := range aliases {
		AliasGlobalVariable(name, target)
	}
}

func moduleDefineMethod(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver == nil || (receiver.Type != object.ValueClass && receiver.Type != object.ValueModule) {
		return typeError("not a class/module")
	}
	if receiver.Frozen {
		return frozenError("can't modify frozen class/module")
	}
	if len(args) == 0 {
		return NewArgumentError("wrong number of arguments")
	}
	names, errVal := attrNamesFromValues(args[0])
	if errVal != nil {
		return errVal
	}
	if len(names) == 0 {
		return typeError("is not a symbol nor a string")
	}
	name := names[0]
	var method *object.Method
	if len(args) > 1 {
		method, errVal = methodFromDefineMethodValue(receiver, name, args[1])
	} else {
		if CurrentBlockValue == nil || CurrentBlockValue() == nil {
			return NewArgumentError("tried to create Proc object without a block")
		}
		method, errVal = methodFromDefineMethodValue(receiver, name, CurrentBlockValue())
	}
	if errVal != nil {
		return errVal
	}
	method.DefinedByDefineMethod = true
	method.Name = name
	method.Owner = receiver
	method.Visibility = defineMethodVisibility(receiver, name)
	method.EnforceArity = true
	switch receiver.Type {
	case object.ValueClass:
		receiver.Data.(*object.Class).DefineMethod(name, method)
	case object.ValueModule:
		receiver.Data.(*object.Module).DefineMethod(name, method)
		if currentMethodVisibilityMode(receiver) == "module_function" {
			if result := moduleFunction(receiver, &object.EmeraldValue{Type: object.ValueSymbol, Data: name, Class: R.Classes["Symbol"]}); result != nil && result.Type == object.ValueException {
				return result
			}
		}
	}
	if errVal := callMethodAddedHook(receiver, name); errVal != nil && errVal.Type == object.ValueException {
		return errVal
	}
	return &object.EmeraldValue{Type: object.ValueSymbol, Data: name, Class: R.Classes["Symbol"]}
}

func methodFromDefineMethodValue(receiver *object.EmeraldValue, name string, value *object.EmeraldValue) (*object.Method, *object.EmeraldValue) {
	if value == nil {
		return nil, typeError("wrong argument type NilClass (expected Proc/Method/UnboundMethod)")
	}
	switch value.Type {
	case object.ValueClosure:
		closure := value.Data.(*object.Closure)
		closure.Fn.DefinedByDefineMethod = true
		return &object.Method{Name: name, Fn: closure.Fn, Closure: closure}, nil
	case object.ValueProc:
		proc := value.Data.(*object.Proc)
		if proc.Native != nil {
			return &object.Method{Name: name, Fn: func(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
				return proc.Native(args...)
			}}, nil
		}
		proc.Fn.DefinedByDefineMethod = true
		return &object.Method{Name: name, Fn: proc.Fn, Closure: &object.Closure{
			Fn:               proc.Fn,
			Free:             proc.Env,
			Block:            proc.Block,
			Binding:          proc.Binding,
			ClassStack:       proc.ClassStack,
			Refinements:      append([]*object.EmeraldValue(nil), proc.Refinements...),
			RefinementsFixed: proc.RefinementsFixed,
			AutoSplat:        proc.AutoSplat,
			ReturnOwnerID:    proc.ReturnOwnerID,
		}}, nil
	case object.ValueMethod:
		copy := *value.Data.(*object.Method)
		if errVal := validateDefineMethodOwner(receiver, &copy); errVal != nil {
			return nil, errVal
		}
		copy.Name = name
		return &copy, nil
	default:
		typeName := value.Inspect()
		if value.Class != nil && value.Class.Name != "" {
			typeName = value.Class.Name
		}
		return nil, typeError("wrong argument type " + typeName + " (expected Proc/Method/UnboundMethod)")
	}
}

func validateDefineMethodOwner(receiver *object.EmeraldValue, method *object.Method) *object.EmeraldValue {
	if receiver == nil || method == nil || method.Owner == nil {
		return nil
	}
	if method.Owner.Type != object.ValueClass {
		return nil
	}
	owner := method.Owner.Data.(*object.Class)
	if owner == nil || owner == R.Classes["Kernel"] {
		return nil
	}
	if owner.IsSingleton {
		if receiver.Type == object.ValueClass && defineMethodClassInheritsFrom(receiver.Data.(*object.Class), owner) {
			return nil
		}
		return typeError("can't bind singleton method to a different class")
	}
	if owner == R.Classes["Object"] && receiver.Type == object.ValueClass {
		if kernel := R.Classes["Kernel"]; kernel != nil {
			if kernelMethod, ok := kernel.Methods[method.Name]; ok && methodImplementationEqual(kernelMethod.Fn, method.Fn) && defineMethodClassInheritsFrom(receiver.Data.(*object.Class), R.Classes["BasicObject"]) {
				return nil
			}
		}
	}
	if receiver.Type != object.ValueClass {
		return typeError("bind argument must be a subclass of " + owner.Name)
	}
	target := receiver.Data.(*object.Class)
	if defineMethodClassInheritsFrom(target, owner) {
		return nil
	}
	return typeError("bind argument must be a subclass of " + owner.Name)
}

func defineMethodClassInheritsFrom(cls, target *object.Class) bool {
	if cls == nil || target == nil {
		return false
	}
	for current := cls; current != nil; current = current.SuperClass {
		if current == target {
			return true
		}
		if current.Name != "" && current.Name == target.Name {
			return true
		}
	}
	return false
}

func defineMethodVisibility(receiver *object.EmeraldValue, name string) string {
	if isAlwaysPrivateMethodName(name) {
		return "private"
	}
	if currentMethodVisibilityMode(receiver) == "module_function" {
		return "private"
	}
	return currentMethodVisibility(receiver)
}

func currentMethodVisibilityMode(receiver *object.EmeraldValue) string {
	if receiver == nil {
		return "public"
	}
	var visibility *object.EmeraldValue
	switch receiver.Type {
	case object.ValueClass:
		visibility = receiver.Data.(*object.Class).GetInstanceVar("@__visibility")
	case object.ValueModule:
		visibility = receiver.Data.(*object.Module).GetInstanceVar("@__visibility")
	}
	if visibility != nil && visibility.Type == object.ValueString {
		switch visibility.Data.(string) {
		case "private", "protected", "module_function":
			return visibility.Data.(string)
		}
	}
	return "public"
}

func moduleRemoveMethod(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 0 {
		return receiver
	}
	names, errVal := attrNamesFromValues(args...)
	if errVal != nil {
		return errVal
	}
	if receiver != nil && receiver.Frozen {
		return frozenError("can't modify frozen class/module")
	}
	for _, name := range names {
		if !removeDirectMethod(receiver, name) {
			return NewNameError("method `" + name + "' not defined")
		}
		hookReceiver, hook := methodMutationHook(receiver, "method_removed", "singleton_method_removed")
		if result := callModuleMethodHook(hookReceiver, hook, name); result != nil && result.Type == object.ValueException {
			return result
		}
	}
	return receiver
}

func removeDirectMethod(receiver *object.EmeraldValue, name string) bool {
	if receiver == nil {
		return false
	}
	if HasNativeSingletonMethod != nil && HasNativeSingletonMethod(receiver, name) {
		return true
	}
	switch receiver.Type {
	case object.ValueClass:
		methods := receiver.Data.(*object.Class).Methods
		if _, ok := methods[name]; ok {
			delete(methods, name)
			return true
		}
	case object.ValueModule:
		methods := receiver.Data.(*object.Module).Methods
		if _, ok := methods[name]; ok {
			delete(methods, name)
			return true
		}
	}
	return false
}

func moduleUndefMethod(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 0 {
		return receiver
	}
	names, errVal := attrNamesFromValues(args...)
	if errVal != nil {
		return errVal
	}
	if receiver != nil && receiver.Frozen {
		return frozenError("can't modify frozen class/module")
	}
	for _, name := range names {
		method, _, ok := lookupInstanceMethodWithOwner(receiver, name)
		if (!ok || isUndefinedMethod(method)) && receiver.Type == object.ValueClass {
			if cls := receiver.Data.(*object.Class); cls.IsSingleton && cls.SingletonOwner != nil && cls.SingletonOwner.Type == object.ValueObject {
				if obj, objOK := cls.SingletonOwner.Data.(*object.Object); objOK {
					if singletonMethod, found := obj.SingletonMethods[name]; found {
						method = singletonMethod
						ok = true
					}
				}
			}
		}
		if !ok || isUndefinedMethod(method) {
			return NewNameError("undefined method `" + name + "' for " + moduleOrClassDescription(receiver))
		}
		undefined := &object.Method{Name: name, Visibility: "undefined"}
		switch receiver.Type {
		case object.ValueClass:
			cls := receiver.Data.(*object.Class)
			cls.Methods[name] = undefined
			if cls.IsSingleton && cls.SingletonOwner != nil && cls.SingletonOwner.Type == object.ValueObject {
				if obj, ok := cls.SingletonOwner.Data.(*object.Object); ok {
					if obj.SingletonMethods == nil {
						obj.SingletonMethods = map[string]*object.Method{}
					}
					obj.SingletonMethods[name] = undefined
				}
			}
		case object.ValueModule:
			receiver.Data.(*object.Module).Methods[name] = undefined
		}
		hookReceiver, hook := methodMutationHook(receiver, "method_undefined", "singleton_method_undefined")
		if result := callModuleMethodHook(hookReceiver, hook, name); result != nil && result.Type == object.ValueException {
			return result
		}
	}
	return receiver
}

func methodMutationHook(receiver *object.EmeraldValue, ordinary, singleton string) (*object.EmeraldValue, string) {
	if receiver != nil && receiver.Type == object.ValueClass {
		if class := receiver.Data.(*object.Class); class.IsSingleton && class.SingletonOwner != nil {
			return class.SingletonOwner, singleton
		}
	}
	return receiver, ordinary
}

func moduleOrClassDescription(receiver *object.EmeraldValue) string {
	switch receiver.Type {
	case object.ValueModule:
		return "module `" + moduleToS(receiver.Data.(*object.Module)) + "'"
	case object.ValueClass:
		name := classToS(receiver.Data.(*object.Class))
		if strings.HasPrefix(name, "#<Class:") && strings.HasSuffix(name, ">") {
			inner := strings.TrimSuffix(strings.TrimPrefix(name, "#<Class:"), ">")
			if !strings.HasPrefix(inner, "#<") {
				name = inner
			}
		}
		return "class `" + name + "'"
	default:
		return "class/module"
	}
}

func moduleRuby2Keywords(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	for _, arg := range args {
		name := ""
		if arg != nil && arg.Type == object.ValueClosure {
			if closure, ok := arg.Data.(*object.Closure); ok && closure.Fn != nil {
				name = closure.Fn.Name
			}
		} else {
			names, errVal := attrNamesFromValues(arg)
			if errVal != nil {
				return errVal
			}
			if len(names) > 0 {
				name = names[0]
			}
		}
		method, owner, ok := lookupInstanceMethodWithOwner(receiver, name)
		if !ok {
			return NewNameError("undefined method `" + name + "'")
		}
		markRuby2KeywordsMethodAliases(owner, method)
	}
	return R.NilVal
}

func markRuby2KeywordsMethodAliases(owner *object.EmeraldValue, method *object.Method) {
	if method == nil {
		return
	}
	method.Ruby2Keywords = true
	target, ok := method.Fn.(*object.Function)
	if !ok || owner == nil {
		return
	}
	var methods map[string]*object.Method
	switch owner.Type {
	case object.ValueClass:
		methods = owner.Data.(*object.Class).Methods
	case object.ValueModule:
		methods = owner.Data.(*object.Module).Methods
	}
	for _, candidate := range methods {
		if function, ok := candidate.Fn.(*object.Function); ok && function == target {
			candidate.Ruby2Keywords = true
		}
	}
}

func lookupInstanceMethodWithOwner(receiver *object.EmeraldValue, name string) (*object.Method, *object.EmeraldValue, bool) {
	if receiver == nil {
		return nil, nil, false
	}
	switch receiver.Type {
	case object.ValueClass:
		for cls := receiver.Data.(*object.Class); cls != nil; cls = cls.SuperClass {
			for _, mod := range cls.PrependedModules {
				if method, owner, ok := lookupModuleMethodWithOwner(mod, name); ok {
					return method, owner, true
				}
			}
			if method, ok := cls.Methods[name]; ok {
				return method, &object.EmeraldValue{Type: object.ValueClass, Data: cls, Class: R.Classes["Class"]}, true
			}
			for index := len(cls.IncludedModules) - 1; index >= 0; index-- {
				mod := cls.IncludedModules[index]
				if method, owner, ok := lookupModuleMethodWithOwner(mod, name); ok {
					return method, owner, true
				}
			}
		}
	case object.ValueModule:
		return lookupModuleMethodWithOwner(receiver.Data.(*object.Module), name)
	}
	return nil, nil, false
}

func lookupModuleMethodWithOwner(module *object.Module, name string) (*object.Method, *object.EmeraldValue, bool) {
	if module == nil {
		return nil, nil, false
	}
	for _, mod := range module.PrependedModules {
		if method, owner, ok := lookupModuleMethodWithOwner(mod, name); ok {
			return method, owner, true
		}
	}
	if method, ok := module.Methods[name]; ok {
		if method.Owner != nil {
			return method, method.Owner, true
		}
		return method, &object.EmeraldValue{Type: object.ValueModule, Data: module, Class: R.Classes["Module"]}, true
	}
	for index := len(module.IncludedModules) - 1; index >= 0; index-- {
		included := module.IncludedModules[index]
		if method, owner, ok := lookupModuleMethodWithOwner(included, name); ok {
			return method, owner, true
		}
	}
	if module.Parent != nil {
		return lookupModuleMethodWithOwner(module.Parent, name)
	}
	return nil, nil, false
}

func includeInheritedMethods(args ...*object.EmeraldValue) bool {
	if len(args) == 0 {
		return true
	}
	return args[0] != nil && isTruthy(args[0])
}

func moduleMethodDefined(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return moduleMethodDefinedForVisibility(receiver, "", args...)
}

func modulePublicMethodDefined(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return moduleMethodDefinedForVisibility(receiver, "public", args...)
}

func moduleProtectedMethodDefined(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return moduleMethodDefinedForVisibility(receiver, "protected", args...)
}

func modulePrivateMethodDefined(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return moduleMethodDefinedForVisibility(receiver, "private", args...)
}

func moduleMethodDefinedForVisibility(receiver *object.EmeraldValue, visibility string, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 0 {
		return R.FalseVal
	}
	names, errVal := attrNamesFromValues(args[0])
	if errVal != nil {
		return errVal
	}
	if len(names) == 0 {
		return R.FalseVal
	}
	name := names[0]
	inherited := true
	if len(args) > 1 {
		inherited = includeInheritedMethods(args[1])
	}
	var method *object.Method
	var ok bool
	if inherited {
		method, _, ok = lookupInstanceMethodWithOwner(receiver, name)
	} else {
		method, ok = lookupDirectInstanceMethod(receiver, name)
	}
	if ok && methodMatchesDefinedVisibility(method, visibility) {
		return R.TrueVal
	}
	return R.FalseVal
}

func methodMatchesDefinedVisibility(method *object.Method, visibility string) bool {
	if isUndefinedMethod(method) {
		return false
	}
	actual := methodVisibility(method)
	if visibility == "" {
		return actual != "private"
	}
	return actual == visibility
}

func lookupDirectInstanceMethod(receiver *object.EmeraldValue, name string) (*object.Method, bool) {
	if receiver == nil {
		return nil, false
	}
	switch receiver.Type {
	case object.ValueClass:
		method, ok := receiver.Data.(*object.Class).Methods[name]
		return method, ok
	case object.ValueModule:
		method, ok := receiver.Data.(*object.Module).Methods[name]
		return method, ok
	}
	return nil, false
}

func moduleMethodsForVisibility(receiver *object.EmeraldValue, visibility string, inherited bool) *object.EmeraldValue {
	seen := map[string]bool{}
	names := []string{}
	add := func(name string, method *object.Method) {
		if seen[name] {
			return
		}
		if isUndefinedMethod(method) {
			seen[name] = true
			return
		}
		if visibility == "" && methodVisibility(method) == "private" {
			return
		}
		if visibility != "" && methodVisibility(method) != visibility {
			return
		}
		if !inherited && !methodOwnedByModuleReceiver(method, receiver) {
			return
		}
		seen[name] = true
		names = append(names, name)
	}
	if receiver != nil {
		switch receiver.Type {
		case object.ValueClass:
			start := receiver.Data.(*object.Class)
			for cls := start; cls != nil; cls = cls.SuperClass {
				for _, mod := range cls.PrependedModules {
					for name, method := range mod.Methods {
						add(name, method)
					}
				}
				for name, method := range cls.Methods {
					if start.Name == "Class" && cls.Name == "Module" && (name == "append_features" || name == "prepend_features" || name == "extend_object") {
						continue
					}
					add(name, method)
				}
				for _, mod := range cls.IncludedModules {
					for name, method := range mod.Methods {
						add(name, method)
					}
				}
				if !inherited {
					break
				}
			}
		case object.ValueModule:
			mod := receiver.Data.(*object.Module)
			for _, prepended := range mod.PrependedModules {
				for name, method := range prepended.Methods {
					add(name, method)
				}
			}
			for name, method := range mod.Methods {
				add(name, method)
			}
			if inherited {
				for _, included := range mod.IncludedModules {
					for name, method := range included.Methods {
						add(name, method)
					}
				}
			}
		}
	}
	sort.Strings(names)
	return symbolArray(names...)
}

func methodOwnedByModuleReceiver(method *object.Method, receiver *object.EmeraldValue) bool {
	if method == nil || method.Owner == nil || receiver == nil {
		return true
	}
	if method.Owner.Type != receiver.Type {
		return false
	}
	return method.Owner.Data == receiver.Data
}

func methodVisibility(method *object.Method) string {
	if isUndefinedMethod(method) {
		return "undefined"
	}
	if method == nil || method.Visibility == "" {
		return "public"
	}
	return method.Visibility
}

func isUndefinedMethod(method *object.Method) bool {
	return method != nil && method.Visibility == "undefined"
}

func setMethodVisibility(receiver *object.EmeraldValue, visibility string, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 0 {
		setCurrentMethodVisibility(receiver, visibility)
		return R.NilVal
	}
	names, errVal := classMethodNamesFromValues(args...)
	if errVal != nil {
		return errVal
	}
	for _, name := range names {
		_, directlyDefined := lookupDirectInstanceMethod(receiver, name)
		if !setNamedMethodVisibility(receiver, name, visibility) {
			return NewNameError("undefined method `" + name + "'")
		}
		if !directlyDefined {
			if hook := callMethodAddedHook(receiver, name); hook != nil && hook.Type == object.ValueException {
				return hook
			}
		}
	}
	if len(args) == 1 && args[0] != nil && args[0].Type != object.ValueArray {
		return &object.EmeraldValue{Type: object.ValueSymbol, Data: names[0], Class: R.Classes["Symbol"]}
	}
	return symbolArray(names...)
}

func setCurrentMethodVisibility(receiver *object.EmeraldValue, visibility string) {
	if receiver == nil {
		return
	}
	switch receiver.Type {
	case object.ValueClass:
		receiver.Data.(*object.Class).SetInstanceVar("@__visibility", rubyString(visibility))
	case object.ValueModule:
		receiver.Data.(*object.Module).SetInstanceVar("@__visibility", rubyString(visibility))
	}
}

func SetCurrentMethodVisibility(receiver *object.EmeraldValue, visibility string) {
	setCurrentMethodVisibility(receiver, visibility)
}

func CurrentMethodVisibilityMode(receiver *object.EmeraldValue) string {
	return currentMethodVisibilityMode(receiver)
}

func ResetCurrentMethodVisibility(receiver *object.EmeraldValue) {
	if receiver == nil {
		return
	}
	switch receiver.Type {
	case object.ValueClass:
		delete(receiver.Data.(*object.Class).InstanceVars, "@__visibility")
	case object.ValueModule:
		delete(receiver.Data.(*object.Module).InstanceVars, "@__visibility")
	}
}

func setNamedMethodVisibility(receiver *object.EmeraldValue, name, visibility string) bool {
	if receiver == nil {
		return false
	}
	switch receiver.Type {
	case object.ValueClass:
		cls := receiver.Data.(*object.Class)
		if method, ok := cls.Methods[name]; ok {
			method.Visibility = visibility
			return true
		}
		if method, _, ok := cls.GetMethodWithOwner(name); ok && method != nil {
			clone := *method
			clone.Visibility = visibility
			clone.VisibilityAliasStart = cls
			clone.Owner = &object.EmeraldValue{Type: object.ValueClass, Data: cls, Class: R.Classes["Class"]}
			cls.Methods[name] = &clone
			return true
		}
	case object.ValueModule:
		mod := receiver.Data.(*object.Module)
		if method, ok := mod.Methods[name]; ok {
			method.Visibility = visibility
			return true
		}
		if method, ok := R.Classes["Object"].GetMethod(name); ok {
			clone := *method
			clone.Visibility = visibility
			clone.Owner = &object.EmeraldValue{Type: object.ValueModule, Data: mod, Class: R.Classes["Module"]}
			mod.Methods[name] = &clone
			return true
		}
	}
	return false
}

func setClassMethodVisibility(receiver *object.EmeraldValue, visibility string, args ...*object.EmeraldValue) *object.EmeraldValue {
	names, errVal := classMethodNamesFromValues(args...)
	if errVal != nil {
		return errVal
	}
	for _, name := range names {
		if !setNamedClassMethodVisibility(receiver, name, visibility) {
			return NewNameError("undefined method `" + name + "'")
		}
	}
	if len(args) == 1 && args[0] != nil && args[0].Type != object.ValueArray {
		return &object.EmeraldValue{Type: object.ValueSymbol, Data: names[0], Class: R.Classes["Symbol"]}
	}
	return symbolArray(names...)
}

func classMethodNamesFromValues(args ...*object.EmeraldValue) ([]string, *object.EmeraldValue) {
	expanded := make([]*object.EmeraldValue, 0, len(args))
	for _, arg := range args {
		if arg != nil && arg.Type == object.ValueArray {
			expanded = append(expanded, arg.Data.([]*object.EmeraldValue)...)
			continue
		}
		expanded = append(expanded, arg)
	}
	return attrNamesFromValues(expanded...)
}

func setNamedClassMethodVisibility(receiver *object.EmeraldValue, name, visibility string) bool {
	if receiver == nil {
		return false
	}
	switch receiver.Type {
	case object.ValueClass:
		cls := receiver.Data.(*object.Class)
		if cls.SingletonClass != nil {
			if method, ok := cls.SingletonClass.Methods[name]; ok {
				clone := *method
				clone.Visibility = visibility
				cls.SingletonClass.Methods[name] = &clone
				return true
			}
		}
		if method, ok := cls.ClassMethods[name]; ok {
			clone := *method
			clone.Visibility = visibility
			cls.ClassMethods[name] = &clone
			return true
		}
		if method, ok := lookupInheritedClassMethodForVisibility(cls, name); ok {
			clone := *method
			clone.Visibility = visibility
			cls.ClassMethods[name] = &clone
			return true
		}
	case object.ValueModule:
		mod := receiver.Data.(*object.Module)
		if mod.SingletonClass != nil {
			if method, ok := mod.SingletonClass.Methods[name]; ok {
				clone := *method
				clone.Visibility = visibility
				mod.SingletonClass.Methods[name] = &clone
				return true
			}
		}
	}
	return false
}

func lookupInheritedClassMethodForVisibility(cls *object.Class, name string) (*object.Method, bool) {
	for current := cls.SuperClass; current != nil; current = current.SuperClass {
		if current.SingletonClass != nil {
			if method, ok := current.SingletonClass.Methods[name]; ok {
				return method, true
			}
		}
		if method, ok := current.ClassMethods[name]; ok {
			return method, true
		}
	}
	return nil, false
}

func currentMethodVisibility(receiver *object.EmeraldValue) string {
	if receiver == nil {
		return "public"
	}
	var visibility *object.EmeraldValue
	switch receiver.Type {
	case object.ValueClass:
		visibility = receiver.Data.(*object.Class).GetInstanceVar("@__visibility")
	case object.ValueModule:
		visibility = receiver.Data.(*object.Module).GetInstanceVar("@__visibility")
	}
	if visibility != nil && visibility.Type == object.ValueString {
		switch visibility.Data.(string) {
		case "private", "protected":
			return visibility.Data.(string)
		}
	}
	return "public"
}

func defineAttrReaders(receiver *object.EmeraldValue, names ...string) {
	if receiver == nil || receiver.Class == nil {
		return
	}
	for _, name := range names {
		ivar := "@" + name
		getterName := name
		visibility := currentMethodVisibility(receiver)
		defineDynamicAccessor(receiver, getterName, &object.Method{
			Name:       getterName,
			Arity:      0,
			Visibility: visibility,
			Fn: func(r *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
				if value := dynamicInstanceVar(r, ivar); value != nil {
					return value
				}
				return R.NilVal
			},
		})
	}
}

func defineAttrWriters(receiver *object.EmeraldValue, names ...string) {
	if receiver == nil || receiver.Class == nil {
		return
	}
	for _, name := range names {
		ivar := "@" + name
		setterName := name + "="
		visibility := currentMethodVisibility(receiver)
		defineDynamicAccessor(receiver, setterName, &object.Method{
			Name:       setterName,
			Arity:      1,
			Visibility: visibility,
			Fn: func(r *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
				if len(args) == 0 {
					return R.NilVal
				}
				if result := setDynamicInstanceVar(r, ivar, args[0]); result != nil {
					return result
				}
				return args[0]
			},
		})
	}
}

func attrWriteFrozen(receiver *object.EmeraldValue) bool {
	if receiver == nil {
		return false
	}
	if receiver.Frozen {
		return true
	}
	switch receiver.Type {
	case object.ValueBool, object.ValueInteger, object.ValueFloat, object.ValueSymbol, object.ValueNil:
		return true
	}
	return false
}

func defineDynamicAccessor(receiver *object.EmeraldValue, name string, method *object.Method) {
	switch receiver.Type {
	case object.ValueClass:
		cls := receiver.Data.(*object.Class)
		cls.DefineMethod(name, method)
		callMethodAddedHook(receiver, name)
	case object.ValueModule:
		receiver.Data.(*object.Module).DefineMethod(name, method)
		callMethodAddedHook(receiver, name)
	default:
		receiver.Class.DefineMethod(name, method)
	}
}

func callMethodAddedHook(receiver *object.EmeraldValue, name string) *object.EmeraldValue {
	if CallMethod == nil || receiver == nil {
		return nil
	}
	if result := callModuleMethodHook(receiver, "method_added", name); result != nil && result.Type == object.ValueException {
		return result
	}
	if receiver.Type == object.ValueClass {
		if cls := receiver.Data.(*object.Class); cls.IsSingleton && cls.SingletonOwner != nil {
			if result := NotifySingletonMethodAdded(cls.SingletonOwner, name); result != nil && result.Type == object.ValueException {
				return result
			}
		}
	}
	return nil
}

func NotifyMethodAdded(receiver *object.EmeraldValue, name string) *object.EmeraldValue {
	return callModuleMethodHook(receiver, "method_added", name)
}

func callModuleMethodHook(receiver *object.EmeraldValue, hook string, name string) *object.EmeraldValue {
	if receiver == nil {
		return nil
	}
	if receiverHasCallableMethod(receiver, hook) {
		if CallMethodBypass != nil {
			return CallMethodBypass(receiver, hook, &object.EmeraldValue{Type: object.ValueSymbol, Data: name, Class: R.Classes["Symbol"]})
		}
		if CallMethod == nil {
			return nil
		}
		return CallMethod(receiver, hook, &object.EmeraldValue{Type: object.ValueSymbol, Data: name, Class: R.Classes["Symbol"]})
	}
	return nil
}

func NotifySingletonMethodAdded(receiver *object.EmeraldValue, name string) *object.EmeraldValue {
	if receiver == nil {
		return nil
	}
	if CallMethodBypass != nil {
		return CallMethodBypass(receiver, "singleton_method_added", &object.EmeraldValue{Type: object.ValueSymbol, Data: name, Class: R.Classes["Symbol"]})
	}
	if CallMethod == nil {
		return nil
	}
	return CallMethod(receiver, "singleton_method_added", &object.EmeraldValue{Type: object.ValueSymbol, Data: name, Class: R.Classes["Symbol"]})
}

func NotifyConstAdded(receiver *object.EmeraldValue, name string) *object.EmeraldValue {
	if receiver == nil {
		return R.NilVal
	}
	nameValue := &object.EmeraldValue{Type: object.ValueSymbol, Data: name, Class: R.Classes["Symbol"]}
	if CallMethodBypass != nil {
		return CallMethodBypass(receiver, "const_added", nameValue)
	}
	if CallMethod != nil {
		return CallMethod(receiver, "const_added", nameValue)
	}
	return R.NilVal
}

func receiverHasCallableMethod(receiver *object.EmeraldValue, name string) bool {
	if receiver == nil {
		return false
	}
	switch receiver.Type {
	case object.ValueObject:
		if obj, ok := receiver.Data.(*object.Object); ok {
			if method, ok := obj.SingletonMethods[name]; ok {
				return !isUndefinedMethod(method)
			}
			if obj.SingletonClass != nil {
				for _, mod := range obj.SingletonClass.PrependedModules {
					if method, ok := mod.GetMethod(name); ok {
						return !isUndefinedMethod(method)
					}
				}
				if method, ok := obj.SingletonClass.Methods[name]; ok {
					return !isUndefinedMethod(method)
				}
				for _, mod := range obj.SingletonClass.IncludedModules {
					if method, ok := mod.GetMethod(name); ok {
						return !isUndefinedMethod(method)
					}
				}
			}
		}
	case object.ValueClass:
		cls := receiver.Data.(*object.Class)
		method, _, ok := lookupClassReceiverMethod(cls, name)
		if ok && !isUndefinedMethod(method) {
			return true
		}
	case object.ValueModule:
		mod := receiver.Data.(*object.Module)
		if mod.SingletonClass != nil {
			for _, singletonMod := range mod.SingletonClass.PrependedModules {
				if _, ok := singletonMod.GetMethod(name); ok {
					return true
				}
			}
			if _, ok := mod.SingletonClass.Methods[name]; ok {
				return true
			}
			for _, singletonMod := range mod.SingletonClass.IncludedModules {
				if _, ok := singletonMod.GetMethod(name); ok {
					return true
				}
			}
		}
		if _, ok := mod.Methods[name]; ok {
			return true
		}
	case object.ValueException:
		if exc, ok := receiver.Data.(*object.RException); ok && exc.SingletonClass != nil {
			for _, mod := range exc.SingletonClass.PrependedModules {
				if method, ok := mod.GetMethod(name); ok {
					return !isUndefinedMethod(method)
				}
			}
			if method, ok := exc.SingletonClass.Methods[name]; ok {
				return !isUndefinedMethod(method)
			}
			for _, mod := range exc.SingletonClass.IncludedModules {
				if method, ok := mod.GetMethod(name); ok {
					return !isUndefinedMethod(method)
				}
			}
		}
	}
	if receiver.Class != nil {
		if method, ok := receiver.Class.GetMethod(name); ok {
			return !isUndefinedMethod(method)
		}
	}
	return false
}

func ReceiverHasCallableMethod(receiver *object.EmeraldValue, name string) bool {
	return receiverHasCallableMethod(receiver, name)
}

func dynamicInstanceVar(receiver *object.EmeraldValue, name string) *object.EmeraldValue {
	if receiver == nil {
		return nil
	}
	switch receiver.Type {
	case object.ValueObject:
		if data, ok := receiver.Data.(*ioShimData); ok && name == "@close_exception" {
			if data.closeException != nil {
				return data.closeException
			}
			return R.NilVal
		}
		if obj, ok := receiver.Data.(*object.Object); ok {
			return obj.GetInstanceVar(name)
		}
	case object.ValueHash:
		if hash := hashData(receiver); hash != nil && hash.InstanceVars != nil {
			return hash.InstanceVars[name]
		}
	case object.ValueException:
		if exc, ok := receiver.Data.(*object.RException); ok && exc.InstanceVars != nil {
			return exc.InstanceVars[name]
		}
	case object.ValueProc:
		if proc, ok := receiver.Data.(*object.Proc); ok {
			return proc.InstanceVars[name]
		}
	case object.ValueClass:
		if cls, ok := receiver.Data.(*object.Class); ok {
			return cls.GetInstanceVar(name)
		}
	case object.ValueModule:
		if mod, ok := receiver.Data.(*object.Module); ok {
			return mod.InstanceVars[name]
		}
	}
	if auxiliaryInstanceVars != nil {
		return auxiliaryInstanceVars[receiver][name]
	}
	return nil
}

func setDynamicInstanceVar(receiver *object.EmeraldValue, name string, value *object.EmeraldValue) *object.EmeraldValue {
	if receiver == nil {
		return nil
	}
	if attrWriteFrozen(receiver) {
		return instanceVariableFrozenError(receiver)
	}
	switch receiver.Type {
	case object.ValueObject:
		if data, ok := receiver.Data.(*ioShimData); ok && name == "@close_exception" {
			data.closeHook = true
			data.closeException = value
			return nil
		}
		if obj, ok := receiver.Data.(*object.Object); ok {
			obj.SetInstanceVar(name, value)
			return nil
		}
	case object.ValueHash:
		if hash := hashData(receiver); hash != nil {
			if hash.InstanceVars == nil {
				hash.InstanceVars = make(map[string]*object.EmeraldValue)
			}
			hash.InstanceVars[name] = value
			return nil
		}
	case object.ValueException:
		if exc, ok := receiver.Data.(*object.RException); ok {
			if exc.InstanceVars == nil {
				exc.InstanceVars = make(map[string]*object.EmeraldValue)
			}
			exc.InstanceVars[name] = value
			return nil
		}
	case object.ValueProc:
		if proc, ok := receiver.Data.(*object.Proc); ok {
			if proc.InstanceVars == nil {
				proc.InstanceVars = make(map[string]*object.EmeraldValue)
			}
			proc.InstanceVars[name] = value
			return nil
		}
	case object.ValueClass:
		if cls, ok := receiver.Data.(*object.Class); ok {
			cls.SetInstanceVar(name, value)
			return nil
		}
	case object.ValueModule:
		if mod, ok := receiver.Data.(*object.Module); ok {
			mod.InstanceVars[name] = value
			return nil
		}
	}
	receiverInstanceVarMap(receiver)[name] = value
	return nil
}

func DynamicInstanceVar(receiver *object.EmeraldValue, name string) *object.EmeraldValue {
	return dynamicInstanceVar(receiver, name)
}

func SetDynamicInstanceVar(receiver *object.EmeraldValue, name string, value *object.EmeraldValue) *object.EmeraldValue {
	return setDynamicInstanceVar(receiver, name, value)
}

func instanceVariableFrozenError(receiver *object.EmeraldValue) *object.EmeraldValue {
	if receiver == nil {
		return frozenError("can't modify frozen object")
	}
	className := receiver.TypeName()
	if receiver.Type == object.ValueObject && receiver.Class != nil && receiver.Class.Name != "" {
		className = receiver.Class.Name
	}
	return frozenError(fmt.Sprintf("can't modify frozen %s: %s", className, receiver.Inspect()))
}

func methodInstanceOf(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) < 1 {
		return R.FalseVal
	}
	if args[0].Type != object.ValueClass && args[0].Type != object.ValueModule {
		return typeError("class or module required")
	}
	if args[0].Type == object.ValueModule {
		return R.FalseVal
	}
	expected := args[0].Data.(*object.Class)
	if receiver.Class != nil && (receiver.Class == expected || receiver.Class.Name == expected.Name) {
		return R.TrueVal
	}
	return R.FalseVal
}

func methodInitializeCopy(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) < 1 {
		return NewArgumentError("wrong number of arguments")
	}
	source := args[0]
	if receiver == source || sameImmediateValue(receiver, source) {
		return receiver
	}
	if attrWriteFrozen(receiver) {
		return instanceVariableFrozenError(receiver)
	}
	if receiver == nil || source == nil || receiver.Class == nil || source.Class == nil || receiver.Class != source.Class {
		return typeError("initialize_copy should take same class object")
	}
	return receiver
}

func methodInitializeDup(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 1 {
		return NewArgumentError("wrong number of arguments")
	}
	if CallMethod != nil {
		if result := CallMethod(receiver, "initialize_copy", args[0]); result != nil && result.Type == object.ValueException {
			return result
		}
	}
	return receiver
}

func methodInitializeClone(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) < 1 || len(args) > 2 {
		return NewArgumentError("wrong number of arguments")
	}
	if CallMethod != nil {
		if result := CallMethod(receiver, "initialize_copy", args[0]); result != nil && result.Type == object.ValueException {
			return result
		}
	}
	return receiver
}

func sameImmediateValue(left, right *object.EmeraldValue) bool {
	if left == nil || right == nil || left.Type != right.Type {
		return false
	}
	switch left.Type {
	case object.ValueBool, object.ValueInteger, object.ValueFloat, object.ValueSymbol, object.ValueNil:
		return left.Equals(right)
	default:
		return false
	}
}

func methodEqual(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) < 1 {
		return R.FalseVal
	}
	if receiver == args[0] {
		return R.TrueVal
	}
	if receiver != nil && args[0] != nil && receiver.Type == args[0].Type {
		switch receiver.Type {
		case object.ValueNil, object.ValueBool, object.ValueSymbol:
			if receiver.Equals(args[0]) {
				return R.TrueVal
			}
		case object.ValueInteger:
			if _, ok := NumericBigIntOverride(receiver); ok {
				return R.FalseVal
			}
			if _, ok := NumericBigIntOverride(args[0]); ok {
				return R.FalseVal
			}
			if receiver.Equals(args[0]) {
				return R.TrueVal
			}
		case object.ValueClass, object.ValueModule:
			if receiver.Data == args[0].Data {
				return R.TrueVal
			}
		}
	}
	return R.FalseVal
}

func methodNotEqual(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) < 1 {
		return R.TrueVal
	}
	result := methodEqual(receiver, args...)
	if CallMethod != nil {
		result = CallMethod(receiver, "==", args[0])
	}
	if result != nil && result.Type == object.ValueException {
		return result
	}
	return boolValue(!isTruthy(result))
}

func methodNot(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return boolValue(!isTruthy(receiver))
}

func methodCaseEqual(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) < 1 {
		return R.FalseVal
	}
	if receiver == args[0] {
		return R.TrueVal
	}
	if CallMethod != nil {
		return CallMethod(receiver, "==", args[0])
	}
	return methodEqual(receiver, args...)
}

func methodCompare(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) < 1 {
		return R.NilVal
	}
	if receiver == args[0] {
		return newInt(0)
	}
	if CallMethod != nil {
		equal := CallMethod(receiver, "==", args[0])
		if equal != nil && equal.Type != object.ValueException && equal.IsTruthy() {
			return newInt(0)
		}
	}
	return R.NilVal
}

func methodEql(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) < 1 {
		return R.FalseVal
	}
	if receiver == args[0] {
		return R.TrueVal
	}
	if receiver != nil && args[0] != nil && receiver.Type == args[0].Type {
		switch receiver.Type {
		case object.ValueString, object.ValueInteger, object.ValueFloat, object.ValueSymbol, object.ValueBool, object.ValueNil:
			return boolValue(receiver.Equals(args[0]))
		}
	}
	return R.FalseVal
}

func methodRespondTo(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) < 1 || receiver == nil {
		return R.FalseVal
	}
	methodName, ok, nameErr := methodNameFromValueWithError(args[0])
	if nameErr != nil {
		return nameErr
	}
	if !ok {
		return typeError("is not a symbol nor a string")
	}
	if methodName == "" {
		return R.FalseVal
	}
	includePrivate := false
	if len(args) > 1 {
		includePrivate = args[1] != nil && args[1].Type == object.ValueBool && args[1].Data.(bool)
	}

	checkVisibility := func(method *object.Method) bool {
		if method == nil {
			return false
		}
		if method.Visibility == "undefined" {
			return false
		}
		if !includePrivate && (method.Visibility == "private" || method.Visibility == "protected") {
			return false
		}
		return true
	}
	if ActiveRefinedMethod != nil {
		if method, found := ActiveRefinedMethod(receiver, methodName); found {
			return boolValue(checkVisibility(method))
		}
	}
	if singleton := existingSingletonClass(receiver); singleton != nil {
		if method, _, found := singleton.GetMethodWithOwner(methodName); found {
			return boolValue(checkVisibility(method))
		}
	}

	switch receiver.Type {
	case object.ValueObject:
		if obj, ok := receiver.Data.(*object.Object); ok {
			if method, found := obj.SingletonMethods[methodName]; found {
				if checkVisibility(method) {
					return R.TrueVal
				}
				return R.FalseVal
			}
			if obj.SingletonClass != nil {
				for _, mod := range obj.SingletonClass.PrependedModules {
					if method, _, ok := lookupModuleMethodWithOwner(mod, methodName); ok {
						if checkVisibility(method) {
							return R.TrueVal
						}
						return R.FalseVal
					}
				}
				if method, found := obj.SingletonClass.Methods[methodName]; found {
					if checkVisibility(method) {
						return R.TrueVal
					}
					return R.FalseVal
				}
				for _, mod := range obj.SingletonClass.IncludedModules {
					if method, _, ok := lookupModuleMethodWithOwner(mod, methodName); ok {
						if checkVisibility(method) {
							return R.TrueVal
						}
						return R.FalseVal
					}
				}
			}
		}
	case object.ValueClass:
		if cls, ok := receiver.Data.(*object.Class); ok {
			if method, _, found := lookupClassReceiverMethod(cls, methodName); found {
				if checkVisibility(method) {
					return R.TrueVal
				}
				return R.FalseVal
			}
		}
	case object.ValueModule:
		if mod, ok := receiver.Data.(*object.Module); ok {
			if mod.SingletonClass != nil {
				for _, singletonMod := range mod.SingletonClass.PrependedModules {
					if method, _, ok := lookupModuleMethodWithOwner(singletonMod, methodName); ok {
						if checkVisibility(method) {
							return R.TrueVal
						}
						return R.FalseVal
					}
				}
				if method, found := mod.SingletonClass.Methods[methodName]; found {
					if checkVisibility(method) {
						return R.TrueVal
					}
					return R.FalseVal
				}
				for _, singletonMod := range mod.SingletonClass.IncludedModules {
					if method, _, ok := lookupModuleMethodWithOwner(singletonMod, methodName); ok {
						if checkVisibility(method) {
							return R.TrueVal
						}
						return R.FalseVal
					}
				}
			}
		}
	}

	if receiver.Class != nil {
		if method, ok := receiver.Class.GetMethod(methodName); ok && checkVisibility(method) {
			return R.TrueVal
		}
	}
	if receiver != nil {
		if !receiverHasCallableMethod(receiver, "respond_to_missing?") {
			return R.FalseVal
		}
		call := CallMethodBypass
		if call == nil {
			call = CallMethod
		}
		if call == nil {
			return R.FalseVal
		}
		respondToMissing := call(receiver, "respond_to_missing?", &object.EmeraldValue{
			Type:  object.ValueSymbol,
			Data:  methodName,
			Class: R.Classes["Symbol"],
		}, &object.EmeraldValue{Type: object.ValueBool, Data: includePrivate, Class: R.Classes["Boolean"]})
		if respondToMissing != nil && respondToMissing.Type == object.ValueException {
			return respondToMissing
		}
		if isTruthy(respondToMissing) {
			return R.TrueVal
		}
	}

	return R.FalseVal
}

func methodRespondToMissing(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return R.FalseVal
}

func methodMethods(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	includeInherited := includeInheritedMethods(args...)
	names := map[string]bool{}
	shadowed := map[string]bool{}
	if receiver != nil && receiver.Type == object.ValueObject {
		if obj, ok := receiver.Data.(*object.Object); ok {
			for name, method := range obj.SingletonMethods {
				if method == nil || method.Visibility == "undefined" {
					continue
				}
				names[name] = true
			}
			if obj.SingletonClass != nil {
				for _, mod := range obj.SingletonClass.PrependedModules {
					collectModuleMethodNames(mod, names, shadowed)
				}
				for name, method := range obj.SingletonClass.Methods {
					if shadowed[name] {
						continue
					}
					if method == nil || method.Visibility == "undefined" || method.Visibility == "private" {
						if _, existed := names[name]; existed {
							delete(names, name)
						}
						shadowed[name] = true
						continue
					}
					if _, exists := names[name]; !exists {
						names[name] = true
					}
				}
				for _, mod := range obj.SingletonClass.IncludedModules {
					collectModuleMethodNames(mod, names, shadowed)
				}
			}
		}
	}
	if receiver != nil && receiver.Type == object.ValueClass {
		if class, ok := receiver.Data.(*object.Class); ok {
			collectClassReceiverMethodNames(class, names, includeInherited)
		}
	}
	if receiver != nil && receiver.Type == object.ValueModule {
		if mod, ok := receiver.Data.(*object.Module); ok {
			if mod.SingletonClass != nil {
				for _, modModule := range mod.SingletonClass.PrependedModules {
					collectModuleMethodNames(modModule, names, shadowed)
				}
				for name, method := range mod.SingletonClass.Methods {
					if shadowed[name] {
						continue
					}
					if method == nil || method.Visibility == "undefined" || method.Visibility == "private" {
						if _, existed := names[name]; existed {
							delete(names, name)
						}
						shadowed[name] = true
						continue
					}
					if _, exists := names[name]; !exists {
						names[name] = true
					}
				}
				for _, modModule := range mod.SingletonClass.IncludedModules {
					collectModuleMethodNames(modModule, names, shadowed)
				}
			}
		}
	}
	if receiver != nil && receiver.Class != nil {
		if includeInherited {
			collectClassMethodNames(receiver.Class, names)
		}
	}
	result := make([]*object.EmeraldValue, 0, len(names))
	for name := range names {
		result = append(result, &object.EmeraldValue{Type: object.ValueSymbol, Data: name, Class: R.Classes["Symbol"]})
	}
	sort.Slice(result, func(i, j int) bool {
		return result[i].Data.(string) < result[j].Data.(string)
	})
	return &object.EmeraldValue{Type: object.ValueArray, Data: result, Class: R.Classes["Array"]}
}

func methodSingletonMethods(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	includeInherited := includeInheritedMethods(args...)
	names := map[string]bool{}
	shadowed := map[string]bool{}
	if receiver != nil && receiver.Type == object.ValueObject {
		if obj, ok := receiver.Data.(*object.Object); ok {
			collectPublicProtectedMethodMap(obj.SingletonMethods, names, shadowed)
			if obj.SingletonClass != nil {
				collectPublicProtectedMethodMap(obj.SingletonClass.Methods, names, shadowed)
				if includeInherited {
					for _, mod := range obj.SingletonClass.IncludedModules {
						collectModuleMethodNames(mod, names, shadowed)
					}
				}
			}
		}
	}
	if receiver != nil && receiver.Type == object.ValueClass {
		if class, ok := receiver.Data.(*object.Class); ok {
			if includeInherited {
				collectClassReceiverMethodNames(class, names, true)
			} else {
				if class.SingletonClass != nil {
					collectPublicProtectedMethodMap(class.SingletonClass.Methods, names, shadowed)
				}
				collectPublicProtectedMethodMap(class.ClassMethods, names, shadowed)
			}
		}
	}
	if receiver != nil && receiver.Type == object.ValueModule {
		if mod, ok := receiver.Data.(*object.Module); ok && mod.SingletonClass != nil {
			collectPublicProtectedMethodMap(mod.SingletonClass.Methods, names, shadowed)
		}
	}
	result := make([]*object.EmeraldValue, 0, len(names))
	for name := range names {
		result = append(result, &object.EmeraldValue{Type: object.ValueSymbol, Data: name, Class: R.Classes["Symbol"]})
	}
	sort.Slice(result, func(i, j int) bool {
		return result[i].Data.(string) < result[j].Data.(string)
	})
	return &object.EmeraldValue{Type: object.ValueArray, Data: result, Class: R.Classes["Array"]}
}

func methodPublicMethods(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return methodVisibilityList(receiver, "public", args...)
}

func methodPrivateMethods(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return methodVisibilityList(receiver, "private", args...)
}

func methodProtectedMethods(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return methodVisibilityList(receiver, "protected", args...)
}

func methodVisibilityList(receiver *object.EmeraldValue, visibility string, args ...*object.EmeraldValue) *object.EmeraldValue {
	includeInherited := includeInheritedMethods(args...)
	names := map[string]bool{}
	shadowed := map[string]bool{}
	if receiver != nil && receiver.Type == object.ValueObject {
		if obj, ok := receiver.Data.(*object.Object); ok {
			collectMethodMapForVisibility(obj.SingletonMethods, visibility, names, shadowed)
			if obj.SingletonClass != nil {
				collectSingletonClassForVisibility(obj.SingletonClass, visibility, names, shadowed)
			}
		}
	}
	if receiver != nil && receiver.Type == object.ValueClass {
		if class, ok := receiver.Data.(*object.Class); ok {
			collectClassReceiverMethodNamesForVisibility(class, visibility, names, includeInherited)
		}
	}
	if receiver != nil && receiver.Type == object.ValueModule {
		if mod, ok := receiver.Data.(*object.Module); ok {
			if mod.SingletonClass != nil {
				collectSingletonClassForVisibility(mod.SingletonClass, visibility, names, shadowed)
			}
		}
	}
	if receiver != nil && receiver.Class != nil && (includeInherited || (receiver.Type != object.ValueClass && receiver.Type != object.ValueModule)) {
		collectClassMethodNamesForVisibility(receiver.Class, visibility, names, includeInherited)
	}
	result := make([]*object.EmeraldValue, 0, len(names))
	for name := range names {
		result = append(result, &object.EmeraldValue{Type: object.ValueSymbol, Data: name, Class: R.Classes["Symbol"]})
	}
	sort.Slice(result, func(i, j int) bool {
		return result[i].Data.(string) < result[j].Data.(string)
	})
	return &object.EmeraldValue{Type: object.ValueArray, Data: result, Class: R.Classes["Array"]}
}

func collectSingletonClassForVisibility(class *object.Class, visibility string, names map[string]bool, shadowed map[string]bool) {
	if class == nil {
		return
	}
	for _, mod := range class.PrependedModules {
		collectModuleMethodNamesForVisibility(mod, visibility, names, shadowed)
	}
	collectMethodMapForVisibility(class.Methods, visibility, names, shadowed)
	for _, mod := range class.IncludedModules {
		collectModuleMethodNamesForVisibility(mod, visibility, names, shadowed)
	}
}

func collectClassMethodNamesForVisibility(class *object.Class, visibility string, names map[string]bool, includeInherited bool) {
	if class == nil {
		return
	}
	shadowed := map[string]bool{}
	if !includeInherited {
		collectMethodMapForVisibility(class.Methods, visibility, names, shadowed)
		return
	}
	for current := class; current != nil; current = current.SuperClass {
		for _, mod := range current.PrependedModules {
			collectModuleMethodNamesForVisibility(mod, visibility, names, shadowed)
		}
		collectMethodMapForVisibility(current.Methods, visibility, names, shadowed)
		for _, mod := range current.IncludedModules {
			collectModuleMethodNamesForVisibility(mod, visibility, names, shadowed)
		}
	}
}

func collectClassReceiverMethodNamesForVisibility(class *object.Class, visibility string, names map[string]bool, includeInherited bool) {
	if class == nil {
		return
	}
	shadowed := map[string]bool{}
	for current := class; current != nil; current = current.SuperClass {
		if current.SingletonClass != nil && includeInherited {
			collectSingletonClassForVisibility(current.SingletonClass, visibility, names, shadowed)
		} else if current.SingletonClass != nil {
			collectMethodMapForVisibility(current.SingletonClass.Methods, visibility, names, shadowed)
		}
		collectMethodMapForVisibility(current.ClassMethods, visibility, names, shadowed)
		if includeInherited {
			for _, mod := range current.IncludedModules {
				collectModuleMethodNamesForVisibility(mod, visibility, names, shadowed)
			}
		}
	}
}

func collectModuleMethodNamesForVisibility(module *object.Module, visibility string, names map[string]bool, shadowed map[string]bool) {
	if module == nil {
		return
	}
	for _, mod := range module.PrependedModules {
		collectModuleMethodNamesForVisibility(mod, visibility, names, shadowed)
	}
	collectMethodMapForVisibility(module.Methods, visibility, names, shadowed)
	for _, included := range module.IncludedModules {
		collectModuleMethodNamesForVisibility(included, visibility, names, shadowed)
	}
}

func collectMethodMapForVisibility(methods map[string]*object.Method, visibility string, names map[string]bool, shadowed map[string]bool) {
	for name, method := range methods {
		if shadowed[name] {
			continue
		}
		if method == nil || method.Visibility == "undefined" {
			delete(names, name)
			shadowed[name] = true
			continue
		}
		if methodVisibility(method) == visibility {
			names[name] = true
			continue
		}
		if method.Visibility == "private" || method.Visibility == "protected" {
			shadowed[name] = true
		}
	}
}

func collectPublicProtectedMethodMap(methods map[string]*object.Method, names map[string]bool, shadowed map[string]bool) {
	for name, method := range methods {
		if shadowed[name] {
			continue
		}
		if method == nil || method.Visibility == "undefined" || method.Visibility == "private" {
			delete(names, name)
			shadowed[name] = true
			continue
		}
		names[name] = true
	}
}

func collectClassMethodNames(class *object.Class, names map[string]bool) {
	if class == nil {
		return
	}
	shadowed := map[string]bool{}
	for current := class; current != nil; current = current.SuperClass {
		for _, mod := range current.PrependedModules {
			collectModuleMethodNames(mod, names, shadowed)
		}
		for name, method := range current.Methods {
			if shadowed[name] {
				continue
			}
			if method == nil || method.Visibility == "undefined" || method.Visibility == "private" {
				delete(names, name)
				shadowed[name] = true
				continue
			}
			if _, exists := names[name]; !exists {
				names[name] = true
			}
		}
		for _, mod := range current.IncludedModules {
			collectModuleMethodNames(mod, names, shadowed)
		}
	}
}

func collectClassReceiverMethodNames(class *object.Class, names map[string]bool, includeInherited bool) {
	if class == nil {
		return
	}
	shadowed := map[string]bool{}
	for current := class; current != nil; current = current.SuperClass {
		if current.SingletonClass != nil {
			for _, mod := range current.SingletonClass.PrependedModules {
				collectModuleMethodNames(mod, names, shadowed)
			}
			for name, method := range current.SingletonClass.Methods {
				if shadowed[name] {
					continue
				}
				if method == nil || method.Visibility == "undefined" || method.Visibility == "private" {
					if _, existed := names[name]; existed {
						delete(names, name)
					}
					shadowed[name] = true
					continue
				}
				if _, exists := names[name]; !exists {
					names[name] = true
				}
			}
			for _, mod := range current.SingletonClass.IncludedModules {
				collectModuleMethodNames(mod, names, shadowed)
			}
		}
		for name, method := range current.ClassMethods {
			if shadowed[name] {
				continue
			}
			if method == nil || method.Visibility == "undefined" || method.Visibility == "private" {
				if _, existed := names[name]; existed {
					delete(names, name)
				}
				shadowed[name] = true
				continue
			}
			if _, exists := names[name]; !exists {
				names[name] = true
			}
		}
		if !includeInherited {
			break
		}
	}
}

func lookupClassReceiverMethod(class *object.Class, name string) (*object.Method, *object.EmeraldValue, bool) {
	for current := class; current != nil; current = current.SuperClass {
		if current.SingletonClass != nil {
			for _, mod := range current.SingletonClass.PrependedModules {
				if method, owner, ok := lookupModuleMethodWithOwner(mod, name); ok {
					return method, owner, true
				}
			}
			if method, ok := current.SingletonClass.Methods[name]; ok {
				return method, &object.EmeraldValue{Type: object.ValueClass, Data: current.SingletonClass, Class: R.Classes["Class"]}, true
			}
			for _, mod := range current.SingletonClass.IncludedModules {
				if method, owner, ok := lookupModuleMethodWithOwner(mod, name); ok {
					return method, owner, true
				}
			}
		}
		if method, ok := current.ClassMethods[name]; ok {
			return method, &object.EmeraldValue{Type: object.ValueClass, Data: current, Class: R.Classes["Class"]}, true
		}
	}
	return nil, nil, false
}

func collectModuleMethodNames(module *object.Module, names map[string]bool, shadowed map[string]bool) {
	if module == nil {
		return
	}
	for _, mod := range module.PrependedModules {
		collectModuleMethodNames(mod, names, shadowed)
	}
	for name, method := range module.Methods {
		if shadowed[name] {
			continue
		}
		if method == nil || method.Visibility == "undefined" || method.Visibility == "private" {
			delete(names, name)
			shadowed[name] = true
			continue
		}
		names[name] = true
	}
	for _, included := range module.IncludedModules {
		collectModuleMethodNames(included, names, shadowed)
	}
}

func methodSend(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) < 1 {
		return argumentError("wrong number of arguments")
	}
	methodName, ok, parseErr := methodNameFromValueWithError(args[0])
	if parseErr != nil {
		return parseErr
	}
	if !ok {
		return typeError("is not a symbol nor a string")
	}
	forwardArgs := args[1:]
	if CallMethodWithBlock != nil && BlockGivenCheck != nil && BlockGivenCheck() && CurrentBlockValue != nil && CurrentBlockValue() != nil {
		return CallMethodWithBlock(receiver, methodName, CurrentBlockValue(), forwardArgs...)
	}
	if CallMethod != nil {
		return CallMethod(receiver, methodName, forwardArgs...)
	}
	return R.NilVal
}

