func timeStrftime(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 1 {
		return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 1)", len(args)))
	}
	if args[0] == nil || args[0].Type != object.ValueString {
		return typeError("no implicit conversion into String")
	}
	format := args[0].Data.(string)
	if strings.IndexByte(format, 0) >= 0 {
		return NewArgumentError("string contains null byte")
	}
	t, ok := timeValueFrom(receiver)
	if !ok {
		return typeError("uninitialized Time")
	}
	if format == "%Z" {
		if data, ok := receiver.Data.(*timeData); ok && data.zone != nil && receiverHasCallableMethod(data.zone, "abbr") {
			if abbreviation := CallMethod(data.zone, "abbr", receiver); abbreviation != nil && abbreviation.Type == object.ValueString {
				return stringWithEncoding(abbreviation.Data.(string), stringEncodingName(args[0]))
			}
		}
	}
	var fraction *big.Rat
	if data, ok := receiver.Data.(*timeData); ok {
		fraction = data.subsecond
	}
	return stringWithEncoding(formatRubyTime(t, format, fraction), stringEncodingName(args[0]))
}

func formatRubyTime(t time.Time, format string, fractions ...*big.Rat) string {
	var fraction *big.Rat
	if len(fractions) > 0 {
		fraction = fractions[0]
	}
	var result strings.Builder
	for index := 0; index < len(format); index++ {
		if format[index] != '%' || index+1 >= len(format) {
			result.WriteByte(format[index])
			continue
		}
		index++
		flags := ""
		pad := byte(0)
		noPad := false
		for index < len(format) && strings.ContainsRune("-_0^#", rune(format[index])) {
			flag := format[index]
			flags += string(flag)
			if flag == '-' {
				noPad = true
			} else if flag == '_' {
				pad = ' '
			} else if flag == '0' {
				pad = '0'
			}
			index++
		}
		width := 0
		for index < len(format) && format[index] >= '0' && format[index] <= '9' {
			width = width*10 + int(format[index]-'0')
			index++
		}
		colons := 0
		for index < len(format) && format[index] == ':' {
			colons++
			index++
		}
		if index < len(format) && (format[index] == 'E' || format[index] == 'O') {
			index++
		}
		if index >= len(format) {
			result.WriteByte('%')
			break
		}
		directive := format[index]
		text, defaultWidth, defaultPad := rubyTimeDirective(t, directive, width, colons, noPad, pad, fraction)
		if strings.ContainsAny(flags, "^#") {
			text = strings.ToUpper(text)
		}
		if directive != 'N' && directive != 'z' {
			targetWidth := defaultWidth
			if width > 0 {
				targetWidth = width
			}
			if pad == 0 {
				pad = defaultPad
			}
			if !noPad && targetWidth > len(text) {
				text = strings.Repeat(string(pad), targetWidth-len(text)) + text
			}
		}
		result.WriteString(text)
	}
	return result.String()
}

func rubyTimeDirective(t time.Time, directive byte, width, colons int, noPad bool, pad byte, fraction *big.Rat) (string, int, byte) {
	hour12 := t.Hour() % 12
	if hour12 == 0 {
		hour12 = 12
	}
	isoYear, isoWeek := t.ISOWeek()
	weekday := int(t.Weekday())
	yday := t.YearDay() - 1
	weekU := (yday + 7 - weekday) / 7
	mondayWeekday := (weekday + 6) % 7
	weekW := (yday + 7 - mondayWeekday) / 7
	number := func(value int) string { return strconv.Itoa(value) }
	switch directive {
	case '%':
		return "%", 0, ' '
	case 'A':
		return t.Format("Monday"), 0, ' '
	case 'a':
		return t.Format("Mon"), 0, ' '
	case 'B':
		return t.Format("January"), 0, ' '
	case 'b', 'h':
		return t.Format("Jan"), 0, ' '
	case 'C':
		return number(t.Year() / 100), 2, '0'
	case 'd':
		return number(t.Day()), 2, '0'
	case 'e':
		return number(t.Day()), 2, ' '
	case 'G':
		return number(isoYear), 4, '0'
	case 'g':
		return number((isoYear%100 + 100) % 100), 2, '0'
	case 'H':
		return number(t.Hour()), 2, '0'
	case 'I':
		return number(hour12), 2, '0'
	case 'j':
		return number(t.YearDay()), 3, '0'
	case 'k':
		return number(t.Hour()), 2, ' '
	case 'l':
		return number(hour12), 2, ' '
	case 'M':
		return number(t.Minute()), 2, '0'
	case 'm':
		return number(int(t.Month())), 2, '0'
	case 'n':
		return "\n", 0, ' '
	case 'P':
		return strings.ToLower(t.Format("PM")), 0, ' '
	case 'p':
		return t.Format("PM"), 0, ' '
	case 'S':
		return number(t.Second()), 2, '0'
	case 's':
		return strconv.FormatInt(t.Unix(), 10), 0, ' '
	case 't':
		return "\t", 0, ' '
	case 'U':
		return number(weekU), 2, '0'
	case 'W':
		return number(weekW), 2, '0'
	case 'u':
		if weekday == 0 {
			weekday = 7
		}
		return number(weekday), 0, ' '
	case 'V':
		return number(isoWeek), 2, '0'
	case 'w':
		return number(weekday), 0, ' '
	case 'Y':
		return number(t.Year()), 4, '0'
	case 'y':
		return number((t.Year()%100 + 100) % 100), 2, '0'
	case 'Z':
		zone, _ := t.Zone()
		return zone, 0, ' '
	case 'z':
		return rubyTimeZoneOffset(t, colons, noPad, width, pad), 0, ' '
	case 'c':
		return formatRubyTime(t, "%a %b %e %H:%M:%S %Y"), 0, ' '
	case 'D', 'x':
		return formatRubyTime(t, "%m/%d/%y"), 0, ' '
	case 'F':
		return formatRubyTime(t, "%Y-%m-%d"), 0, ' '
	case 'R':
		return formatRubyTime(t, "%H:%M"), 0, ' '
	case 'r':
		return formatRubyTime(t, "%I:%M:%S %p"), 0, ' '
	case 'T', 'X':
		return formatRubyTime(t, "%H:%M:%S"), 0, ' '
	case 'v':
		return strings.ToUpper(formatRubyTime(t, "%e-%b-%Y")), 0, ' '
	case 'L':
		return fmt.Sprintf("%03d", t.Nanosecond()/1_000_000), 0, ' '
	case 'N':
		precision := width
		if precision == 0 {
			precision = 9
		}
		if fraction != nil {
			scale := new(big.Int).Exp(big.NewInt(10), big.NewInt(int64(precision)), nil)
			numerator := new(big.Int).Mul(fraction.Num(), scale)
			digits := new(big.Int).Quo(numerator, fraction.Denom()).String()
			if len(digits) < precision {
				digits = strings.Repeat("0", precision-len(digits)) + digits
			}
			return digits, 0, ' '
		}
		nanos := fmt.Sprintf("%09d", t.Nanosecond())
		if precision <= 9 {
			return nanos[:precision], 0, ' '
		}
		return nanos + strings.Repeat("0", precision-9), 0, ' '
	case 'Q':
		return strconv.FormatInt(t.UnixMilli(), 10), 0, ' '
	default:
		return "%" + string(directive), 0, ' '
	}
}

func rubyTimeZoneOffset(t time.Time, colons int, negativeZero bool, width int, pad byte) string {
	_, offset := t.Zone()
	sign := "+"
	if offset < 0 || (offset == 0 && negativeZero) {
		sign = "-"
	}
	if offset < 0 {
		offset = -offset
	}
	hours := offset / 3600
	minutes := (offset % 3600) / 60
	seconds := offset % 60
	hourWidth := 2
	if negativeZero && width > 0 {
		hourWidth = 1
	}
	text := ""
	switch colons {
	case 0:
		text = fmt.Sprintf("%s%0*d%02d", sign, hourWidth, hours, minutes)
	case 1:
		text = fmt.Sprintf("%s%0*d:%02d", sign, hourWidth, hours, minutes)
	default:
		text = fmt.Sprintf("%s%0*d:%02d:%02d", sign, hourWidth, hours, minutes, seconds)
	}
	if width > len(text) {
		if pad == ' ' {
			text = strings.Repeat(" ", width-len(text)) + text
		} else {
			text = text[:1] + strings.Repeat("0", width-len(text)) + text[1:]
		}
	}
	return text
}

func objectDeconstructKeys(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 0 {
		return argumentError("wrong number of arguments (given 0, expected 1)")
	}
	if args[0] != R.NilVal && args[0].Type != object.ValueArray {
		return typeError("wrong argument type " + valueTypeName(args[0]) + " (expected Array)")
	}
	if args[0] != R.NilVal {
		for _, key := range args[0].Data.([]*object.EmeraldValue) {
			if key == nil || key.Type != object.ValueSymbol {
				return typeError("wrong argument type " + valueTypeName(key) + " (expected Symbol)")
			}
		}
	}
	return &object.EmeraldValue{
		Type:  object.ValueHash,
		Data:  map[*object.EmeraldValue]*object.EmeraldValue{},
		Class: R.Classes["Hash"],
	}
}

