func threadFetch(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data := threadValueData(receiver)
	if data == nil {
		return R.NilVal
	}
	if len(args) < 1 || len(args) > 2 {
		return argumentError("wrong number of arguments")
	}
	key, ok := threadLocalKey(args[0])
	if !ok {
		return threadLocalKeyTypeError()
	}
	if value, exists := threadLocalValues(receiver, false)[key]; exists {
		return value
	}
	if CallBlock != nil && BlockGivenCheck != nil && BlockGivenCheck() {
		return CallBlock(args[0])
	}
	if len(args) == 2 {
		return args[1]
	}
	return newRuntimeException(R.Classes["KeyError"], "key not found")
}

func threadLocalValues(receiver *object.EmeraldValue, create bool) map[string]*object.EmeraldValue {
	data := threadValueData(receiver)
	if data == nil {
		return nil
	}
	if receiver == currentThread && currentFiber != nil {
		if fiber, ok := currentFiber.Data.(*fiberData); ok && fiber != nil && fiber.block != nil {
			if fiber.locals == nil && create {
				fiber.locals = make(map[string]*object.EmeraldValue)
			}
			return fiber.locals
		}
	}
	if data.locals == nil && create {
		data.locals = make(map[string]*object.EmeraldValue)
	}
	return data.locals
}

