func currentSourcePath() string {
	if CurrentSpecFile != "" {
		return CurrentSpecFile
	}
	return "spec.rb"
}

func currentBacktraceFramesOrEmpty() []object.RBacktraceLocation {
	if CurrentBacktraceFrames == nil {
		return []object.RBacktraceLocation{{Path: currentSourcePath(), Line: 1, Label: "main"}}
	}
	frames := CurrentBacktraceFrames()
	if len(frames) == 0 {
		return []object.RBacktraceLocation{{Path: currentSourcePath(), Line: 1, Label: "main"}}
	}
	result := append([]object.RBacktraceLocation{}, frames...)
	for i := range result {
		if result[i].Path == "" {
			result[i].Path = currentSourcePath()
		}
		if result[i].Line <= 0 {
			result[i].Line = 1
		}
		if result[i].Label == "" {
			result[i].Label = "main"
		}
	}
	result = maybeInsertMspecRunnerFrame(result, true)
	return result
}

func maybeInsertMspecRunnerFrame(frames []object.RBacktraceLocation, allowShallow bool) []object.RBacktraceLocation {
	if os.Getenv("MSPEC_RUNNER") == "" || (!allowShallow && len(frames) < 3) {
		return frames
	}
	specPath := filepath.ToSlash(CurrentSpecFile)
	specMarker := "/vendor/ruby/spec/"
	if !strings.HasSuffix(specPath, "_spec.rb") || (!strings.Contains(specPath, specMarker) && !strings.HasPrefix(specPath, "vendor/ruby/spec/")) {
		return frames
	}
	for _, frame := range frames {
		if strings.Contains(filepath.ToSlash(frame.Path), "runner/mspec.rb") {
			return frames
		}
	}
	runnerPath := filepath.Join("vendor", "ruby", "mspec", "lib", "mspec", "runner", "mspec.rb")
	if idx := strings.Index(specPath, specMarker); idx >= 0 {
		root := specPath[:idx]
		runnerPath = filepath.FromSlash(root + "/vendor/ruby/mspec/lib/mspec/runner/mspec.rb")
	}
	runnerFrame := object.RBacktraceLocation{Path: runnerPath, Line: 1, Label: "run"}
	insertAt := 2
	if insertAt > len(frames) {
		insertAt = len(frames)
	}
	extra := 1
	if len(frames) <= 2 {
		extra = 2
	}
	out := make([]object.RBacktraceLocation, 0, len(frames)+extra)
	out = append(out, frames[:insertAt]...)
	out = append(out, runnerFrame)
	if len(frames) <= 2 {
		out = append(out, object.RBacktraceLocation{Path: runnerPath, Line: 1, Label: "process"})
	}
	out = append(out, frames[insertAt:]...)
	return out
}

func backtraceString(frame object.RBacktraceLocation) string {
	return fmt.Sprintf("%s:%d:in '%s'", frame.Path, frame.Line, frame.Label)
}

func backtraceStrings(frames []object.RBacktraceLocation) []string {
	result := make([]string, len(frames))
	for i, frame := range frames {
		result[i] = backtraceString(frame)
	}
	return result
}

func backtraceStringsValue(frames []object.RBacktraceLocation) *object.EmeraldValue {
	result := make([]*object.EmeraldValue, len(frames))
	for i, bt := range frames {
		result[i] = rubyString(backtraceString(bt))
	}
	return &object.EmeraldValue{
		Type:  object.ValueArray,
		Data:  result,
		Class: R.Classes["Array"],
	}
}

