func threadBacktraceLocationLabel(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	frame, ok := backtraceLocationFrame(receiver)
	if !ok {
		return R.NilVal
	}
	return rubyString(frame.Label)
}

func threadBacktraceLocationBaseLabel(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	frame, ok := backtraceLocationFrame(receiver)
	if !ok {
		return R.NilVal
	}
	if frame.Label == "__singleton_class__#body" {
		return rubyString("singleton class")
	}
	label := frame.Label
	if index := strings.Index(label, " in "); strings.HasPrefix(label, "block") && index >= 0 {
		label = label[index+4:]
	}
	if !strings.HasPrefix(label, "<") {
		if index := strings.LastIndexAny(label, "#."); index >= 0 {
			label = label[index+1:]
		}
	}
	return rubyString(label)
}

func threadBacktraceLocationToS(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	frame, ok := backtraceLocationFrame(receiver)
	if !ok {
		return R.NilVal
	}
	return rubyString(backtraceString(frame))
}

func threadBacktraceLocationInspect(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	frame, ok := backtraceLocationFrame(receiver)
	if !ok {
		return R.NilVal
	}
	return rubyString(fmt.Sprintf("#<Thread::Backtrace::Location: %s>", backtraceString(frame)))
}

func threadAlive(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data := threadValueData(receiver)
	if data != nil && !data.finished {
		return R.TrueVal
	}
	return R.FalseVal
}

func threadStatus(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data := threadValueData(receiver)
	if data == nil {
		return R.NilVal
	}
	threadCollectAsyncRubyExe(data, false)
	if data.finished {
		if data.exception != nil {
			return R.NilVal
		}
		return R.FalseVal
	}
	if data.stopped {
		return rubyString("sleep")
	}
	if data.terminating {
		return rubyString("aborting")
	}
	return rubyString("run")
}

func threadToS(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data := threadValueData(receiver)
	status := "run"
	path := currentSourcePath()
	line := int64(1)
	if data != nil {
		if data.finished {
			status = "dead"
		} else if data.stopped {
			status = "sleep"
		} else if data.terminating {
			status = "aborting"
		}
		if data.sourcePath != "" {
			path = data.sourcePath
		}
		if data.sourceLine > 0 {
			line = data.sourceLine
		}
	}
	return stringWithEncoding(fmt.Sprintf("#<Thread:%p %s:%d %s>", receiver, path, line, status), "BINARY")
}

func threadNativeThreadID(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data := threadValueData(receiver)
	if receiver == currentThread || (data != nil && !data.ran) {
		return &object.EmeraldValue{Type: object.ValueInteger, Data: int64(1), Class: R.Classes["Integer"]}
	}
	return R.NilVal
}

func newThreadGroup() *object.EmeraldValue {
	return &object.EmeraldValue{
		Type:  object.ValueObject,
		Data:  &threadGroupData{},
		Class: R.Classes["ThreadGroup"],
	}
}

func threadGroupClassNew(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return newThreadGroup()
}

func DefaultThreadGroup() *object.EmeraldValue {
	if defaultThreadGroup == nil {
		defaultThreadGroup = newThreadGroup()
	}
	return defaultThreadGroup
}

func threadGroup(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return ensureThreadGroup(receiver)
}

func ensureThreadGroup(thread *object.EmeraldValue) *object.EmeraldValue {
	data := threadValueData(thread)
	if data == nil {
		return R.NilVal
	}
	if data.group == nil {
		data.group = defaultThreadGroup
		addThreadToGroup(defaultThreadGroup, thread)
	}
	return data.group
}

func threadGroupAdd(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 0 {
		return receiver
	}
	thread := args[0]
	data := threadValueData(thread)
	if data == nil {
		return receiver
	}
	oldGroup := ensureThreadGroup(thread)
	if groupData, ok := oldGroup.Data.(*threadGroupData); ok && groupData.enclosed && oldGroup != receiver {
		return threadError("can't move from the enclosed thread group")
	}
	removeThreadFromGroup(oldGroup, thread)
	data.group = receiver
	addThreadToGroup(receiver, thread)
	return receiver
}

func threadGroupList(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data, _ := receiver.Data.(*threadGroupData)
	threads := []*object.EmeraldValue{}
	if data != nil {
		threads = append(threads, data.threads...)
	}
	return &object.EmeraldValue{Type: object.ValueArray, Data: threads, Class: R.Classes["Array"]}
}

func threadGroupEnclose(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if data, ok := receiver.Data.(*threadGroupData); ok {
		data.enclosed = true
	}
	return receiver
}

func threadGroupEnclosed(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if data, ok := receiver.Data.(*threadGroupData); ok && data.enclosed {
		return R.TrueVal
	}
	return R.FalseVal
}

func addThreadToGroup(group, thread *object.EmeraldValue) {
	if group == nil || thread == nil {
		return
	}
	data, _ := group.Data.(*threadGroupData)
	if data == nil {
		return
	}
	for _, existing := range data.threads {
		if existing == thread {
			return
		}
	}
	data.threads = append(data.threads, thread)
}

func removeThreadFromGroup(group, thread *object.EmeraldValue) {
	if group == nil || thread == nil {
		return
	}
	data, _ := group.Data.(*threadGroupData)
	if data == nil {
		return
	}
	for i, existing := range data.threads {
		if existing == thread {
			data.threads = append(data.threads[:i], data.threads[i+1:]...)
			return
		}
	}
}

func threadStop(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data := threadValueData(receiver)
	if data == nil {
		return R.FalseVal
	}
	if data.finished || data.stopped {
		return R.TrueVal
	}
	return R.FalseVal
}

func threadClassStop(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	thread := threadClassCurrent(nil)
	data := threadValueData(thread)
	if data == nil {
		return threadError("stopping only thread")
	}
	data.stopped = true
	if SuspendCurrentThread != nil {
		return SuspendCurrentThread()
	}
	return threadBlockedResult
}

func threadWakeup(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data := threadValueData(receiver)
	if data == nil || data.finished {
		return threadError("killed thread")
	}
	if data.suspended || data.stopped {
		data.stopped = false
		queuePendingThread(receiver)
	}
	return receiver
}

func threadKill(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data := threadValueData(receiver)
	if data == nil || data.finished || data.terminating {
		return receiver
	}
	if data.pendingInterrupt != nil {
		return receiver
	}
	data.terminating = true
	if receiver == currentThread {
		return ThreadTerminationResult()
	}
	if data.suspended {
		data.terminationPending = true
		data.stopped = false
		queuePendingThread(receiver)
		return receiver
	}
	data.ran = true
	data.finished = true
	data.terminating = false
	releaseThreadMutexes(receiver)
	return receiver
}

func threadRaise(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data := threadValueData(receiver)
	if data == nil || data.finished {
		return R.NilVal
	}
	if data.deferInterrupt {
		exception, inject := buildThreadRaiseException(args)
		if !inject {
			return exception
		}
		data.pendingInterrupt = exception
		if data.interruptMode == "on_blocking" && data.blockingCall {
			data.deferInterrupt = false
			data.stopped = false
			queuePendingThread(receiver)
		}
		LastException = nil
		return receiver
	}
	if receiver == currentThread {
		exception, _ := buildThreadRaiseException(args)
		LastRaisedResult = exception
		return exception
	}

	previousException := LastException
	previousRaisedResult := LastRaisedResult
	previousMatcherException := LastMatcherException
	exception, inject := buildThreadRaiseException(args)
	LastException = previousException
	LastRaisedResult = previousRaisedResult
	LastMatcherException = previousMatcherException
	if !inject {
		return exception
	}
	data.pendingInterrupt = exception
	if len(args) == 0 || args[0] == nil || args[0].Type != object.ValueException {
		setThreadRaisedExceptionBacktrace(receiver, data, exception)
	}
	if data.suspended || data.stopped {
		data.stopped = false
		queuePendingThread(receiver)
	}
	return receiver
}

func setThreadRaisedExceptionBacktrace(thread *object.EmeraldValue, data *threadData, exception *object.EmeraldValue) {
	if exception == nil || exception.Type != object.ValueException {
		return
	}
	payload, ok := exception.Data.(*object.RException)
	if !ok || payload == nil {
		return
	}
	frames := []object.RBacktraceLocation{}
	if ThreadBacktraceFrames != nil {
		frames = ThreadBacktraceFrames(thread)
	}
	if data != nil && data.blockedLabel != "" {
		frames = prependBacktraceCallFrame(frames, data.blockedLabel)
	}
	if len(frames) == 0 {
		return
	}
	payload.Locations = frames
	payload.Backtrace = backtraceStrings(frames)
	payload.BacktraceValue = nil
}

func buildThreadRaiseException(args []*object.EmeraldValue) (*object.EmeraldValue, bool) {
	if len(args) > 0 {
		last := args[len(args)-1]
		if last != nil && last.Type == object.ValueHash && Ruby2KeywordHash(last) && dataEmptyHashArg(last) {
			args = args[:len(args)-1]
		}
	}
	if len(args) == 0 {
		return builtinRaise(nil, rubyString("")), true
	}
	if len(args) > 1 && args[0] != nil && args[0].Type == object.ValueString {
		last := args[len(args)-1]
		if last == nil || last.Type != object.ValueHash || !Ruby2KeywordHash(last) {
			return typeError("exception class/object expected"), false
		}
	}
	cause, hasCause, causeErr := raiseCauseKeyword(args)
	if causeErr != nil {
		return causeErr, false
	}
	positional := args
	if hasCause && args[len(args)-1] != nil && args[len(args)-1].Type == object.ValueHash && raiseHashHasCauseKeyword(args[len(args)-1]) {
		positional = args[:len(args)-1]
	}
	if len(positional) == 0 {
		return argumentError("only cause is given with no arguments"), false
	}
	if len(positional) > 3 {
		return argumentError("wrong number of arguments"), false
	}
	first := positional[0]
	valid := first != nil && (first.Type == object.ValueException || first.Type == object.ValueString)
	if first != nil && first.Type == object.ValueClass {
		class, _ := first.Data.(*object.Class)
		valid = class != nil && classInheritsFrom(class, R.Classes["Exception"])
	}
	if first != nil && !valid && CallMethod != nil && receiverHasCallableMethod(first, "exception") {
		valid = true
	}
	if !valid || (first.Type == object.ValueString && len(positional) > 1) {
		return typeError("exception class/object expected"), false
	}

	if first.Type == object.ValueException && len(positional) > 1 {
		exception := first
		if CallMethod != nil {
			exception = CallMethod(first, "exception", positional[1])
		}
		if exception == nil || exception.Type != object.ValueException {
			return typeError("exception object expected"), false
		}
		fillExceptionBacktrace(exception)
		if len(positional) == 3 {
			if result := exceptionSetBacktrace(exception, positional[2]); result != nil && result.Type == object.ValueException {
				return result, false
			}
		}
		if hasCause {
			if result := setExceptionCause(exception, cause); result != nil {
				return result, false
			}
		}
		if data, ok := exception.Data.(*object.RException); ok && data != nil {
			data.Raised = true
		}
		LastException = exception
		LastMatcherException = exception
		return exception, true
	}

	exception := builtinRaise(nil, args...)
	if exception == nil || exception.Type != object.ValueException {
		return typeError("exception object expected"), false
	}
	return exception, true
}

