func noMethodErrorReceiverDescription(receiver *object.EmeraldValue) string {
	if receiver == nil || receiver.Type == object.ValueNil {
		return "nil"
	}
	if receiver == R.TrueVal {
		return "true"
	}
	if receiver == R.FalseVal {
		return "false"
	}
	switch receiver.Type {
	case object.ValueClass:
		if cls, ok := receiver.Data.(*object.Class); ok {
			return "class " + classReceiverDisplayName(receiver, cls)
		}
	case object.ValueModule:
		if mod, ok := receiver.Data.(*object.Module); ok {
			return "module " + moduleReceiverDisplayName(receiver, mod)
		}
	case object.ValueObject:
		if obj, ok := receiver.Data.(*object.Object); ok && obj != nil {
			if obj.SingletonClass != nil || len(obj.SingletonMethods) > 0 {
				return objectInstanceInspect(receiver)
			}
		}
	}
	if receiver.Class != nil {
		return "an instance of " + classReceiverDisplayName(&object.EmeraldValue{Type: object.ValueClass, Data: receiver.Class, Class: R.Classes["Class"]}, receiver.Class)
	}
	return receiver.TypeName()
}

func classReceiverDisplayName(receiver *object.EmeraldValue, cls *object.Class) string {
	if CallMethod != nil && receiverHasCallableMethod(receiver, "name") {
		if name := CallMethod(receiver, "name"); name != nil && name.Type == object.ValueString {
			if text, ok := name.Data.(string); ok && text != "" {
				return text
			}
		}
	}
	return classToS(cls)
}

func moduleReceiverDisplayName(receiver *object.EmeraldValue, mod *object.Module) string {
	if CallMethod != nil && receiverHasCallableMethod(receiver, "name") {
		if name := CallMethod(receiver, "name"); name != nil && name.Type == object.ValueString {
			if text, ok := name.Data.(string); ok && text != "" {
				return text
			}
		}
	}
	return moduleToS(mod)
}

