func installErrnoConstants() {
	errnoClass := R.Classes["Errno"]
	if errnoClass == nil {
		return
	}
	classesByNumber := make(map[int64]*object.Class)
	for _, meta := range errnoMetadataList() {
		cls := R.Classes["Errno::"+meta.name]
		if cls == nil {
			cls = classesByNumber[meta.number]
			if cls == nil {
				cls = object.NewClass("Errno::" + meta.name)
				cls.SuperClass = R.Classes["SystemCallError"]
			}
			R.Classes["Errno::"+meta.name] = cls
		}
		if existing := classesByNumber[meta.number]; existing != nil {
			cls = existing
			R.Classes["Errno::"+meta.name] = cls
		} else {
			classesByNumber[meta.number] = cls
		}
		classValue := &object.EmeraldValue{Type: object.ValueClass, Data: cls, Class: R.Classes["Class"]}
		errnoClass.DefineConstant(meta.name, classValue)
		cls.DefineConstant("Errno", newInt(meta.number))
	}
	if cls := R.Classes["Errno::EINPROGRESS"]; cls != nil {
		R.Classes["IO::EINPROGRESSWaitWritable"] = cls
		if ioClass := R.Classes["IO"]; ioClass != nil {
			if value := ioClass.Constants["WaitWritable"]; value != nil {
				if wait, ok := value.Data.(*object.Module); ok {
					cls.IncludedModules = append(cls.IncludedModules, wait)
				}
			}
			ioClass.DefineConstant("EINPROGRESSWaitWritable", &object.EmeraldValue{Type: object.ValueClass, Data: cls, Class: R.Classes["Class"]})
		}
	}
}

func errnoMetadataByNumber(errno int64) (errnoMetadata, bool) {
	for _, meta := range errnoMetadataList() {
		if meta.number == errno {
			return meta, true
		}
	}
	return errnoMetadata{}, false
}

func systemCallErrorNew(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	class := R.Classes["SystemCallError"]
	messageArg := (*object.EmeraldValue)(nil)
	errnoArg := (*object.EmeraldValue)(nil)
	locationArg := (*object.EmeraldValue)(nil)
	if receiver != nil && receiver.Type == object.ValueClass {
		if receiverClass, ok := receiver.Data.(*object.Class); ok && receiverClass != nil && receiverClass != R.Classes["SystemCallError"] {
			if len(args) > 2 {
				return NewArgumentError("wrong number of arguments")
			}
			class = receiverClass
			if errno, ok := errnoForClass(receiverClass); ok {
				errnoArg = newInt(errno)
			}
			if len(args) > 0 {
				messageArg = args[0]
			}
			if len(args) > 1 {
				locationArg = args[1]
			}
			return newSystemCallError(class, messageArg, errnoArg, locationArg, false)
		}
	}
	if len(args) == 0 {
		return NewArgumentError("wrong number of arguments")
	}
	errnoArg = args[0]
	if len(args) == 1 && args[0] != nil && args[0].Type == object.ValueString {
		messageArg = args[0]
		errnoArg = R.NilVal
	}
	if len(args) > 1 {
		messageArg = args[0]
		errnoArg = args[1]
	}
	if len(args) > 2 {
		locationArg = args[2]
	}
	if len(args) > 3 {
		return NewArgumentError("wrong number of arguments")
	}
	return newSystemCallError(class, messageArg, errnoArg, locationArg, true)
}

func errnoForClass(class *object.Class) (int64, bool) {
	for current := class; current != nil; current = current.SuperClass {
		if value, ok := current.Constants["Errno"]; ok {
			if errno, ok := valueToInteger(value); ok {
				return errno, true
			}
		}
	}
	return 0, false
}

func newSystemCallError(class *object.Class, messageArg, errnoArg, locationArg *object.EmeraldValue, mapClass bool) *object.EmeraldValue {
	errnoValue, hasErrno, errVal := systemCallErrorErrnoValue(errnoArg)
	if errVal != nil {
		return errVal
	}
	baseMessage := "Unknown error"
	if hasErrno {
		if meta, ok := errnoMetadataByNumber(errnoValue); ok {
			baseMessage = meta.message
			if mapClass {
				if mapped := R.Classes["Errno::"+meta.name]; mapped != nil {
					class = mapped
				}
			}
		} else {
			baseMessage = fmt.Sprintf("Unknown error %d", errnoValue)
		}
	}
	customMessage, errVal := systemCallErrorCustomMessage(messageArg)
	if errVal != nil {
		return errVal
	}
	location := ""
	if locationArg != nil && locationArg != R.NilVal && locationArg.Type != object.ValueNil {
		location = locationArg.Inspect()
		if locationArg.Type == object.ValueString || locationArg.Type == object.ValueSymbol {
			location = locationArg.Data.(string)
		}
	}
	message := baseMessage
	if location != "" {
		message += " @ " + location
	}
	if customMessage != "" {
		message += " - " + customMessage
	}
	exc := newExceptionObject(class, message)
	if data, ok := exc.Data.(*object.RException); ok && hasErrno {
		errnoCopy := errnoValue
		data.Errno = &errnoCopy
	}
	return exc
}

func systemCallErrorInitialize(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver == nil || receiver.Type != object.ValueException {
		return receiver
	}
	if len(args) > 2 {
		return argumentError("wrong number of arguments")
	}
	var messageArg, locationArg *object.EmeraldValue
	if len(args) > 0 {
		messageArg = args[0]
	}
	if len(args) > 1 {
		locationArg = args[1]
	}
	errno, hasErrno := errnoForClass(receiver.Class)
	var errnoArg *object.EmeraldValue
	if hasErrno {
		errnoArg = newInt(errno)
	}
	initialized := newSystemCallError(receiver.Class, messageArg, errnoArg, locationArg, false)
	if initialized != nil && initialized.Type == object.ValueException {
		receiver.Data = initialized.Data
	}
	return receiver
}

func systemCallErrorErrnoValue(value *object.EmeraldValue) (int64, bool, *object.EmeraldValue) {
	if value == nil || value == R.NilVal || value.Type == object.ValueNil {
		return 0, false, nil
	}
	if value.Type == object.ValueFloat {
		return int64(value.Data.(float64)), true, nil
	}
	if value.Type == object.ValueInteger {
		n, ok := valueToInteger(value)
		if ok {
			return n, true, nil
		}
	}
	if value.Type == object.ValueObject {
		if complex, ok := value.Data.(*complexData); ok {
			if complex.imag != 0 {
				return 0, false, NewRangeError("can't convert")
			}
			return int64(complex.real), true, nil
		}
	}
	return 0, false, typeError("no implicit conversion of " + value.TypeName() + " into Integer")
}

func systemCallErrorCustomMessage(value *object.EmeraldValue) (string, *object.EmeraldValue) {
	if value == nil || value == R.NilVal || value.Type == object.ValueNil {
		return "", nil
	}
	if value.Type != object.ValueString {
		return "", typeError("no implicit conversion of " + value.TypeName() + " into String")
	}
	return value.Data.(string), nil
}

