func systemCallErrorEqual(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver == nil || receiver.Type != object.ValueException || len(args) == 0 || args[0] == nil || args[0].Type != object.ValueException {
		return R.FalseVal
	}
	left := receiver.Data.(*object.RException)
	right := args[0].Data.(*object.RException)
	if receiver.Class != args[0].Class || left.Message != right.Message {
		return R.FalseVal
	}
	if left.Errno == nil || right.Errno == nil {
		if left.Errno == right.Errno {
			return R.TrueVal
		}
		return R.FalseVal
	}
	if *left.Errno == *right.Errno {
		return R.TrueVal
	}
	return R.FalseVal
}

func noMethodErrorNew(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) > 4 {
		return argumentError("wrong number of arguments")
	}
	positional := args
	var errorReceiver *object.EmeraldValue
	if len(positional) > 0 && positional[len(positional)-1] != nil && positional[len(positional)-1].Type == object.ValueHash {
		kwargs := valueToHashMap(positional[len(positional)-1])
		for key, value := range kwargs {
			if specName(key) == "receiver" {
				errorReceiver = value
			}
		}
		positional = positional[:len(positional)-1]
	}
	message := ""
	if len(positional) > 0 && positional[0] != nil && positional[0] != R.NilVal {
		if value, ok := positional[0].Data.(string); ok {
			message = value
		} else {
			message = positional[0].Inspect()
		}
	}
	err := newExceptionObject(R.Classes["NoMethodError"], message)
	if exc, ok := err.Data.(*object.RException); ok {
		if len(positional) > 1 && positional[1] != nil && positional[1] != R.NilVal {
			exc.NameErrorName = specName(positional[1])
			if exc.NameErrorName == "" {
				if value, ok := positional[1].Data.(string); ok {
					exc.NameErrorName = value
				}
			}
		}
		if len(positional) > 2 && positional[2] != nil && positional[2].Type == object.ValueArray {
			exc.NoMethodArgs = append([]*object.EmeraldValue{}, positional[2].Data.([]*object.EmeraldValue)...)
		}
		if errorReceiver != nil {
			exc.NameErrorReceiver = errorReceiver
		}
	}
	return err
}

