func conditionVariableWait(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 0 {
		return NewArgumentError("wrong number of arguments (given 0, expected 1..2)")
	}
	mutex := args[0]
	if mutexValueData(mutex) == nil {
		if CallMethod != nil {
			return CallMethod(mutex, "sleep", args[1:]...)
		}
		return R.NilVal
	}
	if owned := mutexOwned(mutex); owned == nil || owned.Type != object.ValueBool || !owned.Data.(bool) {
		return threadError("Mutex is not owned by current thread")
	}
	current := threadClassCurrent(nil)
	data, _ := receiver.Data.(*conditionVariableData)
	if data == nil {
		return R.NilVal
	}
	if result := mutexUnlock(mutex); result != mutex {
		return result
	}
	data.waiters = append(data.waiters, conditionVariableWaiter{thread: current, mutex: mutex})
	if currentData := threadValueData(current); currentData != nil {
		currentData.stopped = true
	}
	result := R.NilVal
	if SuspendCurrentThread != nil {
		result = SuspendCurrentThread()
	} else {
		runNextPendingThread()
	}
	conditionVariableRemoveWaiter(data, current)
	if currentData := threadValueData(current); currentData != nil {
		currentData.stopped = false
		currentData.blockedLabel = ""
	}
	lockResult := mutexLock(mutex)
	if lockResult != mutex {
		if result == nil || result.Type != object.ValueException {
			return lockResult
		}
	}
	return result
}

func conditionVariableRemoveWaiter(data *conditionVariableData, thread *object.EmeraldValue) {
	if data == nil {
		return
	}
	for i, waiter := range data.waiters {
		if waiter.thread == thread {
			data.waiters = append(data.waiters[:i], data.waiters[i+1:]...)
			return
		}
	}
}

func conditionVariableSignal(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data, _ := receiver.Data.(*conditionVariableData)
	for data != nil && len(data.waiters) > 0 {
		waiter := data.waiters[0]
		data.waiters = data.waiters[1:]
		if conditionVariableWake(waiter) {
			break
		}
	}
	return receiver
}

func conditionVariableBroadcast(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data, _ := receiver.Data.(*conditionVariableData)
	if data == nil {
		return receiver
	}
	waiters := append([]conditionVariableWaiter(nil), data.waiters...)
	data.waiters = nil
	for _, waiter := range waiters {
		conditionVariableWake(waiter)
	}
	return receiver
}

func conditionVariableWake(waiter conditionVariableWaiter) bool {
	threadData := threadValueData(waiter.thread)
	if threadData == nil || threadData.finished {
		return false
	}
	if mutexData := mutexValueData(waiter.mutex); mutexData != nil && mutexData.locked {
		alreadyWaiting := false
		for _, thread := range mutexData.waiters {
			if thread == waiter.thread {
				alreadyWaiting = true
				break
			}
		}
		if !alreadyWaiting {
			mutexData.waiters = append(mutexData.waiters, waiter.thread)
		}
		threadData.stopped = true
		return true
	}
	threadData.stopped = false
	queuePendingThread(waiter.thread)
	return true
}

func queueClassNew(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	items := []*object.EmeraldValue{}
	if len(args) > 0 {
		if arr, ok := args[0].Data.([]*object.EmeraldValue); ok {
			items = append(items, arr...)
		} else if CallMethod != nil {
			fromType := valueTypeName(args[0])
			if !receiverHasCallableMethod(args[0], "to_a") {
				return typeError("can't convert " + fromType + " into Array")
			}
			coerced := CallMethod(args[0], "to_a")
			if coerced != nil && coerced.Type == object.ValueException {
				return coerced
			}
			if arr, ok := coerced.Data.([]*object.EmeraldValue); ok {
				items = append(items, arr...)
			} else {
				got := "nil"
				if coerced != nil {
					got = coerced.TypeName()
				}
				return typeError("can't convert " + fromType + " into Array (" + fromType + "#to_a gives " + got + ")")
			}
		} else {
			return typeError("can't convert " + valueTypeName(args[0]) + " into Array")
		}
	}
	return &object.EmeraldValue{
		Type:  object.ValueObject,
		Data:  &queueData{items: items},
		Class: R.Classes["Queue"],
	}
}

