func queueEmpty(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data := queueValueData(receiver)
	if data != nil && len(data.items) == 0 {
		return R.TrueVal
	}
	return R.FalseVal
}

func queueClear(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data := queueValueData(receiver)
	if data != nil {
		data.items = nil
	}
	return receiver
}

func queueClose(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data := queueValueData(receiver)
	if data != nil {
		data.closed = true
		for len(data.popWaiters) > 0 {
			queueWakePopWaiter(data)
		}
		for len(data.pendingPush) > 0 {
			pending := data.pendingPush[0]
			data.pendingPush = data.pendingPush[1:]
			if data.numWaiting > 0 {
				data.numWaiting--
			}
			cancelTimedThread(pending.thread)
			if threadData := threadValueData(pending.thread); threadData != nil && !threadData.finished {
				threadData.stopped = false
				queuePendingThread(pending.thread)
			}
		}
	}
	return receiver
}

func queueClosed(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data := queueValueData(receiver)
	if data != nil && data.closed {
		return R.TrueVal
	}
	return R.FalseVal
}

func queueNumWaiting(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data := queueValueData(receiver)
	if data == nil {
		return R.NilVal
	}
	return &object.EmeraldValue{Type: object.ValueInteger, Data: data.numWaiting, Class: R.Classes["Integer"]}
}

func sizedQueueReleasePendingPush(data *queueData) {
	if data == nil || data.max <= 0 {
		return
	}
	for len(data.pendingPush) > 0 && int64(len(data.items)) < data.max {
		pending := data.pendingPush[0]
		data.pendingPush = data.pendingPush[1:]
		if data.numWaiting > 0 {
			data.numWaiting--
		}
		if threadData := threadValueData(pending.thread); threadData != nil {
			cancelTimedThread(pending.thread)
			threadData.stopped = false
			queuePendingThread(pending.thread)
		}
		break
	}
}

func sizedQueueClassNew(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 0 {
		return argumentError("queue size must be given")
	}
	max, ok := sizedQueueCapacity(args[0])
	if !ok {
		return typeError("can't convert object into Integer")
	}
	if max <= 0 {
		return argumentError("queue size must be positive")
	}
	return &object.EmeraldValue{
		Type:  object.ValueObject,
		Data:  &queueData{max: max},
		Class: R.Classes["SizedQueue"],
	}
}

func sizedQueueCapacity(value *object.EmeraldValue) (int64, bool) {
	if value == nil {
		return 0, false
	}
	if value.Type == object.ValueFloat {
		if f, ok := value.Data.(float64); ok {
			return int64(f), true
		}
	}
	return valueToInteger(value)
}

func sizedQueuePush(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data := queueValueData(receiver)
	if data == nil || len(args) == 0 {
		return R.NilVal
	}
	if data.closed {
		return newRuntimeException(R.Classes["ClosedQueueError"], "queue closed")
	}
	value := args[0]
	nonBlockingArgs := args[1:]
	timeoutGiven := false
	timeoutValue := (*object.EmeraldValue)(nil)
	if len(nonBlockingArgs) > 0 && nonBlockingArgs[len(nonBlockingArgs)-1].Type == object.ValueHash {
		hash := valueToHashMap(nonBlockingArgs[len(nonBlockingArgs)-1])
		for key, candidate := range hash {
			if specName(key) != "timeout" {
				continue
			}
			timeoutGiven = true
			timeoutValue = candidate
			if timeoutValue.Type != object.ValueNil && timeoutValue.Type != object.ValueInteger && timeoutValue.Type != object.ValueFloat {
				return typeError("no implicit conversion into Float")
			}
		}
		nonBlockingArgs = nonBlockingArgs[:len(nonBlockingArgs)-1]
	}
	nonBlocking := len(nonBlockingArgs) > 0 && nonBlockingArgs[0].IsTruthy()
	if nonBlocking && timeoutGiven {
		return argumentError("can't set a timeout if non_block is enabled")
	}
	var deadline time.Time
	if timeoutGiven && timeoutValue != nil && timeoutValue.Type != object.ValueNil {
		seconds := float64(0)
		if timeoutValue.Type == object.ValueInteger {
			seconds = float64(timeoutValue.Data.(int64))
		} else {
			seconds = timeoutValue.Data.(float64)
		}
		deadline = time.Now().Add(time.Duration(seconds * float64(time.Second)))
	}
	current := threadClassCurrent(nil)
	for data.max > 0 && int64(len(data.items)) >= data.max {
		if nonBlocking {
			return threadError("queue full")
		}
		if currentData := threadValueData(current); currentData != nil && currentData.waitTimedOut {
			currentData.waitTimedOut = false
			sizedQueueRemovePendingPush(data, current)
			return R.NilVal
		}
		if !deadline.IsZero() && !time.Now().Before(deadline) {
			sizedQueueRemovePendingPush(data, current)
			return R.NilVal
		}
		if currentData := threadValueData(current); currentData != nil && currentData.block == nil {
			if len(pendingThreads) > 0 {
				runNextPendingThread()
				continue
			}
			if !deadline.IsZero() {
				if delay := time.Until(deadline); delay > 0 {
					time.Sleep(delay)
				}
				continue
			}
			return threadError("stopping only thread")
		}
		alreadyWaiting := false
		for _, pending := range data.pendingPush {
			if pending.thread == current {
				alreadyWaiting = true
				break
			}
		}
		if !alreadyWaiting {
			data.pendingPush = append(data.pendingPush, queuePendingPush{value: value, thread: current})
			data.numWaiting++
		}
		if currentData := threadValueData(current); currentData != nil {
			currentData.stopped = true
		}
		if !deadline.IsZero() {
			scheduleTimedThread(current, deadline)
		}
		if SuspendCurrentThread != nil {
			result := SuspendCurrentThread()
			if result != nil && result.Type == object.ValueException {
				return result
			}
		} else {
			return threadBlockedResult
		}
		if data.closed {
			sizedQueueRemovePendingPush(data, current)
			return newRuntimeException(R.Classes["ClosedQueueError"], "queue closed")
		}
	}
	sizedQueueRemovePendingPush(data, current)
	data.items = append(data.items, value)
	queueWakePopWaiter(data)
	return receiver
}

func sizedQueueRemovePendingPush(data *queueData, thread *object.EmeraldValue) {
	if data == nil {
		return
	}
	for i, pending := range data.pendingPush {
		if pending.thread != thread {
			continue
		}
		data.pendingPush = append(data.pendingPush[:i], data.pendingPush[i+1:]...)
		if data.numWaiting > 0 {
			data.numWaiting--
		}
		break
	}
	cancelTimedThread(thread)
}

func sizedQueueMax(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data := queueValueData(receiver)
	if data == nil {
		return R.NilVal
	}
	return &object.EmeraldValue{Type: object.ValueInteger, Data: data.max, Class: R.Classes["Integer"]}
}

func sizedQueueSetMax(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data := queueValueData(receiver)
	if data == nil || len(args) == 0 {
		return R.NilVal
	}
	max, ok := sizedQueueCapacity(args[0])
	if !ok {
		return typeError("can't convert object into Integer")
	}
	if max <= 0 {
		return argumentError("queue size must be positive")
	}
	data.max = max
	return args[0]
}

func fiberClassNew(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if CurrentBlockValue == nil || CurrentBlockValue() == nil {
		return argumentError("tried to create Proc object without a block")
	}
	storage, hasStorage, optionError := fiberNewStorageOption(args)
	if optionError != nil {
		return optionError
	}
	class := R.Classes["Fiber"]
	if receiver != nil && receiver.Type == object.ValueClass {
		if cls, ok := receiver.Data.(*object.Class); ok {
			class = cls
		}
	}
	data := &fiberData{block: CurrentBlockValue(), owner: threadClassCurrent(nil), blocking: fiberNewBlockingOption(args)}
	if hasStorage {
		validated, err := validatedFiberStorage(storage)
		if err != nil {
			return err
		}
		data.storage = validated
	} else {
		data.storage = copyFiberStorage(currentFiberStorage())
	}
	data.sourcePath, data.sourceLine = threadBlockSource(data.block)
	if data.sourcePath == "" {
		data.sourcePath = currentSourcePath()
	}
	if data.sourceLine <= 0 {
		data.sourceLine = 1
	}
	return &object.EmeraldValue{
		Type:  object.ValueObject,
		Data:  data,
		Class: class,
	}
}

func fiberClassCurrent(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if currentFiber != nil {
		return currentFiber
	}
	thread := threadClassCurrent(nil)
	threadData := threadValueData(thread)
	data := &fiberData{
		owner:      thread,
		ran:        true,
		sourcePath: currentSourcePath(),
		sourceLine: 1,
	}
	if threadData != nil {
		data.storage = threadData.fiberStorage
	}
	currentFiber = &object.EmeraldValue{
		Type:  object.ValueObject,
		Data:  data,
		Class: R.Classes["Fiber"],
	}
	if threadData != nil {
		threadData.rootFiber = currentFiber
	}
	return currentFiber
}

func fiberNewStorageOption(args []*object.EmeraldValue) (*object.EmeraldValue, bool, *object.EmeraldValue) {
	if len(args) == 0 {
		return nil, false, nil
	}
	if len(args) != 1 || args[0] == nil || args[0].Type != object.ValueHash || !Ruby2KeywordHash(args[0]) {
		return nil, false, argumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 0)", len(args)))
	}
	var storage *object.EmeraldValue
	hasStorage := false
	for key, value := range valueToHashMap(args[0]) {
		switch specName(key) {
		case "storage":
			storage = value
			hasStorage = true
		case "blocking":
			// The blocking option is handled independently of Fiber storage.
		default:
			return nil, false, argumentError("unknown keyword: " + specName(key))
		}
	}
	return storage, hasStorage, nil
}

func fiberNewBlockingOption(args []*object.EmeraldValue) bool {
	if len(args) != 1 || args[0] == nil || args[0].Type != object.ValueHash {
		return false
	}
	for key, value := range valueToHashMap(args[0]) {
		if specName(key) == "blocking" {
			return value != nil && value.IsTruthy()
		}
	}
	return false
}

func validatedFiberStorage(value *object.EmeraldValue) (*object.EmeraldValue, *object.EmeraldValue) {
	if value == nil || value.Type == object.ValueNil {
		return nil, nil
	}
	if value.Type != object.ValueHash {
		return nil, typeError("storage must be a Hash")
	}
	if value.Frozen {
		return nil, frozenError("can't use frozen Hash as Fiber storage")
	}
	data := hashData(value)
	if data != nil {
		for key := range data.Pairs {
			if key == nil || key.Type != object.ValueSymbol {
				return nil, typeError("Fiber storage key must be a Symbol")
			}
		}
	}
	return copyFiberStorage(value), nil
}

func copyFiberStorage(storage *object.EmeraldValue) *object.EmeraldValue {
	if storage == nil || storage.Type != object.ValueHash {
		return nil
	}
	return &object.EmeraldValue{Type: object.ValueHash, Data: cloneRHash(hashData(storage)), Class: R.Classes["Hash"]}
}

func currentFiberStorage() *object.EmeraldValue {
	if currentFiber == nil {
		return nil
	}
	data, _ := currentFiber.Data.(*fiberData)
	if data == nil {
		return nil
	}
	return data.storage
}

func fiberClassScheduler(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data := threadValueData(threadClassCurrent(nil))
	if data == nil || data.scheduler == nil {
		return R.NilVal
	}
	return data.scheduler
}

func fiberClassSetScheduler(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 0 || args[0] == nil || args[0].Type == object.ValueNil {
		if data := threadValueData(threadClassCurrent(nil)); data != nil {
			data.scheduler = nil
		}
		return R.NilVal
	}
	scheduler := args[0]
	for _, name := range []string{"block", "unblock", "kernel_sleep", "io_wait"} {
		if !receiverHasCallableMethod(scheduler, name) {
			return argumentError("Scheduler must implement #" + name)
		}
	}
	if data := threadValueData(threadClassCurrent(nil)); data != nil {
		data.scheduler = scheduler
	}
	return scheduler
}

func fiberClassYield(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if currentFiber == nil {
		return newRuntimeException(R.Classes["FiberError"], "can't yield from root fiber")
	}
	data, _ := currentFiber.Data.(*fiberData)
	if data == nil || data.block == nil {
		return newRuntimeException(R.Classes["FiberError"], "can't yield from root fiber")
	}
	yielded := R.NilVal
	if len(args) == 1 {
		yielded = args[0]
	} else if len(args) > 1 {
		yielded = &object.EmeraldValue{Type: object.ValueArray, Data: append([]*object.EmeraldValue(nil), args...), Class: R.Classes["Array"]}
	}
	if SuspendCurrentFiber != nil {
		data.suspensionKind = "yield"
		return SuspendCurrentFiber(yielded)
	}
	return yielded
}

func fiberResume(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return fiberRun(receiver, "resume", args...)
}

func fiberRun(receiver *object.EmeraldValue, activationMode string, args ...*object.EmeraldValue) *object.EmeraldValue {
	data, ok := receiver.Data.(*fiberData)
	if !ok || data == nil {
		return newRuntimeException(R.Classes["FiberError"], "invalid fiber")
	}
	if data.finished {
		return newRuntimeException(R.Classes["FiberError"], "dead fiber called")
	}
	if data.owner != nil && data.owner != threadClassCurrent(nil) {
		return newRuntimeException(R.Classes["FiberError"], "fiber called across threads")
	}
	if receiver == currentFiber {
		return newRuntimeException(R.Classes["FiberError"], "attempt to resume the current fiber")
	}
	if data.block == nil || data.resuming {
		return newRuntimeException(R.Classes["FiberError"], "attempt to resume a resuming fiber")
	}
	prev := currentFiber
	currentFiber = receiver
	defer func() {
		currentFiber = prev
	}()
	data.resuming = true
	defer func() {
		data.resuming = false
	}()
	previousActivationMode := data.activationMode
	data.activationMode = activationMode
	defer func() {
		data.activationMode = previousActivationMode
	}()
	data.ran = true
	if RunFiberBlock == nil {
		LastException = nil
	}
	result := R.NilVal
	if RunFiberBlock != nil {
		result = RunFiberBlock(receiver, data.block, args...)
	} else if CallBlockWithArgs != nil {
		result = CallBlockWithArgs(data.block, args...)
	}
	if yielded, ok := FiberSuspensionValue(result); ok {
		data.suspended = true
		if ConsumeFiberTermination(prev) {
			return FiberTerminationResult()
		}
		if data.suspensionKind == "root_transfer" {
			if prev != nil {
				previousData, _ := prev.Data.(*fiberData)
				if previousData != nil && previousData.block != nil && SuspendCurrentFiber != nil {
					currentFiber = prev
					previousData.suspensionKind = "root_transfer"
					return SuspendCurrentFiber(yielded)
				}
			}
		}
		return yielded
	}
	data.suspended = false
	data.finished = true
	if ConsumeFiberTermination(prev) {
		return FiberTerminationResult()
	}
	if IsFiberTerminationResult(result) {
		return R.NilVal
	}
	if result != nil && result.Type == object.ValueException {
		LastRaisedResult = result
		LastMatcherException = result
		return result
	}
	if LastException != nil {
		result = LastException
		LastRaisedResult = result
		LastException = nil
	}
	return result
}

func fiberTransfer(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data, ok := receiver.Data.(*fiberData)
	if !ok || data == nil {
		return newRuntimeException(R.Classes["FiberError"], "invalid fiber")
	}
	if data.finished {
		return newRuntimeException(R.Classes["FiberError"], "dead fiber called")
	}
	if data.owner != nil && data.owner != threadClassCurrent(nil) {
		return newRuntimeException(R.Classes["FiberError"], "fiber called across threads")
	}
	current := currentFiber
	if current == nil {
		current = fiberClassCurrent(nil)
	}
	if receiver == current {
		return fiberArgumentsValue(args)
	}
	currentData, _ := current.Data.(*fiberData)
	if data.block == nil {
		if currentData == nil || currentData.block == nil || SuspendCurrentFiber == nil {
			return fiberArgumentsValue(args)
		}
		currentData.suspensionKind = "root_transfer"
		return SuspendCurrentFiber(fiberArgumentsValue(args))
	}
	if data.suspended && data.suspensionKind == "yield" {
		return newRuntimeException(R.Classes["FiberError"], "cannot transfer to a yielding fiber")
	}
	result := fiberRun(receiver, "transfer", args...)
	if result != nil && result.Type == object.ValueException {
		return result
	}
	if currentData != nil && currentData.block != nil && currentData.activationMode == "transfer" && SuspendCurrentFiber != nil {
		currentData.suspensionKind = "transfer"
		return SuspendCurrentFiber(result)
	}
	return result
}

func fiberArgumentsValue(args []*object.EmeraldValue) *object.EmeraldValue {
	switch len(args) {
	case 0:
		return R.NilVal
	case 1:
		return args[0]
	default:
		return &object.EmeraldValue{Type: object.ValueArray, Data: append([]*object.EmeraldValue(nil), args...), Class: R.Classes["Array"]}
	}
}

func fiberRaise(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data, ok := receiver.Data.(*fiberData)
	if !ok || data == nil || (!data.ran && data.block != nil) {
		return newRuntimeException(R.Classes["FiberError"], "cannot raise exception on unborn fiber")
	}
	if data.finished {
		return newRuntimeException(R.Classes["FiberError"], "dead fiber called")
	}
	if data.owner != nil && data.owner != threadClassCurrent(nil) {
		return newRuntimeException(R.Classes["FiberError"], "fiber called across threads")
	}
	if receiver == currentFiber {
		exception, _ := buildThreadRaiseException(args)
		LastRaisedResult = exception
		return exception
	}
	if data.resuming {
		exception, _ := buildThreadRaiseException(args)
		LastRaisedResult = exception
		return exception
	}
	if !data.suspended {
		return newRuntimeException(R.Classes["FiberError"], "cannot raise exception on unborn fiber")
	}
	previousException := LastException
	previousRaisedResult := LastRaisedResult
	previousMatcherException := LastMatcherException
	exception, inject := buildThreadRaiseException(args)
	LastException = previousException
	LastRaisedResult = previousRaisedResult
	LastMatcherException = previousMatcherException
	if !inject {
		return exception
	}
	data.pendingInterrupt = exception
	return fiberResume(receiver)
}

func ConsumeCurrentFiberInterrupt() *object.EmeraldValue {
	return ConsumeFiberInterrupt(currentFiber)
}

func ConsumeFiberInterrupt(fiber *object.EmeraldValue) *object.EmeraldValue {
	if fiber == nil {
		return nil
	}
	data, _ := fiber.Data.(*fiberData)
	if data == nil || data.pendingInterrupt == nil {
		return nil
	}
	exception := data.pendingInterrupt
	data.pendingInterrupt = nil
	if CallMethod != nil && receiverHasCallableMethod(exception, "exception") {
		if converted := CallMethod(exception, "exception"); converted != nil {
			if converted.Type != object.ValueException {
				return typeError("exception object expected")
			}
			exception = converted
		}
	}
	LastRaisedResult = exception
	return exception
}

func fiberAlive(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data, ok := receiver.Data.(*fiberData)
	if ok && !data.finished {
		return R.TrueVal
	}
	return R.FalseVal
}

func fiberStorage(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver != fiberClassCurrent(nil) {
		return argumentError("Fiber storage can only be accessed from the Fiber it belongs to")
	}
	data, _ := receiver.Data.(*fiberData)
	if data == nil || data.storage == nil {
		return R.NilVal
	}
	return data.storage
}

func fiberSetStorage(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver != fiberClassCurrent(nil) {
		return argumentError("Fiber storage can only be accessed from the Fiber it belongs to")
	}
	value := R.NilVal
	if len(args) > 0 && args[0] != nil {
		value = args[0]
	}
	storage, err := validatedFiberStorage(value)
	if err != nil {
		return err
	}
	data, _ := receiver.Data.(*fiberData)
	if data != nil {
		data.storage = storage
	}
	return value
}

func fiberStorageKey(value *object.EmeraldValue) (*object.EmeraldValue, *object.EmeraldValue) {
	if value == nil || value.Type != object.ValueSymbol {
		return nil, typeError("Fiber storage key must be a Symbol")
	}
	return value, nil
}

func fiberClassStorageGet(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 0 {
		return R.NilVal
	}
	key, err := fiberStorageKey(args[0])
	if err != nil {
		return err
	}
	data, _ := fiberClassCurrent(nil).Data.(*fiberData)
	if data == nil || data.storage == nil {
		return R.NilVal
	}
	return hashIndex(data.storage, key)
}

func fiberClassStorageSet(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) < 2 {
		return R.NilVal
	}
	key, err := fiberStorageKey(args[0])
	if err != nil {
		return err
	}
	data, _ := fiberClassCurrent(nil).Data.(*fiberData)
	if data == nil {
		return R.NilVal
	}
	if data.storage == nil {
		data.storage = emptyHashValue()
	}
	if args[1] == nil || args[1].Type == object.ValueNil {
		hashDelete(data.storage, key)
		return R.NilVal
	}
	return hashIndexSet(data.storage, key, args[1])
}

func fiberKill(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data, ok := receiver.Data.(*fiberData)
	if !ok || data == nil || data.finished {
		return receiver
	}
	if data.owner != nil && data.owner != threadClassCurrent(nil) {
		return newRuntimeException(R.Classes["FiberError"], "fiber called across threads")
	}
	if !data.ran {
		data.finished = true
		return receiver
	}
	if receiver == currentFiber {
		return FiberTerminationResult()
	}
	data.terminationPending = true
	if data.suspended {
		fiberResume(receiver)
	}
	return receiver
}

func ConsumeFiberTermination(fiber *object.EmeraldValue) bool {
	if fiber == nil {
		return false
	}
	data, _ := fiber.Data.(*fiberData)
	if data == nil || !data.terminationPending {
		return false
	}
	data.terminationPending = false
	return true
}

func fiberInspect(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	state := "created"
	path := currentSourcePath()
	line := int64(1)
	if data, ok := receiver.Data.(*fiberData); ok {
		if data.finished {
			state = "terminated"
		} else if data.suspended {
			state = "suspended"
		} else if data.ran {
			state = "resumed"
		}
		if data.sourcePath != "" {
			path = data.sourcePath
		}
		if data.sourceLine > 0 {
			line = data.sourceLine
		}
	}
	inspected := fmt.Sprintf("#<Fiber:%p %s:%d (%s)>", receiver, path, line, state)
	return &object.EmeraldValue{Type: object.ValueString, Data: inspected, Class: R.Classes["String"]}
}

func NewFiberSuspension(value *object.EmeraldValue) *object.EmeraldValue {
	if value == nil {
		value = R.NilVal
	}
	return &object.EmeraldValue{Type: object.ValueObject, Data: &fiberSuspension{value: value}, Class: R.Classes["Object"]}
}

func FiberSuspensionValue(value *object.EmeraldValue) (*object.EmeraldValue, bool) {
	if value == nil || value.Type != object.ValueObject {
		return nil, false
	}
	suspension, ok := value.Data.(*fiberSuspension)
	if !ok || suspension == nil {
		return nil, false
	}
	return suspension.value, true
}

func CurrentFiberValue() *object.EmeraldValue {
	return currentFiber
}

func threadValueData(thread *object.EmeraldValue) *threadData {
	if thread == nil {
		return nil
	}
	data, _ := thread.Data.(*threadData)
	return data
}

func runNextPendingThread() {
	wakeExpiredTimedThreads()
	for len(pendingThreads) > 0 {
		thread := pendingThreads[0]
		pendingThreads = pendingThreads[1:]
		if data := threadValueData(thread); data != nil && !data.finished && (!data.ran || (data.suspended && !data.stopped)) {
			runThread(thread)
			return
		}
	}
}

func scheduleTimedThread(thread *object.EmeraldValue, deadline time.Time) {
	data := threadValueData(thread)
	if data == nil {
		return
	}
	data.waitDeadline = deadline
	data.waitTimedOut = false
	if timedThreads == nil {
		timedThreads = make(map[*object.EmeraldValue]time.Time)
	}
	timedThreads[thread] = deadline
}

func cancelTimedThread(thread *object.EmeraldValue) {
	delete(timedThreads, thread)
	if data := threadValueData(thread); data != nil {
		data.waitDeadline = time.Time{}
		data.waitTimedOut = false
	}
}

func wakeExpiredTimedThreads() {
	now := time.Now()
	for thread, deadline := range timedThreads {
		if now.Before(deadline) {
			continue
		}
		delete(timedThreads, thread)
		data := threadValueData(thread)
		if data == nil || data.finished {
			continue
		}
		data.waitDeadline = time.Time{}
		data.waitTimedOut = true
		data.stopped = false
		queuePendingThread(thread)
	}
}

func nextTimedThreadDeadline() (time.Time, bool) {
	var next time.Time
	for _, deadline := range timedThreads {
		if next.IsZero() || deadline.Before(next) {
			next = deadline
		}
	}
	return next, !next.IsZero()
}

func runAllPendingThreads() {
	for len(pendingThreads) > 0 {
		runNextPendingThread()
	}
}

func runThread(thread *object.EmeraldValue) {
	data := threadValueData(thread)
	if data == nil || data.finished || (data.ran && (!data.suspended || data.stopped)) {
		return
	}
	firstRun := !data.ran
	data.ran = true
	if data.block == nil || (RunThreadBlock == nil && CallBlockWithArgs == nil) {
		data.result = R.NilVal
		data.finished = true
		return
	}
	prevThread := currentThread
	prevFiber := currentFiber
	currentThread = thread
	currentFiber = data.rootFiber
	if firstRun {
		FireTracePointThread("thread_begin", thread)
	}
	defer func() {
		data.rootFiber = currentFiber
		currentFiber = prevFiber
		currentThread = prevThread
	}()
	data.suspended = false
	if firstRun && data.pendingInterrupt != nil && !data.deferInterrupt {
		data.exception = data.pendingInterrupt
		data.result = data.pendingInterrupt
		data.pendingInterrupt = nil
		data.finished = true
		data.stopped = false
		return
	}
	if RunThreadBlock == nil {
		LastException = nil
	}
	if RunThreadBlock != nil {
		data.result = RunThreadBlock(thread, data.block, data.args...)
	} else {
		if EnterThreadBlock != nil {
			EnterThreadBlock()
		}
		data.result = CallBlockWithArgs(data.block, data.args...)
	}
	if threadIsBlockedResult(data, data.result) {
		data.suspended = true
		return
	}
	if IsThreadTerminationResult(data.result) {
		data.result = R.NilVal
		data.exception = nil
		data.terminating = false
		data.terminationPending = false
	} else if data.result != nil && data.result.Type == object.ValueException {
		if exception, ok := data.result.Data.(*object.RException); ok && exception != nil && exception.Raised {
			data.exception = data.result
		}
	}
	data.suspended = false
	FireTracePointThread("thread_end", thread)
	data.finished = true
	if RunThreadBlock == nil && LeaveThreadBlock != nil {
		LeaveThreadBlock()
	}
	data.stopped = false
	if RunThreadBlock == nil && LastException != nil {
		data.exception = LastException
		if !data.abortOnException {
			LastException = nil
		}
	} else if data.exception != nil && (data.abortOnException || classInheritsFrom(data.exception.Class, R.Classes["SystemExit"])) {
		LastException = data.exception
	}
}

func queuePendingThread(thread *object.EmeraldValue) {
	for _, pending := range pendingThreads {
		if pending == thread {
			return
		}
	}
	pendingThreads = append(pendingThreads, thread)
}

func threadIsBlockedResult(data *threadData, result *object.EmeraldValue) bool {
	return result == threadBlockedResult || (data != nil && data.blockedResult != nil && result == data.blockedResult)
}

func IsThreadBlockedResult(result *object.EmeraldValue) bool {
	return threadIsBlockedResult(threadValueData(currentThread), result)
}

func ThreadBlockedResult() *object.EmeraldValue {
	return threadBlockedResult
}

func ThreadTerminationResult() *object.EmeraldValue {
	if threadTerminationResult == nil {
		threadTerminationResult = &object.EmeraldValue{
			Type:  object.ValueException,
			Data:  &object.RException{Message: "thread terminated", Raised: true},
			Class: R.Classes["Exception"],
		}
	}
	return threadTerminationResult
}

func IsThreadTerminationResult(result *object.EmeraldValue) bool {
	return result != nil && result == ThreadTerminationResult()
}

func FiberTerminationResult() *object.EmeraldValue {
	if fiberTerminationResult == nil {
		fiberTerminationResult = &object.EmeraldValue{
			Type:  object.ValueException,
			Data:  &object.RException{Message: "fiber terminated", Raised: true},
			Class: R.Classes["Exception"],
		}
	}
	return fiberTerminationResult
}

func IsFiberTerminationResult(result *object.EmeraldValue) bool {
	return result != nil && result == FiberTerminationResult()
}

func IsTerminationResult(result *object.EmeraldValue) bool {
	return IsThreadTerminationResult(result) || IsFiberTerminationResult(result)
}

func ConsumeCurrentThreadTermination() bool {
	data := threadValueData(currentThread)
	if data == nil || !data.terminationPending {
		return false
	}
	data.terminationPending = false
	return true
}

func ConsumeCurrentThreadInterrupt() *object.EmeraldValue {
	data := threadValueData(currentThread)
	if data == nil || data.deferInterrupt || data.pendingInterrupt == nil {
		return nil
	}
	exception := data.pendingInterrupt
	data.pendingInterrupt = nil
	if CallMethod != nil && receiverHasCallableMethod(exception, "exception") {
		if converted := CallMethod(exception, "exception"); converted != nil {
			if converted.Type != object.ValueException {
				return typeError("exception object expected")
			}
			exception = converted
		}
	}
	LastRaisedResult = exception
	return exception
}

func CurrentThreadValue() *object.EmeraldValue {
	return threadClassCurrent(nil)
}

func enumeratorClassNew(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data := &enumeratorData{}
	if CurrentBlockValue != nil {
		data.block = CurrentBlockValue()
	}
	class := R.Classes["Enumerator"]
	if receiver != nil && receiver.Type == object.ValueClass {
		if cls, ok := receiver.Data.(*object.Class); ok && cls != nil {
			class = cls
		}
	}
	if class.Name == "Enumerator" && data.block == nil && len(args) > 0 {
		return argumentError("tried to create Proc object without a block")
	}
	if class.Name == "Enumerator" && len(args) > 0 {
		data.sizeValue = args[0]
	}
	if class.Name == "Enumerator::Chain" || class.Name == "Enumerator::Product" {
		data.chainSources = append([]*object.EmeraldValue(nil), args...)
	}
	return &object.EmeraldValue{
		Type:  object.ValueObject,
		Data:  data,
		Class: class,
	}
}

func enumeratorInitialize(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver != nil && receiver.Frozen {
		return frozenError("can't modify frozen Enumerator")
	}
	data, ok := receiver.Data.(*enumeratorData)
	if !ok || data == nil {
		data = &enumeratorData{}
		receiver.Data = data
	}
	if CurrentBlockValue != nil {
		data.block = CurrentBlockValue()
	}
	if len(args) > 0 {
		data.sizeValue = args[0]
	}
	return receiver
}

func newLoopEnumerator() *object.EmeraldValue {
	return &object.EmeraldValue{
		Type:  object.ValueObject,
		Data:  &enumeratorData{kind: "loop"},
		Class: R.Classes["Enumerator"],
	}
}

func enumeratorEach(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data, ok := receiver.Data.(*enumeratorData)
	if !ok {
		return receiver
	}
	if data.kind == "lazy_chunk_pending" && data.chunkSource != nil {
		block := enumerableCurrentBlock()
		if block == nil {
			return receiver
		}
		return lazyEnumeratorChunkWithBlock(data.chunkSource, block)
	}
	if data.inspectReceiver != nil && data.inspectMethod != "" && len(args) > 0 {
		callArgs := append(append([]*object.EmeraldValue(nil), data.inspectArgs...), args...)
		block := enumerableCurrentBlock()
		if block == nil {
			return objectToEnum(data.inspectReceiver, append([]*object.EmeraldValue{rubySymbol(data.inspectMethod)}, callArgs...)...)
		}
		if CallMethodWithBlock != nil {
			return CallMethodWithBlock(data.inspectReceiver, data.inspectMethod, block, callArgs...)
		}
	}
	if data.block != nil {
		consumer := enumerableCurrentBlock()
		if consumer == nil {
			return receiver
		}
		data.externalFiber = nil
		data.externalDone = false
		data.externalPeek = nil
		for {
			value := enumeratorExternalNext(data)
			if value != nil && value.Type == object.ValueException {
				if value.Class == R.Classes["StopIteration"] {
					LastException = nil
					if exception, ok := value.Data.(*object.RException); ok && exception.Result != nil {
						return exception.Result
					}
					return R.NilVal
				}
				return value
			}
			blockResult := CallBlockWithArgs(consumer, data.externalYieldArgs...)
			if blockResult != nil && blockResult.Type == object.ValueException {
				return blockResult
			}
			if LastBlockResult != nil {
				control := LastBlockResult
				LastBlockResult = nil
				return control
			}
			data.feedSet = true
			data.feedValue = blockResult
		}
	}
	if data.kind == "loop" {
		previousException := LastException
		for {
			LastBlockResult = nil
			LastException = nil
			if CallBlock != nil {
				CallBlock()
			}
			if LastException != nil {
				return LastException
			}
			if LastBlockResult != nil {
				result := LastBlockResult
				LastBlockResult = nil
				LastException = previousException
				return result
			}
		}
	}
	if data.eachFunc != nil {
		return data.eachFunc()
	}
	previousException := LastException
	if data.limitFunc != nil {
		values, errVal := data.limitFunc(-1)
		if errVal != nil {
			if evaluatingRaiseErrorMatcher {
				LastRaisedResult = errVal
			}
			return errVal
		}
		data.values = values
		data.generated = true
	} else if errVal := enumeratorGenerateResult(data); errVal != nil {
		if evaluatingRaiseErrorMatcher {
			LastRaisedResult = errVal
		}
		return errVal
	}
	LastException = previousException
	for _, value := range data.values {
		if CallBlock != nil {
			LastBlockResult = nil
			LastException = nil
			CallBlock(value)
			if LastException != nil {
				return LastException
			}
			LastException = previousException
			if LastBlockResult != nil {
				result := LastBlockResult
				LastBlockResult = nil
				return result
			}
		}
	}
	LastException = previousException
	return receiver
}

func enumeratorNext(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data, ok := receiver.Data.(*enumeratorData)
	if !ok {
		return R.NilVal
	}
	if data.externalPeek != nil {
		value := data.externalPeek
		data.externalPeek = nil
		data.externalYieldArgs = append([]*object.EmeraldValue(nil), data.externalPeekArgs...)
		data.externalPeekArgs = nil
		return value
	}
	if data.block != nil || data.inspectReceiver != nil {
		return enumeratorExternalNext(data)
	}
	if os.Getenv("RGO_DEBUG_ENUM") == "1" {
		fmt.Printf("enumeratorNext: index=%d len=%d generated=%v result=%v\n", data.index, len(data.values), data.generated, data.result)
	}
	if data.lazy && data.lazyFunc != nil && data.index >= len(data.values) && !data.generated {
		requested := data.index + 1
		values, errVal := data.lazyFunc(requested)
		if errVal != nil {
			return errVal
		}
		data.values = values
		if len(values) < requested {
			data.generated = true
		}
	} else if data.index >= len(data.values) && data.limitFunc != nil && !data.generated {
		values, errVal := data.limitFunc(-1)
		if errVal != nil {
			return errVal
		}
		data.values = values
		data.generated = true
	} else if data.index >= len(data.values) {
		if errVal := enumeratorGenerateResult(data); errVal != nil {
			data.generated = false
			data.result = nil
			data.values = nil
			data.yieldLists = nil
			if os.Getenv("RGO_DEBUG_ENUM") == "1" {
				fmt.Printf("enumeratorNext generate error=%s\n", errVal.Inspect())
			}
			return errVal
		}
	}
	if data.index < len(data.values) {
		startIndex := data.index
		value := data.values[data.index]
		if data.index < len(data.valuePrep) && data.valuePrep[data.index] != nil {
			data.valuePrep[data.index]()
		}
		data.index++
		if data.feedSet && startIndex > 0 {
			data.feedSet = false
			data.feedValue = nil
		}
		if os.Getenv("RGO_DEBUG_ENUM") == "1" {
			fmt.Printf("enumeratorNext returns value=%s\n", value.Inspect())
		}
		return value
	}
	if os.Getenv("RGO_DEBUG_ENUM") == "1" {
		fmt.Printf("enumeratorNext exhausting; cached result=%v\n", data.result)
	}
	LastException = newStopIteration(data.result)
	if evaluatingRaiseErrorMatcher {
		LastRaisedResult = LastException
	}
	if os.Getenv("RGO_DEBUG_ENUM") == "1" {
		exc := LastException.Data.(*object.RException)
		fmt.Printf("enumeratorNext stop result nil?=%v\n", exc.Result == nil)
	}
	return LastException
}

func enumeratorNextValues(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data, _ := receiver.Data.(*enumeratorData)
	index := 0
	if data != nil {
		index = data.index
	}
	value := enumeratorNext(receiver)
	if value != nil && value.Type == object.ValueException {
		return value
	}
	if data != nil && (data.externalFiber != nil || data.externalDone) && data.externalYieldArgs != nil {
		return &object.EmeraldValue{Type: object.ValueArray, Data: append([]*object.EmeraldValue(nil), data.externalYieldArgs...), Class: R.Classes["Array"]}
	}
	if data != nil && index < len(data.yieldLists) {
		return &object.EmeraldValue{Type: object.ValueArray, Data: append([]*object.EmeraldValue(nil), data.yieldLists[index]...), Class: R.Classes["Array"]}
	}
	return &object.EmeraldValue{Type: object.ValueArray, Data: enumeratorValueList(value), Class: R.Classes["Array"]}
}

func enumeratorFeed(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 1 {
		return NewArgumentError("wrong number of arguments")
	}
	data, ok := receiver.Data.(*enumeratorData)
	if !ok {
		return R.NilVal
	}
	if data.feedSet {
		return typeError("feed value already set")
	}
	data.feedSet = true
	data.feedValue = args[0]
	return R.NilVal
}

func enumeratorPeek(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data, ok := receiver.Data.(*enumeratorData)
	if !ok {
		return R.NilVal
	}
	if data.block != nil || data.inspectReceiver != nil {
		if data.externalPeek != nil {
			return data.externalPeek
		}
		value := enumeratorExternalNext(data)
		if value != nil && value.Type != object.ValueException {
			data.externalPeek = value
			data.externalPeekArgs = append(make([]*object.EmeraldValue, 0, len(data.externalYieldArgs)), data.externalYieldArgs...)
		}
		return value
	}
	if data.lazy && data.lazyFunc != nil && data.index >= len(data.values) && !data.generated {
		requested := data.index + 1
		values, errVal := data.lazyFunc(requested)
		if errVal != nil {
			return errVal
		}
		data.values = values
		if len(values) < requested {
			data.generated = true
		}
	} else if data.index >= len(data.values) && data.limitFunc != nil && !data.generated {
		values, errVal := data.limitFunc(-1)
		if errVal != nil {
			return errVal
		}
		data.values = values
		data.generated = true
	} else if data.index >= len(data.values) {
		if errVal := enumeratorGenerateResult(data); errVal != nil {
			return errVal
		}
	}
	if data.index < len(data.values) {
		return data.values[data.index]
	}
	LastException = newStopIteration(data.result)
	return LastException
}

func enumeratorPeekValues(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data, _ := receiver.Data.(*enumeratorData)
	value := enumeratorPeek(receiver)
	if value != nil && value.Type == object.ValueException {
		return value
	}
	if data != nil && data.externalPeek != nil && data.externalPeekArgs != nil {
		return &object.EmeraldValue{Type: object.ValueArray, Data: append([]*object.EmeraldValue(nil), data.externalPeekArgs...), Class: R.Classes["Array"]}
	}
	if data != nil && data.index < len(data.yieldLists) {
		return &object.EmeraldValue{Type: object.ValueArray, Data: append([]*object.EmeraldValue(nil), data.yieldLists[data.index]...), Class: R.Classes["Array"]}
	}
	return &object.EmeraldValue{Type: object.ValueArray, Data: enumeratorValueList(value), Class: R.Classes["Array"]}
}

func enumeratorValueList(value *object.EmeraldValue) []*object.EmeraldValue {
	if value == nil {
		return []*object.EmeraldValue{R.NilVal}
	}
	if value.Type == object.ValueArray {
		return append([]*object.EmeraldValue(nil), value.Data.([]*object.EmeraldValue)...)
	}
	return []*object.EmeraldValue{value}
}

func enumeratorRewind(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data, ok := receiver.Data.(*enumeratorData)
	if ok && data != nil {
		if data.inspectReceiver != nil && CallMethod != nil && receiverHasCallableMethod(data.inspectReceiver, "rewind") {
			result := CallMethod(data.inspectReceiver, "rewind")
			if result != nil && result.Type == object.ValueException {
				return result
			}
		}
		data.index = 0
		data.feedSet = false
		data.feedValue = nil
		data.externalFiber = nil
		data.externalDone = false
		data.externalPeek = nil
		data.externalPeekArgs = nil
		data.externalYieldArgs = nil
	}
	return receiver
}

func enumeratorExternalNext(data *enumeratorData) *object.EmeraldValue {
	if data == nil || data.externalDone {
		LastException = newStopIteration(data.result)
		return LastException
	}
	firstRun := data.externalFiber == nil
	if firstRun {
		wrapper := nativeProc(func(args ...*object.EmeraldValue) *object.EmeraldValue {
			if data.block != nil {
				yielder := &object.EmeraldValue{Type: object.ValueObject, Data: &yielderData{enum: data}, Class: R.Classes["Enumerator::Yielder"]}
				return CallBlockWithArgs(data.block, yielder)
			}
			collector := nativeProc(func(yielded ...*object.EmeraldValue) *object.EmeraldValue {
				data.externalYieldArgs = append(make([]*object.EmeraldValue, 0, len(yielded)), yielded...)
				if SuspendCurrentFiber != nil {
					return SuspendCurrentFiber(enumerableYieldValue(yielded))
				}
				return R.NilVal
			})
			if CallMethodWithBlock == nil {
				return R.NilVal
			}
			return CallMethodWithBlock(data.inspectReceiver, data.inspectMethod, collector, data.inspectArgs...)
		})
		data.externalFiber = &object.EmeraldValue{
			Type:  object.ValueObject,
			Data:  &fiberData{block: wrapper, owner: threadClassCurrent(nil), locals: make(map[string]*object.EmeraldValue), activationMode: "resume"},
			Class: R.Classes["Fiber"],
		}
	}
	resumeArgs := []*object.EmeraldValue{}
	if !firstRun {
		if data.feedSet {
			resumeArgs = append(resumeArgs, data.feedValue)
		}
		data.feedSet = false
		data.feedValue = nil
	}
	result := fiberRun(data.externalFiber, "resume", resumeArgs...)
	fiberState, _ := data.externalFiber.Data.(*fiberData)
	if fiberState != nil && fiberState.suspended {
		return result
	}
	if result != nil && result.Type == object.ValueException {
		data.externalFiber = nil
		data.externalDone = false
		return result
	}
	data.result = result
	data.externalDone = true
	LastException = newStopIteration(result)
	return LastException
}

func enumeratorSize(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if data, ok := receiver.Data.(*enumeratorData); ok {
		if data.sizeFunc != nil {
			return data.sizeFunc()
		}
		if data.sizeValue != nil {
			if CallMethod != nil && receiverHasCallableMethod(data.sizeValue, "call") {
				return CallMethod(data.sizeValue, "call")
			}
			return data.sizeValue
		}
		if data.size != nil {
			return &object.EmeraldValue{Type: object.ValueInteger, Data: *data.size, Class: R.Classes["Integer"]}
		}
		if data.kind == "loop" {
			return &object.EmeraldValue{Type: object.ValueFloat, Data: math.Inf(1), Class: R.Classes["Float"]}
		}
	}
	return R.NilVal
}

func enumeratorToA(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data, ok := receiver.Data.(*enumeratorData)
	if !ok {
		return &object.EmeraldValue{Type: object.ValueArray, Data: []*object.EmeraldValue{}, Class: R.Classes["Array"]}
	}
	if data.limitFunc != nil {
		values, errVal := data.limitFunc(-1)
		if errVal != nil {
			return errVal
		}
		data.values = values
		data.generated = true
	} else if errVal := enumeratorGenerateResult(data); errVal != nil {
		return errVal
	}
	values := append([]*object.EmeraldValue(nil), data.values...)
	return &object.EmeraldValue{Type: object.ValueArray, Data: values, Class: R.Classes["Array"]}
}

func enumeratorInspect(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data, ok := receiver.Data.(*enumeratorData)
	className := "Enumerator"
	if receiver != nil && receiver.Class != nil {
		className = receiver.Class.Name
	}
	if !ok || data == nil {
		return rubyString("#<" + className + ": uninitialized>")
	}
	if data.inspectReceiver == nil || data.inspectMethod == "" {
		return rubyString("#<" + className + ": generator>")
	}
	text := "#<" + className + ": " + valueInspectText(data.inspectReceiver) + ":" + data.inspectMethod
	if len(data.inspectArgs) > 0 {
		parts := make([]string, len(data.inspectArgs))
		for i, arg := range data.inspectArgs {
			parts[i] = valueInspectText(arg)
		}
		text += "(" + strings.Join(parts, ", ") + ")"
	}
	return rubyString(text + ">")
}

