func enumeratorClassProduct(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) > 0 && args[len(args)-1] != nil && args[len(args)-1].Type == object.ValueHash && Ruby2KeywordHash(args[len(args)-1]) {
		hash := valueToHashMap(args[len(args)-1])
		names := make([]string, 0, len(hash))
		for key := range hash {
			names = append(names, ":"+strings.TrimPrefix(specName(key), ":"))
		}
		sort.Strings(names)
		return argumentError("unknown keywords: " + strings.Join(names, ", "))
	}
	product := &object.EmeraldValue{
		Type:  object.ValueObject,
		Data:  &enumeratorData{chainSources: append([]*object.EmeraldValue(nil), args...)},
		Class: R.Classes["Enumerator::Product"],
	}
	if BlockGivenCheck != nil && BlockGivenCheck() && CurrentBlockValue != nil && CurrentBlockValue() != nil {
		result := enumeratorProductEach(product)
		if result != nil && result.Type == object.ValueException {
			return result
		}
		return R.NilVal
	}
	return product
}

func enumeratorProductInitializeCopy(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 1 {
		return NewArgumentError("wrong number of arguments")
	}
	source := args[0]
	if receiver == source {
		return receiver
	}
	if receiver != nil && receiver.Frozen {
		return frozenError("can't modify frozen Enumerator::Product")
	}
	if receiver == nil || source == nil || receiver.Class != source.Class {
		return typeError("initialize_copy should take same class object")
	}
	sourceData, ok := source.Data.(*enumeratorData)
	if !ok || sourceData == nil {
		return argumentError("uninitialized product")
	}
	data, ok := receiver.Data.(*enumeratorData)
	if !ok || data == nil {
		data = &enumeratorData{}
		receiver.Data = data
	}
	data.chainSources = append([]*object.EmeraldValue(nil), sourceData.chainSources...)
	data.chainIterated = sourceData.chainIterated
	data.values = append([]*object.EmeraldValue(nil), sourceData.values...)
	data.generated = sourceData.generated
	return receiver
}

func enumeratorProductToA(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	values, errVal := enumeratorProductValues(receiver)
	if errVal != nil {
		return errVal
	}
	return &object.EmeraldValue{Type: object.ValueArray, Data: values, Class: R.Classes["Array"]}
}

func enumeratorProductSize(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data, ok := receiver.Data.(*enumeratorData)
	if !ok || data == nil {
		return R.NilVal
	}
	product := big.NewInt(1)
	infinite := false
	for _, source := range data.chainSources {
		if source != nil && (source.Type == object.ValueRange || source.Class == R.Classes["Range"]) {
			if r, ok := source.Data.(*object.RRange); ok && r.EndMissing {
				infinite = true
				continue
			}
		}
		if !chainRespondsTo(source, "size") {
			return R.NilVal
		}
		size := chainCall(source, "size")
		if size == nil || size.Type == object.ValueNil || size.Type == object.ValueException {
			return R.NilVal
		}
		if size.Type == object.ValueFloat {
			if math.IsInf(size.Data.(float64), 1) {
				infinite = true
				continue
			}
			return R.NilVal
		}
		integer, ok := numericBigIntValue(size)
		if !ok {
			return R.NilVal
		}
		product.Mul(product, integer)
	}
	if infinite {
		return newFloat(math.Inf(1))
	}
	return NewIntegerFromBigInt(product)
}

func enumeratorProductRewind(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data, ok := receiver.Data.(*enumeratorData)
	if !ok || data == nil {
		return receiver
	}
	for _, source := range data.chainSources {
		if source != nil && CallMethod != nil && receiverHasCallableMethod(source, "rewind") {
			result := CallMethod(source, "rewind")
			if result != nil && result.Type == object.ValueException {
				return result
			}
		}
	}
	data.chainIterated = 0
	return receiver
}

func enumeratorProductTake(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 1 {
		return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 1)", len(args)))
	}
	count, errVal := enumerableCountArg(args[0], false)
	if errVal != nil {
		return errVal
	}
	values, errVal := enumeratorProductValuesLimited(receiver, int(count))
	if errVal != nil {
		return errVal
	}
	return &object.EmeraldValue{Type: object.ValueArray, Data: values, Class: R.Classes["Array"]}
}

func enumeratorProductInspect(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data, ok := receiver.Data.(*enumeratorData)
	if !ok || data == nil {
		return rubyString("#<Enumerator::Product: uninitialized>")
	}
	if data.inspecting {
		return rubyString("#<Enumerator::Product: ...>")
	}
	data.inspecting = true
	defer func() { data.inspecting = false }()
	parts := make([]string, len(data.chainSources))
	for i, source := range data.chainSources {
		parts[i] = valueInspectText(source)
	}
	return rubyString("#<Enumerator::Product: [" + strings.Join(parts, ", ") + "]>")
}

func enumeratorProductEach(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 0 {
		return NewArgumentError("wrong number of arguments")
	}
	values, errVal := enumeratorProductValues(receiver)
	if errVal != nil {
		if evaluatingRaiseErrorMatcher {
			LastRaisedResult = errVal
		}
		return errVal
	}
	if BlockGivenCheck == nil || !BlockGivenCheck() || CurrentBlockValue == nil || CurrentBlockValue() == nil {
		return newSizedValueGeneratorEnumerator(enumeratorProductSize(receiver), func() ([]*object.EmeraldValue, *object.EmeraldValue) {
			return values, nil
		})
	}
	block := CurrentBlockValue()
	for _, value := range values {
		result := CallBlockWithArgs(block, value)
		if result != nil && result.Type == object.ValueException {
			return result
		}
		if LastBlockResult != nil {
			control := LastBlockResult
			LastBlockResult = nil
			return control
		}
	}
	return receiver
}

func enumeratorProductValues(receiver *object.EmeraldValue) ([]*object.EmeraldValue, *object.EmeraldValue) {
	data, ok := receiver.Data.(*enumeratorData)
	if !ok || data == nil {
		return nil, argumentError("uninitialized product")
	}
	result := make([]*object.EmeraldValue, 0)
	var productErr *object.EmeraldValue
	var build func(int, []*object.EmeraldValue)
	build = func(index int, tuple []*object.EmeraldValue) {
		if productErr != nil {
			return
		}
		if index == len(data.chainSources) {
			result = append(result, &object.EmeraldValue{Type: object.ValueArray, Data: append([]*object.EmeraldValue(nil), tuple...), Class: R.Classes["Array"]})
			return
		}
		// A source is enumerated once per preceding tuple. Consuming
		// enumerators are therefore exhausted after their first traversal.
		values, errVal := productSourceValues(data.chainSources[index])
		if errVal != nil {
			productErr = errVal
			return
		}
		for _, value := range values {
			build(index+1, append(tuple, value))
		}
	}
	build(0, nil)
	return result, productErr
}

func productSourceValues(source *object.EmeraldValue) ([]*object.EmeraldValue, *object.EmeraldValue) {
	if source == nil {
		return nil, NewNoMethodError("undefined method `each_entry' for nil")
	}
	if source.Type == object.ValueArray {
		return append([]*object.EmeraldValue(nil), source.Data.([]*object.EmeraldValue)...), nil
	}
	if source.Type == object.ValueRange {
		arr := rangeToA(source)
		if arr != nil && arr.Type == object.ValueException {
			return nil, arr
		}
		return append([]*object.EmeraldValue(nil), arr.Data.([]*object.EmeraldValue)...), nil
	}
	if CallMethod == nil || CallMethodWithBlock == nil {
		return nil, NewNoMethodError("undefined method `each_entry' for " + source.Inspect())
	}
	responds := CallMethod(source, "respond_to?", rubySymbol("each_entry"))
	if responds != nil && responds.Type == object.ValueException {
		return nil, responds
	}
	if !isTruthy(responds) {
		return nil, NewNoMethodError("undefined method `each_entry' for " + source.Inspect())
	}
	values := make([]*object.EmeraldValue, 0)
	collector := nativeProc(func(yielded ...*object.EmeraldValue) *object.EmeraldValue {
		values = append(values, enumerableYieldValue(yielded))
		return R.NilVal
	})
	result := CallMethodWithBlock(source, "each_entry", collector)
	if result != nil && result.Type == object.ValueException {
		return nil, result
	}
	return values, nil
}

func enumeratorProductValuesLimited(receiver *object.EmeraldValue, limit int) ([]*object.EmeraldValue, *object.EmeraldValue) {
	data, ok := receiver.Data.(*enumeratorData)
	if !ok || data == nil {
		return nil, argumentError("uninitialized product")
	}
	lists := make([][]*object.EmeraldValue, len(data.chainSources))
	for i, source := range data.chainSources {
		if source != nil && source.Type == object.ValueRange {
			if values, ok := rangeTakeValues(source, int64(limit)); ok {
				lists[i] = values
				continue
			}
		}
		values, errVal := productSourceValues(source)
		if errVal != nil {
			return nil, errVal
		}
		if len(values) > limit {
			values = values[:limit]
		}
		lists[i] = values
	}
	if len(lists) == 0 {
		return []*object.EmeraldValue{{Type: object.ValueArray, Data: []*object.EmeraldValue{}, Class: R.Classes["Array"]}}, nil
	}
	result := make([]*object.EmeraldValue, 0, limit)
	current := make([]*object.EmeraldValue, len(lists))
	var visit func(int)
	visit = func(depth int) {
		if len(result) >= limit {
			return
		}
		if depth == len(lists) {
			result = append(result, &object.EmeraldValue{Type: object.ValueArray, Data: append([]*object.EmeraldValue(nil), current...), Class: R.Classes["Array"]})
			return
		}
		for _, value := range lists[depth] {
			current[depth] = value
			visit(depth + 1)
			if len(result) >= limit {
				return
			}
		}
	}
	visit(0)
	return result, nil
}

func enumeratorChainEach(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data, ok := receiver.Data.(*enumeratorData)
	if !ok || data == nil {
		return receiver
	}
	if BlockGivenCheck == nil || !BlockGivenCheck() || CurrentBlockValue == nil || CurrentBlockValue() == nil {
		data.chainIterated = len(data.chainSources)
		return receiver
	}
	block := CurrentBlockValue()
	for i, source := range data.chainSources {
		data.chainIterated = i + 1
		result := chainCallWithBlock(source, "each", block)
		if result != nil && result.Type == object.ValueException {
			return result
		}
		if LastBlockResult != nil {
			result := LastBlockResult
			LastBlockResult = nil
			return result
		}
	}
	return receiver
}

func enumeratorChainRewind(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data, ok := receiver.Data.(*enumeratorData)
	if !ok || data == nil {
		return receiver
	}
	limit := data.chainIterated
	if limit > len(data.chainSources) {
		limit = len(data.chainSources)
	}
	for i := limit - 1; i >= 0; i-- {
		source := data.chainSources[i]
		if !chainRespondsTo(source, "rewind") {
			continue
		}
		result := chainCall(source, "rewind")
		if result != nil && result.Type == object.ValueException {
			return result
		}
	}
	return receiver
}

func enumeratorChainSize(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data, ok := receiver.Data.(*enumeratorData)
	if !ok || data == nil {
		return R.NilVal
	}
	total := int64(0)
	for _, source := range data.chainSources {
		size := chainCall(source, "size")
		if size == nil || size.Type == object.ValueNil || size.Type == object.ValueException {
			return size
		}
		if size.Type == object.ValueFloat && math.IsInf(size.Data.(float64), 1) {
			return size
		}
		if integer, ok := numericBigIntValue(size); ok && integer.IsInt64() {
			total += integer.Int64()
			continue
		}
		return R.NilVal
	}
	return newInt(total)
}

func enumeratorChainInspect(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data, ok := receiver.Data.(*enumeratorData)
	if !ok || data == nil {
		return rubyString("#<Enumerator::Chain: uninitialized>")
	}
	parts := make([]string, len(data.chainSources))
	for i, source := range data.chainSources {
		parts[i] = valueInspectText(source)
	}
	return rubyString("#<Enumerator::Chain: [" + strings.Join(parts, ", ") + "]>")
}

func chainCall(receiver *object.EmeraldValue, name string, args ...*object.EmeraldValue) *object.EmeraldValue {
	if CallMethod == nil {
		return R.NilVal
	}
	result := CallMethod(receiver, name, args...)
	if isNoMethodErrorFor(result, name) {
		missingArgs := append([]*object.EmeraldValue{rubySymbol(name)}, args...)
		return CallMethod(receiver, "method_missing", missingArgs...)
	}
	return result
}

func chainCallWithBlock(receiver *object.EmeraldValue, name string, block *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if CallMethodWithBlock == nil {
		return chainCall(receiver, name, args...)
	}
	result := CallMethodWithBlock(receiver, name, block, args...)
	if isNoMethodErrorFor(result, name) {
		missingArgs := append([]*object.EmeraldValue{rubySymbol(name)}, args...)
		return CallMethodWithBlock(receiver, "method_missing", block, missingArgs...)
	}
	return result
}

func chainRespondsTo(receiver *object.EmeraldValue, name string) bool {
	if CallMethod == nil {
		return receiverHasCallableMethod(receiver, name)
	}
	result := CallMethod(receiver, "respond_to?", rubySymbol(name))
	if result != nil && result.Type == object.ValueException {
		return false
	}
	return isTruthy(result)
}

func isNoMethodErrorFor(value *object.EmeraldValue, name string) bool {
	if value == nil || value.Type != object.ValueException || value.Class != R.Classes["NoMethodError"] {
		return false
	}
	rex, ok := value.Data.(*object.RException)
	return ok && strings.Contains(rex.Message, "undefined method `"+name+"'")
}

func yielderAppend(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 1 {
		return NewArgumentError("wrong number of arguments")
	}
	data, ok := receiver.Data.(*yielderData)
	if !ok {
		return receiver
	}
	if data.block != nil {
		CallBlockWithArgs(data.block, args[0])
		return receiver
	}
	if data.enum == nil {
		return receiver
	}
	if data.enum.externalFiber != nil {
		data.enum.externalYieldArgs = []*object.EmeraldValue{args[0]}
		if SuspendCurrentFiber != nil {
			return SuspendCurrentFiber(args[0])
		}
	}
	data.enum.values = append(data.enum.values, args[0])
	data.enum.yieldLists = append(data.enum.yieldLists, []*object.EmeraldValue{args[0]})
	if data.enum.limitGeneration && len(data.enum.values) >= data.enum.generationLimit {
		data.enum.limitReached = true
		enumeratorLimitAbort = true
		if AbortCurrentBlock != nil {
			AbortCurrentBlock(R.NilVal)
			return receiver
		}
		stop := NewLocalJumpError("enumerator generation limit reached")
		LastBlockResult = stop
		return stop
	}
	return receiver
}

func yielderClassNew(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	block := enumerableCurrentBlock()
	if block == nil {
		return NewArgumentError("tried to create Proc object without a block")
	}
	return &object.EmeraldValue{Type: object.ValueObject, Data: &yielderData{block: block}, Class: R.Classes["Enumerator::Yielder"]}
}

func yielderYield(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data, ok := receiver.Data.(*yielderData)
	if !ok {
		return R.NilVal
	}
	if data.enum != nil {
		if data.enum.externalFiber != nil {
			data.enum.externalYieldArgs = append(make([]*object.EmeraldValue, 0, len(args)), args...)
			if SuspendCurrentFiber != nil {
				return SuspendCurrentFiber(enumerableYieldValue(args))
			}
		}
		data.enum.values = append(data.enum.values, enumerableYieldValue(args))
		data.enum.yieldLists = append(data.enum.yieldLists, append([]*object.EmeraldValue(nil), args...))
		if data.enum.limitGeneration && len(data.enum.values) >= data.enum.generationLimit {
			data.enum.limitReached = true
			enumeratorLimitAbort = true
			if AbortCurrentBlock != nil {
				AbortCurrentBlock(R.NilVal)
				return R.NilVal
			}
			stop := NewLocalJumpError("enumerator generation limit reached")
			LastBlockResult = stop
			return stop
		}
		return R.NilVal
	}
	if data.block == nil {
		return R.NilVal
	}
	return CallBlockWithArgs(data.block, args...)
}

func yielderToProc(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data, ok := receiver.Data.(*yielderData)
	if !ok || (data.block == nil && data.enum == nil) {
		return R.NilVal
	}
	return nativeProc(func(args ...*object.EmeraldValue) *object.EmeraldValue {
		return yielderYield(receiver, args...)
	})
}

func newStopIteration(result *object.EmeraldValue) *object.EmeraldValue {
	if result == nil {
		result = R.NilVal
	}
	return &object.EmeraldValue{
		Type:  object.ValueException,
		Data:  &object.RException{Message: "StopIteration", Result: result},
		Class: R.Classes["StopIteration"],
	}
}

func methodIsA(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) < 1 {
		return R.FalseVal
	}
	if args[0].Type != object.ValueClass && args[0].Type != object.ValueModule {
		return typeError("class or module required")
	}
	if args[0].Type == object.ValueModule {
		effective := receiverEffectiveClass(receiver)
		if singleton := existingSingletonClass(receiver); singleton != nil {
			effective = singleton
		}
		if classAncestryIncludesModule(effective, args[0].Data.(*object.Module)) {
			return R.TrueVal
		}
		return R.FalseVal
	}
	targetClass := args[0].Data.(*object.Class)
	if classValueKindOfSingletonTarget(receiver, targetClass) {
		return R.TrueVal
	}
	currentClass := receiverEffectiveClass(receiver)
	if effectiveClassKindOf(currentClass, targetClass) {
		return R.TrueVal
	}
	return R.FalseVal
}

func classValueKindOfSingletonTarget(receiver *object.EmeraldValue, target *object.Class) bool {
	if receiver == nil || receiver.Type != object.ValueClass || target == nil || !target.IsSingleton || target.SingletonOwner == nil || target.SingletonOwner.Type != object.ValueClass {
		return false
	}
	targetOwner, ok := target.SingletonOwner.Data.(*object.Class)
	if !ok || targetOwner == nil {
		return false
	}
	candidate, ok := receiver.Data.(*object.Class)
	if !ok || candidate == nil {
		return false
	}
	if !candidate.IsSingleton {
		return classInheritsFrom(candidate, targetOwner)
	}
	owner := candidate.SingletonOwner
	if owner == nil || owner.Type == object.ValueClass || owner.Class == nil {
		return false
	}
	return classInheritsFrom(owner.Class, targetOwner)
}

func moduleCaseEqual(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 1 {
		return R.FalseVal
	}
	return methodIsA(args[0], receiver)
}

func moduleCompare(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 1 || receiver == nil || args[0] == nil ||
		(receiver.Type != object.ValueClass && receiver.Type != object.ValueModule) ||
		(args[0].Type != object.ValueClass && args[0].Type != object.ValueModule) {
		return R.NilVal
	}
	if receiver.Type == args[0].Type && receiver.Data == args[0].Data {
		return &object.EmeraldValue{Type: object.ValueInteger, Data: int64(0), Class: R.Classes["Integer"]}
	}
	if moduleValueDescendsFrom(receiver, args[0]) {
		return &object.EmeraldValue{Type: object.ValueInteger, Data: int64(-1), Class: R.Classes["Integer"]}
	}
	if moduleValueDescendsFrom(args[0], receiver) {
		return &object.EmeraldValue{Type: object.ValueInteger, Data: int64(1), Class: R.Classes["Integer"]}
	}
	return R.NilVal
}

func moduleValueDescendsFrom(value, ancestor *object.EmeraldValue) bool {
	if value == nil || ancestor == nil {
		return false
	}
	switch value.Type {
	case object.ValueClass:
		class := value.Data.(*object.Class)
		if ancestor.Type == object.ValueClass {
			target := ancestor.Data.(*object.Class)
			for current := class.SuperClass; current != nil; current = current.SuperClass {
				if current == target {
					return true
				}
			}
			return false
		}
		if ancestor.Type == object.ValueModule {
			return classAncestryIncludesModule(class, ancestor.Data.(*object.Module))
		}
	case object.ValueModule:
		if ancestor.Type == object.ValueModule {
			module := value.Data.(*object.Module)
			target := ancestor.Data.(*object.Module)
			return module != target && moduleAncestryIncludesModule(module, target)
		}
	}
	return false
}

func classAncestryIncludesModule(class *object.Class, target *object.Module) bool {
	for current := class; current != nil; current = current.SuperClass {
		if moduleListIncludesModule(current.PrependedModules, target) || moduleListIncludesModule(current.IncludedModules, target) {
			return true
		}
	}
	return false
}

func moduleListIncludesModule(modules []*object.Module, target *object.Module) bool {
	for _, mod := range modules {
		if moduleAncestryIncludesModule(mod, target) {
			return true
		}
	}
	return false
}

func moduleAncestryIncludesModule(module *object.Module, target *object.Module) bool {
	if module == nil || target == nil {
		return false
	}
	if module == target || (module.Name != "" && module.Name == target.Name) {
		return true
	}
	return moduleListIncludesModule(module.PrependedModules, target) || moduleListIncludesModule(module.IncludedModules, target)
}

func receiverEffectiveClass(receiver *object.EmeraldValue) *object.Class {
	if receiver == nil {
		return nil
	}
	if receiver.Type == object.ValueClass {
		if class, ok := receiver.Data.(*object.Class); ok && class != nil && class.IsSingleton {
			depth := singletonClassDepth(class)
			effective := R.Classes["Class"]
			for level := 0; level < depth && effective != nil; level++ {
				if effective.SingletonClass == nil {
					break
				}
				effective = effective.SingletonClass
			}
			if effective != nil {
				return effective
			}
		}
		return receiver.Class
	}
	if receiver.Type == object.ValueModule {
		return receiver.Class
	}
	if singleton := existingSingletonClass(receiver); singleton != nil {
		return singleton
	}
	return receiver.Class
}

func singletonClassDepth(class *object.Class) int {
	depth := 0
	for class != nil && class.IsSingleton {
		depth++
		owner := class.SingletonOwner
		if owner == nil || owner.Type != object.ValueClass {
			break
		}
		parent, ok := owner.Data.(*object.Class)
		if !ok || parent == class {
			break
		}
		class = parent
	}
	return depth
}

func effectiveClassKindOf(class, target *object.Class) bool {
	if classInheritsFrom(class, target) {
		return true
	}
	classDepth, classTower := classSingletonTowerDepth(class)
	targetDepth, targetTower := classSingletonTowerDepth(target)
	return classTower && targetTower && classDepth >= targetDepth
}

func classSingletonTowerDepth(class *object.Class) (int, bool) {
	depth := 0
	for class != nil && class.IsSingleton {
		depth++
		owner := class.SingletonOwner
		if owner == nil || owner.Type != object.ValueClass {
			return 0, false
		}
		parent, ok := owner.Data.(*object.Class)
		if !ok || parent == class {
			return 0, false
		}
		class = parent
	}
	return depth, class == R.Classes["Class"]
}

func intAdd(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) < 1 {
		return R.NilVal
	}
	if left, ok := numericBigIntValue(receiver); ok {
		if right, ok := numericBigIntValue(args[0]); ok {
			return NewIntegerFromBigInt(new(big.Int).Add(left, right))
		}
		if rational, ok := rationalValueData(args[0]); ok {
			numerator := new(big.Int).Add(new(big.Int).Mul(left, rational.denominator), rational.numerator)
			return newRationalValue(numerator, rational.denominator)
		}
		if args[0] != nil && args[0].Type == object.ValueFloat {
			return newFloat(bigIntFloat64(left) + args[0].Data.(float64))
		}
	}
	l := receiver.Data.(int64)
	switch r := args[0].Data.(type) {
	case int64:
		return &object.EmeraldValue{Type: object.ValueInteger, Data: l + r, Class: R.Classes["Integer"]}
	case float64:
		return &object.EmeraldValue{Type: object.ValueFloat, Data: float64(l) + r, Class: R.Classes["Float"]}
	}
	return integerCoercedBinary(receiver, args[0], "+")
}

func IntegerPlusUsesBuiltinImplementation() bool {
	integerClass := R.Classes["Integer"]
	if integerClass == nil {
		return false
	}
	if len(integerClass.PrependedModules) > 0 {
		return false
	}
	method, ok := integerClass.Methods["+"]
	if !ok || method == nil || method.Fn == nil {
		return false
	}
	actual := reflect.ValueOf(method.Fn)
	expected := reflect.ValueOf(BuiltinMethod(intAdd))
	return actual.Kind() == reflect.Func && actual.Pointer() == expected.Pointer()
}

