func intModuloBinary(receiver *object.EmeraldValue, args []*object.EmeraldValue, operation string) *object.EmeraldValue {
	if len(args) != 1 {
		return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 1)", len(args)))
	}
	if left, ok := numericBigIntValue(receiver); ok {
		if right, ok := numericBigIntValue(args[0]); ok {
			if right.Sign() == 0 {
				return newRuntimeException(R.Classes["ZeroDivisionError"], "divided by 0")
			}
			_, remainder := rubyBigIntDivMod(left, right)
			return NewIntegerFromBigInt(remainder)
		}
	}
	if args[0] != nil && args[0].Type == object.ValueFloat {
		divisor := args[0].Data.(float64)
		if divisor == 0 {
			return newRuntimeException(R.Classes["ZeroDivisionError"], "divided by 0")
		}
		left := float64(receiver.Data.(int64))
		if bigValue, ok := NumericBigIntOverride(receiver); ok {
			left, _ = new(big.Float).SetInt(bigValue).Float64()
		}
		result := math.Mod(left, divisor)
		if result != 0 && math.Signbit(result) != math.Signbit(divisor) {
			result += divisor
		}
		return newFloat(result)
	}
	if args[0] != nil && ReceiverHasCallableMethod(args[0], "coerce") && CallMethod != nil {
		var coerced *object.EmeraldValue
		if CallMethodBypass != nil {
			coerced = CallMethodBypass(args[0], "coerce", receiver)
		} else {
			coerced = CallMethod(args[0], "coerce", receiver)
		}
		if coerced != nil && coerced.Type == object.ValueException {
			return coerced
		}
		if coerced == nil || coerced.Type != object.ValueArray || len(coerced.Data.([]*object.EmeraldValue)) != 2 {
			return NewTypeError("coerce must return [x, y]")
		}
		pair := coerced.Data.([]*object.EmeraldValue)
		return CallMethod(pair[0], operation, pair[1])
	}
	return NewTypeError("no implicit conversion into Integer")
}

func intRemainder(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 1 {
		return R.NilVal
	}
	if args[0] != nil && args[0].Type == object.ValueFloat {
		divisor := args[0].Data.(float64)
		if divisor == 0 {
			return newRuntimeException(R.Classes["ZeroDivisionError"], "divided by 0")
		}
		left := float64(receiver.Data.(int64))
		if bigValue, ok := NumericBigIntOverride(receiver); ok {
			left, _ = new(big.Float).SetInt(bigValue).Float64()
		}
		return newFloat(math.Mod(left, divisor))
	}
	if right, ok := rationalValueData(args[0]); ok {
		if right.numerator.Sign() == 0 {
			return newRuntimeException(R.Classes["ZeroDivisionError"], "divided by 0")
		}
		left, _ := numericBigIntValue(receiver)
		ratioNumerator := new(big.Int).Mul(left, right.denominator)
		quotient := new(big.Int).Quo(ratioNumerator, right.numerator)
		remainderNumerator := new(big.Int).Sub(
			new(big.Int).Mul(left, right.denominator),
			new(big.Int).Mul(quotient, right.numerator),
		)
		return newRationalValue(remainderNumerator, right.denominator)
	}
	left, leftOK := numericBigIntValue(receiver)
	right, rightOK := numericBigIntValue(args[0])
	if !leftOK || !rightOK {
		return NewTypeError("no implicit conversion into Integer")
	}
	if right.Sign() == 0 {
		return newRuntimeException(R.Classes["ZeroDivisionError"], "divided by 0")
	}
	return NewIntegerFromBigInt(new(big.Int).Rem(left, right))
}

func intPow(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 2 {
		base, baseOK := numericBigIntValue(receiver)
		exponent, exponentOK := numericBigIntValue(args[0])
		modulus, modulusOK := numericBigIntValue(args[1])
		if !baseOK || !exponentOK || !modulusOK {
			return NewTypeError("2nd argument not allowed unless all arguments are integers")
		}
		if exponent.Sign() < 0 {
			return NewRangeError("integer exponent must be non-negative")
		}
		if modulus.Sign() == 0 {
			return newRuntimeException(R.Classes["ZeroDivisionError"], "divided by 0")
		}
		absModulus := new(big.Int).Abs(new(big.Int).Set(modulus))
		result := new(big.Int).Exp(base, exponent, absModulus)
		if modulus.Sign() < 0 && result.Sign() != 0 {
			result.Add(result, modulus)
		}
		return NewIntegerFromBigInt(result)
	}
	if len(args) != 1 {
		return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 1..2)", len(args)))
	}
	base, baseOK := numericBigIntValue(receiver)
	if !baseOK {
		return R.NilVal
	}
	if rationalExponent, ok := rationalValueData(args[0]); ok {
		if rationalExponent.denominator.Cmp(big.NewInt(1)) == 0 {
			return rationalPow(newRationalValue(base, big.NewInt(1)), args[0])
		}
		return integerPowFloat(base, rationalDataAsFloat(rationalExponent))
	}
	if args[0] != nil && args[0].Type == object.ValueFloat {
		return integerPowFloat(base, args[0].Data.(float64))
	}
	if exponent, ok := numericBigIntValue(args[0]); ok {
		if exponent.Sign() < 0 {
			if base.Sign() == 0 {
				return newRuntimeException(R.Classes["ZeroDivisionError"], "divided by 0")
			}
			baseFloat, _ := new(big.Float).SetInt(base).Float64()
			exponentFloat, _ := new(big.Float).SetInt(exponent).Float64()
			return newFloat(math.Pow(baseFloat, exponentFloat))
		}
		if IntegerPowerResultTooLarge(base, exponent) {
			return NewArgumentError("exponent is too large")
		}
		return NewIntegerFromBigInt(new(big.Int).Exp(base, exponent, nil))
	}
	return integerCoercedBinary(receiver, args[0], "**")
}

func integerPowFloat(base *big.Int, exponent float64) *object.EmeraldValue {
	baseFloat, _ := new(big.Float).SetInt(base).Float64()
	if base.Sign() < 0 && exponent != math.Trunc(exponent) {
		magnitude := math.Pow(math.Abs(baseFloat), exponent)
		angle := math.Pi * exponent
		return newComplexValue(magnitude*math.Cos(angle), magnitude*math.Sin(angle))
	}
	return newFloat(math.Pow(baseFloat, exponent))
}

func IntegerPowerResultTooLarge(base, exponent *big.Int) bool {
	if base == nil || exponent == nil || exponent.Sign() <= 0 {
		return false
	}
	absBase := new(big.Int).Abs(new(big.Int).Set(base))
	if absBase.Cmp(big.NewInt(1)) <= 0 {
		return false
	}
	bitsPerPower := absBase.BitLen() - 1
	if bitsPerPower < 1 {
		bitsPerPower = 1
	}
	const maximumResultBits = int64(50_000_000)
	maximumExponent := big.NewInt(maximumResultBits / int64(bitsPerPower))
	return exponent.Cmp(maximumExponent) > 0
}

func integerPowOverflows(base int64, exp int) bool {
	if exp < 0 {
		return false
	}
	if base == 0 || base == 1 || base == -1 {
		return false
	}
	return math.Pow(math.Abs(float64(base)), float64(exp)) > float64(math.MaxInt64)
}

func ApproximateIntegerPowAsFloat(base int64, exp int) float64 {
	if exp < 0 {
		return math.Pow(float64(base), float64(exp))
	}
	result := new(big.Int).Exp(big.NewInt(base), big.NewInt(int64(exp)), nil)
	f, _ := new(big.Float).SetInt(result).Float64()
	return f
}

func powInt(base int64, exp int) int64 {
	result := int64(1)
	for i := 0; i < exp; i++ {
		result *= base
	}
	return result
}

func mathPow(base, exp float64) float64 {
	result := 1.0
	for i := 0; i < int(exp); i++ {
		result *= base
	}
	return result
}

func installMathMethods(module *object.Module) {
	unary := map[string]func(float64) float64{
		"acos": math.Acos, "acosh": math.Acosh, "asin": math.Asin, "asinh": math.Asinh,
		"atan": math.Atan, "atanh": math.Atanh, "cbrt": math.Cbrt, "cos": math.Cos,
		"cosh": math.Cosh, "erf": math.Erf, "erfc": math.Erfc, "exp": math.Exp,
		"expm1": math.Expm1, "gamma": math.Gamma, "log10": math.Log10, "log1p": math.Log1p,
		"sin": math.Sin, "sinh": math.Sinh, "sqrt": math.Sqrt,
		"tan": math.Tan, "tanh": math.Tanh,
	}
	for name, fn := range unary {
		module.DefineMethod(name, &object.Method{Name: name, Fn: mathUnaryMethod(name, fn), Arity: 1})
	}
	module.DefineMethod("atan2", &object.Method{Name: "atan2", Fn: mathBinaryMethod("atan2", math.Atan2), Arity: 2})
	module.DefineMethod("hypot", &object.Method{Name: "hypot", Fn: mathBinaryMethod("hypot", math.Hypot), Arity: 2})
	module.DefineMethod("frexp", &object.Method{Name: "frexp", Fn: mathFrexp, Arity: 1})
	module.DefineMethod("ldexp", &object.Method{Name: "ldexp", Fn: mathLdexp, Arity: 2})
	module.DefineMethod("lgamma", &object.Method{Name: "lgamma", Fn: mathLgamma, Arity: 1})
	module.DefineMethod("log", &object.Method{Name: "log", Fn: mathLog, Arity: -1})
	module.DefineMethod("log2", &object.Method{Name: "log2", Fn: mathLog2, Arity: 1})
}

func mathFloatArgument(value *object.EmeraldValue) (float64, *object.EmeraldValue) {
	if value != nil && value.Type == object.ValueString {
		return 0, typeError("can't convert String into Float")
	}
	converted := builtinKernelFloat(R.Main, value)
	if converted == nil || converted.Type == object.ValueException {
		if converted != nil && converted.Class == R.Classes["ArgumentError"] {
			if exception, ok := converted.Data.(*object.RException); ok {
				return 0, typeError(exception.Message)
			}
		}
		return 0, converted
	}
	return converted.Data.(float64), nil
}

func mathDomainError(name string) *object.EmeraldValue {
	return newRuntimeException(R.Classes["Math::DomainError"], "Numerical argument is out of domain - "+name)
}

func mathUnaryMethod(name string, operation func(float64) float64) func(*object.EmeraldValue, ...*object.EmeraldValue) *object.EmeraldValue {
	return func(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
		if len(args) != 1 {
			return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 1)", len(args)))
		}
		input, errValue := mathFloatArgument(args[0])
		if errValue != nil {
			return errValue
		}
		result := operation(input)
		if math.IsNaN(result) && !math.IsNaN(input) {
			return mathDomainError(name)
		}
		if name == "gamma" && math.IsInf(result, 0) && input < 0 && input == math.Trunc(input) {
			return mathDomainError(name)
		}
		return newFloat(result)
	}
}

func mathBinaryMethod(name string, operation func(float64, float64) float64) func(*object.EmeraldValue, ...*object.EmeraldValue) *object.EmeraldValue {
	return func(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
		if len(args) != 2 {
			return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 2)", len(args)))
		}
		left, errValue := mathFloatArgument(args[0])
		if errValue != nil {
			return errValue
		}
		right, errValue := mathFloatArgument(args[1])
		if errValue != nil {
			return errValue
		}
		result := operation(left, right)
		if math.IsNaN(result) && !math.IsNaN(left) && !math.IsNaN(right) {
			return mathDomainError(name)
		}
		return newFloat(result)
	}
}

func mathFrexp(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	value, errValue := mathFloatArgument(args[0])
	if errValue != nil {
		return errValue
	}
	fraction, exponent := math.Frexp(value)
	return &object.EmeraldValue{Type: object.ValueArray, Data: []*object.EmeraldValue{newFloat(fraction), newInt(int64(exponent))}, Class: R.Classes["Array"]}
}

func mathLdexp(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	value, errValue := mathFloatArgument(args[0])
	if errValue != nil {
		return errValue
	}
	if args[1] != nil && args[1].Type == object.ValueFloat && math.IsNaN(args[1].Data.(float64)) {
		return NewRangeError("float NaN out of range of integer")
	}
	exponent, ok := valueToInteger(args[1])
	if !ok {
		return NewTypeError("can't convert " + args[1].TypeName() + " into Integer")
	}
	return newFloat(math.Ldexp(value, int(exponent)))
}

func mathLgamma(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	value, errValue := mathFloatArgument(args[0])
	if errValue != nil {
		return errValue
	}
	result, sign := math.Lgamma(value)
	if math.IsInf(value, -1) {
		return mathDomainError("lgamma")
	}
	if value == 0 && math.Signbit(value) {
		sign = -1
	}
	return &object.EmeraldValue{Type: object.ValueArray, Data: []*object.EmeraldValue{newFloat(result), newInt(int64(sign))}, Class: R.Classes["Array"]}
}

func mathLog(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) < 1 || len(args) > 2 {
		return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 1..2)", len(args)))
	}
	value, errValue := mathFloatArgument(args[0])
	if errValue != nil {
		return errValue
	}
	result := math.Log(value)
	if len(args) == 2 {
		base, baseError := mathFloatArgument(args[1])
		if baseError != nil {
			return baseError
		}
		result /= math.Log(base)
	}
	if math.IsNaN(result) && !math.IsNaN(value) {
		return mathDomainError("log")
	}
	return newFloat(result)
}

func mathLog2(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 1 {
		return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 1)", len(args)))
	}
	if integer, ok := NumericBigIntOverride(args[0]); ok {
		if integer.Sign() < 0 {
			return mathDomainError("log2")
		}
		if integer.Sign() == 0 {
			return newFloat(math.Inf(-1))
		}
		mantissa := new(big.Float)
		exponent := new(big.Float).SetInt(integer).MantExp(mantissa)
		fraction, _ := mantissa.Float64()
		return newFloat(math.Log2(fraction) + float64(exponent))
	}
	value, errValue := mathFloatArgument(args[0])
	if errValue != nil {
		return errValue
	}
	result := math.Log2(value)
	if math.IsNaN(result) && !math.IsNaN(value) {
		return mathDomainError("log2")
	}
	return newFloat(result)
}

func intToS(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	base := int64(10)
	if len(args) > 0 && args[0] != nil && args[0].Type == object.ValueInteger {
		base = args[0].Data.(int64)
	}
	if base < 2 || base > 36 {
		return NewArgumentError("invalid radix")
	}
	if bigValue, ok := NumericBigIntOverride(receiver); ok {
		return &object.EmeraldValue{
			Type:  object.ValueString,
			Data:  bigValue.Text(int(base)),
			Class: R.Classes["String"],
		}
	}
	return &object.EmeraldValue{
		Type:  object.ValueString,
		Data:  strconv.FormatInt(receiver.Data.(int64), int(base)),
		Class: R.Classes["String"],
	}
}

func intSucc(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if value, ok := numericBigIntValue(receiver); ok {
		return NewIntegerFromBigInt(new(big.Int).Add(value, big.NewInt(1)))
	}
	v := receiver.Data.(int64)
	return &object.EmeraldValue{
		Type:  object.ValueInteger,
		Data:  v + 1,
		Class: R.Classes["Integer"],
	}
}

func numericCall(receiver *object.EmeraldValue, method string, args ...*object.EmeraldValue) *object.EmeraldValue {
	if CallMethod == nil || receiver == nil || !ReceiverHasCallableMethod(receiver, method) {
		return NewNoMethodError("undefined method `" + method + "'")
	}
	return CallMethod(receiver, method, args...)
}

func numericAbs(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 0 {
		return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 0)", len(args)))
	}
	negative := numericCall(receiver, "<", newInt(0))
	if negative != nil && negative.Type == object.ValueException {
		return negative
	}
	if isTruthy(negative) {
		return numericCall(receiver, "-@")
	}
	return receiver
}

func numericAbs2(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 0 {
		return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 0)", len(args)))
	}
	return numericCall(receiver, "*", receiver)
}

func numericArg(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 0 {
		return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 0)", len(args)))
	}
	if receiver != nil && receiver.Type == object.ValueFloat {
		value := receiver.Data.(float64)
		if math.IsNaN(value) {
			return receiver
		}
		if math.Signbit(value) {
			return newFloat(math.Pi)
		}
		return newInt(0)
	}
	negative := numericCall(receiver, "<", newInt(0))
	if negative != nil && negative.Type == object.ValueException {
		return negative
	}
	if isTruthy(negative) {
		return newFloat(math.Pi)
	}
	return newInt(0)
}

