func numericPolar(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 0 {
		return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 0)", len(args)))
	}
	absolute := numericCall(receiver, "abs")
	if absolute != nil && absolute.Type == object.ValueException {
		return absolute
	}
	angle := numericArg(receiver)
	if angle != nil && angle.Type == object.ValueException {
		return angle
	}
	if receiver != nil && receiver.Type == object.ValueFloat && math.IsNaN(receiver.Data.(float64)) {
		angle = newFloat(math.NaN())
	}
	return &object.EmeraldValue{Type: object.ValueArray, Data: []*object.EmeraldValue{absolute, angle}, Class: R.Classes["Array"]}
}

