func numericUnaryMinus(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 0 {
		return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 0)", len(args)))
	}
	coerced := numericCall(receiver, "coerce", newInt(0))
	if coerced != nil && coerced.Type == object.ValueException {
		return coerced
	}
	if coerced == nil || coerced.Type != object.ValueArray {
		return typeError("coerce must return [x, y]")
	}
	values := coerced.Data.([]*object.EmeraldValue)
	if len(values) != 2 {
		return typeError("coerce must return [x, y]")
	}
	return numericCall(values[0], "-", values[1])
}

func numericCoerce(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 1 {
		return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 1)", len(args)))
	}
	other := args[0]
	if _, receiverIsRational := rationalValueData(receiver); receiverIsRational && bigDecimalDataFrom(other) != nil {
		return typeError("BigDecimal can't be coerced into Rational")
	}
	if other != nil && receiverEffectiveClass(other) == receiverEffectiveClass(receiver) {
		return &object.EmeraldValue{Type: object.ValueArray, Data: []*object.EmeraldValue{other, receiver}, Class: R.Classes["Array"]}
	}
	convertedOther, errVal := numericCoerceFloat(other)
	if errVal != nil {
		return errVal
	}
	convertedSelf, errVal := numericCoerceFloat(receiver)
	if errVal != nil {
		return errVal
	}
	return &object.EmeraldValue{Type: object.ValueArray, Data: []*object.EmeraldValue{convertedOther, convertedSelf}, Class: R.Classes["Array"]}
}

func numericCoerceFloat(value *object.EmeraldValue) (*object.EmeraldValue, *object.EmeraldValue) {
	if value == nil || value.Type == object.ValueNil {
		return nil, typeError("can't convert nil into Float")
	}
	if value.Type == object.ValueFloat {
		return value, nil
	}
	if value.Type == object.ValueInteger {
		integer, _ := numericBigIntValue(value)
		return newFloat(bigIntFloat64(integer)), nil
	}
	if value.Type == object.ValueString {
		parsed, err := strconv.ParseFloat(strings.TrimSpace(stringRawValue(value)), 64)
		if err != nil {
			return nil, NewArgumentError("invalid value for Float()")
		}
		return newFloat(parsed), nil
	}
	if CallMethod == nil || !ReceiverHasCallableMethod(value, "to_f") {
		return nil, typeError("can't convert " + value.TypeName() + " into Float")
	}
	converted := CallMethod(value, "to_f")
	if converted == nil || converted.Type == object.ValueException {
		return nil, converted
	}
	if converted == nil || converted.Type != object.ValueFloat {
		return nil, typeError("can't convert " + value.TypeName() + " into Float")
	}
	return converted, nil
}

func numericIsZero(value *object.EmeraldValue) bool {
	if value == nil {
		return false
	}
	switch value.Type {
	case object.ValueInteger:
		integer, _ := numericBigIntValue(value)
		return integer.Sign() == 0
	case object.ValueFloat:
		return value.Data.(float64) == 0
	}
	if data, ok := value.Data.(*complexData); ok && data != nil {
		return data.real == 0 && data.imag == 0
	}
	return false
}

func numericDiv(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 1 {
		return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 1)", len(args)))
	}
	if numericIsZero(args[0]) {
		return newRuntimeException(R.Classes["ZeroDivisionError"], "divided by 0")
	}
	quotient := numericCall(receiver, "/", args[0])
	if quotient != nil && quotient.Type == object.ValueException {
		return quotient
	}
	return numericCall(quotient, "floor")
}

func numericFdiv(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 1 {
		return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 1)", len(args)))
	}
	left, errVal := numericCoerceFloat(receiver)
	if errVal != nil {
		return errVal
	}
	right, errVal := numericCoerceFloat(args[0])
	if errVal != nil {
		return errVal
	}
	return newFloat(left.Data.(float64) / right.Data.(float64))
}

func numericQuo(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 1 {
		return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 1)", len(args)))
	}
	if args[0] != nil && args[0].Type == object.ValueFloat {
		return numericCall(receiver, "/", args[0])
	}
	converted := numericCall(receiver, "to_r")
	if converted != nil && converted.Type == object.ValueException {
		return converted
	}
	if converted == nil || converted.Class != R.Classes["Rational"] {
		return typeError("to_r did not return Rational")
	}
	return numericCall(converted, "/", args[0])
}

