func numericModulo(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 1 {
		return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 1)", len(args)))
	}
	quotient := numericCall(receiver, "div", args[0])
	if quotient != nil && quotient.Type == object.ValueException {
		return quotient
	}
	product := numericCall(args[0], "*", quotient)
	if product != nil && product.Type == object.ValueException {
		return product
	}
	return numericCall(receiver, "-", product)
}

func numericRemainder(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 1 {
		return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 1)", len(args)))
	}
	other := args[0]
	result := numericCall(receiver, "%", other)
	if result != nil && result.Type == object.ValueException {
		return result
	}
	equalZero := numericCall(result, "==", newInt(0))
	if equalZero != nil && equalZero.Type == object.ValueException {
		return equalZero
	}
	if isTruthy(equalZero) {
		return result
	}
	selfNegative := numericCall(receiver, "<", newInt(0))
	if selfNegative != nil && selfNegative.Type == object.ValueException {
		return selfNegative
	}
	if isTruthy(selfNegative) {
		otherPositive := numericCall(other, ">", newInt(0))
		if otherPositive != nil && otherPositive.Type == object.ValueException {
			return otherPositive
		}
		if isTruthy(otherPositive) {
			return numericCall(result, "-", other)
		}
		return result
	}
	selfPositive := numericCall(receiver, ">", newInt(0))
	if selfPositive != nil && selfPositive.Type == object.ValueException {
		return selfPositive
	}
	if isTruthy(selfPositive) {
		otherNegative := numericCall(other, "<", newInt(0))
		if otherNegative != nil && otherNegative.Type == object.ValueException {
			return otherNegative
		}
		if isTruthy(otherNegative) {
			return numericCall(result, "-", other)
		}
	}
	return result
}

