func numericStep(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	blockGiven := BlockGivenCheck != nil && BlockGivenCheck() && CurrentBlockValue != nil
	if blockGiven {
		block := CurrentBlockValue()
		blockGiven = block != nil && block.Type != object.ValueNil
	}
	positional := args
	var keywordHash *object.EmeraldValue
	if len(args) > 0 && args[len(args)-1] != nil && args[len(args)-1].Type == object.ValueHash {
		keywordHash = args[len(args)-1]
		positional = args[:len(args)-1]
	}
	if len(positional) > 2 {
		return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 0..2)", len(positional)))
	}
	var limit *object.EmeraldValue
	step := newInt(1)
	if len(positional) >= 1 {
		limit = positional[0]
	}
	if len(positional) == 2 {
		step = positional[1]
	}
	if keywordHash != nil {
		for key, value := range valueToHashMap(keywordHash) {
			switch specName(key) {
			case "to":
				if len(positional) >= 1 {
					return NewArgumentError("to is given twice")
				}
				limit = value
			case "by":
				if len(positional) == 2 {
					return NewArgumentError("step is given twice")
				}
				step = value
			default:
				return NewArgumentError("unknown keyword: " + specName(key))
			}
		}
	}
	valid := receiver != nil && (receiver.Type == object.ValueInteger || receiver.Type == object.ValueFloat) &&
		step != nil && (step.Type == object.ValueInteger || step.Type == object.ValueFloat) &&
		(limit == nil || limit.Type == object.ValueNil || limit.Type == object.ValueInteger || limit.Type == object.ValueFloat)
	if !valid {
		errVal := NewArgumentError("step must be numeric")
		if blockGiven {
			return errVal
		}
		data := &enumeratorData{
			sizeFunc:  func() *object.EmeraldValue { return errVal },
			limitFunc: func(int) ([]*object.EmeraldValue, *object.EmeraldValue) { return nil, errVal },
		}
		return &object.EmeraldValue{Type: object.ValueObject, Data: data, Class: R.Classes["Enumerator"]}
	}
	if numericStepIsZero(step) {
		return NewArgumentError("step can't be 0")
	}
	data := numericStepEnumeratorData(receiver, limit, step, false)
	sequence := &object.EmeraldValue{Type: object.ValueObject, Data: data, Class: R.Classes["Enumerator::ArithmeticSequence"]}
	if !blockGiven {
		return sequence
	}
	values, errVal := data.limitFunc(-1)
	if errVal != nil {
		return errVal
	}
	for _, value := range values {
		LastBlockResult = nil
		if CallBlock != nil {
			CallBlock(value)
		}
		if LastException != nil {
			return LastException
		}
		if LastBlockResult != nil {
			result := LastBlockResult
			LastBlockResult = nil
			return result
		}
	}
	return receiver
}

func numericStepIsZero(value *object.EmeraldValue) bool {
	if value.Type == object.ValueFloat {
		return value.Data.(float64) == 0
	}
	integer, _ := numericBigIntValue(value)
	return integer.Sign() == 0
}

func numericStepEnumeratorData(start, limit, step *object.EmeraldValue, exclusive bool) *enumeratorData {
	data := &enumeratorData{arithBegin: start, arithEnd: limit, arithStep: step, arithExclusive: exclusive}
	unbounded := limit == nil || limit.Type == object.ValueNil
	allInteger := start.Type == object.ValueInteger && step.Type == object.ValueInteger && (unbounded || limit.Type == object.ValueInteger)
	if allInteger {
		startInteger, _ := numericBigIntValue(start)
		stepInteger, _ := numericBigIntValue(step)
		var limitInteger *big.Int
		if !unbounded {
			limitInteger, _ = numericBigIntValue(limit)
		}
		data.sizeFunc = func() *object.EmeraldValue {
			if unbounded {
				return newFloat(math.Inf(1))
			}
			return NewIntegerFromBigInt(numericIntegerStepSize(startInteger, limitInteger, stepInteger, exclusive))
		}
		data.limitFunc = func(requested int) ([]*object.EmeraldValue, *object.EmeraldValue) {
			if unbounded && requested < 0 {
				return nil, NewRangeError("cannot materialize infinite arithmetic sequence")
			}
			count := requested
			if !unbounded {
				size := numericIntegerStepSize(startInteger, limitInteger, stepInteger, exclusive)
				if !size.IsInt64() {
					if requested < 0 {
						return nil, NewRangeError("arithmetic sequence too large")
					}
				} else if requested < 0 || int64(requested) > size.Int64() {
					count = int(size.Int64())
				}
			}
			if count < 0 {
				count = 0
			}
			values := make([]*object.EmeraldValue, count)
			for i := 0; i < count; i++ {
				value := new(big.Int).Mul(stepInteger, big.NewInt(int64(i)))
				value.Add(value, startInteger)
				values[i] = NewIntegerFromBigInt(value)
			}
			return values, nil
		}
		return data
	}
	startFloat := numericValueAsFloat(start)
	stepFloat := numericValueAsFloat(step)
	limitFloat := math.Inf(1)
	if stepFloat < 0 {
		limitFloat = math.Inf(-1)
	}
	if !unbounded {
		limitFloat = numericValueAsFloat(limit)
	}
	data.sizeFunc = func() *object.EmeraldValue {
		if unbounded || numericFloatStepInfiniteSize(startFloat, limitFloat, stepFloat) {
			return newFloat(math.Inf(1))
		}
		return newInt(int64(numericFloatStepSize(startFloat, limitFloat, stepFloat, exclusive)))
	}
	data.limitFunc = func(requested int) ([]*object.EmeraldValue, *object.EmeraldValue) {
		infinite := unbounded || numericFloatStepInfiniteSize(startFloat, limitFloat, stepFloat)
		if infinite && requested < 0 {
			return nil, NewRangeError("cannot materialize infinite arithmetic sequence")
		}
		count := requested
		if !infinite {
			size := numericFloatStepSize(startFloat, limitFloat, stepFloat, exclusive)
			if requested < 0 || requested > size {
				count = size
			}
		}
		if count < 0 {
			count = 0
		}
		values := make([]*object.EmeraldValue, count)
		for i := 0; i < count; i++ {
			value := startFloat
			if i != 0 {
				value = startFloat + float64(i)*stepFloat
			}
			if !unbounded && i == count-1 && math.Abs(value-limitFloat) <= math.Max(1, math.Abs(limitFloat))*1e-12 {
				value = limitFloat
			}
			values[i] = newFloat(value)
		}
		return values, nil
	}
	return data
}

func numericIntegerStepSize(start, limit, step *big.Int, exclusive bool) *big.Int {
	if step.Sign() > 0 && start.Cmp(limit) > 0 || step.Sign() < 0 && start.Cmp(limit) < 0 {
		return big.NewInt(0)
	}
	difference := new(big.Int).Sub(limit, start)
	if difference.Sign() < 0 {
		difference.Neg(difference)
	}
	stepAbs := new(big.Int).Abs(new(big.Int).Set(step))
	if exclusive {
		if difference.Sign() == 0 {
			return big.NewInt(0)
		}
		difference.Sub(difference, big.NewInt(1))
	}
	return new(big.Int).Add(new(big.Int).Quo(difference, stepAbs), big.NewInt(1))
}

func numericFloatStepInfiniteSize(start, limit, step float64) bool {
	if math.IsInf(step, 0) {
		return false
	}
	if step > 0 && math.IsInf(limit, 1) && !math.IsInf(start, 1) {
		return true
	}
	return step < 0 && math.IsInf(limit, -1) && !math.IsInf(start, -1)
}

func numericFloatStepSize(start, limit, step float64, exclusive bool) int {
	if math.IsNaN(start) || math.IsNaN(limit) || math.IsNaN(step) {
		return 0
	}
	if step > 0 && start > limit || step < 0 && start < limit {
		return 0
	}
	if start == limit {
		if exclusive {
			return 0
		}
		if math.IsInf(start, 0) && !math.IsInf(step, 0) {
			return 0
		}
		return 1
	}
	if math.IsInf(step, 0) {
		return 1
	}
	if math.IsInf(start, 0) || math.IsInf(limit, 0) {
		return 0
	}
	ratio := (limit - start) / step
	if ratio < 0 {
		return 0
	}
	if exclusive {
		count := int(math.Ceil(ratio))
		next := start + float64(count)*step
		if (step > 0 && next < limit) || (step < 0 && next > limit) {
			count++
		}
		return count
	}
	return int(math.Floor(ratio+1e-12)) + 1
}

func intPred(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if value, ok := numericBigIntValue(receiver); ok {
		return NewIntegerFromBigInt(new(big.Int).Sub(value, big.NewInt(1)))
	}
	v := receiver.Data.(int64)
	return &object.EmeraldValue{
		Type:  object.ValueInteger,
		Data:  v - 1,
		Class: R.Classes["Integer"],
	}
}

func intChr(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) > 1 {
		return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 0..1)", len(args)))
	}
	integer, ok := numericBigIntValue(receiver)
	if !ok || !integer.IsInt64() {
		return NewRangeError("bignum out of char range")
	}
	codepoint := integer.Int64()
	if codepoint < 0 {
		return NewRangeError(fmt.Sprintf("%d out of char range", codepoint))
	}
	encoding := ""
	if len(args) == 1 {
		encoding = encodingName(args[0])
		if encoding == "" {
			return typeError("no implicit conversion into String")
		}
		if canonical, found := canonicalEncodingFindName(encoding); found {
			encoding = canonical
		} else {
			return NewArgumentError("unknown encoding name - " + encoding)
		}
	} else if codepoint <= 127 {
		encoding = "US-ASCII"
	} else if codepoint <= 255 {
		encoding = "BINARY"
	} else if defaultInternalEncoding != "" {
		encoding = defaultInternalEncoding
	} else {
		return NewRangeError(fmt.Sprintf("%d out of char range", codepoint))
	}

	var raw string
	switch normalizedEncodingName(encoding) {
	case "US_ASCII":
		if codepoint > 127 {
			return NewRangeError(fmt.Sprintf("%d out of char range", codepoint))
		}
		raw = string([]byte{byte(codepoint)})
	case "BINARY", "ASCII_8BIT":
		if codepoint > 255 {
			return NewRangeError(fmt.Sprintf("%d out of char range", codepoint))
		}
		raw = string([]byte{byte(codepoint)})
	case "UTF_8":
		if codepoint > utf8.MaxRune || codepoint >= 0xD800 && codepoint <= 0xDFFF {
			return NewRangeError(fmt.Sprintf("invalid codepoint 0x%X in UTF-8", codepoint))
		}
		raw = string(rune(codepoint))
	case "CESU_8":
		if codepoint > utf8.MaxRune || codepoint >= 0xD800 && codepoint <= 0xDFFF {
			return NewRangeError(fmt.Sprintf("invalid codepoint 0x%X in CESU-8", codepoint))
		}
		encodeThreeBytes := func(value int64) []byte {
			return []byte{byte(0xE0 | value>>12), byte(0x80 | value>>6&0x3F), byte(0x80 | value&0x3F)}
		}
		if codepoint < 0x10000 {
			raw = string(rune(codepoint))
		} else {
			value := codepoint - 0x10000
			high := int64(0xD800) + value>>10
			low := int64(0xDC00) + value&0x3FF
			raw = string(append(encodeThreeBytes(high), encodeThreeBytes(low)...))
		}
	case "SHIFT_JIS", "SJIS":
		switch {
		case codepoint <= 0x7f, codepoint >= 0xA1 && codepoint <= 0xDF:
			raw = string([]byte{byte(codepoint)})
		case codepoint >= 0x8140 && codepoint <= 0xFC4B && codepoint&0xff >= 0x40 && codepoint&0xff <= 0xFC && codepoint&0xff != 0x7F:
			raw = string([]byte{byte(codepoint >> 8), byte(codepoint)})
		default:
			return NewRangeError(fmt.Sprintf("invalid codepoint 0x%X in SHIFT_JIS", codepoint))
		}
	case "EUC_JP":
		if codepoint >= 0xA1A1 && codepoint <= 0xFEFE && codepoint&0xff >= 0xA1 {
			raw = string([]byte{byte(codepoint >> 8), byte(codepoint)})
		} else if codepoint <= 0x7f {
			raw = string([]byte{byte(codepoint)})
		} else {
			return NewRangeError(fmt.Sprintf("invalid codepoint 0x%X in EUC-JP", codepoint))
		}
	default:
		return NewRangeError(fmt.Sprintf("invalid codepoint 0x%X in %s", codepoint, encoding))
	}
	return stringWithEncoding(raw, encoding)
}

