func floatRound(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	f := receiver.Data.(float64)
	ndigits := int64(0)
	half := "up"
	positional := args
	if len(args) > 0 && args[len(args)-1] != nil && args[len(args)-1].Type == object.ValueHash {
		for key, value := range valueToHashMap(args[len(args)-1]) {
			if specName(key) == "half" && value != nil && value.Type != object.ValueNil {
				half = specName(value)
			}
		}
		positional = args[:len(args)-1]
	}
	if half != "up" && half != "down" && half != "even" {
		return NewArgumentError("invalid rounding mode: " + half)
	}
	if len(positional) > 1 {
		return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 0..1)", len(positional)))
	}
	if len(positional) == 1 {
		value, ok := valueToInteger(positional[0])
		if !ok {
			return typeError("can't convert " + positional[0].TypeName() + " into Integer")
		}
		ndigits = value
	}
	if math.IsNaN(f) {
		if len(positional) == 1 && ndigits <= 0 {
			return newRuntimeException(R.Classes["RangeError"], "NaN")
		}
		if len(positional) == 1 && ndigits > 0 {
			return receiver
		}
		return newRuntimeException(R.Classes["FloatDomainError"], "NaN")
	}
	if math.IsInf(f, 0) {
		if len(positional) == 1 && ndigits > 0 {
			return receiver
		}
		return newRuntimeException(R.Classes["FloatDomainError"], "Infinity")
	}
	if ndigits > 0 {
		if ndigits > 308 || f == 0 {
			return newFloat(f)
		}
		scale := math.Pow10(int(ndigits))
		return newFloat(roundScaledFloat(f, scale, half) / scale)
	}
	if ndigits < 0 {
		scale := math.Pow10(int(-ndigits))
		rounded := roundScaledFloat(f/scale, 1, half) * scale
		if math.Abs(rounded) > float64(math.MaxInt64) {
			return newFloat(rounded)
		}
		return newInt(int64(rounded))
	}
	rounded := roundScaledFloat(f, 1, half)
	return newInt(int64(rounded))
}

func roundScaledFloat(value, scale float64, half string) float64 {
	scaled := value * scale
	sign := 1.0
	if scaled < 0 || math.Signbit(scaled) {
		sign = -1
		scaled = -scaled
	}
	floor := math.Floor(scaled)
	frac := scaled - floor
	switch {
	case frac > 0.5:
		floor++
	case frac < 0.5:
	default:
		switch half {
		case "down":
		case "even":
			if math.Mod(floor, 2) != 0 {
				floor++
			}
		default:
			floor++
		}
	}
	return sign * floor
}

