func floatRelationalCompare(receiver, other *object.EmeraldValue, op string) *object.EmeraldValue {
	cmp := floatCompare(receiver, other)
	if cmp != nil && cmp.Type == object.ValueException {
		return cmp
	}
	if cmp == nil || cmp.Type == object.ValueNil {
		if other != nil && (other.Type == object.ValueInteger || other.Type == object.ValueFloat || classInheritsFrom(other.Class, R.Classes["Numeric"])) {
			return R.FalseVal
		}
		return NewArgumentError("comparison of Float with " + other.TypeName() + " failed")
	}
	value := cmp.Data.(int64)
	switch op {
	case "<":
		if value < 0 {
			return R.TrueVal
		}
	case ">":
		if value > 0 {
			return R.TrueVal
		}
	case "<=":
		if value <= 0 {
			return R.TrueVal
		}
	case ">=":
		if value >= 0 {
			return R.TrueVal
		}
	}
	return R.FalseVal
}

func floatCompare(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) < 1 {
		return R.NilVal
	}
	l := receiver.Data.(float64)
	if math.IsNaN(l) {
		return R.NilVal
	}
	switch r := args[0].Data.(type) {
	case int64:
		return floatCompareNumber(l, float64(r))
	case float64:
		return floatCompareNumber(l, r)
	}
	if math.IsInf(l, 0) && CallMethod != nil && receiverHasCallableMethod(args[0], "infinite?") {
		result := CallMethod(args[0], "infinite?")
		if result != nil && result.Type == object.ValueInteger {
			otherInf := result.Data.(int64)
			if math.IsInf(l, 1) {
				if otherInf > 0 {
					return newInt(0)
				}
				return newInt(1)
			}
			if otherInf < 0 {
				return newInt(0)
			}
			return newInt(-1)
		}
		if math.IsInf(l, 1) {
			return newInt(1)
		}
		return newInt(-1)
	}
	if CallMethod != nil && receiverHasCallableMethod(args[0], "coerce") {
		coerced := CallMethod(args[0], "coerce", receiver)
		if coerced != nil && coerced.Type == object.ValueException {
			return coerced
		}
		if coerced == nil || coerced.Type != object.ValueArray {
			return NewTypeError("coerce must return [x, y]")
		}
		pair := coerced.Data.([]*object.EmeraldValue)
		if len(pair) != 2 {
			return NewTypeError("coerce must return [x, y]")
		}
		left, okLeft := numericValueAsFloatOK(pair[0])
		right, okRight := numericValueAsFloatOK(pair[1])
		if !okLeft || !okRight {
			if CallMethod != nil && receiverHasCallableMethod(pair[0], "<=>") {
				return CallMethod(pair[0], "<=>", pair[1])
			}
			return NewTypeError("coerce must return [x, y]")
		}
		return floatCompareNumber(left, right)
	}
	return R.NilVal
}

func floatCompareNumber(left, right float64) *object.EmeraldValue {
	if math.IsNaN(left) || math.IsNaN(right) {
		return R.NilVal
	}
	if left < right {
		return newInt(-1)
	}
	if left > right {
		return newInt(1)
	}
	return newInt(0)
}

func stringAdd(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	right, errVal := stringCoerceConcatenationString(args[0])
	if errVal != nil {
		return errVal
	}
	encoding, errVal := StringConcatenationEncoding(receiver, right)
	if errVal != nil {
		return errVal
	}
	return stringWithEncoding(stringRawValue(receiver)+stringRawValue(right), encoding)
}

func stringCompare(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) < 1 || args[0] == nil {
		return R.NilVal
	}
	other := args[0]
	if other.Type != object.ValueString {
		if CallMethod != nil && receiverHasCallableMethod(other, "to_str") {
			converted := CallMethod(other, "to_str")
			if converted != nil && converted.Type == object.ValueException {
				return converted
			}
			if converted == nil || converted.Type != object.ValueString {
				return R.NilVal
			}
			other = converted
		} else if CallMethod != nil && receiverHasCallableMethod(other, "<=>") && stringComparisonInverseDepth == 0 {
			stringComparisonInverseDepth++
			inverse := CallMethod(other, "<=>", receiver)
			stringComparisonInverseDepth--
			if inverse == nil || inverse.Type != object.ValueInteger {
				return R.NilVal
			}
			value, ok := numericBigIntValue(inverse)
			if !ok {
				return R.NilVal
			}
			return NewIntegerFromBigInt(value.Neg(value))
		} else {
			return R.NilVal
		}
	}
	leftRaw, rightRaw := stringRawValue(receiver), stringRawValue(other)
	cmp := strings.Compare(leftRaw, rightRaw)
	if cmp == 0 && leftRaw != "" && stringHasNonASCIIByte(leftRaw) {
		leftEncoding, rightEncoding := stringEncodingName(receiver), stringEncodingName(other)
		if !strings.EqualFold(leftEncoding, rightEncoding) {
			cmp = stringEncodingIndexCompare(leftEncoding, rightEncoding)
		}
	}
	switch {
	case cmp < 0:
		return &object.EmeraldValue{Type: object.ValueInteger, Data: int64(-1), Class: R.Classes["Integer"]}
	case cmp > 0:
		return &object.EmeraldValue{Type: object.ValueInteger, Data: int64(1), Class: R.Classes["Integer"]}
	default:
		return &object.EmeraldValue{Type: object.ValueInteger, Data: int64(0), Class: R.Classes["Integer"]}
	}
}

func stringEncodingIndexCompare(left, right string) int {
	indices := map[string]int{
		"BINARY": 0, "UTF-8": 1, "US-ASCII": 2, "ISO-8859-1": 20,
	}
	leftName, rightName := canonicalEncodingCompatibilityName(left), canonicalEncodingCompatibilityName(right)
	leftIndex, leftFound := indices[normalizeEncodingNameForIO(leftName)]
	rightIndex, rightFound := indices[normalizeEncodingNameForIO(rightName)]
	if leftFound && rightFound {
		return leftIndex - rightIndex
	}
	return strings.Compare(normalizeEncodingNameForIO(leftName), normalizeEncodingNameForIO(rightName))
}

func stringMul(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 1 {
		return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 1)", len(args)))
	}
	countValue := args[0]
	if countValue == nil || countValue.Type != object.ValueInteger {
		if countValue == nil || CallMethod == nil || !receiverHasCallableMethod(countValue, "to_int") {
			return conversionTypeErrorToInteger(countValue)
		}
		countValue = CallMethod(countValue, "to_int")
		if countValue == nil || countValue.Type != object.ValueInteger {
			return conversionTypeErrorToInteger(args[0])
		}
	}
	count, ok := numericBigIntValue(countValue)
	if !ok {
		return conversionTypeErrorToInteger(args[0])
	}
	s := stringRawValue(receiver)
	if count.Sign() < 0 {
		return NewArgumentError("negative argument")
	}
	if !count.IsInt64() {
		return NewRangeError("integer out of range")
	}
	n := count.Int64()
	if s == "" || count.Sign() == 0 {
		return stringWithEncoding("", stringEncodingName(receiver))
	}
	maxInt := int(^uint(0) >> 1)
	if n > int64(maxInt/len(s)) {
		return NewArgumentError("argument too big")
	}
	var builder strings.Builder
	builder.Grow(len(s) * int(n))
	for i := int64(0); i < n; i++ {
		builder.WriteString(s)
	}
	return stringWithEncoding(builder.String(), stringEncodingName(receiver))
}

func stringModulo(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver == nil || receiver.Type != object.ValueString {
		return typeError("no implicit conversion into String")
	}
	formatArgs := []*object.EmeraldValue{receiver}
	if len(args) == 1 && args[0] != nil && args[0].Type == object.ValueArray {
		formatArgs = append(formatArgs, args[0].Data.([]*object.EmeraldValue)...)
	} else if len(args) == 1 && args[0] != nil && CallMethod != nil && receiverHasCallableMethod(args[0], "to_ary") {
		converted := CallMethod(args[0], "to_ary")
		if converted != nil && converted.Type == object.ValueException {
			return converted
		}
		if converted != nil && converted.Type != object.ValueNil {
			if converted.Type != object.ValueArray {
				return typeError("can't convert " + args[0].TypeName() + " to Array")
			}
			formatArgs = append(formatArgs, converted.Data.([]*object.EmeraldValue)...)
		} else {
			formatArgs = append(formatArgs, args...)
		}
	} else {
		formatArgs = append(formatArgs, args...)
	}
	return builtinFormat(receiver, formatArgs...)
}

func stringLength(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return newInt(int64(stringCharacterLength(receiver)))
}

func stringCharacterLength(receiver *object.EmeraldValue) int {
	raw := stringRawValue(receiver)
	encoding := normalizedEncodingName(stringEncodingName(receiver))
	switch encoding {
	case "BINARY", "ASCII_8BIT", "US_ASCII":
		return len(raw)
	case "UTF_8":
		return utf8.RuneCountInString(raw)
	}
	if textEncoding := stringTextEncoding(stringEncodingName(receiver)); textEncoding != nil {
		if decoded, _, err := transform.String(textEncoding.NewDecoder(), raw); err == nil {
			return utf8.RuneCountInString(decoded)
		}
	}
	switch encoding {
	case "UTF_16", "UTF_16LE", "UTF_16BE":
		return (len(raw) + 1) / 2
	case "UTF_32", "UTF_32LE", "UTF_32BE":
		return (len(raw) + 3) / 4
	case "SHIFT_JIS", "SJIS", "WINDOWS_31J":
		return len(stringCharacterChunks(receiver))
	default:
		return utf8.RuneCountInString(raw)
	}
}

