func ioBufferResize(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data := ioBufferValueData(receiver)
	if data == nil {
		return R.NilVal
	}
	if data.locked {
		return NewException("IO::Buffer::LockedError", "Cannot resize locked buffer!")
	}
	if len(args) != 1 || args[0] == nil || args[0].Type != object.ValueInteger {
		return typeError("not an Integer")
	}
	size, ok := valueToInteger(args[0])
	if !ok {
		return typeError("not an Integer")
	}
	if size < 0 {
		return NewArgumentError("Size can't be negative!")
	}
	wasNull := data.null
	if !wasNull && data.origin == ioBufferExternalOrigin {
		return NewException("IO::Buffer::AccessError", "Cannot resize external buffer!")
	}
	if size == 0 {
		if data.storage != nil {
			data.storage.valid = false
		}
		data.storage = &ioBufferStorage{valid: true}
		data.offset = 0
		data.length = 0
		data.null = true
		data.origin = ioBufferNullOrigin
		data.mapped = false
		data.shared = false
		data.private = false
		data.readonly = false
		data.backingString = nil
		return receiver
	}
	oldBytes, _ := ioBufferBytes(data)
	resized := make([]byte, int(size))
	copy(resized, oldBytes)
	if data.storage == nil || !data.storage.valid {
		data.storage = &ioBufferStorage{valid: true}
	}
	data.storage.bytes = resized
	data.storage.valid = true
	data.offset = 0
	data.length = int(size)
	data.null = false
	data.backingString = nil
	data.readonly = false
	data.shared = false
	data.private = false
	if wasNull || data.origin == ioBufferNullOrigin || data.origin == ioBufferExternalOrigin {
		data.mapped = size >= int64(os.Getpagesize())
		if data.mapped {
			data.origin = ioBufferMappedOrigin
		} else {
			data.origin = ioBufferInternalOrigin
		}
	}
	return receiver
}

func ioBufferEach(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data := ioBufferValueData(receiver)
	bytes, errValue := ioBufferBytes(data)
	if errValue != nil {
		return errValue
	}
	if len(args) != 1 || args[0] == nil || args[0].Type != object.ValueSymbol || args[0].Data.(string) != "U8" {
		return NewArgumentError("Invalid data type!")
	}
	buildValues := func() ([]*object.EmeraldValue, *object.EmeraldValue) {
		values := make([]*object.EmeraldValue, len(bytes))
		for index, value := range bytes {
			values[index] = &object.EmeraldValue{Type: object.ValueArray, Data: []*object.EmeraldValue{newInt(int64(index)), newInt(int64(value))}, Class: R.Classes["Array"]}
		}
		return values, nil
	}
	if BlockGivenCheck == nil || !BlockGivenCheck() || CurrentBlockValue == nil || CurrentBlockValue() == nil || CallBlockWithArgs == nil {
		return newSizedGeneratorEnumerator(int64(len(bytes)), buildValues)
	}
	for index, value := range bytes {
		result := CallBlockWithArgs(CurrentBlockValue(), newInt(int64(index)), newInt(int64(value)))
		if result != nil && result.Type == object.ValueException {
			return result
		}
	}
	return receiver
}

func ioBufferTransfer(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data := ioBufferValueData(receiver)
	if data == nil {
		return R.NilVal
	}
	if data.locked {
		return NewException("IO::Buffer::LockedError", "Cannot transfer ownership of locked buffer!")
	}
	newData := *data
	if data.storage != nil && data.offset == 0 && data.length == len(data.storage.bytes) {
		copied := append([]byte(nil), data.storage.bytes...)
		newData.storage = &ioBufferStorage{bytes: copied, valid: true}
		data.storage.valid = false
	}
	data.null = true
	return newIOBufferValue(&newData)
}

func ioBufferSlice(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data := ioBufferValueData(receiver)
	if data == nil || len(args) < 2 {
		return R.NilVal
	}
	offset, _ := valueToInteger(args[0])
	length, _ := valueToInteger(args[1])
	if offset < 0 {
		offset = 0
	}
	if length < 0 {
		length = 0
	}
	return newIOBufferValue(&ioBufferData{storage: data.storage, offset: data.offset + int(offset), length: int(length), null: data.null, slice: true, readonly: data.readonly, origin: data.origin, backingString: data.backingString})
}

func ioBufferSetString(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data := ioBufferValueData(receiver)
	if data == nil || data.storage == nil || len(args) == 0 || args[0] == nil || args[0].Type != object.ValueString {
		return R.NilVal
	}
	if data.readonly {
		return NewException("IO::Buffer::AccessError", "Buffer is not writable!")
	}
	text := []byte(args[0].Data.(string))
	needed := data.offset + len(text)
	if needed > len(data.storage.bytes) {
		grown := make([]byte, needed)
		copy(grown, data.storage.bytes)
		data.storage.bytes = grown
	}
	copy(data.storage.bytes[data.offset:], text)
	if len(text) > data.length {
		data.length = len(text)
	}
	if data.backingString != nil {
		data.backingString.Data = string(data.storage.bytes)
	}
	if data.backingFile != "" && data.shared {
		if file, err := os.OpenFile(data.backingFile, os.O_WRONLY, 0); err == nil {
			_, _ = file.WriteAt(data.storage.bytes[data.offset:data.offset+data.length], data.fileOffset)
			_ = file.Close()
		}
	}
	return newInt(int64(len(text)))
}

func ioBufferGetString(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data := ioBufferValueData(receiver)
	if data == nil || data.storage == nil || !data.storage.valid {
		return NewException("IO::Buffer::InvalidatedError", "Buffer has been invalidated!")
	}
	relativeOffset := int64(0)
	length := int64(data.length)
	if len(args) > 0 {
		var ok bool
		relativeOffset, ok = valueToInteger(args[0])
		if !ok {
			return typeError("no implicit conversion into Integer")
		}
	}
	if len(args) > 1 {
		var ok bool
		length, ok = valueToInteger(args[1])
		if !ok {
			return typeError("no implicit conversion into Integer")
		}
	} else {
		length -= relativeOffset
	}
	if relativeOffset < 0 || length < 0 || relativeOffset > int64(data.length) {
		return NewArgumentError("specified offset+length is bigger than the buffer size")
	}
	start := data.offset + int(relativeOffset)
	end := start + int(length)
	bufferEnd := data.offset + data.length
	if end > bufferEnd {
		end = bufferEnd
	}
	if end > len(data.storage.bytes) {
		end = len(data.storage.bytes)
	}
	if start > end {
		return rubyString("")
	}
	return rubyString(string(data.storage.bytes[start:end]))
}

