func ioBufferBinaryOperation(receiver *object.EmeraldValue, maskValue *object.EmeraldValue, inPlace bool, operation func(byte, byte) byte) *object.EmeraldValue {
	maskData := ioBufferValueData(maskValue)
	if maskData == nil || maskValue.Class != R.Classes["IO::Buffer"] {
		return typeError("wrong argument type " + ioBufferMaskTypeName(maskValue) + " (expected IO::Buffer)")
	}
	source, sourceErr := ioBufferBytes(ioBufferValueData(receiver))
	if sourceErr != nil {
		return sourceErr
	}
	mask, maskErr := ioBufferBytes(maskData)
	if maskErr != nil {
		return maskErr
	}
	if len(mask) == 0 {
		return NewArgumentError("The mask should not be empty!")
	}
	target := source
	result := receiver
	if !inPlace {
		target = append([]byte(nil), source...)
		result = newIOBufferFromBytes(target)
	}
	for index := range target {
		target[index] = operation(target[index], mask[index%len(mask)])
	}
	return result
}

