func hashOne(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return hashPredicate(receiver, args, func(matched bool, matchCount *int) (bool, *object.EmeraldValue) {
		if *matchCount > 1 {
			return true, R.FalseVal
		}
		return false, nil
	}, func(matchCount int) *object.EmeraldValue {
		if matchCount == 1 {
			return R.TrueVal
		}
		return R.FalseVal
	})
}

func hashPredicate(receiver *object.EmeraldValue, args []*object.EmeraldValue, decide func(bool, *int) (bool, *object.EmeraldValue), finish func(int) *object.EmeraldValue) *object.EmeraldValue {
	if len(args) > 1 {
		return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 0..1)", len(args)))
	}
	keys, hash := hashOrderedKeysFromValue(receiver)
	if len(keys) == 0 {
		return finish(0)
	}
	blockGiven := len(args) == 0 && BlockGivenCheck != nil && BlockGivenCheck() && CurrentBlockValue != nil && CurrentBlockValue() != nil
	var block *object.EmeraldValue
	passesAsPair := false
	if blockGiven {
		block = CurrentBlockValue()
		var errVal *object.EmeraldValue
		passesAsPair, errVal = hashBlockPassesAsPair(block)
		if errVal != nil {
			return errVal
		}
	}
	matchCount := 0
	for _, k := range keys {
		v, ok := hash[k]
		if !ok {
			continue
		}
		pair := &object.EmeraldValue{
			Type:  object.ValueArray,
			Data:  []*object.EmeraldValue{k, v},
			Class: R.Classes["Array"],
		}
		var predicate *object.EmeraldValue
		if len(args) == 1 {
			predicate = enumerablePatternMatch(args[0], pair)
		} else if blockGiven {
			if passesAsPair {
				predicate = CallBlockWithArgs(block, pair)
			} else {
				predicate = CallBlockWithArgs(block, k, v)
			}
			if LastBlockResult != nil {
				result := LastBlockResult
				LastBlockResult = nil
				return result
			}
		} else {
			predicate = pair
		}
		if predicate != nil && predicate.Type == object.ValueException {
			return predicate
		}
		matched := isTruthy(predicate)
		if matched {
			matchCount++
		}
		stop, result := decide(matched, &matchCount)
		if stop {
			return result
		}
	}
	return finish(matchCount)
}

func hashBlockPassesAsPair(block *object.EmeraldValue) (bool, *object.EmeraldValue) {
	if arity, ok := procNativeArity(block); ok {
		if arity > 2 {
			return false, NewArgumentError("wrong number of arguments")
		}
		return arity != 2, nil
	}
	fn := procFunction(block)
	if fn != nil && callableIsLambda(block) {
		return true, nil
	}
	if fn != nil && fn.HasRestParam && len(fn.Params) == 0 && !callableIsLambda(block) {
		return true, nil
	}
	if fn != nil && !fn.HasRestParam && len(fn.Params) == 1 && !callableIsLambda(block) {
		return true, nil
	}
	return false, nil
}

func hashEachKey(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	keys, hash := hashOrderedKeysFromValue(receiver)
	if hash == nil {
		return &object.EmeraldValue{
			Type:  object.ValueArray,
			Data:  []*object.EmeraldValue{},
			Class: R.Classes["Array"],
		}
	}
	if CallBlock != nil && CurrentBlockValue != nil && CurrentBlockValue() != nil {
		for _, key := range keys {
			if _, ok := hash[key]; !ok {
				continue
			}
			LastBlockResult = nil
			ForEachClearNext()
			value := CallBlock(key)
			if value != nil && value.Type == object.ValueException {
				return value
			}
			if LastBlockResult != nil {
				result := LastBlockResult
				LastBlockResult = nil
				return result
			}
			if ForEachConsumeNext() {
				continue
			}
		}
		return receiver
	}
	return &object.EmeraldValue{
		Type:  object.ValueArray,
		Data:  keys,
		Class: R.Classes["Array"],
	}
}

func hashEachValue(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	keys, hash := hashOrderedKeysFromValue(receiver)
	values := make([]*object.EmeraldValue, 0, len(hash))
	if hash == nil {
		return &object.EmeraldValue{
			Type:  object.ValueArray,
			Data:  values,
			Class: R.Classes["Array"],
		}
	}
	if CallBlock != nil && CurrentBlockValue != nil && CurrentBlockValue() != nil {
		for _, key := range keys {
			value, ok := hash[key]
			if !ok {
				continue
			}
			LastBlockResult = nil
			ForEachClearNext()
			result := CallBlock(value)
			if result != nil && result.Type == object.ValueException {
				return result
			}
			if LastBlockResult != nil {
				blockResult := LastBlockResult
				LastBlockResult = nil
				return blockResult
			}
			if ForEachConsumeNext() {
				continue
			}
		}
		return receiver
	}
	for _, key := range keys {
		value, ok := hash[key]
		if ok {
			values = append(values, value)
		}
	}
	return &object.EmeraldValue{
		Type:  object.ValueArray,
		Data:  values,
		Class: R.Classes["Array"],
	}
}

func hashHasKey(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) < 1 {
		return R.FalseVal
	}
	if receiver == envObject {
		key, errVal := envCoerceKey(args[0])
		if errVal != nil {
			return errVal
		}
		if _, ok := hashLookup(valueToHashMap(receiver), rubyString(key)); ok {
			return R.TrueVal
		}
		return R.FalseVal
	}
	hash := hashData(receiver)
	if hash == nil {
		return R.FalseVal
	}
	if hash.CompareByIdentity {
		_, ok := hash.Pairs[hashIdentityKey(args[0])]
		if ok {
			return R.TrueVal
		}
		return R.FalseVal
	}
	_, _, ok := hashFindStoredKeyValue(hash, args[0])
	if ok {
		return R.TrueVal
	}
	return R.FalseVal
}

func stringCount(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 0 {
		return NewArgumentError("wrong number of arguments (given 0, expected 1+)")
	}
	sets, errVal := stringCharacterSets(args)
	if errVal != nil {
		return errVal
	}
	count := int64(0)
	for _, character := range stringRawValue(receiver) {
		if stringCharacterInAllSets(character, sets) {
			count++
		}
	}
	return newInt(count)
}

type stringCharacterSet struct {
	characters map[rune]struct{}
	sequence   []rune
	negated    bool
}

type stringCharacterSetToken struct {
	character rune
	escaped   bool
}

func stringCharacterSets(values []*object.EmeraldValue) ([]stringCharacterSet, *object.EmeraldValue) {
	sets := make([]stringCharacterSet, 0, len(values))
	for _, value := range values {
		raw, ok, viaToStr, errVal := evalCoerceToString(value)
		if errVal != nil {
			return nil, errVal
		}
		if !ok {
			return nil, conversionTypeErrorToStringForMode(value, viaToStr)
		}
		set, errVal := parseStringCharacterSet(raw, true)
		if errVal != nil {
			return nil, errVal
		}
		sets = append(sets, set)
	}
	return sets, nil
}

func tokenizeStringCharacterSet(raw string) []stringCharacterSetToken {
	runes := []rune(raw)
	tokens := make([]stringCharacterSetToken, 0, len(runes))
	for index := 0; index < len(runes); index++ {
		if runes[index] == '\\' && index+1 < len(runes) {
			index++
			tokens = append(tokens, stringCharacterSetToken{character: runes[index], escaped: true})
			continue
		}
		tokens = append(tokens, stringCharacterSetToken{character: runes[index]})
	}
	return tokens
}

func parseStringCharacterSet(raw string, allowNegation bool) (stringCharacterSet, *object.EmeraldValue) {
	tokens := tokenizeStringCharacterSet(raw)
	set := stringCharacterSet{characters: make(map[rune]struct{})}
	if allowNegation && len(tokens) > 1 && tokens[0].character == '^' && !tokens[0].escaped {
		set.negated = true
		tokens = tokens[1:]
	}
	for index := 0; index < len(tokens); {
		if index+2 < len(tokens) && tokens[index+1].character == '-' && !tokens[index+1].escaped {
			start := tokens[index].character
			end := tokens[index+2].character
			if start > end {
				return stringCharacterSet{}, NewArgumentError("invalid range")
			}
			for character := start; character <= end; character++ {
				set.sequence = append(set.sequence, character)
				set.characters[character] = struct{}{}
				if character == utf8.MaxRune {
					break
				}
			}
			index += 3
			continue
		}
		character := tokens[index].character
		set.sequence = append(set.sequence, character)
		set.characters[character] = struct{}{}
		index++
	}
	return set, nil
}

func (set stringCharacterSet) contains(character rune) bool {
	_, found := set.characters[character]
	if set.negated {
		return !found
	}
	return found
}

func stringCharacterInAllSets(character rune, sets []stringCharacterSet) bool {
	for _, set := range sets {
		if !set.contains(character) {
			return false
		}
	}
	return true
}

