func symbolEqual(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) < 1 {
		return R.FalseVal
	}
	if args[0].Type != object.ValueSymbol {
		return R.FalseVal
	}
	if symbolValuesEqual(receiver, args[0]) {
		return R.TrueVal
	}
	return R.FalseVal
}

func symbolValuesEqual(left, right *object.EmeraldValue) bool {
	if left == nil || right == nil || left.Type != object.ValueSymbol || right.Type != object.ValueSymbol {
		return false
	}
	s1 := left.Data.(string)
	s2 := right.Data.(string)
	if s1 != s2 {
		return false
	}
	if !ioWriteTextHasNonASCII(s1) {
		return true
	}
	return normalizeEncodingNameForIO(symbolEncodingName(left)) == normalizeEncodingNameForIO(symbolEncodingName(right))
}

func symbolCaseEqual(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return symbolEqual(receiver, args...)
}

func symbolCompare(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) < 1 || args[0] == nil || args[0].Type != object.ValueSymbol {
		return R.NilVal
	}
	left := receiver.Data.(string)
	right := args[0].Data.(string)
	switch strings.Compare(left, right) {
	case -1:
		return newInt(-1)
	case 1:
		return newInt(1)
	default:
		return newInt(0)
	}
}

func symbolStringValue(receiver *object.EmeraldValue) *object.EmeraldValue {
	return stringWithEncoding(receiver.Data.(string), symbolEncodingName(receiver))
}

func symbolCasecmp(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 0 || args[0] == nil || args[0].Type != object.ValueSymbol {
		return R.NilVal
	}
	return stringCasecmp(symbolStringValue(receiver), symbolStringValue(args[0]))
}

func symbolCasecmpQuestion(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 0 || args[0] == nil || args[0].Type != object.ValueSymbol {
		return R.NilVal
	}
	left := receiver.Data.(string)
	right := args[0].Data.(string)
	if left == "" && right == "" {
		return R.TrueVal
	}
	leftEncoding := normalizeEncodingNameForIO(symbolEncodingName(receiver))
	rightEncoding := normalizeEncodingNameForIO(symbolEncodingName(args[0]))
	if leftEncoding != rightEncoding {
		return R.NilVal
	}
	if leftEncoding == "UTF-8" {
		return boolValue(stringFullCaseFold(left) == stringFullCaseFold(right))
	}
	return boolValue(stringASCIICaseFold(left) == stringASCIICaseFold(right))
}

func symbolRegexpMatch(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return stringRegexpMatch(symbolStringValue(receiver), args...)
}

func symbolMatch(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return stringMatch(symbolStringValue(receiver), args...)
}

func symbolMatchQ(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return stringMatchQ(symbolStringValue(receiver), args...)
}

func symbolStartWith(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return stringStartWith(symbolStringValue(receiver), args...)
}

func symbolEndWith(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return stringEndWith(symbolStringValue(receiver), args...)
}

func symbolIndex(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return symbolSlice(receiver, args...)
}

func symbolSlice(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	value := stringWithEncoding(receiver.Data.(string), symbolEncodingName(receiver))
	return stringSlice(value, args...)
}

func rangeEach(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver.Type != object.ValueRange {
		return receiver
	}
	if BlockGivenCheck == nil || !BlockGivenCheck() {
		enum := objectToEnum(receiver)
		if data, ok := enum.Data.(*enumeratorData); ok {
			data.sizeFunc = func() *object.EmeraldValue { return rangeSize(receiver) }
		}
		return enum
	}
	r := receiver.Data.(*object.RRange)
	if r.StartMissing {
		if BlockGivenCheck != nil && BlockGivenCheck() {
			return typeError("can't iterate from NilClass")
		}
		return receiver
	}
	if r.EndMissing {
		start, ok := r.StartValue.(*object.EmeraldValue)
		if !ok || start == nil {
			return receiver
		}
		if start.Type != object.ValueInteger {
			return rangeStepNonNumeric(receiver, r, nil, true)
		}
		for value := start.Data.(int64); ; value++ {
			LastBlockResult = nil
			result := CallBlock(newInt(value))
			if result != nil && result.Type == object.ValueException {
				return result
			}
			if LastBlockResult != nil {
				result = LastBlockResult
				LastBlockResult = nil
				return result
			}
		}
	}

	start, startOk := r.StartValue.(*object.EmeraldValue)
	end, endOk := r.EndValue.(*object.EmeraldValue)
	if !startOk || start == nil || !endOk || end == nil {
		return receiver
	}
	collectResult := ForEachCollecting()
	collected := make([]*object.EmeraldValue, 0)

	if start.Type == object.ValueInteger && end.Type == object.ValueInteger && !r.StartFloat && !r.EndFloat {
		endVal := r.End
		if r.Exclusive {
			endVal--
		}
		for i := r.Start; i <= endVal; i++ {
			val := &object.EmeraldValue{
				Type:  object.ValueInteger,
				Data:  i,
				Class: R.Classes["Integer"],
			}
			if CallBlock != nil {
				LastBlockResult = nil
				ForEachClearNext()
				CallBlock(val)
				if LastBlockResult != nil {
					result := LastBlockResult
					LastBlockResult = nil
					return result
				}
				if ForEachConsumeNext() {
					continue
				}
			}
			if collectResult {
				collected = append(collected, val)
			}
		}
		if collectResult {
			return &object.EmeraldValue{
				Type:  object.ValueArray,
				Data:  collected,
				Class: R.Classes["Array"],
			}
		}
		return receiver
	}

	if (start.Type == object.ValueString || start.Type == object.ValueSymbol) &&
		(end.Type == object.ValueString || end.Type == object.ValueSymbol) {
		current := start
		for {
			cmp, ok := rangeCompareValues(current, end)
			if !ok || cmp > 0 || (r.Exclusive && cmp == 0) {
				break
			}
			if collectResult {
				collected = append(collected, current)
			}
			if CallBlock != nil {
				LastBlockResult = nil
				ForEachClearNext()
				CallBlock(current)
				if LastBlockResult != nil {
					result := LastBlockResult
					LastBlockResult = nil
					return result
				}
				if ForEachConsumeNext() {
					continue
				}
			}
			if equalValuesForRange(current, end) {
				break
			}
			next := rangeSuccessorValue(current, end)
			if next == nil || next == current {
				break
			}
			nextCmp, ok := rangeCompareValues(next, current)
			if !ok || nextCmp <= 0 {
				break
			}
			current = next
		}
		if collectResult {
			return &object.EmeraldValue{
				Type:  object.ValueArray,
				Data:  collected,
				Class: R.Classes["Array"],
			}
		}
		return receiver
	}

	if CallMethod != nil && receiverHasCallableMethod(start, "succ") {
		current := start
		for {
			cmp, ok := rangeCompareValues(current, end)
			if !ok {
				return typeError("can't iterate from " + valueTypeName(start))
			}
			if cmp > 0 || (r.Exclusive && cmp == 0) {
				break
			}
			if collectResult {
				collected = append(collected, current)
			}
			if CallBlock != nil {
				LastBlockResult = nil
				ForEachClearNext()
				CallBlock(current)
				if LastBlockResult != nil {
					result := LastBlockResult
					LastBlockResult = nil
					return result
				}
				if ForEachConsumeNext() {
					continue
				}
			}
			if current == end || current != start && cmp == 0 {
				break
			}
			next, errVal := rangeSuccOrTypeError(current)
			if errVal != nil {
				return errVal
			}
			current = next
		}
		if collectResult {
			return &object.EmeraldValue{
				Type:  object.ValueArray,
				Data:  collected,
				Class: R.Classes["Array"],
			}
		}
		return receiver
	}

	if start.Class != nil {
		return newRuntimeException(R.Classes["TypeError"], "can't iterate from "+start.Class.Name)
	}
	return newRuntimeException(R.Classes["TypeError"], "can't iterate from unknown type")
}

func rangeSuccessorValue(current, end *object.EmeraldValue) *object.EmeraldValue {
	if current != nil && end != nil && current.Type == object.ValueSymbol && end.Type == object.ValueSymbol {
		currentRunes := []rune(current.Data.(string))
		endRunes := []rune(end.Data.(string))
		if len(currentRunes) == 1 && len(endRunes) == 1 && currentRunes[0] < endRunes[0] {
			return rubySymbol(string(currentRunes[0] + 1))
		}
	}
	if CallMethod == nil {
		return nil
	}
	return CallMethod(current, "succ")
}

func rangeReverseEach(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 0 {
		return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 0)", len(args)))
	}
	if receiver.Type != object.ValueRange {
		return receiver
	}
	if BlockGivenCheck == nil || !BlockGivenCheck() || CallBlock == nil {
		r := receiver.Data.(*object.RRange)
		if r.EndMissing {
			return typeError("can't iterate from NilClass")
		}
		if r.StartMissing {
			end, ok := r.EndValue.(*object.EmeraldValue)
			if !ok || end == nil || end.Type != object.ValueInteger || r.EndFloat {
				return typeError("can't iterate from " + valueTypeName(end))
			}
			return newLimitGeneratorEnumerator(func(limit int) ([]*object.EmeraldValue, *object.EmeraldValue) {
				return rangeReverseBeginlessIntegerValues(r, limit), nil
			})
		}
		sizeValue := rangeReverseEachSizeValue(receiver)
		generator := func() ([]*object.EmeraldValue, *object.EmeraldValue) {
			return rangeReverseValues(receiver, -1)
		}
		if sizeValue != nil && sizeValue.Type == object.ValueInteger {
			return newSizedGeneratorEnumerator(sizeValue.Data.(int64), generator)
		}
		if sizeValue != nil && sizeValue.Type == object.ValueException {
			return newSizedValueGeneratorEnumerator(sizeValue, generator)
		}
		return newSizedValueGeneratorEnumerator(R.NilVal, generator)
	}

	values, errVal := rangeReverseValues(receiver, -1)
	if errVal != nil {
		return errVal
	}
	collectResult := ForEachCollecting()
	collected := make([]*object.EmeraldValue, 0, len(values))
	for _, value := range values {
		LastBlockResult = nil
		ForEachClearNext()
		result := CallBlock(value)
		if LastBlockResult != nil {
			blockResult := LastBlockResult
			LastBlockResult = nil
			return blockResult
		}
		if ForEachConsumeNext() {
			continue
		}
		if collectResult {
			collected = append(collected, result)
		}
	}
	if collectResult {
		return &object.EmeraldValue{Type: object.ValueArray, Data: collected, Class: R.Classes["Array"]}
	}
	return receiver
}

func rangeReverseValues(receiver *object.EmeraldValue, limit int) ([]*object.EmeraldValue, *object.EmeraldValue) {
	r := receiver.Data.(*object.RRange)
	if r.EndMissing {
		return nil, typeError("can't iterate from NilClass")
	}
	if r.StartMissing {
		end, ok := r.EndValue.(*object.EmeraldValue)
		if !ok || end == nil || end.Type != object.ValueInteger || r.EndFloat {
			return nil, typeError("can't iterate from " + valueTypeName(end))
		}
		return rangeReverseBeginlessIntegerValues(r, limit), nil
	}
	start, startOK := r.StartValue.(*object.EmeraldValue)
	end, endOK := r.EndValue.(*object.EmeraldValue)
	if !startOK || start == nil || !endOK || end == nil {
		return []*object.EmeraldValue{}, nil
	}
	if start.Type == object.ValueInteger && (end.Type == object.ValueInteger || end.Type == object.ValueFloat) && !r.StartFloat {
		last, ok := rangeReverseIntegerLast(r, end)
		if !ok {
			return nil, typeError("can't iterate from " + valueTypeName(end))
		}
		values := make([]*object.EmeraldValue, 0)
		for i := last; i >= r.Start; i-- {
			values = append(values, newInt(i))
			if limit >= 0 && len(values) >= limit {
				break
			}
		}
		return values, nil
	}
	if start.Type == object.ValueFloat || end.Type == object.ValueFloat {
		return nil, typeError("can't iterate from " + valueTypeName(end))
	}
	if (start.Type == object.ValueString || start.Type == object.ValueSymbol) &&
		(end.Type == object.ValueString || end.Type == object.ValueSymbol) {
		values := rangeToA(receiver)
		if values == nil || values.Type == object.ValueException {
			return nil, values
		}
		return reverseValueSlice(values.Data.([]*object.EmeraldValue), limit), nil
	}
	if _, errVal := rangeSuccOrTypeError(start); errVal != nil {
		return nil, errVal
	}
	values := rangeToA(receiver)
	if values == nil || values.Type == object.ValueException {
		return nil, values
	}
	return reverseValueSlice(values.Data.([]*object.EmeraldValue), limit), nil
}

func rangeReverseEachSizeValue(receiver *object.EmeraldValue) *object.EmeraldValue {
	r := receiver.Data.(*object.RRange)
	if r.EndMissing {
		return typeError("can't iterate from NilClass")
	}
	end, endOK := r.EndValue.(*object.EmeraldValue)
	if r.StartMissing {
		if !endOK || end == nil || end.Type != object.ValueInteger || r.EndFloat {
			return typeError("can't iterate from " + valueTypeName(end))
		}
		return newFloat(math.Inf(1))
	}
	start, startOK := r.StartValue.(*object.EmeraldValue)
	if !startOK || start == nil || !endOK || end == nil {
		return R.NilVal
	}
	if start.Type == object.ValueNil || end.Type == object.ValueNil {
		return typeError("can't iterate from NilClass")
	}
	if start.Type == object.ValueInteger && (end.Type == object.ValueInteger || end.Type == object.ValueFloat) && !r.StartFloat {
		last, ok := rangeReverseIntegerLast(r, end)
		if !ok {
			return typeError("can't iterate from " + valueTypeName(end))
		}
		size := last - r.Start + 1
		if size < 0 {
			size = 0
		}
		return newInt(size)
	}
	if start.Type == object.ValueFloat || end.Type == object.ValueFloat {
		return typeError("can't iterate from " + valueTypeName(end))
	}
	return R.NilVal
}

func rangeReverseIntegerLast(r *object.RRange, end *object.EmeraldValue) (int64, bool) {
	switch end.Type {
	case object.ValueInteger:
		last := r.End
		if r.Exclusive {
			last--
		}
		return last, true
	case object.ValueFloat:
		raw := end.Data.(float64)
		if math.IsInf(raw, 0) || math.IsNaN(raw) {
			return 0, false
		}
		last := int64(math.Floor(raw))
		if r.Exclusive && raw == float64(last) {
			last--
		}
		return last, true
	default:
		return 0, false
	}
}

func rangeReverseBeginlessIntegerValues(r *object.RRange, limit int) []*object.EmeraldValue {
	count := limit
	if count < 0 {
		count = 10000
	}
	start := r.End
	if r.Exclusive {
		start--
	}
	values := make([]*object.EmeraldValue, 0, count)
	for i := 0; i < count; i++ {
		values = append(values, newInt(start-int64(i)))
	}
	return values
}

func reverseValueSlice(values []*object.EmeraldValue, limit int) []*object.EmeraldValue {
	reversed := make([]*object.EmeraldValue, 0, len(values))
	for i := len(values) - 1; i >= 0; i-- {
		reversed = append(reversed, values[i])
		if limit >= 0 && len(reversed) >= limit {
			break
		}
	}
	return reversed
}

func rangeBsearch(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 0 {
		return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 0)", len(args)))
	}
	if receiver.Type != object.ValueRange {
		return receiver
	}
	r := receiver.Data.(*object.RRange)
	if errVal := rangeBsearchValidateNumeric(r); errVal != nil {
		return errVal
	}
	if BlockGivenCheck == nil || !BlockGivenCheck() || CallBlock == nil {
		return newSizedValueGeneratorEnumerator(R.NilVal, func() ([]*object.EmeraldValue, *object.EmeraldValue) {
			return []*object.EmeraldValue{}, nil
		})
	}
	if rangeBsearchUsesFloat(r) {
		return rangeBsearchFloat(r)
	}
	return rangeBsearchInteger(r)
}

func rangeBsearchValidateNumeric(r *object.RRange) *object.EmeraldValue {
	if !r.StartMissing {
		start, ok := r.StartValue.(*object.EmeraldValue)
		if !ok || start == nil || (start.Type != object.ValueInteger && start.Type != object.ValueFloat) {
			return typeError("can't do binary search for " + valueTypeName(start))
		}
	}
	if !r.EndMissing {
		end, ok := r.EndValue.(*object.EmeraldValue)
		if !ok || end == nil || (end.Type != object.ValueInteger && end.Type != object.ValueFloat) {
			return typeError("can't do binary search for " + valueTypeName(end))
		}
	}
	return nil
}

func rangeBsearchUsesFloat(r *object.RRange) bool {
	if !r.StartMissing {
		if start, ok := r.StartValue.(*object.EmeraldValue); ok && start != nil && start.Type == object.ValueFloat {
			return true
		}
	}
	if !r.EndMissing {
		if end, ok := r.EndValue.(*object.EmeraldValue); ok && end != nil && end.Type == object.ValueFloat {
			return true
		}
	}
	return false
}

type bsearchBlockResult struct {
	mode string
	cmp  int
}

func rangeBsearchInteger(r *object.RRange) *object.EmeraldValue {
	low, high, boundedLow, boundedHigh := r.Start, r.End, !r.StartMissing, !r.EndMissing
	if boundedHigh && r.Exclusive {
		high--
	}
	if boundedLow && boundedHigh && low > high {
		return R.NilVal
	}
	if !boundedLow {
		low = high - 1
	}
	if !boundedHigh {
		high = low + 1
	}
	first := low
	if boundedLow {
		first = r.Start
	}
	probe := rangeBsearchCallBlock(newInt(first))
	if probe == nil || probe.Type == object.ValueException {
		return probe
	}
	state, errVal := rangeBsearchClassify(probe)
	if errVal != nil {
		return errVal
	}
	mode := state.mode
	if boundedLow && !boundedHigh {
		if (mode == "boolean" && rangeBsearchAccepts(state)) || (mode == "numeric" && state.cmp == 0) {
			return newInt(r.Start)
		}
		if mode == "numeric" && state.cmp < 0 {
			return R.NilVal
		}
		step := int64(1)
		foundUpper := false
		for i := 0; i < 62; i++ {
			if r.Start > math.MaxInt64-step {
				return R.NilVal
			}
			high = r.Start + step
			nextState, errVal := rangeBsearchProbeInt(high, mode)
			if errVal != nil {
				return errVal
			}
			if rangeBsearchAccepts(nextState) {
				low = r.Start
				foundUpper = true
				break
			}
			if step > math.MaxInt64/2 {
				return R.NilVal
			}
			step *= 2
		}
		if !foundUpper {
			return R.NilVal
		}
	}
	if !boundedLow && boundedHigh {
		endState, errVal := rangeBsearchProbeInt(high, mode)
		if errVal != nil {
			return errVal
		}
		if !rangeBsearchAccepts(endState) {
			return R.NilVal
		}
		step := int64(1)
		low = high - step
		for i := 0; i < 62; i++ {
			nextState, errVal := rangeBsearchProbeInt(low, mode)
			if errVal != nil {
				return errVal
			}
			if !rangeBsearchAccepts(nextState) {
				low++
				break
			}
			if step > math.MaxInt64/2 {
				low = math.MinInt64 / 2
				break
			}
			step *= 2
			low = high - step
		}
	}
	result := (*object.EmeraldValue)(nil)
	for low <= high {
		mid := low + (high-low)/2
		state, errVal := rangeBsearchProbeInt(mid, mode)
		if errVal != nil {
			return errVal
		}
		if mode == "boolean" {
			if state.cmp <= 0 {
				result = newInt(mid)
				high = mid - 1
			} else {
				low = mid + 1
			}
			continue
		}
		if state.cmp == 0 {
			return newInt(mid)
		}
		if state.cmp > 0 {
			low = mid + 1
		} else {
			high = mid - 1
		}
	}
	if result != nil {
		return result
	}
	return R.NilVal
}

func rangeBsearchProbeInt(value int64, mode string) (bsearchBlockResult, *object.EmeraldValue) {
	result := rangeBsearchCallBlock(newInt(value))
	if result == nil || result.Type == object.ValueException {
		return bsearchBlockResult{}, result
	}
	state, errVal := rangeBsearchClassify(result)
	if errVal != nil {
		return bsearchBlockResult{}, errVal
	}
	if state.mode != mode {
		return bsearchBlockResult{}, rangeBsearchWrongType(result)
	}
	return state, nil
}

func rangeBsearchFloat(r *object.RRange) *object.EmeraldValue {
	low := math.Inf(-1)
	high := math.Inf(1)
	if !r.StartMissing {
		low = rangeBsearchEndpointFloat(r.StartValue.(*object.EmeraldValue))
	}
	if !r.EndMissing {
		high = rangeBsearchEndpointFloat(r.EndValue.(*object.EmeraldValue))
	}
	lowKey := rangeBsearchFloatKey(low)
	highKey := rangeBsearchFloatKey(high)
	if !r.EndMissing && r.Exclusive {
		if highKey == 0 {
			return R.NilVal
		}
		highKey--
	}
	if lowKey > highKey || (r.EndMissing && r.Exclusive && math.IsInf(low, 1)) {
		return R.NilVal
	}
	mode := ""
	var resultKey uint64
	found := false
	for lowKey <= highKey {
		midKey := lowKey + (highKey-lowKey)/2
		mid := rangeBsearchFloatFromKey(midKey)
		state, errVal := rangeBsearchProbeFloat(mid, mode)
		if errVal != nil {
			return errVal
		}
		if mode == "" {
			mode = state.mode
		}
		if mode == "boolean" {
			if state.cmp <= 0 {
				resultKey = midKey
				found = true
				if midKey == 0 {
					break
				}
				highKey = midKey - 1
			} else {
				if midKey == math.MaxUint64 {
					break
				}
				lowKey = midKey + 1
			}
			continue
		}
		if state.cmp == 0 {
			return newFloat(mid)
		} else if state.cmp > 0 {
			if midKey == math.MaxUint64 {
				break
			}
			lowKey = midKey + 1
		} else {
			if midKey == 0 {
				break
			}
			highKey = midKey - 1
		}
	}
	if found {
		return newFloat(rangeBsearchFloatFromKey(resultKey))
	}
	return R.NilVal
}

func rangeBsearchFloatKey(value float64) uint64 {
	bits := math.Float64bits(value)
	if bits&(uint64(1)<<63) != 0 {
		return ^bits
	}
	return bits | (uint64(1) << 63)
}

func rangeBsearchFloatFromKey(key uint64) float64 {
	var bits uint64
	if key&(uint64(1)<<63) != 0 {
		bits = key &^ (uint64(1) << 63)
	} else {
		bits = ^key
	}
	return math.Float64frombits(bits)
}

func rangeBsearchEndpointFloat(value *object.EmeraldValue) float64 {
	if value.Type == object.ValueInteger {
		return float64(value.Data.(int64))
	}
	return value.Data.(float64)
}

func rangeBsearchProbeFloat(value float64, mode string) (bsearchBlockResult, *object.EmeraldValue) {
	result := rangeBsearchCallBlock(newFloat(value))
	if result == nil || result.Type == object.ValueException {
		return bsearchBlockResult{}, result
	}
	state, errVal := rangeBsearchClassify(result)
	if errVal != nil {
		return bsearchBlockResult{}, errVal
	}
	if mode != "" && state.mode != mode {
		return bsearchBlockResult{}, rangeBsearchWrongType(result)
	}
	return state, nil
}

func rangeBsearchCallBlock(value *object.EmeraldValue) *object.EmeraldValue {
	LastBlockResult = nil
	result := CallBlock(value)
	if LastBlockResult != nil {
		breakValue := LastBlockResult
		LastBlockResult = nil
		if breakValue == nil {
			return R.NilVal
		}
		return breakValue
	}
	return result
}

func rangeBsearchClassify(result *object.EmeraldValue) (bsearchBlockResult, *object.EmeraldValue) {
	if result == nil || result.Type == object.ValueNil {
		return bsearchBlockResult{mode: "boolean", cmp: 1}, nil
	}
	switch result.Type {
	case object.ValueBool:
		if result.Data.(bool) {
			return bsearchBlockResult{mode: "boolean", cmp: 0}, nil
		}
		return bsearchBlockResult{mode: "boolean", cmp: 1}, nil
	case object.ValueInteger:
		n := result.Data.(int64)
		return bsearchBlockResult{mode: "numeric", cmp: compareBsearchNumber(float64(n))}, nil
	case object.ValueFloat:
		return bsearchBlockResult{mode: "numeric", cmp: compareBsearchNumber(result.Data.(float64))}, nil
	default:
		return bsearchBlockResult{}, rangeBsearchWrongType(result)
	}
}

func compareBsearchNumber(n float64) int {
	if n > 0 {
		return 1
	}
	if n < 0 {
		return -1
	}
	return 0
}

func rangeBsearchAccepts(state bsearchBlockResult) bool {
	return state.cmp <= 0
}

func rangeBsearchWrongType(value *object.EmeraldValue) *object.EmeraldValue {
	return typeError(fmt.Sprintf("wrong argument type %s (must be numeric, true, false or nil)", valueTypeName(value)))
}

func rangeLazy(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) > 0 {
		return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 0)", len(args)))
	}
	if receiver.Type != object.ValueRange {
		return newLazyEnumerator(R.NilVal, func(limit int) ([]*object.EmeraldValue, *object.EmeraldValue) {
			return []*object.EmeraldValue{}, nil
		})
	}
	r := receiver.Data.(*object.RRange)
	return newLazyEnumerator(rangeSize(receiver), func(limit int) ([]*object.EmeraldValue, *object.EmeraldValue) {
		if limit < 0 {
			limit = 10000
		}
		values := make([]*object.EmeraldValue, 0, limit)
		infinite := false
		if endValue, ok := r.EndValue.(*object.EmeraldValue); ok && endValue != nil && endValue.Type == object.ValueFloat {
			infinite = math.IsInf(endValue.Data.(float64), 1)
		}
		for current := r.Start; len(values) < limit; current++ {
			if !infinite {
				if r.Exclusive {
					if current >= r.End {
						break
					}
				} else if current > r.End {
					break
				}
			}
			values = append(values, &object.EmeraldValue{
				Type:  object.ValueInteger,
				Data:  current,
				Class: R.Classes["Integer"],
			})
		}
		return values, nil
	})
}

func rangeToA(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver.Type != object.ValueRange {
		return receiver
	}
	r := receiver.Data.(*object.RRange)
	if r.StartMissing {
		return newRuntimeException(R.Classes["TypeError"], "can't convert beginless range to an Array")
	}
	if r.EndMissing {
		return newRuntimeException(R.Classes["RangeError"], "can't convert endless range to an Array")
	}

	startVal, okStart := r.StartValue.(*object.EmeraldValue)
	endVal, okEnd := r.EndValue.(*object.EmeraldValue)
	if !okStart || !okEnd || startVal == nil || endVal == nil {
		return newRuntimeException(R.Classes["TypeError"], "can't convert object to Integer")
	}
	if startVal.Type == object.ValueFloat || endVal.Type == object.ValueFloat {
		return newRuntimeException(R.Classes["TypeError"], "can't convert Float to Integer")
	}
	if (startVal.Type == object.ValueString || startVal.Type == object.ValueSymbol) &&
		(endVal.Type == object.ValueString || endVal.Type == object.ValueSymbol) {
		arr := make([]*object.EmeraldValue, 0)
		current := startVal
		for {
			cmp, ok := rangeCompareValues(current, endVal)
			if !ok || cmp > 0 || (r.Exclusive && cmp == 0) {
				break
			}
			arr = append(arr, current)
			if equalValuesForRange(current, endVal) {
				break
			}
			next := rangeSuccessorValue(current, endVal)
			if next == nil || next == current {
				break
			}
			nextCmp, ok := rangeCompareValues(next, current)
			if !ok || nextCmp <= 0 {
				break
			}
			current = next
		}
		return &object.EmeraldValue{
			Type:  object.ValueArray,
			Data:  arr,
			Class: R.Classes["Array"],
		}
	}

	if CallMethod != nil && startVal.Type != object.ValueInteger {
		arr := make([]*object.EmeraldValue, 0)
		current := startVal
		for {
			cmp, ok := rangeCompareValues(current, endVal)
			if !ok {
				return typeError("can't convert " + valueTypeName(startVal) + " to Integer")
			}
			if cmp > 0 || (r.Exclusive && cmp == 0) {
				break
			}
			arr = append(arr, current)
			if current == endVal || current != startVal && cmp == 0 {
				break
			}
			next, errVal := rangeSuccOrTypeError(current)
			if errVal != nil {
				return errVal
			}
			current = next
		}
		return &object.EmeraldValue{
			Type:  object.ValueArray,
			Data:  arr,
			Class: R.Classes["Array"],
		}
	}

	if startVal.Type != object.ValueInteger || endVal.Type != object.ValueInteger {
		if startVal.Class != nil {
			return newRuntimeException(R.Classes["TypeError"], "can't convert "+startVal.Class.Name+" to Integer")
		}
		return newRuntimeException(R.Classes["TypeError"], "can't convert object to Integer")
	}

	endInt := r.End
	if r.Exclusive {
		endInt--
	}
	arr := make([]*object.EmeraldValue, 0)
	for i := r.Start; i <= endInt; i++ {
		arr = append(arr, &object.EmeraldValue{
			Type:  object.ValueInteger,
			Data:  i,
			Class: R.Classes["Integer"],
		})
	}
	return &object.EmeraldValue{
		Type:  object.ValueArray,
		Data:  arr,
		Class: R.Classes["Array"],
	}
}

