func setJoin(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) > 1 {
		return NewArgumentError("wrong number of arguments")
	}
	separator := ""
	if len(args) == 1 && args[0] != nil && args[0].Type != object.ValueNil {
		if args[0].Type != object.ValueString {
			return typeError("no implicit conversion into String")
		}
		separator = args[0].Data.(string)
	}
	parts := make([]string, 0, len(setValues(receiver)))
	for _, value := range setValues(receiver) {
		converted := CallMethod(value, "to_s")
		if converted == nil || converted.Type != object.ValueString {
			return typeError("can't convert into String")
		}
		parts = append(parts, converted.Data.(string))
	}
	return rubyString(strings.Join(parts, separator))
}

func setComparison(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 1 || !isSetValue(args[0]) {
		return R.NilVal
	}
	left, right := setValues(receiver), setValues(args[0])
	leftInRight := setValuesContainedIn(receiver, left, right)
	rightInLeft := setValuesContainedIn(receiver, right, left)
	switch {
	case leftInRight && rightInLeft:
		return newInt(0)
	case leftInRight:
		return newInt(-1)
	case rightInLeft:
		return newInt(1)
	default:
		return R.NilVal
	}
}

func setIntersect(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 1 {
		return NewArgumentError("wrong number of arguments")
	}
	others, ok := setComparableValues(args[0])
	if !ok {
		return NewArgumentError("value must be a set")
	}
	for _, stored := range setValues(receiver) {
		for _, candidate := range others {
			if setElementsEqual(receiver, stored, candidate) {
				return R.TrueVal
			}
		}
	}
	return R.FalseVal
}

func setDisjoint(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	result := setIntersect(receiver, args...)
	if result == R.TrueVal {
		return R.FalseVal
	}
	if result == R.FalseVal {
		return R.TrueVal
	}
	return result
}

