func arrayInclude(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) < 1 {
		return R.FalseVal
	}
	arr := receiver.Data.([]*object.EmeraldValue)
	target := args[0]
	for _, elem := range arr {
		if elem != nil && target != nil && elem.Type == object.ValueSymbol && target.Type == object.ValueSymbol {
			if symbolValuesEqual(elem, target) {
				return R.TrueVal
			}
			continue
		}
		if valuesEqualWithRubyFallback(elem, target) {
			return R.TrueVal
		}
	}
	return R.FalseVal
}

func arrayAssoc(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) < 1 {
		return R.NilVal
	}
	for _, elem := range receiver.Data.([]*object.EmeraldValue) {
		nested, ok := valueToArray(elem)
		if !ok {
			continue
		}
		if len(nested) > 0 && valuesEqualWithRubyFallback(nested[0], args[0]) {
			if elem.Type == object.ValueArray {
				return elem
			}
			return &object.EmeraldValue{Type: object.ValueArray, Data: nested, Class: R.Classes["Array"]}
		}
	}
	return R.NilVal
}

func arrayRassoc(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) < 1 {
		return R.NilVal
	}
	for _, elem := range receiver.Data.([]*object.EmeraldValue) {
		nested, ok := valueToArray(elem)
		if !ok {
			continue
		}
		if len(nested) > 1 && valuesEqualWithRubyFallback(nested[1], args[0]) {
			if elem.Type == object.ValueArray {
				return elem
			}
			return &object.EmeraldValue{Type: object.ValueArray, Data: nested, Class: R.Classes["Array"]}
		}
	}
	return R.NilVal
}

func arrayHash(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	h := fnv.New64a()
	key := "array-recursive"
	if !valueHashHasCycle(receiver, make(map[*object.EmeraldValue]bool)) {
		key = valueHashKey(receiver, make(map[*object.EmeraldValue]bool))
	}
	_, _ = h.Write([]byte(key))
	return &object.EmeraldValue{Type: object.ValueInteger, Data: int64(h.Sum64()), Class: R.Classes["Integer"]}
}

func hashHash(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	h := fnv.New64a()
	key := "hash-recursive"
	if !valueHashHasCycle(receiver, make(map[*object.EmeraldValue]bool)) {
		key = valueHashKey(receiver, make(map[*object.EmeraldValue]bool))
	}
	_, _ = h.Write([]byte(key))
	return &object.EmeraldValue{Type: object.ValueInteger, Data: int64(h.Sum64()), Class: R.Classes["Integer"]}
}

func valueHashHasCycle(value *object.EmeraldValue, visiting map[*object.EmeraldValue]bool) bool {
	if value == nil || (value.Type != object.ValueArray && value.Type != object.ValueHash) {
		return false
	}
	if visiting[value] {
		return true
	}
	visiting[value] = true
	defer delete(visiting, value)
	if value.Type == object.ValueArray {
		for _, elem := range value.Data.([]*object.EmeraldValue) {
			if valueHashHasCycle(elem, visiting) {
				return true
			}
		}
		return false
	}
	for key, elem := range valueToHashMap(value) {
		if valueHashHasCycle(key, visiting) || valueHashHasCycle(elem, visiting) {
			return true
		}
	}
	return false
}

func valueHashKey(value *object.EmeraldValue, visiting map[*object.EmeraldValue]bool) string {
	if value == nil {
		return "nil"
	}
	switch value.Type {
	case object.ValueArray:
		if visiting[value] {
			return "[...]"
		}
		visiting[value] = true
		parts := []string{"array"}
		for _, elem := range value.Data.([]*object.EmeraldValue) {
			parts = append(parts, valueHashKey(elem, visiting))
		}
		delete(visiting, value)
		if len(parts) == 2 && (parts[1] == "[...]" || parts[1] == "array|[...]") {
			return "array|[...]"
		}
		return strings.Join(parts, "|")
	case object.ValueHash:
		if visiting[value] {
			return "{...}"
		}
		visiting[value] = true
		parts := []string{"hash"}
		for key, val := range valueToHashMap(value) {
			parts = append(parts, valueHashKey(key, visiting)+":"+valueHashKey(val, visiting))
		}
		sort.Strings(parts[1:])
		delete(visiting, value)
		return strings.Join(parts, "|")
	default:
		if hash, ok := rubyHashInteger(value); ok {
			return fmt.Sprintf("hash:%d", hash)
		}
		return fmt.Sprintf("%d:%s", value.Type, value.Inspect())
	}
}

func rubyHashInteger(value *object.EmeraldValue) (int64, bool) {
	if CallMethod == nil || value == nil || !receiverHasCallableMethod(value, "hash") {
		return 0, false
	}
	hash := CallMethod(value, "hash")
	if hash == nil || hash.Type == object.ValueException {
		return 0, false
	}
	if result, ok := valueToInteger(hash); ok {
		return result, true
	}
	if !receiverHasCallableMethod(hash, "to_int") {
		return 0, false
	}
	coerced := CallMethod(hash, "to_int")
	if coerced == nil || coerced.Type == object.ValueException {
		return 0, false
	}
	return valueToInteger(coerced)
}

func hashDelete(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver != nil && receiver.Frozen {
		return frozenError("can't modify frozen Hash")
	}
	if len(args) < 1 {
		return R.NilVal
	}
	deleteKey := args[0]
	if receiver == envObject {
		key, errVal := envCoerceKey(args[0])
		if errVal != nil {
			return errVal
		}
		deleteKey = rubyString(key)
	}
	data := hashData(receiver)
	if data == nil {
		return R.NilVal
	}
	if k, v, ok := hashFindKeyValue(data.Pairs, deleteKey, data.CompareByIdentity); ok {
		delete(data.Pairs, k)
		hashRemoveOrderedKey(receiver, k)
		return v
	}
	if BlockGivenCheck != nil && BlockGivenCheck() && CallBlock != nil {
		return CallBlock(deleteKey)
	}
	return R.NilVal
}

func hashClear(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver != nil && receiver.Frozen {
		return frozenError("can't modify frozen Hash")
	}
	if h := hashData(receiver); h != nil {
		h.Pairs = make(map[*object.EmeraldValue]*object.EmeraldValue)
		h.Keys = []*object.EmeraldValue{}
		return receiver
	}
	receiver.Data = make(map[*object.EmeraldValue]*object.EmeraldValue)
	return receiver
}

func hashCompact(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	source := hashData(receiver)
	result := &object.RHash{
		Pairs: make(map[*object.EmeraldValue]*object.EmeraldValue),
		Keys:  []*object.EmeraldValue{},
	}
	if source != nil {
		result.Default = source.Default
		result.DefaultProc = source.DefaultProc
		result.CompareByIdentity = source.CompareByIdentity
	}
	keys, pairs := hashOrderedKeysFromValue(receiver)
	for _, key := range keys {
		value, ok := pairs[key]
		if !ok || value == nil || value.Type == object.ValueNil {
			continue
		}
		result.Pairs[key] = value
		result.Keys = append(result.Keys, key)
	}
	return &object.EmeraldValue{Type: object.ValueHash, Data: result, Class: R.Classes["Hash"]}
}

func hashCompactBang(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver != nil && receiver.Frozen {
		return frozenError("can't modify frozen Hash")
	}
	data := hashData(receiver)
	if data == nil {
		return R.NilVal
	}
	keys, pairs := hashOrderedKeysFromValue(receiver)
	nextPairs := make(map[*object.EmeraldValue]*object.EmeraldValue)
	nextKeys := make([]*object.EmeraldValue, 0, len(keys))
	changed := false
	for _, key := range keys {
		value, ok := pairs[key]
		if !ok {
			continue
		}
		if value == nil || value.Type == object.ValueNil {
			changed = true
			continue
		}
		nextPairs[key] = value
		nextKeys = append(nextKeys, key)
	}
	if !changed {
		return R.NilVal
	}
	data.Pairs = nextPairs
	data.Keys = nextKeys
	return receiver
}

func hashHasValue(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) < 1 {
		return R.FalseVal
	}
	target := args[0]
	if receiver == envObject {
		text, ok, viaToStr, errVal := evalCoerceToString(target)
		if errVal != nil {
			return errVal
		}
		if !ok {
			if viaToStr {
				return conversionTypeErrorToStringForMode(target, true)
			}
			return R.NilVal
		}
		target = rubyString(text)
	}
	hash := valueToHashMap(receiver)
	for _, val := range hash {
		if valuesEqualWithRubyFallback(val, target) {
			return R.TrueVal
		}
	}
	return R.FalseVal
}

func hashKey(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) < 1 {
		return R.NilVal
	}
	target := args[0]
	if receiver == envObject {
		text, errVal := envCoerceKey(args[0])
		if errVal != nil {
			return errVal
		}
		target = rubyString(text)
	}
	keys, hash := hashOrderedKeysFromValue(receiver)
	for _, key := range keys {
		if val, ok := hash[key]; ok && valuesEqualWithRubyFallback(val, target) {
			return key
		}
	}
	for key, val := range hash {
		if valuesEqualWithRubyFallback(val, target) {
			return key
		}
	}
	return R.NilVal
}

func stringLjust(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	s := stringRawValue(receiver)
	width, pad, encoding, errVal := stringJustifyArgs(receiver, args)
	if errVal != nil {
		return errVal
	}
	if utf8RuneCount(s) >= width {
		return stringWithEncoding(s, stringEncodingName(receiver))
	}
	result := s + repeatPadToWidth(pad, width-utf8RuneCount(s))
	return stringWithEncoding(result, encoding)
}

func stringRjust(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	s := stringRawValue(receiver)
	width, pad, encoding, errVal := stringJustifyArgs(receiver, args)
	if errVal != nil {
		return errVal
	}
	if utf8RuneCount(s) >= width {
		return stringWithEncoding(s, stringEncodingName(receiver))
	}
	result := repeatPadToWidth(pad, width-utf8RuneCount(s)) + s
	return stringWithEncoding(result, encoding)
}

func stringCenter(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	s := stringRawValue(receiver)
	width, pad, encoding, errVal := stringJustifyArgs(receiver, args)
	if errVal != nil {
		return errVal
	}
	currentWidth := utf8RuneCount(s)
	if currentWidth >= width {
		return stringWithEncoding(s, stringEncodingName(receiver))
	}
	total := width - currentWidth
	left := total / 2
	right := total - left
	result := repeatPadToWidth(pad, left) + s + repeatPadToWidth(pad, right)
	return stringWithEncoding(result, encoding)
}

func stringJustifyArgs(receiver *object.EmeraldValue, args []*object.EmeraldValue) (int, string, string, *object.EmeraldValue) {
	if len(args) == 0 {
		return 0, "", "", NewArgumentError("wrong number of arguments (given 0, expected 1..2)")
	}
	if len(args) > 2 {
		return 0, "", "", NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 1..2)", len(args)))
	}
	width, ok := valueToInteger(args[0])
	if !ok {
		return 0, "", "", conversionTypeErrorToInteger(args[0])
	}
	pad := " "
	resultEncoding := stringEncodingName(receiver)
	if len(args) > 1 {
		convertedPad, converted, viaToStr, coerceErr := evalCoerceToString(args[1])
		if coerceErr != nil {
			return 0, "", "", coerceErr
		}
		if !converted {
			return 0, "", "", conversionTypeErrorToStringForMode(args[1], viaToStr)
		}
		pad = convertedPad
		if pad == "" {
			return 0, "", "", NewArgumentError("zero width padding")
		}
		padEncoding := stringEncodingName(args[1])
		receiverHasNonASCII := stringHasNonASCIIByte(stringRawValue(receiver))
		padHasNonASCII := stringHasNonASCIIByte(pad)
		if receiverHasNonASCII && padHasNonASCII && !strings.EqualFold(resultEncoding, padEncoding) {
			return 0, "", "", newRuntimeException(R.Classes["Encoding::CompatibilityError"], "incompatible encoding")
		}
		if padHasNonASCII {
			resultEncoding = padEncoding
		}
	}
	return int(width), pad, resultEncoding, nil
}

func repeatPadToWidth(pad string, width int) string {
	if width <= 0 || pad == "" {
		return ""
	}
	padRunes := []rune(pad)
	result := make([]rune, 0, width)
	for len(result) < width {
		remaining := width - len(result)
		if remaining >= len(padRunes) {
			result = append(result, padRunes...)
		} else {
			result = append(result, padRunes[:remaining]...)
		}
	}
	return string(result)
}

func utf8RuneCount(value string) int {
	return len([]rune(value))
}

func stringWithEncoding(value string, encoding string) *object.EmeraldValue {
	result := rubyString(value)
	if stringEncodings != nil && encoding != "" {
		stringEncodings[result] = encoding
	}
	return result
}

func stringRawValue(value *object.EmeraldValue) string {
	if value == nil {
		return ""
	}
	if s, ok := value.Data.(string); ok {
		return s
	}
	return ""
}

// ========== New Array Methods ==========

func arrayIndexSet(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) < 2 {
		return R.NilVal
	}
	if receiver != nil && receiver.Frozen {
		return frozenError("can't modify frozen array")
	}
	arr := receiver.Data.([]*object.EmeraldValue)
	if args[0].Type == object.ValueRange {
		replacement := arrayReplacementValues(args[1])
		rangeObj, ok := args[0].Data.(*object.RRange)
		if !ok {
			return R.NilVal
		}
		start, count, ok, err := arrayRangeAssignmentBounds(rangeObj, len(arr))
		if !ok {
			return err
		}
		if start > len(arr) {
			for len(arr) < start {
				arr = append(arr, R.NilVal)
			}
		}
		if start+count > len(arr) {
			count = len(arr) - start
		}
		updated := append([]*object.EmeraldValue{}, arr[:start]...)
		updated = append(updated, replacement...)
		updated = append(updated, arr[start+count:]...)
		receiver.Data = updated
		return args[1]
	}
	if len(args) >= 3 {
		idx, err := arrayIndexIntArg(args[0])
		if err != nil {
			return err
		}
		count64, ok := valueToInteger(args[1])
		if !ok {
			msg := "no implicit conversion into Integer"
			if args[1] != nil && args[1].Class != nil {
				msg = "no implicit conversion of " + args[1].Class.Name + " into Integer"
				if args[1].Type == object.ValueNil {
					msg = "no implicit conversion of nil into Integer"
				}
			}
			return typeError(msg)
		}
		if idx < 0 {
			idx += len(arr)
		}
		if idx < 0 {
			return NewIndexErrorWithBounds(idx, len(arr))
		}
		if count64 < 0 {
			return NewIndexErrorWithBounds(idx, len(arr))
		}
		if idx > len(arr) {
			for len(arr) < idx {
				arr = append(arr, R.NilVal)
			}
		}
		count := int(count64)
		if idx+count > len(arr) {
			count = len(arr) - idx
		}
		replacement := arrayReplacementValues(args[2])
		updated := append([]*object.EmeraldValue{}, arr[:idx]...)
		updated = append(updated, replacement...)
		updated = append(updated, arr[idx+count:]...)
		receiver.Data = updated
		return args[2]
	}
	idx, err := arrayIndexIntArg(args[0])
	if err != nil {
		return err
	}
	if idx < 0 {
		idx += len(arr)
	}
	if idx < 0 {
		return NewIndexErrorWithBounds(idx, len(arr))
	}
	for len(arr) <= idx {
		arr = append(arr, R.NilVal)
	}
	arr[idx] = args[1]
	receiver.Data = arr
	return args[1]
}

func arrayReplacementValues(value *object.EmeraldValue) []*object.EmeraldValue {
	if elems, ok := valueToArray(value); ok {
		return elems
	}
	return []*object.EmeraldValue{value}
}

func arrayRangeAssignmentBounds(r *object.RRange, length int) (int, int, bool, *object.EmeraldValue) {
	startValue, ok := valueToIntegerOrRangeBound(r.StartValue, r.Start)
	if !ok {
		msg := "no implicit conversion into Integer"
		if value, ok := r.StartValue.(*object.EmeraldValue); ok && value != nil && value.Class != nil {
			msg = "no implicit conversion of " + value.Class.Name + " into Integer"
			if value.Type == object.ValueNil {
				msg = "no implicit conversion of nil into Integer"
			}
		}
		return 0, 0, false, typeError(msg)
	}
	endFallback := r.End
	if r.EndMissing || arrayRangeBoundaryNil(r.EndValue) {
		endFallback = int64(length - 1)
	}
	endValue, ok := valueToIntegerOrRangeBound(r.EndValue, endFallback)
	if !ok {
		msg := "no implicit conversion into Integer"
		if value, ok := r.EndValue.(*object.EmeraldValue); ok && value != nil && value.Class != nil {
			msg = "no implicit conversion of " + value.Class.Name + " into Integer"
			if value.Type == object.ValueNil {
				msg = "no implicit conversion of nil into Integer"
			}
		}
		return 0, 0, false, typeError(msg)
	}
	endIsOpen := r.EndMissing || arrayRangeBoundaryNil(r.EndValue)
	start := int(startValue)
	end := int(endValue)
	if start < 0 {
		start = length + start
	}
	if start < 0 {
		return 0, 0, false, NewRangeError("range out of bounds")
	}
	if end < 0 {
		end = length + end
	}
	if r.Exclusive && !endIsOpen {
		end--
	}
	if start >= length {
		return start, 0, true, nil
	}
	if end >= length {
		end = length - 1
	}
	if end < start || end < 0 {
		return start, 0, true, nil
	}
	return start, end - start + 1, true, nil
}

func valueToIntegerOrRangeBound(raw interface{}, fallback int64) (int64, bool) {
	if value, ok := raw.(*object.EmeraldValue); ok {
		if value == nil || value.Type == object.ValueNil {
			return fallback, true
		}
		return valueToInteger(value)
	}
	if raw == nil {
		return fallback, true
	}
	return fallback, true
}

func arrayIndexIntArg(arg *object.EmeraldValue) (int, *object.EmeraldValue) {
	idx, ok := valueToInteger(arg)
	if !ok {
		msg := "no implicit conversion into Integer"
		if arg != nil && arg.Class != nil {
			msg = "no implicit conversion of " + arg.Class.Name + " into Integer"
			if arg.Type == object.ValueNil {
				msg = "no implicit conversion of nil into Integer"
			}
		}
		return 0, typeError(msg)
	}
	if idx >= 1<<62 || idx < -(1<<62) {
		return 0, NewRangeError("integer out of range")
	}
	return int(idx), nil
}

func NewIndexErrorWithBounds(index int, length int) *object.EmeraldValue {
	msg := fmt.Sprintf("index %d outside of array bounds: -%d...%d", index, length, length)
	if length == 0 {
		msg = fmt.Sprintf("index %d outside of array bounds: 0...0", index)
	}
	return newRuntimeException(R.Classes["IndexError"], msg)
}

func arrayCount(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 0 {
		if BlockGivenCheck != nil && BlockGivenCheck() && CallBlock != nil {
			count := int64(0)
			for i := 0; ; i++ {
				arr := receiver.Data.([]*object.EmeraldValue)
				if i >= len(arr) {
					break
				}
				result := CallBlock(arr[i])
				if result != nil && result.Type == object.ValueException {
					return result
				}
				if isTruthy(result) {
					count++
				}
			}
			return newInt(count)
		}
		arr := receiver.Data.([]*object.EmeraldValue)
		return &object.EmeraldValue{
			Type:  object.ValueInteger,
			Data:  int64(len(arr)),
			Class: R.Classes["Integer"],
		}
	}
	count := 0
	target := args[0]
	for _, elem := range receiver.Data.([]*object.EmeraldValue) {
		if valuesEqualWithRubyFallback(elem, target) {
			count++
		}
	}
	return &object.EmeraldValue{
		Type:  object.ValueInteger,
		Data:  int64(count),
		Class: R.Classes["Integer"],
	}
}

func arrayIndexOf(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) < 1 {
		if CurrentBlockValue == nil || CurrentBlockValue() == nil || CallBlockWithArgs == nil {
			return newArrayIndexEnumerator(receiver, false)
		}
		block := CurrentBlockValue()
		for i := 0; ; i++ {
			arr := receiver.Data.([]*object.EmeraldValue)
			if i >= len(arr) {
				break
			}
			elem := arr[i]
			result := CallBlockWithArgs(block, elem)
			if result != nil && result.Type == object.ValueException {
				return result
			}
			if isTruthy(result) {
				return &object.EmeraldValue{Type: object.ValueInteger, Data: int64(i), Class: R.Classes["Integer"]}
			}
		}
		return R.NilVal
	}
	arr := receiver.Data.([]*object.EmeraldValue)
	target := args[0]
	for i, elem := range arr {
		if valuesEqualWithRubyFallback(elem, target) {
			return &object.EmeraldValue{
				Type:  object.ValueInteger,
				Data:  int64(i),
				Class: R.Classes["Integer"],
			}
		}
	}
	return R.NilVal
}

func arrayRIndexOf(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) < 1 {
		if CurrentBlockValue == nil || CurrentBlockValue() == nil || CallBlock == nil {
			return newArrayIndexEnumerator(receiver, true)
		}
		for i := len(receiver.Data.([]*object.EmeraldValue)) - 1; i >= 0; i-- {
			arr := receiver.Data.([]*object.EmeraldValue)
			if i >= len(arr) {
				continue
			}
			result := CallBlock(arr[i])
			if result != nil && result.Type == object.ValueException {
				return result
			}
			if isTruthy(result) {
				return newInt(int64(i))
			}
		}
		return R.NilVal
	}
	arr := receiver.Data.([]*object.EmeraldValue)
	target := args[0]
	for i := len(arr) - 1; i >= 0; i-- {
		if valuesEqualWithRubyFallback(arr[i], target) {
			return &object.EmeraldValue{
				Type:  object.ValueInteger,
				Data:  int64(i),
				Class: R.Classes["Integer"],
			}
		}
	}
	return R.NilVal
}

func newArrayIndexEnumerator(receiver *object.EmeraldValue, reverse bool) *object.EmeraldValue {
	data := &enumeratorData{sizeValue: R.NilVal}
	data.eachFunc = func() *object.EmeraldValue {
		if reverse {
			return arrayRIndexOf(receiver)
		}
		return arrayIndexOf(receiver)
	}
	return &object.EmeraldValue{Type: object.ValueObject, Data: data, Class: R.Classes["Enumerator"]}
}

func arrayDelete(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) < 1 {
		return R.NilVal
	}
	arr := receiver.Data.([]*object.EmeraldValue)
	target := args[0]
	result := R.NilVal
	newArr := make([]*object.EmeraldValue, 0)
	for _, elem := range arr {
		if valuesEqualWithRubyFallback(elem, target) {
			if result == R.NilVal {
				result = elem
			}
			continue
		}
		newArr = append(newArr, elem)
	}
	if result != R.NilVal && receiver != nil && receiver.Frozen {
		return frozenError("can't modify frozen array")
	}
	receiver.Data = newArr
	if receiver == loadedFeaturesGlobal() {
		syncRequiredFeaturesFromLoadedFeatures()
	}
	if result == R.NilVal && BlockGivenCheck != nil && BlockGivenCheck() && CallBlock != nil {
		return CallBlock()
	}
	return result
}

func arrayDeleteIf(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 0 {
		return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 0)", len(args)))
	}
	if BlockGivenCheck == nil || !BlockGivenCheck() || CallBlock == nil {
		enum := objectToEnum(receiver, rubySymbol("delete_if"))
		if data, ok := enum.Data.(*enumeratorData); ok {
			data.sizeValue = newInt(int64(len(receiver.Data.([]*object.EmeraldValue))))
		}
		return enum
	}
	if receiver != nil && receiver.Frozen {
		return frozenError("can't modify frozen array")
	}
	newArr := make([]*object.EmeraldValue, 0, len(receiver.Data.([]*object.EmeraldValue)))
	for index := 0; ; index++ {
		current := receiver.Data.([]*object.EmeraldValue)
		if index >= len(current) {
			break
		}
		elem := current[index]
		previousException := LastException
		value := CallBlock(elem)
		if value != nil && value.Type == object.ValueException || LastException != nil && LastException != previousException {
			current = receiver.Data.([]*object.EmeraldValue)
			newArr = append(newArr, current[index:]...)
			receiver.Data = newArr
			if LastException != nil && LastException != previousException {
				return LastException
			}
			return value
		}
		if !value.IsTruthy() {
			newArr = append(newArr, elem)
		}
	}
	receiver.Data = newArr
	return receiver
}

func arrayKeepIf(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) > 0 {
		return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 0)", len(args)))
	}
	if BlockGivenCheck == nil || !BlockGivenCheck() || CallBlock == nil {
		return newArrayKeepIfEnumerator(receiver)
	}
	if receiver != nil && receiver.Frozen {
		return frozenError("can't modify frozen array")
	}
	newArr := make([]*object.EmeraldValue, 0, len(receiver.Data.([]*object.EmeraldValue)))
	for index := 0; ; index++ {
		current := receiver.Data.([]*object.EmeraldValue)
		if index >= len(current) {
			break
		}
		elem := current[index]
		if CallBlock(elem).IsTruthy() {
			newArr = append(newArr, elem)
		}
	}
	receiver.Data = newArr
	return receiver
}

func arrayCompact(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	arr := receiver.Data.([]*object.EmeraldValue)
	newArr := make([]*object.EmeraldValue, 0)
	for _, elem := range arr {
		if elem.Type != object.ValueNil {
			newArr = append(newArr, elem)
		}
	}
	return &object.EmeraldValue{
		Type:  object.ValueArray,
		Data:  newArr,
		Class: R.Classes["Array"],
	}
}

func arrayCompactBang(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver != nil && receiver.Frozen {
		return frozenError("can't modify frozen array")
	}
	arr := receiver.Data.([]*object.EmeraldValue)
	newArr := make([]*object.EmeraldValue, 0, len(arr))
	changed := false
	for _, elem := range arr {
		if elem.Type == object.ValueNil {
			changed = true
			continue
		}
		newArr = append(newArr, elem)
	}
	if !changed {
		return R.NilVal
	}
	receiver.Data = newArr
	return receiver
}

func arrayFlatten(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	depth, errVal := arrayFlattenDepth(args)
	if errVal != nil {
		return errVal
	}
	flat, _, errVal := flattenArray(receiver, depth, make(map[*object.EmeraldValue]bool))
	if errVal != nil {
		return errVal
	}
	return &object.EmeraldValue{
		Type:  object.ValueArray,
		Data:  flat,
		Class: R.Classes["Array"],
	}
}

func arrayFlattenBang(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver != nil && receiver.Frozen {
		return frozenError("can't modify frozen array")
	}
	depth, errVal := arrayFlattenDepth(args)
	if errVal != nil {
		return errVal
	}
	flat, changed, errVal := flattenArray(receiver, depth, make(map[*object.EmeraldValue]bool))
	if errVal != nil {
		return errVal
	}
	if !changed {
		return R.NilVal
	}
	receiver.Data = flat
	return receiver
}

func arrayFlattenDepth(args []*object.EmeraldValue) (int64, *object.EmeraldValue) {
	if len(args) == 0 {
		return -1, nil
	}
	if len(args) > 1 {
		return -1, argumentError("wrong number of arguments")
	}
	depth, ok := valueToInteger(args[0])
	if !ok {
		return -1, typeError("no implicit conversion to Integer")
	}
	if depth < 0 {
		return -1, nil
	}
	return depth, nil
}

func flattenArray(arrayValue *object.EmeraldValue, depth int64, stack map[*object.EmeraldValue]bool) ([]*object.EmeraldValue, bool, *object.EmeraldValue) {
	if arrayValue == nil || arrayValue.Type != object.ValueArray {
		return nil, false, typeError("expected Array")
	}
	if stack == nil {
		stack = make(map[*object.EmeraldValue]bool)
	}
	if stack[arrayValue] {
		return nil, false, argumentError("recursive array")
	}
	stack[arrayValue] = true
	defer delete(stack, arrayValue)

	arr := arrayValue.Data.([]*object.EmeraldValue)
	out := make([]*object.EmeraldValue, 0, len(arr))
	changed := false
	for _, elem := range arr {
		if depth == 0 {
			out = append(out, elem)
			continue
		}

		nested, ok, errVal := arrayFlattenElementArray(elem)
		if errVal != nil {
			return nil, false, errVal
		}
		if !ok {
			out = append(out, elem)
			continue
		}

		nextDepth := depth
		if nextDepth > 0 {
			nextDepth--
		}
		nestedFlat, _, errVal := flattenArray(nested, nextDepth, stack)
		if errVal != nil {
			return nil, false, errVal
		}
		out = append(out, nestedFlat...)
		changed = true
	}
	return out, changed, nil
}

func arrayFlattenElementArray(value *object.EmeraldValue) (*object.EmeraldValue, bool, *object.EmeraldValue) {
	if value == nil {
		return nil, false, nil
	}
	if value.TypeName() == "Unknown" && EvaluatingRaiseErrorMatcher() {
		if lastMockToAryReturn != nil {
			if lastMockToAryReturn.Type != object.ValueNil && lastMockToAryReturn.Type != object.ValueArray {
				return nil, false, typeError("can't convert " + value.TypeName() + " to Array")
			}
			return lastMockToAryReturn, lastMockToAryReturn.Type == object.ValueArray, nil
		}
		scratchPadAppend(nil, &object.EmeraldValue{Type: object.ValueSymbol, Data: "to_ary", Class: R.Classes["Symbol"]})
		return nil, false, NewNoMethodError("undefined method `to_ary'")
	}
	if value.Type == object.ValueArray {
		return value, true, nil
	}
	if CallMethod == nil {
		return nil, false, nil
	}

	shouldCall, errVal := arrayFlattenRespondsToAry(value)
	if errVal != nil {
		return nil, false, errVal
	}
	if !shouldCall && receiverHasCallableMethod(value, "to_ary") {
		shouldCall = true
	}
	if !shouldCall && arrayFlattenHasExplicitMethodMissing(value) && !arrayFlattenHasExplicitRespondTo(value) {
		shouldCall = true
	}
	if !shouldCall {
		return nil, false, nil
	}

	converted := CallMethod(value, "to_ary")
	if converted == nil || converted.Type == object.ValueNil {
		return nil, false, nil
	}
	if converted.Type == object.ValueException {
		return nil, false, converted
	}
	if converted.Type != object.ValueArray {
		return nil, false, typeError("can't convert " + value.TypeName() + " to Array")
	}
	return converted, true, nil
}

func arrayFlattenRespondsToAry(value *object.EmeraldValue) (bool, *object.EmeraldValue) {
	methodName := &object.EmeraldValue{Type: object.ValueSymbol, Data: "to_ary", Class: R.Classes["Symbol"]}
	respondTo := CallMethod(value, "respond_to?", methodName, R.TrueVal)
	respondToMissing := false
	if respondTo != nil && respondTo.Type == object.ValueException {
		if !isNoMethodError(respondTo) {
			return false, respondTo
		}
		respondToMissing = true
	} else if isTruthy(respondTo) {
		return true, nil
	}

	if respondToMissing && receiverHasCallableMethod(value, "respond_to_missing?") {
		respondToMissing := CallMethod(value, "respond_to_missing?", methodName, R.TrueVal)
		if respondToMissing != nil && respondToMissing.Type == object.ValueException {
			if !isNoMethodError(respondToMissing) {
				return false, respondToMissing
			}
			return false, nil
		}
		return isTruthy(respondToMissing), nil
	}
	return false, nil
}

func arrayFlattenHasExplicitRespondTo(value *object.EmeraldValue) bool {
	return arrayFlattenHasSingletonMethod(value, "respond_to?")
}

func arrayFlattenHasExplicitMethodMissing(value *object.EmeraldValue) bool {
	return arrayFlattenHasSingletonMethod(value, "method_missing")
}

func arrayFlattenHasSingletonMethod(value *object.EmeraldValue, name string) bool {
	if value == nil || value.Type != object.ValueObject {
		return false
	}
	obj, ok := value.Data.(*object.Object)
	if !ok {
		return false
	}
	if _, ok := obj.SingletonMethods[name]; ok {
		return true
	}
	if obj.SingletonClass != nil {
		if _, ok := obj.SingletonClass.Methods[name]; ok {
			return true
		}
	}
	return false
}

func arrayPack(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 0 || args[0] == nil {
		return typeError("no implicit conversion to String")
	}

	formatObj := args[0]
	if formatObj.Type != object.ValueString {
		if !receiverHasCallableMethod(formatObj, "to_str") {
			return typeError("no implicit conversion to String")
		}
		coerced := CallMethod(formatObj, "to_str")
		if coerced == nil || coerced.Type != object.ValueString {
			return typeError("no implicit conversion to String")
		}
		formatObj = coerced
	}

	format := formatObj.Data.(string)
	values := receiver.Data.([]*object.EmeraldValue)
	var bufferArg *object.EmeraldValue
	if len(args) > 1 && args[1] != nil && args[1].Type == object.ValueHash {
		if value, ok := hashLookup(valueToHashMap(args[1]), rubySymbol("buffer")); ok {
			if value == nil || value.Type != object.ValueString {
				typeName := "nil"
				if value != nil {
					typeName = value.TypeName()
				}
				return typeError("buffer must be String, not " + typeName)
			}
			if value.Frozen {
				return frozenError("can't modify frozen String")
			}
			bufferArg = value
		}
	}
	out := make([]byte, 0, len(values)*4)
	if bufferArg != nil {
		out = append(out, []byte(bufferArg.Data.(string))...)
	}
	valueIndex := 0
	sawBinaryDirective := false
	sawUnicodeDirective := false
	sawASCIIDirective := false
	var packedPointerPayload *string

	isNativeLittleEndian := func() bool {
		var n uint16 = 1
		return *(*byte)(unsafe.Pointer(&n)) == 1
	}

	longSize := int(strconv.IntSize / 8)

	consumeInteger := func(count int64, signed bool, width int, endian binary.ByteOrder) *object.EmeraldValue {
		if count < 0 {
			count = int64(len(values) - valueIndex)
		}
		if count < 0 {
			count = 0
		}
		for i := int64(0); i < count; i++ {
			if valueIndex >= len(values) {
				return argumentError("too few arguments")
			}
			n, ok := valueToInteger(values[valueIndex])
			valueIndex++
			if !ok {
				return typeError("no implicit conversion to Integer")
			}
			var u uint64
			switch width {
			case 1:
				if signed {
					u = uint64(uint8(int8(n)))
				} else {
					u = uint64(uint8(n))
				}
			case 2:
				if signed {
					u = uint64(uint16(int16(n)))
				} else {
					u = uint64(uint16(n))
				}
			case 4:
				if signed {
					u = uint64(uint32(int32(n)))
				} else {
					u = uint64(uint32(n))
				}
			default:
				u = uint64(n)
			}
			buf := make([]byte, width)
			switch width {
			case 1, 2, 4, 8:
				switch endian {
				case binary.LittleEndian:
					switch width {
					case 1:
						buf[0] = byte(u)
					case 2:
						endian.PutUint16(buf, uint16(u))
					case 4:
						endian.PutUint32(buf, uint32(u))
					case 8:
						endian.PutUint64(buf, uint64(u))
					}
				case binary.BigEndian:
					switch width {
					case 1:
						buf[0] = byte(u)
					case 2:
						endian.PutUint16(buf, uint16(u))
					case 4:
						endian.PutUint32(buf, uint32(u))
					case 8:
						endian.PutUint64(buf, uint64(u))
					}
				}
			default:
				for b := 0; b < width; b++ {
					buf[b] = byte(u >> uint(8*b))
				}
			}
			out = append(out, buf...)
		}
		return nil
	}

	packValueToFloat := func(value *object.EmeraldValue) (float64, *object.EmeraldValue) {
		if value == nil || value.Type == object.ValueNil || value.Type == object.ValueBool || value.Type == object.ValueString {
			return 0, typeError("can't convert " + packValueClassName(value) + " into Float")
		}
		switch value.Type {
		case object.ValueFloat:
			return value.Data.(float64), nil
		case object.ValueInteger:
			if integer, ok := NumericBigIntOverride(value); ok {
				converted, _ := new(big.Float).SetInt(integer).Float64()
				return converted, nil
			}
			return float64(value.Data.(int64)), nil
		}
		if CallMethod == nil || !receiverHasCallableMethod(value, "to_f") {
			return 0, typeError("can't convert " + packValueClassName(value) + " into Float")
		}
		converted := CallMethod(value, "to_f")
		if converted != nil && converted.Type == object.ValueException {
			return 0, converted
		}
		if converted == nil || converted.Type == object.ValueNil {
			return 0, typeError("can't convert " + packValueClassName(value) + " into Float")
		}
		if converted.Type == object.ValueFloat {
			return converted.Data.(float64), nil
		}
		if converted.Type == object.ValueInteger {
			return float64(converted.Data.(int64)), nil
		}
		return 0, typeError("can't convert " + packValueClassName(value) + " into Float")
	}

	consumeFloat := func(count int64, width int, endian binary.ByteOrder) *object.EmeraldValue {
		if count < 0 {
			count = int64(len(values) - valueIndex)
		}
		if count < 0 {
			count = 0
		}
		for i := int64(0); i < count; i++ {
			if valueIndex >= len(values) {
				return argumentError("too few arguments")
			}
			n, err := packValueToFloat(values[valueIndex])
			valueIndex++
			if err != nil {
				return err
			}
			buf := make([]byte, width)
			if width == 4 {
				bits := math.Float32bits(float32(n))
				if math.IsNaN(n) {
					bits = 0x7fc00000
				}
				endian.PutUint32(buf, bits)
			} else {
				bits := math.Float64bits(n)
				if math.IsNaN(n) {
					bits = 0x7ff8000000000000
				}
				endian.PutUint64(buf, bits)
			}
			out = append(out, buf...)
		}
		return nil
	}

	coercePackString := func() (string, *object.EmeraldValue) {
		if valueIndex >= len(values) {
			return "", argumentError("too few arguments")
		}
		obj := values[valueIndex]
		valueIndex++
		if obj == nil || obj.Type == object.ValueNil {
			return "", nil
		}
		if obj.Type == object.ValueString {
			return obj.Data.(string), nil
		}
		if !receiverHasCallableMethod(obj, "to_str") {
			return "", typeError("no implicit conversion to String")
		}
		coerced := CallMethod(obj, "to_str")
		if coerced == nil || coerced.Type != object.ValueString {
			return "", typeError("no implicit conversion to String")
		}
		return coerced.Data.(string), nil
	}

	coerceRequiredPackString := func() (string, *object.EmeraldValue) {
		if valueIndex >= len(values) {
			return "", argumentError("too few arguments")
		}
		obj := values[valueIndex]
		valueIndex++
		if obj == nil || obj.Type == object.ValueNil {
			return "", typeError("no implicit conversion to String")
		}
		if obj.Type == object.ValueString {
			return obj.Data.(string), nil
		}
		if !receiverHasCallableMethod(obj, "to_str") || CallMethod == nil {
			return "", typeError("no implicit conversion to String")
		}
		coerced := CallMethod(obj, "to_str")
		if coerced != nil && coerced.Type == object.ValueException {
			return "", coerced
		}
		if coerced == nil || coerced.Type != object.ValueString {
			return "", typeError("no implicit conversion to String")
		}
		return coerced.Data.(string), nil
	}

	coercePrintablePackString := func() (string, *object.EmeraldValue) {
		if valueIndex >= len(values) {
			return "", argumentError("too few arguments")
		}
		obj := values[valueIndex]
		valueIndex++
		if obj == nil || obj.Type == object.ValueNil {
			return "", nil
		}
		if obj.Type == object.ValueString {
			return obj.Data.(string), nil
		}
		if CallMethod != nil {
			converted := CallMethod(obj, "to_s")
			if converted != nil && converted.Type == object.ValueException {
				return "", converted
			}
			if converted != nil && converted.Type == object.ValueString {
				return converted.Data.(string), nil
			}
		}
		return obj.Inspect(), nil
	}

	parseCount := func(pos int) (int64, int) {
		if pos >= len(format) {
			return 1, pos
		}
		if format[pos] == '*' {
			return -1, pos + 1
		}
		if format[pos] < '0' || format[pos] > '9' {
			return 1, pos
		}
		parsed := int64(0)
		j := pos
		for j < len(format) {
			d := format[j]
			if d < '0' || d > '9' {
				break
			}
			parsed = parsed*10 + int64(d-'0')
			j++
		}
		return parsed, j
	}

	validPackDirective := func(directive byte) bool {
		return strings.ContainsRune("CcSsIiLlNnVvQqJjAaZBbhHwUuMmXx@PpDdEeFfGgRr", rune(directive))
	}

	validatePackFormat := func() *object.EmeraldValue {
		for i := 0; i < len(format); i++ {
			directive := format[i]
			if directive == ' ' || directive == '\t' || directive == '\n' || directive == '\v' || directive == '\f' || directive == '\r' {
				continue
			}
			if directive == '#' {
				for i+1 < len(format) && format[i+1] != '\n' {
					i++
				}
				continue
			}
			if !validPackDirective(directive) {
				return argumentError("unknown pack directive '" + string(directive) + "'")
			}
			for i+1 < len(format) {
				switch format[i+1] {
				case '<', '>', '_', '!':
					i++
				default:
					goto validate_mod_done
				}
			}
		validate_mod_done:
			if i+1 < len(format) {
				_, next := parseCount(i + 1)
				i = next - 1
			}
		}
		return nil
	}

	if err := validatePackFormat(); err != nil {
		return err
	}

	for i := 0; i < len(format); i++ {
		directive := format[i]
		if directive == ' ' || directive == '\t' || directive == '\n' || directive == '\v' || directive == '\f' || directive == '\r' {
			continue
		}
		if directive == '#' {
			for i+1 < len(format) && format[i+1] != '\n' {
				i++
			}
			continue
		}

		count := int64(1)
		var nativeOrder = isNativeLittleEndian()
		byteOrder := binary.ByteOrder(binary.LittleEndian)
		if !nativeOrder {
			byteOrder = binary.BigEndian
		}
		// parse modifiers like < > _ !
		modifier := byte(0)
		nativeModifier := byte(0)
		for i+1 < len(format) {
			ch := format[i+1]
			switch ch {
			case '<':
				byteOrder = binary.LittleEndian
				modifier = ch
				i++
			case '>':
				byteOrder = binary.BigEndian
				modifier = ch
				i++
			case '_', '!':
				nativeModifier = ch
				i++
			default:
				goto mod_done
			}
		}
	mod_done:
		if i+1 < len(format) {
			c, next := parseCount(i + 1)
			count = c
			i = next - 1
		}

		var err *object.EmeraldValue
		if directive == 'U' {
			sawUnicodeDirective = true
		} else if directive == 'm' || directive == 'M' || directive == 'u' {
			sawASCIIDirective = true
		} else {
			sawBinaryDirective = true
		}
		switch directive {
		case 'C':
			if nativeModifier != 0 || modifier != 0 {
				return argumentError("unknown pack directive '" + string(directive) + "'")
			}
			err = consumeInteger(count, false, 1, byteOrder)
		case 'c':
			if nativeModifier != 0 || modifier != 0 {
				return argumentError("unknown pack directive '" + string(directive) + "'")
			}
			err = consumeInteger(count, true, 1, byteOrder)
		case 'S':
			if modifier != 0 && modifier != '<' && modifier != '>' {
				return argumentError("unknown pack directive '" + string(directive) + "'")
			}
			err = consumeInteger(count, false, 2, byteOrder)
		case 's':
			if modifier != 0 && modifier != '<' && modifier != '>' {
				return argumentError("unknown pack directive '" + string(directive) + "'")
			}
			err = consumeInteger(count, true, 2, byteOrder)
		case 'I':
			if modifier == 0 && nativeModifier == 0 {
				byteOrder = func() binary.ByteOrder {
					if nativeOrder {
						return binary.LittleEndian
					}
					return binary.BigEndian
				}()
			}
			width := 4
			err = consumeInteger(count, false, width, byteOrder)
		case 'i':
			if modifier == 0 && nativeModifier == 0 {
				byteOrder = func() binary.ByteOrder {
					if nativeOrder {
						return binary.LittleEndian
					}
					return binary.BigEndian
				}()
			}
			width := 4
			err = consumeInteger(count, true, width, byteOrder)
		case 'L':
			width := 4
			if nativeModifier != 0 {
				width = longSize
			}
			if nativeModifier == 0 && modifier == 0 {
				byteOrder = func() binary.ByteOrder {
					if nativeOrder {
						return binary.LittleEndian
					}
					return binary.BigEndian
				}()
			}
			err = consumeInteger(count, false, width, byteOrder)
		case 'l':
			width := 4
			if nativeModifier != 0 {
				width = longSize
			}
			if nativeModifier == 0 && modifier == 0 {
				byteOrder = func() binary.ByteOrder {
					if nativeOrder {
						return binary.LittleEndian
					}
					return binary.BigEndian
				}()
			}
			err = consumeInteger(count, true, width, byteOrder)
		case 'N':
			if nativeModifier != 0 || modifier != 0 {
				return argumentError("unknown pack directive '" + string(directive) + "'")
			}
			err = consumeInteger(count, false, 4, binary.BigEndian)
		case 'n':
			if nativeModifier != 0 || modifier != 0 {
				return argumentError("unknown pack directive '" + string(directive) + "'")
			}
			err = consumeInteger(count, false, 2, binary.BigEndian)
		case 'V':
			if nativeModifier != 0 || modifier != 0 {
				return argumentError("unknown pack directive '" + string(directive) + "'")
			}
			err = consumeInteger(count, false, 4, binary.LittleEndian)
		case 'v':
			if nativeModifier != 0 || modifier != 0 {
				return argumentError("unknown pack directive '" + string(directive) + "'")
			}
			err = consumeInteger(count, false, 2, binary.LittleEndian)
		case 'Q':
			if nativeModifier != 0 {
				return argumentError("unknown pack directive '" + string(directive) + "'")
			}
			err = consumeInteger(count, false, 8, byteOrder)
		case 'q':
			if nativeModifier != 0 {
				return argumentError("unknown pack directive '" + string(directive) + "'")
			}
			err = consumeInteger(count, true, 8, byteOrder)
		case 'J':
			if modifier == 0 && nativeModifier == 0 {
				byteOrder = func() binary.ByteOrder {
					if nativeOrder {
						return binary.LittleEndian
					}
					return binary.BigEndian
				}()
			}
			err = consumeInteger(count, false, longSize, byteOrder)
		case 'j':
			if modifier == 0 && nativeModifier == 0 {
				byteOrder = func() binary.ByteOrder {
					if nativeOrder {
						return binary.LittleEndian
					}
					return binary.BigEndian
				}()
			}
			err = consumeInteger(count, true, longSize, byteOrder)
		case 'D', 'd', 'E':
			if nativeModifier != 0 || modifier != 0 {
				return argumentError("unknown pack directive '" + string(directive) + "'")
			}
			err = consumeFloat(count, 8, binary.LittleEndian)
		case 'G':
			if nativeModifier != 0 || modifier != 0 {
				return argumentError("unknown pack directive '" + string(directive) + "'")
			}
			err = consumeFloat(count, 8, binary.BigEndian)
		case 'F', 'f', 'e':
			if nativeModifier != 0 || modifier != 0 {
				return argumentError("unknown pack directive '" + string(directive) + "'")
			}
			err = consumeFloat(count, 4, binary.LittleEndian)
		case 'g':
			if nativeModifier != 0 || modifier != 0 {
				return argumentError("unknown pack directive '" + string(directive) + "'")
			}
			err = consumeFloat(count, 4, binary.BigEndian)
		case 'a':
			if nativeModifier != 0 || modifier != 0 {
				return argumentError("unknown pack directive '" + string(directive) + "'")
			}
			if value, e := coercePackString(); e != nil {
				return e
			} else {
				if count < 0 {
					count = int64(len(value))
				}
				if count == 0 {
					err = nil
					break
				}
				bound := int(count)
				chunk := []byte(value)
				if len(chunk) > bound {
					chunk = chunk[:bound]
				}
				out = append(out, chunk...)
				if len(chunk) < bound {
					out = append(out, bytes.Repeat([]byte{0x00}, bound-len(chunk))...)
				}
			}
		case 'A':
			if nativeModifier != 0 || modifier != 0 {
				return argumentError("unknown pack directive '" + string(directive) + "'")
			}
			if value, e := coercePackString(); e != nil {
				return e
			} else {
				if count < 0 {
					count = int64(len(value))
				}
				if count == 0 {
					err = nil
					break
				}
				bound := int(count)
				chunk := []byte(value)
				if len(chunk) > bound {
					chunk = chunk[:bound]
				}
				out = append(out, chunk...)
				if len(chunk) < bound {
					out = append(out, bytes.Repeat([]byte{' '}, bound-len(chunk))...)
				}
			}
		case 'Z':
			if nativeModifier != 0 || modifier != 0 {
				return argumentError("unknown pack directive '" + string(directive) + "'")
			}
			if value, e := coercePackString(); e != nil {
				return e
			} else {
				if count < 0 {
					out = append(out, []byte(value)...)
					out = append(out, 0x00)
					break
				}
				if count == 0 {
					err = nil
					break
				}
				bound := int(count)
				chunk := []byte(value)
				if len(chunk) > bound {
					chunk = chunk[:bound]
				}
				out = append(out, chunk...)
				if len(chunk) < bound {
					out = append(out, bytes.Repeat([]byte{0x00}, bound-len(chunk))...)
				}
			}
		case 'U':
			if nativeModifier != 0 || modifier != 0 {
				return argumentError("unknown pack directive '" + string(directive) + "'")
			}
			if count < 0 {
				count = int64(len(values) - valueIndex)
			}
			for j := int64(0); j < count; j++ {
				if valueIndex >= len(values) {
					return argumentError("too few arguments")
				}
				if override, ok := ULEBPackOverride(values[valueIndex]); ok {
					valueIndex++
					out = append(out, override...)
					continue
				}
				n, ok := valueToInteger(values[valueIndex])
				valueIndex++
				if !ok {
					return typeError("no implicit conversion to Integer")
				}
				if n < 0 || n > math.MaxUint32 {
					return NewRangeError("pack(U): value out of range")
				}
				out = append(out, packUnicodeCodepoint(uint32(n))...)
			}
		case 'u':
			if nativeModifier != 0 || modifier != 0 {
				return argumentError("unknown pack directive '" + string(directive) + "'")
			}
			value, e := coerceRequiredPackString()
			if e != nil {
				return e
			}
			lineLength := int(count)
			if count < 0 || count <= 2 {
				lineLength = 45
			} else {
				lineLength = int(count/3) * 3
			}
			out = append(out, uuencodePackString([]byte(value), lineLength)...)
		case 'm':
			if nativeModifier != 0 || modifier != 0 {
				return argumentError("unknown pack directive '" + string(directive) + "'")
			}
			value, e := coerceRequiredPackString()
			if e != nil {
				return e
			}
			lineLength := int(count)
			if count < 0 || count == 1 || count == 2 {
				lineLength = 45
			}
			out = append(out, base64PackString([]byte(value), lineLength)...)
		case 'M':
			if nativeModifier != 0 || modifier != 0 {
				return argumentError("unknown pack directive '" + string(directive) + "'")
			}
			value, e := coercePrintablePackString()
			if e != nil {
				return e
			}
			lineLength := int(count)
			if count < 0 || count <= 1 {
				lineLength = 73
			} else {
				lineLength++
			}
			out = append(out, quotedPrintablePackString([]byte(value), lineLength)...)
		case 'P', 'p':
			if nativeModifier != 0 || modifier != 0 {
				return argumentError("unknown pack directive '" + string(directive) + "'")
			}
			nullPointer := valueIndex < len(values) && (values[valueIndex] == nil || values[valueIndex].Type == object.ValueNil)
			value, e := coercePackString()
			if e != nil {
				return e
			}
			if !nullPointer {
				payload := value
				packedPointerPayload = &payload
			}
			out = append(out, make([]byte, int(unsafe.Sizeof(uintptr(0))))...)
		case 'B', 'b':
			if nativeModifier != 0 || modifier != 0 {
				return argumentError("unknown pack directive '" + string(directive) + "'")
			}
			value, e := coerceRequiredPackString()
			if e != nil {
				return e
			}
			out = append(out, bitPackString([]byte(value), count, directive == 'B')...)
		case 'H', 'h':
			if nativeModifier != 0 || modifier != 0 {
				return argumentError("unknown pack directive '" + string(directive) + "'")
			}
			value, e := coerceRequiredPackString()
			if e != nil {
				return e
			}
			out = append(out, hexPackString([]byte(value), count, directive == 'H')...)
		case 'w':
			if nativeModifier != 0 || modifier != 0 {
				return argumentError("unknown pack directive '" + string(directive) + "'")
			}
			if count < 0 {
				count = int64(len(values) - valueIndex)
			}
			for j := int64(0); j < count; j++ {
				if valueIndex >= len(values) {
					return argumentError("too few arguments")
				}
				if integer, ok := NumericBigIntOverride(values[valueIndex]); ok {
					valueIndex++
					if integer.Sign() < 0 {
						return argumentError("can't compress negative numbers")
					}
					out = append(out, berPackBigInteger(integer)...)
					continue
				}
				if override, ok := BERPackOverride(values[valueIndex]); ok {
					valueIndex++
					out = append(out, override...)
					continue
				}
				n, ok := valueToInteger(values[valueIndex])
				valueIndex++
				if !ok {
					return typeError("no implicit conversion to Integer")
				}
				if n < 0 {
					return argumentError("can't compress negative numbers")
				}
				out = append(out, berPackInteger(uint64(n))...)
			}
		case 'R':
			if nativeModifier != 0 || modifier != 0 {
				return argumentError("unknown pack directive '" + string(directive) + "'")
			}
			if count < 0 {
				count = int64(len(values) - valueIndex)
			}
			for j := int64(0); j < count; j++ {
				if valueIndex >= len(values) {
					return argumentError("too few arguments")
				}
				if override, ok := ULEBPackOverride(values[valueIndex]); ok {
					valueIndex++
					out = append(out, override...)
					continue
				}
				n, ok := valueToInteger(values[valueIndex])
				valueIndex++
				if !ok {
					return typeError("no implicit conversion to Integer")
				}
				if n < 0 {
					return argumentError("can't compress negative numbers")
				}
				out = append(out, uleb128PackInteger(uint64(n))...)
			}
		case 'r':
			if nativeModifier != 0 || modifier != 0 {
				return argumentError("unknown pack directive '" + string(directive) + "'")
			}
			if count < 0 {
				count = int64(len(values) - valueIndex)
			}
			for j := int64(0); j < count; j++ {
				if valueIndex >= len(values) {
					return argumentError("too few arguments")
				}
				if integer, ok := NumericBigIntOverride(values[valueIndex]); ok {
					valueIndex++
					out = append(out, sleb128PackBigInteger(integer)...)
					continue
				}
				n, ok := valueToInteger(values[valueIndex])
				valueIndex++
				if !ok {
					return typeError("no implicit conversion to Integer")
				}
				out = append(out, sleb128PackInteger(n)...)
			}
		case 'x':
			if nativeModifier != 0 || modifier != 0 {
				return argumentError("unknown pack directive '" + string(directive) + "'")
			}
			if count > 0 {
				out = append(out, bytes.Repeat([]byte{0x00}, int(count))...)
			}
		case 'X':
			if nativeModifier != 0 || modifier != 0 {
				return argumentError("unknown pack directive '" + string(directive) + "'")
			}
			if count < 0 || count == 0 {
				break
			}
			if int(count) > len(out) {
				return argumentError("string not long enough")
			}
			out = out[:len(out)-int(count)]
		case '@':
			if nativeModifier != 0 || modifier != 0 {
				return argumentError("unknown pack directive '" + string(directive) + "'")
			}
			if count < 0 {
				count = 0
			}
			target := int(count)
			if len(out) > target {
				out = out[:target]
			} else if len(out) < target {
				out = append(out, bytes.Repeat([]byte{0x00}, target-len(out))...)
			}
		case '_', '!':
			return argumentError("unknown pack directive '" + string(directive) + "'")
		default:
			return argumentError("unknown pack directive '" + string(directive) + "'")
		}
		if err != nil {
			return err
		}
	}

	if bufferArg != nil {
		bufferArg.Data = string(out)
		if packedPointerPayload != nil && packedPointerStrings != nil {
			packedPointerStrings[bufferArg] = *packedPointerPayload
		}
		return bufferArg
	}
	result := rubyString(string(out))
	if stringEncodings != nil {
		stringEncodings[result] = packResultEncoding(sawBinaryDirective, sawUnicodeDirective, sawASCIIDirective)
	}
	if packedPointerPayload != nil && packedPointerStrings != nil {
		packedPointerStrings[result] = *packedPointerPayload
	}
	return result
}

func packResultEncoding(sawBinaryDirective, sawUnicodeDirective, sawASCIIDirective bool) string {
	if sawBinaryDirective {
		return "BINARY"
	}
	if sawUnicodeDirective {
		return "UTF-8"
	}
	if sawASCIIDirective || !sawUnicodeDirective {
		return "US-ASCII"
	}
	return "BINARY"
}

func packUnicodeCodepoint(value uint32) []byte {
	switch {
	case value <= 0x7f:
		return []byte{byte(value)}
	case value <= 0x7ff:
		return []byte{
			0xc0 | byte(value>>6),
			0x80 | byte(value&0x3f),
		}
	case value <= 0xffff:
		return []byte{
			0xe0 | byte(value>>12),
			0x80 | byte((value>>6)&0x3f),
			0x80 | byte(value&0x3f),
		}
	case value <= 0x1fffff:
		return []byte{
			0xf0 | byte(value>>18),
			0x80 | byte((value>>12)&0x3f),
			0x80 | byte((value>>6)&0x3f),
			0x80 | byte(value&0x3f),
		}
	case value <= 0x3ffffff:
		return []byte{
			0xf8 | byte(value>>24),
			0x80 | byte((value>>18)&0x3f),
			0x80 | byte((value>>12)&0x3f),
			0x80 | byte((value>>6)&0x3f),
			0x80 | byte(value&0x3f),
		}
	default:
		return []byte{
			0xfc | byte(value>>30),
			0x80 | byte((value>>24)&0x3f),
			0x80 | byte((value>>18)&0x3f),
			0x80 | byte((value>>12)&0x3f),
			0x80 | byte((value>>6)&0x3f),
			0x80 | byte(value&0x3f),
		}
	}
}

func packValueClassName(value *object.EmeraldValue) string {
	if value == nil {
		return "NilClass"
	}
	if value.Class != nil && value.Class.Name != "" {
		return value.Class.Name
	}
	switch value.Type {
	case object.ValueNil:
		return "NilClass"
	case object.ValueBool:
		if value.Data == true {
			return "TrueClass"
		}
		return "FalseClass"
	case object.ValueString:
		return "String"
	case object.ValueInteger:
		return "Integer"
	case object.ValueFloat:
		return "Float"
	default:
		return value.TypeName()
	}
}

func bitPackString(input []byte, count int64, msbFirst bool) []byte {
	if count < 0 {
		count = int64(len(input))
	}
	if count <= 0 {
		return []byte{}
	}
	out := make([]byte, (int(count)+7)/8)
	for i := int64(0); i < count; i++ {
		bit := byte(0)
		if i < int64(len(input)) {
			ch := input[i]
			if ch == '0' {
				bit = 0
			} else if ch == '1' {
				bit = 1
			} else {
				bit = ch & 1
			}
		}
		if bit == 0 {
			continue
		}
		byteIndex := int(i / 8)
		bitIndex := uint(i % 8)
		if msbFirst {
			out[byteIndex] |= 1 << (7 - bitIndex)
		} else {
			out[byteIndex] |= 1 << bitIndex
		}
	}
	return out
}

func hexPackString(input []byte, count int64, highNibbleFirst bool) []byte {
	if count < 0 {
		count = int64(len(input))
	}
	if count <= 0 {
		return []byte{}
	}
	out := make([]byte, (int(count)+1)/2)
	for i := int64(0); i < count; i++ {
		nibble := byte(0)
		if i < int64(len(input)) {
			nibble = packHexNibble(input[i])
		}
		byteIndex := int(i / 2)
		if highNibbleFirst {
			if i%2 == 0 {
				out[byteIndex] |= nibble << 4
			} else {
				out[byteIndex] |= nibble
			}
		} else {
			if i%2 == 0 {
				out[byteIndex] |= nibble
			} else {
				out[byteIndex] |= nibble << 4
			}
		}
	}
	return out
}

func packHexNibble(ch byte) byte {
	switch {
	case ch >= '0' && ch <= '9':
		return ch - '0'
	case ch >= 'a' && ch <= 'z':
		return (ch - 'a' + 10) & 0x0f
	case ch >= 'A' && ch <= 'Z':
		return (ch - 'A' + 10) & 0x0f
	default:
		return ch & 0x0f
	}
}

func RememberBERPackOverride(value *object.EmeraldValue, encoded []byte) *object.EmeraldValue {
	if value == nil || len(encoded) == 0 {
		return value
	}
	if berPackOverrides == nil {
		berPackOverrides = make(map[*object.EmeraldValue][]byte)
	}
	berPackOverrides[value] = append([]byte(nil), encoded...)
	return value
}

func BERPackOverride(value *object.EmeraldValue) ([]byte, bool) {
	if value == nil || berPackOverrides == nil {
		return nil, false
	}
	encoded, ok := berPackOverrides[value]
	if !ok {
		return nil, false
	}
	return append([]byte(nil), encoded...), true
}

func RememberNumericBigIntOverride(value *object.EmeraldValue, n *big.Int) *object.EmeraldValue {
	if value == nil || n == nil {
		return value
	}
	if numericBigIntOverrides == nil {
		numericBigIntOverrides = make(map[*object.EmeraldValue]*big.Int)
	}
	numericBigIntOverrides[value] = new(big.Int).Set(n)
	value.BigInt = new(big.Int).Set(n)
	return value
}

func NumericBigIntOverride(value *object.EmeraldValue) (*big.Int, bool) {
	if value == nil {
		return nil, false
	}
	if value.BigInt != nil {
		return new(big.Int).Set(value.BigInt), true
	}
	if numericBigIntOverrides == nil {
		return nil, false
	}
	n, ok := numericBigIntOverrides[value]
	if !ok {
		return nil, false
	}
	return new(big.Int).Set(n), true
}

func numericBigIntValue(value *object.EmeraldValue) (*big.Int, bool) {
	if value == nil || value.Type != object.ValueInteger {
		return nil, false
	}
	if n, ok := NumericBigIntOverride(value); ok {
		return n, true
	}
	return big.NewInt(value.Data.(int64)), true
}

func RememberNumericFloatOverride(value *object.EmeraldValue, f float64) *object.EmeraldValue {
	if value == nil {
		return value
	}
	if numericFloatOverrides == nil {
		numericFloatOverrides = make(map[*object.EmeraldValue]float64)
	}
	numericFloatOverrides[value] = f
	return value
}

func NumericFloatOverride(value *object.EmeraldValue) (float64, bool) {
	if value == nil {
		return 0, false
	}
	if numericFloatOverrides != nil {
		if f, ok := numericFloatOverrides[value]; ok {
			return f, true
		}
	}
	return 0, false
}

func RememberULEBPackOverride(value *object.EmeraldValue, encoded []byte) *object.EmeraldValue {
	if value == nil || len(encoded) == 0 {
		return value
	}
	if ulebPackOverrides == nil {
		ulebPackOverrides = make(map[*object.EmeraldValue][]byte)
	}
	ulebPackOverrides[value] = append([]byte(nil), encoded...)
	return value
}

func ULEBPackOverride(value *object.EmeraldValue) ([]byte, bool) {
	if value == nil || ulebPackOverrides == nil {
		return nil, false
	}
	encoded, ok := ulebPackOverrides[value]
	if !ok {
		return nil, false
	}
	return append([]byte(nil), encoded...), true
}

func RememberULEBPackIntegerLiteral(value *object.EmeraldValue, literal string) *object.EmeraldValue {
	text := strings.ReplaceAll(literal, "_", "")
	n, ok := new(big.Int).SetString(text, 0)
	if !ok || n.IsInt64() {
		return value
	}
	RememberNumericBigIntOverride(value, n)
	if strings.HasPrefix(strings.ToLower(text), "0x") && n.Sign() >= 0 {
		RememberULEBPackOverride(value, uleb128PackBigInteger(n))
	}
	return value
}

func uleb128PackInteger(value uint64) []byte {
	out := []byte{}
	for {
		b := byte(value & 0x7f)
		value >>= 7
		if value != 0 {
			b |= 0x80
		}
		out = append(out, b)
		if value == 0 {
			break
		}
	}
	return out
}

func uleb128PackBigInteger(value *big.Int) []byte {
	if value == nil || value.Sign() == 0 {
		return []byte{0}
	}
	n := new(big.Int).Set(value)
	base := big.NewInt(128)
	zero := big.NewInt(0)
	rem := new(big.Int)
	out := []byte{}
	for n.Cmp(zero) > 0 {
		n.QuoRem(n, base, rem)
		b := byte(rem.Int64())
		if n.Cmp(zero) > 0 {
			b |= 0x80
		}
		out = append(out, b)
	}
	return out
}

func sleb128PackInteger(value int64) []byte {
	out := []byte{}
	for {
		b := byte(value & 0x7f)
		signSet := b&0x40 != 0
		value >>= 7
		done := (value == 0 && !signSet) || (value == -1 && signSet)
		if !done {
			b |= 0x80
		}
		out = append(out, b)
		if done {
			break
		}
	}
	return out
}

func sleb128PackBigInteger(value *big.Int) []byte {
	remaining := new(big.Int).Set(value)
	minusOne := big.NewInt(-1)
	mask := big.NewInt(0x7f)
	result := make([]byte, 0)
	for {
		low := new(big.Int).And(new(big.Int).Set(remaining), mask)
		b := byte(low.Uint64())
		remaining.Rsh(remaining, 7)
		done := (remaining.Sign() == 0 && b&0x40 == 0) || (remaining.Cmp(minusOne) == 0 && b&0x40 != 0)
		if !done {
			b |= 0x80
		}
		result = append(result, b)
		if done {
			return result
		}
	}
}

func BERPackPowerOfTwo(exp int) []byte {
	if exp < 0 {
		return []byte{}
	}
	n := new(big.Int).Lsh(big.NewInt(1), uint(exp))
	return berPackBigInteger(n)
}

func berPackBigInteger(value *big.Int) []byte {
	if value == nil || value.Sign() == 0 {
		return []byte{0}
	}
	base := big.NewInt(128)
	zero := big.NewInt(0)
	n := new(big.Int).Set(value)
	rem := new(big.Int)
	groups := []byte{}
	for n.Cmp(zero) > 0 {
		n.QuoRem(n, base, rem)
		groups = append(groups, byte(rem.Int64()))
	}
	out := make([]byte, len(groups))
	for i := len(groups) - 1; i >= 0; i-- {
		b := groups[i]
		if i != 0 {
			b |= 0x80
		}
		out[len(groups)-1-i] = b
	}
	return out
}

func berPackInteger(value uint64) []byte {
	if value == 0 {
		return []byte{0}
	}
	groups := []byte{}
	for value > 0 {
		groups = append(groups, byte(value&0x7f))
		value >>= 7
	}
	out := make([]byte, len(groups))
	for i := len(groups) - 1; i >= 0; i-- {
		b := groups[i]
		if i != 0 {
			b |= 0x80
		}
		out[len(groups)-1-i] = b
	}
	return out
}

func uuencodePackString(input []byte, lineLength int) []byte {
	if len(input) == 0 {
		return []byte{}
	}
	if lineLength <= 0 {
		lineLength = 45
	}
	out := make([]byte, 0, ((len(input)+lineLength-1)/lineLength)*(lineLength*4/3+2))
	encodeChar := func(value byte) byte {
		value &= 0x3f
		if value == 0 {
			return '`'
		}
		return value + 0x20
	}
	for offset := 0; offset < len(input); offset += lineLength {
		end := offset + lineLength
		if end > len(input) {
			end = len(input)
		}
		chunk := input[offset:end]
		out = append(out, encodeChar(byte(len(chunk))))
		for i := 0; i < len(chunk); i += 3 {
			var a, b, c byte
			a = chunk[i]
			if i+1 < len(chunk) {
				b = chunk[i+1]
			}
			if i+2 < len(chunk) {
				c = chunk[i+2]
			}
			out = append(out,
				encodeChar(a>>2),
				encodeChar((a<<4)|(b>>4)),
				encodeChar((b<<2)|(c>>6)),
				encodeChar(c),
			)
		}
		out = append(out, '\n')
	}
	return out
}

func base64PackString(input []byte, lineLength int) []byte {
	if len(input) == 0 {
		return []byte{}
	}
	encoded := base64.StdEncoding.EncodeToString(input)
	if lineLength == 0 {
		return []byte(encoded)
	}
	if lineLength < 0 {
		lineLength = 45
	}
	charsPerLine := ((lineLength + 2) / 3) * 4
	if charsPerLine <= 0 {
		charsPerLine = 60
	}
	out := make([]byte, 0, len(encoded)+len(encoded)/charsPerLine+1)
	for offset := 0; offset < len(encoded); offset += charsPerLine {
		end := offset + charsPerLine
		if end > len(encoded) {
			end = len(encoded)
		}
		out = append(out, encoded[offset:end]...)
		out = append(out, '\n')
	}
	return out
}

func quotedPrintablePackString(input []byte, lineLength int) []byte {
	if len(input) == 0 {
		return []byte{}
	}
	if lineLength <= 0 {
		lineLength = 73
	}
	out := make([]byte, 0, len(input)+len(input)/lineLength+4)
	col := 0
	hex := "0123456789ABCDEF"

	appendSoftBreak := func() {
		out = append(out, '=', '\n')
		col = 0
	}
	encodedFor := func(b byte) []byte {
		if b == '=' || b < 32 && b != '\t' && b != '\n' || b >= 127 {
			return []byte{'=', hex[b>>4], hex[b&0x0f]}
		}
		return []byte{b}
	}

	for i, b := range input {
		if b == '\n' {
			out = append(out, '\n')
			col = 0
			continue
		}
		token := encodedFor(b)
		limit := lineLength
		if len(token) == 3 {
			limit = ((lineLength + 2) / 3) * 3
		}
		if col+len(token) > limit {
			appendSoftBreak()
		}
		out = append(out, token...)
		col += len(token)
		if i+1 < len(input) && input[i+1] == '\n' && (b == ' ' || b == '\t') {
			appendSoftBreak()
		}
	}
	if col > 0 {
		appendSoftBreak()
	}
	return out
}

func arrayUniq(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	seen := make(map[string][]*object.EmeraldValue)
	newArr := make([]*object.EmeraldValue, 0)
	for i := 0; ; i++ {
		arr := receiver.Data.([]*object.EmeraldValue)
		if i >= len(arr) {
			break
		}
		elem := arr[i]
		keyValue := elem
		if BlockGivenCheck != nil && BlockGivenCheck() && CallBlock != nil {
			keyValue = CallBlock(elem)
			if keyValue != nil && keyValue.Type == object.ValueException {
				return keyValue
			}
		}
		key, duplicate, errVal := arrayUniqKey(seen, keyValue)
		if errVal != nil {
			return errVal
		}
		if !duplicate {
			seen[key] = append(seen[key], keyValue)
			newArr = append(newArr, elem)
		}
	}
	return &object.EmeraldValue{
		Type:  object.ValueArray,
		Data:  newArr,
		Class: R.Classes["Array"],
	}
}

func arrayUniqBang(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver != nil && receiver.Frozen {
		return frozenError("can't modify frozen array")
	}
	seen := make(map[string][]*object.EmeraldValue)
	newArr := make([]*object.EmeraldValue, 0, len(receiver.Data.([]*object.EmeraldValue)))
	changed := false
	for i := 0; ; i++ {
		arr := receiver.Data.([]*object.EmeraldValue)
		if i >= len(arr) {
			break
		}
		elem := arr[i]
		keyValue := elem
		if BlockGivenCheck != nil && BlockGivenCheck() && CallBlock != nil {
			keyValue = CallBlock(elem)
			if keyValue != nil && keyValue.Type == object.ValueException {
				return keyValue
			}
		}
		key, duplicate, errVal := arrayUniqKey(seen, keyValue)
		if errVal != nil {
			return errVal
		}
		if duplicate {
			changed = true
			continue
		}
		seen[key] = append(seen[key], keyValue)
		newArr = append(newArr, elem)
	}
	if !changed {
		return R.NilVal
	}
	receiver.Data = newArr
	return receiver
}

func arrayUniqKey(seen map[string][]*object.EmeraldValue, value *object.EmeraldValue) (string, bool, *object.EmeraldValue) {
	hash := value
	if CallMethod != nil {
		hash = CallMethod(value, "hash")
		if hash != nil && hash.Type == object.ValueException {
			return "", false, hash
		}
	}
	key := hash.Inspect()
	for _, existing := range seen[key] {
		if existing == value {
			return key, true, nil
		}
		if CallMethod != nil {
			result := CallMethod(existing, "eql?", value)
			if result != nil && result.Type == object.ValueException {
				return "", false, result
			}
			if isTruthy(result) {
				return key, true, nil
			}
		} else if existing.Equals(value) {
			return key, true, nil
		}
	}
	return key, false, nil
}

func arraySort(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	arr := receiver.Data.([]*object.EmeraldValue)
	if len(arr) == 0 {
		return &object.EmeraldValue{Type: object.ValueArray, Data: []*object.EmeraldValue{}, Class: R.Classes["Array"]}
	}
	newArr := make([]*object.EmeraldValue, len(arr))
	copy(newArr, arr)
	if err := sortArrayValues(newArr); err != nil {
		return err
	}
	return &object.EmeraldValue{
		Type:  object.ValueArray,
		Data:  newArr,
		Class: R.Classes["Array"],
	}
}

func arraySortBang(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver != nil && receiver.Frozen {
		return frozenError("can't modify frozen array")
	}
	arr := receiver.Data.([]*object.EmeraldValue)
	if err := sortArrayValues(arr); err != nil {
		return err
	}
	receiver.Data = arr
	return receiver
}

func sortArrayValues(arr []*object.EmeraldValue) *object.EmeraldValue {
	for i := 0; i < len(arr)-1; i++ {
		for j := 0; j < len(arr)-i-1; j++ {
			cmp, err := arraySortCompare(arr[j], arr[j+1])
			if err != nil {
				return err
			}
			if cmp > 0 {
				arr[j], arr[j+1] = arr[j+1], arr[j]
			}
		}
	}
	return nil
}

func arraySortCompare(left, right *object.EmeraldValue) (int, *object.EmeraldValue) {
	if BlockGivenCheck != nil && BlockGivenCheck() && CallBlock != nil {
		value := CallBlock(left, right)
		if LastBlockResult != nil {
			result := LastBlockResult
			LastBlockResult = nil
			return 0, result
		}
		if value == nil || value.Type == object.ValueNil {
			return 0, NewArgumentError("comparison of Array elements failed")
		}
		if value.Type == object.ValueException {
			return 0, value
		}
		if cmp, ok := valueToSortComparison(value); ok {
			return cmp, nil
		}
		return 0, NewArgumentError("comparison of Array elements failed")
	}
	if CallMethod == nil || left == nil {
		return 0, NewArgumentError("comparison of Array elements failed")
	}
	value := CallMethod(left, "<=>", right)
	if value != nil && value.Type == object.ValueException {
		if isNoMethodError(value) {
			return 0, NewArgumentError("comparison of Array elements failed")
		}
		return 0, value
	}
	if cmp, ok := valueToSortComparison(value); ok {
		return cmp, nil
	}
	return 0, NewArgumentError("comparison of Array elements failed")
}

func valueToSortComparison(value *object.EmeraldValue) (int, bool) {
	return valueToSortComparisonSeen(value, make(map[*object.EmeraldValue]bool))
}

func valueToSortComparisonSeen(value *object.EmeraldValue, seen map[*object.EmeraldValue]bool) (int, bool) {
	if value == nil {
		return 0, false
	}
	if seen[value] {
		return 0, false
	}
	seen[value] = true
	switch value.Type {
	case object.ValueInteger:
		if integer, ok := NumericBigIntOverride(value); ok {
			return integer.Sign(), true
		}
		n := value.Data.(int64)
		if n < 0 {
			return -1, true
		}
		if n > 0 {
			return 1, true
		}
		return 0, true
	case object.ValueFloat:
		n := value.Data.(float64)
		if n < 0 {
			return -1, true
		}
		if n > 0 {
			return 1, true
		}
		return 0, true
	}
	if CallMethod != nil && receiverHasCallableMethod(value, "<=>") {
		cmp := CallMethod(value, "<=>", newInt(0))
		if cmp != nil && cmp.Type == object.ValueException {
			return 0, false
		}
		return valueToSortComparisonSeen(cmp, seen)
	}
	return 0, false
}

func arrayPlus(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) < 1 {
		return receiver
	}
	arr := receiver.Data.([]*object.EmeraldValue)
	otherValue := args[0]
	if otherValue.Type != object.ValueArray {
		if CallMethod != nil && receiverHasCallableMethod(otherValue, "to_ary") {
			converted := callMethodPropagatingException(otherValue, "to_ary")
			if converted != nil && converted.Type == object.ValueException {
				return converted
			}
			otherValue = converted
		}
	}
	other, ok := otherValue.Data.([]*object.EmeraldValue)
	if !ok {
		return typeError("no implicit conversion to Array")
	}
	result := make([]*object.EmeraldValue, len(arr)+len(other))
	copy(result, arr)
	copy(result[len(arr):], other)
	return &object.EmeraldValue{
		Type:  object.ValueArray,
		Data:  result,
		Class: R.Classes["Array"],
	}
}

func arrayMinus(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	arr := receiver.Data.([]*object.EmeraldValue)
	others := make([][]*object.EmeraldValue, 0, len(args))
	for _, argument := range args {
		value := argument
		if value == nil || value.Type != object.ValueArray {
			if value == nil || CallMethod == nil || !receiverHasCallableMethod(value, "to_ary") {
				return typeError("no implicit conversion to Array")
			}
			value = CallMethod(value, "to_ary")
			if value != nil && value.Type == object.ValueException {
				return value
			}
		}
		if value == nil || value.Type != object.ValueArray {
			return typeError("no implicit conversion to Array")
		}
		others = append(others, value.Data.([]*object.EmeraldValue))
	}
	result := make([]*object.EmeraldValue, 0, len(arr))
	for _, candidate := range arr {
		remove := false
		for _, other := range others {
			for _, value := range other {
				equal, errVal := arraySetElementEqual(candidate, value)
				if errVal != nil {
					return errVal
				}
				if equal {
					remove = true
					break
				}
			}
			if remove {
				break
			}
		}
		if !remove {
			result = append(result, candidate)
		}
	}
	return &object.EmeraldValue{
		Type:  object.ValueArray,
		Data:  result,
		Class: R.Classes["Array"],
	}
}

func arrayIntersection(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) < 1 {
		return &object.EmeraldValue{Type: object.ValueArray, Data: append([]*object.EmeraldValue(nil), receiver.Data.([]*object.EmeraldValue)...), Class: R.Classes["Array"]}
	}
	arr := receiver.Data.([]*object.EmeraldValue)
	others := make([][]*object.EmeraldValue, 0, len(args))
	for _, argument := range args {
		value := argument
		if value == nil || value.Type != object.ValueArray {
			if value == nil || CallMethod == nil || !receiverHasCallableMethod(value, "to_ary") {
				return typeError("no implicit conversion to Array")
			}
			value = CallMethod(value, "to_ary")
			if value != nil && value.Type == object.ValueException {
				return value
			}
		}
		if value == nil || value.Type != object.ValueArray {
			return typeError("no implicit conversion to Array")
		}
		others = append(others, value.Data.([]*object.EmeraldValue))
	}
	result := make([]*object.EmeraldValue, 0)
	for _, candidate := range arr {
		presentEverywhere := true
		for _, other := range others {
			present := false
			for _, value := range other {
				equal, errVal := arraySetElementEqual(candidate, value)
				if errVal != nil {
					return errVal
				}
				if equal {
					present = true
					break
				}
			}
			if !present {
				presentEverywhere = false
				break
			}
		}
		if !presentEverywhere {
			continue
		}
		duplicate := false
		for _, existing := range result {
			equal, errVal := arraySetElementEqual(existing, candidate)
			if errVal != nil {
				return errVal
			}
			if equal {
				duplicate = true
				break
			}
		}
		if !duplicate {
			result = append(result, candidate)
		}
	}
	return &object.EmeraldValue{
		Type:  object.ValueArray,
		Data:  result,
		Class: R.Classes["Array"],
	}
}

func arraySetElementEqual(left, right *object.EmeraldValue) (bool, *object.EmeraldValue) {
	if left == right {
		return true, nil
	}
	if left == nil || right == nil {
		return false, nil
	}
	if CallMethod != nil && receiverHasCallableMethod(left, "eql?") {
		result := CallMethod(left, "eql?", right)
		if result != nil && result.Type == object.ValueException {
			return false, result
		}
		return result != nil && result.IsTruthy(), nil
	}
	return left.Equals(right), nil
}

func arrayIntersectPredicate(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 1 {
		return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 1)", len(args)))
	}
	other := args[0]
	if other == nil || other.Type != object.ValueArray {
		if other == nil || CallMethod == nil || !receiverHasCallableMethod(other, "to_ary") {
			return typeError("no implicit conversion to Array")
		}
		other = CallMethod(other, "to_ary")
		if other != nil && other.Type == object.ValueException {
			return other
		}
		if other == nil || other.Type != object.ValueArray {
			return typeError("no implicit conversion to Array")
		}
	}
	for _, left := range receiver.Data.([]*object.EmeraldValue) {
		for _, right := range other.Data.([]*object.EmeraldValue) {
			if left == right {
				return R.TrueVal
			}
			if left != nil && right != nil && CallMethod != nil && receiverHasCallableMethod(left, "eql?") {
				if result := CallMethod(left, "eql?", right); result != nil && result.Type != object.ValueException && isTruthy(result) {
					return R.TrueVal
				}
				continue
			}
			if left != nil && left.Equals(right) {
				return R.TrueVal
			}
		}
	}
	return R.FalseVal
}

func arrayUnion(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	inputs := make([][]*object.EmeraldValue, 0, len(args)+1)
	inputs = append(inputs, receiver.Data.([]*object.EmeraldValue))
	for _, arg := range args {
		value := arg
		if value == nil || value.Type != object.ValueArray {
			if value == nil || CallMethod == nil || !receiverHasCallableMethod(value, "to_ary") {
				return typeError("no implicit conversion to Array")
			}
			value = CallMethod(value, "to_ary")
			if value != nil && value.Type == object.ValueException {
				return value
			}
		}
		if value == nil || value.Type != object.ValueArray {
			return typeError("no implicit conversion to Array")
		}
		inputs = append(inputs, value.Data.([]*object.EmeraldValue))
	}
	result := make([]*object.EmeraldValue, 0)
	for _, input := range inputs {
		for _, candidate := range input {
			duplicate := false
			for _, existing := range result {
				equal, errVal := arraySetElementEqual(candidate, existing)
				if errVal != nil {
					return errVal
				}
				if equal {
					duplicate = true
					break
				}
			}
			if !duplicate {
				result = append(result, candidate)
			}
		}
	}
	return &object.EmeraldValue{
		Type:  object.ValueArray,
		Data:  result,
		Class: R.Classes["Array"],
	}
}

func arrayProduct(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	arrays := make([][]*object.EmeraldValue, 0, len(args)+1)
	arrays = append(arrays, receiver.Data.([]*object.EmeraldValue))
	total := int64(len(arrays[0]))
	for _, arg := range args {
		values, ok := valueToArray(arg)
		if !ok {
			return typeError("no implicit conversion of " + arg.TypeName() + " into Array")
		}
		arrays = append(arrays, values)
		total *= int64(len(values))
		if total > 10_000_000 && !(BlockGivenCheck != nil && BlockGivenCheck()) {
			return NewRangeError("too big to product")
		}
	}
	if len(arrays) == 1 {
		rows := make([]*object.EmeraldValue, len(arrays[0]))
		for i, value := range arrays[0] {
			rows[i] = &object.EmeraldValue{Type: object.ValueArray, Data: []*object.EmeraldValue{value}, Class: R.Classes["Array"]}
		}
		if BlockGivenCheck != nil && BlockGivenCheck() && CallBlock != nil {
			for _, row := range rows {
				CallBlock(row)
			}
			return receiver
		}
		return &object.EmeraldValue{Type: object.ValueArray, Data: rows, Class: R.Classes["Array"]}
	}
	for _, values := range arrays {
		if len(values) == 0 {
			if BlockGivenCheck != nil && BlockGivenCheck() {
				return receiver
			}
			return &object.EmeraldValue{Type: object.ValueArray, Data: []*object.EmeraldValue{}, Class: R.Classes["Array"]}
		}
	}
	result := make([]*object.EmeraldValue, 0)
	var build func(int, []*object.EmeraldValue)
	build = func(depth int, prefix []*object.EmeraldValue) {
		if depth == len(arrays) {
			rowValues := append([]*object.EmeraldValue(nil), prefix...)
			row := &object.EmeraldValue{Type: object.ValueArray, Data: rowValues, Class: R.Classes["Array"]}
			if BlockGivenCheck != nil && BlockGivenCheck() && CallBlock != nil {
				CallBlock(row)
			} else {
				result = append(result, row)
			}
			return
		}
		for _, value := range arrays[depth] {
			build(depth+1, append(prefix, value))
		}
	}
	build(0, nil)
	if BlockGivenCheck != nil && BlockGivenCheck() {
		return receiver
	}
	return &object.EmeraldValue{Type: object.ValueArray, Data: result, Class: R.Classes["Array"]}
}

func arrayTake(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) < 1 {
		return R.NilVal
	}
	arr := receiver.Data.([]*object.EmeraldValue)
	count, ok := valueToInteger(args[0])
	if !ok {
		return R.NilVal
	}
	n := int(count)
	if n > len(arr) {
		n = len(arr)
	}
	if n < 0 {
		return NewArgumentError("attempt to take negative size")
	}
	return &object.EmeraldValue{
		Type:  object.ValueArray,
		Data:  arr[:n],
		Class: R.Classes["Array"],
	}
}

func arrayDrop(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) < 1 {
		return R.NilVal
	}
	arr := receiver.Data.([]*object.EmeraldValue)
	count, ok := valueToInteger(args[0])
	if !ok {
		return conversionTypeErrorToInteger(args[0])
	}
	n := int(count)
	if n < 0 {
		return NewArgumentError("attempt to drop negative size")
	}
	if n > len(arr) {
		n = len(arr)
	}
	return &object.EmeraldValue{
		Type:  object.ValueArray,
		Data:  arr[n:],
		Class: R.Classes["Array"],
	}
}

func arrayTranspose(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) > 0 {
		return NewArgumentError("wrong number of arguments")
	}
	rawRows := receiver.Data.([]*object.EmeraldValue)
	if len(rawRows) == 0 {
		return &object.EmeraldValue{Type: object.ValueArray, Data: []*object.EmeraldValue{}, Class: R.Classes["Array"]}
	}
	rows := make([][]*object.EmeraldValue, len(rawRows))
	width := -1
	for i, rowValue := range rawRows {
		row, ok := valueToArray(rowValue)
		if !ok {
			return typeError("can't convert " + rowValue.TypeName() + " into Array")
		}
		if width < 0 {
			width = len(row)
		} else if len(row) != width {
			return newRuntimeException(R.Classes["IndexError"], "element size differs")
		}
		rows[i] = row
	}
	if width <= 0 {
		return &object.EmeraldValue{Type: object.ValueArray, Data: []*object.EmeraldValue{}, Class: R.Classes["Array"]}
	}
	result := make([]*object.EmeraldValue, width)
	for col := 0; col < width; col++ {
		outRow := make([]*object.EmeraldValue, len(rows))
		for row := range rows {
			outRow[row] = rows[row][col]
		}
		result[col] = &object.EmeraldValue{Type: object.ValueArray, Data: outRow, Class: R.Classes["Array"]}
	}
	return &object.EmeraldValue{Type: object.ValueArray, Data: result, Class: R.Classes["Array"]}
}

func arrayDig(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 0 {
		return NewArgumentError("wrong number of arguments")
	}
	value := arrayAt(receiver, args[0])
	if value == nil || value.Type == object.ValueException {
		return value
	}
	if len(args) == 1 || value.Type == object.ValueNil {
		return value
	}
	if CallMethod == nil || !receiverHasCallableMethod(value, "dig") {
		return typeError(value.TypeName() + " does not have #dig method")
	}
	result := CallMethod(value, "dig", args[1:]...)
	if result == nil {
		return R.NilVal
	}
	return result
}

func arrayAny(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) > 1 {
		return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 0..1)", len(args)))
	}
	if len(receiver.Data.([]*object.EmeraldValue)) == 0 {
		return R.FalseVal
	}
	for i := 0; ; i++ {
		arr := receiver.Data.([]*object.EmeraldValue)
		if i >= len(arr) {
			break
		}
		elem := arr[i]
		if len(args) == 1 {
			val := enumerablePatternMatch(args[0], elem)
			if val != nil && val.Type == object.ValueException {
				return val
			}
			if isTruthy(val) {
				return R.TrueVal
			}
		} else if CallBlock != nil && BlockGivenCheck != nil && BlockGivenCheck() {
			val := CallBlock(elem)
			if val != nil && val.Type == object.ValueException {
				return val
			}
			if isTruthy(val) {
				return R.TrueVal
			}
		} else {
			if isTruthy(elem) {
				return R.TrueVal
			}
		}
	}
	return R.FalseVal
}

