func arrayOne(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) > 1 {
		return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 0..1)", len(args)))
	}
	count := 0
	for i := 0; ; i++ {
		arr := receiver.Data.([]*object.EmeraldValue)
		if i >= len(arr) {
			break
		}
		elem := arr[i]
		var matched bool
		if len(args) == 1 {
			val := enumerablePatternMatch(args[0], elem)
			if val != nil && val.Type == object.ValueException {
				return val
			}
			matched = isTruthy(val)
		} else if CallBlock != nil && BlockGivenCheck != nil && BlockGivenCheck() {
			val := CallBlock(elem)
			if val != nil && val.Type == object.ValueException {
				return val
			}
			matched = isTruthy(val)
		} else if elem.Type != object.ValueNil && elem.Type != object.ValueBool {
			matched = true
		} else if elem.Type == object.ValueBool && elem.Data.(bool) {
			matched = true
		}
		if matched {
			count++
			if count > 1 {
				return R.FalseVal
			}
		}
	}
	if count == 1 {
		return R.TrueVal
	}
	return R.FalseVal
}

func arraySum(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) > 1 {
		return NewArgumentError("wrong number of arguments")
	}
	sum := &object.EmeraldValue{Type: object.ValueInteger, Data: int64(0), Class: R.Classes["Integer"]}
	if len(args) == 1 {
		sum = args[0]
	}
	values := make([]*object.EmeraldValue, 0, len(receiver.Data.([]*object.EmeraldValue)))
	for i := 0; ; i++ {
		arr := receiver.Data.([]*object.EmeraldValue)
		if i >= len(arr) {
			break
		}
		value := arr[i]
		if CallBlock != nil && BlockGivenCheck != nil && BlockGivenCheck() {
			value = CallBlock(value)
			if value != nil && value.Type == object.ValueException {
				return value
			}
		}
		values = append(values, value)
	}
	allNumeric := sum.Type == object.ValueInteger || sum.Type == object.ValueFloat
	hasFloat := sum.Type == object.ValueFloat
	for _, value := range values {
		if value == nil || (value.Type != object.ValueInteger && value.Type != object.ValueFloat) {
			allNumeric = false
			break
		}
		hasFloat = hasFloat || value.Type == object.ValueFloat
	}
	if allNumeric && hasFloat {
		total := numericValueAsFloat(sum)
		compensation := 0.0
		for _, value := range values {
			next := numericValueAsFloat(value)
			if math.IsInf(total, 0) || math.IsNaN(total) || math.IsInf(next, 0) || math.IsNaN(next) {
				total += next
				compensation = 0
				continue
			}
			y := next - compensation
			t := total + y
			compensation = (t - total) - y
			total = t
		}
		return &object.EmeraldValue{Type: object.ValueFloat, Data: total, Class: R.Classes["Float"]}
	}
	for _, value := range values {
		if CallMethod == nil {
			return typeError("Array#sum requires +")
		}
		next := CallMethod(sum, "+", value)
		if next == nil || next.Type == object.ValueNil {
			return typeError("Array#sum element cannot be added")
		}
		if next.Type == object.ValueException {
			return next
		}
		sum = next
	}
	return sum
}

