func stringSubstitute(receiver *object.EmeraldValue, args []*object.EmeraldValue, global bool, bang bool) (*object.EmeraldValue, bool, *object.EmeraldValue) {
	hasBlock := len(args) < 2 && BlockGivenCheck != nil && BlockGivenCheck() && CurrentBlockValue != nil && CurrentBlockValue() != nil && CallBlockWithArgs != nil
	if strings.EqualFold(stringEncodingName(receiver), "UTF-8") && stringHasInvalidUTF8Byte(stringRawValue(receiver)) {
		return nil, false, argumentError("invalid byte sequence in UTF-8")
	}
	if len(args) == 0 {
		return nil, false, NewArgumentError("wrong number of arguments")
	}
	if len(args) < 2 && !hasBlock {
		if !global {
			return nil, false, NewArgumentError("wrong number of arguments")
		}
		return newGeneratorEnumerator(func() ([]*object.EmeraldValue, *object.EmeraldValue) {
			return stringSubstituteEnumeratorValues(receiver, args[0], global)
		}), true, nil
	}
	if len(args) > 2 {
		merged, ok := stringSubstituteMergeHashArguments(args[1:])
		if !ok {
			return nil, false, NewArgumentError("wrong number of arguments")
		}
		args = []*object.EmeraldValue{args[0], merged}
	}
	pattern, errVal := stringSubstitutePattern(args[0])
	if errVal != nil {
		return nil, false, errVal
	}
	replacement := ""
	var replacementHash *object.EmeraldValue
	if !hasBlock {
		if args[1] != nil && args[1].Type == object.ValueHash {
			replacementHash = args[1]
		} else {
			text, errVal := stringSubstituteReplacement(args[1])
			if errVal != nil {
				return nil, false, errVal
			}
			replacement = text
		}
	}
	result, resultEncoding, modified, errVal := stringSubstituteApply(receiver, pattern, replacement, replacementHash, global, hasBlock, bang)
	if errVal != nil {
		return nil, false, errVal
	}
	return stringWithEncoding(result, resultEncoding), modified, nil
}

func stringSubstituteMergeHashArguments(values []*object.EmeraldValue) (*object.EmeraldValue, bool) {
	merged := emptyHashValue()
	mergedData := hashData(merged)
	for _, value := range values {
		if value == nil || value.Type != object.ValueHash {
			return nil, false
		}
		data := hashData(value)
		if data == nil {
			continue
		}
		for _, key := range data.Keys {
			mergedData.Pairs[key] = data.Pairs[key]
			mergedData.Keys = append(mergedData.Keys, key)
		}
	}
	return merged, true
}

func stringSubstitutePattern(value *object.EmeraldValue) (*object.EmeraldValue, *object.EmeraldValue) {
	if value == nil || value.Type == object.ValueNil {
		return nil, conversionTypeErrorToString(value)
	}
	if value.Type == object.ValueRegexp || value.Type == object.ValueString {
		return value, nil
	}
	text, ok, viaToStr, errVal := evalCoerceToString(value)
	if errVal != nil {
		return nil, errVal
	}
	if !ok {
		return nil, conversionTypeErrorToStringForMode(value, viaToStr)
	}
	return stringWithEncoding(text, stringEncodingName(value)), nil
}

func stringSubstituteReplacement(value *object.EmeraldValue) (string, *object.EmeraldValue) {
	if value == nil || value.Type == object.ValueNil {
		return "", conversionTypeErrorToString(value)
	}
	text, ok, viaToStr, errVal := evalCoerceToString(value)
	if errVal != nil {
		return "", errVal
	}
	if !ok {
		return "", conversionTypeErrorToStringForMode(value, viaToStr)
	}
	return text, nil
}

func stringSubstituteEnumeratorValues(receiver, patternValue *object.EmeraldValue, global bool) ([]*object.EmeraldValue, *object.EmeraldValue) {
	pattern, errVal := stringSubstitutePattern(patternValue)
	if errVal != nil {
		return nil, errVal
	}
	matches := stringSubstituteMatches(stringRawValue(receiver), pattern, global)
	values := make([]*object.EmeraldValue, 0, len(matches))
	for _, m := range matches {
		values = append(values, stringWithEncoding(m.text, stringEncodingName(receiver)))
	}
	return values, nil
}

type stringSubstituteMatch struct {
	start   int
	end     int
	text    string
	indices []int
	matches []string
	names   map[string][]int
}

func stringSubstituteMatches(s string, pattern *object.EmeraldValue, global bool) []stringSubstituteMatch {
	if pattern == nil {
		return nil
	}
	if pattern.Type == object.ValueString {
		p := stringRawValue(pattern)
		if p == "" {
			if !global {
				return []stringSubstituteMatch{stringSubstituteStringMatch(s, 0, 0)}
			}
			matches := make([]stringSubstituteMatch, 0, len([]rune(s))+1)
			offset := 0
			matches = append(matches, stringSubstituteStringMatch(s, 0, 0))
			for _, r := range s {
				offset += len(string(r))
				matches = append(matches, stringSubstituteStringMatch(s, offset, offset))
			}
			return matches
		}
		matches := []stringSubstituteMatch{}
		for i := 0; i <= len(s); {
			idx := strings.Index(s[i:], p)
			if idx < 0 {
				break
			}
			start := i + idx
			end := start + len(p)
			matches = append(matches, stringSubstituteStringMatch(s, start, end))
			if !global {
				break
			}
			i = end
		}
		return matches
	}
	if pattern.Type != object.ValueRegexp {
		return nil
	}
	r := pattern.Data.(*object.RRegexp)
	compiled := *r
	if strings.HasPrefix(compiled.Pattern, "(?~") && strings.HasSuffix(compiled.Pattern, ")") {
		forbidden := compiled.Pattern[3 : len(compiled.Pattern)-1]
		if forbidden != "" {
			matches := make([]stringSubstituteMatch, 0)
			for position := 0; position <= len(s); {
				end := len(s)
				if index := strings.Index(s[position:], forbidden); index >= 0 {
					end = position + index + len(forbidden) - 1
				}
				matches = append(matches, stringSubstituteStringMatch(s, position, end))
				if !global || end >= len(s) {
					if global && position < len(s) && end == len(s) {
						matches = append(matches, stringSubstituteStringMatch(s, end, end))
					}
					break
				}
				if end > position {
					position = end
				} else {
					_, width := utf8.DecodeRuneInString(s[position:])
					position += width
				}
			}
			return matches
		}
	}
	sequential := strings.Contains(compiled.Pattern, `\G`)
	if sequential {
		compiled.Pattern = strings.ReplaceAll(compiled.Pattern, `\G`, `^`)
	}
	names := make(map[string][]int)
	var locs [][]int
	re, err := regexp.Compile(rubyRegexpCompilePattern(&compiled))
	if regexpNeedsOnig(compiled.Pattern) {
		position := 0
		for position <= len(s) {
			loc, handled, errorText := onigRegexpSearch(regexpOnigCompatiblePattern(compiled.Pattern), s[position:], compiled.Options)
			if !handled || errorText != "" || len(loc) < 2 {
				break
			}
			for index := range loc {
				if loc[index] >= 0 {
					loc[index] += position
				}
			}
			locs = append(locs, loc)
			if !global {
				break
			}
			if loc[1] > position {
				position = loc[1]
			} else if position < len(s) {
				_, width := utf8.DecodeRuneInString(s[position:])
				position += width
			} else {
				break
			}
		}
	} else if err != nil {
		return nil
	} else if sequential {
		for index, name := range re.SubexpNames() {
			if index > 0 && name != "" {
				names[name] = append(names[name], index)
			}
		}
		position := 0
		for position <= len(s) {
			loc := re.FindStringSubmatchIndex(s[position:])
			if len(loc) < 2 || loc[0] != 0 {
				break
			}
			for i := range loc {
				if loc[i] >= 0 {
					loc[i] += position
				}
			}
			locs = append(locs, loc)
			if !global {
				break
			}
			if loc[1] > position {
				position = loc[1]
			} else if position < len(s) {
				_, width := utf8.DecodeRuneInString(s[position:])
				position += width
			} else {
				break
			}
		}
	} else {
		for index, name := range re.SubexpNames() {
			if index > 0 && name != "" {
				names[name] = append(names[name], index)
			}
		}
		limit := -1
		if !global {
			limit = 1
		}
		locs = re.FindAllStringSubmatchIndex(s, limit)
		if global {
			locs = stringSubstituteAddSuppressedEmptyMatches(re, locs)
		}
	}
	matches := make([]stringSubstituteMatch, 0, len(locs))
	for _, loc := range locs {
		if loc == nil || len(loc) < 2 {
			continue
		}
		if loc[0] == len(s) && strings.HasSuffix(s, "\n") && strings.Contains(r.Pattern, "^") {
			continue
		}
		matches = append(matches, stringSubstituteRegexpMatch(s, loc, names))
	}
	return matches
}

func stringSubstituteStringMatch(source string, start, end int) stringSubstituteMatch {
	return stringSubstituteMatch{
		start: start, end: end, text: source[start:end],
		indices: []int{start, end}, matches: []string{source[start:end]},
	}
}

func stringSubstituteRegexpMatch(source string, indices []int, names map[string][]int) stringSubstituteMatch {
	copyIndices := append([]int(nil), indices...)
	return stringSubstituteMatch{
		start: indices[0], end: indices[1], text: source[indices[0]:indices[1]],
		indices: copyIndices, matches: regexpMatchesFromIndices(source, copyIndices), names: names,
	}
}

// regexp.FindAll intentionally suppresses an empty match immediately after a
// non-empty one. Ruby's substitution methods retain that boundary match.
func stringSubstituteAddSuppressedEmptyMatches(re *regexp.Regexp, locations [][]int) [][]int {
	empty := re.FindStringSubmatchIndex("")
	if len(empty) < 2 || empty[0] != 0 || empty[1] != 0 || len(locations) == 0 {
		return locations
	}
	result := make([][]int, 0, len(locations)*2)
	for index, location := range locations {
		result = append(result, location)
		if len(location) < 2 || location[1] <= location[0] {
			continue
		}
		if index+1 < len(locations) && len(locations[index+1]) >= 2 && locations[index+1][0] == location[1] {
			continue
		}
		boundary := append([]int(nil), empty...)
		for i := range boundary {
			if boundary[i] >= 0 {
				boundary[i] += location[1]
			}
		}
		result = append(result, boundary)
	}
	return result
}

func stringSubstituteApply(receiver, pattern *object.EmeraldValue, replacement string, replacementHash *object.EmeraldValue, global bool, hasBlock bool, bang bool) (string, string, bool, *object.EmeraldValue) {
	s := stringRawValue(receiver)
	resultEncoding := stringEncodingName(receiver)
	matches := stringSubstituteMatches(s, pattern, global)
	if len(matches) == 0 {
		setRegexpMatchGlobals(nil, "", nil)
		return s, resultEncoding, false, nil
	}
	var b strings.Builder
	last := 0
	original := s
	for _, m := range matches {
		if m.start < last {
			continue
		}
		b.WriteString(original[last:m.start])
		stringSubstituteSetMatchGlobalsForPattern(m, original, stringEncodingName(receiver), pattern)
		repl := stringSubstituteExpandReplacement(replacement, original, m)
		if hasBlock {
			before := stringRawValue(receiver)
			if stringSubstituteBlockSuppressesMatchGlobals(CurrentBlockValue()) {
				setRegexpMatchGlobals(nil, "", nil)
			}
			blockResult := CallBlockWithArgs(CurrentBlockValue(), stringWithEncoding(m.text, stringEncodingName(receiver)))
			stringSubstituteSetMatchGlobalsForPattern(m, original, stringEncodingName(receiver), pattern)
			if blockResult != nil && blockResult.Type == object.ValueException {
				return "", resultEncoding, false, blockResult
			}
			if LastBlockResult != nil {
				control := LastBlockResult
				LastBlockResult = nil
				return "", resultEncoding, false, control
			}
			if bang && stringRawValue(receiver) != before {
				return "", resultEncoding, false, NewRuntimeError("string modified")
			}
			text, errVal := toStringValue(blockResult)
			if errVal != nil {
				return "", resultEncoding, false, errVal
			}
			if errVal := stringSubstituteCheckReplacementEncoding(receiver, m.text, blockResult); errVal != nil {
				return "", resultEncoding, false, errVal
			}
			if stringHasNonASCIIByte(text) && !strings.EqualFold(stringEncodingName(blockResult), resultEncoding) {
				resultEncoding = stringEncodingName(blockResult)
			}
			repl = text
		} else if replacementHash != nil {
			value := stringSubstituteHashReplacement(replacementHash, m.text)
			stringSubstituteSetMatchGlobalsForPattern(m, original, stringEncodingName(receiver), pattern)
			text, errVal := toStringValue(value)
			if errVal != nil {
				return "", resultEncoding, false, errVal
			}
			repl = text
		}
		b.WriteString(repl)
		last = m.end
	}
	b.WriteString(original[last:])
	result := b.String()
	return result, resultEncoding, result != s || len(matches) > 0, nil
}

func stringSubstituteBlockSuppressesMatchGlobals(block *object.EmeraldValue) bool {
	if block == nil || block.Type != object.ValueProc {
		return false
	}
	proc, _ := block.Data.(*object.Proc)
	return proc != nil && proc.Native != nil
}

func stringSubstituteSetMatchGlobals(match stringSubstituteMatch, source, encoding string) {
	matchData := setRegexpMatchGlobalsWithContext(match.matches, source, match.indices, encoding)
	if data, ok := matchDataPayload(matchData); ok {
		data.Names = match.names
	}
}

func stringSubstituteSetMatchGlobalsForPattern(match stringSubstituteMatch, source, encoding string, pattern *object.EmeraldValue) {
	stringSubstituteSetMatchGlobals(match, source, encoding)
	if GetGlobalVariable == nil {
		return
	}
	matchData := GetGlobalVariable("$~")
	data, ok := matchDataPayload(matchData)
	if !ok || pattern == nil {
		return
	}
	if pattern.Type == object.ValueRegexp {
		data.Regexp = pattern
		return
	}
	if pattern.Type == object.ValueString {
		data.Regexp = &object.EmeraldValue{
			Type:   object.ValueRegexp,
			Data:   &object.RRegexp{Pattern: regexp.QuoteMeta(pattern.Data.(string))},
			Class:  R.Classes["Regexp"],
			Frozen: true,
		}
	}
}

func stringSubstituteExpandReplacement(replacement, source string, match stringSubstituteMatch) string {
	var result strings.Builder
	for i := 0; i < len(replacement); i++ {
		if replacement[i] != '\\' || i+1 >= len(replacement) {
			result.WriteByte(replacement[i])
			continue
		}
		i++
		switch escaped := replacement[i]; escaped {
		case '\\':
			result.WriteByte('\\')
		case '0', '&':
			result.WriteString(match.text)
		case '`':
			result.WriteString(source[:match.start])
		case '\'':
			result.WriteString(source[match.end:])
		case '+':
			for capture := len(match.matches) - 1; capture >= 1; capture-- {
				if len(match.indices) >= (capture+1)*2 && match.indices[capture*2] >= 0 {
					result.WriteString(match.matches[capture])
					break
				}
			}
		case '1', '2', '3', '4', '5', '6', '7', '8', '9':
			capture := int(escaped - '0')
			if capture < len(match.matches) && len(match.indices) >= (capture+1)*2 && match.indices[capture*2] >= 0 {
				result.WriteString(match.matches[capture])
			}
		case 'k':
			if i+1 < len(replacement) && replacement[i+1] == '<' {
				end := strings.IndexByte(replacement[i+2:], '>')
				if end >= 0 {
					name := replacement[i+2 : i+2+end]
					for _, capture := range match.names[name] {
						if capture < len(match.matches) && len(match.indices) >= (capture+1)*2 && match.indices[capture*2] >= 0 {
							result.WriteString(match.matches[capture])
						}
					}
					i += end + 2
					continue
				}
			}
			result.WriteString(`\k`)
		default:
			result.WriteByte('\\')
			result.WriteByte(escaped)
		}
	}
	return result.String()
}

func stringSubstituteHashReplacement(hashValue *object.EmeraldValue, matched string) *object.EmeraldValue {
	if hashValue == nil || hashValue.Type != object.ValueHash {
		return rubyString("")
	}
	return hashIndex(hashValue, rubyString(matched))
}

func stringSubstituteCheckReplacementEncoding(receiver *object.EmeraldValue, matched string, replacement *object.EmeraldValue) *object.EmeraldValue {
	if replacement == nil || replacement.Type != object.ValueString {
		return nil
	}
	replacementText := stringRawValue(replacement)
	if !stringHasNonASCIIByte(replacementText) {
		return nil
	}
	receiverEncoding := stringEncodingName(receiver)
	replacementEncoding := stringEncodingName(replacement)
	if strings.EqualFold(receiverEncoding, replacementEncoding) {
		return nil
	}
	if !stringHasNonASCIIByte(stringRawValue(receiver)) {
		return nil
	}
	if stringHasNonASCIIByte(matched) {
		return nil
	}
	return newRuntimeException(R.Classes["Encoding::CompatibilityError"], "incompatible encoding")
}

func stringSplit(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) > 2 {
		return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 0..2)", len(args)))
	}
	s := stringRawValue(receiver)
	if !stringValidForEncoding(s, stringEncodingName(receiver)) {
		return NewArgumentError("invalid byte sequence in " + stringEncodingName(receiver))
	}
	limit := int64(0)
	hasLimit := false
	if len(args) >= 2 {
		var ok bool
		limit, ok = valueToInteger(args[1])
		if !ok {
			return conversionTypeErrorToInteger(args[1])
		}
		if limit > math.MaxInt32 || limit < math.MinInt32 {
			return NewRangeError("integer out of range of int")
		}
		hasLimit = true
	}
	if hasLimit && limit == 1 {
		return stringSplitResult(receiver, []string{s})
	}
	if s == "" {
		return stringSplitResult(receiver, nil)
	}

	var parts []string
	trimTrailing := !hasLimit || limit == 0
	patternValue := (*object.EmeraldValue)(nil)
	if len(args) > 0 {
		patternValue = args[0]
	}
	if patternValue == nil || patternValue.Type == object.ValueNil {
		if GetGlobalVariable != nil {
			separator := GetGlobalVariable("$;")
			if separator != nil && separator.Type != object.ValueNil {
				if len(args) == 0 {
					fmt.Fprintln(os.Stderr, "warning: $; is set to non-nil value")
				}
				patternValue = separator
			}
		}
	}
	if patternValue == nil || patternValue.Type == object.ValueNil {
		parts = splitWhitespace(s, limit, hasLimit)
		return stringSplitResult(receiver, parts)
	}

	if patternValue.Type == object.ValueRegexp {
		pattern := patternValue.Data.(*object.RRegexp)
		if errVal := regexpMatchEncodingError(pattern, receiver); errVal != nil {
			return errVal
		}
		parts = splitByRegexpPattern(s, pattern, limit, hasLimit)
	} else {
		pattern, ok, viaToStr, errVal := evalCoerceToString(patternValue)
		if errVal != nil {
			return errVal
		}
		if !ok {
			return conversionTypeErrorToStringForMode(patternValue, viaToStr)
		}
		patternEncoding := defaultExternalEncoding
		if patternValue.Type == object.ValueString {
			patternEncoding = stringEncodingName(patternValue)
		}
		if !stringValidForEncoding(pattern, patternEncoding) {
			return NewArgumentError("invalid byte sequence in " + patternEncoding)
		}
		parts = splitByStringPattern(s, pattern, limit, hasLimit)
	}
	if trimTrailing {
		parts = trimTrailingEmptyStrings(parts)
	}
	return stringSplitResult(receiver, parts)
}

func stringSplitResult(receiver *object.EmeraldValue, parts []string) *object.EmeraldValue {
	result := make([]*object.EmeraldValue, len(parts))
	for i, p := range parts {
		result[i] = stringWithEncoding(p, stringEncodingName(receiver))
	}
	if BlockGivenCheck != nil && BlockGivenCheck() && CurrentBlockValue != nil && CurrentBlockValue() != nil && CallBlockWithArgs != nil {
		return stringYieldValues(receiver, result)
	}
	return &object.EmeraldValue{
		Type:  object.ValueArray,
		Data:  result,
		Class: R.Classes["Array"],
	}
}

func splitByStringPattern(s, delim string, limit int64, hasLimit bool) []string {
	if delim == " " {
		return splitWhitespace(s, limit, hasLimit)
	}
	if delim == "" {
		return splitCharacters(s, limit, hasLimit)
	}
	if hasLimit && limit > 0 {
		return strings.SplitN(s, delim, int(limit))
	}
	return strings.Split(s, delim)
}

func splitByRegexpPattern(s string, pattern *object.RRegexp, limit int64, hasLimit bool) []string {
	if pattern.Pattern == "" {
		return splitCharacters(s, limit, hasLimit)
	}
	locations, matchesEmpty, ok := stringSplitRegexpLocations(s, pattern)
	if !ok {
		return []string{s}
	}
	parts := make([]string, 0, len(locations)+1)
	last := 0
	fields := int64(0)
	for _, location := range locations {
		if len(location) < 2 || location[0] < last || location[1] < location[0] {
			continue
		}
		if hasLimit && limit > 0 && fields >= limit-1 {
			break
		}
		start, end := location[0], location[1]
		if start == end && start == last {
			continue
		}
		field := s[last:start]
		if field != "" || !matchesEmpty {
			parts = append(parts, field)
			fields++
		}
		for capture := 2; capture+1 < len(location); capture += 2 {
			if location[capture] >= 0 && location[capture+1] >= location[capture] {
				parts = append(parts, s[location[capture]:location[capture+1]])
			}
		}
		last = end
	}
	parts = append(parts, s[last:])
	return parts
}

func stringSplitRegexpLocations(source string, pattern *object.RRegexp) ([][]int, bool, bool) {
	compiledPattern := rubyRegexpCompilePattern(pattern)
	if re, err := regexp.Compile(compiledPattern); err == nil {
		empty := re.FindStringIndex("")
		return re.FindAllStringSubmatchIndex(source, -1), len(empty) == 2 && empty[0] == 0 && empty[1] == 0, true
	}
	locations := make([][]int, 0)
	offset := 0
	matchesEmpty := false
	for offset <= len(source) {
		location, handled, errorText := onigRegexpSearch(pattern.Pattern, source[offset:], pattern.Options)
		if !handled || errorText != "" {
			return nil, false, false
		}
		if len(location) < 2 {
			break
		}
		for index := range location {
			if location[index] >= 0 {
				location[index] += offset
			}
		}
		locations = append(locations, location)
		if location[0] == location[1] {
			matchesEmpty = true
			if location[1] >= len(source) {
				break
			}
			_, width := utf8.DecodeRuneInString(source[location[1]:])
			offset = location[1] + width
		} else {
			offset = location[1]
		}
	}
	return locations, matchesEmpty, true
}

func splitCharacters(s string, limit int64, hasLimit bool) []string {
	if !hasLimit || limit <= 0 {
		parts := make([]string, 0, len([]rune(s)))
		for _, r := range s {
			parts = append(parts, string(r))
		}
		if hasLimit && limit < 0 {
			parts = append(parts, "")
		}
		return parts
	}
	runes := []rune(s)
	if limit <= 1 || int(limit) >= len(runes)+1 {
		parts := make([]string, 0, len(runes)+1)
		for _, r := range runes {
			parts = append(parts, string(r))
		}
		if int(limit) > len(runes) {
			parts = append(parts, "")
		}
		return parts
	}
	parts := make([]string, 0, limit)
	for i := 0; i < int(limit)-1; i++ {
		parts = append(parts, string(runes[i]))
	}
	parts = append(parts, string(runes[int(limit)-1:]))
	return parts
}

func splitWhitespace(s string, limit int64, hasLimit bool) []string {
	isSpace := func(character byte) bool {
		return character == ' ' || character == '\t' || character == '\n' || character == '\r' || character == '\v' || character == '\f'
	}
	position := 0
	for position < len(s) && isSpace(s[position]) {
		position++
	}
	if position == len(s) {
		return nil
	}
	parts := make([]string, 0)
	for position < len(s) {
		if hasLimit && limit > 0 && len(parts) == int(limit)-1 {
			parts = append(parts, s[position:])
			return parts
		}
		start := position
		for position < len(s) && !isSpace(s[position]) {
			position++
		}
		parts = append(parts, s[start:position])
		if position == len(s) {
			return parts
		}
		for position < len(s) && isSpace(s[position]) {
			position++
		}
		if position == len(s) {
			if hasLimit && limit != 0 {
				parts = append(parts, "")
			}
			return parts
		}
	}
	return parts
}

func trimTrailingEmptyStrings(parts []string) []string {
	for len(parts) > 0 && parts[len(parts)-1] == "" {
		parts = parts[:len(parts)-1]
	}
	return parts
}

func legacyStringSplit(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	s := stringRawValue(receiver)
	delim := ","
	if len(args) > 0 {
		delim = args[0].Data.(string)
	}
	parts := strings.Split(s, delim)
	result := make([]*object.EmeraldValue, len(parts))
	for i, p := range parts {
		result[i] = &object.EmeraldValue{
			Type:  object.ValueString,
			Data:  p,
			Class: R.Classes["String"],
		}
	}
	return &object.EmeraldValue{
		Type:  object.ValueArray,
		Data:  result,
		Class: R.Classes["Array"],
	}
}

func stringLines(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return stringLineIteration(receiver, false, args...)
}

func stringEachLine(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return stringLineIteration(receiver, true, args...)
}

func stringLineIteration(receiver *object.EmeraldValue, enumeratorWithoutBlock bool, args ...*object.EmeraldValue) *object.EmeraldValue {
	positional := args
	chomp := false
	if len(positional) > 0 && positional[len(positional)-1] != nil && positional[len(positional)-1].Type == object.ValueHash {
		options := valueToHashMap(positional[len(positional)-1])
		if value, ok := hashLookup(options, rubySymbol("chomp")); ok {
			chomp = isTruthy(value)
		}
		positional = positional[:len(positional)-1]
	}
	if len(positional) > 1 {
		return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 0..1)", len(positional)))
	}
	separator := (*object.EmeraldValue)(nil)
	if len(positional) == 1 {
		separator = positional[0]
	} else if GetGlobalVariable != nil {
		separator = GetGlobalVariable("$/")
	}
	if separator == nil {
		separator = rubyString("\n")
	}
	separatorNil := separator.Type == object.ValueNil
	separatorText := ""
	if !separatorNil {
		raw, ok, viaToStr, errVal := evalCoerceToString(separator)
		if errVal != nil {
			return errVal
		}
		if !ok {
			return conversionTypeErrorToStringForMode(separator, viaToStr)
		}
		separatorText = raw
	}
	encoding := stringEncodingName(receiver)
	normalized := normalizeEncodingNameForIO(encoding)
	if normalized == "UTF-7" {
		return newRuntimeException(R.Classes["Encoding::ConverterNotFoundError"], "code converter not found")
	}
	source := stringRawValue(receiver)
	parts := stringLineParts(source, separatorText, separatorNil, !encodingIsASCICompatible(encoding))
	values := make([]*object.EmeraldValue, 0, len(parts))
	for _, part := range parts {
		if chomp {
			if separatorNil {
				// nil means no separator and therefore nothing to chomp.
			} else if separatorText == "\n" {
				part = stringRawValue(stringChomp(stringWithEncoding(part, encoding), rubyString("\n")))
			} else {
				part = strings.TrimSuffix(part, separatorText)
			}
		}
		values = append(values, stringWithEncoding(part, encoding))
	}
	hasBlock := BlockGivenCheck != nil && BlockGivenCheck() && CurrentBlockValue != nil && CurrentBlockValue() != nil && CallBlockWithArgs != nil
	if !hasBlock {
		generator := func() ([]*object.EmeraldValue, *object.EmeraldValue) { return values, nil }
		if enumeratorWithoutBlock {
			return newSizedValueGeneratorEnumerator(R.NilVal, generator)
		}
		return &object.EmeraldValue{Type: object.ValueArray, Data: values, Class: R.Classes["Array"]}
	}
	for _, value := range values {
		LastBlockResult = nil
		result := CallBlockWithArgs(CurrentBlockValue(), value)
		if result != nil && result.Type == object.ValueException {
			return result
		}
		if LastBlockResult != nil {
			control := LastBlockResult
			LastBlockResult = nil
			return control
		}
	}
	return receiver
}

func stringLineParts(source, separator string, separatorNil, unsplittableEncoding bool) []string {
	if source == "" {
		return nil
	}
	if separatorNil || unsplittableEncoding {
		return []string{source}
	}
	if separator == "" {
		parts := []string{}
		start := 0
		for start < len(source) {
			index := strings.Index(source[start:], "\n\n")
			if index < 0 {
				parts = append(parts, source[start:])
				break
			}
			end := start + index + 2
			for end < len(source) && source[end] == '\n' {
				end++
			}
			parts = append(parts, source[start:start+index+2])
			start = end
		}
		return parts
	}
	parts := []string{}
	start := 0
	for start < len(source) {
		index := strings.Index(source[start:], separator)
		if index < 0 {
			parts = append(parts, source[start:])
			break
		}
		end := start + index + len(separator)
		parts = append(parts, source[start:end])
		start = end
	}
	return parts
}

func stringChomp(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	s := stringRawValue(receiver)
	separator := (*object.EmeraldValue)(nil)
	if len(args) > 1 {
		return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 0..1)", len(args)))
	}
	if len(args) == 1 {
		separator = args[0]
	} else if GetGlobalVariable != nil {
		separator = GetGlobalVariable("$/")
	}
	if separator == nil {
		separator = rubyString("\n")
	}
	if separator.Type == object.ValueNil {
		return stringWithEncoding(s, stringEncodingName(receiver))
	}
	raw, ok, viaToStr, errVal := evalCoerceToString(separator)
	if errVal != nil {
		return errVal
	}
	if !ok {
		return conversionTypeErrorToStringForMode(separator, viaToStr)
	}
	if result, handled := stringChompNonASCIICompatible(receiver, s, raw); handled {
		return result
	}
	result := s
	switch raw {
	case "":
		for strings.HasSuffix(result, "\n") {
			result = strings.TrimSuffix(result, "\n")
			result = strings.TrimSuffix(result, "\r")
		}
	case "\n":
		if strings.HasSuffix(result, "\r\n") {
			result = strings.TrimSuffix(result, "\r\n")
		} else if strings.HasSuffix(result, "\n") {
			result = strings.TrimSuffix(result, "\n")
		} else if strings.HasSuffix(result, "\r") {
			result = strings.TrimSuffix(result, "\r")
		}
	default:
		result = strings.TrimSuffix(result, raw)
	}
	return stringWithEncoding(result, stringEncodingName(receiver))
}

func kernelGlobalChomp(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if GetGlobalVariable == nil {
		return R.NilVal
	}
	current := GetGlobalVariable("$_")
	if current == nil || current.Type != object.ValueString {
		return R.NilVal
	}
	result := stringChomp(current, args...)
	if result != nil && result.Type != object.ValueException {
		SetGlobalVariableIfAvailable("$_", result)
	}
	return result
}

func kernelGlobalChop(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 0 {
		return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 0)", len(args)))
	}
	if GetGlobalVariable == nil {
		return R.NilVal
	}
	current := GetGlobalVariable("$_")
	if current == nil || current.Type != object.ValueString {
		return R.NilVal
	}
	result := stringChop(current)
	if result != nil && result.Type != object.ValueException {
		SetGlobalVariableIfAvailable("$_", result)
	}
	return result
}

func stringChompNonASCIICompatible(receiver *object.EmeraldValue, source, separator string) (*object.EmeraldValue, bool) {
	encodingName := stringEncodingName(receiver)
	if encodingIsASCICompatible(encodingName) {
		return nil, false
	}
	encoding := stringTextEncoding(encodingName)
	if encoding == nil {
		return nil, false
	}
	decoded, _, err := transform.String(encoding.NewDecoder(), source)
	if err != nil {
		return nil, false
	}
	result := decoded
	switch separator {
	case "":
		for strings.HasSuffix(result, "\n") {
			result = strings.TrimSuffix(result, "\n")
			result = strings.TrimSuffix(result, "\r")
		}
	case "\n":
		if strings.HasSuffix(result, "\r\n") {
			result = strings.TrimSuffix(result, "\r\n")
		} else if strings.HasSuffix(result, "\n") {
			result = strings.TrimSuffix(result, "\n")
		} else if strings.HasSuffix(result, "\r") {
			result = strings.TrimSuffix(result, "\r")
		}
	default:
		result = strings.TrimSuffix(result, separator)
	}
	encoded, _, err := transform.String(encoding.NewEncoder(), result)
	if err != nil {
		return nil, false
	}
	return stringWithEncoding(encoded, encodingName), true
}

func stringChop(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	s := stringRawValue(receiver)
	if len(s) == 0 {
		return stringWithEncoding("", stringEncodingName(receiver))
	}
	if result, handled := stringChopNonASCIICompatible(receiver, s); handled {
		return result
	}
	if strings.HasSuffix(s, "\r\n") {
		return stringWithEncoding(s[:len(s)-2], stringEncodingName(receiver))
	}
	chunks := stringCharacterChunks(receiver)
	width := 1
	if len(chunks) > 0 {
		width = len(chunks[len(chunks)-1])
	}
	return stringWithEncoding(s[:len(s)-width], stringEncodingName(receiver))
}

func stringChopNonASCIICompatible(receiver *object.EmeraldValue, source string) (*object.EmeraldValue, bool) {
	encodingName := stringEncodingName(receiver)
	if encodingIsASCICompatible(encodingName) {
		return nil, false
	}
	encoding := stringTextEncoding(encodingName)
	if encoding == nil {
		return nil, false
	}
	decoded, _, err := transform.String(encoding.NewDecoder(), source)
	if err != nil || decoded == "" {
		return nil, false
	}
	if strings.HasSuffix(decoded, "\r\n") {
		decoded = strings.TrimSuffix(decoded, "\r\n")
	} else {
		_, width := utf8.DecodeLastRuneInString(decoded)
		decoded = decoded[:len(decoded)-width]
	}
	encoded, _, err := transform.String(encoding.NewEncoder(), decoded)
	if err != nil {
		return nil, false
	}
	return stringWithEncoding(encoded, encodingName), true
}

