func stringCoerceConcatenationString(value *object.EmeraldValue) (*object.EmeraldValue, *object.EmeraldValue) {
	raw, ok, viaToStr, errVal := evalCoerceToString(value)
	if errVal != nil {
		return nil, errVal
	}
	if !ok {
		return nil, conversionTypeErrorToStringForMode(value, viaToStr)
	}
	encoding := stringEncodingName(value)
	if value == nil || value.Type != object.ValueString {
		encoding = defaultExternalEncoding
	}
	return stringWithEncoding(raw, encoding), nil
}

func stringConcatenationValue(receiver, value *object.EmeraldValue) (*object.EmeraldValue, *object.EmeraldValue) {
	if value != nil && value.Type == object.ValueInteger {
		return stringIntegerConcatenationValue(receiver, value)
	}
	return stringCoerceConcatenationString(value)
}

func stringIntegerConcatenationValue(receiver, value *object.EmeraldValue) (*object.EmeraldValue, *object.EmeraldValue) {
	integer, ok := numericBigIntValue(value)
	if !ok || !integer.IsInt64() || integer.Sign() < 0 {
		return nil, NewRangeError("integer out of char range")
	}
	codepoint := integer.Int64()
	encoding := stringEncodingName(receiver)
	normalized := normalizedEncodingName(encoding)
	if normalized == "US_ASCII" && codepoint >= 128 && codepoint <= 255 {
		return stringWithEncoding(string([]byte{byte(codepoint)}), "BINARY"), nil
	}
	character := intChr(value, newEncodingValue(encoding))
	if character == nil || character.Type == object.ValueException {
		return nil, character
	}
	return character, nil
}

func stringPrepend(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver != nil && receiver.Frozen {
		return frozenError("can't modify frozen String")
	}
	values := make([]*object.EmeraldValue, 0, len(args))
	for _, arg := range args {
		value, errVal := stringCoerceConcatenationString(arg)
		if errVal != nil {
			return errVal
		}
		values = append(values, value)
	}
	prefix := stringWithEncoding("", stringEncodingName(receiver))
	for _, value := range values {
		encoding, errVal := StringConcatenationEncoding(prefix, value)
		if errVal != nil {
			return errVal
		}
		prefix.Data = stringRawValue(prefix) + stringRawValue(value)
		SetStringEncoding(prefix, encoding)
	}
	encoding, errVal := StringConcatenationEncoding(prefix, receiver)
	if errVal != nil {
		return errVal
	}
	receiver.Data = stringRawValue(prefix) + stringRawValue(receiver)
	SetStringEncoding(receiver, encoding)
	return receiver
}

