func stringPartitionDirection(receiver, separator *object.EmeraldValue, reverse bool) *object.EmeraldValue {
	source := stringRawValue(receiver)
	receiverEncoding := stringEncodingName(receiver)
	start, end := -1, -1
	middleEncoding := receiverEncoding
	if separator != nil && separator.Type == object.ValueRegexp {
		regexpData := separator.Data.(*object.RRegexp)
		if errVal := regexpMatchEncodingError(regexpData, receiver); errVal != nil {
			return errVal
		}
		matches := stringSubstituteMatches(source, separator, true)
		if reverse {
			matches = stringRightmostRegexpMatches(source, regexpData)
		}
		if len(matches) > 0 {
			selected := matches[0]
			if reverse {
				selected = matches[len(matches)-1]
			}
			start, end = selected.start, selected.end
			stringSubstituteSetMatchGlobals(selected, source, receiverEncoding)
		} else {
			setRegexpMatchGlobals(nil, "", nil)
		}
		middleEncoding = regexpEncodingName(regexpData)
	} else {
		value, errVal := stringCoerceConcatenationString(separator)
		if errVal != nil {
			return errVal
		}
		needle := stringRawValue(value)
		index := strings.Index(source, needle)
		if reverse {
			index = strings.LastIndex(source, needle)
		}
		if index >= 0 {
			start, end = index, index+len(needle)
		}
		middleEncoding = stringEncodingName(value)
	}
	values := make([]*object.EmeraldValue, 3)
	if start < 0 {
		if reverse {
			values[0] = stringWithEncoding("", receiverEncoding)
			values[1] = stringWithEncoding("", receiverEncoding)
			values[2] = stringWithEncoding(source, receiverEncoding)
		} else {
			values[0] = stringWithEncoding(source, receiverEncoding)
			values[1] = stringWithEncoding("", receiverEncoding)
			values[2] = stringWithEncoding("", receiverEncoding)
		}
	} else {
		values[0] = stringWithEncoding(source[:start], receiverEncoding)
		values[1] = stringWithEncoding(source[start:end], middleEncoding)
		values[2] = stringWithEncoding(source[end:], receiverEncoding)
	}
	return &object.EmeraldValue{Type: object.ValueArray, Data: values, Class: R.Classes["Array"]}
}

func stringRightmostRegexpMatches(source string, pattern *object.RRegexp) []stringSubstituteMatch {
	compiled := *pattern
	re, err := regexp.Compile(rubyRegexpCompilePattern(&compiled))
	if err != nil {
		return nil
	}
	names := make(map[string][]int)
	for index, name := range re.SubexpNames() {
		if index > 0 && name != "" {
			names[name] = append(names[name], index)
		}
	}
	var selected []int
	for offset := 0; offset <= len(source); {
		location := re.FindStringSubmatchIndex(source[offset:])
		if len(location) >= 2 && location[0] == 0 {
			selected = append([]int(nil), location...)
			for index := range selected {
				if selected[index] >= 0 {
					selected[index] += offset
				}
			}
		}
		if offset == len(source) {
			break
		}
		_, width := utf8.DecodeRuneInString(source[offset:])
		if width <= 0 {
			width = 1
		}
		offset += width
	}
	if selected == nil {
		return nil
	}
	return []stringSubstituteMatch{stringSubstituteRegexpMatch(source, selected, names)}
}

func stringIndexOf(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) < 1 {
		return R.NilVal
	}
	s := stringRawValue(receiver)
	arg := args[0]
	if arg == nil || arg.Type == object.ValueNil {
		return conversionTypeErrorToStringForMode(arg, false)
	}
	if arg.Type == object.ValueSymbol {
		return conversionTypeErrorToStringForMode(arg, false)
	}
	offset := 0
	if len(args) > 1 {
		var errVal *object.EmeraldValue
		offset, errVal = stringSliceIntegerArg(args[1])
		if errVal != nil {
			return errVal
		}
	}
	charCount := stringCharCount(s)
	if offset < 0 {
		offset = charCount + offset
	}
	if offset < 0 || offset > charCount {
		SetGlobalVariableIfAvailable("$~", R.NilVal)
		return R.NilVal
	}
	byteOffset, ok := stringCharByteIndex(s, offset)
	if !ok {
		return R.NilVal
	}
	switch v := arg.Data.(type) {
	case string:
		if errVal := stringIndexEncodingError(receiver, arg); errVal != nil {
			return errVal
		}
		idx := strings.Index(s[byteOffset:], v)
		if idx < 0 {
			return R.NilVal
		}
		return newInt(int64(stringByteIndexToCharIndex(s, byteOffset+idx)))
	case int64:
		return conversionTypeErrorToStringForMode(arg, false)
	case *object.RRegexp:
		if errValue := regexpMatchEncodingError(v, receiver); errValue != nil {
			return errValue
		}
		if errValue := stringIndexRegexpEncodingError(receiver, v); errValue != nil {
			return errValue
		}
		if v.Pattern == "$" {
			relative := strings.IndexByte(s[byteOffset:], '\n')
			byteIndex := len(s)
			if relative >= 0 {
				byteIndex = byteOffset + relative
			}
			SetGlobalVariableIfAvailable("$~", newMatchDataValue([]string{""}))
			return newInt(int64(stringByteIndexToCharIndex(s, byteIndex)))
		}
		pattern := rubyRegexpCompilePattern(v)
		if strings.Contains(pattern, `\G`) {
			pattern = strings.ReplaceAll(pattern, `\G`, `^`)
		}
		re, err := regexp.Compile(pattern)
		if err != nil {
			SetGlobalVariableIfAvailable("$~", R.NilVal)
			return R.NilVal
		}
		loc := regexpFindStringIndexForRubyMatch(re, pattern, s[byteOffset:])
		if loc == nil {
			SetGlobalVariableIfAvailable("$~", R.NilVal)
			return R.NilVal
		}
		matchText := s[byteOffset+loc[0] : byteOffset+loc[1]]
		SetGlobalVariableIfAvailable("$~", newMatchDataValue([]string{matchText}))
		return newInt(int64(stringByteIndexToCharIndex(s, byteOffset+loc[0])))
	}
	converted, convertedOK, _, coerceErr := evalCoerceToString(arg)
	if coerceErr != nil {
		return coerceErr
	}
	if !convertedOK {
		return conversionTypeErrorToStringForMode(arg, false)
	}
	if errVal := stringIndexEncodingError(receiver, arg); errVal != nil {
		return errVal
	}
	idx := strings.Index(s[byteOffset:], converted)
	if idx < 0 {
		return R.NilVal
	}
	return newInt(int64(stringByteIndexToCharIndex(s, byteOffset+idx)))
}

func stringIndexEncodingError(receiver, needle *object.EmeraldValue) *object.EmeraldValue {
	if receiver == nil || needle == nil || receiver.Type != object.ValueString || needle.Type != object.ValueString {
		return nil
	}
	receiverEncoding := stringEncodingName(receiver)
	needleEncoding := stringEncodingName(needle)
	if strings.EqualFold(receiverEncoding, needleEncoding) {
		return nil
	}
	if strings.EqualFold(needleEncoding, "US-ASCII") || strings.EqualFold(receiverEncoding, "US-ASCII") {
		return nil
	}
	if !strings.EqualFold(receiverEncoding, "UTF-8") && !strings.EqualFold(needleEncoding, "UTF-8") {
		return newRuntimeException(R.Classes["Encoding::CompatibilityError"], "incompatible character encodings: "+receiverEncoding+" and "+needleEncoding)
	}
	if !encodingIsASCICompatible(receiverEncoding) || !encodingIsASCICompatible(needleEncoding) {
		return newRuntimeException(R.Classes["Encoding::CompatibilityError"], "incompatible character encodings: "+receiverEncoding+" and "+needleEncoding)
	}
	if stringHasNonASCIIByte(stringRawValue(receiver)) || stringHasNonASCIIByte(stringRawValue(needle)) {
		return newRuntimeException(R.Classes["Encoding::CompatibilityError"], "incompatible character encodings: "+receiverEncoding+" and "+needleEncoding)
	}
	return nil
}

func stringIndexRegexpEncodingError(receiver *object.EmeraldValue, pattern *object.RRegexp) *object.EmeraldValue {
	if receiver == nil || receiver.Type != object.ValueString || pattern == nil {
		return nil
	}
	receiverEncoding := stringEncodingName(receiver)
	if patternEncoding, fixed := regexpFixedEncodingOption(pattern.Options); fixed {
		if strings.EqualFold(patternEncoding, receiverEncoding) || strings.EqualFold(patternEncoding, "US-ASCII") {
			return nil
		}
		if strings.EqualFold(receiverEncoding, "US-ASCII") && !stringHasNonASCIIByte(stringRawValue(receiver)) {
			return nil
		}
		return newRuntimeException(R.Classes["Encoding::CompatibilityError"], "incompatible encoding regexp match ("+patternEncoding+" regexp with "+receiverEncoding+" string)")
	}
	if strings.EqualFold(receiverEncoding, "UTF-8") || strings.EqualFold(receiverEncoding, "US-ASCII") {
		return nil
	}
	return newRuntimeException(R.Classes["Encoding::CompatibilityError"], "incompatible encoding")
}

func stringByteIndexToCharIndex(s string, byteIndex int) int {
	if byteIndex <= 0 {
		return 0
	}
	if byteIndex > len(s) {
		byteIndex = len(s)
	}
	return stringCharCount(s[:byteIndex])
}

func stringByteSlice(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 0 {
		return NewArgumentError("wrong number of arguments")
	}
	s := stringRawValue(receiver)
	encoding := stringEncodingName(receiver)
	if args[0] != nil && args[0].Type == object.ValueRange {
		if len(args) > 1 {
			return typeError("no implicit conversion of Range into Integer")
		}
		return stringByteSliceRange(s, encoding, args[0])
	}
	start, errVal := stringSliceIntegerArg(args[0])
	if errVal != nil {
		return errVal
	}
	length := 1
	if len(args) > 1 {
		length, errVal = stringSliceLengthArg(args[1])
		if errVal != nil {
			return errVal
		}
	}
	if length < 0 {
		return R.NilVal
	}
	if start < 0 {
		start += len(s)
	}
	if start < 0 || start > len(s) || start == len(s) && len(args) == 1 {
		return R.NilVal
	}
	end := start + length
	if end < start || end > len(s) {
		end = len(s)
	}
	return stringWithEncoding(s[start:end], encoding)
}

func stringGetByte(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 1 {
		return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 1)", len(args)))
	}
	index, ok := valueToInteger(args[0])
	if !ok {
		return typeError("no implicit conversion into Integer")
	}
	s := stringRawValue(receiver)
	if index < 0 {
		index += int64(len(s))
	}
	if index < 0 || index >= int64(len(s)) {
		return R.NilVal
	}
	return newInt(int64(s[index]))
}

func stringSetByte(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver != nil && receiver.Frozen {
		return frozenError("can't modify frozen String")
	}
	index, ok := valueToInteger(args[0])
	if !ok {
		return typeError("no implicit conversion into Integer")
	}
	value, ok := valueToInteger(args[1])
	if !ok {
		return typeError("no implicit conversion into Integer")
	}
	bytes := []byte(stringRawValue(receiver))
	if index < 0 {
		index += int64(len(bytes))
	}
	if index < 0 || index >= int64(len(bytes)) {
		return newRuntimeException(R.Classes["IndexError"], "index out of string")
	}
	bytes[index] = byte(value)
	receiver.Data = string(bytes)
	return newInt(value)
}

func stringAppendAsBytes(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver != nil && receiver.Frozen {
		return frozenError("can't modify frozen String")
	}
	bytes := append([]byte(nil), []byte(stringRawValue(receiver))...)
	modulus := big.NewInt(256)
	for _, arg := range args {
		if arg != nil && arg.Type == object.ValueString {
			bytes = append(bytes, []byte(stringRawValue(arg))...)
			continue
		}
		if integer, ok := numericBigIntValue(arg); ok {
			least := new(big.Int).Mod(integer, modulus)
			bytes = append(bytes, byte(least.Int64()))
			continue
		}
		typeName := "NilClass"
		if arg != nil {
			typeName = arg.TypeName()
			if arg.Class != nil && arg.Class.Name != "" {
				typeName = arg.Class.Name
			}
		}
		return typeError("wrong argument type " + typeName + " (expected String or Integer)")
	}
	receiver.Data = string(bytes)
	return receiver
}

func stringByteSliceRange(s, encoding string, value *object.EmeraldValue) *object.EmeraldValue {
	rangeObj, ok := value.Data.(*object.RRange)
	if !ok || rangeObj == nil {
		return R.NilVal
	}
	startOpen := rangeObj.StartMissing
	if startValue, ok := rangeObj.StartValue.(*object.EmeraldValue); ok && startValue != nil && startValue.Type == object.ValueNil {
		startOpen = true
	}
	endOpen := rangeObj.EndMissing
	if endValue, ok := rangeObj.EndValue.(*object.EmeraldValue); ok && endValue != nil && endValue.Type == object.ValueNil {
		endOpen = true
	}
	start := 0
	if !startOpen {
		var errVal *object.EmeraldValue
		start, errVal = arrayIndexIntArgRangeBoundaryChecked(rangeObj.StartValue, rangeObj.Start)
		if errVal != nil {
			return errVal
		}
	}
	if start < 0 {
		start += len(s)
	}
	end := len(s) - 1
	if !endOpen {
		var errVal *object.EmeraldValue
		end, errVal = arrayIndexIntArgRangeBoundaryChecked(rangeObj.EndValue, rangeObj.End)
		if errVal != nil {
			return errVal
		}
		if end < 0 {
			end += len(s)
		}
		if rangeObj.Exclusive {
			end--
		}
	}
	if start < 0 || start > len(s) {
		return R.NilVal
	}
	if end >= len(s) {
		end = len(s) - 1
	}
	if end < start || end < 0 {
		return stringWithEncoding("", encoding)
	}
	return stringWithEncoding(s[start:end+1], encoding)
}

func stringByteSplice(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver != nil && receiver.Frozen {
		return frozenError("can't modify frozen String: " + receiver.Inspect())
	}
	if len(args) < 2 {
		return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 2, 3, or 5)", len(args)))
	}
	receiverRange := args[0] != nil && args[0].Type == object.ValueRange
	if receiverRange && len(args) != 2 && len(args) != 3 || !receiverRange && len(args) != 3 && len(args) != 5 {
		if !receiverRange && len(args) == 2 {
			return typeError("wrong argument type Integer (expected Range)")
		}
		return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 2, 3, or 5)", len(args)))
	}
	replacementIndex := 2
	if receiverRange {
		replacementIndex = 1
	}
	replacement := args[replacementIndex]
	if replacement == nil || replacement.Type != object.ValueString {
		raw, converted, viaToStr, errVal := evalCoerceToString(replacement)
		if errVal != nil {
			return errVal
		}
		if !converted {
			return conversionTypeErrorToStringForMode(replacement, viaToStr)
		}
		replacement = rubyString(raw)
	}
	receiverStart, receiverEnd, errVal := stringByteSpliceSpan(receiver, args[0], func() *object.EmeraldValue {
		if receiverRange {
			return nil
		}
		return args[1]
	}(), receiverRange)
	if errVal != nil {
		return errVal
	}
	replacementStart, replacementEnd := 0, len(stringRawValue(replacement))
	if receiverRange && len(args) == 3 {
		if args[2] == nil || args[2].Type != object.ValueRange {
			return NewArgumentError("wrong number of arguments (given 3, expected 2, 3, or 5)")
		}
		replacementStart, replacementEnd, errVal = stringByteSpliceSpan(replacement, args[2], nil, true)
	} else if !receiverRange && len(args) == 5 {
		replacementStart, replacementEnd, errVal = stringByteSpliceSpan(replacement, args[3], args[4], false)
	}
	if errVal != nil {
		return errVal
	}
	replacementText := stringRawValue(replacement)[replacementStart:replacementEnd]
	replacementSlice := stringWithEncoding(replacementText, stringEncodingName(replacement))
	resultEncoding, encodingErr := StringConcatenationEncoding(receiver, replacementSlice)
	if encodingErr != nil {
		return encodingErr
	}
	original := stringRawValue(receiver)
	receiver.Data = original[:receiverStart] + replacementText + original[receiverEnd:]
	SetStringEncoding(receiver, resultEncoding)
	return receiver
}

func stringByteSpliceSpan(value *object.EmeraldValue, indexValue, lengthValue *object.EmeraldValue, isRange bool) (int, int, *object.EmeraldValue) {
	s := stringRawValue(value)
	if isRange {
		rangeObj, ok := indexValue.Data.(*object.RRange)
		if !ok || rangeObj == nil {
			return 0, 0, typeError("wrong argument type")
		}
		start := 0
		if !rangeObj.StartMissing {
			var errVal *object.EmeraldValue
			start, errVal = arrayIndexIntArgRangeBoundaryChecked(rangeObj.StartValue, rangeObj.Start)
			if errVal != nil {
				return 0, 0, errVal
			}
		}
		if start < -len(s) || start > len(s) {
			return 0, 0, NewRangeError(indexValue.Inspect() + " out of range")
		}
		if start < 0 {
			start += len(s)
		}
		end := len(s)
		if !rangeObj.EndMissing {
			var errVal *object.EmeraldValue
			end, errVal = arrayIndexIntArgRangeBoundaryChecked(rangeObj.EndValue, rangeObj.End)
			if errVal != nil {
				return 0, 0, errVal
			}
			if end < 0 {
				end += len(s)
			}
			if !rangeObj.Exclusive {
				end++
			}
		}
		if end < start {
			end = start
		}
		if end > len(s) {
			end = len(s)
		}
		if errVal := stringByteOffsetBoundaryError(value, s, start); errVal != nil {
			return 0, 0, errVal
		}
		if errVal := stringByteOffsetBoundaryError(value, s, end); errVal != nil {
			return 0, 0, errVal
		}
		return start, end, nil
	}
	start, errVal := stringSliceIntegerArg(indexValue)
	if errVal != nil {
		return 0, 0, errVal
	}
	length, errVal := stringSliceIntegerArg(lengthValue)
	if errVal != nil {
		return 0, 0, errVal
	}
	if start < -len(s) || start > len(s) {
		return 0, 0, newRuntimeException(R.Classes["IndexError"], fmt.Sprintf("index %d out of string", start))
	}
	if length < 0 {
		return 0, 0, newRuntimeException(R.Classes["IndexError"], fmt.Sprintf("negative length %d", length))
	}
	if start < 0 {
		start += len(s)
	}
	end := start + length
	if end < start || end > len(s) {
		end = len(s)
	}
	if errVal := stringByteOffsetBoundaryError(value, s, start); errVal != nil {
		return 0, 0, errVal
	}
	if errVal := stringByteOffsetBoundaryError(value, s, end); errVal != nil {
		return 0, 0, errVal
	}
	return start, end, nil
}

func stringByteIndexOf(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return stringByteSearch(receiver, false, args...)
}

func stringByteRIndexOf(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return stringByteSearch(receiver, true, args...)
}

func stringByteSearch(receiver *object.EmeraldValue, reverse bool, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 0 {
		return NewArgumentError("wrong number of arguments")
	}
	s := stringRawValue(receiver)
	offset := 0
	if reverse {
		offset = len(s)
	}
	if len(args) > 1 {
		parsed, ok := valueToInteger(args[1])
		if !ok {
			return typeError("no implicit conversion into Integer")
		}
		offset = int(parsed)
		if offset < 0 {
			offset += len(s)
		}
	}
	if reverse && offset > len(s) {
		offset = len(s)
	}
	if offset < 0 || offset > len(s) {
		SetGlobalVariableIfAvailable("$~", R.NilVal)
		return R.NilVal
	}
	if errVal := stringByteOffsetBoundaryError(receiver, s, offset); errVal != nil {
		return errVal
	}
	needle := args[0]
	if needle == nil || needle.Type == object.ValueNil || needle.Type == object.ValueSymbol || needle.Type == object.ValueInteger {
		return conversionTypeErrorToStringForMode(needle, false)
	}
	if needle.Type == object.ValueRegexp {
		pattern, ok := needle.Data.(*object.RRegexp)
		if !ok || pattern == nil {
			return R.NilVal
		}
		if errValue := regexpMatchEncodingError(pattern, receiver); errValue != nil {
			return errValue
		}
		if errValue := stringIndexRegexpEncodingError(receiver, pattern); errValue != nil {
			return errValue
		}
		return stringByteRegexpSearch(s, pattern, offset, reverse)
	}
	if needle.Type != object.ValueString {
		raw, converted, viaToStr, errVal := evalCoerceToString(needle)
		if errVal != nil {
			return errVal
		}
		if !converted {
			return conversionTypeErrorToStringForMode(needle, viaToStr)
		}
		needle = rubyString(raw)
	}
	if errVal := stringIndexEncodingError(receiver, needle); errVal != nil {
		return errVal
	}
	text := stringRawValue(needle)
	index := -1
	if reverse {
		for start := 0; start <= len(s); {
			relative := strings.Index(s[start:], text)
			if relative < 0 {
				break
			}
			candidate := start + relative
			if candidate > offset {
				break
			}
			index = candidate
			if text == "" {
				start = candidate + 1
			} else {
				start = candidate + 1
			}
		}
	} else if relative := strings.Index(s[offset:], text); relative >= 0 {
		index = offset + relative
	}
	if index < 0 {
		return R.NilVal
	}
	return newInt(int64(index))
}

func stringByteOffsetBoundaryError(receiver *object.EmeraldValue, s string, offset int) *object.EmeraldValue {
	if offset <= 0 || offset >= len(s) {
		return nil
	}
	encoding := normalizedEncodingName(stringEncodingName(receiver))
	if encoding == "UTF_8" && !utf8.RuneStart(s[offset]) {
		return newRuntimeException(R.Classes["IndexError"], fmt.Sprintf("offset %d does not land on character boundary", offset))
	}
	return nil
}

func stringByteRegexpSearch(s string, pattern *object.RRegexp, offset int, reverse bool) *object.EmeraldValue {
	compiledPattern := rubyRegexpCompilePattern(pattern)
	if strings.Contains(compiledPattern, `\G`) {
		compiledPattern = strings.ReplaceAll(compiledPattern, `\G`, `^`)
	}
	re, err := regexp.Compile(compiledPattern)
	if err != nil {
		SetGlobalVariableIfAvailable("$~", R.NilVal)
		return R.NilVal
	}
	index := -1
	end := -1
	if reverse {
		usesAbsoluteAnchor := strings.Contains(compiledPattern, "^") || strings.Contains(compiledPattern, `\A`) ||
			strings.Contains(compiledPattern, `\z`) || strings.Contains(compiledPattern, `\Z`)
		if usesAbsoluteAnchor {
			for _, location := range re.FindAllStringIndex(s, -1) {
				if location[0] <= offset {
					index, end = location[0], location[1]
				}
			}
		} else {
			for start := 0; start <= offset && start <= len(s); start++ {
				if start < len(s) && !utf8.RuneStart(s[start]) {
					continue
				}
				location := regexpFindStringIndexForRubyMatch(re, compiledPattern, s[start:])
				if location != nil && location[0] == 0 {
					index, end = start, start+location[1]
				}
			}
		}
	} else {
		location := regexpFindStringIndexForRubyMatch(re, compiledPattern, s[offset:])
		if location != nil {
			index, end = offset+location[0], offset+location[1]
		}
	}
	if index < 0 {
		SetGlobalVariableIfAvailable("$~", R.NilVal)
		return R.NilVal
	}
	SetGlobalVariableIfAvailable("$~", newMatchDataValue([]string{s[index:end]}))
	return newInt(int64(index))
}

func stringRIndexOf(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 0 {
		return NewArgumentError("wrong number of arguments")
	}
	s := stringRawValue(receiver)
	charOffset := stringCharCount(s)
	if len(args) > 1 {
		parsed, ok := valueToInteger(args[1])
		if !ok {
			return typeError("no implicit conversion into Integer")
		}
		charOffset = int(parsed)
		if charOffset < 0 {
			charOffset += stringCharCount(s)
		}
	}
	if charOffset < 0 {
		SetGlobalVariableIfAvailable("$~", R.NilVal)
		return R.NilVal
	}
	charCount := stringCharCount(s)
	if charOffset > charCount {
		charOffset = charCount
	}
	byteOffset, ok := stringCharByteIndex(s, charOffset)
	if !ok {
		return R.NilVal
	}
	result := stringByteSearch(receiver, true, args[0], newInt(int64(byteOffset)))
	if result == nil || result.Type != object.ValueInteger {
		return result
	}
	return newInt(int64(stringByteIndexToCharIndex(s, int(result.Data.(int64)))))
}

func stringOrd(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	s := stringRawValue(receiver)
	if len(s) == 0 {
		return NewArgumentError("empty string")
	}
	encoding := normalizedEncodingName(stringEncodingName(receiver))
	if encoding == "US_ASCII" && s[0] >= 0x80 {
		return NewArgumentError("invalid byte sequence in US-ASCII")
	}
	if encoding == "BINARY" || encoding == "ASCII_8BIT" || encoding == "US_ASCII" {
		return newInt(int64(s[0]))
	}
	r, width := utf8.DecodeRuneInString(s)
	if r == utf8.RuneError && width == 1 {
		return NewArgumentError("invalid byte sequence in " + stringEncodingName(receiver))
	}
	return newInt(int64(r))
}

func stringChr(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	s := stringRawValue(receiver)
	if len(s) == 0 {
		return stringWithEncoding("", stringEncodingName(receiver))
	}
	encoding := normalizedEncodingName(stringEncodingName(receiver))
	width := 1
	if encoding != "BINARY" && encoding != "ASCII_8BIT" && encoding != "US_ASCII" {
		_, width = utf8.DecodeRuneInString(s)
		if width <= 0 {
			width = 1
		}
	}
	return stringWithEncoding(s[:width], stringEncodingName(receiver))
}

func stringUplus(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver != nil && (receiver.Frozen || receiver.Chilled) {
		result := duplicateStringValue(receiver, false, false)
		result.Chilled = false
		result.Literal = false
		return result
	}
	return receiver
}

func stringUminus(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	result := stringWithEncoding(stringRawValue(receiver), stringEncodingName(receiver))
	result.Frozen = true
	return result
}

func stringDedup(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver.Frozen && len(auxiliaryInstanceVars[receiver]) > 0 {
		return receiver
	}
	if !receiver.Frozen {
		receiver = duplicateStringValue(receiver, true, false)
		receiver.Chilled = false
		receiver.Literal = false
	}
	return deduplicateFrozenString(receiver)
}

func deduplicateFrozenString(receiver *object.EmeraldValue) *object.EmeraldValue {
	key := stringEncodingName(receiver) + "\x00" + stringRawValue(receiver)
	if canonical := deduplicatedStrings[key]; canonical != nil {
		return canonical
	}
	deduplicatedStrings[key] = receiver
	return receiver
}

func stringSucc(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	bytes := []byte(stringRawValue(receiver))
	if len(bytes) == 0 {
		return stringWithEncoding("", stringEncodingName(receiver))
	}
	rightmostAlphaNumeric := -1
	for index := len(bytes) - 1; index >= 0; index-- {
		if isASCIIAlphaNumeric(bytes[index]) {
			rightmostAlphaNumeric = index
			break
		}
	}
	if rightmostAlphaNumeric < 0 {
		carry := true
		for index := len(bytes) - 1; index >= 0 && carry; index-- {
			if bytes[index] == 0xff {
				bytes[index] = 0
				continue
			}
			bytes[index]++
			carry = false
		}
		if carry {
			bytes = append([]byte{1}, bytes...)
		}
		return stringWithEncoding(string(bytes), stringEncodingName(receiver))
	}
	insertAt := rightmostAlphaNumeric
	insert := byte(0)
	carry := true
	for index := rightmostAlphaNumeric; index >= 0 && carry; index-- {
		character := bytes[index]
		if !isASCIIAlphaNumeric(character) {
			continue
		}
		insertAt = index
		switch {
		case character >= '0' && character <= '8':
			bytes[index]++
			carry = false
		case character == '9':
			bytes[index] = '0'
			insert = '1'
		case character >= 'a' && character <= 'y':
			bytes[index]++
			carry = false
		case character == 'z':
			bytes[index] = 'a'
			insert = 'a'
		case character >= 'A' && character <= 'Y':
			bytes[index]++
			carry = false
		case character == 'Z':
			bytes[index] = 'A'
			insert = 'A'
		}
	}
	if carry {
		bytes = append(bytes, 0)
		copy(bytes[insertAt+1:], bytes[insertAt:])
		bytes[insertAt] = insert
	}
	return stringWithEncoding(string(bytes), stringEncodingName(receiver))
}

func isASCIIAlphaNumeric(character byte) bool {
	return character >= '0' && character <= '9' || character >= 'a' && character <= 'z' || character >= 'A' && character <= 'Z'
}

func stringSuccBang(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver != nil && receiver.Frozen {
		return frozenError("can't modify frozen String")
	}
	result := stringSucc(receiver)
	receiver.Data = stringRawValue(result)
	return receiver
}

func stringUpto(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) < 1 || len(args) > 2 {
		return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 1..2)", len(args)))
	}
	stop, errVal := stringCoerceConcatenationString(args[0])
	if errVal != nil {
		return errVal
	}
	if _, compatibilityErr := StringConcatenationEncoding(receiver, stop); compatibilityErr != nil {
		return compatibilityErr
	}
	exclusive := len(args) == 2 && isTruthy(args[1])
	generator := func() ([]*object.EmeraldValue, *object.EmeraldValue) {
		return stringUptoValues(receiver, stop, exclusive), nil
	}
	if BlockGivenCheck == nil || !BlockGivenCheck() || CurrentBlockValue == nil || CurrentBlockValue() == nil || CallBlockWithArgs == nil {
		return newSizedValueGeneratorEnumerator(R.NilVal, generator)
	}
	values, _ := generator()
	for _, value := range values {
		LastBlockResult = nil
		result := CallBlockWithArgs(CurrentBlockValue(), value)
		if result != nil && result.Type == object.ValueException {
			return result
		}
		if LastBlockResult != nil {
			control := LastBlockResult
			LastBlockResult = nil
			return control
		}
	}
	return receiver
}

func stringUptoValues(startValue, stopValue *object.EmeraldValue, exclusive bool) []*object.EmeraldValue {
	start := stringRawValue(startValue)
	stop := stringRawValue(stopValue)
	encoding := stringEncodingName(startValue)
	values := []*object.EmeraldValue{}
	if stringIsDecimalDigits(start) && stringIsDecimalDigits(stop) && (len(start) > 1 || len(stop) > 1) {
		current, _ := new(big.Int).SetString(start, 10)
		end, _ := new(big.Int).SetString(stop, 10)
		for current.Cmp(end) <= 0 {
			if exclusive && current.Cmp(end) == 0 {
				break
			}
			values = append(values, stringWithEncoding(current.String(), encoding))
			current = new(big.Int).Add(current, big.NewInt(1))
		}
		return values
	}
	startRunes := []rune(start)
	stopRunes := []rune(stop)
	if len(startRunes) == 1 && len(stopRunes) == 1 {
		for current := startRunes[0]; current <= stopRunes[0]; current++ {
			if exclusive && current == stopRunes[0] {
				break
			}
			values = append(values, stringWithEncoding(string(current), encoding))
			if current == utf8.MaxRune {
				break
			}
		}
		return values
	}
	if len([]rune(start)) > len([]rune(stop)) || strings.Compare(start, stop) > 0 {
		return values
	}
	current := stringWithEncoding(start, encoding)
	stopCharacters := len([]rune(stop))
	for iterations := 0; iterations < 10_000_000; iterations++ {
		text := stringRawValue(current)
		if len([]rune(text)) > stopCharacters || strings.Compare(text, stop) > 0 {
			break
		}
		if !exclusive || text != stop {
			values = append(values, stringWithEncoding(text, encoding))
		}
		if text == stop {
			break
		}
		next := stringSucc(current)
		if stringRawValue(next) == text {
			break
		}
		current = next
	}
	return values
}

func stringIsDecimalDigits(value string) bool {
	if value == "" {
		return false
	}
	for index := range value {
		if value[index] < '0' || value[index] > '9' {
			return false
		}
	}
	return true
}

func arrayMin(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return arrayMinMax(receiver, true)
}

func hashDig(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 0 {
		return NewArgumentError("wrong number of arguments")
	}
	value := hashIndex(receiver, args[0])
	if value == nil || value.Type == object.ValueException {
		return value
	}
	if len(args) == 1 || value.Type == object.ValueNil {
		return value
	}
	if CallMethod == nil || !receiverHasCallableMethod(value, "dig") {
		return typeError(value.TypeName() + " does not have #dig method")
	}
	result := CallMethod(value, "dig", args[1:]...)
	if result == nil {
		return R.NilVal
	}
	return result
}

func hashMergeBang(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver != nil && receiver.Frozen {
		return frozenError("can't modify frozen Hash")
	}
	if len(args) < 1 {
		return receiver
	}
	if receiver == envObject {
		return envMergeBang(receiver, args...)
	}
	target := hashData(receiver)
	if target == nil {
		return receiver
	}
	for _, arg := range args {
		if errVal := hashMergeInto(target, arg); errVal != nil {
			return errVal
		}
	}
	return receiver
}

func envMergeBang(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	target := hashData(receiver)
	if target == nil {
		return receiver
	}
	for _, arg := range args {
		other := valueToHashMap(arg)
		if other == nil {
			continue
		}
		keys, _ := hashOrderedKeysFromValue(arg)
		keys = append(keys, keysNotInOrder(other, keys)...)
		for _, rawKey := range keys {
			rawValue, ok := other[rawKey]
			if !ok {
				if foundKey, foundValue, found := hashFindKeyValue(other, rawKey, false); found {
					rawKey = foundKey
					rawValue = foundValue
					ok = true
				}
			}
			if !ok {
				continue
			}
			keyText, errVal := envCoerceKey(rawKey)
			if errVal != nil {
				return errVal
			}
			key := rubyString(keyText)
			value := rawValue
			if _, oldValue, found := hashFindKeyValue(target.Pairs, key, false); found && BlockGivenCheck != nil && BlockGivenCheck() && CallBlock != nil {
				value = CallBlock(key, oldValue, rawValue)
				if value != nil && value.Type == object.ValueException {
					return value
				}
			}
			if result := hashIndexSet(receiver, key, value); result != nil && result.Type == object.ValueException {
				return result
			}
		}
	}
	return receiver
}

func hashMergeInto(target *object.RHash, arg *object.EmeraldValue) *object.EmeraldValue {
	other := valueToHashMap(arg)
	if other == nil {
		return nil
	}
	keys, _ := hashOrderedKeysFromValue(arg)
	for _, key := range keys {
		value, ok := other[key]
		if !ok {
			for candidate, candidateValue := range other {
				if candidate.Equals(key) {
					key = candidate
					value = candidateValue
					ok = true
					break
				}
			}
		}
		if !ok {
			continue
		}
		existingKey, existingValue, found := hashFindKeyValue(target.Pairs, key, target.CompareByIdentity)
		if found {
			if BlockGivenCheck != nil && BlockGivenCheck() && CallBlock != nil {
				value = CallBlock(existingKey, existingValue, value)
			}
			target.Pairs[existingKey] = value
			continue
		}
		target.Pairs[key] = value
		target.Keys = append(target.Keys, key)
	}
	for _, key := range keysNotInOrder(other, keys) {
		value := other[key]
		existingKey, existingValue, found := hashFindKeyValue(target.Pairs, key, target.CompareByIdentity)
		if found {
			if BlockGivenCheck != nil && BlockGivenCheck() && CallBlock != nil {
				value = CallBlock(existingKey, existingValue, value)
			}
			target.Pairs[existingKey] = value
			continue
		}
		target.Pairs[key] = value
		target.Keys = append(target.Keys, key)
	}
	return nil
}

func keysNotInOrder(hash map[*object.EmeraldValue]*object.EmeraldValue, keys []*object.EmeraldValue) []*object.EmeraldValue {
	missing := []*object.EmeraldValue{}
	for key := range hash {
		found := false
		for _, existing := range keys {
			if existing == key || existing.Equals(key) {
				found = true
				break
			}
		}
		if !found {
			missing = append(missing, key)
		}
	}
	return missing
}

func hashFindKeyValue(hash map[*object.EmeraldValue]*object.EmeraldValue, key *object.EmeraldValue, byIdentity bool) (*object.EmeraldValue, *object.EmeraldValue, bool) {
	if byIdentity {
		identityKey := hashIdentityKey(key)
		if value, ok := hash[identityKey]; ok {
			return identityKey, value, true
		}
		return nil, nil, false
	}
	keyHash := hashKeyCode(key)
	for candidate, value := range hash {
		if candidate == key {
			return candidate, value, true
		}
		if hashKeyCode(candidate) == keyHash && hashKeysEql(candidate, key) {
			return candidate, value, true
		}
	}
	return nil, nil, false
}

func hashInvert(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	keys, pairs := hashOrderedKeysFromValue(receiver)
	result := emptyHashValue()
	for _, key := range keys {
		if value, ok := pairs[key]; ok {
			hashIndexSet(result, value, key)
		}
	}
	return result
}

func builtinLoop(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if BlockGivenCheck == nil || !BlockGivenCheck() || CallBlock == nil {
		return newLoopEnumerator()
	}
	if os.Getenv("RGO_DEBUG_ENUM") == "1" {
		fmt.Printf("builtinLoop enter blockGiven=%v\n", BlockGivenCheck())
	}
	iterations := 0
	for {
		LastException = nil
		LastBlockResult = nil
		CallBlock()
		iterations++
		if enumeratorLimitAbort {
			return R.NilVal
		}
		if os.Getenv("RGO_DEBUG_ENUM") == "1" {
			if LastException == nil {
				fmt.Println("builtinLoop after call: no exception")
			} else {
				fmt.Printf("builtinLoop after call: exception=%s\n", LastException.Inspect())
			}
		}
		if LastException != nil {
			if os.Getenv("RGO_DEBUG_ENUM") == "1" {
				exc := LastException
				r := exc.Data.(*object.RException)
				fmt.Printf("builtinLoop handling exception class=%s resultNil=%v\n", exc.Class.Name, r.Result == nil)
			}
			if classInheritsFrom(LastException.Class, R.Classes["StopIteration"]) {
				exc := LastException.Data.(*object.RException)
				LastException = nil
				if os.Getenv("RGO_DEBUG_ENUM") == "1" {
					if exc.Result == nil {
						fmt.Println("builtinLoop stop result=nil")
					} else {
						fmt.Printf("builtinLoop stop result=%s\n", exc.Result.Inspect())
					}
				}
				if exc.Result != nil {
					return exc.Result
				}
				return R.NilVal
			}
			return LastException
		}
		if LastBlockResult != nil {
			result := LastBlockResult
			LastBlockResult = nil
			return result
		}
		if loopRunningInBoundedContext() && iterations >= 1 {
			return R.NilVal
		}
	}
}

func loopRunningInBoundedContext() bool {
	if InThreadBlock != nil && InThreadBlock() {
		return true
	}
	if currentFiber == nil {
		return false
	}
	data, ok := currentFiber.Data.(*fiberData)
	return ok && data != nil && data.block != nil
}

func classInheritsFrom(cls, target *object.Class) bool {
	if cls == nil || target == nil {
		return false
	}
	for current := cls; current != nil; current = current.SuperClass {
		if current == target || (current.Name != "" && current.Name == target.Name) {
			return true
		}
	}
	return false
}

func builtinExit(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	status, err := exitStatusFromArgs(args...)
	if err != nil {
		return err
	}
	exc := newSystemExit("exit", status)
	if exception, ok := exc.Data.(*object.RException); ok && exception != nil {
		exception.Raised = true
	}
	LastException = exc
	return exc
}

func builtinExitBang(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	status, err := exitStatusFromArgs(args...)
	if err != nil {
		return err
	}
	if processForkNoBlockStatus != nil {
		*processForkNoBlockStatus = status
		processForkNoBlockStatus = nil
		if SetGlobalVariable != nil {
			SetGlobalVariable("$?", newProcessStatus(-1, &status, nil))
		}
		return R.NilVal
	}
	if processForkExitBangStatus != nil {
		*processForkExitBangStatus = status
		return newSystemExit("exit!", status)
	}
	if SetGlobalVariable != nil {
		SetGlobalVariable("$?", newProcessStatus(-1, &status, nil))
	}
	if !InAtExitHooks {
		skipAtExitHooks = true
	}
	return newSystemExit("exit!", status)
}

func builtinSleep(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) > 1 {
		return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 0..1)", len(args)))
	}
	duration := 0.0
	if len(args) == 1 && args[0] != nil && args[0].Type != object.ValueNil {
		parsedDuration, errVal := sleepDurationSeconds(args[0])
		if errVal != nil {
			return errVal
		}
		if parsedDuration < 0 {
			return NewArgumentError("time interval must not be negative")
		}
		duration = parsedDuration
	}
	if currentFiber != nil {
		if fiber, ok := currentFiber.Data.(*fiberData); ok && fiber != nil && fiber.block != nil && !fiber.blocking {
			if thread := threadValueData(threadClassCurrent(nil)); thread != nil && thread.scheduler != nil && CallMethod != nil {
				result := CallMethod(thread.scheduler, "kernel_sleep", args...)
				if result != nil && result.Type == object.ValueException {
					return result
				}
				return newInt(0)
			}
		}
	}
	if len(args) == 0 && os.Getenv("RGO_REAL_SLEEP") == "1" {
		current := threadClassCurrent(nil)
		if currentData := threadValueData(current); currentData == nil || currentData.block == nil {
			select {}
		}
	}
	if len(args) == 0 {
		kernelSleepNoArgsObserved = true
	}
	previousException := LastException
	current := threadClassCurrent(nil)
	if currentData := threadValueData(current); currentData != nil {
		currentData.stopped = true
	}
	if !threadOwnsLoadingFeature(current) {
		runAllPendingThreads()
	}
	if currentData := threadValueData(current); currentData != nil {
		currentData.stopped = false
	}
	if LastException != nil && LastException != previousException {
		exception := LastException
		LastException = nil
		return exception
	}
	if len(args) == 0 {
		if currentData := threadValueData(current); currentData != nil {
			currentData.stopped = true
			currentData.blockedLabel = "sleep"
			if currentData.block != nil && SuspendCurrentThread != nil {
				result := SuspendCurrentThread()
				currentData.stopped = false
				currentData.blockedLabel = ""
				if result != nil && result.Type == object.ValueException {
					return result
				}
				return newInt(0)
			}
		}
		return threadBlockedResult
	}
	if duration > 0 {
		time.Sleep(time.Duration(duration * float64(time.Second)))
	}
	return newInt(0)
}

func threadOwnsLoadingFeature(thread *object.EmeraldValue) bool {
	if thread == nil {
		return false
	}
	for path, loading := range loadingFeatures {
		if loading && loadingFeatureOwners[path] == thread {
			return true
		}
	}
	return false
}

func sleepDurationSeconds(value *object.EmeraldValue) (float64, *object.EmeraldValue) {
	if value == nil || value.Type == object.ValueNil {
		return 0, nil
	}
	if value.Type == object.ValueString || value.Type == object.ValueSymbol {
		return 0, typeError("no implicit conversion to float from " + value.TypeName())
	}
	switch v := value.Data.(type) {
	case int64:
		return float64(v), nil
	case float64:
		return v, nil
	}
	if CallMethod != nil && value.Class != nil && receiverHasCallableMethod(value, "divmod") {
		divmod := CallMethod(value, "divmod", newInt(1))
		if divmod != nil && divmod.Type == object.ValueException {
			return 0, divmod
		}
		parts, ok := valueToArray(divmod)
		if ok && len(parts) >= 2 {
			whole, wholeErr := valueToFloat(parts[0])
			if wholeErr != nil {
				return 0, wholeErr
			}
			fraction, fractionErr := valueToFloat(parts[1])
			if fractionErr != nil {
				return 0, fractionErr
			}
			return whole + fraction, nil
		}
	}
	return valueToFloat(value)
}

func installSecureRandomModule(objectClass *object.Class) {
	klass := object.NewClass("SecureRandom")
	klass.SuperClass = objectClass
	klass.DefineClassMethod("bytes", &object.Method{Name: "bytes", Fn: secureRandomBytes, Arity: -1})
	klass.DefineClassMethod("random_bytes", &object.Method{Name: "random_bytes", Fn: secureRandomBytes, Arity: -1})
	klass.DefineClassMethod("hex", &object.Method{Name: "hex", Fn: secureRandomHex, Arity: -1})
	klass.DefineClassMethod("base64", &object.Method{Name: "base64", Fn: secureRandomBase64, Arity: -1})
	klass.DefineClassMethod("random_number", &object.Method{Name: "random_number", Fn: secureRandomNumber, Arity: -1})
	klass.DefineClassMethod("rand", &object.Method{Name: "rand", Fn: secureRandomNumber, Arity: -1})
	R.Classes["SecureRandom"] = klass
	classValue := &object.EmeraldValue{Type: object.ValueClass, Data: klass, Class: R.Classes["Class"]}
	objectClass.DefineConstant("SecureRandom", classValue)
	AssignConstantName(&object.EmeraldValue{Type: object.ValueClass, Data: objectClass, Class: R.Classes["Class"]}, "SecureRandom", classValue)
}

func installRandomClass(objectClass *object.Class) {
	randomClass := object.NewClass("Random")
	randomClass.SuperClass = objectClass
	randomClass.DefineMethod("initialize", &object.Method{Name: "initialize", Fn: randomInitialize, Arity: -1, Visibility: "private"})
	randomClass.DefineMethod("rand", &object.Method{Name: "rand", Fn: randomRand, Arity: -1})
	randomClass.DefineMethod("random_number", &object.Method{Name: "random_number", Fn: randomRand, Arity: -1})
	randomClass.DefineMethod("bytes", &object.Method{Name: "bytes", Fn: randomBytes, Arity: 1})
	randomClass.DefineMethod("seed", &object.Method{Name: "seed", Fn: randomSeed, Arity: 0})
	randomClass.DefineMethod("state", &object.Method{Name: "state", Fn: randomState, Arity: 0, Visibility: "private"})
	randomClass.DefineMethod("==", &object.Method{Name: "==", Fn: randomEqual, Arity: 1})
	randomClass.DefineMethod("marshal_dump", &object.Method{Name: "marshal_dump", Fn: randomMarshalDump, Arity: 0})
	randomClass.DefineMethod("marshal_load", &object.Method{Name: "marshal_load", Fn: randomMarshalLoad, Arity: 1})
	randomClass.DefineClassMethod("rand", &object.Method{Name: "rand", Fn: builtinRand, Arity: -1})
	randomClass.DefineClassMethod("random_number", &object.Method{Name: "random_number", Fn: builtinRand, Arity: -1})
	randomClass.DefineClassMethod("srand", &object.Method{Name: "srand", Fn: builtinSrand, Arity: -1})
	randomClass.DefineClassMethod("new_seed", &object.Method{Name: "new_seed", Fn: randomClassNewSeed, Arity: 0})
	randomClass.DefineClassMethod("bytes", &object.Method{Name: "bytes", Fn: randomClassBytes, Arity: 1})
	randomClass.DefineClassMethod("urandom", &object.Method{Name: "urandom", Fn: randomClassURandom, Arity: 1})
	R.Classes["Random"] = randomClass
	value := &object.EmeraldValue{Type: object.ValueClass, Data: randomClass, Class: R.Classes["Class"]}
	objectClass.DefineConstant("Random", value)
	AssignConstantName(&object.EmeraldValue{Type: object.ValueClass, Data: objectClass, Class: R.Classes["Class"]}, "Random", value)
}

func randomInitialize(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) > 1 {
		return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 0..1)", len(args)))
	}
	seed := randomNewSeedBigInt()
	if len(args) == 1 {
		var errVal *object.EmeraldValue
		seed, errVal = randomSeedBigInt(args[0])
		if errVal != nil {
			return errVal
		}
	}
	receiver.Data = newRandomData(seed)
	return receiver
}

func randomRand(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data, ok := receiver.Data.(*randomData)
	if !ok || data.mt == nil {
		return typeError("uninitialized Random")
	}
	if len(args) == 0 || args[0] == nil || args[0].Type == object.ValueNil {
		return newFloat(data.mt.float64())
	}
	if args[0].Type == object.ValueRange {
		return randomRangeNumber(data, args[0])
	}
	if args[0].Type == object.ValueFloat {
		limit := args[0].Data.(float64)
		if limit <= 0 {
			return NewArgumentError("invalid argument")
		}
		return newFloat(data.mt.float64() * limit)
	}
	limit, errVal := randomIntegerArgument(args[0])
	if errVal != nil {
		return errVal
	}
	if limit.Sign() <= 0 {
		return NewArgumentError("invalid argument")
	}
	return NewIntegerFromBigInt(data.mt.bigBelow(limit))
}

func randomEqual(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 1 || args[0] == nil || args[0].Class != receiver.Class {
		return R.FalseVal
	}
	left, leftOK := receiver.Data.(*randomData)
	right, rightOK := args[0].Data.(*randomData)
	if !leftOK || !rightOK || left.mt == nil || right.mt == nil || left.seedBig.Cmp(right.seedBig) != 0 {
		return R.FalseVal
	}
	if left.payload != nil || right.payload != nil {
		return R.TrueVal
	}
	return boolValue(left.mt.equal(right.mt))
}

func randomMarshalDump(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data, ok := receiver.Data.(*randomData)
	if !ok {
		return typeError("uninitialized Random")
	}
	if data.payload != nil {
		return data.payload
	}
	return &object.EmeraldValue{Type: object.ValueArray, Data: []*object.EmeraldValue{randomState(receiver), newInt(int64(data.mt.index)), NewIntegerFromBigInt(data.seedBig)}, Class: R.Classes["Array"]}
}

func randomMarshalLoad(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 1 || args[0] == nil || args[0].Type != object.ValueArray {
		return typeError("wrong dump data")
	}
	items := args[0].Data.([]*object.EmeraldValue)
	seed := big.NewInt(0)
	if len(items) >= 3 {
		if parsed, ok := numericBigIntValue(items[2]); ok {
			seed = parsed
		}
	}
	receiver.Data = newRandomData(seed)
	if data, ok := receiver.Data.(*randomData); ok {
		data.payload = args[0]
	}
	return receiver
}

func newRandomData(seed *big.Int) *randomData {
	if seed == nil {
		seed = big.NewInt(0)
	}
	seed = new(big.Int).Abs(new(big.Int).Set(seed))
	mt := newRubyMT19937(seed)
	return &randomData{seed: seed.Int64(), seedBig: seed, mt: mt}
}

func newRubyMT19937(seed *big.Int) *rubyMT19937 {
	mt := &rubyMT19937{}
	mt.seed(new(big.Int).Abs(new(big.Int).Set(seed)))
	return mt
}

func randomSeedBigInt(value *object.EmeraldValue) (*big.Int, *object.EmeraldValue) {
	if integer, ok := numericBigIntValue(value); ok {
		return new(big.Int).Abs(integer), nil
	}
	if value == nil {
		return nil, typeError("no implicit conversion into Integer")
	}
	if data, ok := value.Data.(*rationalData); ok && data != nil && data.denominator.Sign() != 0 {
		return new(big.Int).Quo(data.numerator, data.denominator), nil
	}
	if data, ok := value.Data.(*complexData); ok && data != nil {
		if data.imag != 0 || (data.imagValue != nil && numericValueAsFloat(data.imagValue) != 0) {
			return nil, newRuntimeException(R.Classes["RangeError"], "can't convert Complex into Integer")
		}
		if data.realValue != nil {
			return randomSeedBigInt(data.realValue)
		}
		return big.NewInt(int64(data.real)), nil
	}
	switch value.Type {
	case object.ValueFloat:
		return big.NewInt(int64(value.Data.(float64))), nil
	}
	if CallMethod != nil && receiverHasCallableMethod(value, "to_int") {
		converted := CallMethod(value, "to_int")
		if converted != nil && converted.Type == object.ValueException {
			return nil, converted
		}
		if integer, ok := numericBigIntValue(converted); ok {
			return new(big.Int).Abs(integer), nil
		}
	}
	return nil, typeError("no implicit conversion into Integer")
}

func randomIntegerArgument(value *object.EmeraldValue) (*big.Int, *object.EmeraldValue) {
	if integer, ok := numericBigIntValue(value); ok {
		return integer, nil
	}
	if CallMethod != nil && value != nil && receiverHasCallableMethod(value, "to_int") {
		converted := CallMethod(value, "to_int")
		if converted != nil && converted.Type == object.ValueException {
			return nil, converted
		}
		if integer, ok := numericBigIntValue(converted); ok {
			return integer, nil
		}
	}
	return nil, typeError("no implicit conversion into Integer")
}

func randomSeed(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data, ok := receiver.Data.(*randomData)
	if !ok || data.seedBig == nil {
		return typeError("uninitialized Random")
	}
	return NewIntegerFromBigInt(data.seedBig)
}

func randomState(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data, ok := receiver.Data.(*randomData)
	if !ok || data.mt == nil {
		return typeError("uninitialized Random")
	}
	buffer := make([]byte, 4*(len(data.mt.state)+1))
	for i, word := range data.mt.state {
		binary.LittleEndian.PutUint32(buffer[i*4:], word)
	}
	binary.LittleEndian.PutUint32(buffer[len(data.mt.state)*4:], uint32(data.mt.index))
	return stringWithEncoding(string(buffer), "ASCII-8BIT")
}

func randomBytes(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data, ok := receiver.Data.(*randomData)
	if !ok || data.mt == nil {
		return typeError("uninitialized Random")
	}
	if len(args) != 1 {
		return NewArgumentError("wrong number of arguments")
	}
	size, ok := valueToInteger(args[0])
	if !ok {
		return typeError("no implicit conversion into Integer")
	}
	if size < 0 {
		return NewArgumentError("negative string size")
	}
	buffer := make([]byte, int(size))
	for offset := 0; offset < len(buffer); {
		word := data.mt.uint32()
		for shift := uint(0); shift < 32 && offset < len(buffer); shift += 8 {
			buffer[offset] = byte(word >> shift)
			offset++
		}
	}
	return stringWithEncoding(string(buffer), "ASCII-8BIT")
}

func randomNewSeedBigInt() *big.Int {
	buffer := make([]byte, 16)
	if _, err := crand.Read(buffer); err == nil {
		return new(big.Int).SetBytes(buffer)
	}
	return big.NewInt(time.Now().UnixNano())
}

func randomClassNewSeed(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return NewIntegerFromBigInt(randomNewSeedBigInt())
}

func randomClassBytes(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return randomClassRandomBytes(args)
}

func randomClassURandom(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return randomClassRandomBytes(args)
}

func randomClassRandomBytes(args []*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 1 {
		return NewArgumentError("wrong number of arguments")
	}
	size, ok := valueToInteger(args[0])
	if !ok {
		return typeError("no implicit conversion into Integer")
	}
	if size < 0 {
		return NewArgumentError("negative string size")
	}
	buffer := make([]byte, int(size))
	if _, err := crand.Read(buffer); err != nil {
		return newRuntimeException(R.Classes["RuntimeError"], err.Error())
	}
	return stringWithEncoding(string(buffer), "ASCII-8BIT")
}

func randomRangeNumber(data *randomData, value *object.EmeraldValue) *object.EmeraldValue {
	r, ok := value.Data.(*object.RRange)
	if !ok || r == nil {
		return NewArgumentError("invalid argument")
	}
	start, startOK := r.StartValue.(*object.EmeraldValue)
	end, endOK := r.EndValue.(*object.EmeraldValue)
	if !startOK || !endOK || start == nil || end == nil {
		return NewArgumentError("invalid argument")
	}
	if start.Type == object.ValueFloat || end.Type == object.ValueFloat {
		startFloat, startOK := numericValueAsFloatOK(start)
		endFloat, endOK := numericValueAsFloatOK(end)
		if !startOK || !endOK || endFloat < startFloat || (r.Exclusive && endFloat == startFloat) {
			return NewArgumentError("invalid argument")
		}
		if startFloat == endFloat {
			return newFloat(startFloat)
		}
		return newFloat(startFloat + data.mt.float64()*(endFloat-startFloat))
	}
	startInt, startOK := numericBigIntValue(start)
	endInt, endOK := numericBigIntValue(end)
	if startOK && endOK {
		limit := new(big.Int).Sub(endInt, startInt)
		if !r.Exclusive {
			limit.Add(limit, big.NewInt(1))
		}
		if limit.Sign() <= 0 {
			return NewArgumentError("invalid argument")
		}
		return NewIntegerFromBigInt(new(big.Int).Add(startInt, data.mt.bigBelow(limit)))
	}
	return randomCustomRangeNumber(data, start, end, r.Exclusive)
}

func randomCustomRangeNumber(data *randomData, start, end *object.EmeraldValue, exclusive bool) *object.EmeraldValue {
	if CallMethod == nil {
		return NewArgumentError("invalid argument")
	}
	difference := CallMethod(end, "-", start)
	if difference == nil || difference.Type == object.ValueException {
		return NewArgumentError("invalid argument")
	}
	if span, ok := numericValueAsFloatOK(difference); ok {
		if span < 0 || (exclusive && span == 0) {
			return NewArgumentError("invalid argument")
		}
		return CallMethod(start, "+", newFloat(data.mt.float64()*span))
	}
	limit, errVal := randomIntegerArgument(difference)
	if errVal != nil {
		return NewArgumentError("invalid argument")
	}
	if !exclusive {
		limit.Add(limit, big.NewInt(1))
	}
	if limit.Sign() <= 0 {
		return NewArgumentError("invalid argument")
	}
	return CallMethod(start, "+", NewIntegerFromBigInt(data.mt.bigBelow(limit)))
}

func (mt *rubyMT19937) seed(seed *big.Int) {
	absolute := new(big.Int).Abs(new(big.Int).Set(seed))
	if absolute.BitLen() <= 32 {
		mt.init(uint32(absolute.Uint64()))
		return
	}
	words := make([]uint32, 0, (absolute.BitLen()+31)/32)
	mask := new(big.Int).SetUint64(uint64(^uint32(0)))
	remaining := new(big.Int).Set(absolute)
	for remaining.Sign() != 0 {
		words = append(words, uint32(new(big.Int).And(remaining, mask).Uint64()))
		remaining.Rsh(remaining, 32)
	}
	mt.initByArray(words)
}

func (mt *rubyMT19937) init(seed uint32) {
	mt.state[0] = seed
	for i := 1; i < len(mt.state); i++ {
		mt.state[i] = 1812433253*(mt.state[i-1]^(mt.state[i-1]>>30)) + uint32(i)
	}
	mt.index = len(mt.state)
}

func (mt *rubyMT19937) initByArray(keys []uint32) {
	mt.init(19650218)
	i, j := 1, 0
	count := len(mt.state)
	if len(keys) > count {
		count = len(keys)
	}
	for ; count > 0; count-- {
		mt.state[i] = (mt.state[i] ^ ((mt.state[i-1] ^ (mt.state[i-1] >> 30)) * 1664525)) + keys[j] + uint32(j)
		i++
		j++
		if i >= len(mt.state) {
			mt.state[0] = mt.state[len(mt.state)-1]
			i = 1
		}
		if j >= len(keys) {
			j = 0
		}
	}
	for count = len(mt.state) - 1; count > 0; count-- {
		mt.state[i] = (mt.state[i] ^ ((mt.state[i-1] ^ (mt.state[i-1] >> 30)) * 1566083941)) - uint32(i)
		i++
		if i >= len(mt.state) {
			mt.state[0] = mt.state[len(mt.state)-1]
			i = 1
		}
	}
	mt.state[0] = 0x80000000
	mt.index = len(mt.state)
}

func (mt *rubyMT19937) uint32() uint32 {
	if mt.index >= len(mt.state) {
		for i := 0; i < len(mt.state); i++ {
			y := (mt.state[i] & 0x80000000) | (mt.state[(i+1)%len(mt.state)] & 0x7fffffff)
			mt.state[i] = mt.state[(i+397)%len(mt.state)] ^ (y >> 1)
			if y&1 != 0 {
				mt.state[i] ^= 0x9908b0df
			}
		}
		mt.index = 0
	}
	y := mt.state[mt.index]
	mt.index++
	y ^= y >> 11
	y ^= (y << 7) & 0x9d2c5680
	y ^= (y << 15) & 0xefc60000
	y ^= y >> 18
	return y
}

func (mt *rubyMT19937) float64() float64 {
	a := uint64(mt.uint32() >> 5)
	b := uint64(mt.uint32() >> 6)
	return float64(a*67108864+b) / 9007199254740992.0
}

func (mt *rubyMT19937) bigBelow(limit *big.Int) *big.Int {
	if limit == nil || limit.Sign() <= 0 {
		return big.NewInt(0)
	}
	bits := new(big.Int).Sub(limit, big.NewInt(1)).BitLen()
	if bits == 0 {
		return big.NewInt(0)
	}
	words := (bits + 31) / 32
	for {
		candidate := big.NewInt(0)
		for i := 0; i < words; i++ {
			candidate.Or(candidate, new(big.Int).Lsh(new(big.Int).SetUint64(uint64(mt.uint32())), uint(i*32)))
		}
		if extra := words*32 - bits; extra > 0 {
			candidate.And(candidate, new(big.Int).Sub(new(big.Int).Lsh(big.NewInt(1), uint(bits)), big.NewInt(1)))
		}
		if candidate.Cmp(limit) < 0 {
			return candidate
		}
	}
}

func (mt *rubyMT19937) equal(other *rubyMT19937) bool {
	if mt == nil || other == nil || mt.index != other.index {
		return false
	}
	return mt.state == other.state
}

