func primeValues(bound *big.Int) []*object.EmeraldValue {
	limit := int64(105000)
	if bound != nil && bound.IsInt64() {
		limit = bound.Int64()
	}
	if limit < 2 {
		return []*object.EmeraldValue{}
	}
	values := make([]*object.EmeraldValue, 0)
	for candidate := int64(2); candidate <= limit; candidate++ {
		prime := true
		for divisor := int64(2); divisor <= candidate/divisor; divisor++ {
			if candidate%divisor == 0 {
				prime = false
				break
			}
		}
		if prime {
			values = append(values, newInt(candidate))
		}
	}
	return values
}

func primeEach(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) > 2 {
		return NewArgumentError("wrong number of arguments")
	}
	if len(args) == 2 {
		if CallMethod == nil {
			return R.NilVal
		}
		result := CallMethod(args[1], "upper_bound=", args[0])
		if result != nil && result.Type == object.ValueException {
			return result
		}
		return CallMethod(args[1], "each")
	}
	var bound *big.Int
	if len(args) == 1 {
		var ok bool
		bound, ok = numericBigIntValue(args[0])
		if !ok {
			return NewTypeError("expected Integer")
		}
	}
	build := func() ([]*object.EmeraldValue, *object.EmeraldValue) { return primeValues(bound), nil }
	if BlockGivenCheck == nil || !BlockGivenCheck() || CurrentBlockValue == nil || CurrentBlockValue() == nil {
		return newGeneratorEnumerator(build)
	}
	values := primeValues(bound)
	last := R.NilVal
	for _, value := range values {
		result := CallBlockWithArgs(CurrentBlockValue(), value)
		if result != nil && result.Type == object.ValueException {
			return result
		}
		last = result
		if LastBlockResult != nil {
			control := LastBlockResult
			LastBlockResult = nil
			return control
		}
	}
	return last
}

func primeIntegerEachPrime(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if prime := R.Classes["Prime"]; prime != nil && CallMethod != nil {
		return CallMethod(&object.EmeraldValue{Type: object.ValueClass, Data: prime, Class: R.Classes["Class"]}, "each", args...)
	}
	return R.NilVal
}

func primeIntFromDivision(_ *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 1 {
		return NewArgumentError("wrong number of arguments")
	}
	factors, ok := valueToArray(args[0])
	if !ok {
		return NewTypeError("expected Array")
	}
	product := big.NewInt(1)
	for _, factor := range factors {
		pair, ok := valueToArray(factor)
		if !ok || len(pair) != 2 {
			return NewTypeError("invalid factorization")
		}
		base, bok := numericBigIntValue(pair[0])
		exponent, eok := numericBigIntValue(pair[1])
		if !bok || !eok || exponent.Sign() < 0 || !exponent.IsInt64() {
			return NewTypeError("invalid factorization")
		}
		power := new(big.Int).Exp(base, exponent, nil)
		product.Mul(product, power)
	}
	return NewIntegerFromBigInt(product)
}
func primeClassPrime(_ *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 1 {
		return NewArgumentError("wrong number of arguments")
	}
	value, ok := numericBigIntValue(args[0])
	return boolValue(ok && value.Sign() > 0 && value.ProbablyPrime(20))
}
func intPrime(receiver *object.EmeraldValue, _ ...*object.EmeraldValue) *object.EmeraldValue {
	value, ok := numericBigIntValue(receiver)
	return boolValue(ok && value.Sign() > 0 && value.ProbablyPrime(20))
}

