func zlibAdler32(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) > 2 {
		return NewArgumentError("wrong number of arguments")
	}
	initial := uint32(1)
	if len(args) > 1 {
		next, errVal := zlibInitialValue(args[1])
		if errVal != nil {
			return errVal
		}
		initial = next
	}
	if len(args) == 0 || args[0] == nil || args[0].Type == object.ValueNil {
		return newInt(int64(initial))
	}
	_, raw, errVal := cgiStringArg(args[0])
	if errVal != nil {
		return errVal
	}
	if initial == 1 {
		return newInt(int64(adler32.Checksum([]byte(raw))))
	}
	const mod = 65521
	s1 := initial & 0xffff
	s2 := (initial >> 16) & 0xffff
	for i := 0; i < len(raw); i++ {
		s1 = (s1 + uint32(raw[i])) % mod
		s2 = (s2 + s1) % mod
	}
	return newInt(int64((s2 << 16) | s1))
}

func zlibCRC32(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) > 2 {
		return NewArgumentError("wrong number of arguments")
	}
	initial := uint32(0)
	if len(args) > 1 {
		next, errVal := zlibInitialValue(args[1])
		if errVal != nil {
			return errVal
		}
		initial = next
	}
	if len(args) == 0 || args[0] == nil || args[0].Type == object.ValueNil {
		return newInt(int64(initial))
	}
	_, raw, errVal := cgiStringArg(args[0])
	if errVal != nil {
		return errVal
	}
	return newInt(int64(crc32.Update(initial, crc32.IEEETable, []byte(raw))))
}

func zlibCRCTable(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	values := make([]*object.EmeraldValue, 256)
	for index := range values {
		crc := uint32(index)
		for bit := 0; bit < 8; bit++ {
			if crc&1 != 0 {
				crc = 0xedb88320 ^ (crc >> 1)
			} else {
				crc >>= 1
			}
		}
		values[index] = newInt(int64(crc))
	}
	return &object.EmeraldValue{Type: object.ValueArray, Data: values, Class: R.Classes["Array"]}
}

