func digestSHA2ClassNew(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) > 1 {
		return NewArgumentError("wrong number of arguments")
	}
	bits := int64(256)
	if len(args) == 1 {
		value, ok := valueToInteger(args[0])
		if !ok {
			return NewTypeError("no implicit conversion into Integer")
		}
		bits = value
	}
	index := 2
	switch bits {
	case 256:
		index = 2
	case 384:
		index = 3
	case 512:
		index = 4
	default:
		return NewArgumentError("unsupported bit length: " + strconv.FormatInt(bits, 10))
	}
	klass, _ := receiver.Data.(*object.Class)
	return digestAlgorithmNewValueForClass(&digestAlgorithms[index], klass, nil)
}

