func digestAlgorithmEqual(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 1 {
		return NewArgumentError("wrong number of arguments")
	}
	state := digestAlgorithmState(receiver)
	if state == nil {
		return R.FalseVal
	}
	hexdigest := hex.EncodeToString(digestAlgorithmSum(state.spec, state.data))
	other := args[0]
	if other == receiver {
		return R.TrueVal
	}
	if otherState := digestAlgorithmState(other); otherState != nil {
		if otherState.spec == state.spec && hex.EncodeToString(digestAlgorithmSum(otherState.spec, otherState.data)) == hexdigest {
			return R.TrueVal
		}
		return R.FalseVal
	}
	text, ok, _, errVal := evalCoerceToString(other)
	if errVal != nil {
		return errVal
	}
	if ok && text == hexdigest {
		return R.TrueVal
	}
	return R.FalseVal
}

func digestStringWithSpec(spec *digestAlgorithmSpec, value *object.EmeraldValue, asHex bool) *object.EmeraldValue {
	if spec == nil {
		return R.NilVal
	}
	text, ok, viaToStr, errVal := evalCoerceToString(value)
	if errVal != nil {
		return errVal
	}
	if !ok {
		return conversionTypeErrorToStringForMode(value, viaToStr)
	}
	sum := digestAlgorithmSum(spec, []byte(text))
	if asHex {
		return rubyString(hex.EncodeToString(sum))
	}
	return stringWithEncoding(string(sum), "ASCII-8BIT")
}

func digestAlgorithmSum(spec *digestAlgorithmSpec, data []byte) []byte {
	if spec == nil || spec.newHash == nil {
		return nil
	}
	h := spec.newHash()
	_, _ = h.Write(data)
	return h.Sum(nil)
}

