func getoptLongSetOrdering(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data := getoptLongDataFor(receiver)
	if data == nil || len(args) == 0 || args[0] == nil || args[0].Type != object.ValueInteger {
		return getoptLongArgumentError(data)
	}
	value := args[0].Data.(int64)
	if value < 0 || value > 2 {
		return getoptLongArgumentError(data)
	}
	if data.Started {
		return getoptLongArgumentError(data)
	}
	if value == 1 {
		if _, ok := envString("POSIXLY_CORRECT"); ok {
			data.Ordering = 0
			return args[0]
		}
	}
	data.Ordering = value
	return args[0]
}

