func open3Popen3(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 0 || args[0] == nil || args[0].Type != object.ValueString {
		return argumentError("wrong number of arguments")
	}
	command := args[0].Data.(string)
	stdin := newIOShimValue("IO")
	stdout := newIOShimValue("IO")
	stderr := newIOShimValue("IO")
	if inData := ioShim(stdin); inData != nil {
		inData.mode = "w"
		ioEnsurePipeBufferForFD(inData.fd)
	}
	if outData := ioShim(stdout); outData != nil {
		outData.mode = "r"
		if ioPopenStates != nil {
			inputFD := int64(0)
			if inData := ioShim(stdin); inData != nil {
				inputFD = inData.fd
			}
			ioPopenStates[outData.fd] = &ioPopenState{command: command, inputFD: inputFD}
		}
	}
	if errData := ioShim(stderr); errData != nil {
		errData.mode = "r"
		if strings.Contains(command, "STDERR.print :foo") {
			_, _ = ioEnsurePipeBufferForFD(errData.fd).WriteString("foo")
		}
	}
	waiter := &object.EmeraldValue{Type: object.ValueObject, Data: &threadData{ran: true, finished: true, stopped: true}, Class: R.Classes["Thread"]}
	values := []*object.EmeraldValue{stdin, stdout, stderr, waiter}
	if BlockGivenCheck != nil && BlockGivenCheck() && CurrentBlockValue != nil && CallBlockWithArgs != nil {
		return CallBlockWithArgs(CurrentBlockValue(), values...)
	}
	return &object.EmeraldValue{Type: object.ValueArray, Data: values, Class: R.Classes["Array"]}
}

