func pathnameString(value *object.EmeraldValue) (string, bool) {
	if value == nil {
		return "", false
	}
	if value.Type == object.ValueString {
		return value.Data.(string), true
	}
	if data, ok := value.Data.(*pathnameData); ok && data != nil {
		return data.Path, true
	}
	return "", false
}

func pathnameRelativePathFrom(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 1 {
		return argumentError("wrong number of arguments")
	}
	dest, ok := pathnameString(receiver)
	if !ok {
		return typeError("no implicit conversion into String")
	}
	base, ok := pathnameString(args[0])
	if !ok {
		var errVal *object.EmeraldValue
		base, errVal = coercePath(args[0])
		if errVal != nil {
			return errVal
		}
	}
	if filepath.IsAbs(dest) != filepath.IsAbs(base) {
		return argumentError("different prefix")
	}
	cleanDest := filepath.Clean(dest)
	cleanBase := filepath.Clean(base)
	if cleanDest == cleanBase {
		return &object.EmeraldValue{Type: object.ValueString, Data: ".", Class: R.Classes["Pathname"]}
	}
	if base == ".." || strings.HasPrefix(base, "../") {
		return argumentError("base directory has ..")
	}
	rel, err := filepath.Rel(cleanBase, cleanDest)
	if err != nil {
		return argumentError(err.Error())
	}
	if rel == "" {
		rel = "."
	}
	return &object.EmeraldValue{Type: object.ValueString, Data: filepath.ToSlash(rel), Class: R.Classes["Pathname"]}
}

func pathnameClassGlob(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	checkedArgs, errVal := pathnameGlobArgs(args)
	if errVal != nil {
		return errVal
	}
	result := dirClassGlobMapped(receiver, pathnameGlobValue, checkedArgs...)
	return pathnameGlobResult(result)
}

func pathnameInstanceGlob(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	base, ok := pathnameString(receiver)
	if !ok {
		return typeError("no implicit conversion into String")
	}
	checkedArgs, errVal := pathnameGlobArgs(args)
	if errVal != nil {
		return errVal
	}
	if len(checkedArgs) > 0 && checkedArgs[len(checkedArgs)-1] != nil && checkedArgs[len(checkedArgs)-1].Type == object.ValueHash {
		opts := valueToHashMap(checkedArgs[len(checkedArgs)-1])
		opts[rubySymbol("base")] = rubyString(base)
	} else {
		opt := emptyHashValue()
		data := hashData(opt)
		key := rubySymbol("base")
		data.Keys = append(data.Keys, key)
		data.Pairs[key] = rubyString(base)
		checkedArgs = append(checkedArgs, opt)
	}
	result := dirClassGlobMapped(receiver, func(value *object.EmeraldValue) *object.EmeraldValue {
		path, errVal := coercePath(value)
		if errVal != nil {
			return errVal
		}
		if !filepath.IsAbs(path) {
			path = filepath.Join(base, path)
		}
		return &object.EmeraldValue{Type: object.ValueString, Data: filepath.Clean(path), Class: R.Classes["Pathname"]}
	}, checkedArgs...)
	return pathnameGlobResult(result)
}

func pathnameGlobValue(value *object.EmeraldValue) *object.EmeraldValue {
	path, errVal := coercePath(value)
	if errVal != nil {
		return errVal
	}
	return &object.EmeraldValue{Type: object.ValueString, Data: path, Class: R.Classes["Pathname"]}
}

func pathnameGlobArgs(args []*object.EmeraldValue) ([]*object.EmeraldValue, *object.EmeraldValue) {
	checked := append([]*object.EmeraldValue{}, args...)
	if len(checked) == 0 || checked[len(checked)-1] == nil || checked[len(checked)-1].Type != object.ValueHash {
		return checked, nil
	}
	opts := valueToHashMap(checked[len(checked)-1])
	for key := range opts {
		if specName(key) != "base" && specName(key) != ":base" {
			return nil, argumentError("unknown keyword: :" + strings.TrimPrefix(specName(key), ":"))
		}
	}
	return checked, nil
}

func pathnameGlobResult(result *object.EmeraldValue) *object.EmeraldValue {
	if result == nil || result.Type != object.ValueArray {
		return result
	}
	values := result.Data.([]*object.EmeraldValue)
	paths := make([]*object.EmeraldValue, 0, len(values))
	for _, value := range values {
		path, errVal := coercePath(value)
		if errVal != nil {
			return errVal
		}
		paths = append(paths, &object.EmeraldValue{Type: object.ValueString, Data: path, Class: R.Classes["Pathname"]})
	}
	return &object.EmeraldValue{Type: object.ValueArray, Data: paths, Class: R.Classes["Array"]}
}

