	R.Classes["Logger"] = klass
	classValue := &object.EmeraldValue{Type: object.ValueClass, Data: klass, Class: R.Classes["Class"]}
	objectClass.DefineConstant("Logger", classValue)
	AssignConstantName(&object.EmeraldValue{Type: object.ValueClass, Data: objectClass, Class: R.Classes["Class"]}, "Logger", classValue)
