func loggerClassNew(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data := &loggerData{level: 0, progname: R.NilVal, datetimeFormat: R.NilVal, formatter: R.NilVal}
	if len(args) > 0 {
		data.device = args[0]
	}
	if len(args) > 1 && args[1] != nil && args[1].Type == object.ValueInteger {
		data.shiftAge = args[1].Data.(int64)
	}
	if len(args) > 2 && args[2] != nil && args[2].Type == object.ValueInteger {
		data.shiftSize = args[2].Data.(int64)
	}
	if len(args) > 0 && args[len(args)-1] != nil && args[len(args)-1].Type == object.ValueHash {
		opts := valueToHashMap(args[len(args)-1])
		if value, ok := hashLookup(opts, rubySymbol("level")); ok {
			data.level = loggerLevelValue(value)
		}
		if value, ok := hashLookup(opts, rubySymbol("progname")); ok {
			data.progname = value
		}
		if value, ok := hashLookup(opts, rubySymbol("datetime_format")); ok {
			data.datetimeFormat = value
		}
		if value, ok := hashLookup(opts, rubySymbol("formatter")); ok {
			data.formatter = value
		}
	}
	return &object.EmeraldValue{Type: object.ValueObject, Data: data, Class: R.Classes["Logger"]}
}

func loggerLevelValue(value *object.EmeraldValue) int64 {
	if value == nil {
		return 0
	}
	if value.Type == object.ValueInteger {
		return value.Data.(int64)
	}
	if value.Type == object.ValueSymbol {
		switch value.Data.(string) {
		case "debug":
			return 0
		case "info":
			return 1
		case "warn":
			return 2
		case "error":
			return 3
		case "fatal":
			return 4
		case "unknown":
			return 5
		}
	}
	return 0
}

