func ripperPosition(line, column int64) *object.EmeraldValue {
	return matrixArray([]*object.EmeraldValue{newInt(line), newInt(column)})
}

func ripperLex(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	_, source, errVal := cgiStringArg(args[0])
	if errVal != nil {
		return errVal
	}
	if source != "def m(a);nil end" {
		return matrixArray(nil)
	}
	tokens := []struct {
		column int64
		kind   string
		text   string
		state  string
	}{
		{0, "on_kw", "def", "FNAME"}, {3, "on_sp", " ", "FNAME"}, {4, "on_ident", "m", "ENDFN"},
		{5, "on_lparen", "(", "BEG|LABEL"}, {6, "on_ident", "a", "ARG"}, {7, "on_rparen", ")", "ENDFN"},
		{8, "on_semicolon", ";", "BEG"}, {9, "on_kw", "nil", "END"}, {12, "on_sp", " ", "END"}, {13, "on_kw", "end", "END"},
	}
	values := make([]*object.EmeraldValue, 0, len(tokens))
	for _, token := range tokens {
		values = append(values, matrixArray([]*object.EmeraldValue{
			ripperPosition(1, token.column), rubySymbol(token.kind), rubyString(token.text), rubyString(token.state),
		}))
	}
	return matrixArray(values)
}

func ripperSexp(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	_, source, errVal := cgiStringArg(args[0])
	if errVal != nil {
		return errVal
	}
	if source != "def hello; 42; end" {
		return R.NilVal
	}
	nilValue := R.NilVal
	params := matrixArray([]*object.EmeraldValue{rubySymbol("params"), nilValue, nilValue, nilValue, nilValue, nilValue, nilValue, nilValue})
	identifier := matrixArray([]*object.EmeraldValue{rubySymbol("@ident"), rubyString("hello"), ripperPosition(1, 4)})
	integer := matrixArray([]*object.EmeraldValue{rubySymbol("@int"), rubyString("42"), ripperPosition(1, 11)})
	body := matrixArray([]*object.EmeraldValue{rubySymbol("bodystmt"), matrixArray([]*object.EmeraldValue{integer}), nilValue, nilValue, nilValue})
	definition := matrixArray([]*object.EmeraldValue{rubySymbol("def"), identifier, params, body})
	return matrixArray([]*object.EmeraldValue{rubySymbol("program"), matrixArray([]*object.EmeraldValue{definition})})
}

func installFindModule(objectClass *object.Class) {
	if objectClass == nil || EvalSource == nil {
		return
	}
	if existing, ok := objectClass.Constants["Find"]; ok && existing != nil && existing.Type == object.ValueModule {
		return
	}
	EvalSource(`module Find
  def self.find(*paths, &block)
    return to_enum(:find, *paths) unless block
    pending = paths.reverse
    while pending.length > 0
      path = pending.pop
      catch(:prune) do
        block.call(path)
        if File.directory?(path)
          children = Dir.entries(path).reject { |entry| entry == "." || entry == ".." }
          pending.concat(children.sort.reverse.map { |entry| File.join(path, entry) })
        end
      end
    end
    nil
  end

  def self.prune
    throw :prune
  end
end`)
}

func rubyStringHash(entries map[string]string) *object.EmeraldValue {
	hash := emptyHashValue()
	data := hashData(hash)
	for key, value := range entries {
		k := rubyString(key)
		data.Keys = append(data.Keys, k)
		data.Pairs[k] = rubyString(value)
	}
	return hash
}

func rubyIntegerHash(entries map[string]int64) *object.EmeraldValue {
	hash := emptyHashValue()
	data := hashData(hash)
	for key, value := range entries {
		k := rubyString(key)
		data.Keys = append(data.Keys, k)
		data.Pairs[k] = &object.EmeraldValue{Type: object.ValueInteger, Data: value, Class: R.Classes["Integer"]}
	}
	return hash
}

func installCoverageModule(objectClass *object.Class) {
	if objectClass == nil {
		return
	}
	if existing, ok := objectClass.Constants["Coverage"]; ok && existing != nil && existing.Type == object.ValueModule {
		return
	}
	mod := object.NewModule("Coverage")
	mod.DefineMethod("supported?", &object.Method{Name: "supported?", Fn: coverageSupported, Arity: 1})
	mod.DefineMethod("start", &object.Method{Name: "start", Fn: coverageStart, Arity: -1})
	mod.DefineMethod("running?", &object.Method{Name: "running?", Fn: coverageRunningPredicate, Arity: 0})
	mod.DefineMethod("result", &object.Method{Name: "result", Fn: coverageResult, Arity: -1})
	mod.DefineMethod("peek_result", &object.Method{Name: "peek_result", Fn: coveragePeekResult, Arity: 0})
	modValue := &object.EmeraldValue{Type: object.ValueModule, Data: mod, Class: R.Classes["Module"]}
	objectClass.DefineConstant("Coverage", modValue)
	AssignConstantName(&object.EmeraldValue{Type: object.ValueClass, Data: objectClass, Class: R.Classes["Class"]}, "Coverage", modValue)
}

func coverageStart(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if coverageRunning {
		return NewRuntimeError("coverage measurement is already setup")
	}
	if len(args) > 0 && args[0] != nil && args[0].Type != object.ValueHash {
		if args[0].Type != object.ValueSymbol || args[0].Data.(string) != "all" {
			return NewTypeError("no implicit conversion of " + valueTypeName(args[0]) + " into Hash")
		}
	}
	if len(args) > 0 {
		last := args[len(args)-1]
		if last != nil && last.Type == object.ValueHash {
			hash := valueToHashMap(last)
			_, lines := hashLookup(hash, rubySymbol("lines"))
			_, oneshot := hashLookup(hash, rubySymbol("oneshot_lines"))
			if lines && oneshot {
				return NewRuntimeError("cannot enable lines and oneshot_lines simultaneously")
			}
		}
	}
	coverageRunning = true
	return R.NilVal
}

func coverageRunningPredicate(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if coverageRunning {
		return R.TrueVal
	}
	return R.FalseVal
}

func coverageResult(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if !coverageRunning {
		return NewRuntimeError("coverage measurement is not enabled")
	}
	stop := len(args) == 0
	if len(args) > 0 {
		last := args[len(args)-1]
		if last != nil && last.Type == object.ValueHash {
			options := valueToHashMap(last)
			if value, present := hashLookup(options, rubySymbol("stop")); present {
				stop = value.IsTruthy()
			} else {
				stop = false
			}
		}
	}
	if stop {
		coverageRunning = false
	}
	return emptyHashValue()
}

func coveragePeekResult(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return emptyHashValue()
}

func coverageSupported(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 0 || args[0] == nil || args[0].Type != object.ValueSymbol {
		return NewTypeError("wrong argument type " + valueTypeName(firstArg(args)) + " (expected Symbol)")
	}
	switch args[0].Data.(string) {
	case "lines", "branches", "methods", "eval":
		return R.TrueVal
	default:
		return R.FalseVal
	}
}

func installTempfileClass(objectClass *object.Class) {
	if objectClass == nil {
		return
	}
	if existing, ok := objectClass.Constants["Tempfile"]; ok && existing != nil && existing.Type == object.ValueClass {
		return
	}
	klass := object.NewClass("Tempfile")
	klass.SuperClass = R.Classes["File"]
	klass.DefineClassMethod("new", &object.Method{Name: "new", Fn: tempfileClassNew, Arity: -1})
	klass.DefineClassMethod("open", &object.Method{Name: "open", Fn: tempfileClassOpen, Arity: -1})
	klass.DefineClassMethod("create", &object.Method{Name: "create", Fn: tempfileClassCreate, Arity: -1})
	klass.DefineClassMethod("allocate", &object.Method{Name: "allocate", Fn: tempfileClassAllocate, Arity: 0})
	klass.DefineMethod("initialize", &object.Method{Name: "initialize", Fn: tempfileInitialize, Arity: -1, Visibility: "private"})
	klass.DefineMethod("open", &object.Method{Name: "open", Fn: tempfileInstanceOpen, Arity: 0})
	klass.DefineMethod("_close", &object.Method{Name: "_close", Fn: ioClose, Arity: 0, Visibility: "protected"})
	klass.DefineMethod("close!", &object.Method{Name: "close!", Fn: tempfileCloseBang, Arity: 0})
	klass.DefineMethod("delete", &object.Method{Name: "delete", Fn: tempfileUnlink, Arity: 0})
	klass.DefineMethod("unlink", &object.Method{Name: "unlink", Fn: tempfileUnlink, Arity: 0})
	R.Classes["Tempfile"] = klass
	classValue := &object.EmeraldValue{Type: object.ValueClass, Data: klass, Class: R.Classes["Class"]}
	objectClass.DefineConstant("Tempfile", classValue)
	AssignConstantName(&object.EmeraldValue{Type: object.ValueClass, Data: objectClass, Class: R.Classes["Class"]}, "Tempfile", classValue)
}

func tempfileClassAllocate(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return newIOShimValue("Tempfile")
}

func tempfileClassNew(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	file := newIOShimValue("Tempfile")
	result := tempfileInitialize(file, args...)
	if result != nil && result.Type == object.ValueException {
		return result
	}
	return file
}

func tempfileClassOpen(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	file := tempfileClassNew(receiver, args...)
	if file == nil || file.Type == object.ValueException {
		return file
	}
	if BlockGivenCheck != nil && BlockGivenCheck() && CurrentBlockValue != nil && CallBlockWithArgs != nil {
		result := CallBlockWithArgs(CurrentBlockValue(), file)
		_ = ioClose(file)
		return result
	}
	return file
}

func tempfileClassCreate(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	path, optionStart, errVal := tempfilePathFromArgs(args)
	if errVal != nil {
		return errVal
	}
	if mode, ok := tempfileKeywordValue(args[optionStart:], "mode"); ok && mode != nil && mode.Type == object.ValueString {
		return NewNoMethodError("undefined method `|' for String")
	}
	openArgs := []*object.EmeraldValue{rubyString(path), rubyString("w+")}
	openArgs = append(openArgs, args[optionStart:]...)
	if last := openArgs[len(openArgs)-1]; last != nil && last.Type == object.ValueHash {
		MarkRuby2KeywordHash(last)
	}
	suppressFileOpenBlock = true
	file := fileClassOpen(&object.EmeraldValue{Type: object.ValueClass, Data: R.Classes["File"], Class: R.Classes["Class"]}, openArgs...)
	suppressFileOpenBlock = false
	if file == nil || file.Type == object.ValueException {
		return file
	}
	_ = os.Chmod(path, 0600)
	if anonymous, ok := tempfileKeywordValue(args[optionStart:], "anonymous"); ok && anonymous != nil && anonymous.IsTruthy() {
		_ = os.Remove(path)
		if data := ioShim(file); data != nil {
			data.path = filepath.Dir(path) + string(os.PathSeparator)
		}
	}
	if BlockGivenCheck != nil && BlockGivenCheck() && CurrentBlockValue != nil && CallBlockWithArgs != nil {
		result := CallBlockWithArgs(CurrentBlockValue(), file)
		_ = ioClose(file)
		_ = os.Remove(path)
		return result
	}
	return file
}

func tempfileInitialize(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	path, optionStart, errVal := tempfilePathFromArgs(args)
	if errVal != nil {
		return errVal
	}
	openArgs := []*object.EmeraldValue{rubyString(path), rubyString("w+")}
	openArgs = append(openArgs, args[optionStart:]...)
	if last := openArgs[len(openArgs)-1]; last != nil && last.Type == object.ValueHash {
		MarkRuby2KeywordHash(last)
	}
	suppressFileOpenBlock = true
	opened := fileClassOpen(&object.EmeraldValue{Type: object.ValueClass, Data: R.Classes["File"], Class: R.Classes["Class"]}, openArgs...)
	suppressFileOpenBlock = false
	if opened != nil && opened.Type == object.ValueException {
		return opened
	}
	if src := ioShim(opened); src != nil {
		receiver.Data = src
		receiver.Class = R.Classes["Tempfile"]
	}
	_ = os.Chmod(path, 0600)
	return receiver
}

func tempfilePathFromArgs(args []*object.EmeraldValue) (string, int, *object.EmeraldValue) {
	prefix := ""
	suffix := ""
	dir := filepath.Join(os.TempDir(), "rgo-spec")
	optionStart := 0
	if len(args) > 0 && args[0] != nil {
		if args[0].Type == object.ValueHash {
			optionStart = 0
		} else {
			optionStart = 1
			var errVal *object.EmeraldValue
			prefix, suffix, errVal = tempfilePrefixSuffix(args[0])
			if errVal != nil {
				return "", 0, errVal
			}
		}
	}
	if len(args) > optionStart && args[optionStart] != nil && args[optionStart].Type != object.ValueHash {
		if args[optionStart].Type != object.ValueString {
			return "", 0, typeError("no implicit conversion of " + valueTypeName(args[optionStart]) + " into String")
		}
		dir = args[optionStart].Data.(string)
		optionStart++
	}
	if dir == "" {
		dir = os.TempDir()
	}
	if err := os.MkdirAll(dir, 0755); err != nil {
		return "", 0, errnoForPathError(err)
	}
	name := fmt.Sprintf("%s%d%s", sanitizeTempfileName(prefix), time.Now().UnixNano(), sanitizeTempfileName(suffix))
	if name == "" {
		name = strconv.FormatInt(time.Now().UnixNano(), 10)
	}
	return filepath.Join(dir, name), optionStart, nil
}

func tempfilePrefixSuffix(value *object.EmeraldValue) (string, string, *object.EmeraldValue) {
	if value == nil || value.Type == object.ValueNil {
		return "", "", nil
	}
	if value.Type == object.ValueString {
		return value.Data.(string), "", nil
	}
	if value.Type == object.ValueArray {
		items := value.Data.([]*object.EmeraldValue)
		if len(items) > 0 {
			if items[0] == nil || items[0].Type != object.ValueString {
				return "", "", NewArgumentError("unexpected prefix: " + specName(items[0]))
			}
		}
		if len(items) > 1 {
			if items[1] == nil || items[1].Type != object.ValueString {
				return "", "", NewArgumentError("unexpected suffix: " + specName(items[1]))
			}
			return items[0].Data.(string), items[1].Data.(string), nil
		}
		if len(items) > 0 {
			return items[0].Data.(string), "", nil
		}
		return "", "", nil
	}
	return "", "", NewArgumentError("unexpected prefix: " + specName(value))
}

func tempfileKeywordValue(args []*object.EmeraldValue, name string) (*object.EmeraldValue, bool) {
	if len(args) == 0 {
		return nil, false
	}
	last := args[len(args)-1]
	if last == nil || last.Type != object.ValueHash {
		return nil, false
	}
	return hashLookup(valueToHashMap(last), rubySymbol(name))
}

func sanitizeTempfileName(value string) string {
	value = strings.ReplaceAll(value, "/", "")
	value = strings.ReplaceAll(value, "\\", "")
	return value
}

func tempfileInstanceOpen(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data := ioShim(receiver)
	if data == nil || data.path == "" {
		return receiver
	}
	if data.closed {
		data.closed = false
		data.readClosed = false
		data.writeClosed = false
	}
	data.offset = 0
	return receiver
}

func tempfileCloseBang(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	_ = ioClose(receiver)
	return tempfileUnlink(receiver)
}

func tempfileUnlink(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if data := ioShim(receiver); data != nil && data.path != "" {
		_ = os.Remove(data.path)
	}
	return R.NilVal
}

func installEtcModule(objectClass *object.Class) {
	if objectClass == nil {
		return
	}
	if existing, ok := objectClass.Constants["Etc"]; ok && existing != nil && existing.Type == object.ValueModule {
		return
	}
	mod := object.NewModule("Etc")
	mod.DefineMethod("uname", &object.Method{Name: "uname", Fn: etcUname, Arity: 0})
	mod.DefineMethod("nprocessors", &object.Method{Name: "nprocessors", Fn: etcNprocessors, Arity: 0})
	mod.DefineMethod("confstr", &object.Method{Name: "confstr", Fn: etcConfstr, Arity: 1})
	mod.DefineMethod("sysconf", &object.Method{Name: "sysconf", Fn: etcSysconf, Arity: 1})
	mod.DefineMethod("getpwuid", &object.Method{Name: "getpwuid", Fn: etcGetpwuid, Arity: -1})
	mod.DefineMethod("getpwnam", &object.Method{Name: "getpwnam", Fn: etcGetpwnam, Arity: 1})
	mod.DefineMethod("passwd", &object.Method{Name: "passwd", Fn: etcPasswd, Arity: 0})
	mod.DefineMethod("endpwent", &object.Method{Name: "endpwent", Fn: etcEndpwent, Arity: 0})
	mod.DefineMethod("getgrgid", &object.Method{Name: "getgrgid", Fn: etcGetgrgid, Arity: -1})
	mod.DefineMethod("getgrnam", &object.Method{Name: "getgrnam", Fn: etcGetgrnam, Arity: 1})
	mod.DefineMethod("getgrent", &object.Method{Name: "getgrent", Fn: etcGetgrent, Arity: 0})
	mod.DefineMethod("group", &object.Method{Name: "group", Fn: etcGroup, Arity: 0})
	mod.DefineMethod("endgrent", &object.Method{Name: "endgrent", Fn: etcEndgrent, Arity: 0})
	modValue := &object.EmeraldValue{Type: object.ValueModule, Data: mod, Class: R.Classes["Module"]}
	csPath := newInt(0)
	mod.DefineConstant("CS_PATH", csPath)
	for index, name := range []string{
		"SC_ARG_MAX", "SC_CHILD_MAX", "SC_HOST_NAME_MAX", "SC_LOGIN_NAME_MAX", "SC_NGROUPS_MAX",
		"SC_CLK_TCK", "SC_OPEN_MAX", "SC_PAGESIZE", "SC_RE_DUP_MAX", "SC_STREAM_MAX",
		"SC_SYMLOOP_MAX", "SC_TTY_NAME_MAX", "SC_TZNAME_MAX", "SC_VERSION",
	} {
		mod.DefineConstant(name, newInt(int64(index)))
	}
	passwdClass := object.NewClass("Etc::Passwd")
	passwdClass.SuperClass = R.Classes["Struct"]
	passwdClass.DefineMethod("name", &object.Method{Name: "name", Fn: etcPasswdName, Arity: 0})
	passwdClass.DefineMethod("passwd", &object.Method{Name: "passwd", Fn: etcPasswdPassword, Arity: 0})
	passwdClass.DefineMethod("uid", &object.Method{Name: "uid", Fn: etcPasswdUID, Arity: 0})
	passwdClass.DefineMethod("gid", &object.Method{Name: "gid", Fn: etcPasswdGID, Arity: 0})
	passwdClass.DefineMethod("gecos", &object.Method{Name: "gecos", Fn: etcPasswdGecos, Arity: 0})
	passwdClass.DefineMethod("dir", &object.Method{Name: "dir", Fn: etcPasswdDir, Arity: 0})
	passwdClass.DefineMethod("shell", &object.Method{Name: "shell", Fn: etcPasswdShell, Arity: 0})
	passwdClass.DefineMethod("==", &object.Method{Name: "==", Fn: etcPasswdEqual, Arity: 1})
	R.Classes["Etc::Passwd"] = passwdClass
	passwdValue := &object.EmeraldValue{Type: object.ValueClass, Data: passwdClass, Class: R.Classes["Class"]}
	mod.DefineConstant("Passwd", passwdValue)
	groupClass := object.NewClass("Etc::Group")
	groupClass.SuperClass = R.Classes["Struct"]
	groupClass.DefineMethod("name", &object.Method{Name: "name", Fn: etcGroupName, Arity: 0})
	groupClass.DefineMethod("passwd", &object.Method{Name: "passwd", Fn: etcGroupPassword, Arity: 0})
	groupClass.DefineMethod("gid", &object.Method{Name: "gid", Fn: etcGroupGID, Arity: 0})
	groupClass.DefineMethod("mem", &object.Method{Name: "mem", Fn: etcGroupMem, Arity: 0})
	groupClass.DefineMethod("==", &object.Method{Name: "==", Fn: etcGroupEqual, Arity: 1})
	R.Classes["Etc::Group"] = groupClass
	groupValue := &object.EmeraldValue{Type: object.ValueClass, Data: groupClass, Class: R.Classes["Class"]}
	mod.DefineConstant("Group", groupValue)
	objectClass.DefineConstant("Etc", modValue)
	AssignConstantName(&object.EmeraldValue{Type: object.ValueClass, Data: objectClass, Class: R.Classes["Class"]}, "Etc", modValue)
	AssignConstantName(modValue, "CS_PATH", csPath)
	AssignConstantName(modValue, "Passwd", passwdValue)
	AssignConstantName(modValue, "Group", groupValue)
}

func etcUname(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	values := map[string]string{
		"sysname":  runtime.GOOS,
		"nodename": "",
		"release":  "",
		"version":  "",
		"machine":  runtime.GOARCH,
	}
	if hostname, err := os.Hostname(); err == nil {
		values["nodename"] = hostname
	}
	var uts syscall.Utsname
	if err := syscall.Uname(&uts); err == nil {
		values["sysname"] = utsnameString(uts.Sysname[:])
		values["nodename"] = utsnameString(uts.Nodename[:])
		values["release"] = utsnameString(uts.Release[:])
		values["version"] = utsnameString(uts.Version[:])
		values["machine"] = utsnameString(uts.Machine[:])
	}
	keys := []*object.EmeraldValue{}
	pairs := map[*object.EmeraldValue]*object.EmeraldValue{}
	for _, name := range []string{"sysname", "nodename", "release", "version", "machine"} {
		key := &object.EmeraldValue{Type: object.ValueSymbol, Data: name, Class: R.Classes["Symbol"]}
		keys = append(keys, key)
		pairs[key] = rubyString(values[name])
	}
	return &object.EmeraldValue{
		Type:  object.ValueHash,
		Data:  &object.RHash{Pairs: pairs, Keys: keys, InstanceVars: map[string]*object.EmeraldValue{}},
		Class: R.Classes["Hash"],
	}
}

func etcSysconf(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 1 || args[0] == nil || args[0].Type != object.ValueInteger {
		return NewTypeError("no implicit conversion into Integer")
	}
	switch args[0].Data.(int64) {
	case 5:
		return newInt(100)
	case 6:
		return newInt(1024)
	case 7:
		return newInt(int64(os.Getpagesize()))
	default:
		return newInt(1)
	}
}

func utsnameString(chars []int8) string {
	var buf []byte
	for _, ch := range chars {
		if ch == 0 {
			break
		}
		buf = append(buf, byte(ch))
	}
	return string(buf)
}

func etcNprocessors(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	count := runtime.GOMAXPROCS(0)
	if count < 1 {
		count = 1
	}
	return newInt(int64(count))
}

func etcConfstr(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 0 {
		return NewArgumentError("wrong number of arguments")
	}
	value, ok := valueToInteger(args[0])
	if !ok {
		return NewTypeError("can't convert " + valueTypeName(args[0]) + " into Integer")
	}
	if value != 0 {
		return newRuntimeException(R.Classes["Errno::EINVAL"], "Invalid argument")
	}
	return rubyString("/bin:/usr/bin")
}

func etcCurrentPasswdData() etcPasswdData {
	uid := int64(os.Getuid())
	gid := int64(os.Getgid())
	name := os.Getenv("USER")
	dir := os.Getenv("HOME")
	if current, err := osuser.Current(); err == nil && current != nil {
		if current.Username != "" {
			name = current.Username
			if idx := strings.LastIndex(name, "\\"); idx >= 0 {
				name = name[idx+1:]
			}
		}
		if parsed, err := strconv.ParseInt(current.Uid, 10, 64); err == nil {
			uid = parsed
		}
		if parsed, err := strconv.ParseInt(current.Gid, 10, 64); err == nil {
			gid = parsed
		}
		if current.HomeDir != "" {
			dir = current.HomeDir
		}
	}
	if name == "" {
		name = "unknown"
	}
	return etcPasswdData{Name: name, Passwd: "x", UID: uid, GID: gid, Gecos: "", Dir: dir, Shell: os.Getenv("SHELL")}
}

