	if group, err := osuser.LookupGroupId(strconv.FormatInt(gid, 10)); err == nil && group != nil && group.Name != "" {
		name = group.Name
	}
	if name == "" {
		name = "unknown"
	}
	return etcGroupData{Name: name, Passwd: "x", GID: gid, Mem: []*object.EmeraldValue{}}
