func etcGroup(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	group := newEtcGroupValue(etcCurrentGroupData())
	if CurrentBlockValue == nil || BlockGivenCheck == nil || !BlockGivenCheck() {
		return group
	}
	if etcGroupIterating {
		return NewRuntimeError("parallel group iteration")
	}
	etcGroupIterating = true
	defer func() { etcGroupIterating = false }()
	if CallBlockWithArgs != nil {
		result := CallBlockWithArgs(CurrentBlockValue(), group)
		if result != nil && result.Type == object.ValueException {
			return result
		}
	}
	return R.NilVal
}

