func singletonModuleIncluded(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 0 || args[0] == nil || args[0].Type != object.ValueClass {
		return R.NilVal
	}
	klass := args[0].Data.(*object.Class)
	klass.DefineClassMethod("instance", &object.Method{Name: "instance", Fn: singletonClassInstance, Arity: 0})
	klass.DefineClassMethod("new", &object.Method{Name: "new", Fn: singletonPrivateConstructor, Arity: -1, Visibility: "private"})
	klass.DefineClassMethod("allocate", &object.Method{Name: "allocate", Fn: singletonPrivateConstructor, Arity: -1, Visibility: "private"})
	return R.NilVal
}

func singletonClassInstance(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver == nil || receiver.Type != object.ValueClass {
		return R.NilVal
	}
	klass := receiver.Data.(*object.Class)
	if klass.InstanceVars == nil {
		klass.InstanceVars = map[string]*object.EmeraldValue{}
	}
	if instance := klass.InstanceVars["@__rgo_singleton_instance"]; instance != nil {
		return instance
	}
	instance := &object.EmeraldValue{
		Type: object.ValueObject,
		Data: &object.Object{
			Class:            klass,
			InstanceVars:     map[string]*object.EmeraldValue{},
			SingletonMethods: map[string]*object.Method{},
		},
		Class: klass,
	}
	klass.InstanceVars["@__rgo_singleton_instance"] = instance
	return instance
}

