func builtinOpen(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 0 {
		return argumentError("wrong number of arguments")
	}
	fileClass := R.Classes["File"]
	if fileClass == nil {
		return newRuntimeException(R.Classes["TypeError"], "uninitialized constant File")
	}
	if len(args) > 0 {
		path := args[0]
		if path != nil && path.Type != object.ValueString {
			if CallMethod != nil && receiverHasCallableMethod(path, "to_open") {
				opened := CallMethod(path, "to_open", args[1:]...)
				if opened != nil && opened.Type == object.ValueException {
					return opened
				}
				if BlockGivenCheck != nil && BlockGivenCheck() && opened != nil && CurrentBlockValue != nil && CallBlockWithArgs != nil {
					block := CurrentBlockValue()
					if block != nil {
						return CallBlockWithArgs(block, opened)
					}
				}
				return opened
			}
			if _, errVal := coercePath(path); errVal != nil {
				return errVal
			}
		}
	}
	return fileClassOpen(&object.EmeraldValue{Type: object.ValueClass, Data: fileClass, Class: R.Classes["Class"]}, args...)
}

func builtinLoad(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) < 1 {
		return argumentError("wrong number of arguments")
	}
	if len(args) > 2 {
		return argumentError("wrong number of arguments")
	}
	path, errVal := coercePath(args[0])
	if errVal != nil {
		return errVal
	}
	resolvedPath := path
	if ResolveLoadPath != nil {
		if resolved := ResolveLoadPath(path); resolved != "" {
			resolvedPath = resolved
		}
	}
	content, err := os.ReadFile(resolvedPath)
	if err != nil {
		return newRuntimeException(R.Classes["LoadError"], "cannot load such file -- "+path)
	}
	var wrapModule *object.EmeraldValue
	if len(args) > 1 && args[1] != nil {
		switch args[1].Type {
		case object.ValueModule:
			wrapModule = args[1]
		case object.ValueBool:
			if isTruthy(args[1]) {
				wrapModule = &object.EmeraldValue{Type: object.ValueModule, Data: object.NewModule(""), Class: R.Classes["Module"]}
			}
		}
	}
	prevException := LastException
	prevSpecFile := CurrentSpecFile
	prevSpecFileAbsolute := CurrentSpecFileAbsolute
	CurrentSpecFile = resolvedPath
	CurrentSpecFileAbsolute, _ = filepath.Abs(resolvedPath)
	if realPath, err := filepath.EvalSymlinks(CurrentSpecFileAbsolute); err == nil {
		CurrentSpecFileAbsolute = realPath
	}
	defer func() {
		CurrentSpecFile = prevSpecFile
		CurrentSpecFileAbsolute = prevSpecFileAbsolute
	}()
	if EvalSource == nil {
		return newRuntimeException(R.Classes["LoadError"], "load unavailable")
	}
	var result *object.EmeraldValue
	if wrapModule != nil && EvalSourceWithBinding != nil {
		wrappedSelf := loadWrappedTopLevelSelf(wrapModule)
		module := wrapModule.Data.(*object.Module)
		priorVisibility, hadVisibility := module.InstanceVars["@__visibility"]
		module.SetInstanceVar("@__visibility", rubyString("private"))
		result = EvalSourceWithBinding(string(content), &object.RBinding{
			Self:         wrappedSelf,
			Locals:       map[string]*object.EmeraldValue{},
			ClassStack:   []*object.EmeraldValue{wrapModule},
			Path:         resolvedPath,
			Line:         1,
			InstanceVars: map[string]*object.EmeraldValue{},
		})
		if hadVisibility {
			module.InstanceVars["@__visibility"] = priorVisibility
		} else {
			delete(module.InstanceVars, "@__visibility")
		}
	} else {
		result = EvalSource(string(content))
	}
	if result != nil && result.Type == object.ValueException {
		return result
	}
	if LastException != nil && LastException != prevException {
		return LastException
	}
	return R.TrueVal
}

func loadWrappedTopLevelSelf(wrapModule *object.EmeraldValue) *object.EmeraldValue {
	mainObject, ok := R.Main.Data.(*object.Object)
	if !ok || mainObject == nil {
		return R.Main
	}
	copyObject := object.NewObject(mainObject.Class)
	copyObject.StructValues = append([]*object.EmeraldValue(nil), mainObject.StructValues...)
	for name, value := range mainObject.InstanceVars {
		copyObject.InstanceVars[name] = value
	}
	for name, value := range mainObject.ClassVars {
		copyObject.ClassVars[name] = value
	}
	for name, method := range mainObject.SingletonMethods {
		copyObject.SingletonMethods[name] = method
	}
	copyValue := &object.EmeraldValue{Type: object.ValueObject, Data: copyObject, Class: R.Main.Class}
	copyObject.SingletonClass = cloneSingletonClass(mainObject.SingletonClass, copyValue)
	singleton := SingletonClass(copyValue)
	if singleton != nil && singleton.Type == object.ValueClass && wrapModule != nil && wrapModule.Type == object.ValueModule {
		class := singleton.Data.(*object.Class)
		class.IncludedModules = append(class.IncludedModules, wrapModule.Data.(*object.Module))
	}
	return copyValue
}

func builtinCaller(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	frames := currentBacktraceFramesOrEmpty()
	if len(frames) < 3 {
		frames = maybeInsertMspecRunnerFrame(frames, true)
	}
	frames, nilResult, err := backtraceFramesFromList(frames, 1, args...)
	if err != nil {
		return err
	}
	if nilResult {
		return R.NilVal
	}
	for i := range frames {
		if separator := strings.LastIndexAny(frames[i].Label, "#."); separator >= 0 {
			frames[i].Label = frames[i].Label[separator+1:]
		}
	}
	return backtraceStringsValue(frames)
}

func builtinCallerLocations(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	frames := currentBacktraceFramesOrEmpty()
	if len(frames) < 3 {
		frames = maybeInsertMspecRunnerFrame(frames, true)
	}
	frames, nilResult, err := backtraceFramesFromList(frames, 1, args...)
	if err != nil {
		return err
	}
	if nilResult {
		return R.NilVal
	}
	return backtraceLocationsValue(frames)
}

func builtinGlobalVariables(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	variableSet := make(map[string]struct{})
	addName := func(name string) {
		if name == "" {
			return
		}
		resolved := ResolveGlobalAlias(name)
		if resolved == "" {
			resolved = name
		}
		variableSet[resolved] = struct{}{}
	}
	if GlobalVariableNames != nil {
		for _, name := range GlobalVariableNames() {
			addName(name)
		}
	}
	defaultNames := []string{
		"$LOAD_PATH", "$:", "$LOADED_FEATURES", "$\"", "$VERBOSE", "$DEBUG", "$stderr", "$stdout", "$stdin",
		"$0", "$?", "$.", "$/", "$\\", "$,", "$_", "$~", "$!", "$&", "$`", "$'", "$+", "$*",
	}
	for _, name := range defaultNames {
		addName(name)
	}
	names := make([]string, 0, len(variableSet))
	for name := range variableSet {
		names = append(names, name)
	}
	sort.Strings(names)
	values := make([]*object.EmeraldValue, len(names))
	for i, name := range names {
		values[i] = &object.EmeraldValue{
			Type:  object.ValueSymbol,
			Data:  name,
			Class: R.Classes["Symbol"],
		}
	}
	return &object.EmeraldValue{
		Type:  object.ValueArray,
		Data:  values,
		Class: R.Classes["Array"],
	}
}

func builtinWarn(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if GetGlobalVariable != nil {
		verbose := GetGlobalVariable("$VERBOSE")
		if verbose == nil || verbose == R.NilVal || verbose.Type == object.ValueNil {
			return R.NilVal
		}
	}
	uplevel := -1
	category := R.NilVal
	warnArgs := args
	if n := len(args); n > 0 {
		last := args[n-1]
		if last != nil && last.Type == object.ValueHash {
			options := valueToHashMap(last)
			if len(options) == 0 {
				warnArgs = args[:n-1]
			}
			for key, value := range options {
				switch specName(key) {
				case "uplevel":
					warnArgs = args[:n-1]
					if value == nil || value.Type == object.ValueNil {
						uplevel = -1
						continue
					}
					level, ok := valueToInteger(value)
					if !ok {
						return typeError("wrong argument type")
					}
					if level < 0 {
						return NewArgumentError("warning position must be non-negative")
					}
					uplevel = int(level)
				case "category":
					warnArgs = args[:n-1]
					if value == nil || value.Type == object.ValueNil {
						category = R.NilVal
						continue
					}
					if value.Type == object.ValueSymbol {
						category = value
						continue
					}
					if CallMethod == nil || value.Class == nil || !receiverHasCallableMethod(value, "to_sym") {
						return typeError("wrong argument type")
					}
					converted := CallMethod(value, "to_sym")
					if converted != nil && converted.Type == object.ValueException {
						return converted
					}
					if converted == nil || converted.Type != object.ValueSymbol {
						return typeError("wrong argument type")
					}
					category = converted
				}
			}
		}
	}
	expanded := make([]*object.EmeraldValue, 0, len(warnArgs))
	for _, value := range warnArgs {
		if array, ok := valueToArray(value); ok {
			expanded = append(expanded, array...)
		} else {
			expanded = append(expanded, value)
		}
	}
	prefix := ""
	if uplevel >= 0 {
		frames := currentBacktraceFramesOrEmpty()
		if uplevel < len(frames) {
			frame := frames[uplevel]
			prefix = fmt.Sprintf("%s:%d: warning: ", frame.Path, frame.Line)
		}
	}
	for _, value := range expanded {
		message := prefix + warningString(value)
		if !strings.HasSuffix(message, "\n") {
			message += "\n"
		}
		if result := dispatchWarning(receiver, rubyString(message), category); result != nil && result.Type == object.ValueException {
			return result
		}
	}
	return R.NilVal
}

func warningModuleValue() *object.EmeraldValue {
	if R == nil || R.Classes["Object"] == nil {
		return nil
	}
	return R.Classes["Object"].Constants["Warning"]
}

func dispatchWarning(receiver, message, category *object.EmeraldValue) *object.EmeraldValue {
	warning := warningModuleValue()
	if warning == nil || receiver == warning || CallMethod == nil {
		return warningModuleWarn(warning, message)
	}
	args := []*object.EmeraldValue{message}
	if warningWarnAcceptsKeywords(warning) {
		key := &object.EmeraldValue{Type: object.ValueSymbol, Data: "category", Class: R.Classes["Symbol"]}
		options := &object.EmeraldValue{Type: object.ValueHash, Data: map[*object.EmeraldValue]*object.EmeraldValue{key: category}, Class: R.Classes["Hash"]}
		MarkRuby2KeywordHash(options)
		args = append(args, options)
	}
	return CallMethod(warning, "warn", args...)
}

func warningWarnAcceptsKeywords(warning *object.EmeraldValue) bool {
	if CallMethod == nil {
		return false
	}
	methodValue := CallMethod(warning, "method", &object.EmeraldValue{Type: object.ValueSymbol, Data: "warn", Class: R.Classes["Symbol"]})
	if methodValue == nil || methodValue.Type != object.ValueMethod {
		return false
	}
	method, ok := methodValue.Data.(*object.Method)
	if !ok || method == nil {
		return false
	}
	if fn, ok := method.Fn.(*object.Function); ok && fn != nil {
		return len(fn.KeywordParams) > 0 || fn.KeywordRestParam != ""
	}
	return true
}

func warningModuleWarn(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 0 {
		return R.NilVal
	}
	if category := warningCategoryOption(args); category != nil && category.Type != object.ValueNil {
		name, errVal := warningCategoryName(category)
		if errVal != nil {
			return errVal
		}
		if !warningCategoryEnabled(name) {
			return R.NilVal
		}
	}
	message := warningString(args[0])
	_, _ = fmt.Fprint(os.Stderr, message)
	return R.NilVal
}

func warningModuleGet(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 1 {
		return NewArgumentError("wrong number of arguments")
	}
	name, errVal := warningCategoryName(args[0])
	if errVal != nil {
		return errVal
	}
	return boolValue(warningCategoryEnabled(name))
}

func warningModuleSet(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 2 {
		return NewArgumentError("wrong number of arguments")
	}
	name, errVal := warningCategoryName(args[0])
	if errVal != nil {
		return errVal
	}
	warning := warningModuleValue()
	if warning != nil && warning.Type == object.ValueModule {
		warning.Data.(*object.Module).SetInstanceVar("@__warning_"+name, boolValue(args[1] != nil && args[1].IsTruthy()))
	}
	return args[1]
}

func warningCategoryName(value *object.EmeraldValue) (string, *object.EmeraldValue) {
	if value == nil || value.Type != object.ValueSymbol {
		return "", typeError("category must be a Symbol")
	}
	name, _ := value.Data.(string)
	switch name {
	case "deprecated", "experimental", "performance":
		return name, nil
	default:
		return "", NewArgumentError("unknown category: " + name)
	}
}

func warningCategoryEnabled(name string) bool {
	warning := warningModuleValue()
	if warning == nil || warning.Type != object.ValueModule {
		return false
	}
	value := warning.Data.(*object.Module).GetInstanceVar("@__warning_" + name)
	return value != nil && value.IsTruthy()
}

func warningCategoryOption(args []*object.EmeraldValue) *object.EmeraldValue {
	if len(args) < 2 {
		return nil
	}
	last := args[len(args)-1]
	if last == nil || last.Type != object.ValueHash {
		return nil
	}
	for key, value := range valueToHashMap(last) {
		if specName(key) == "category" {
			return value
		}
	}
	return nil
}

func warningString(value *object.EmeraldValue) string {
	if value == nil || value.Type == object.ValueNil {
		return "nil"
	}
	if value.Type == object.ValueString || value.Type == object.ValueSymbol {
		return value.Data.(string)
	}
	if CallMethod != nil && value.Class != nil {
		if method, hasToString := value.Class.GetMethod("to_s"); hasToString && method != nil {
			text := CallMethod(value, "to_s")
			if text != nil && text.Type == object.ValueString {
				return text.Data.(string)
			}
			if text != nil && text.Type == object.ValueException {
				return text.Inspect()
			}
		}
	}
	return value.Inspect()
}

func builtinAtExit(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if BlockGivenCheck == nil || !BlockGivenCheck() || CurrentBlockValue == nil {
		return NewArgumentError("called without a block")
	}
	block := CurrentBlockValue()
	if block == nil {
		return NewArgumentError("called without a block")
	}
	RegisterAtExitHook(block)
	return R.NilVal
}

func builtinTraceVar(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 0 {
		return NewArgumentError("wrong number of arguments")
	}
	name := globalVariableTraceName(args[0])
	if name == "" {
		return typeError("wrong argument type")
	}
	trace := globalVariableTrace{}
	if len(args) > 1 {
		switch args[1].Type {
		case object.ValueProc:
			trace.handler = args[1]
		case object.ValueString:
			trace.source = args[1].Data.(string)
		default:
			return typeError("wrong argument type")
		}
	} else {
		if CurrentBlockValue == nil || CurrentBlockValue() == nil {
			return NewArgumentError("tried to create Proc object without a block")
		}
		trace.handler = CurrentBlockValue()
	}
	if globalVariableTraces == nil {
		globalVariableTraces = make(map[string][]globalVariableTrace)
	}
	globalVariableTraces[name] = append(globalVariableTraces[name], trace)
	return R.NilVal
}

func builtinUntraceVar(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 0 {
		return NewArgumentError("wrong number of arguments")
	}
	name := globalVariableTraceName(args[0])
	if name == "" {
		return typeError("wrong argument type")
	}
	delete(globalVariableTraces, name)
	return R.NilVal
}

func globalVariableTraceName(value *object.EmeraldValue) string {
	name := specName(value)
	if name == "" {
		return ""
	}
	if !strings.HasPrefix(name, "$") {
		name = "$" + name
	}
	return ResolveGlobalAlias(name)
}

func NotifyGlobalVariableSet(name string, value *object.EmeraldValue) {
	resolved := ResolveGlobalAlias(name)
	if resolved == "$~" {
		if data, ok := matchDataPayload(value); ok {
			updateMatchDataDerivedGlobals(data)
		} else {
			clearMatchDataDerivedGlobals()
		}
	}
	if resolved == "$;" && value != nil && value.Type != object.ValueNil {
		dispatchWarning(R.Main, rubyString("warning: $; is deprecated\n"), rubySymbol("deprecated"))
	}
	if globalVariableTraces == nil {
		return
	}
	traces := append([]globalVariableTrace(nil), globalVariableTraces[resolved]...)
	if len(traces) == 0 && resolved != name {
		traces = append(traces, globalVariableTraces[name]...)
	}
	for _, trace := range traces {
		if trace.handler != nil && CallBlockWithArgs != nil {
			CallBlockWithArgs(trace.handler, value)
			continue
		}
		if trace.source != "" && EvalSource != nil {
			EvalSource(trace.source)
		}
	}
}

func builtinEND(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if BlockGivenCheck == nil || !BlockGivenCheck() || CurrentBlockValue == nil {
		return newRuntimeException(R.Classes["LocalJumpError"], "no block given")
	}
	block := CurrentBlockValue()
	if block == nil {
		return newRuntimeException(R.Classes["LocalJumpError"], "no block given")
	}
	RegisterEndHook(block)
	return R.NilVal
}

func builtinSetTraceFunc(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	old := setTraceFuncValue
	if old == nil {
		old = R.NilVal
	}
	if len(args) != 1 {
		return NewArgumentError("wrong number of arguments")
	}
	setTraceFuncValue = args[0]
	if args[0] != nil && args[0].Type != object.ValueNil {
		traceProc := args[0]
		if traceProc.Type != object.ValueProc && CallMethod != nil && traceProc.Class != nil {
			if method, hasToProc := traceProc.Class.GetMethod("to_proc"); hasToProc && method != nil {
				coerced := CallMethod(traceProc, "to_proc")
				if coerced != nil && coerced.Type == object.ValueException {
					return coerced
				}
				if coerced != nil {
					setTraceFuncValue = coerced
				}
			}
		}
	} else {
		setTraceFuncValue = R.NilVal
	}
	return old
}

func builtinRand(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 0 {
		return &object.EmeraldValue{
			Type:  object.ValueFloat,
			Data:  kernelRand.Float64(),
			Class: R.Classes["Float"],
		}
	}
	if len(args) != 1 {
		return NewArgumentError("wrong number of arguments")
	}
	arg := args[0]
	if arg == nil || arg.Type == object.ValueNil {
		return typeError("no implicit conversion into Integer")
	}
	if arg.Type == object.ValueRange {
		rangeValue, ok := arg.Data.(*object.RRange)
		if !ok {
			return typeError("wrong type")
		}
		return builtinRandRange(rangeValue)
	}
	if arg.Type == object.ValueFloat {
		return builtinRandFloat(arg.Data.(float64))
	}

	max, err := valueToRandInteger(arg)
	if err != nil {
		return err
	}
	return builtinRandInt(max)
}

func builtinSrand(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	previousSeed := kernelRandSeed
	switch len(args) {
	case 0:
		seed := time.Now().UnixNano()
		seedRand(seed)
	case 1:
		seedValue := args[0]
		if seedValue == nil || seedValue.Type == object.ValueNil {
			return typeError("no implicit conversion to Integer")
		}
		seed, err := valueToRandInteger(seedValue)
		if err != nil {
			return err
		}
		seedRand(seed)
	default:
		return NewArgumentError("wrong number of arguments")
	}
	return &object.EmeraldValue{
		Type:  object.ValueInteger,
		Data:  previousSeed,
		Class: R.Classes["Integer"],
	}
}

func builtinRandFloat(max float64) *object.EmeraldValue {
	if max < 0 {
		max = -max
	}
	if max == 0 {
		return &object.EmeraldValue{
			Type:  object.ValueFloat,
			Data:  kernelRand.Float64(),
			Class: R.Classes["Float"],
		}
	}
	if max < 1.0 {
		return &object.EmeraldValue{
			Type:  object.ValueFloat,
			Data:  kernelRand.Float64() * max,
			Class: R.Classes["Float"],
		}
	}
	return builtinRandInt(int64(max))
}

func builtinRandInt(max int64) *object.EmeraldValue {
	if max < 0 {
		max = -max
	}
	if max == 0 {
		return &object.EmeraldValue{
			Type:  object.ValueFloat,
			Data:  kernelRand.Float64(),
			Class: R.Classes["Float"],
		}
	}
	if max == 1 {
		return &object.EmeraldValue{
			Type:  object.ValueInteger,
			Data:  int64(0),
			Class: R.Classes["Integer"],
		}
	}
	return &object.EmeraldValue{
		Type:  object.ValueInteger,
		Data:  kernelRand.Int63n(max),
		Class: R.Classes["Integer"],
	}
}

func builtinRandRange(r *object.RRange) *object.EmeraldValue {
	if r == nil {
		return R.NilVal
	}

	startValue, startOk := r.StartValue.(*object.EmeraldValue)
	endValue, endOk := r.EndValue.(*object.EmeraldValue)
	if !startOk || !endOk || startValue == nil || endValue == nil {
		if r.StartFloat || r.EndFloat {
			start := r.StartRaw
			end := r.EndRaw
			if !r.StartFloat {
				start = float64(r.Start)
			}
			if !r.EndFloat {
				end = float64(r.End)
			}
			return builtinRandRangeFloat(start, end, r.Exclusive)
		}
		return builtinRandRangeInt(r.Start, r.End, r.Exclusive)
	}

	if isPrimitiveNumericValue(startValue) && isPrimitiveNumericValue(endValue) {
		if r.StartFloat || r.EndFloat {
			start := r.StartRaw
			end := r.EndRaw
			if !r.StartFloat {
				start = float64(r.Start)
			}
			if !r.EndFloat {
				end = float64(r.End)
			}
			return builtinRandRangeFloat(start, end, r.Exclusive)
		}
		return builtinRandRangeInt(r.Start, r.End, r.Exclusive)
	}

	return builtinRandRangeCustom(startValue, endValue, r.Exclusive)
}

func builtinRandRangeInt(start, end int64, exclusive bool) *object.EmeraldValue {
	if exclusive {
		if start >= end {
			return R.NilVal
		}
		size := end - start
		return &object.EmeraldValue{
			Type:  object.ValueInteger,
			Data:  kernelRand.Int63n(size) + start,
			Class: R.Classes["Integer"],
		}
	}
	if start > end {
		return R.NilVal
	}
	if start == end {
		return &object.EmeraldValue{
			Type:  object.ValueInteger,
			Data:  start,
			Class: R.Classes["Integer"],
		}
	}
	return &object.EmeraldValue{
		Type:  object.ValueInteger,
		Data:  kernelRand.Int63n(end-start+1) + start,
		Class: R.Classes["Integer"],
	}
}

func builtinRandRangeFloat(start, end float64, exclusive bool) *object.EmeraldValue {
	if exclusive {
		if start >= end {
			return R.NilVal
		}
		return &object.EmeraldValue{
			Type:  object.ValueFloat,
			Data:  start + kernelRand.Float64()*(end-start),
			Class: R.Classes["Float"],
		}
	}
	if start > end {
		return R.NilVal
	}
	if start == end {
		return &object.EmeraldValue{
			Type:  object.ValueFloat,
			Data:  start,
			Class: R.Classes["Float"],
		}
	}
	return &object.EmeraldValue{
		Type:  object.ValueFloat,
		Data:  start + kernelRand.Float64()*(end-start),
		Class: R.Classes["Float"],
	}
}

func builtinRandRangeCustom(start, end *object.EmeraldValue, exclusive bool) *object.EmeraldValue {
	if isRangeValueFloat(start) || isRangeValueFloat(end) {
		startFloat, startErr := valueToFloat(start)
		if startErr != nil {
			if startErr.Type == object.ValueException {
				return startErr
			}
		}
		endFloat, endErr := valueToFloat(end)
		if endErr != nil {
			if endErr.Type == object.ValueException {
				return endErr
			}
		}
		if startErr == nil && endErr == nil {
			result := startFloat + kernelRand.Float64()*(endFloat-startFloat)
			if exclusive {
				if startFloat >= endFloat {
					return R.NilVal
				}
			} else {
				if startFloat > endFloat {
					return R.NilVal
				}
				if startFloat == endFloat {
					return start
				}
			}
			return addToValue(start, &object.EmeraldValue{
				Type:  object.ValueFloat,
				Data:  result,
				Class: R.Classes["Float"],
			})
		}
	}

	startInt, startErr := valueToRandInteger(start)
	if startErr != nil {
		return startErr
	}
	endInt, endErr := valueToRandInteger(end)
	if endErr != nil {
		return endErr
	}
	if exclusive {
		if startInt >= endInt {
			return R.NilVal
		}
		return addToValue(start, &object.EmeraldValue{
			Type:  object.ValueInteger,
			Data:  kernelRand.Int63n(endInt - startInt),
			Class: R.Classes["Integer"],
		})
	}
	if startInt > endInt {
		return R.NilVal
	}
	if startInt == endInt {
		return start
	}
	return addToValue(start, &object.EmeraldValue{
		Type:  object.ValueInteger,
		Data:  kernelRand.Int63n(endInt - startInt + 1),
		Class: R.Classes["Integer"],
	})
}

func addToValue(receiver, addend *object.EmeraldValue) *object.EmeraldValue {
	if receiver == nil || addend == nil || CallMethod == nil {
		return typeError("no implicit conversion into Integer")
	}
	value := CallMethod(receiver, "+", addend)
	if value == nil {
		return typeError("no implicit conversion into Integer")
	}
	return value
}

func isPrimitiveNumericValue(value *object.EmeraldValue) bool {
	if value == nil {
		return false
	}
	return value.Type == object.ValueInteger || value.Type == object.ValueFloat
}

func isRangeValueFloat(value *object.EmeraldValue) bool {
	if value == nil {
		return false
	}
	if value.Type == object.ValueFloat {
		return true
	}
	if value.Type != object.ValueInteger && receiverHasCallableMethod(value, "to_f") {
		return true
	}
	return false
}

func valueToRandInteger(value *object.EmeraldValue) (int64, *object.EmeraldValue) {
	if value == nil {
		return 0, typeError("no implicit conversion into Integer")
	}
	switch v := value.Data.(type) {
	case int64:
		return v, nil
	case float64:
		return int64(v), nil
	}
	if CallMethod == nil || value.Class == nil || !receiverHasCallableMethod(value, "to_int") {
		return 0, typeError("no implicit conversion into Integer")
	}
	converted := CallMethod(value, "to_int")
	if converted == nil {
		return 0, typeError("no implicit conversion into Integer")
	}
	if converted.Type == object.ValueException {
		return 0, converted
	}
	switch v := converted.Data.(type) {
	case int64:
		return v, nil
	case float64:
		return int64(v), nil
	}
	return 0, typeError("no implicit conversion into Integer")
}

func valueToFloat(value *object.EmeraldValue) (float64, *object.EmeraldValue) {
	if value == nil {
		return 0, typeError("no implicit conversion into Float")
	}
	switch v := value.Data.(type) {
	case int64:
		return float64(v), nil
	case float64:
		return v, nil
	}
	if CallMethod == nil || value.Class == nil || !receiverHasCallableMethod(value, "to_f") {
		return 0, typeError("no implicit conversion into Float")
	}
	converted := CallMethod(value, "to_f")
	if converted == nil {
		return 0, typeError("no implicit conversion into Float")
	}
	if converted.Type == object.ValueException {
		return 0, converted
	}
	switch v := converted.Data.(type) {
	case int64:
		return float64(v), nil
	case float64:
		return v, nil
	}
	return 0, typeError("no implicit conversion into Float")
}

func seedRand(seed int64) {
	kernelRandSeed = seed
	kernelRand = rand.New(rand.NewSource(seed))
	kernelRubyRand = newRubyMT19937(big.NewInt(seed))
}

func kernelConversionExceptionFalse(args []*object.EmeraldValue) ([]*object.EmeraldValue, bool) {
	if len(args) == 0 {
		return args, false
	}
	last := args[len(args)-1]
	if last == nil || last.Type != object.ValueHash {
		return args, false
	}
	options := valueToHashMap(last)
	value, ok := hashLookup(options, rubySymbol("exception"))
	if !ok {
		value, ok = hashLookup(options, rubyString(":exception"))
	}
	if ok {
		if value != nil && value.Type == object.ValueBool {
			if enabled, isBool := value.Data.(bool); isBool && !enabled {
				return args[:len(args)-1], true
			}
		}
	}
	return args, false
}

func kernelConversionResult(value *object.EmeraldValue, exceptionFalse bool) *object.EmeraldValue {
	if value != nil && value.Type == object.ValueException && exceptionFalse {
		return R.NilVal
	}
	return value
}

func builtinKernelFloat(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	args, exceptionFalse := kernelConversionExceptionFalse(args)
	if len(args) != 1 {
		return kernelConversionResult(NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 1)", len(args))), exceptionFalse)
	}
	value := args[0]
	if value == nil || value.Type == object.ValueNil {
		return kernelConversionResult(typeError("can't convert nil into Float"), exceptionFalse)
	}
	if value.Type == object.ValueFloat {
		return value
	}
	if value.Type == object.ValueInteger {
		if integer, ok := NumericBigIntOverride(value); ok {
			converted, _ := new(big.Float).SetInt(integer).Float64()
			return newFloat(converted)
		}
		return newFloat(float64(value.Data.(int64)))
	}
	if value.Type == object.ValueString {
		parsed, errVal := parseKernelFloatString(stringRawValue(value))
		if errVal != nil {
			return kernelConversionResult(errVal, exceptionFalse)
		}
		return newFloat(parsed)
	}
	if data, ok := value.Data.(*complexData); ok {
		if data.imag != 0 {
			return kernelConversionResult(NewRangeError("can't convert complex into float"), exceptionFalse)
		}
		return newFloat(data.real)
	}
	if CallMethod == nil || value.Class == nil || !receiverHasCallableMethod(value, "to_f") {
		return kernelConversionResult(typeError("can't convert "+value.TypeName()+" into Float"), exceptionFalse)
	}
	converted := CallMethod(value, "to_f")
	if converted == nil {
		return kernelConversionResult(typeError("can't convert "+value.TypeName()+" into Float"), exceptionFalse)
	}
	if converted.Type == object.ValueException {
		return kernelConversionResult(converted, exceptionFalse)
	}
	if converted.Type != object.ValueFloat {
		return kernelConversionResult(typeError("can't convert "+converted.TypeName()+" to Float"), exceptionFalse)
	}
	return converted
}

func builtinComplex(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	args, exceptionFalse := kernelConversionExceptionFalse(args)
	if len(args) == 0 || len(args) > 2 {
		return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 1..2)", len(args)))
	}
	if len(args) == 1 {
		if _, ok := args[0].Data.(*complexData); ok {
			return args[0]
		}
		if args[0] != nil && args[0].Type == object.ValueString {
			return kernelConversionResult(parseKernelComplexString(args[0]), exceptionFalse)
		}
		if args[0] != nil && CallMethod != nil && receiverHasCallableMethod(args[0], "to_c") {
			converted := CallMethod(args[0], "to_c")
			if converted != nil && converted.Type == object.ValueException {
				return kernelConversionResult(converted, exceptionFalse)
			}
			if converted != nil {
				if _, ok := converted.Data.(*complexData); ok {
					return converted
				}
			}
		}
	}
	if len(args) == 2 {
		left, leftComplex := args[0].Data.(*complexData)
		right, rightComplex := args[1].Data.(*complexData)
		if leftComplex && rightComplex && left != nil && right != nil {
			return newComplexFromValues(
				CallMethod(complexReal(args[0]), "-", complexImag(args[1])),
				CallMethod(complexImag(args[0]), "+", complexReal(args[1])),
			)
		}
	}
	if exceptionFalse && len(args) == 2 && args[1] != nil && (args[1].Type == object.ValueInteger || args[1].Type == object.ValueFloat) &&
		args[0] != nil && args[0].Type != object.ValueNil && args[0].Type != object.ValueInteger && args[0].Type != object.ValueFloat && args[0].Type != object.ValueString {
		return typeError("not a real")
	}
	real, errVal := complexPartAsFloat(args[0])
	if errVal != nil {
		return kernelConversionResult(errVal, exceptionFalse)
	}
	imag := 0.0
	imagFloat := false
	imagValue := newInt(0)
	if len(args) == 2 {
		imagFloat = args[1] != nil && args[1].Type == object.ValueFloat
		imagValue = args[1]
		imag, errVal = complexPartAsFloat(args[1])
		if errVal != nil {
			return kernelConversionResult(errVal, exceptionFalse)
		}
	}
	return &object.EmeraldValue{
		Type:   object.ValueObject,
		Data:   &complexData{real: real, imag: imag, imagFloat: imagFloat, realValue: args[0], imagValue: imagValue},
		Class:  R.Classes["Complex"],
		Frozen: true,
	}
}

func parseKernelComplexString(value *object.EmeraldValue) *object.EmeraldValue {
	encoding := stringEncodingName(value)
	if !encodingIsASCICompatible(encoding) {
		return newRuntimeException(R.Classes["Encoding::CompatibilityError"], "ASCII incompatible encoding: "+encoding)
	}
	raw := stringRawValue(value)
	if strings.ContainsRune(raw, '\x00') {
		return NewArgumentError("string contains null byte")
	}
	input := strings.TrimSpace(raw)
	invalid := func() *object.EmeraldValue {
		return NewArgumentError(fmt.Sprintf("invalid value for convert(): %q", raw))
	}
	if input == "" || !rubyNumericUnderscoresValid(input) {
		return invalid()
	}
	zero := newInt(0)
	if len(input) == 1 && isStringImaginaryUnit(input[0]) {
		return newComplexFromValues(zero, newInt(1))
	}
	if len(input) == 2 && (input[0] == '+' || input[0] == '-') && isStringImaginaryUnit(input[1]) {
		sign := int64(1)
		if input[0] == '-' {
			sign = -1
		}
		return newComplexFromValues(zero, newInt(sign))
	}
	first, end, ok := parseStringNumericPrefix(input, false)
	if !ok {
		return invalid()
	}
	if end == len(input) {
		return newComplexFromValues(first, zero)
	}
	if input[end] == '@' {
		angle, angleEnd, angleOK := parseStringNumericPrefix(input[end+1:], false)
		if angleOK && end+1+angleEnd == len(input) {
			return newComplexValue(complexComponentFloat(first)*math.Cos(complexComponentFloat(angle)), complexComponentFloat(first)*math.Sin(complexComponentFloat(angle)))
		}
		return invalid()
	}
	if end+1 == len(input) && isStringImaginaryUnit(input[end]) {
		return newComplexFromValues(zero, first)
	}
	if input[end] == '+' || input[end] == '-' {
		if end+2 == len(input) && isStringImaginaryUnit(input[end+1]) {
			sign := int64(1)
			if input[end] == '-' {
				sign = -1
			}
			return newComplexFromValues(first, newInt(sign))
		}
		imaginary, imaginaryEnd, imaginaryOK := parseStringNumericPrefix(input[end:], false)
		if imaginaryOK && end+imaginaryEnd+1 == len(input) && isStringImaginaryUnit(input[end+imaginaryEnd]) {
			return newComplexFromValues(first, imaginary)
		}
	}
	return invalid()
}

func complexToR(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data, ok := receiver.Data.(*complexData)
	if !ok || data == nil {
		return R.NilVal
	}
	if !complexImaginaryIsZero(receiver, true) {
		return NewRangeError(fmt.Sprintf("can't convert %g+%gi into Rational", data.real, data.imag))
	}
	if data.realValue != nil && CallMethod != nil && receiverHasCallableMethod(data.realValue, "to_r") {
		return CallMethod(data.realValue, "to_r")
	}
	return floatToR(newFloat(data.real))
}

func complexClassPolar(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) < 1 || len(args) > 2 {
		return NewArgumentError("wrong number of arguments")
	}
	radius, errVal := complexRealFloatArg(args[0])
	if errVal != nil {
		return errVal
	}
	angle := 0.0
	if len(args) == 2 {
		angle, errVal = complexRealFloatArg(args[1])
		if errVal != nil {
			return errVal
		}
	}
	return newComplexValue(radius*math.Cos(angle), radius*math.Sin(angle))
}

func complexRealFloatArg(value *object.EmeraldValue) (float64, *object.EmeraldValue) {
	if value == nil || value.Type == object.ValueNil {
		return 0, typeError("not a real")
	}
	if data, ok := value.Data.(*complexData); ok && data != nil {
		if data.imag != 0 {
			return 0, typeError("not a real")
		}
		return data.real, nil
	}
	switch value.Type {
	case object.ValueInteger:
		if integer, ok := NumericBigIntOverride(value); ok {
			converted, _ := new(big.Float).SetInt(integer).Float64()
			return converted, nil
		}
		return float64(value.Data.(int64)), nil
	case object.ValueFloat:
		return value.Data.(float64), nil
	default:
		return 0, typeError("not a real")
	}
}

func complexPolar(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data, ok := receiver.Data.(*complexData)
	if !ok || data == nil {
		return R.NilVal
	}
	values := []*object.EmeraldValue{newFloat(math.Hypot(data.real, data.imag)), newFloat(math.Atan2(data.imag, data.real))}
	return &object.EmeraldValue{Type: object.ValueArray, Data: values, Class: R.Classes["Array"]}
}

func complexClassRect(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) < 1 || len(args) > 2 {
		return NewArgumentError("wrong number of arguments")
	}
	for _, arg := range args {
		if !complexRectRealArg(arg) {
			return typeError("not a real")
		}
	}
	imag := newInt(0)
	if len(args) == 2 {
		imag = args[1]
	}
	realFloat, _ := complexRealFloatArg(args[0])
	imagFloat, _ := complexRealFloatArg(imag)
	return &object.EmeraldValue{
		Type: object.ValueObject,
		Data: &complexData{
			real:      realFloat,
			imag:      imagFloat,
			imagFloat: imag.Type == object.ValueFloat,
			realValue: args[0],
			imagValue: imag,
		},
		Class:  R.Classes["Complex"],
		Frozen: true,
	}
}

func complexRectRealArg(value *object.EmeraldValue) bool {
	if value == nil || value.Type == object.ValueNil || value.Type == object.ValueSymbol || value.Type == object.ValueString || value.Type == object.ValueArray {
		return false
	}
	if value.Type == object.ValueInteger || value.Type == object.ValueFloat {
		return true
	}
	if CallMethod != nil && receiverHasCallableMethod(value, "real?") {
		result := CallMethod(value, "real?")
		return result != nil && result.IsTruthy()
	}
	return false
}

func complexRect(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 0 {
		return NewArgumentError("wrong number of arguments")
	}
	return &object.EmeraldValue{
		Type:  object.ValueArray,
		Data:  []*object.EmeraldValue{complexReal(receiver), complexImag(receiver)},
		Class: R.Classes["Array"],
	}
}

func complexToF(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data, ok := receiver.Data.(*complexData)
	if !ok || data == nil {
		return R.NilVal
	}
	if !complexImaginaryIsZero(receiver, false) {
		return NewRangeError(fmt.Sprintf("can't convert %g+%gi into Float", data.real, data.imag))
	}
	if data.realValue != nil && CallMethod != nil && receiverHasCallableMethod(data.realValue, "to_f") {
		return CallMethod(data.realValue, "to_f")
	}
	return newFloat(data.real)
}

func complexRationalize(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) > 1 {
		return NewArgumentError("wrong number of arguments")
	}
	data, ok := receiver.Data.(*complexData)
	if !ok || data == nil {
		return R.NilVal
	}
	if data.imag != 0 || data.imagFloat {
		return NewRangeError(fmt.Sprintf("can't convert %g+%gi into Rational", data.real, data.imag))
	}
	if data.realValue != nil && CallMethod != nil && receiverHasCallableMethod(data.realValue, "rationalize") {
		return CallMethod(data.realValue, "rationalize", args...)
	}
	return builtinRational(receiver, newFloat(data.real))
}

func complexToI(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data, ok := receiver.Data.(*complexData)
	if !ok || data == nil {
		return R.NilVal
	}
	if !complexImaginaryIsZero(receiver, false) {
		return NewRangeError(fmt.Sprintf("can't convert %g+%gi into Integer", data.real, data.imag))
	}
	if data.realValue != nil && CallMethod != nil && receiverHasCallableMethod(data.realValue, "to_i") {
		return CallMethod(data.realValue, "to_i")
	}
	return newInt(int64(data.real))
}

func complexImaginaryIsZero(receiver *object.EmeraldValue, allowFloat bool) bool {
	data, ok := receiver.Data.(*complexData)
	if !ok || data == nil {
		return false
	}
	if data.imagValue == nil {
		return data.imag == 0 && (allowFloat || !data.imagFloat)
	}
	if data.imagValue.Type == object.ValueFloat && !allowFloat {
		return false
	}
	if CallMethod != nil {
		result := CallMethod(data.imagValue, "==", newInt(0))
		return result != nil && result.IsTruthy()
	}
	return data.imag == 0
}

func complexComponentFloat(value *object.EmeraldValue) float64 {
	if value == nil {
		return 0
	}
	if rational, ok := rationalValueData(value); ok {
		result, _ := new(big.Rat).SetFrac(rational.numerator, rational.denominator).Float64()
		return result
	}
	if value.Type == object.ValueInteger || value.Type == object.ValueFloat {
		if integer, ok := NumericBigIntOverride(value); ok {
			converted, _ := new(big.Float).SetInt(integer).Float64()
			return converted
		}
		return numericValueAsFloat(value)
	}
	if CallMethod != nil && receiverHasCallableMethod(value, "to_f") {
		converted := CallMethod(value, "to_f")
		if converted != nil && converted.Type == object.ValueFloat {
			return converted.Data.(float64)
		}
	}
	return 0
}

func newComplexFromValues(realValue, imagValue *object.EmeraldValue) *object.EmeraldValue {
	return &object.EmeraldValue{
		Type: object.ValueObject,
		Data: &complexData{
			real:      complexComponentFloat(realValue),
			imag:      complexComponentFloat(imagValue),
			imagFloat: imagValue != nil && imagValue.Type == object.ValueFloat,
			realValue: realValue,
			imagValue: imagValue,
		},
		Class:  R.Classes["Complex"],
		Frozen: true,
	}
}

func complexBinaryCoerce(receiver, other *object.EmeraldValue, operation string) *object.EmeraldValue {
	if CallMethod == nil || other == nil || !receiverHasCallableMethod(other, "coerce") {
		return typeError("can't be coerced into Complex")
	}
	coerced := CallMethod(other, "coerce", receiver)
	if coerced == nil || coerced.Type != object.ValueArray {
		return typeError("coerce must return [x, y]")
	}
	pair := coerced.Data.([]*object.EmeraldValue)
	if len(pair) != 2 {
		return typeError("coerce must return [x, y]")
	}
	return CallMethod(pair[0], operation, pair[1])
}

func complexAdd(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return complexAddSub(receiver, args, "+")
}

func complexSub(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return complexAddSub(receiver, args, "-")
}

func complexAddSub(receiver *object.EmeraldValue, args []*object.EmeraldValue, operation string) *object.EmeraldValue {
	if len(args) != 1 || args[0] == nil {
		return NewArgumentError("wrong number of arguments")
	}
	left, ok := receiver.Data.(*complexData)
	if !ok || left == nil {
		return R.NilVal
	}
	leftReal, leftImag := complexReal(receiver), complexImag(receiver)
	if right, ok := args[0].Data.(*complexData); ok && right != nil {
		return newComplexFromValues(CallMethod(leftReal, operation, complexReal(args[0])), CallMethod(leftImag, operation, complexImag(args[0])))
	}
	if complexRectRealArg(args[0]) {
		return newComplexFromValues(CallMethod(leftReal, operation, args[0]), leftImag)
	}
	return complexBinaryCoerce(receiver, args[0], operation)
}

func complexMul(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 1 || args[0] == nil {
		return NewArgumentError("wrong number of arguments")
	}
	a, b := complexReal(receiver), complexImag(receiver)
	if _, ok := args[0].Data.(*complexData); ok {
		c, d := complexReal(args[0]), complexImag(args[0])
		real := CallMethod(CallMethod(a, "*", c), "-", CallMethod(b, "*", d))
		imag := CallMethod(CallMethod(a, "*", d), "+", CallMethod(b, "*", c))
		return newComplexFromValues(real, imag)
	}
	if complexRectRealArg(args[0]) {
		return newComplexFromValues(CallMethod(a, "*", args[0]), CallMethod(b, "*", args[0]))
	}
	return complexBinaryCoerce(receiver, args[0], "*")
}

func complexPow(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 1 || args[0] == nil {
		return NewArgumentError("wrong number of arguments")
	}
	if exponent, ok := numericBigIntValue(args[0]); ok && exponent.IsInt64() {
		n := exponent.Int64()
		if n == 0 {
			if args[0].Type == object.ValueFloat {
				return newComplexFromValues(newFloat(1), newFloat(0))
			}
			return newComplexFromValues(newInt(1), newInt(0))
		}
		if n > 0 {
			result := newComplexFromValues(newInt(1), newInt(0))
			base := receiver
			for n > 0 {
				if n&1 == 1 {
					result = complexMul(result, base)
				}
				n >>= 1
				if n > 0 {
					base = complexMul(base, base)
				}
			}
			return result
		}
	}
	var exponent complex128
	if data, ok := args[0].Data.(*complexData); ok {
		exponent = complex(data.real, data.imag)
	} else if args[0].Type == object.ValueInteger || args[0].Type == object.ValueFloat || rationalValueIsNumeric(args[0]) {
		exponent = complex(complexComponentFloat(args[0]), 0)
	} else {
		return complexBinaryCoerce(receiver, args[0], "**")
	}
	data := receiver.Data.(*complexData)
	result := cmplx.Pow(complex(data.real, data.imag), exponent)
	return newComplexValue(real(result), imag(result))
}

func rationalValueIsNumeric(value *object.EmeraldValue) bool {
	_, ok := rationalValueData(value)
	return ok
}

func complexAbs2(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	real, imag := complexReal(receiver), complexImag(receiver)
	return CallMethod(CallMethod(real, "*", real), "+", CallMethod(imag, "*", imag))
}

func complexAbs(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data := receiver.Data.(*complexData)
	return newFloat(math.Hypot(data.real, data.imag))
}

func complexConjugate(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return newComplexFromValues(complexReal(receiver), CallMethod(complexImag(receiver), "-@"))
}

func complexNegate(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return newComplexFromValues(CallMethod(complexReal(receiver), "-@"), CallMethod(complexImag(receiver), "-@"))
}

func complexToC(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return receiver
}

func complexComponentString(value *object.EmeraldValue, inspect bool) string {
	method := "to_s"
	if inspect {
		method = "inspect"
	}
	if CallMethod != nil {
		result := CallMethod(value, method)
		if result != nil && result.Type == object.ValueString {
			return stringRawValue(result)
		}
	}
	return value.Inspect()
}

func complexFormat(receiver *object.EmeraldValue, inspect bool) string {
	realValue, imagValue := complexReal(receiver), complexImag(receiver)
	realText := complexComponentString(realValue, inspect)
	imagFloat := complexComponentFloat(imagValue)
	negative := imagFloat < 0 || math.Signbit(imagFloat)
	absImag := imagValue
	if negative && CallMethod != nil {
		absImag = CallMethod(imagValue, "-@")
	}
	imagText := complexComponentString(absImag, inspect)
	suffix := "i"
	if len(imagText) == 0 || imagText[len(imagText)-1] < '0' || imagText[len(imagText)-1] > '9' {
		suffix = "*i"
	}
	separator := "+"
	if negative {
		separator = "-"
	}
	text := realText + separator + imagText + suffix
	if inspect {
		text = "(" + text + ")"
	}
	return text
}

func complexToS(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return rubyString(complexFormat(receiver, false))
}

func complexInspect(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return rubyString(complexFormat(receiver, true))
}

func complexHash(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data := receiver.Data.(*complexData)
	bits := math.Float64bits(data.real) ^ bitsRotateLeft(math.Float64bits(data.imag), 1)
	return newInt(int64(bits^bits>>32) ^ processHashSalt)
}

func bitsRotateLeft(value uint64, shift uint) uint64 {
	return value<<shift | value>>(64-shift)
}

func complexInfinite(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data := receiver.Data.(*complexData)
	if math.IsNaN(data.real) || math.IsNaN(data.imag) {
		return R.NilVal
	}
	if math.IsInf(data.real, 0) {
		if math.IsInf(data.real, -1) {
			return newInt(-1)
		}
		return newInt(1)
	}
	if math.IsInf(data.imag, 0) {
		if math.IsInf(data.imag, -1) {
			return newInt(-1)
		}
		return newInt(1)
	}
	return R.NilVal
}

func complexDenominator(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	realDen := CallMethod(complexReal(receiver), "denominator")
	imagDen := CallMethod(complexImag(receiver), "denominator")
	return CallMethod(realDen, "lcm", imagDen)
}

func complexNumerator(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	denominator := complexDenominator(receiver)
	return newComplexFromValues(CallMethod(complexReal(receiver), "*", denominator), CallMethod(complexImag(receiver), "*", denominator))
}

func complexDiv(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 1 {
		return NewArgumentError("wrong number of arguments")
	}
	left, ok := receiver.Data.(*complexData)
	if !ok || left == nil || args[0] == nil {
		return R.NilVal
	}
	switch args[0].Type {
	case object.ValueInteger:
		den := args[0].Data.(int64)
		if den == 0 {
			return newRuntimeException(R.Classes["ZeroDivisionError"], "divided by 0")
		}
		return newComplexValue(left.real/float64(den), left.imag/float64(den))
	case object.ValueFloat:
		den := args[0].Data.(float64)
		return newComplexValue(left.real/den, left.imag/den)
	}
	if right, ok := args[0].Data.(*complexData); ok && right != nil {
		a, b := complexReal(receiver), complexImag(receiver)
		c, d := complexReal(args[0]), complexImag(args[0])
		den := CallMethod(CallMethod(c, "*", c), "+", CallMethod(d, "*", d))
		if equal := CallMethod(den, "==", newInt(0)); equal != nil && equal.IsTruthy() {
			return newRuntimeException(R.Classes["ZeroDivisionError"], "divided by 0")
		}
		return newComplexFromValues(
			CallMethod(CallMethod(CallMethod(a, "*", c), "+", CallMethod(b, "*", d)), "/", den),
			CallMethod(CallMethod(CallMethod(b, "*", c), "-", CallMethod(a, "*", d)), "/", den),
		)
	}
	if complexRectRealArg(args[0]) {
		return newComplexFromValues(CallMethod(complexReal(receiver), "quo", args[0]), CallMethod(complexImag(receiver), "quo", args[0]))
	}
	return complexBinaryCoerce(receiver, args[0], "/")
}

func complexFdiv(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 1 {
		return NewArgumentError("wrong number of arguments")
	}
	data, ok := receiver.Data.(*complexData)
	if !ok || data == nil || args[0] == nil {
		return R.NilVal
	}
	switch args[0].Type {
	case object.ValueInteger, object.ValueFloat:
		den := complexComponentFloat(args[0])
		return newComplexValue(data.real/den, data.imag/den)
	default:
		return typeError("not a numeric")
	}
}

func newComplexValue(real, imag float64) *object.EmeraldValue {
	return &object.EmeraldValue{
		Type:   object.ValueObject,
		Data:   &complexData{real: real, imag: imag},
		Class:  R.Classes["Complex"],
		Frozen: true,
	}
}

func complexReal(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if data, ok := receiver.Data.(*complexData); ok && data != nil {
		if data.realValue != nil {
			return data.realValue
		}
		return newFloat(data.real)
	}
	return R.NilVal
}

func complexMarshalDump(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return &object.EmeraldValue{Type: object.ValueArray, Data: []*object.EmeraldValue{complexReal(receiver), complexImag(receiver)}, Class: R.Classes["Array"]}
}

func complexFalsePredicate(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return R.FalseVal
}

func complexImag(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if data, ok := receiver.Data.(*complexData); ok && data != nil {
		if data.imagValue != nil {
			return data.imagValue
		}
		return newFloat(data.imag)
	}
	return R.NilVal
}

func complexEqual(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 1 {
		return R.FalseVal
	}
	left, ok := receiver.Data.(*complexData)
	if !ok || left == nil {
		return R.FalseVal
	}
	if args[0] != nil && (args[0].Type == object.ValueInteger || args[0].Type == object.ValueFloat) {
		imaginaryZero := CallMethod(complexImag(receiver), "==", newInt(0))
		realEqual := CallMethod(complexReal(receiver), "==", args[0])
		if imaginaryZero != nil && imaginaryZero.IsTruthy() && realEqual != nil && realEqual.IsTruthy() {
			return R.TrueVal
		}
		return R.FalseVal
	}
	right, ok := args[0].Data.(*complexData)
	if !ok || right == nil {
		if CallMethod != nil && args[0] != nil && receiverHasCallableMethod(args[0], "real?") {
			real := CallMethod(args[0], "real?")
			if real != nil && real.Type == object.ValueException {
				return real
			}
			if isTruthy(real) {
				if !isTruthy(CallMethod(complexImag(receiver), "==", newInt(0))) {
					return R.FalseVal
				}
				return CallMethod(complexReal(receiver), "==", args[0])
			}
		}
		if CallMethod != nil && args[0] != nil && receiverHasCallableMethod(args[0], "==") {
			return CallMethod(args[0], "==", receiver)
		}
		return R.FalseVal
	}
	realEqual := CallMethod(complexReal(receiver), "==", complexReal(args[0]))
	imagEqual := CallMethod(complexImag(receiver), "==", complexImag(args[0]))
	if realEqual != nil && realEqual.IsTruthy() && imagEqual != nil && imagEqual.IsTruthy() {
		return R.TrueVal
	}
	return R.FalseVal
}

func complexEql(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 1 || args[0] == nil || args[0].Class != R.Classes["Complex"] {
		return R.FalseVal
	}
	leftReal, rightReal := complexReal(receiver), complexReal(args[0])
	leftImag, rightImag := complexImag(receiver), complexImag(args[0])
	if leftReal == nil || rightReal == nil || leftImag == nil || rightImag == nil || leftReal.Class != rightReal.Class || leftImag.Class != rightImag.Class {
		return R.FalseVal
	}
	realEqual := CallMethod(leftReal, "==", rightReal)
	imagEqual := CallMethod(leftImag, "==", rightImag)
	return boolValue(isTruthy(realEqual) && isTruthy(imagEqual))
}

func complexCompare(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 1 || args[0] == nil || !complexImaginaryIsZero(receiver, true) {
		return R.NilVal
	}
	if other, ok := args[0].Data.(*complexData); ok {
		if other == nil || !complexImaginaryIsZero(args[0], true) {
			return R.NilVal
		}
		return CallMethod(complexReal(receiver), "<=>", complexReal(args[0]))
	}
	if args[0].Type == object.ValueInteger || args[0].Type == object.ValueFloat || rationalValueIsNumeric(args[0]) {
		return CallMethod(complexReal(receiver), "<=>", args[0])
	}
	return R.NilVal
}

func floatsEqualForComplex(left, right float64) bool {
	if left == right {
		return true
	}
	diff := math.Abs(left - right)
	scale := math.Max(1, math.Max(math.Abs(left), math.Abs(right)))
	return diff <= scale*1e-12
}

func complexCoerce(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 1 || args[0] == nil {
		return typeError("can't convert into Complex")
	}
	if _, ok := args[0].Data.(*complexData); ok {
		return &object.EmeraldValue{Type: object.ValueArray, Data: []*object.EmeraldValue{args[0], receiver}, Class: R.Classes["Array"]}
	}
	switch args[0].Type {
	case object.ValueInteger, object.ValueFloat:
		return &object.EmeraldValue{Type: object.ValueArray, Data: []*object.EmeraldValue{builtinComplex(receiver, args[0]), receiver}, Class: R.Classes["Array"]}
	case object.ValueString, object.ValueSymbol, object.ValueNil, object.ValueBool, object.ValueArray:
		return typeError("can't convert into Complex")
	default:
		if !complexRectRealArg(args[0]) {
			return typeError("can't convert into Complex")
		}
		return &object.EmeraldValue{Type: object.ValueArray, Data: []*object.EmeraldValue{builtinComplex(receiver, args[0]), receiver}, Class: R.Classes["Array"]}
	}
}

func complexPartAsFloat(value *object.EmeraldValue) (float64, *object.EmeraldValue) {
	if value == nil || value.Type == object.ValueNil {
		return 0, typeError("can't convert nil into Complex")
	}
	switch value.Type {
	case object.ValueInteger:
		if integer, ok := NumericBigIntOverride(value); ok {
			converted, _ := new(big.Float).SetInt(integer).Float64()
			return converted, nil
		}
		return float64(value.Data.(int64)), nil
	case object.ValueFloat:
		return value.Data.(float64), nil
	case object.ValueString:
		encoding := strings.ToUpper(stringEncodingName(value))
		if strings.HasPrefix(encoding, "UTF-16") || strings.HasPrefix(encoding, "UTF-32") {
			return 0, newRuntimeException(R.Classes["Encoding::CompatibilityError"], "ASCII incompatible encoding: "+stringEncodingName(value))
		}
		return 0, NewArgumentError("invalid value for Complex()")
	default:
		if CallMethod != nil && receiverHasCallableMethod(value, "real?") {
			result := CallMethod(value, "real?")
			if result != nil && result.IsTruthy() {
				return 0, nil
			}
		}
		return 0, typeError("can't convert " + value.TypeName() + " into Complex")
	}
}

func parseKernelFloatString(raw string) (float64, *object.EmeraldValue) {
	if strings.ContainsRune(raw, '\x00') {
		return 0, NewArgumentError(fmt.Sprintf("invalid value for Float(): %q", raw))
	}
	trimmed := strings.TrimSpace(raw)
	if trimmed == "" {
		return 0, NewArgumentError(fmt.Sprintf("invalid value for Float(): %q", raw))
	}
	if strings.ContainsAny(trimmed, " \t\n\r\v\f") {
		return 0, NewArgumentError(fmt.Sprintf("invalid value for Float(): %q", raw))
	}
	if !rubyNumericUnderscoresValid(trimmed) {
		return 0, NewArgumentError(fmt.Sprintf("invalid value for Float(): %q", raw))
	}
	normalized := strings.ReplaceAll(trimmed, "_", "")
	if sign := 1.0; strings.HasPrefix(normalized, "0x") || strings.HasPrefix(normalized, "0X") ||
		strings.HasPrefix(normalized, "+0x") || strings.HasPrefix(normalized, "+0X") ||
		strings.HasPrefix(normalized, "-0x") || strings.HasPrefix(normalized, "-0X") {
		digits := normalized
		if strings.HasPrefix(digits, "-") {
			sign = -1
			digits = digits[1:]
		} else if strings.HasPrefix(digits, "+") {
			digits = digits[1:]
		}
		if integer, ok := new(big.Int).SetString(digits[2:], 16); ok {
			converted, _ := new(big.Float).SetInt(integer).Float64()
			return sign * converted, nil
		}
	}
	parseText := normalized
	if strings.Contains(strings.ToLower(parseText), "0x") && !strings.ContainsAny(parseText, "pP") {
		parseText += "p0"
	}
	value, err := strconv.ParseFloat(parseText, 64)
	if err != nil {
		if numErr, ok := err.(*strconv.NumError); ok && numErr.Err == strconv.ErrRange {
			return value, nil
		}
		return 0, NewArgumentError(fmt.Sprintf("invalid value for Float(): %q", raw))
	}
	return value, nil
}

func builtinKernelInteger(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	args, exceptionFalse := kernelConversionExceptionFalse(args)
	if len(args) < 1 || len(args) > 2 {
		return kernelConversionResult(NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 1..2)", len(args))), exceptionFalse)
	}
	value := args[0]
	if value == nil || value.Type == object.ValueNil {
		return kernelConversionResult(typeError("can't convert nil into Integer"), exceptionFalse)
	}
	base := int64(0)
	if len(args) == 2 {
		parsedBase, ok := valueToInteger(args[1])
		if !ok {
			return kernelConversionResult(typeError("base must be an integer"), exceptionFalse)
		}
		base = parsedBase
	}
	if value.Type != object.ValueString && len(args) == 2 {
		return kernelConversionResult(NewArgumentError("base specified for non string value"), exceptionFalse)
	}
	switch value.Type {
	case object.ValueInteger:
		return value
	case object.ValueFloat:
		f := value.Data.(float64)
		if math.IsNaN(f) {
			return kernelConversionResult(newRuntimeException(R.Classes["FloatDomainError"], "NaN"), exceptionFalse)
		}
		if math.IsInf(f, 0) {
			return kernelConversionResult(newRuntimeException(R.Classes["FloatDomainError"], "Infinity"), exceptionFalse)
		}
		integer, _ := new(big.Float).SetFloat64(f).Int(nil)
		return NewIntegerFromBigInt(integer)
	case object.ValueString:
		parsed, errVal := parseKernelIntegerString(stringRawValue(value), base)
		if errVal != nil {
			return kernelConversionResult(errVal, exceptionFalse)
		}
		return newInt(parsed)
	}
	if CallMethod != nil && receiverHasCallableMethod(value, "to_int") {
		converted := CallMethod(value, "to_int")
		if converted != nil && converted.Type == object.ValueException {
			return kernelConversionResult(converted, exceptionFalse)
		}
		if converted != nil && converted.Type == object.ValueInteger {
			return converted
		}
	}
	if CallMethod != nil && receiverHasCallableMethod(value, "to_i") {
		converted := CallMethod(value, "to_i")
		if converted != nil && converted.Type == object.ValueException {
			return kernelConversionResult(converted, exceptionFalse)
		}
		if converted != nil && converted.Type == object.ValueInteger {
			return converted
		}
	}
	return kernelConversionResult(typeError("can't convert "+value.TypeName()+" into Integer"), exceptionFalse)
}

func parseKernelIntegerString(raw string, base int64) (int64, *object.EmeraldValue) {
	if strings.ContainsRune(raw, '\x00') {
		return 0, NewArgumentError(fmt.Sprintf("invalid value for Integer(): %q", raw))
	}
	trimmed := strings.TrimSpace(raw)
	if trimmed == "" {
		return 0, NewArgumentError(fmt.Sprintf("invalid value for Integer(): %q", raw))
	}
	if !rubyNumericUnderscoresValid(trimmed) {
		return 0, NewArgumentError(fmt.Sprintf("invalid value for Integer(): %q", raw))
	}
	if base != 0 && (base < 2 || base > 36) {
		return 0, NewArgumentError("invalid radix")
	}
	sign := ""
	digits := trimmed
	if strings.HasPrefix(digits, "+") || strings.HasPrefix(digits, "-") {
		sign = digits[:1]
		digits = digits[1:]
	}
	parseBase := int(base)
	if parseBase == 0 {
		parseBase = 10
		switch {
		case strings.HasPrefix(digits, "0x") || strings.HasPrefix(digits, "0X"):
			parseBase = 16
			digits = digits[2:]
		case strings.HasPrefix(digits, "0b") || strings.HasPrefix(digits, "0B"):
			parseBase = 2
			digits = digits[2:]
		case strings.HasPrefix(digits, "0o") || strings.HasPrefix(digits, "0O"):
			parseBase = 8
			digits = digits[2:]
		case strings.HasPrefix(digits, "0d") || strings.HasPrefix(digits, "0D"):
			parseBase = 10
			digits = digits[2:]
		case len(digits) > 1 && strings.HasPrefix(digits, "0"):
			parseBase = 8
		}
	} else if parseBase == 16 && (strings.HasPrefix(digits, "0x") || strings.HasPrefix(digits, "0X")) {
		digits = digits[2:]
	} else if parseBase == 2 && (strings.HasPrefix(digits, "0b") || strings.HasPrefix(digits, "0B")) {
		digits = digits[2:]
	} else if parseBase == 8 && (strings.HasPrefix(digits, "0o") || strings.HasPrefix(digits, "0O")) {
		digits = digits[2:]
	} else if parseBase == 10 && (strings.HasPrefix(digits, "0d") || strings.HasPrefix(digits, "0D")) {
		digits = digits[2:]
	}
	if digits == "" {
		return 0, NewArgumentError(fmt.Sprintf("invalid value for Integer(): %q", raw))
	}
	normalized := sign + strings.ReplaceAll(digits, "_", "")
	value, err := strconv.ParseInt(normalized, parseBase, 64)
	if err != nil {
		return 0, NewArgumentError(fmt.Sprintf("invalid value for Integer(): %q", raw))
	}
	return value, nil
}

func rubyNumericUnderscoresValid(s string) bool {
	prevUnderscore := false
	prevDigitOrLetter := false
	for i, r := range s {
		isDigitOrLetter := (r >= '0' && r <= '9') || (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z')
		if r == '_' {
			if i == 0 || prevUnderscore || !prevDigitOrLetter {
				return false
			}
			prevUnderscore = true
			prevDigitOrLetter = false
			continue
		}
		if (r == 'e' || r == 'E' || r == 'p' || r == 'P' || r == 'x' || r == 'X') && (prevUnderscore || (i+1 < len(s) && s[i+1] == '_')) {
			return false
		}
		if prevUnderscore && !isDigitOrLetter {
			return false
		}
		prevUnderscore = false
		prevDigitOrLetter = isDigitOrLetter
	}
	return !prevUnderscore
}

func builtinRational(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	args, exceptionFalse := kernelConversionExceptionFalse(args)
	if len(args) == 0 {
		return newRationalValue(big.NewInt(0), big.NewInt(1))
	}
	if len(args) > 2 {
		return kernelConversionResult(NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 0..2)", len(args))), exceptionFalse)
	}
	numerator, errVal := kernelRationalOperand(args[0], true)
	if errVal != nil {
		return kernelConversionResult(errVal, exceptionFalse)
	}
	if len(args) == 1 {
		return numerator
	}
	denominator, errVal := kernelRationalOperand(args[1], false)
	if errVal != nil {
		return kernelConversionResult(errVal, exceptionFalse)
	}
	result := CallMethod(numerator, "/", denominator)
	return kernelConversionResult(result, exceptionFalse)
}

func kernelRationalOperand(value *object.EmeraldValue, numerator bool) (*object.EmeraldValue, *object.EmeraldValue) {
	if value == nil || value.Type == object.ValueNil || value.Type == object.ValueSymbol {
		return nil, typeError("can't convert " + valueTypeNameForConversion(value) + " into Rational")
	}
	if _, ok := rationalValueData(value); ok {
		return value, nil
	}
	if value.Type == object.ValueInteger {
		integer, _ := numericBigIntValue(value)
		return newRationalValue(integer, big.NewInt(1)), nil
	}
	if value.Type == object.ValueFloat {
		floating := value.Data.(float64)
		if math.IsNaN(floating) || math.IsInf(floating, 0) {
			return nil, newRuntimeException(R.Classes["FloatDomainError"], value.Inspect())
		}
		ratio := new(big.Rat).SetFloat64(floating)
		return newRationalValue(ratio.Num(), ratio.Denom()), nil
	}
	if value.Type == object.ValueString {
		text := strings.ReplaceAll(strings.TrimSpace(stringRawValue(value)), "_", "")
		parsed, ok := new(big.Rat).SetString(text)
		if !ok {
			return nil, NewArgumentError(fmt.Sprintf("invalid value for Rational(): %q", stringRawValue(value)))
		}
		return newRationalValue(parsed.Num(), parsed.Denom()), nil
	}
	if data, ok := value.Data.(*complexData); ok && data != nil {
		if data.imag != 0 && numerator {
			return nil, NewRangeError(fmt.Sprintf("can't convert %g+%gi into Rational", data.real, data.imag))
		}
		if data.imag == 0 {
			return kernelRationalOperand(complexReal(value), numerator)
		}
		return value, nil
	}
	if CallMethod != nil && receiverHasCallableMethod(value, "to_r") {
		converted := CallMethod(value, "to_r")
		if converted != nil && converted.Type == object.ValueException {
			return nil, converted
		}
		if _, ok := rationalValueData(converted); ok {
			return converted, nil
		}
		got := "nil"
		if converted != nil {
			got = converted.TypeName()
		}
		return nil, typeError("can't convert " + value.TypeName() + " into Rational (" + value.TypeName() + "#to_r gives " + got + ")")
	}
	if CallMethod != nil && receiverHasCallableMethod(value, "to_int") {
		converted := CallMethod(value, "to_int")
		if converted != nil && converted.Type == object.ValueInteger {
			return kernelRationalOperand(converted, numerator)
		}
		return nil, typeError("can't convert " + value.TypeName() + " into Rational")
	}
	return nil, typeError("can't convert " + value.TypeName() + " into Rational")
}

func builtinRationalLegacy(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 0 {
		return &object.EmeraldValue{Type: object.ValueInteger, Data: int64(0), Class: R.Classes["Integer"]}
	}
	if len(args) > 2 {
		return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 1..2)", len(args)))
	}
	if len(args) == 1 {
		if _, ok := rationalValueData(args[0]); ok {
			return args[0]
		}
	}
	if args[0] == nil || args[0].Type == object.ValueNil || args[0].Type == object.ValueSymbol {
		return typeError("can't convert " + valueTypeNameForConversion(args[0]) + " into Rational")
	}
	if len(args) > 1 && (args[1] == nil || args[1].Type == object.ValueNil || args[1].Type == object.ValueSymbol) {
		return typeError("can't convert " + valueTypeNameForConversion(args[1]) + " into Rational")
	}
	if len(args) == 1 && args[0].Type == object.ValueString {
		text := strings.ReplaceAll(strings.TrimSpace(args[0].Data.(string)), "_", "")
		parsed, parsedOK := new(big.Rat).SetString(text)
		if !parsedOK {
			return NewArgumentError(fmt.Sprintf("invalid value for Rational(): %q", args[0].Data.(string)))
		}
		return newRationalValue(parsed.Num(), parsed.Denom())
	}
	if args[0].Type != object.ValueInteger && args[0].Type != object.ValueFloat {
		if data, ok := args[0].Data.(*complexData); ok {
			if data.imag != 0 {
				return NewRangeError(fmt.Sprintf("can't convert %g+%gi into Rational", data.real, data.imag))
			}
			args[0] = &object.EmeraldValue{Type: object.ValueFloat, Data: data.real, Class: R.Classes["Float"]}
		}
	}
	if args[0].Type != object.ValueInteger && args[0].Type != object.ValueFloat && CallMethod != nil && ReceiverHasCallableMethod(args[0], "to_r") {
		converted := CallMethod(args[0], "to_r")
		if converted != nil && converted.Type == object.ValueException {
			return converted
		}
		if _, ok := rationalValueData(converted); !ok {
			return typeError("can't convert " + args[0].TypeName() + " into Rational")
		}
		return converted
	}
	if args[0].Type != object.ValueInteger && args[0].Type != object.ValueFloat {
		return typeError("can't convert " + args[0].TypeName() + " into Rational")
	}
	if len(args) > 1 && args[1].Type != object.ValueInteger && args[1].Type != object.ValueFloat {
		return typeError("can't convert " + args[1].TypeName() + " into Rational")
	}
	if args[0].Type == object.ValueInteger && (len(args) == 1 || args[1].Type == object.ValueInteger) {
		numerator, _ := numericBigIntValue(args[0])
		denominator := big.NewInt(1)
		if len(args) == 2 && args[1] != nil && args[1].Type != object.ValueNil {
			denominator, _ = numericBigIntValue(args[1])
		}
		if denominator.Sign() == 0 {
			return newRuntimeException(R.Classes["ZeroDivisionError"], "divided by 0")
		}
		return newRationalValue(numerator, denominator)
	}
	if len(args) == 1 && args[0].Type == object.ValueFloat {
		value := args[0].Data.(float64)
		if math.IsNaN(value) || math.IsInf(value, 0) {
			return newRuntimeException(R.Classes["FloatDomainError"], args[0].Inspect())
		}
		ratio := new(big.Rat).SetFloat64(value)
		return newRationalValue(ratio.Num(), ratio.Denom())
	}
	numerator := rationalArgumentAsFloat(args[0])
	denominator := 1.0
	if len(args) > 1 {
		denominator = rationalArgumentAsFloat(args[1])
	}
	if denominator == 0 {
		return newRuntimeException(R.Classes["ZeroDivisionError"], "divided by 0")
	}
	result := numerator / denominator
	if math.Trunc(result) == result {
		return &object.EmeraldValue{Type: object.ValueInteger, Data: int64(result), Class: R.Classes["Integer"]}
	}
	return &object.EmeraldValue{Type: object.ValueFloat, Data: result, Class: R.Classes["Float"]}
}

func rationalArgumentAsFloat(value *object.EmeraldValue) float64 {
	if value != nil && value.Type == object.ValueInteger {
		n := value.Data.(int64)
		if n < math.MinInt64/2 {
			return float64(uint64(n))
		}
	}
	return numericValueAsFloat(value)
}

func valueTypeNameForConversion(value *object.EmeraldValue) string {
	if value == nil || value.Type == object.ValueNil {
		return "nil"
	}
	return value.TypeName()
}

func numericValueAsFloat(value *object.EmeraldValue) float64 {
	if value == nil {
		return 0
	}
	if integer, ok := NumericBigIntOverride(value); ok {
		converted, _ := new(big.Float).SetInt(integer).Float64()
		return converted
	}
	if override, ok := NumericFloatOverride(value); ok {
		return override
	}
	switch value.Type {
	case object.ValueInteger:
		return float64(value.Data.(int64))
	case object.ValueFloat:
		return value.Data.(float64)
	default:
		return 0
	}
}

func numericValueAsFloatOK(value *object.EmeraldValue) (float64, bool) {
	if value == nil {
		return 0, false
	}
	if integer, ok := NumericBigIntOverride(value); ok {
		converted, _ := new(big.Float).SetInt(integer).Float64()
		return converted, true
	}
	if override, ok := NumericFloatOverride(value); ok {
		return override, true
	}
	switch value.Type {
	case object.ValueInteger:
		return float64(value.Data.(int64)), true
	case object.ValueFloat:
		return value.Data.(float64), true
	default:
		return 0, false
	}
}

func builtinRaise(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	var message string
	var excClass *object.Class
	var exc *object.EmeraldValue
	constructFromClass := false
	previousException := LastException
	cause, hasCause, causeErr := raiseCauseKeyword(args)
	if causeErr != nil {
		return causeErr
	}
	if !hasCause && previousException != nil && InRescue != nil && InRescue() {
		cause = previousException
		hasCause = true
	}
	positionalArgs := args
	if hasCause && len(args) > 0 && args[len(args)-1].Type == object.ValueHash && raiseHashHasCauseKeyword(args[len(args)-1]) {
		positionalArgs = args[:len(args)-1]
	}

	if len(positionalArgs) == 0 && hasCause {
		return argumentError("only cause is given with no arguments")
	}

	if len(positionalArgs) > 3 {
		return NewArgumentError("wrong number of arguments")
	}
	if len(positionalArgs) > 1 {
		switch positionalArgs[0].Type {
		case object.ValueException, object.ValueClass:
		case object.ValueString:
			return typeError("exception class/object expected")
		default:
			return typeError("exception class/object expected")
		}
	}

	switch len(positionalArgs) {
	case 0:
		if LastException != nil {
			return LastException
		}
		message = ""
		excClass = R.Classes["RuntimeError"]
	case 1:
		switch positionalArgs[0].Type {
		case object.ValueException:
			if hasCause && cause != nil && cause.Type != object.ValueNil {
				if err := setExceptionCause(positionalArgs[0], cause); err != nil {
					return err
				}
			}
			fillExceptionBacktrace(positionalArgs[0])
			if exc, ok := positionalArgs[0].Data.(*object.RException); ok && exc != nil {
				exc.Raised = true
			}
			LastException = positionalArgs[0]
			LastMatcherException = positionalArgs[0]
			return positionalArgs[0]
		case object.ValueString:
			message = positionalArgs[0].Data.(string)
			excClass = R.Classes["RuntimeError"]
		case object.ValueClass:
			excClass = positionalArgs[0].Data.(*object.Class)
			if excClass == nil || !classInheritsFrom(excClass, R.Classes["Exception"]) {
				return typeError("exception class/object expected")
			}
			constructFromClass = true
		default:
			if CallMethod != nil && receiverHasCallableMethod(positionalArgs[0], "exception") {
				converted := CallMethod(positionalArgs[0], "exception")
				if converted != nil && converted.Type == object.ValueException {
					if hasCause {
						if err := setExceptionCause(converted, cause); err != nil {
							return err
						}
					}
					fillExceptionBacktrace(converted)
					LastException = converted
					LastMatcherException = converted
					return converted
				}
				return typeError("exception object expected")
			}
			return typeError("exception class/object expected")
		}
	case 2, 3:
		if positionalArgs[0].Type == object.ValueClass {
			excClass = positionalArgs[0].Data.(*object.Class)
			if excClass == nil || !classInheritsFrom(excClass, R.Classes["Exception"]) {
				return typeError("exception class/object expected")
			}
			constructFromClass = true
		} else {
			return typeError("exception class/object expected")
		}
		if positionalArgs[1] != nil && positionalArgs[1].Type == object.ValueString {
			message = stringRawValue(positionalArgs[1])
		} else {
			message = positionalArgs[1].Inspect()
		}
	default:
		exc = NewArgumentError("wrong number of arguments")
	}
	if exc != nil {
		return exc
	}
	if excClass == nil {
		excClass = R.Classes["RuntimeError"]
	}
	if constructFromClass {
		classValue := &object.EmeraldValue{Type: object.ValueClass, Data: excClass, Class: R.Classes["Class"]}
		if len(positionalArgs) > 1 {
			exc = classNew(classValue, positionalArgs[1])
		} else {
			exc = classNew(classValue)
		}
		if exc == nil || exc.Type != object.ValueException {
			return typeError("exception object expected")
		}
		fillExceptionBacktrace(exc)
		if data, ok := exc.Data.(*object.RException); ok {
			data.Raised = true
		}
		LastException = exc
	} else {
		exc = newRuntimeException(excClass, message)
	}
	if len(positionalArgs) == 3 {
		if result := exceptionSetBacktrace(exc, positionalArgs[2]); result != nil && result.Type == object.ValueException {
			return result
		}
	}
	if hasCause {
		if err := setExceptionCause(exc, cause); err != nil {
			return err
		}
	}
	LastException = exc
	LastMatcherException = exc
	return exc
}

func RaiseValue(value *object.EmeraldValue) *object.EmeraldValue {
	return builtinRaise(nil, value)
}

func raiseCauseKeyword(args []*object.EmeraldValue) (*object.EmeraldValue, bool, *object.EmeraldValue) {
	if len(args) == 0 {
		return nil, false, nil
	}
	last := args[len(args)-1]
	if last == nil || last.Type != object.ValueHash || !Ruby2KeywordHash(last) || !raiseHashHasCauseKeyword(last) {
		return nil, false, nil
	}
	hash, ok := last.Data.(*object.RHash)
	if !ok || hash == nil {
		return nil, false, nil
	}
	for key, value := range hash.Pairs {
		if !raiseKeywordKeyMatches(key, "cause") {
			continue
		}
		if value != nil && value.Type != object.ValueNil && value.Type != object.ValueException {
			return nil, true, typeError("exception object expected")
		}
		if value == nil || value.Type == object.ValueNil {
			return R.NilVal, true, nil
		}
		return value, true, nil
	}
	return nil, false, nil
}

func raiseHashHasCauseKeyword(value *object.EmeraldValue) bool {
	if value == nil || value.Type != object.ValueHash {
		return false
	}
	hash, ok := value.Data.(*object.RHash)
	if !ok || hash == nil {
		return false
	}
	for key := range hash.Pairs {
		if raiseKeywordKeyMatches(key, "cause") {
			return true
		}
	}
	return false
}

func raiseKeywordKeyMatches(key *object.EmeraldValue, name string) bool {
	if key == nil {
		return false
	}
	switch key.Type {
	case object.ValueString, object.ValueSymbol:
		if s, ok := key.Data.(string); ok {
			return strings.TrimPrefix(s, ":") == name
		}
	}
	return false
}

func setExceptionCause(exc, cause *object.EmeraldValue) *object.EmeraldValue {
	if exc == nil || exc.Type != object.ValueException {
		return nil
	}
	data, ok := exc.Data.(*object.RException)
	if !ok || data == nil {
		return nil
	}
	if cause == nil || cause.Type == object.ValueNil || cause == exc {
		data.Cause = nil
		return nil
	}
	if exceptionCauseChainContains(cause, exc) {
		return argumentError("circular causes")
	}
	data.Cause = cause
	return nil
}

func exceptionCauseChainContains(cause, target *object.EmeraldValue) bool {
	seen := map[*object.EmeraldValue]bool{}
	for cause != nil && cause.Type == object.ValueException {
		if cause == target {
			return true
		}
		if seen[cause] {
			return false
		}
		seen[cause] = true
		data, ok := cause.Data.(*object.RException)
		if !ok || data == nil {
			return false
		}
		cause = data.Cause
	}
	return false
}

func builtinAbort(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	message := ""
	if len(args) > 0 {
		if args[0] == nil || args[0].Type == object.ValueNil {
			return typeError("no implicit conversion to String")
		}
		if s, ok := args[0].Data.(string); ok {
			message = s
		} else if CallMethod != nil && receiverHasCallableMethod(args[0], "to_str") {
			coerced := CallMethod(args[0], "to_str")
			if coerced != nil && coerced.Type == object.ValueException {
				return coerced
			}
			if coerced == nil {
				return typeError("no implicit conversion to String")
			}
			if s, ok := coerced.Data.(string); ok {
				message = s
			} else {
				return typeError("no implicit conversion to String")
			}
		} else {
			return typeError("no implicit conversion to String")
		}
	}

	if message != "" {
		writtenToStderr := false
		if GetGlobalVariable != nil {
			stderr := GetGlobalVariable("$stderr")
			if stderr != nil && CallMethod != nil {
				writeResult := CallMethod(stderr, "write", rubyString(message+"\n"))
				if writeResult != nil && writeResult.Type != object.ValueException {
					writtenToStderr = true
				}
			}
		}
		if !writtenToStderr {
			fmt.Fprintln(os.Stderr, message)
		}
	}

	status := int64(1)
	exc := newSystemExit(message, status)
	LastException = exc
	return exc
}

func exitStatusFromArgs(args ...*object.EmeraldValue) (int64, *object.EmeraldValue) {
	if len(args) == 0 {
		return 0, nil
	}
	arg := args[0]
	if arg == nil || arg.Type == object.ValueNil {
		return 0, typeError("no implicit conversion to Integer")
	}
	if arg == R.TrueVal {
		return 0, nil
	}
	if arg == R.FalseVal {
		return 1, nil
	}
	switch v := arg.Data.(type) {
	case int64:
		return v, nil
	case float64:
		return int64(v), nil
	}
	if CallMethod != nil {
		coerced := CallMethod(arg, "to_int")
		if coerced != nil && coerced.Type == object.ValueException {
			if isNoMethodError(coerced) {
				return 0, typeError("no implicit conversion to Integer")
			}
			return 0, coerced
		}
		if coerced != nil {
			if n, ok := coerced.Data.(int64); ok {
				return n, nil
			}
		}
	}
	return 0, typeError("no implicit conversion to Integer")
}

func newSystemExit(message string, status int64) *object.EmeraldValue {
	frames := currentBacktraceFramesOrEmpty()
	exc := &object.EmeraldValue{
		Type:  object.ValueException,
		Data:  &object.RException{Message: message, Backtrace: backtraceStrings(frames), Locations: frames, Status: &status},
		Class: R.Classes["SystemExit"],
	}
	LastException = exc
	return exc
}

