func builtinMagicFile(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if CurrentSpecFile != "" {
		return rubyString(CurrentSpecFile)
	}
	return rubyString("spec.rb")
}

func builtinMagicEncoding(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	frames := currentBacktraceFramesOrEmpty()
	if len(frames) > 0 && frames[0].Path != "" && frames[0].Path != CurrentSpecFile {
		if source, err := os.ReadFile(frames[0].Path); err == nil {
			if magicEncoding := evalSourceMagicEncoding(string(source)); magicEncoding != "" {
				return newEncodingValue(magicEncoding)
			}
		}
	}
	if CurrentEvalSourceEncoding != "" {
		return newEncodingValue(canonicalEncodingName(normalizeEncodingNameForIO(CurrentEvalSourceEncoding)))
	}
	encoding := "UTF-8"
	if len(frames) > 0 && frames[0].Path != "" {
		if source, err := os.ReadFile(frames[0].Path); err == nil {
			if magicEncoding := evalSourceMagicEncoding(string(source)); magicEncoding != "" {
				encoding = magicEncoding
			}
		}
	}
	return newEncodingValue(encoding)
}

func builtinMagicMethod(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if CurrentMethodName == nil || CurrentMethodName() == "" {
		return R.NilVal
	}
	return &object.EmeraldValue{Type: object.ValueSymbol, Data: CurrentMethodName(), Class: R.Classes["Symbol"]}
}

func builtinMagicCallee(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if CurrentCalleeName == nil || CurrentCalleeName() == "" {
		return R.NilVal
	}
	return &object.EmeraldValue{Type: object.ValueSymbol, Data: CurrentCalleeName(), Class: R.Classes["Symbol"]}
}

func builtinMagicDir(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if CurrentSpecFile != "" {
		path := CurrentSpecFile
		if CurrentSpecFileAbsolute != "" {
			path = CurrentSpecFileAbsolute
		}
		if abs, err := filepath.Abs(path); err == nil {
			path = abs
		}
		return rubyString(filepath.Dir(path))
	}
	return rubyString("/")
}

var BlockGivenCheck func() bool
var MethodBlockGivenCheck func() bool
var CurrentBlockValue func() *object.EmeraldValue

func builtinBlockGiven(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if MethodBlockGivenCheck != nil && MethodBlockGivenCheck() {
		return R.TrueVal
	}
	return R.FalseVal
}

func builtinTap(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if BlockGivenCheck == nil || !BlockGivenCheck() || CallBlock == nil {
		return NewLocalJumpError("no block given")
	}
	result := CallBlock(receiver)
	if result != nil && result.Type == object.ValueException {
		return result
	}
	return receiver
}

func builtinYieldSelf(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if BlockGivenCheck == nil || !BlockGivenCheck() || CallBlock == nil {
		return newStaticEnumerator([]*object.EmeraldValue{receiver})
	}
	return CallBlock(receiver)
}

func builtinNotMatch(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 0 {
		return NewArgumentError("wrong number of arguments")
	}
	if CallMethod == nil {
		return NewNoMethodError("undefined method `=~'")
	}
	if !receiverHasCallableMethod(receiver, "=~") {
		return NewNoMethodError("undefined method `=~'")
	}
	result := CallMethod(receiver, "=~", args[0])
	if result != nil && result.Type == object.ValueException {
		return result
	}
	if result == nil || result == R.NilVal || result == R.FalseVal {
		return R.TrueVal
	}
	return R.FalseVal
}

func builtinLambda(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) > 0 {
		if args[0] != nil && args[0].Type == object.ValueProc {
			if proc, ok := args[0].Data.(*object.Proc); ok && proc.IsLambda {
				return args[0]
			}
		}
		return NewArgumentError("the lambda method requires a literal block")
	}
	if CurrentBlockValue != nil {
		if block := CurrentBlockValue(); block != nil {
			if block.Type == object.ValueProc {
				if proc, ok := block.Data.(*object.Proc); ok && !proc.IsLambda {
					return NewArgumentError("the lambda method requires a literal block")
				}
			}
			return lambdaValueFromBlock(block)
		}
	}
	return NewArgumentError("tried to create Proc object without a block")
}

func builtinProc(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) > 0 {
		return args[0]
	}
	if CurrentBlockValue != nil {
		if block := CurrentBlockValue(); block != nil {
			if proc := procValueFromBlock(block, R.Classes["Proc"]); proc != nil {
				return proc
			}
			return block
		}
	}
	return NewArgumentError("tried to create Proc object without a block")
}

func lambdaValueFromBlock(block *object.EmeraldValue) *object.EmeraldValue {
	switch block.Type {
	case object.ValueProc:
		source := block.Data.(*object.Proc)
		copy := *source
		copy.IsLambda = true
		copy.InstanceVars = make(map[string]*object.EmeraldValue)
		return &object.EmeraldValue{Type: object.ValueProc, Data: &copy, Class: R.Classes["Proc"]}
	case object.ValueClosure:
		closure := block.Data.(*object.Closure)
		return &object.EmeraldValue{
			Type: object.ValueProc,
			Data: &object.Proc{
				Fn:               closure.Fn,
				Env:              closure.Free,
				Block:            closure.Block,
				Binding:          closure.Binding,
				ClassStack:       closure.ClassStack,
				Refinements:      append([]*object.EmeraldValue(nil), closure.Refinements...),
				RefinementsFixed: closure.RefinementsFixed,
				InstanceVars:     make(map[string]*object.EmeraldValue),
				AutoSplat:        closure.AutoSplat,
				IsLambda:         true,
			},
			Class: R.Classes["Proc"],
		}
	default:
		return block
	}
}

func builtinBinding(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 0 {
		return NewArgumentError("wrong number of arguments")
	}
	binding := (*object.RBinding)(nil)
	if CaptureFrameBinding != nil {
		binding = CaptureFrameBinding()
	} else if CurrentFrameBinding != nil {
		binding = CurrentFrameBinding()
	}
	if binding == nil {
		binding = &object.RBinding{
			Self:          R.Main,
			Locals:        map[string]*object.EmeraldValue{},
			LocalNames:    nil,
			Constants:     map[string]*object.EmeraldValue{},
			Method:        "",
			InstanceVars:  map[string]*object.EmeraldValue{},
			ClassStack:    nil,
			ClassVarScope: nil,
			Path:          currentSourcePath(),
			Line:          1,
		}
	}
	return &object.EmeraldValue{Type: object.ValueBinding, Data: binding, Class: R.Classes["Binding"]}
}

func builtinLocalVariables(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 0 {
		return NewArgumentError("wrong number of arguments")
	}
	binding := (*object.RBinding)(nil)
	if CurrentFrameBinding != nil {
		binding = CurrentFrameBinding()
	}
	if binding == nil {
		binding = &object.RBinding{
			Self:         R.Main,
			Locals:       map[string]*object.EmeraldValue{},
			LocalNames:   nil,
			Constants:    map[string]*object.EmeraldValue{},
			Method:       "",
			InstanceVars: map[string]*object.EmeraldValue{},
			Path:         currentSourcePath(),
			Line:         1,
		}
	}
	return bindingLocalVariables(&object.EmeraldValue{
		Type:  object.ValueBinding,
		Data:  binding,
		Class: R.Classes["Binding"],
	})
}

func tracePointClassNew(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if CurrentBlockValue == nil || CurrentBlockValue() == nil {
		return argumentError("must be called with a block")
	}
	events := []string{"line"}
	if len(args) > 0 {
		events = make([]string, 0, len(args))
		for _, argument := range args {
			event, errVal := tracePointEventName(argument)
			if errVal != nil {
				return errVal
			}
			events = append(events, event)
		}
	}
	obj := &object.EmeraldValue{Type: object.ValueObject, Class: R.Classes["TracePoint"]}
	data := &tracePointData{events: events, block: CurrentBlockValue()}
	obj.Data = data
	return obj
}

func tracePointClassTrace(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	tracePoint := tracePointClassNew(receiver, args...)
	if tracePoint == nil || tracePoint.Type == object.ValueException {
		return tracePoint
	}
	returnValue := tracePointEnable(tracePoint)
	if returnValue != nil && returnValue.Type == object.ValueException {
		return returnValue
	}
	return tracePoint
}

func tracePointEventName(value *object.EmeraldValue) (string, *object.EmeraldValue) {
	if value == nil {
		return "", typeError("no implicit conversion into Symbol")
	}
	if value.Type != object.ValueSymbol && value.Type != object.ValueString {
		if CallMethod == nil || !receiverHasCallableMethod(value, "to_sym") {
			return "", typeError("no implicit conversion into Symbol")
		}
		value = CallMethod(value, "to_sym")
		if value == nil || value.Type != object.ValueSymbol {
			return "", typeError("to_sym did not return Symbol")
		}
	}
	event := specName(value)
	valid := map[string]bool{
		"line": true, "class": true, "end": true, "call": true, "return": true,
		"c_call": true, "c_return": true, "raise": true, "b_call": true, "b_return": true,
		"rescue":       true,
		"thread_begin": true, "thread_end": true, "fiber_switch": true, "script_compiled": true,
	}
	if !valid[event] {
		return "", argumentError("unknown event: " + event)
	}
	return event, nil
}

func tracePointHasEvent(data *tracePointData, event string) bool {
	for _, candidate := range data.events {
		if candidate == event {
			return true
		}
	}
	return false
}

func tracePointEnable(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data, _ := receiver.Data.(*tracePointData)
	if data == nil {
		return receiver
	}
	target, hasTarget, targetLineValue, hasTargetLine := tracePointEnableOptions(args)
	if hasTargetLine && !hasTarget {
		return argumentError("only target_line is specified")
	}
	if hasTargetLine && !tracePointHasEvent(data, "line") {
		return argumentError("target_line is specified, but line event is not specified")
	}
	targetInfo, errVal := tracePointTargetInfoFor(target)
	if hasTarget && errVal != nil {
		return errVal
	}
	if hasTarget && !tracePointTargetCanTrigger(data, targetInfo.kind) {
		return argumentError("can not enable any hooks")
	}
	targetLine := int64(0)
	if hasTargetLine {
		var ok bool
		targetLine, ok = valueToInteger(targetLineValue)
		if !ok {
			return typeError("no implicit conversion of " + targetLineValue.TypeName() + " into Integer")
		}
		if targetLine < targetInfo.startLine || targetLine > targetInfo.endLine || targetLine < 0 {
			return argumentError("can not enable any hooks")
		}
	}
	wasEnabled := data.enabled
	if wasEnabled && (data.targeting || hasTarget) {
		return argumentError("can't nest-enable a targeting TracePoint")
	}
	if !wasEnabled {
		if hasTarget {
			data.targeting = true
			data.targetKind = targetInfo.kind
			data.targetMethodID = targetInfo.methodID
			data.targetPath = targetInfo.path
			data.targetStartLine = targetInfo.startLine
			data.targetEndLine = targetInfo.endLine
			data.targetLine = targetLine
			data.lastTargetFrame = 0
			data.lastTargetLine = 0
		}
		data.enabled = true
		activeTracePoints = append(activeTracePoints, receiver)
		if TracePointActivated != nil {
			data.skipFrameID, data.skipPath, data.skipLine = TracePointActivated()
		}
	}
	if BlockGivenCheck != nil && BlockGivenCheck() && CallBlock != nil {
		result := CallBlock()
		if !wasEnabled {
			tracePointDisableValue(receiver)
		}
		return result
	}
	return boolValue(wasEnabled)
}

type tracePointTargetInfo struct {
	kind      string
	methodID  string
	path      string
	startLine int64
	endLine   int64
}

func tracePointEnableOptions(args []*object.EmeraldValue) (target *object.EmeraldValue, hasTarget bool, targetLine *object.EmeraldValue, hasTargetLine bool) {
	if len(args) == 0 {
		return nil, false, nil, false
	}
	options := args[len(args)-1]
	if options == nil || options.Type != object.ValueHash {
		return nil, false, nil, false
	}
	for key, value := range valueToHashMap(options) {
		switch specName(key) {
		case "target":
			target, hasTarget = value, true
		case "target_line":
			targetLine, hasTargetLine = value, true
		}
	}
	return
}

func tracePointTargetInfoFor(target *object.EmeraldValue) (tracePointTargetInfo, *object.EmeraldValue) {
	if target == nil {
		return tracePointTargetInfo{}, argumentError("specified target is not supported")
	}
	info := tracePointTargetInfo{}
	var fn *object.Function
	switch target.Type {
	case object.ValueMethod:
		method, _ := target.Data.(*object.Method)
		if method == nil {
			return info, argumentError("specified target is not supported")
		}
		fn, _ = method.Fn.(*object.Function)
		info.kind = "method"
		info.methodID = method.OriginalName
		if info.methodID == "" {
			info.methodID = method.Name
		}
	case object.ValueProc:
		proc, _ := target.Data.(*object.Proc)
		if proc == nil || proc.Native != nil {
			return info, argumentError("specified target is not supported")
		}
		fn = proc.Fn
		info.kind = "proc"
	case object.ValueClosure:
		closure, _ := target.Data.(*object.Closure)
		if closure != nil {
			fn = closure.Fn
		}
		info.kind = "proc"
	default:
		return info, argumentError("specified target is not supported")
	}
	if fn == nil {
		return info, argumentError("can not enable any hooks")
	}
	info.path, info.startLine, info.endLine = fn.SourcePath, fn.DefinitionLine, fn.DefinitionLine
	for _, line := range fn.LineMap {
		candidate := int64(line)
		if candidate > 0 && (info.startLine == 0 || candidate < info.startLine) {
			info.startLine = candidate
		}
		if candidate > info.endLine {
			info.endLine = candidate
		}
	}
	return info, nil
}

func tracePointTargetCanTrigger(data *tracePointData, kind string) bool {
	for _, event := range data.events {
		if kind == "method" && (event == "line" || event == "call" || event == "return" || event == "b_call" || event == "b_return") {
			return true
		}
		if kind == "proc" && (event == "line" || event == "b_call" || event == "b_return") {
			return true
		}
	}
	return false
}

func tracePointCurrentLocation() (string, int64) {
	path := currentSourcePath()
	line := int64(1)
	if CurrentBlockValue != nil {
		if block := CurrentBlockValue(); block != nil {
			if fn := procFunction(block); fn != nil {
				if fn.SourcePath != "" {
					path = fn.SourcePath
				}
				if fn.DefinitionLine > 0 {
					line = fn.DefinitionLine + 1
				}
			}
		}
	}
	if line == 1 && CurrentFrameBinding != nil {
		if binding := CurrentFrameBinding(); binding != nil {
			if binding.Path != "" {
				path = binding.Path
			}
			if binding.Line > 0 {
				line = binding.Line
			}
		}
	}
	return path, line
}

func tracePointDisable(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data, _ := receiver.Data.(*tracePointData)
	if data == nil {
		return R.FalseVal
	}
	wasEnabled := data.enabled
	hasBlock := BlockGivenCheck != nil && BlockGivenCheck() && CallBlock != nil
	if hasBlock && data.targeting {
		return argumentError("can't disable a targeting TracePoint in a block")
	}
	if wasEnabled {
		tracePointDisableValue(receiver)
	}
	if hasBlock {
		result := CallBlock()
		if wasEnabled {
			data.enabled = true
			activeTracePoints = append(activeTracePoints, receiver)
		}
		return result
	}
	return boolValue(wasEnabled)
}

