func tracePointInspect(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data, _ := receiver.Data.(*tracePointData)
	if data == nil || !data.enabled {
		return rubyString("#<TracePoint:disabled>")
	}
	if !data.inside {
		return rubyString("#<TracePoint:enabled>")
	}
	if (data.event == "thread_begin" || data.event == "thread_end") && data.threadInspect != "" {
		return rubyString(fmt.Sprintf("#<TracePoint:%s %s>", data.event, data.threadInspect))
	}
	method := ""
	if data.methodID != "" {
		method = " '" + data.methodID + "'"
	}
	return rubyString(fmt.Sprintf("#<TracePoint:%s%s %s:%d>", data.event, method, data.path, data.line))
}

