type tracePointPayload struct {
	event           string
	binding         *object.RBinding
	eventSelf       *object.EmeraldValue
	definedClass    *object.EmeraldValue
	path            string
	line            int64
	methodID        string
	calleeID        string
	parameters      *object.EmeraldValue
	returnValue     *object.EmeraldValue
	raisedException *object.EmeraldValue
	evalScript      *object.EmeraldValue
	threadInspect   string
	frameID         int
}

func tracePointFire(event string, binding *object.RBinding, path string, line int64, methodID string, returnValue *object.EmeraldValue) {
	tracePointFirePayload(tracePointPayload{event: event, binding: binding, path: path, line: line, methodID: methodID, calleeID: methodID, returnValue: returnValue})
}

func tracePointFirePayload(payload tracePointPayload) {
	if tracePointDispatching || len(activeTracePoints) == 0 || CallBlockWithArgs == nil {
		return
	}
	tracePointDispatching = true
	defer func() { tracePointDispatching = false }()
	var bindingValue *object.EmeraldValue
	if payload.binding != nil {
		bindingValue = &object.EmeraldValue{Type: object.ValueBinding, Data: payload.binding, Class: R.Classes["Binding"]}
	}
	tracePoints := append([]*object.EmeraldValue(nil), activeTracePoints...)
	orderedTracePoints := make([]*object.EmeraldValue, 0, len(tracePoints))
	for _, tracePoint := range tracePoints {
		if data, _ := tracePoint.Data.(*tracePointData); data == nil || !data.targeting {
			orderedTracePoints = append(orderedTracePoints, tracePoint)
		}
	}
	for index := len(tracePoints) - 1; index >= 0; index-- {
		tracePoint := tracePoints[index]
		if data, _ := tracePoint.Data.(*tracePointData); data != nil && data.targeting {
			orderedTracePoints = append(orderedTracePoints, tracePoint)
		}
	}
	for _, tracePoint := range orderedTracePoints {
		data, _ := tracePoint.Data.(*tracePointData)
		if data == nil || !data.enabled || !tracePointHasEvent(data, payload.event) || data.block == nil {
			continue
		}
		if data.targeting && !tracePointTargetMatches(data, payload) {
			continue
		}
		if payload.event == "line" && payload.frameID != 0 && payload.frameID == data.skipFrameID && payload.path == data.skipPath && payload.line == data.skipLine {
			continue
		}
		if data.targeting && data.targetLine > 0 && payload.event == "line" {
			if data.lastTargetFrame == payload.frameID && data.lastTargetLine == payload.line {
				continue
			}
			data.lastTargetFrame = payload.frameID
			data.lastTargetLine = payload.line
		}
		data.event, data.path, data.line = payload.event, payload.path, payload.line
		data.eventSelf, data.definedClass = payload.eventSelf, payload.definedClass
		data.methodID, data.calleeID, data.parameters = payload.methodID, payload.calleeID, payload.parameters
		data.returnValue, data.raisedException = payload.returnValue, payload.raisedException
		data.evalScript, data.threadInspect = payload.evalScript, payload.threadInspect
		data.binding = bindingValue
		data.inside = true
		CallBlockWithArgs(data.block, tracePoint)
		data.inside = false
	}
}

func tracePointTargetMatches(data *tracePointData, payload tracePointPayload) bool {
	if data.targetLine > 0 && payload.event == "line" && payload.line != data.targetLine {
		return false
	}
	switch data.targetKind {
	case "method":
		switch payload.event {
		case "call", "return":
			return payload.methodID == data.targetMethodID
		case "line", "b_call", "b_return":
			return payload.binding != nil && payload.binding.Method == data.targetMethodID
		}
	case "proc":
		if payload.path != data.targetPath {
			return false
		}
		switch payload.event {
		case "b_call":
			return payload.line == 0 || payload.line >= data.targetStartLine && payload.line <= data.targetEndLine
		case "b_return":
			return payload.line >= data.targetStartLine && payload.line <= data.targetEndLine
		case "line":
			return payload.line >= data.targetStartLine && payload.line <= data.targetEndLine
		}
	}
	return false
}

func TracePointEventActive(event string) bool {
	if tracePointDispatching {
		return false
	}
	for _, tracePoint := range activeTracePoints {
		data, _ := tracePoint.Data.(*tracePointData)
		if data != nil && data.enabled && tracePointHasEvent(data, event) {
			return true
		}
	}
	return false
}

