func stringStripBangSide(receiver *object.EmeraldValue, left, right bool) *object.EmeraldValue {
	if receiver != nil && receiver.Frozen {
		return frozenError("can't modify frozen String")
	}
	if strings.EqualFold(stringEncodingName(receiver), "UTF-8") && stringHasInvalidUTF8Byte(stringRawValue(receiver)) {
		if left && !right {
			return NewArgumentError("invalid byte sequence in UTF-8")
		}
		if right && !left {
			return newRuntimeException(R.Classes["Encoding::CompatibilityError"], "invalid byte sequence in UTF-8")
		}
	}
	result := stringStripSide(receiver, left, right)
	if stringRawValue(result) == stringRawValue(receiver) {
		return R.NilVal
	}
	receiver.Data = stringRawValue(result)
	return receiver
}

func stringReplace(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver != nil && receiver.Frozen {
		return frozenError("can't modify frozen String")
	}
	if len(args) != 1 {
		return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 1)", len(args)))
	}
	newStr, ok, viaToStr, errVal := evalCoerceToString(args[0])
	if errVal != nil {
		return errVal
	}
	if !ok {
		return conversionTypeErrorToStringForMode(args[0], viaToStr)
	}
	receiver.Data = newStr
	if args[0] != nil && args[0].Type == object.ValueString {
		CopyStringEncoding(receiver, args[0])
	} else {
		SetStringEncoding(receiver, defaultExternalEncoding)
	}
	return receiver
}

func stringInitialize(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 0 {
		return receiver
	}
	if len(args) != 1 {
		return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 0..1)", len(args)))
	}
	return stringReplace(receiver, args[0])
}

func stringClear(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver != nil && receiver.Frozen {
		return frozenError("can't modify frozen String")
	}
	receiver.Data = ""
	return receiver
}

func stringInsert(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver != nil && receiver.Frozen {
		return frozenError("can't modify frozen String")
	}
	insertValue, errVal := stringCoerceConcatenationString(args[1])
	if errVal != nil {
		return errVal
	}
	idx, ok := valueToInteger(args[0])
	if !ok {
		return typeError("no implicit conversion into Integer")
	}
	s := stringRawValue(receiver)
	characterCount := stringCharacterLength(receiver)
	if idx < 0 {
		idx = int64(characterCount) + idx + 1
	}
	if idx < 0 || idx > int64(characterCount) {
		return newRuntimeException(R.Classes["IndexError"], "index out of string")
	}
	byteIndex, valid := stringCharByteIndex(s, int(idx))
	if !valid {
		return newRuntimeException(R.Classes["IndexError"], "index out of string")
	}
	encoding, encodingErr := StringConcatenationEncoding(receiver, insertValue)
	if encodingErr != nil {
		return encodingErr
	}
	receiver.Data = s[:byteIndex] + stringRawValue(insertValue) + s[byteIndex:]
	SetStringEncoding(receiver, encoding)
	return receiver
}

