func stringDelete(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 0 {
		return NewArgumentError("wrong number of arguments (given 0, expected 1+)")
	}
	sets, errVal := stringCharacterSets(args)
	if errVal != nil {
		return errVal
	}
	var result strings.Builder
	for _, character := range stringRawValue(receiver) {
		if !stringCharacterInAllSets(character, sets) {
			result.WriteRune(character)
		}
	}
	return stringWithEncoding(result.String(), stringEncodingName(receiver))
}

func stringSqueeze(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	sets := []stringCharacterSet(nil)
	if len(args) > 0 {
		var errVal *object.EmeraldValue
		sets, errVal = stringCharacterSets(args)
		if errVal != nil {
			return errVal
		}
	}
	var result strings.Builder
	var previous rune
	hasPrevious := false
	for _, character := range stringRawValue(receiver) {
		selected := len(sets) == 0 || stringCharacterInAllSets(character, sets)
		if hasPrevious && character == previous && selected {
			continue
		}
		result.WriteRune(character)
		previous = character
		hasPrevious = true
	}
	return stringWithEncoding(result.String(), stringEncodingName(receiver))
}

func stringDeleteBang(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver != nil && receiver.Frozen {
		return frozenError("can't modify frozen String")
	}
	result := stringDelete(receiver, args...)
	if result == nil || result.Type == object.ValueException {
		return result
	}
	if stringRawValue(result) == stringRawValue(receiver) {
		return R.NilVal
	}
	receiver.Data = stringRawValue(result)
	return receiver
}

func stringDeleteEdge(receiver, value *object.EmeraldValue, prefix bool) *object.EmeraldValue {
	raw, ok, viaToStr, errVal := evalCoerceToString(value)
	if errVal != nil {
		return errVal
	}
	if !ok {
		return conversionTypeErrorToStringForMode(value, viaToStr)
	}
	source := stringRawValue(receiver)
	if raw == "" {
		return stringWithEncoding(source, stringEncodingName(receiver))
	}
	if normalizedEncodingName(stringEncodingName(receiver)) == "UTF_8" && !utf8.ValidString(raw) {
		return stringWithEncoding(source, stringEncodingName(receiver))
	}
	if prefix && strings.HasPrefix(source, raw) {
		return stringWithEncoding(source[len(raw):], stringEncodingName(receiver))
	}
	if !prefix && strings.HasSuffix(source, raw) {
		return stringWithEncoding(source[:len(source)-len(raw)], stringEncodingName(receiver))
	}
	return stringWithEncoding(source, stringEncodingName(receiver))
}

