func stringTranslationSets(fromValue, toValue *object.EmeraldValue) (stringCharacterSet, stringCharacterSet, *object.EmeraldValue) {
	fromRaw, ok, viaToStr, errVal := evalCoerceToString(fromValue)
	if errVal != nil {
		return stringCharacterSet{}, stringCharacterSet{}, errVal
	}
	if !ok {
		return stringCharacterSet{}, stringCharacterSet{}, conversionTypeErrorToStringForMode(fromValue, viaToStr)
	}
	toRaw, ok, viaToStr, errVal := evalCoerceToString(toValue)
	if errVal != nil {
		return stringCharacterSet{}, stringCharacterSet{}, errVal
	}
	if !ok {
		return stringCharacterSet{}, stringCharacterSet{}, conversionTypeErrorToStringForMode(toValue, viaToStr)
	}
	from, errVal := parseStringCharacterSet(fromRaw, true)
	if errVal != nil {
		return stringCharacterSet{}, stringCharacterSet{}, errVal
	}
	to, errVal := parseStringCharacterSet(toRaw, false)
	return from, to, errVal
}

func stringTranslate(receiver *object.EmeraldValue, fromValue, toValue *object.EmeraldValue, squeeze bool) *object.EmeraldValue {
	from, to, errVal := stringTranslationSets(fromValue, toValue)
	if errVal != nil {
		return errVal
	}
	if len(from.sequence) == 0 {
		return stringWithEncoding(stringRawValue(receiver), stringEncodingName(receiver))
	}
	indices := make(map[rune]int, len(from.sequence))
	for index, character := range from.sequence {
		if _, exists := indices[character]; !exists {
			indices[character] = index
		}
	}
	var result strings.Builder
	var previous rune
	previousTranslated := false
	for _, character := range stringRawValue(receiver) {
		index, explicitlyFound := indices[character]
		translated := explicitlyFound
		if from.negated {
			translated = !explicitlyFound
			index = len(from.sequence)
		}
		if !translated {
			result.WriteRune(character)
			previous = character
			previousTranslated = false
			continue
		}
		if len(to.sequence) == 0 {
			previousTranslated = false
			continue
		}
		if index >= len(to.sequence) {
			index = len(to.sequence) - 1
		}
		replacement := to.sequence[index]
		if squeeze && previousTranslated && replacement == previous {
			continue
		}
		result.WriteRune(replacement)
		previous = replacement
		previousTranslated = true
	}
	return stringWithEncoding(result.String(), stringEncodingName(receiver))
}

func stringTr(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return stringTranslate(receiver, args[0], args[1], false)
}

func stringTrS(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return stringTranslate(receiver, args[0], args[1], true)
}

func stringTranslateBang(receiver *object.EmeraldValue, squeeze bool, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver != nil && receiver.Frozen {
		return frozenError("can't modify frozen String")
	}
	result := stringTranslate(receiver, args[0], args[1], squeeze)
	if result == nil || result.Type == object.ValueException {
		return result
	}
	if stringRawValue(result) == stringRawValue(receiver) {
		return R.NilVal
	}
	receiver.Data = stringRawValue(result)
	return receiver
}

func stringTrBang(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return stringTranslateBang(receiver, false, args...)
}

func stringTrSBang(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return stringTranslateBang(receiver, true, args...)
}

func stringToF(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	encoding := stringEncodingName(receiver)
	if !encodingIsASCICompatible(encoding) {
		return newRuntimeException(R.Classes["Encoding::CompatibilityError"], "ASCII incompatible encoding: "+encoding)
	}
	s := strings.TrimLeft(stringRawValue(receiver), " \t\n\r\v\f")
	end := stringFloatPrefixEnd(s)
	if end == 0 {
		return newFloat(0)
	}
	number := strings.ReplaceAll(s[:end], "_", "")
	value, err := strconv.ParseFloat(number, 64)
	if err != nil {
		return newFloat(0)
	}
	return newFloat(value)
}

func stringToR(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	encoding := stringEncodingName(receiver)
	if !encodingIsASCICompatible(encoding) {
		return newRuntimeException(R.Classes["Encoding::CompatibilityError"], "ASCII incompatible encoding: "+encoding)
	}
	input := strings.TrimLeft(stringRawValue(receiver), " \t\n\r\v\f")
	value, _, ok := parseStringNumericPrefix(input, true)
	if !ok {
		return newRationalValue(big.NewInt(0), big.NewInt(1))
	}
	return value
}

func stringToC(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	encoding := stringEncodingName(receiver)
	if !encodingIsASCICompatible(encoding) {
		return newRuntimeException(R.Classes["Encoding::CompatibilityError"], "ASCII incompatible encoding: "+encoding)
	}
	input := strings.TrimLeft(stringRawValue(receiver), " \t\n\r\v\f")
	zero := newInt(0)
	unit := func(sign int64) *object.EmeraldValue {
		return newComplexFromValues(zero, newInt(sign))
	}
	if len(input) > 0 && isStringImaginaryUnit(input[0]) {
		return unit(1)
	}
	if len(input) > 1 && (input[0] == '+' || input[0] == '-') && isStringImaginaryUnit(input[1]) {
		if input[0] == '-' {
			return unit(-1)
		}
		return unit(1)
	}

	first, end, ok := parseStringNumericPrefix(input, false)
	if !ok {
		return newComplexFromValues(zero, zero)
	}
	if end < len(input) && input[end] == '@' {
		angle, _, angleOK := parseStringNumericPrefix(input[end+1:], false)
		if angleOK {
			radiusFloat := complexComponentFloat(first)
			angleFloat := complexComponentFloat(angle)
			return newComplexValue(radiusFloat*math.Cos(angleFloat), radiusFloat*math.Sin(angleFloat))
		}
	}
	if end < len(input) && isStringImaginaryUnit(input[end]) {
		return newComplexFromValues(zero, first)
	}
	if end < len(input) && (input[end] == '+' || input[end] == '-') {
		sign := input[end]
		if end+1 < len(input) && isStringImaginaryUnit(input[end+1]) {
			imaginary := int64(1)
			if sign == '-' {
				imaginary = -1
			}
			return newComplexFromValues(first, newInt(imaginary))
		}
		imaginary, imaginaryEnd, imaginaryOK := parseStringNumericPrefix(input[end:], false)
		if imaginaryOK && end+imaginaryEnd < len(input) && isStringImaginaryUnit(input[end+imaginaryEnd]) {
			return newComplexFromValues(first, imaginary)
		}
	}
	return newComplexFromValues(first, zero)
}

func isStringImaginaryUnit(value byte) bool {
	return value == 'i' || value == 'I' || value == 'j' || value == 'J'
}

func parseStringNumericPrefix(input string, forceRational bool) (*object.EmeraldValue, int, bool) {
	end := stringFloatPrefixEnd(input)
	if end == 0 {
		return nil, 0, false
	}
	numeratorText := input[:end]
	if end < len(input) && input[end] == '/' {
		denominatorEnd := stringFloatPrefixEnd(input[end+1:])
		if denominatorEnd > 0 {
			numerator, numeratorOK := exactStringDecimal(numeratorText)
			denominator, denominatorOK := exactStringDecimal(input[end+1 : end+1+denominatorEnd])
			if numeratorOK && denominatorOK && denominator.Sign() != 0 {
				result := new(big.Rat).Quo(numerator, denominator)
				return newRationalValue(result.Num(), result.Denom()), end + 1 + denominatorEnd, true
			}
		}
	}
	if forceRational {
		rational, valid := exactStringDecimal(numeratorText)
		if !valid {
			return nil, 0, false
		}
		return newRationalValue(rational.Num(), rational.Denom()), end, true
	}
	cleaned := strings.ReplaceAll(numeratorText, "_", "")
	if strings.ContainsAny(cleaned, ".eE") {
		parsed, err := strconv.ParseFloat(cleaned, 64)
		if err != nil {
			return nil, 0, false
		}
		return newFloat(parsed), end, true
	}
	integer := new(big.Int)
	if _, valid := integer.SetString(cleaned, 10); !valid {
		return nil, 0, false
	}
	return NewIntegerFromBigInt(integer), end, true
}

func exactStringDecimal(input string) (*big.Rat, bool) {
	cleaned := strings.ReplaceAll(input, "_", "")
	negative := false
	if len(cleaned) > 0 && (cleaned[0] == '+' || cleaned[0] == '-') {
		negative = cleaned[0] == '-'
		cleaned = cleaned[1:]
	}
	exponent := int64(0)
	if index := strings.IndexAny(cleaned, "eE"); index >= 0 {
		parsedExponent, err := strconv.ParseInt(cleaned[index+1:], 10, 32)
		if err != nil {
			return nil, false
		}
		exponent = parsedExponent
		cleaned = cleaned[:index]
	}
	integerPart := cleaned
	fractionPart := ""
	if index := strings.IndexByte(cleaned, '.'); index >= 0 {
		integerPart = cleaned[:index]
		fractionPart = cleaned[index+1:]
	}
	if integerPart == "" {
		integerPart = "0"
	}
	digits := integerPart + fractionPart
	numerator := new(big.Int)
	if _, valid := numerator.SetString(digits, 10); !valid {
		return nil, false
	}
	if negative {
		numerator.Neg(numerator)
	}
	denominator := new(big.Int).Exp(big.NewInt(10), big.NewInt(int64(len(fractionPart))), nil)
	if exponent > 0 {
		numerator.Mul(numerator, new(big.Int).Exp(big.NewInt(10), big.NewInt(exponent), nil))
	} else if exponent < 0 {
		denominator.Mul(denominator, new(big.Int).Exp(big.NewInt(10), big.NewInt(-exponent), nil))
	}
	return new(big.Rat).SetFrac(numerator, denominator), true
}

func stringHex(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return stringToI(receiver, newInt(16))
}

func stringOct(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	s := strings.TrimLeft(stringRawValue(receiver), " \t\n\r\v\f")
	negative := false
	if strings.HasPrefix(s, "+") || strings.HasPrefix(s, "-") {
		negative = s[0] == '-'
		s = s[1:]
	}
	base := 8
	for prefix, candidateBase := range map[byte]int{'b': 2, 'o': 8, 'd': 10, 'x': 16} {
		if hasStringBasePrefix(s, prefix) {
			base = candidateBase
			s = s[2:]
			break
		}
	}
	return parseStringIntegerDigits(s, base, negative)
}

func stringCrypt(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 1 {
		return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 1)", len(args)))
	}
	salt, errVal := stringCoerceConcatenationString(args[0])
	if errVal != nil {
		return errVal
	}
	passwordText := stringRawValue(receiver)
	saltText := stringRawValue(salt)
	if strings.ContainsRune(passwordText, '\x00') {
		return NewArgumentError("string contains null byte")
	}
	if len(saltText) < 2 || saltText[0] == 0 || saltText[1] == 0 {
		return NewArgumentError("salt too short")
	}
	result, ok := platformCrypt(passwordText, saltText)
	if !ok {
		return newRuntimeException(R.Classes["NotImplementedError"], "crypt is not supported on this platform")
	}
	return rubyString(result)
}

func stringSum(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) > 1 {
		return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 0..1)", len(args)))
	}
	bits := int64(16)
	if len(args) == 1 {
		value := args[0]
		if value == nil || value.Type != object.ValueInteger {
			if value == nil || CallMethod == nil || !receiverHasCallableMethod(value, "to_int") {
				return conversionTypeErrorToInteger(value)
			}
			value = CallMethod(value, "to_int")
			if value == nil || value.Type != object.ValueInteger {
				return conversionTypeErrorToInteger(args[0])
			}
		}
		integer, ok := numericBigIntValue(value)
		if !ok || !integer.IsInt64() {
			return NewRangeError("integer out of range")
		}
		bits = integer.Int64()
	}
	total := new(big.Int)
	for _, character := range []byte(stringRawValue(receiver)) {
		total.Add(total, big.NewInt(int64(character)))
	}
	if bits > 0 && bits < int64(total.BitLen()) {
		mask := new(big.Int).Sub(new(big.Int).Lsh(big.NewInt(1), uint(bits)), big.NewInt(1))
		total.And(total, mask)
	}
	return NewIntegerFromBigInt(total)
}

func stringFloatPrefixEnd(value string) int {
	index := 0
	if index < len(value) && (value[index] == '+' || value[index] == '-') {
		index++
	}
	start := index
	integerEnd, integerDigits := scanStringFloatDigits(value, index)
	index = integerEnd
	digits := integerDigits
	if index < len(value) && value[index] == '.' {
		index++
		fractionEnd, fractionDigits := scanStringFloatDigits(value, index)
		index = fractionEnd
		digits += fractionDigits
	}
	if digits == 0 {
		return 0
	}
	if index < len(value) && (value[index] == 'e' || value[index] == 'E') {
		exponentStart := index
		index++
		if index < len(value) && (value[index] == '+' || value[index] == '-') {
			index++
		}
		exponentEnd, exponentDigits := scanStringFloatDigits(value, index)
		if exponentDigits > 0 {
			index = exponentEnd
		} else {
			index = exponentStart
		}
	}
	if index == start {
		return 0
	}
	return index
}

func scanStringFloatDigits(value string, start int) (int, int) {
	index := start
	digits := 0
	for index < len(value) {
		if value[index] >= '0' && value[index] <= '9' {
			digits++
			index++
			continue
		}
		if value[index] == '_' && digits > 0 && index+1 < len(value) && value[index+1] >= '0' && value[index+1] <= '9' {
			index++
			continue
		}
		break
	}
	return index, digits
}

func parseStringIntegerDigits(value string, base int, negative bool) *object.EmeraldValue {
	digits := make([]byte, 0, len(value))
	for index := 0; index < len(value); index++ {
		digit := stringDigitValue(value[index])
		if digit >= 0 && digit < base {
			digits = append(digits, "0123456789abcdefghijklmnopqrstuvwxyz"[digit])
			continue
		}
		if value[index] == '_' && len(digits) > 0 && index+1 < len(value) {
			next := stringDigitValue(value[index+1])
			if next >= 0 && next < base {
				continue
			}
		}
		break
	}
	if len(digits) == 0 {
		return newInt(0)
	}
	integer, ok := new(big.Int).SetString(string(digits), base)
	if !ok {
		return newInt(0)
	}
	if negative {
		integer.Neg(integer)
	}
	return NewIntegerFromBigInt(integer)
}

func newIOShimValue(className string) *object.EmeraldValue {
	cls := R.Classes[className]
	if cls == nil {
		cls = R.Classes["IO"]
	}
	data := &ioShimData{cachedSize: -1, fd: nextIOFd, dupSourceFD: -1, closeOnExec: true, autoclose: true, peerFD: -1, pid: -1, encodingExplicit: false}
	nextIOFd++
	if ioDataByFd != nil {
		ioDataByFd[data.fd] = data
	}
	return &object.EmeraldValue{
		Type:  object.ValueObject,
		Data:  data,
		Class: cls,
	}
}

func setIOClassFromReceiver(io *object.EmeraldValue, receiver *object.EmeraldValue) *object.EmeraldValue {
	if io == nil || receiver == nil {
		return io
	}
	if receiver.Type != object.ValueClass {
		return io
	}
	cls, ok := receiver.Data.(*object.Class)
	if !ok || cls == nil {
		return io
	}
	io.Class = cls
	return io
}

func ioInspect(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data := ioShim(receiver)
	className := "IO"
	if receiver != nil && receiver.Class != nil && receiver.Class.Name != "" {
		className = receiver.Class.Name
	}
	if data == nil || data.closed {
		return rubyString(fmt.Sprintf("#<%s:(closed)>", className))
	}
	return rubyString(fmt.Sprintf("#<%s:fd %d>", className, data.fd))
}

func ioClassTryConvert(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 1 {
		return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 1)", len(args)))
	}
	value := args[0]
	if ioShim(value) != nil {
		return value
	}
	if value == nil || !receiverHasCallableMethod(value, "to_io") || CallMethod == nil {
		return R.NilVal
	}
	previousException := LastException
	previousRaisedResult := LastRaisedResult
	converted := CallMethod(value, "to_io")
	if converted != nil && converted.Type == object.ValueException {
		return converted
	}
	if LastException != nil && LastException != previousException {
		return LastException
	}
	if LastRaisedResult != nil && LastRaisedResult != previousRaisedResult {
		return LastRaisedResult
	}
	if ioShim(converted) == nil {
		from := "Object"
		to := "NilClass"
		if value != nil && value.Class != nil {
			from = value.Class.Name
		}
		if converted != nil && converted.Class != nil {
			to = converted.Class.Name
		}
		return typeError(fmt.Sprintf("can't convert %s into IO (%s#to_io gives %s)", from, from, to))
	}
	return converted
}

func ioClassSysopen(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) < 1 || len(args) > 3 {
		return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 1..3)", len(args)))
	}
	path, errVal := coercePath(args[0])
	if errVal != nil {
		return errVal
	}
	mode := rubyString("r")
	if len(args) > 1 && args[1] != nil && args[1].Type != object.ValueNil {
		mode = args[1]
	}
	if len(args) > 2 && args[2] != nil && args[2].Type != object.ValueNil && args[2].Type != object.ValueInteger {
		return typeError("no implicit conversion into Integer")
	}
	previousSuppress := suppressFileOpenBlock
	suppressFileOpenBlock = true
	file := fileClassOpen(nil, rubyString(path), mode)
	suppressFileOpenBlock = previousSuppress
	if file == nil || file.Type == object.ValueException {
		return file
	}
	return ioFileno(file)
}

func ioIoctl(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data := ioShim(receiver)
	if data == nil || data.closed {
		return newRuntimeException(R.Classes["IOError"], "closed stream")
	}
	if len(args) < 1 || len(args) > 2 {
		return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 1..2)", len(args)))
	}
	return newRuntimeException(R.Classes["Errno::ENOTTY"], "Inappropriate ioctl for device")
}

func ioClassPipe(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	read := setIOClassFromReceiver(newIOShimValue("IO"), receiver)
	write := setIOClassFromReceiver(newIOShimValue("IO"), receiver)
	readData := ioShim(read)
	writeData := ioShim(write)
	if readData != nil {
		readData.isReadPipe = true
		readData.mode = "r"
		readData.nonblock = true
		if len(args) == 0 {
			applyDefaultIOEncoding(readData)
		} else if result := ioSetEncoding(read, args...); result != nil && result.Type == object.ValueException {
			return result
		}
	}
	if writeData != nil {
		writeData.isReadPipe = false
		writeData.mode = "w"
		writeData.nonblock = true
	}
	if readData != nil && writeData != nil {
		if hostRead, hostWrite, err := os.Pipe(); err == nil {
			readData.hostFile = hostRead
			writeData.hostFile = hostWrite
		}
		readData.peerFD = writeData.fd
		writeData.peerFD = readData.fd
		pipe := ioEnsurePipeBufferForFD(readData.fd)
		ioPipeBuffers[writeData.fd] = pipe
		ioPipeBuffers[readData.fd] = pipe
	}
	if receiver != nil && receiver.Type == object.ValueClass && receiver.Data.(*object.Class) != R.Classes["IO"] {
		call := CallMethodBypass
		if call == nil {
			call = CallMethod
		}
		if call != nil {
			if result := call(read, "initialize", newInt(readData.fd)); result != nil && result.Type == object.ValueException {
				return result
			}
			if result := call(write, "initialize", newInt(writeData.fd)); result != nil && result.Type == object.ValueException {
				return result
			}
		}
	}
	if !suppressIOPipeBlock && BlockGivenCheck != nil && BlockGivenCheck() && CurrentBlockValue != nil && CallBlockWithArgs != nil {
		return CallBlockWithArgs(CurrentBlockValue(), read, write)
	}
	return &object.EmeraldValue{
		Type:  object.ValueArray,
		Data:  []*object.EmeraldValue{read, write},
		Class: R.Classes["Array"],
	}
}

func ioPipeBufferForFD(fd int64) *bytes.Buffer {
	if ioPipeBuffers == nil {
		return nil
	}
	return ioPipeBuffers[fd]
}

const (
	ioWaitReadable = int64(1)
	ioWaitWritable = int64(2)
)

func installIOWait() {
	ioClass := R.Classes["IO"]
	if ioClass == nil {
		return
	}
	ioClass.DefineConstant("READABLE", newInt(ioWaitReadable))
	ioClass.DefineConstant("WRITABLE", newInt(ioWaitWritable))
	ioClass.DefineMethod("wait", &object.Method{Name: "wait", Fn: ioWait, Arity: -1})
	ioClass.DefineMethod("wait_readable", &object.Method{Name: "wait_readable", Fn: ioWaitReadableMethod, Arity: -1})
	ioClass.DefineMethod("wait_writable", &object.Method{Name: "wait_writable", Fn: ioWaitWritableMethod, Arity: -1})
}

func ioWait(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data := ioShim(receiver)
	if data == nil || data.closed {
		return newRuntimeException(R.Classes["IOError"], "closed stream")
	}
	hasModeArg := false
	for _, arg := range args {
		if arg != nil && arg.Type == object.ValueSymbol {
			hasModeArg = true
			break
		}
	}
	if !hasModeArg && len(args) > 0 && args[0] != nil && args[0].Type == object.ValueInteger {
		if len(args) > 2 && args[1] != nil && args[1].Type == object.ValueInteger {
			return NewArgumentError("timeout given more than once")
		}
		timeoutPositive := len(args) > 1 && args[1] != nil && numericValueAsFloat(args[1]) > 0
		events := args[0].Data.(int64)
		if events <= 0 {
			return NewArgumentError("Events must be positive integer!")
		}
		ready := int64(0)
		if events&ioWaitReadable != 0 && ioReadyReadable(receiver) {
			ready |= ioWaitReadable
		}
		if events&ioWaitWritable != 0 && ioReadyWritable(receiver) {
			ready |= ioWaitWritable
		}
		if ready == 0 {
			if timeoutPositive {
				if current := threadClassCurrent(nil); current != nil {
					if currentData := threadValueData(current); currentData != nil {
						currentData.stopped = true
					}
				}
				return threadBlockedResult
			}
			return R.NilVal
		}
		return newInt(ready)
	}
	ready := false
	seenTimeout := false
	timeoutPositive := false
	for _, arg := range args {
		if arg == nil || arg.Type == object.ValueNil {
			continue
		}
		switch arg.Type {
		case object.ValueInteger, object.ValueFloat:
			if seenTimeout {
				return NewArgumentError("timeout given more than once")
			}
			seenTimeout = true
			timeoutPositive = numericValueAsFloat(arg) > 0
		case object.ValueSymbol:
			mode := arg.Data.(string)
			switch mode {
			case "r", "read", "readable":
				ready = ready || ioReadyReadable(receiver)
			case "w", "write", "writable":
				ready = ready || ioReadyWritable(receiver)
			case "rw", "read_write", "readable_writable":
				ready = ready || ioReadyReadable(receiver) || ioReadyWritable(receiver)
			default:
				return NewArgumentError("unsupported mode: " + mode)
			}
		}
	}
	if len(args) == 0 {
		ready = ioReadyReadable(receiver)
	}
	if ready {
		return receiver
	}
	if timeoutPositive {
		if current := threadClassCurrent(nil); current != nil {
			if currentData := threadValueData(current); currentData != nil {
				currentData.stopped = true
			}
		}
		return threadBlockedResult
	}
	return R.NilVal
}

func ioWaitReadableMethod(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if data := ioShim(receiver); data == nil || data.closed {
		return newRuntimeException(R.Classes["IOError"], "closed stream")
	}
	if ioReadyReadable(receiver) {
		return receiver
	}
	return R.NilVal
}

func ioWaitWritableMethod(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if data := ioShim(receiver); data == nil || data.closed {
		return newRuntimeException(R.Classes["IOError"], "closed stream")
	}
	if ioReadyWritable(receiver) {
		return receiver
	}
	return R.NilVal
}

func ioReadyReadable(receiver *object.EmeraldValue) bool {
	data := ioShim(receiver)
	if data == nil || data.closed || data.readClosed {
		return false
	}
	if data.path != "" || data.ungetBuffer != "" {
		return true
	}
	if pipe := ioPipeBufferForFD(data.fd); pipe != nil {
		return pipe.Len() > 0
	}
	return true
}

func ioReadyWritable(receiver *object.EmeraldValue) bool {
	data := ioShim(receiver)
	if data == nil || data.closed || data.writeClosed {
		return false
	}
	if data.fd == 1 || data.fd == 2 {
		return true
	}
	if data.path != "" {
		return true
	}
	if data.peerFD >= 0 {
		if peer := ioDataByFd[data.peerFD]; peer != nil {
			if pipe := ioPipeBufferForFD(data.fd); pipe != nil && peer.offset >= int64(pipe.Len()) {
				data.writeCalls = 0
				return true
			}
		}
	}
	return data.writeCalls < 6
}

func ioFIFOStateForPath(path string) *ioFIFOState {
	if ioFIFOStates == nil {
		ioFIFOStates = make(map[string]*ioFIFOState)
	}
	state, ok := ioFIFOStates[path]
	if !ok || state == nil {
		state = &ioFIFOState{buffer: &bytes.Buffer{}}
		ioFIFOStates[path] = state
	}
	return state
}

func ioWaitForFIFOPeer(path string, readable, writable, nonblock bool) *object.EmeraldValue {
	waitingReader := false
	waitingWriter := false
	for {
		ioFIFOStatesMu.Lock()
		state := ioFIFOStateForPath(path)
		if state == nil {
			ioFIFOStatesMu.Unlock()
			return newRuntimeException(R.Classes["SystemCallError"], "No such file or directory")
		}
		needsReader := writable && !readable
		needsWriter := readable && !writable
		if !needsReader && !needsWriter {
			if readable {
				state.readers++
			}
			if writable {
				state.writers++
			}
			if waitingReader && state.waitingReaders > 0 {
				state.waitingReaders--
			}
			if waitingWriter && state.waitingWriters > 0 {
				state.waitingWriters--
			}
			ioFIFOStatesMu.Unlock()
			return nil
		}

		if nonblock {
			if needsReader {
				if state.readers > 0 {
					state.writers++
					if waitingWriter && state.waitingWriters > 0 {
						state.waitingWriters--
					}
					ioFIFOStatesMu.Unlock()
					return nil
				}
				if state.readers == 0 {
					ioFIFOStatesMu.Unlock()
					return newRuntimeException(R.Classes["Errno::ENXIO"], "No such device or address")
				}
			}
			if needsWriter {
				state.readers++
				if waitingReader && state.waitingReaders > 0 {
					state.waitingReaders--
				}
				ioFIFOStatesMu.Unlock()
				return nil
			}
		}

		if needsReader {
			if state.readers > 0 || state.waitingWriters > 0 {
				state.writers++
				if waitingReader && state.waitingReaders > 0 {
					state.waitingReaders--
				}
				ioFIFOStatesMu.Unlock()
				return nil
			}
			if !waitingReader {
				state.waitingReaders++
				waitingReader = true
			}
			ioFIFOStatesMu.Unlock()
			current := threadClassCurrent(nil)
			if currentData := threadValueData(current); currentData != nil {
				currentData.stopped = true
			}
			if len(pendingThreads) == 0 {
				time.Sleep(1 * time.Millisecond)
			} else {
				runNextPendingThread()
			}
			if currentData := threadValueData(current); currentData != nil {
				currentData.stopped = false
			}
			continue
		}

		if needsWriter {
			if state.writers > 0 || state.waitingReaders > 0 {
				state.readers++
				if waitingWriter && state.waitingWriters > 0 {
					state.waitingWriters--
				}
				ioFIFOStatesMu.Unlock()
				return nil
			}
			if !waitingWriter {
				state.waitingWriters++
				waitingWriter = true
			}
			ioFIFOStatesMu.Unlock()
			current := threadClassCurrent(nil)
			if currentData := threadValueData(current); currentData != nil {
				currentData.stopped = true
			}
			if len(pendingThreads) == 0 {
				time.Sleep(1 * time.Millisecond)
			} else {
				runNextPendingThread()
			}
			if currentData := threadValueData(current); currentData != nil {
				currentData.stopped = false
			}
			continue
		}
	}
}

func ioReleaseFIFOPath(path string, readable bool, writable bool) {
	if path == "" {
		return
	}
	ioFIFOStatesMu.Lock()
	state := ioFIFOStates[path]
	if state == nil {
		ioFIFOStatesMu.Unlock()
		return
	}
	if readable && state.readers > 0 {
		state.readers--
	}
	if writable && state.writers > 0 {
		state.writers--
	}
	if state.readers <= 0 && state.writers <= 0 && state.waitingReaders <= 0 && state.waitingWriters <= 0 {
		delete(ioFIFOStates, path)
	}
	ioFIFOStatesMu.Unlock()
}

func ioFIFOReadContent(path string) string {
	ioFIFOStatesMu.Lock()
	defer ioFIFOStatesMu.Unlock()
	state := ioFIFOStates[path]
	if state == nil || state.buffer == nil {
		return ""
	}
	return state.buffer.String()
}

func ioFIFOWriteContent(path string, content string) {
	ioFIFOStatesMu.Lock()
	defer ioFIFOStatesMu.Unlock()
	state := ioFIFOStateForPath(path)
	if state == nil {
		return
	}
	_, _ = state.buffer.WriteString(content)
}

func ioFIFOHasReader(path string) bool {
	ioFIFOStatesMu.Lock()
	defer ioFIFOStatesMu.Unlock()
	state := ioFIFOStates[path]
	return state != nil && state.readers > 0
}

func ioFIFOHasWriter(path string) bool {
	ioFIFOStatesMu.Lock()
	defer ioFIFOStatesMu.Unlock()
	state := ioFIFOStates[path]
	return state != nil && state.writers > 0
}

func ioFIFOHasData(path string) bool {
	return ioFIFOReadContent(path) != ""
}

func ioEnsurePipeBufferForFD(fd int64) *bytes.Buffer {
	if ioPipeBuffers == nil {
		ioPipeBuffers = make(map[int64]*bytes.Buffer)
	}
	buffer, ok := ioPipeBuffers[fd]
	if !ok || buffer == nil {
		buffer = &bytes.Buffer{}
		ioPipeBuffers[fd] = buffer
	}
	return buffer
}

func stringIOClassNew(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	io := setIOClassFromReceiver(newIOShimValue("StringIO"), receiver)
	return stringIOInitialize(io, args...)
}

func stringIOClassOpen(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	io := setIOClassFromReceiver(newIOShimValue("StringIO"), receiver)
	result := stringIOInitialize(io, args...)
	if result == nil || result.Type == object.ValueException {
		return result
	}
	if BlockGivenCheck != nil && BlockGivenCheck() && CurrentBlockValue != nil && CallBlockWithArgs != nil {
		blockResult := CallBlockWithArgs(CurrentBlockValue(), result)
		closeResult := ioClose(result)
		if data := ioShim(result); data != nil {
			data.stringValue = R.NilVal
		}
		if closeResult != nil && closeResult.Type == object.ValueException {
			return closeResult
		}
		return blockResult
	}
	return result
}

func stringIOInitialize(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data := ioShim(receiver)
	if data == nil {
		io := newIOShimValue("StringIO")
		receiver.Type = io.Type
		receiver.Data = io.Data
		if receiver.Class == nil {
			receiver.Class = io.Class
		}
		data = ioShim(receiver)
	}

	stringArg := (*object.EmeraldValue)(nil)
	if len(args) > 0 {
		stringArg = args[0]
	}
	initialString := ""
	initialValue := (*object.EmeraldValue)(nil)
	if stringArg == nil || stringArg.Type == object.ValueNil {
		initialValue = rubyString("")
		if defaultExternalEncoding != "" {
			stringEncodings[initialValue] = defaultExternalEncoding
		}
	} else if stringArg.Type == object.ValueString {
		initialValue = stringArg
		initialString, _ = stringArg.Data.(string)
	} else {
		rawValue, converted, viaToStr, errVal := evalCoerceToString(stringArg)
		if errVal != nil {
			return errVal
		}
		if !converted {
			return conversionTypeErrorToStringForMode(stringArg, viaToStr)
		}
		initialString = rawValue
		initialValue = rubyString(initialString)
	}

	mode := "r+"
	hasExplicitMode := false
	modeExplicitByPositional := false
	hasExplicitIntegerMode := false
	explicitIntegerMode := int64(0)
	if len(args) > 1 {
		if args[1] != nil && args[1].Type != object.ValueNil && args[1].Type != object.ValueHash {
			switch args[1].Type {
			case object.ValueString:
				hasExplicitMode = true
				modeExplicitByPositional = true
			case object.ValueInteger:
				hasExplicitMode = true
				modeExplicitByPositional = true
				hasExplicitIntegerMode = true
				explicitIntegerMode = args[1].Data.(int64)
			default:
				rawMode, converted, viaToStr, errVal := evalCoerceToString(args[1])
				if errVal != nil {
					return errVal
				}
				if !converted {
					return conversionTypeErrorToStringForMode(args[1], viaToStr)
				}
				coercedArgs := make([]*object.EmeraldValue, len(args))
				copy(coercedArgs, args)
				coercedArgs[1] = rubyString(rawMode)
				args = coercedArgs
				hasExplicitMode = true
				modeExplicitByPositional = true
			}
		}
	}
	openArgs := make([]*object.EmeraldValue, 0, len(args)+1)
	openArgs = append(openArgs, initialValue)
	if len(args) > 1 {
		openArgs = append(openArgs, args[1:]...)
	}
	if hasExplicitMode {
		if modeExplicitByPositional {
			mode = fileOpenMode(openArgs)
		}
	} else {
		if initialValue != nil && initialValue.Type == object.ValueString && initialValue.Frozen {
			mode = "r"
		}
	}

	modeHasBinary := strings.Contains(mode, "b")
	modeHasText := strings.Contains(mode, "t")
	modeHasEncoding := false
	externalEncodingValue := ""
	internalEncodingValue := ""
	encodingOptionValue := ""
	encodingOptionSet := false
	encodingOptionInternalValue := ""
	encodingOptionInternalSet := false
	externalEncodingOptionSet := false
	binmodeOptionSet := false
	binmodeOptionValue := false
	textmodeOptionSet := false
	if strings.Contains(mode, ":") {
		parsedMode, modeExternalEncoding, modeInternalEncoding, errVal := parseModeEncodingFromMode(mode)
		if errVal != nil {
			return errVal
		}
		mode = parsedMode
		externalEncodingValue = modeExternalEncoding
		internalEncodingValue = modeInternalEncoding
		modeHasEncoding = true
		modeHasBinary = strings.Contains(mode, "b")
		modeHasText = strings.Contains(mode, "t")
	}
	modeEncodingSpecified := modeHasEncoding

	if len(args) > 1 {
		for _, arg := range args[1:] {
			if arg == nil || arg.Type != object.ValueHash {
				continue
			}
			for key, value := range valueToHashMap(arg) {
				switch specName(key) {
				case "mode":
					if value == nil || value.Type == object.ValueNil {
						continue
					}
					switch value.Type {
					case object.ValueString:
						mode = value.Data.(string)
						hasExplicitMode = true
						hasExplicitIntegerMode = false
						explicitIntegerMode = 0
					case object.ValueInteger:
						explicitIntegerMode = value.Data.(int64)
						hasExplicitIntegerMode = true
						mode = fileModeFromFlags(explicitIntegerMode)
						hasExplicitMode = true
					default:
						rawMode, converted, viaToStr, errVal := evalCoerceToString(value)
						if errVal != nil {
							return errVal
						}
						if !converted {
							return conversionTypeErrorToStringForMode(value, viaToStr)
						}
						mode = rawMode
						hasExplicitMode = true
						hasExplicitIntegerMode = false
						explicitIntegerMode = 0
					}
				case "encoding":
					parsedEncoding, okValue := fileOpenEncodingValue(value)
					if !okValue {
						return NewArgumentError("wrong type")
					}
					encodingOptionSet = true
					encodingOptionValue = parsedEncoding
					parts := strings.SplitN(parsedEncoding, ":", 2)
					if len(parts) > 1 {
						encodingOptionValue = parts[0]
						encodingOptionInternalSet = true
						encodingOptionInternalValue = parts[1]
						if encodingOptionInternalValue == "" || strings.EqualFold(encodingOptionInternalValue, "-") || strings.EqualFold(encodingOptionInternalValue, encodingOptionValue) {
							encodingOptionInternalValue = ""
							encodingOptionInternalSet = false
						}
					}
				case "external_encoding":
					parsedEncoding, okValue := fileOpenEncodingValue(value)
					if !okValue {
						return NewArgumentError("wrong type")
					}
					externalEncodingOptionSet = true
					externalEncodingValue = parsedEncoding
				case "internal_encoding":
					parsedEncoding, okValue := fileOpenEncodingValue(value)
					if !okValue {
						return NewArgumentError("wrong type")
					}
					if strings.EqualFold(parsedEncoding, "-") {
						parsedEncoding = ""
					}
					encodingOptionInternalSet = true
					encodingOptionInternalValue = parsedEncoding
				case "binmode":
					if value != nil && value.Type == object.ValueBool && value.Data.(bool) {
						binmodeOptionSet = true
						binmodeOptionValue = true
					} else if value != nil && value.Type == object.ValueBool && !value.Data.(bool) {
						binmodeOptionSet = true
						binmodeOptionValue = false
					} else {
						return NewArgumentError("wrong type")
					}
				case "textmode":
					textmodeOptionSet = true
					if value != nil && value.Type == object.ValueBool && value.Data.(bool) {
					} else if value != nil && value.Type == object.ValueBool && !value.Data.(bool) {
					} else {
						return NewArgumentError("wrong type")
					}
				}
			}
		}
	}

	modeHasBinary = strings.Contains(mode, "b")
	modeHasText = strings.Contains(mode, "t")
	modeHasEncoding = modeEncodingSpecified
	externalEncodingValue = ""
	internalEncodingValue = ""
	if strings.Contains(mode, ":") {
		parsedMode, modeExternalEncoding, modeInternalEncoding, parseModeErr := parseModeEncodingFromMode(mode)
		if parseModeErr != nil {
			return parseModeErr
		}
		mode = parsedMode
		externalEncodingValue = modeExternalEncoding
		internalEncodingValue = modeInternalEncoding
		modeHasEncoding = true
	}

	if hasExplicitMode {
		validateMode := mode
		if strings.Contains(validateMode, ":") {
			parsedMode, _, _, parseModeErr := parseModeEncodingFromMode(validateMode)
			if parseModeErr != nil {
				return parseModeErr
			}
			validateMode = parsedMode
		}
		if errVal := validateFileOpenMode(validateMode, []*object.EmeraldValue{openArgs[0], rubyString(validateMode)}); errVal != nil {
			return errVal
		}
	}
	truncateMode := (!hasExplicitIntegerMode && strings.Contains(mode, "w")) || (hasExplicitIntegerMode && explicitIntegerMode&512 != 0)

	if hasExplicitMode && initialValue != nil && initialValue.Type == object.ValueString && initialValue.Frozen {
		if hasExplicitIntegerMode && explicitIntegerMode&512 != 0 && !fileModeWritable(mode) {
			return frozenError("can't modify frozen String")
		}
		if fileModeWritable(mode) {
			return newRuntimeException(R.Classes["Errno::EACCES"], "Permission denied")
		}
	}
	if truncateMode {
		initialString = ""
	}

	if strings.EqualFold(encodingOptionInternalValue, "-") {
		encodingOptionInternalValue = ""
	}
	if strings.EqualFold(internalEncodingValue, encodingOptionValue) && encodingOptionValue != "" {
		internalEncodingValue = ""
	}
	if strings.EqualFold(internalEncodingValue, externalEncodingValue) && externalEncodingValue != "" {
		internalEncodingValue = ""
	}
	if strings.EqualFold(encodingOptionInternalValue, encodingOptionValue) && encodingOptionValue != "" {
		encodingOptionInternalValue = ""
	}
	if encodingOptionSet && (externalEncodingOptionSet || encodingOptionInternalSet) {
		_ = builtinWarn(nil, rubyString("Ignoring encoding parameter"))
		encodingOptionSet = false
		encodingOptionValue = ""
		encodingOptionInternalSet = false
		encodingOptionInternalValue = ""
	}
	if (modeHasEncoding || strings.Contains(mode, ":")) && (encodingOptionSet || externalEncodingOptionSet || encodingOptionInternalSet) {
		return NewArgumentError("encoding specified twice")
	}
	if binmodeOptionSet && textmodeOptionSet {
		return NewArgumentError("invalid mode mode")
	}
	if binmodeOptionSet && modeHasBinary {
		return NewArgumentError("invalid mode mode")
	}
	if binmodeOptionSet && modeHasText {
		return NewArgumentError("invalid mode mode")
	}
	if textmodeOptionSet && modeHasBinary {
		return NewArgumentError("invalid mode mode")
	}
	if textmodeOptionSet && modeHasText {
		return NewArgumentError("invalid mode mode")
	}

	data.mode = mode
	data.stringValue = initialValue
	data.path = ""
	data.pathEncoding = ""
	data.closed = false
	data.readClosed = !fileModeReadable(mode)
	data.writeClosed = !fileModeWritable(mode)
	data.peerFD = -1
	data.peerClosed = false
	data.ungetBuffer = ""
	data.cachedSize = int64(len(initialString))
	data.offset = 0
	data.sync = true
	data.binmode = strings.Contains(mode, "b")
	data.externalEncoding = externalEncodingValue
	data.internalEncoding = internalEncodingValue
	data.encodingInvalidReplace = false
	data.encodingReplaceString = ""
	data.encodingSetBySetter = false
	data.encodingExplicit = modeHasEncoding || encodingOptionSet || externalEncodingOptionSet || encodingOptionInternalSet
	if encodingOptionSet {
		data.externalEncoding = encodingOptionValue
	}
	if encodingOptionInternalSet {
		data.internalEncoding = encodingOptionInternalValue
	}
	if binmodeOptionSet {
		data.binmode = binmodeOptionValue
		if binmodeOptionValue {
			data.externalEncoding = "BINARY"
			data.internalEncoding = ""
		}
	}
	if textmodeOptionSet {
		data.binmode = false
	}
	if data.externalEncoding != "" && data.internalEncoding != "" && strings.EqualFold(data.externalEncoding, data.internalEncoding) {
		data.internalEncoding = ""
	}
	if data.externalEncoding == "" {
		data.externalEncoding = stringEncodingName(initialValue)
	}
	applyDefaultIOEncoding(data)
	if strings.Contains(mode, "a") {
		data.offset = int64(len(initialString))
	}

	buffer := ioEnsurePipeBufferForFD(data.fd)
	buffer.Reset()
	_, _ = buffer.WriteString(initialString)
	stringIOSyncValue(data, initialString)
	return receiver
}

func stringIOReopen(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data := ioShim(receiver)
	if data == nil {
		return R.NilVal
	}
	data.lineno = 0

	switch len(args) {
	case 0:
		current := stringIOString(receiver)
		if current == nil {
			current = rubyString("")
		}
		result := stringIOInitialize(receiver, current, rubyString("r+"))
		if result != nil && result.Type == object.ValueException {
			return result
		}
		return receiver
	case 1:
		firstArg := args[0]
		switch {
		case firstArg == nil || firstArg.Type == object.ValueNil:
			result := stringIOInitialize(receiver, rubyString(""), rubyString("r+"))
			if result != nil && result.Type == object.ValueException {
				return result
			}
			return receiver
		case firstArg.Type == object.ValueString:
			result := stringIOInitialize(receiver, firstArg, rubyString("r+"))
			if result != nil && result.Type == object.ValueException {
				return result
			}
			return receiver
		case ioShim(firstArg) != nil:
			reopenedValue := stringIOString(firstArg)
			if reopenedValue == nil {
				return typeError("no implicit conversion into StringIO")
			}
			result := stringIOInitialize(receiver, reopenedValue, rubyString("r+"))
			if result != nil && result.Type == object.ValueException {
				return result
			}
			return receiver
		case firstArg != nil && firstArg.Class != nil && receiverHasCallableMethod(firstArg, "to_strio") && CallMethod != nil:
			coerced := CallMethod(firstArg, "to_strio")
			if coerced != nil && coerced.Type == object.ValueException {
				return coerced
			}
			reopenedValue := stringIOString(coerced)
			if reopenedValue == nil {
				return typeError("no implicit conversion into StringIO")
			}
			result := stringIOInitialize(receiver, reopenedValue, rubyString("r+"))
			if result != nil && result.Type == object.ValueException {
				return result
			}
			return receiver
		default:
			return typeError("no implicit conversion into StringIO")
		}
	default:
		result := stringIOInitialize(receiver, args...)
		if result != nil && result.Type == object.ValueException {
			return result
		}
		return receiver
	}
}

func stringIOInspect(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	className := "StringIO"
	if receiver != nil && receiver.Class != nil && receiver.Class.Name != "" {
		className = receiver.Class.Name
	}
	return rubyString(fmt.Sprintf("#<%s:%p>", className, receiver))
}

func stringIOString(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data := ioShim(receiver)
	if data == nil {
		return R.NilVal
	}
	return data.stringValue
}

func stringIOSetString(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data := ioShim(receiver)
	if data == nil {
		return R.NilVal
	}
	if data.closed {
		return newRuntimeException(R.Classes["IOError"], "closed stream")
	}
	if len(args) < 1 {
		return NewArgumentError("wrong number of arguments")
	}
	var nextValue *object.EmeraldValue
	if args[0] != nil && args[0].Type == object.ValueString {
		nextValue = args[0]
	} else if args[0] == nil || args[0].Type == object.ValueNil {
		nextValue = rubyString("")
	} else {
		rawValue, converted, viaToStr, errVal := evalCoerceToString(args[0])
		if errVal != nil {
			return errVal
		}
		if !converted {
			return conversionTypeErrorToStringForMode(args[0], viaToStr)
		}
		nextValue = rubyString(rawValue)
	}
	next, _ := nextValue.Data.(string)
	buffer := ioEnsurePipeBufferForFD(data.fd)
	buffer.Reset()
	_, _ = buffer.WriteString(next)
	data.stringValue = nextValue
	data.offset = 0
	data.cachedSize = int64(len(next))
	data.ungetBuffer = ""
	if data.externalEncoding != "" {
		stringIOSyncValue(data, next)
	} else if stringEncodings != nil {
		stringEncodings[data.stringValue] = stringEncodingName(data.stringValue)
	}
	return data.stringValue
}

func stringIOSize(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data := ioShim(receiver)
	if data == nil {
		return &object.EmeraldValue{Type: object.ValueInteger, Data: int64(0), Class: R.Classes["Integer"]}
	}
	if buf := ioPipeBufferForFD(data.fd); buf != nil {
		return &object.EmeraldValue{Type: object.ValueInteger, Data: int64(buf.Len()), Class: R.Classes["Integer"]}
	}
	return &object.EmeraldValue{Type: object.ValueInteger, Data: int64(0), Class: R.Classes["Integer"]}
}

