func fileGroupOwnedPredicate(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	info, errVal := fileInfoForPredicate(args, false)
	if errVal != nil {
		return errVal
	}
	if info == nil {
		return R.FalseVal
	}
	stat, ok := info.Sys().(*syscall.Stat_t)
	if !ok {
		return R.FalseVal
	}
	groups, _ := os.Getgroups()
	groups = append(groups, os.Getegid())
	for _, gid := range groups {
		if uint32(gid) == stat.Gid {
			return R.TrueVal
		}
	}
	return R.FalseVal
}

