func filePermissionPredicate(path string, uid, gid int, mask os.FileMode) *object.EmeraldValue {
	info, err := os.Stat(path)
	if err != nil {
		return R.FalseVal
	}
	if uid == 0 {
		return R.TrueVal
	}
	stat, ok := info.Sys().(*syscall.Stat_t)
	if !ok {
		if info.Mode().Perm()&mask != 0 {
			return R.TrueVal
		}
		return R.FalseVal
	}
	perms := info.Mode().Perm()
	allowed := os.FileMode(0)
	if uint32(uid) == stat.Uid {
		allowed = mask & 0700
	} else {
		inGroup := uint32(gid) == stat.Gid
		if !inGroup {
			groups, _ := os.Getgroups()
			for _, candidate := range groups {
				if uint32(candidate) == stat.Gid {
					inGroup = true
					break
				}
			}
		}
		if inGroup {
			allowed = mask & 0070
		} else {
			allowed = mask & 0007
		}
	}
	if perms&allowed != 0 {
		return R.TrueVal
	}
	return R.FalseVal
}

func dirClassMkdir(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 0 {
		return NewArgumentError("wrong number of arguments")
	}
	path, errVal := coercePath(args[0])
	if errVal != nil {
		return errVal
	}
	mode := os.FileMode(0755)
	if len(args) > 1 {
		if args[1].Type == object.ValueInteger {
			mode = os.FileMode(args[1].Data.(int64))
		} else if CallMethod != nil {
			coerced := CallMethod(args[1], "to_int")
			if coerced != nil && coerced.Type == object.ValueInteger {
				mode = os.FileMode(coerced.Data.(int64))
			} else if coerced != nil && coerced.Type == object.ValueException && !isNoMethodError(coerced) {
				return coerced
			} else {
				return typeError("no implicit conversion of Object into Integer")
			}
		}
	}
	mode = unixModeToFileMode(mode)
	if err := os.Mkdir(path, mode); err != nil {
		return errnoForPathError(err)
	}
	_ = os.Chmod(path, mode)
	return &object.EmeraldValue{Type: object.ValueInteger, Data: int64(0), Class: R.Classes["Integer"]}
}

