func fileInstanceFlock(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data := ioShim(receiver)
	if data == nil || data.path == "" {
		return R.FalseVal
	}
	if data.closed {
		return newRuntimeException(R.Classes["IOError"], "closed stream")
	}
	if len(args) != 1 || args[0] == nil || args[0].Type != object.ValueInteger {
		return typeError("no implicit conversion into Integer")
	}
	operation := args[0].Data.(int64)
	locks := fileLocks[data.path]
	if locks == nil {
		locks = map[*object.EmeraldValue]int64{}
		fileLocks[data.path] = locks
	}
	if operation&8 != 0 {
		delete(locks, receiver)
		_ = os.Remove(data.path + ".rgo-flock-exclusive")
		if len(locks) == 0 {
			delete(fileLocks, data.path)
		}
		for _, waiter := range fileLockWaiters[data.path] {
			if waiterData := threadValueData(waiter); waiterData != nil && !waiterData.finished {
				waiterData.stopped = false
				queuePendingThread(waiter)
			}
		}
		delete(fileLockWaiters, data.path)
		return newInt(0)
	}
	wantExclusive := operation&2 != 0
	conflict := false
	if _, err := os.Stat(data.path + ".rgo-flock-exclusive"); err == nil && locks[receiver]&2 == 0 {
		conflict = true
	}
	for owner, mode := range locks {
		if owner == receiver {
			continue
		}
		if wantExclusive || mode&2 != 0 {
			conflict = true
			break
		}
	}
	if conflict {
		if operation&4 != 0 {
			return R.FalseVal
		}
		if InThreadBlock != nil && InThreadBlock() {
			current := threadClassCurrent(nil)
			if currentData := threadValueData(current); currentData != nil {
				currentData.stopped = true
				alreadyWaiting := false
				for _, waiter := range fileLockWaiters[data.path] {
					if waiter == current {
						alreadyWaiting = true
						break
					}
				}
				if !alreadyWaiting {
					fileLockWaiters[data.path] = append(fileLockWaiters[data.path], current)
				}
				if SuspendCurrentThread != nil {
					result := SuspendCurrentThread()
					currentData.stopped = false
					if result != nil && result.Type == object.ValueException {
						return result
					}
					return fileInstanceFlock(receiver, args...)
				}
			}
			return threadBlockedResult
		}
		return R.NilVal
	}
	locks[receiver] = operation & 3
	if wantExclusive {
		_ = os.WriteFile(data.path+".rgo-flock-exclusive", nil, 0600)
	}
	return newInt(0)
}

