func fileStatInspect(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data, stat := fileStatSystem(receiver)
	if data == nil || data.info == nil || stat == nil {
		return rubyString("#<File::Stat>")
	}
	mode := int64(data.info.Mode().Perm())
	switch {
	case data.info.Mode().IsRegular():
		mode |= 0100000
	case data.info.IsDir():
		mode |= 0040000
	case data.info.Mode()&os.ModeSymlink != 0:
		mode |= 0120000
	}
	timeText := timeInspect(newTimeValue(data.info.ModTime())).Data.(string)
	text := fmt.Sprintf("#<File::Stat dev=0x%x, ino=%d, mode=%07o, nlink=%d, uid=%d, gid=%d, rdev=0x%x, size=%d, blksize=%d, blocks=%d, atime=%s, mtime=%s, ctime=%s>",
		uint64(1), uint64(1), mode, stat.Nlink, stat.Uid, stat.Gid, uint64(0), data.info.Size(), int64(4096), stat.Blocks, timeText, timeText, timeText)
	return rubyString(text)
}

func fileStatFtype(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data := fileStatDataFrom(receiver)
	ftype := "unknown"
	if data != nil && unixServerPaths[data.path] {
		return rubyString("socket")
	}
	if data != nil && data.info != nil {
		mode := data.info.Mode()
		switch {
		case mode&os.ModeSymlink != 0:
			ftype = "link"
		case mode.IsRegular():
			ftype = "file"
		case mode.IsDir():
			ftype = "directory"
		case mode&os.ModeNamedPipe != 0:
			ftype = "fifo"
		case mode&os.ModeSocket != 0:
			ftype = "socket"
		case mode&os.ModeCharDevice != 0:
			ftype = "characterSpecial"
		case mode&os.ModeDevice != 0:
			ftype = "blockSpecial"
		}
	}
	return rubyString(ftype)
}

