func dirClassMktmpdir(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	prefix := "d"
	suffix := ""
	if len(args) > 0 && args[0] != nil && args[0].Type != object.ValueNil {
		p, s, errVal := tempfilePrefixSuffix(args[0])
		if errVal != nil {
			return errVal
		}
		prefix, suffix = p, s
	}
	base := filepath.Join(os.TempDir(), "rgo-spec")
	if CallMethod != nil {
		if tmp := CallMethod(&object.EmeraldValue{Type: object.ValueClass, Data: R.Classes["Dir"], Class: R.Classes["Class"]}, "tmpdir"); tmp != nil && tmp.Type == object.ValueString {
			base = tmp.Data.(string)
		}
	}
	_ = os.MkdirAll(base, 0755)
	path := filepath.Join(base, fmt.Sprintf("%s%d%s", sanitizeTempfileName(prefix), time.Now().UnixNano(), sanitizeTempfileName(suffix)))
	if err := os.MkdirAll(path, 0755); err != nil {
		return errnoForPathError(err)
	}
	if BlockGivenCheck != nil && BlockGivenCheck() && CurrentBlockValue != nil && CallBlockWithArgs != nil {
		result := CallBlockWithArgs(CurrentBlockValue(), rubyString(path))
		_ = os.Remove(path)
		return result
	}
	return rubyString(path)
}

