func argfEachLine(receiver *object.EmeraldValue, state *argfData, args ...*object.EmeraldValue) *object.EmeraldValue {
	sep := "\n"
	if len(args) > 0 && args[0] != nil && args[0].Type == object.ValueString {
		sep = args[0].Data.(string)
	}
	if BlockGivenCheck == nil || !BlockGivenCheck() || CurrentBlockValue == nil || CurrentBlockValue() == nil {
		snapshot := *state
		return newGeneratorEnumerator(func() ([]*object.EmeraldValue, *object.EmeraldValue) {
			return argfEachLineValues(&snapshot, sep)
		})
	}
	block := CurrentBlockValue()
	for {
		line := argfNextSeparatedLine(state, sep)
		if line == nil {
			break
		}
		if result := CallBlockWithArgs(block, line); result != nil && result.Type == object.ValueException {
			return result
		}
	}
	return receiver
}

func argfEachLineValues(state *argfData, sep string) ([]*object.EmeraldValue, *object.EmeraldValue) {
	values := []*object.EmeraldValue{}
	for {
		line := argfNextSeparatedLine(state, sep)
		if line == nil {
			break
		}
		values = append(values, line)
	}
	return values, nil
}

func argfEachCodepoint(receiver *object.EmeraldValue, state *argfData) *object.EmeraldValue {
	if BlockGivenCheck == nil || !BlockGivenCheck() || CurrentBlockValue == nil || CurrentBlockValue() == nil {
		snapshot := *state
		return newGeneratorEnumerator(func() ([]*object.EmeraldValue, *object.EmeraldValue) {
			return argfEachCodepointValues(&snapshot)
		})
	}
	block := CurrentBlockValue()
	for {
		value := argfNextCodepoint(state)
		if value == nil {
			break
		}
		if result := CallBlockWithArgs(block, value); result != nil && result.Type == object.ValueException {
			return result
		}
	}
	return receiver
}

func argfEachUnit(receiver *object.EmeraldValue, state *argfData, chars bool) *object.EmeraldValue {
	snapshot := *state
	build := func() ([]*object.EmeraldValue, *object.EmeraldValue) {
		text := argfRead(&snapshot, -1)
		values := make([]*object.EmeraldValue, 0, len(text))
		if chars {
			for _, character := range text {
				value := rubyString(string(character))
				if snapshot.encoding != "" {
					SetStringEncoding(value, snapshot.encoding)
				}
				values = append(values, value)
			}
		} else {
			for _, b := range []byte(text) {
				values = append(values, newInt(int64(b)))
			}
		}
		return values, nil
	}
	if BlockGivenCheck == nil || !BlockGivenCheck() || CurrentBlockValue == nil || CurrentBlockValue() == nil {
		return newGeneratorEnumerator(build)
	}
	values, _ := build()
	for _, value := range values {
		if result := CallBlockWithArgs(CurrentBlockValue(), value); result != nil && result.Type == object.ValueException {
			return result
		}
	}
	*state = snapshot
	return receiver
}

func argfEachCodepointValues(state *argfData) ([]*object.EmeraldValue, *object.EmeraldValue) {
	values := []*object.EmeraldValue{}
	for {
		value := argfNextCodepoint(state)
		if value == nil {
			break
		}
		values = append(values, value)
	}
	return values, nil
}

func argfNextCodepoint(state *argfData) *object.EmeraldValue {
	if !argfEnsureContent(state) {
		return nil
	}
	r, size := utf8.DecodeRuneInString(state.content[state.offset:])
	if r == utf8.RuneError && size == 0 {
		return nil
	}
	state.offset += size
	return &object.EmeraldValue{Type: object.ValueInteger, Data: int64(r), Class: R.Classes["Integer"]}
}

func argfEof(state *argfData) *object.EmeraldValue {
	if state.closed {
		return newRuntimeException(R.Classes["IOError"], "closed stream")
	}
	if state.content == "" && state.index >= len(state.paths) {
		return R.TrueVal
	}
	if state.content != "" && state.offset >= len(state.content) {
		return R.TrueVal
	}
	return R.FalseVal
}

func argfGetc(state *argfData, raiseEOF bool) *object.EmeraldValue {
	if !argfEnsureContent(state) {
		if raiseEOF {
			return newRuntimeException(R.Classes["EOFError"], "end of file reached")
		}
		return R.NilVal
	}
	ch := state.content[state.offset : state.offset+1]
	state.offset++
	return rubyString(ch)
}

func argfGets(state *argfData, raiseEOF bool) *object.EmeraldValue {
	line := argfNextSeparatedLine(state, "\n")
	if line == nil {
		if raiseEOF {
			return newRuntimeException(R.Classes["EOFError"], "end of file reached")
		}
		return R.NilVal
	}
	return line
}

func argfNextSeparatedLine(state *argfData, sep string) *object.EmeraldValue {
	if !argfEnsureContent(state) {
		return nil
	}
	remaining := state.content[state.offset:]
	next := -1
	if sep != "" {
		next = strings.Index(remaining, sep)
	}
	if next >= 0 {
		end := next + len(sep)
		line := remaining[:end]
		state.offset += end
		state.lineno++
		SetGlobalVariableIfAvailable("$.", newInt(state.lineno))
		SetGlobalVariableIfAvailable("$_", rubyString(line))
		result := rubyString(line)
		if state.encoding != "" {
			SetStringEncoding(result, state.encoding)
		}
		return result
	}
	state.offset = len(state.content)
	state.lineno++
	SetGlobalVariableIfAvailable("$.", newInt(state.lineno))
	SetGlobalVariableIfAvailable("$_", rubyString(remaining))
	result := rubyString(remaining)
	if state.encoding != "" {
		SetStringEncoding(result, state.encoding)
	}
	return result
}

func argfReadpartial(state *argfData, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 0 {
		return NewArgumentError("wrong number of arguments")
	}
	lengthArg := args[0]
	if lengthArg == nil || lengthArg.Type == object.ValueNil {
		return typeError("no implicit conversion of nil into Integer")
	}
	limitVal := int64(0)
	if lengthArg.Type == object.ValueInteger {
		limitVal = lengthArg.Data.(int64)
	} else if receiverHasCallableMethod(lengthArg, "to_int") && CallMethod != nil {
		coerced := CallMethod(lengthArg, "to_int")
		if coerced != nil && coerced.Type == object.ValueException {
			return coerced
		}
		if coerced == nil {
			return typeError("no implicit conversion into Integer")
		}
		if coerced.Type != object.ValueInteger {
			msg := "no implicit conversion into Integer"
			if lengthArg != nil && lengthArg.Class != nil {
				msg = "no implicit conversion of " + lengthArg.Class.Name + " into Integer"
				if lengthArg.Type == object.ValueNil {
					msg = "no implicit conversion of nil into Integer"
				}
			}
			return typeError(msg)
		}
		lengthArg = coerced
		limitVal = lengthArg.Data.(int64)
	} else {
		msg := "no implicit conversion into Integer"
		if lengthArg != nil && lengthArg.Class != nil {
			msg = "no implicit conversion of " + lengthArg.Class.Name + " into Integer"
			if lengthArg.Type == object.ValueNil {
				msg = "no implicit conversion of nil into Integer"
			}
		}
		return typeError(msg)
	}
	if limitVal < 0 {
		return NewArgumentError("negative length")
	}
	var buffer *object.EmeraldValue
	if len(args) > 1 && args[1] != nil && args[1].Type != object.ValueNil {
		if args[1].Type == object.ValueString {
			buffer = args[1]
		} else if receiverHasCallableMethod(args[1], "to_str") && CallMethod != nil {
			coerced := CallMethod(args[1], "to_str")
			if coerced != nil && coerced.Type == object.ValueException {
				return coerced
			}
			if coerced != nil && coerced.Type == object.ValueString {
				buffer = coerced
			} else {
				return typeError("no implicit conversion into String")
			}
		} else {
			return typeError("no implicit conversion into String")
		}
	}
	if buffer != nil {
		buffer.Data = ""
	}
	if state.closed {
		return newRuntimeException(R.Classes["EOFError"], "end of file reached")
	}
	if state.content != "" && state.offset >= len(state.content) {
		if argfAdvance(state) {
			if limitVal == 0 {
				if buffer != nil {
					return buffer
				}
				return rubyString("")
			}
			return rubyString("")
		}
		if buffer != nil {
			buffer.Data = ""
		}
		return newRuntimeException(R.Classes["EOFError"], "end of file reached")
	}
	if !argfEnsureContent(state) {
		if buffer != nil {
			buffer.Data = ""
		}
		return newRuntimeException(R.Classes["EOFError"], "end of file reached")
	}
	limit := int(limitVal)
	if limit == 0 {
		if buffer != nil {
			return buffer
		}
		return rubyString("")
	}
	remaining := state.content[state.offset:]
	if limit < len(remaining) {
		remaining = remaining[:limit]
	}
	state.offset += len(remaining)
	result := rubyString(remaining)
	if buffer != nil {
		buffer.Data = remaining
		return buffer
	}
	return result
}

func argfReadNonblock(state *argfData, args ...*object.EmeraldValue) *object.EmeraldValue {
	if state.content == "" && state.index < len(state.paths) && state.paths[state.index] == "-" {
		if argfExceptionFalse(args) {
			return &object.EmeraldValue{Type: object.ValueSymbol, Data: "wait_readable", Class: R.Classes["Symbol"]}
		}
		return newRuntimeException(R.Classes["IO::EAGAINWaitReadable"], "Resource temporarily unavailable")
	}
	return argfReadpartial(state, args...)
}

func argfExceptionFalse(args []*object.EmeraldValue) bool {
	if len(args) == 0 {
		return false
	}
	last := args[len(args)-1]
	if last == nil || last.Type != object.ValueHash {
		return false
	}
	hash := valueToHashMap(last)
	if hash == nil {
		return false
	}
	for key, value := range hash {
		if specName(key) == "exception" && value == R.FalseVal {
			return true
		}
	}
	return false
}

func argfRead(state *argfData, limit int) string {
	if limit == 0 {
		return ""
	}
	var out strings.Builder
	for limit < 0 || out.Len() < limit {
		if !argfEnsureContent(state) {
			break
		}
		remaining := state.content[state.offset:]
		if limit >= 0 {
			needed := limit - out.Len()
			if needed < len(remaining) {
				out.WriteString(remaining[:needed])
				state.offset += needed
				break
			}
		}
		out.WriteString(remaining)
		state.offset = len(state.content)
	}
	return out.String()
}

func argfEnsureContent(state *argfData) bool {
	for {
		if state.offset < len(state.content) {
			return true
		}
		if !argfAdvance(state) {
			return false
		}
	}
}

// argfEnsureCurrent opens the first input but deliberately preserves a current
// file positioned at EOF. Positioning APIs operate on that file until a read
// attempts to move past its end.
func argfEnsureCurrent(state *argfData) bool {
	if state.closed {
		return false
	}
	if state.io != nil {
		return true
	}
	return argfAdvance(state)
}

func argfAdvance(state *argfData) bool {
	for state.index < len(state.paths) {
		path := state.paths[state.index]
		state.index++
		state.path = path
		state.closed = false
		if path == "/dev/zero" {
			state.content = strings.Repeat("\x00", 4096)
			state.offset = 0
			return true
		}
		data, err := os.ReadFile(path)
		if err != nil {
			continue
		}
		state.content = string(data)
		state.offset = 0
		state.io = newIOShimValue("File")
		if ioData := ioShim(state.io); ioData != nil {
			ioData.path = path
			ioData.mode = "r"
			ioData.externalEncoding = state.encoding
		}
		if len(state.content) > 0 {
			return true
		}
	}
	state.content = ""
	state.offset = 0
	state.io = nil
	state.closed = true
	return false
}

