func ioUngetc(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data := ioShim(receiver)
	if data == nil || data.closed || data.readClosed {
		return newRuntimeException(R.Classes["IOError"], "closed stream")
	}
	if len(args) != 1 {
		return NewArgumentError("wrong number of arguments")
	}
	if !fileModeReadable(data.mode) {
		return newRuntimeException(R.Classes["IOError"], "not opened for reading")
	}
	value := args[0]
	switch {
	case value == nil:
		return typeError("no implicit conversion of nil into String")
	case value.Type == object.ValueInteger:
		intVal := value.Data.(int64)
		externalEncoding := normalizeEncodingNameForIO(data.externalEncoding)
		character := string(rune(intVal))
		if externalEncoding != "" && externalEncoding != "UTF-8" {
			character = string([]byte{byte(intVal)})
		}
		data.ungetBuffer = character + data.ungetBuffer
	case value.Type == object.ValueString:
		data.ungetBuffer = value.Data.(string) + data.ungetBuffer
	case value != nil && value.Class != nil && receiverHasCallableMethod(value, "to_str") && CallMethod != nil:
		coerced := CallMethod(value, "to_str")
		if coerced != nil && coerced.Type == object.ValueException {
			return coerced
		}
		if coerced != nil && coerced.Type == object.ValueString {
			data.ungetBuffer = coerced.Data.(string) + data.ungetBuffer
		} else {
			return typeError("no implicit conversion into String")
		}
	default:
		return typeError("no implicit conversion into String")
	}
	data.bufferedRead = true
	return R.NilVal
}

func ioUngetbyte(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data := ioShim(receiver)
	if data == nil || data.closed || data.readClosed {
		return newRuntimeException(R.Classes["IOError"], "closed stream")
	}
	if len(args) != 1 {
		return NewArgumentError("wrong number of arguments")
	}
	if !fileModeReadable(data.mode) {
		return newRuntimeException(R.Classes["IOError"], "not opened for reading")
	}
	value := args[0]
	switch {
	case value == nil || value.Type == object.ValueNil:
		return R.NilVal
	case value.Type == object.ValueInteger:
		intVal := value.Data.(int64)
		data.ungetBuffer = string([]byte{byte(intVal)}) + data.ungetBuffer
	case value.Type == object.ValueString:
		str := value.Data.(string)
		data.ungetBuffer = str + data.ungetBuffer
	case value != nil && value.Class != nil && receiverHasCallableMethod(value, "to_str") && CallMethod != nil:
		coerced := CallMethod(value, "to_str")
		if coerced != nil && coerced.Type == object.ValueException {
			return coerced
		}
		if coerced == nil || coerced.Type != object.ValueString {
			return typeError("no implicit conversion into String")
		}
		data.ungetBuffer = coerced.Data.(string) + data.ungetBuffer
	case value != nil && value.Class != nil && receiverHasCallableMethod(value, "to_int") && CallMethod != nil:
		coerced := CallMethod(value, "to_int")
		if coerced != nil && coerced.Type == object.ValueException {
			return coerced
		}
		if coerced != nil && coerced.Type == object.ValueInteger {
			intVal := coerced.Data.(int64)
			data.ungetBuffer = string([]byte{byte(intVal)}) + data.ungetBuffer
		} else {
			return typeError("no implicit conversion into Integer")
		}
	default:
		return typeError("no implicit conversion into Integer")
	}
	data.bufferedRead = true
	return R.NilVal
}

func ioEachLine(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	data := ioShim(receiver)
	if data == nil {
		return R.NilVal
	}
	if data.closed {
		return newRuntimeException(R.Classes["IOError"], "closed stream")
	}
	positional := args
	if len(positional) > 0 && positional[len(positional)-1] != nil && positional[len(positional)-1].Type == object.ValueHash && Ruby2KeywordHash(positional[len(positional)-1]) {
		positional = positional[:len(positional)-1]
	}
	if len(positional) == 1 && positional[0] != nil && positional[0].Type != object.ValueNil && positional[0].Type != object.ValueString && positional[0].Type != object.ValueInteger {
		if _, converted, _, coerceErr := evalCoerceToString(positional[0]); coerceErr != nil {
			return coerceErr
		} else if !converted {
			return conversionTypeErrorToString(positional[0])
		}
	}
	if len(positional) >= 2 {
		separator := positional[0]
		if separator != nil && separator.Type != object.ValueNil && separator.Type != object.ValueString {
			if _, converted, _, coerceErr := evalCoerceToString(separator); coerceErr != nil {
				return coerceErr
			} else if !converted {
				return conversionTypeErrorToString(separator)
			}
		}
		if _, ok := valueToInteger(positional[1]); !ok {
			return conversionTypeErrorToInteger(positional[1])
		}
	}
	var limitValue *object.EmeraldValue
	if len(positional) == 1 && positional[0] != nil && positional[0].Type == object.ValueInteger {
		limitValue = positional[0]
	} else if len(positional) >= 2 {
		limitValue = positional[1]
	}
	if limitValue != nil && limitValue.Type == object.ValueInteger {
		if limit, ok := numericBigIntValue(limitValue); ok {
			if limit.Sign() == 0 {
				return NewArgumentError("invalid limit: 0 for each_line")
			}
			min := new(big.Int).Neg(new(big.Int).Lsh(big.NewInt(1), 63))
			max := new(big.Int).Sub(new(big.Int).Lsh(big.NewInt(1), 63), big.NewInt(1))
			if limit.Cmp(min) < 0 || limit.Cmp(max) > 0 {
				return NewRangeError("integer out of range")
			}
		}
	}
	if BlockGivenCheck != nil && BlockGivenCheck() && CurrentBlockValue != nil && CallBlockWithArgs != nil {
		prev := R.NilVal
		if GetGlobalVariable != nil {
			prev = GetGlobalVariable("$_")
		}
		for {
			value := fileInstanceGets(receiver, args...)
			if value == nil || value == R.NilVal {
				break
			}
			if value.Type == object.ValueException {
				if value.Class == R.Classes["EOFError"] {
					break
				}
				return value
			}
			if value == R.NilVal {
				break
			}
			LastBlockResult = nil
			ForEachClearNext()
			CallBlockWithArgs(CurrentBlockValue(), value)
			if LastBlockResult != nil {
				result := LastBlockResult
				LastBlockResult = nil
				if prev != nil && GetGlobalVariable != nil {
					SetGlobalVariableIfAvailable("$_", prev)
				}
				return result
			}
			if ForEachConsumeNext() {
				continue
			}
		}
		if prev != nil && GetGlobalVariable != nil {
			SetGlobalVariableIfAvailable("$_", prev)
		}
		return receiver
	}
	return newGeneratorEnumerator(func() ([]*object.EmeraldValue, *object.EmeraldValue) {
		results := []*object.EmeraldValue{}
		for {
			value := fileInstanceGets(receiver, args...)
			if value == nil || value == R.NilVal {
				return results, nil
			}
			if value.Type == object.ValueException {
				if value.Class == R.Classes["EOFError"] {
					return results, nil
				}
				return results, value
			}
			results = append(results, value)
		}
	})
}

