func compareValues(a, b *object.EmeraldValue) int {
	if a == nil || a.Type == object.ValueNil {
		if b == nil || b.Type == object.ValueNil {
			return 0
		}
		return -1
	}
	if b == nil || b.Type == object.ValueNil {
		return 1
	}
	switch a.Type {
	case object.ValueInteger:
		av := a.Data.(int64)
		switch b.Type {
		case object.ValueInteger:
			bv := b.Data.(int64)
			if av < bv {
				return -1
			} else if av > bv {
				return 1
			}
			return 0
		case object.ValueFloat:
			bv := b.Data.(float64)
			if float64(av) < bv {
				return -1
			} else if float64(av) > bv {
				return 1
			}
			return 0
		}
	case object.ValueFloat:
		av := a.Data.(float64)
		switch b.Type {
		case object.ValueInteger:
			bv := float64(b.Data.(int64))
			if av < bv {
				return -1
			} else if av > bv {
				return 1
			}
			return 0
		case object.ValueFloat:
			bv := b.Data.(float64)
			if av < bv {
				return -1
			} else if av > bv {
				return 1
			}
			return 0
		}
	case object.ValueString:
		if b.Type == object.ValueString {
			av := a.Data.(string)
			bv := b.Data.(string)
			if av < bv {
				return -1
			} else if av > bv {
				return 1
			}
			return 0
		}
	}
	return 0
}

