	objClass.DefineMethod("fixture", &object.Method{
		Name:  "fixture",
		Arity: -1,
		Fn: func(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
			if len(args) == 0 {
				return R.NilVal
			}
			file := CurrentSpecFile
			if args[0] != nil && args[0].Type == object.ValueString {
				file = args[0].Data.(string)
			}
			if file == "" || file == "spec.rb" {
				file = CurrentSpecFile
			}
			dir := filepath.Dir(file)
			fixtureDir := filepath.Join(dir, "fixtures")
			if filepath.Base(dir) == "fixtures" {
				fixtureDir = dir
			} else if filepath.Base(dir) == "shared" {
				fixtureDir = filepath.Join(filepath.Dir(dir), "fixtures")
			}
			parts := make([]string, 0, len(args)-1)
			for _, arg := range args[1:] {
				if arg == nil || arg.Type != object.ValueString {
					return R.NilVal
				}
				parts = append(parts, arg.Data.(string))
			}
			path := filepath.Join(append([]string{fixtureDir}, parts...)...)
			if _, err := os.Stat(path); err == nil {
				return rubyString(absFixturePath(path))
			}
			if len(parts) > 0 {
				if root, ok := rubySpecRootForPath(file); ok {
					sharedPath := filepath.Join(append([]string{root, "shared", filepath.Base(filepath.Dir(file)), "fixtures"}, parts...)...)
					if _, err := os.Stat(sharedPath); err == nil {
						return rubyString(absFixturePath(sharedPath))
					}
				}
			}
			return rubyString(absFixturePath(path))
		},
	})
