	objClass.DefineMethod("evaluate", &object.Method{
		Name:  "evaluate",
		Arity: -1,
		Fn: func(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
			var restoreMethods func()
			if len(args) > 0 && EvalSource != nil {
				if source, ok := args[0].Data.(string); ok {
					root := R.Classes["Object"]
					previous := make(map[string]*object.Method)
					missing := make(map[string]bool)
					for _, match := range regexp.MustCompile(`(?m)^\s*def\s+([A-Za-z_]\w*[!?=]?)`).FindAllStringSubmatch(source, -1) {
						name := match[1]
						if method, exists := root.Methods[name]; exists {
							previous[name] = method
						} else {
							missing[name] = true
						}
					}
					restoreMethods = func() {
						for name, method := range previous {
							root.Methods[name] = method
						}
						for name := range missing {
							delete(root.Methods, name)
						}
					}
					EvalSource(source)
				}
			}
			specRunner.ExampleCount++
			if CallBlock != nil && BlockGivenCheck != nil && BlockGivenCheck() {
				result := CallBlock()
				if restoreMethods != nil {
					restoreMethods()
				}
				return result
			}
			if restoreMethods != nil {
				restoreMethods()
			}
			return R.NilVal
		},
	})

