func versionIsMatches(args ...*object.EmeraldValue) bool {
	if len(args) < 2 || args[0] == nil || args[0].Type != object.ValueString || args[1] == nil {
		return false
	}
	current := args[0].Data.(string)
	switch args[1].Type {
	case object.ValueString:
		min := args[1].Data.(string)
		return min == "" || compareVersionStrings(current, min) >= 0
	case object.ValueRange:
		r := args[1].Data.(*object.RRange)
		if !r.StartMissing {
			if start, ok := versionEndpointString(r.StartValue); ok && start != "" && compareVersionStrings(current, start) < 0 {
				return false
			}
		}
		if !r.EndMissing {
			if end, ok := versionEndpointString(r.EndValue); ok && end != "" {
				cmp := compareVersionStrings(current, end)
				if cmp > 0 || cmp == 0 && r.Exclusive {
					return false
				}
			}
		}
		return true
	default:
		return false
	}
}

func rubyVersionIsMatches(args ...*object.EmeraldValue) bool {
	if len(args) == 0 || args[0] == nil || args[0].Type == object.ValueNil {
		return false
	}
	switch args[0].Type {
	case object.ValueRange:
		return versionIsMatches(rubyString(RubyCompatibilityVersion), args[0])
	case object.ValueString:
		version := args[0].Data.(string)
		if version == "" {
			return false
		}
		return compareVersionStrings(RubyCompatibilityVersion, version) >= 0
	default:
		return false
	}
}

func callGuardBlock() *object.EmeraldValue {
	LastBlockResult = nil
	result := CallBlock()
	if LastBlockResult != nil {
		result = LastBlockResult
		LastBlockResult = nil
	}
	if result == nil {
		return R.NilVal
	}
	return result
}

func versionEndpointString(value interface{}) (string, bool) {
	switch v := value.(type) {
	case string:
		return v, true
	case *object.EmeraldValue:
		if v != nil && v.Type == object.ValueString {
			return v.Data.(string), true
		}
	}
	return "", false
}

func compareVersionStrings(left, right string) int {
	lparts := strings.Split(left, ".")
	rparts := strings.Split(right, ".")
	n := len(lparts)
	if len(rparts) > n {
		n = len(rparts)
	}
	for i := 0; i < n; i++ {
		lv, rv := 0, 0
		if i < len(lparts) {
			lv, _ = strconv.Atoi(versionNumericPrefix(lparts[i]))
		}
		if i < len(rparts) {
			rv, _ = strconv.Atoi(versionNumericPrefix(rparts[i]))
		}
		if lv < rv {
			return -1
		}
		if lv > rv {
			return 1
		}
	}
	return 0
}

func versionNumericPrefix(part string) string {
	for i, r := range part {
		if r < '0' || r > '9' {
			if i == 0 {
				return "0"
			}
			return part[:i]
		}
	}
	if part == "" {
		return "0"
	}
	return part
}

func platformGuardMatches(args []*object.EmeraldValue) bool {
	if len(args) == 0 {
		return true
	}
	matchedPlatform := false
	last := args[len(args)-1]
	if last.Type != object.ValueHash {
		for _, arg := range args {
			if currentPlatformMatches(specName(arg)) {
				matchedPlatform = true
				break
			}
		}
		return matchedPlatform
	}
	for _, arg := range args[:len(args)-1] {
		if currentPlatformMatches(specName(arg)) {
			matchedPlatform = true
			break
		}
	}
	hashMatched := true
	for key, value := range valueToHashMap(last) {
		switch specName(key) {
		case "pointer_size":
			size, ok := valueToInteger(value)
			hashMatched = hashMatched && ok && int(size) == strconv.IntSize
		case "c_short_size":
			size, ok := valueToInteger(value)
			hashMatched = hashMatched && ok && int(size) == 16
		case "c_int_size":
			size, ok := valueToInteger(value)
			hashMatched = hashMatched && ok && int(size) == 32
		case "c_long_size":
			size, ok := valueToInteger(value)
			hashMatched = hashMatched && ok && int(size) == strconv.IntSize
		}
	}
	if len(args) == 1 {
		return hashMatched
	}
	return matchedPlatform && hashMatched
}

func currentPlatformMatches(name string) bool {
	switch name {
	case "":
		return false
	case "windows", "mingw":
		return runtime.GOOS == "windows"
	case "darwin", "macos":
		return runtime.GOOS == "darwin"
	case "linux":
		return runtime.GOOS == "linux"
	case "freebsd":
		return runtime.GOOS == "freebsd"
	case "openbsd":
		return runtime.GOOS == "openbsd"
	case "netbsd":
		return runtime.GOOS == "netbsd"
	case "bsd":
		return runtime.GOOS == "freebsd" || runtime.GOOS == "openbsd" || runtime.GOOS == "netbsd" || runtime.GOOS == "dragonfly"
	case "solaris":
		return runtime.GOOS == "solaris" || runtime.GOOS == "illumos"
	default:
		return name == runtime.GOOS
	}
}

func isLittleEndianArch() bool {
	switch runtime.GOARCH {
	case "s390x", "ppc64", "sparc64":
		return false
	default:
		return true
	}
}

func specName(value *object.EmeraldValue) string {
	name, _ := methodNameFromValue(value)
	return name
}

func methodNameFromValue(value *object.EmeraldValue) (string, bool) {
	name, ok, _ := methodNameFromValueWithError(value)
	if ok {
		return name, ok
	}
	return "", false
}

func MethodNameFromValueWithError(value *object.EmeraldValue) (string, bool, *object.EmeraldValue) {
	return methodNameFromValueWithError(value)
}

func MethodNameFromValue(value *object.EmeraldValue) (string, bool) {
	return methodNameFromValue(value)
}

func methodNameFromValueWithError(value *object.EmeraldValue) (string, bool, *object.EmeraldValue) {
	if value == nil {
		return "", false, nil
	}
	if value.Type == object.ValueString || value.Type == object.ValueSymbol {
		if s, ok := value.Data.(string); ok {
			return strings.TrimPrefix(s, ":"), true, nil
		}
	}

	str, converted, viaToStr, coerceErr := evalCoerceToString(value)
	if coerceErr != nil {
		return "", false, coerceErr
	}
	if !converted {
		if viaToStr {
			return "", false, conversionTypeErrorToStringForMode(value, true)
		}
		return "", false, nil
	}

	return strings.TrimPrefix(str, ":"), true, nil
}

func currentSpecContext() *specContext {
	if specRunner == nil || len(specRunner.Contexts) == 0 {
		return nil
	}
	return specRunner.Contexts[len(specRunner.Contexts)-1]
}

func runSpecExample(example *specExample) {
	if example == nil {
		return
	}
	LastException = nil
	LastRaisedResult = nil
	LastMatcherException = nil
	var restoreExampleState func()
	if BeginSpecExampleIsolation != nil {
		restoreExampleState = BeginSpecExampleIsolation()
	}
	if restoreExampleState != nil {
		defer restoreExampleState()
	}
	specRunner.ExampleCount++
	if example.Description != "" {
		fmt.Printf("  ✓ %s\n", example.Description)
	}
	if mainObj, ok := R.Main.Data.(*object.Object); ok {
		delete(mainObj.InstanceVars, "@method")
		delete(mainObj.InstanceVars, "@object")
		for _, ctx := range specRunner.Contexts {
			for name, value := range ctx.SharedVars {
				mainObj.InstanceVars[name] = value
			}
		}
		for name, value := range example.SharedVars {
			mainObj.InstanceVars[name] = value
		}
	}
	beforeFails := specRunner.FailCount
	runBeforeEachHooks()
	if example.Block != nil && CallBlockWithArgs != nil {
		CallBlockWithArgs(example.Block)
		LastBlockResult = nil
		if ClearPendingBlockControl != nil {
			ClearPendingBlockControl()
		}
	}
	runAfterEachHooks()
	LastBlockResult = nil
	LastException = nil
	LastRaisedResult = nil
	LastMatcherException = nil
	if os.Getenv("RGO_DEFINE_METHOD_DIAG") == "1" && specRunner.FailCount != beforeFails {
		fmt.Printf("RGO_DEFINE_METHOD_DIAG example %s failures %d -> %d\n", example.Description, beforeFails, specRunner.FailCount)
	}
}

func runSpecContext(ctx *specContext) {
	if ctx == nil {
		return
	}
	specRunner.Contexts = append(specRunner.Contexts, ctx)
	for _, block := range ctx.BeforeAll {
		if CallBlockWithArgs != nil {
			CallBlockWithArgs(block)
		}
	}
	ctx.SharedVars = currentSpecSharedVars()
	for _, item := range ctx.Items {
		if item.Example != nil {
			runSpecExample(item.Example)
		} else if item.Child != nil {
			runSpecContext(item.Child)
		}
	}
	for _, block := range ctx.AfterAll {
		if CallBlockWithArgs != nil {
			CallBlockWithArgs(block)
		}
	}
	specRunner.Contexts = specRunner.Contexts[:len(specRunner.Contexts)-1]
}

func hookScope(args []*object.EmeraldValue) string {
	if len(args) == 0 {
		return "each"
	}
	scope := specName(args[0])
	if scope == "all" || scope == "each" {
		return scope
	}
	return "each"
}

func runBeforeEachHooks() {
	if specRunner == nil || CallBlockWithArgs == nil {
		return
	}
	rootInContexts := false
	for _, ctx := range specRunner.Contexts {
		if ctx == specRunner.RootContext {
			rootInContexts = true
			break
		}
	}
	if !rootInContexts && specRunner.RootContext != nil {
		for _, block := range specRunner.RootContext.BeforeEach {
			CallBlockWithArgs(block)
		}
	}
	for _, ctx := range specRunner.Contexts {
		for _, block := range ctx.BeforeEach {
			CallBlockWithArgs(block)
		}
	}
}

func runAfterEachHooks() {
	if specRunner == nil || CallBlockWithArgs == nil {
		return
	}
	rootInContexts := false
	for i := len(specRunner.Contexts) - 1; i >= 0; i-- {
		ctx := specRunner.Contexts[i]
		if ctx == specRunner.RootContext {
			rootInContexts = true
		}
		for j := len(ctx.AfterEach) - 1; j >= 0; j-- {
			CallBlockWithArgs(ctx.AfterEach[j])
		}
	}
	if !rootInContexts && specRunner.RootContext != nil {
		for j := len(specRunner.RootContext.AfterEach) - 1; j >= 0; j-- {
			CallBlockWithArgs(specRunner.RootContext.AfterEach[j])
		}
	}
	for i := len(mockRestores) - 1; i >= 0; i-- {
		mockRestores[i]()
	}
	mockRestores = nil
	lastMockToAryReturn = nil
}

func isSharedExampleDefinition(args []*object.EmeraldValue) bool {
	if len(args) < 2 || args[len(args)-1].Type != object.ValueHash {
		return false
	}
	hash := valueToHashMap(args[len(args)-1])
	for key, value := range hash {
		if specName(key) == "shared" && value.IsTruthy() {
			return true
		}
	}
	return false
}

func exceptionPath(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver.Type != object.ValueException {
		return R.NilVal
	}
	exc := receiver.Data.(*object.RException)
	if exc.Path != "" {
		return rubyString(exc.Path)
	}
	if receiver.Class == nil {
		return R.NilVal
	}
	if classInheritsFrom(receiver.Class, R.Classes["LoadError"]) {
		const prefix = "cannot load such file -- "
		if strings.HasPrefix(exc.Message, prefix) {
			return rubyString(strings.TrimSpace(strings.TrimPrefix(exc.Message, prefix)))
		}
	}
	if classInheritsFrom(receiver.Class, R.Classes["SyntaxError"]) {
		if match := exceptionPathFromMessagePattern.FindStringSubmatch(exc.Message); len(match) == 2 {
			return rubyString(match[1])
		}
	}
	return R.NilVal
}

func exceptionMessage(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver.Type != object.ValueException {
		return R.NilVal
	}
	if CallMethod != nil && receiverHasCallableMethod(receiver, "to_s") {
		return CallMethod(receiver, "to_s")
	}
	return exceptionToS(receiver)
}

func exceptionCause(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver.Type != object.ValueException {
		return R.NilVal
	}
	exc := receiver.Data.(*object.RException)
	if exc.Cause != nil {
		return exc.Cause
	}
	return R.NilVal
}

