func nameErrorName(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver.Type != object.ValueException {
		return R.NilVal
	}
	exc := receiver.Data.(*object.RException)
	if exc.NameErrorNameValue != nil {
		return exc.NameErrorNameValue
	}
	if exc.NameErrorName != "" {
		return rubySymbol(exc.NameErrorName)
	}
	for _, prefix := range []string{"undefined method `", "undefined local variable `"} {
		if strings.HasPrefix(exc.Message, prefix) {
			name := strings.TrimPrefix(exc.Message, prefix)
			if end := strings.Index(name, "'"); end >= 0 {
				return rubySymbol(name[:end])
			}
		}
	}
	if strings.HasPrefix(exc.Message, "uninitialized constant ") {
		name := strings.TrimSpace(strings.TrimPrefix(exc.Message, "uninitialized constant "))
		if separator := strings.LastIndex(name, "::"); separator >= 0 {
			name = name[separator+2:]
		}
		if name != "" {
			return rubySymbol(name)
		}
	}
	if index := strings.Index(exc.Message, "@@"); index >= 0 {
		name := exc.Message[index:]
		if end := strings.IndexAny(name, " `':\n"); end > 1 {
			name = name[:end]
		}
		if name != "@@" {
			return rubySymbol(name)
		}
	}
	return R.NilVal
}

func exceptionKeywordValue(args []*object.EmeraldValue, name string) *object.EmeraldValue {
	if len(args) == 0 {
		return nil
	}
	last := args[len(args)-1]
	if last == nil || last.Type != object.ValueHash {
		return nil
	}
	for key, value := range valueToHashMap(last) {
		if specName(key) == name {
			return value
		}
	}
	return nil
}

func exceptionPositionalArgs(args []*object.EmeraldValue) []*object.EmeraldValue {
	if len(args) > 0 && args[len(args)-1] != nil && args[len(args)-1].Type == object.ValueHash {
		return args[:len(args)-1]
	}
	return args
}

func nameErrorInitialize(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver == nil || receiver.Type != object.ValueException {
		return receiver
	}
	positional := exceptionPositionalArgs(args)
	if len(positional) > 2 {
		return argumentError("wrong number of arguments")
	}
	exc := receiver.Data.(*object.RException)
	if len(positional) > 1 {
		exc.NameErrorNameValue = positional[1]
		exc.NameErrorName = specName(positional[1])
	}
	if value := exceptionKeywordValue(args, "receiver"); value != nil {
		exc.NameErrorReceiver = value
	}
	if len(positional) == 0 {
		exc.Message = receiver.Class.Name
		exc.MessageValue = nil
	}
	return receiver
}

