// Proc methods
func procCall(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if CallBlockWithArgs != nil {
		return CallBlockWithArgs(receiver, args...)
	}
	return R.NilVal
}

func procRuby2Keywords(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver == nil || receiver.Type != object.ValueProc {
		return receiver
	}
	proc, _ := receiver.Data.(*object.Proc)
	if proc == nil || proc.Fn == nil || !proc.Fn.HasRestParam || len(proc.Fn.KeywordParams) > 0 || proc.Fn.KeywordRestParam != "" || proc.Fn.KeywordRestOnly || proc.Fn.RestParamIndex < len(proc.Fn.Params) {
		fmt.Fprintln(os.Stderr, "warning: Skipping set of ruby2_keywords flag for proc")
		return receiver
	}
	if procRuby2KeywordFunctions == nil {
		procRuby2KeywordFunctions = make(map[*object.Function]bool)
	}
	procRuby2KeywordFunctions[proc.Fn] = true
	return receiver
}

func ProcRuby2Keywords(proc *object.Proc) bool {
	return proc != nil && proc.Fn != nil && procRuby2KeywordFunctions != nil && procRuby2KeywordFunctions[proc.Fn]
}

func procClassNew(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	var cls *object.Class
	if receiver != nil && receiver.Type == object.ValueClass {
		cls, _ = receiver.Data.(*object.Class)
	}
	if CurrentBlockValue != nil {
		if block := CurrentBlockValue(); block != nil {
			if proc := procValueFromCallable(block, cls); proc != nil {
				return proc
			}
			if cls == R.Classes["Proc"] && block.Type == object.ValueClosure {
				block.Data.(*object.Closure).AutoSplat = true
				if proc := procValueFromBlock(block, cls); proc != nil {
					return proc
				}
			}
			if cls != nil && cls != R.Classes["Proc"] {
				if block.Class == cls {
					return block
				}
				proc := procValueFromBlock(block, cls)
				if proc != nil {
					if CallMethod != nil && classHasMethod(proc.Class, "initialize") {
						result := CallMethod(proc, "initialize", args...)
						if result != nil && result.Type == object.ValueException {
							return result
						}
					}
					return proc
				}
			}
			return block
		}
	}
	return argumentError("tried to create Proc object without a block")
}

func procValueFromCallable(block *object.EmeraldValue, class *object.Class) *object.EmeraldValue {
	if class == nil {
		class = R.Classes["Proc"]
	}
	switch block.Type {
	case object.ValueMethod:
		methodValue := block
		return &object.EmeraldValue{
			Type: object.ValueProc,
			Data: &object.Proc{
				InstanceVars: make(map[string]*object.EmeraldValue),
				Native: func(args ...*object.EmeraldValue) *object.EmeraldValue {
					return methodCall(methodValue, args...)
				},
				IsLambda:     true,
				SourceMethod: methodValue.Data.(*object.Method),
			},
			Class: class,
		}
	case object.ValueSymbol:
		name, _ := block.Data.(string)
		return &object.EmeraldValue{
			Type: object.ValueProc,
			Data: &object.Proc{
				InstanceVars: make(map[string]*object.EmeraldValue),
				Native: func(args ...*object.EmeraldValue) *object.EmeraldValue {
					if len(args) == 0 || CallMethod == nil {
						return R.NilVal
					}
					return CallMethod(args[0], name, args[1:]...)
				},
			},
			Class: class,
		}
	default:
		return nil
	}
}

func procValueFromBlock(block *object.EmeraldValue, class *object.Class) *object.EmeraldValue {
	if class == nil {
		class = R.Classes["Proc"]
	}
	switch block.Type {
	case object.ValueProc:
		source := block.Data.(*object.Proc)
		copy := *source
		copy.InstanceVars = make(map[string]*object.EmeraldValue)
		if !copy.IsLambda && copy.ReturnOwnerID == 0 && CurrentFrameID != nil {
			copy.ReturnOwnerID = CurrentFrameID()
		}
		return &object.EmeraldValue{Type: object.ValueProc, Data: &copy, Class: class}
	case object.ValueClosure:
		closure := block.Data.(*object.Closure)
		return &object.EmeraldValue{
			Type: object.ValueProc,
			Data: &object.Proc{
				Fn:               closure.Fn,
				Env:              closure.Free,
				Block:            closure.Block,
				Binding:          closure.Binding,
				ClassStack:       closure.ClassStack,
				Refinements:      append([]*object.EmeraldValue(nil), closure.Refinements...),
				RefinementsFixed: closure.RefinementsFixed,
				InstanceVars:     make(map[string]*object.EmeraldValue),
				AutoSplat:        true,
				IsLambda:         false,
				ReturnOwnerID:    closure.ReturnOwnerID,
			},
			Class: class,
		}
	default:
		return nil
	}
}

func procClassAllocate(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return newRuntimeException(R.Classes["TypeError"], "allocator undefined for Proc")
}

func procHash(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	h := fnv.New64a()
	proc, _ := receiver.Data.(*object.Proc)
	identity := fmt.Sprintf("%p:%p", proc.Fn, proc.Env)
	if proc.Native != nil {
		identity += fmt.Sprintf(":%x", reflect.ValueOf(proc.Native).Pointer())
	}
	_, _ = h.Write([]byte(identity))
	return &object.EmeraldValue{Type: object.ValueInteger, Data: int64(h.Sum64()), Class: R.Classes["Integer"]}
}

func procArity(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	newArity := func(value int) *object.EmeraldValue {
		return &object.EmeraldValue{Type: object.ValueInteger, Data: int64(value), Class: R.Classes["Integer"]}
	}
	if receiver.Type == object.ValueProc {
		proc := receiver.Data.(*object.Proc)
		if proc.Native != nil {
			if proc.HasNativeArity {
				return newArity(proc.NativeArity)
			}
			return newArity(-1)
		}
		if proc.Fn != nil {
			return newArity(functionProcArity(proc.Fn, proc.IsLambda))
		}
	} else if receiver.Type == object.ValueClosure {
		closure := receiver.Data.(*object.Closure)
		if closure.Fn != nil {
			return newArity(functionProcArity(closure.Fn, false))
		}
	}
	return newArity(0)
}

func functionProcArity(fn *object.Function, lambda bool) int {
	required := 0
	hasOptionalPositional := false
	for index := range fn.Params {
		if index < len(fn.ParamDefaults) && fn.ParamDefaults[index] != nil {
			hasOptionalPositional = true
			continue
		}
		required++
	}
	hasRequiredKeyword := false
	hasOptionalKeyword := false
	for _, keyword := range fn.KeywordParams {
		if keyword.HasDefault {
			hasOptionalKeyword = true
		} else {
			hasRequiredKeyword = true
		}
	}
	if hasRequiredKeyword {
		required++
	}
	lambdaOptional := hasOptionalPositional || (fn.KeywordRestParam != "" && !hasRequiredKeyword) || (hasOptionalKeyword && !hasRequiredKeyword)
	if fn.HasRestParam || (lambda && lambdaOptional) {
		return -(required + 1)
	}
	return required
}

func procBinding(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	var binding *object.RBinding
	switch receiver.Type {
	case object.ValueProc:
		proc := receiver.Data.(*object.Proc)
		if proc.CurryTarget != nil {
			return argumentError("Can't create Binding from C level Proc")
		}
		binding = proc.Binding
	case object.ValueClosure:
		closure := receiver.Data.(*object.Closure)
		binding = closure.Binding
	}
	if binding == nil {
		binding = &object.RBinding{
			Self:         R.Main,
			Locals:       map[string]*object.EmeraldValue{},
			LocalNames:   nil,
			Constants:    map[string]*object.EmeraldValue{},
			Method:       "",
			InstanceVars: map[string]*object.EmeraldValue{},
			Path:         currentSourcePath(),
			Line:         1,
		}
	}
	return &object.EmeraldValue{Type: object.ValueBinding, Data: binding, Class: R.Classes["Binding"]}
}

func procCurry(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	arity := procRequiredArity(receiver)
	collected := []*object.EmeraldValue{}
	target := receiver
	if receiver.Type == object.ValueProc {
		proc := receiver.Data.(*object.Proc)
		if proc.CurryTarget != nil {
			target = proc.CurryTarget
			collected = append(collected, proc.CurryArgs...)
			arity = proc.CurryArity
		}
	}
	applyArgs := len(args) > 1
	if len(args) == 1 {
		if n, ok := valueToInteger(args[0]); ok {
			arity = int(n)
		}
	}
	if callableIsLambda(target) && !procLambdaAcceptsCurryArity(target, arity) {
		return argumentError("wrong number of arguments")
	}
	curried := newCurriedProc(target, arity, collected, callableIsLambda(target))
	if applyArgs {
		return callCallableValue(curried, args...)
	}
	return curried
}

func procLambdaAcceptsCurryArity(value *object.EmeraldValue, arity int) bool {
	min, max, hasRest := procArityRange(value)
	if arity < min {
		return false
	}
	if !hasRest && arity > max {
		return false
	}
	return true
}

func procArityRange(value *object.EmeraldValue) (int, int, bool) {
	fn := procFunction(value)
	if fn == nil {
		return 0, 0, false
	}
	required := 0
	for i := range fn.Params {
		if i < len(fn.ParamDefaults) && fn.ParamDefaults[i] != nil {
			continue
		}
		required++
	}
	return required, len(fn.Params), fn.HasRestParam
}

func procFunction(value *object.EmeraldValue) *object.Function {
	if value == nil {
		return nil
	}
	switch value.Type {
	case object.ValueProc:
		proc := value.Data.(*object.Proc)
		if proc.CurryTarget != nil {
			return procFunction(proc.CurryTarget)
		}
		if proc.Fn == nil && proc.SourceMethod != nil {
			fn, _ := proc.SourceMethod.Fn.(*object.Function)
			return fn
		}
		return proc.Fn
	case object.ValueClosure:
		return value.Data.(*object.Closure).Fn
	}
	return nil
}

func procNativeArity(value *object.EmeraldValue) (int, bool) {
	if value == nil || value.Type != object.ValueProc {
		return 0, false
	}
	proc := value.Data.(*object.Proc)
	if proc == nil || !proc.HasNativeArity {
		return 0, false
	}
	return proc.NativeArity, true
}

func procRequiredArity(value *object.EmeraldValue) int {
	if value == nil {
		return 0
	}
	switch value.Type {
	case object.ValueProc:
		proc := value.Data.(*object.Proc)
		if proc.CurryTarget != nil && proc.CurryArity > 0 {
			return proc.CurryArity
		}
		min, _, _ := procArityRange(value)
		return min
	case object.ValueClosure:
		min, _, _ := procArityRange(value)
		return min
	}
	return 0
}

func newCurriedProc(target *object.EmeraldValue, arity int, collected []*object.EmeraldValue, isLambda bool) *object.EmeraldValue {
	stored := append([]*object.EmeraldValue(nil), collected...)
	procValue := &object.EmeraldValue{Type: object.ValueProc, Class: R.Classes["Proc"]}
	proc := &object.Proc{
		InstanceVars: make(map[string]*object.EmeraldValue),
		IsLambda:     isLambda,
		CurryTarget:  target,
		CurryArgs:    stored,
		CurryArity:   arity,
	}
	proc.Native = func(args ...*object.EmeraldValue) *object.EmeraldValue {
		combined := append(append([]*object.EmeraldValue(nil), stored...), args...)
		if len(combined) >= arity {
			if isLambda && len(combined) > arity {
				return argumentError("wrong number of arguments")
			}
			return callCallableValue(target, combined...)
		}
		return newCurriedProc(target, arity, combined, isLambda)
	}
	procValue.Data = proc
	return procValue
}

func procParameters(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	var fn *object.Function
	var method *object.Method
	isLambda := false
	if receiver.Type == object.ValueProc {
		proc := receiver.Data.(*object.Proc)
		if proc.SymbolProc {
			return &object.EmeraldValue{Type: object.ValueArray, Data: []*object.EmeraldValue{
				procParameterPair("req", ""), procParameterPair("rest", ""),
			}, Class: R.Classes["Array"]}
		}
		if proc.CurryTarget != nil {
			inner := []*object.EmeraldValue{&object.EmeraldValue{Type: object.ValueSymbol, Data: "rest", Class: R.Classes["Symbol"]}}
			return &object.EmeraldValue{Type: object.ValueArray, Data: []*object.EmeraldValue{{Type: object.ValueArray, Data: inner, Class: R.Classes["Array"]}}, Class: R.Classes["Array"]}
		}
		fn = proc.Fn
		isLambda = proc.IsLambda
	} else if receiver.Type == object.ValueClosure {
		fn = receiver.Data.(*object.Closure).Fn
	} else if receiver.Type == object.ValueMethod {
		method = receiver.Data.(*object.Method)
		fn, _ = method.Fn.(*object.Function)
		isLambda = true
	}
	if len(args) > 0 && args[len(args)-1] != nil && args[len(args)-1].Type == object.ValueHash {
		if data := hashData(args[len(args)-1]); data != nil {
			for key, value := range data.Pairs {
				if specName(key) == "lambda" && value != nil && value.Type != object.ValueNil {
					isLambda = value.IsTruthy()
					break
				}
			}
		}
	}
	if len(args) >= 2 {
		key := args[len(args)-2]
		value := args[len(args)-1]
		if specName(key) == "lambda" && value != nil && value.Type != object.ValueNil {
			isLambda = value.IsTruthy()
		}
	}
	if fn == nil {
		result := []*object.EmeraldValue{}
		if method != nil {
			if method.DynamicMissing || method.Arity < 0 {
				result = append(result, procParameterPair("rest", ""))
			} else {
				for i := 0; i < method.Arity; i++ {
					result = append(result, procParameterPair("req", ""))
				}
			}
		}
		return &object.EmeraldValue{Type: object.ValueArray, Data: result, Class: R.Classes["Array"]}
	}
	result := make([]*object.EmeraldValue, 0, len(fn.Params)+len(fn.KeywordParams)+2)
	appendRest := func() {
		name := fn.RestParamName
		if fn.AnonymousRestParam {
			name = "*"
		} else if name == "__rgo_forward_args" {
			name = "*"
		}
		result = append(result, procParameterPair("rest", name))
	}
	for index := 0; index <= len(fn.Params); index++ {
		if fn.HasRestParam && index == fn.RestParamIndex {
			appendRest()
		}
		if index == len(fn.Params) {
			break
		}
		name := fn.Params[index]
		if fn.ImplicitItParameter && name == "it" {
			name = ""
		}
		if index < len(fn.ParamPatterns) && fn.ParamPatterns[index] != nil {
			name = ""
		}
		kind := "opt"
		if isLambda && (index >= len(fn.ParamDefaults) || fn.ParamDefaults[index] == nil) {
			kind = "req"
		}
		result = append(result, procParameterPair(kind, name))
	}
	for _, keyword := range fn.KeywordParams {
		kind := "keyreq"
		if keyword.HasDefault {
			kind = "key"
		}
		result = append(result, procParameterPair(kind, keyword.Name))
	}
	if fn.KeywordRestParam != "" {
		name := fn.KeywordRestParam
		if name == "__rgo_forward_kwargs" {
			name = "**"
		}
		result = append(result, procParameterPair("keyrest", name))
	} else if fn.KeywordRestOnly {
		result = append(result, procParameterPair("keyrest", "**"))
	} else if fn.RejectKeywords {
		result = append(result, procParameterPair("nokey", ""))
	}
	if fn.HasBlockParam {
		name := localNameAtIndex(fn.LocalNames, fn.BlockParamIndex)
		if fn.AnonymousBlockParam || name == "__rgo_forward_block" {
			name = "&"
		}
		result = append(result, procParameterPair("block", name))
	} else if fn.RejectBlock {
		result = append(result, procParameterPair("noblock", ""))
	}
	return &object.EmeraldValue{Type: object.ValueArray, Data: result, Class: R.Classes["Array"]}
}

func procParameterPair(kind, name string) *object.EmeraldValue {
	values := []*object.EmeraldValue{{Type: object.ValueSymbol, Data: kind, Class: R.Classes["Symbol"]}}
	if name != "" {
		values = append(values, &object.EmeraldValue{Type: object.ValueSymbol, Data: name, Class: R.Classes["Symbol"]})
	}
	return &object.EmeraldValue{Type: object.ValueArray, Data: values, Class: R.Classes["Array"]}
}

func localNameAtIndex(names map[string]int, index int) string {
	for name, candidate := range names {
		if candidate == index {
			return name
		}
	}
	return ""
}

func procSourceLocation(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver == nil {
		return R.NilVal
	}
	switch receiver.Type {
	case object.ValueProc:
		proc := receiver.Data.(*object.Proc)
		if proc != nil && proc.SourceMethod != nil {
			return methodSourceLocationValue(proc.SourceMethod)
		}
		if proc != nil && proc.Binding != nil {
			return sourceLocationArray(proc.Binding.Path, proc.Binding.Line)
		}
	case object.ValueClosure:
		closure := receiver.Data.(*object.Closure)
		if closure != nil && closure.Binding != nil {
			return sourceLocationArray(closure.Binding.Path, closure.Binding.Line)
		}
	}
	return R.NilVal
}

func procIsLambda(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver.Type == object.ValueProc {
		proc := receiver.Data.(*object.Proc)
		if proc.IsLambda {
			return R.TrueVal
		}
	}
	return R.FalseVal
}

func procToProc(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return receiver
}

func methodToProc(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver == nil || receiver.Type != object.ValueMethod {
		return R.NilVal
	}
	method := receiver.Data.(*object.Method)
	binding := &object.RBinding{Self: method.Receiver, Locals: map[string]*object.EmeraldValue{}, Constants: map[string]*object.EmeraldValue{}, InstanceVars: map[string]*object.EmeraldValue{}}
	if fn, ok := method.Fn.(*object.Function); ok && fn != nil {
		binding.Path = fn.SourcePath
		binding.Line = fn.DefinitionLine
	}
	return &object.EmeraldValue{
		Type: object.ValueProc,
		Data: &object.Proc{
			Native: func(callArgs ...*object.EmeraldValue) *object.EmeraldValue {
				return methodCall(receiver, callArgs...)
			},
			NativeArity:    method.Arity,
			HasNativeArity: true,
			IsLambda:       true,
			InstanceVars:   make(map[string]*object.EmeraldValue),
			SourceMethod:   method,
			Binding:        binding,
		},
		Class: R.Classes["Proc"],
	}
}

func methodComposeLeft(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return procComposeLeft(methodToProc(receiver), args...)
}

func methodComposeRight(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return procComposeRight(methodToProc(receiver), args...)
}

func methodCurry(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return procCurry(methodToProc(receiver), args...)
}

func procToS(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver.Type == object.ValueProc {
		proc := receiver.Data.(*object.Proc)
		prefix := fmt.Sprintf("#<Proc:0x%x", reflect.ValueOf(receiver).Pointer())
		if proc.SymbolProc {
			return stringWithEncoding(prefix+"(&:"+proc.SymbolName+")>", "BINARY")
		}
		path := ""
		line := int64(0)
		if proc.SourceMethod != nil {
			if fn, ok := proc.SourceMethod.Fn.(*object.Function); ok && fn != nil {
				path, line = fn.SourcePath, fn.DefinitionLine
			}
		} else if proc.Binding != nil {
			path, line = proc.Binding.Path, proc.Binding.Line
		}
		if path != "" && line > 0 {
			prefix += fmt.Sprintf(" %s:%d", path, line)
		}
		if proc.IsLambda {
			prefix += " (lambda)"
		}
		return stringWithEncoding(prefix+">", "BINARY")
	}
	return stringWithEncoding("#<Proc>", "BINARY")
}

func procInspect(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return procToS(receiver, args...)
}

func procCaseEqual(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return procCall(receiver, args...)
}

func procEqual(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver == nil || receiver.Type != object.ValueProc || len(args) < 1 || args[0] == nil || args[0].Type != object.ValueProc {
		return R.FalseVal
	}
	left := receiver.Data.(*object.Proc)
	right := args[0].Data.(*object.Proc)
	if left.Origin != nil {
		left = left.Origin
	}
	if right.Origin != nil {
		right = right.Origin
	}
	return boolValue(left == right)
}

func procComposeLeft(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) < 1 || !isCallableValue(args[0]) {
		return typeError("callable object is expected")
	}
	other := args[0]
	return composedProc(callableIsLambda(other), func(callArgs ...*object.EmeraldValue) *object.EmeraldValue {
		intermediate := callCallableValue(other, callArgs...)
		return callCallableValueDetached(receiver, intermediate)
	})
}

func procComposeRight(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) < 1 || !isCallableValue(args[0]) {
		return typeError("callable object is expected")
	}
	other := args[0]
	return composedProc(callableIsLambda(receiver), func(callArgs ...*object.EmeraldValue) *object.EmeraldValue {
		intermediate := callCallableValue(receiver, callArgs...)
		return callCallableValueDetached(other, intermediate)
	})
}

func composedProc(isLambda bool, fn func(args ...*object.EmeraldValue) *object.EmeraldValue) *object.EmeraldValue {
	return &object.EmeraldValue{
		Type: object.ValueProc,
		Data: &object.Proc{
			InstanceVars: make(map[string]*object.EmeraldValue),
			Native:       fn,
			IsLambda:     isLambda,
		},
		Class: R.Classes["Proc"],
	}
}

func isCallableValue(value *object.EmeraldValue) bool {
	if value == nil {
		return false
	}
	if value.Type == object.ValueProc || value.Type == object.ValueClosure || value.Type == object.ValueMethod {
		return true
	}
	return receiverHasCallableMethod(value, "call")
}

func callableIsLambda(value *object.EmeraldValue) bool {
	if value == nil {
		return false
	}
	if value.Type == object.ValueProc {
		return value.Data.(*object.Proc).IsLambda
	}
	return false
}

func callCallableValue(value *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if value == nil {
		return R.NilVal
	}
	switch value.Type {
	case object.ValueProc, object.ValueClosure:
		if CallBlockWithArgs != nil {
			return CallBlockWithArgs(value, args...)
		}
	case object.ValueMethod:
		return methodCall(value, args...)
	default:
		if CallMethod != nil {
			return CallMethod(value, "call", args...)
		}
	}
	return R.NilVal
}

func callCallableValueDetached(value *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if value != nil && (value.Type == object.ValueProc || value.Type == object.ValueClosure) && CallBlockDetached != nil {
		return CallBlockDetached(value, args...)
	}
	return callCallableValue(value, args...)
}

func methodCall(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver.Type != object.ValueMethod {
		return R.NilVal
	}
	method := receiver.Data.(*object.Method)
	if method.Fn == nil {
		return R.NilVal
	}
	callReceiver := receiver
	if method.Receiver != nil {
		callReceiver = method.Receiver
	}
	if fn, ok := method.Fn.(*object.Function); ok {
		if InvokeMethodObject != nil {
			return InvokeMethodObject(callReceiver, method, args...)
		}
		if CallMethod != nil {
			name := method.Name
			if name == "" {
				name = fn.Name
			}
			return CallMethod(callReceiver, name, args...)
		}
		return R.NilVal
	}
	if builtin, ok := method.Fn.(BuiltinMethod); ok {
		return builtin(callReceiver, args...)
	}
	if builtin, ok := method.Fn.(func(*object.EmeraldValue, ...*object.EmeraldValue) *object.EmeraldValue); ok {
		return builtin(callReceiver, args...)
	}
	return R.NilVal
}

func unboundMethodBind(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver.Type != object.ValueMethod || len(args) == 0 {
		return R.NilVal
	}
	method := receiver.Data.(*object.Method)
	if (method.Name == "append_features" || method.Name == "prepend_features" || method.Name == "extend_object") && args[0] != nil && args[0].Type == object.ValueClass {
		return typeError("bind argument must be an instance of Module")
	}
	if method.Owner != nil && method.Owner.Type == object.ValueClass {
		owner := method.Owner.Data.(*object.Class)
		if owner.IsSingleton {
			compatible := owner.SingletonOwner != nil && args[0] == owner.SingletonOwner
			if !compatible && owner.SingletonOwner != nil && owner.SingletonOwner.Type == object.ValueClass && args[0] != nil && args[0].Type == object.ValueClass {
				compatible = classInheritsFrom(args[0].Data.(*object.Class), owner.SingletonOwner.Data.(*object.Class))
			}
			if !compatible {
				return typeError("singleton method called for a different object")
			}
		} else if effective := receiverEffectiveClass(args[0]); args[0] == nil || !classInheritsFrom(effective, owner) && !(owner == R.Classes["Object"] && classInheritsFrom(effective, R.Classes["BasicObject"])) && !(owner.Name == "Kernel" && classInheritsFrom(effective, R.Classes["Object"])) {
			return typeError("bind argument must be an instance of " + classToS(owner))
		}
	}
	copy := *method
	copy.Receiver = args[0]
	return &object.EmeraldValue{Type: object.ValueMethod, Data: &copy, Class: R.Classes["Method"]}
}

func methodUnbind(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver == nil || receiver.Type != object.ValueMethod {
		return R.NilVal
	}
	method := receiver.Data.(*object.Method)
	copy := *method
	if copy.DispatchOwner == nil {
		copy.DispatchOwner = methodImplementationOwner(method)
	}
	copy.Receiver = nil
	return &object.EmeraldValue{Type: object.ValueMethod, Data: &copy, Class: R.Classes["UnboundMethod"]}
}

func methodImplementationOwner(method *object.Method) *object.EmeraldValue {
	if method == nil || method.Owner == nil || method.Owner.Type != object.ValueClass {
		return nil
	}
	root := method.Owner.Data.(*object.Class)
	name := method.OriginalName
	if name == "" {
		name = method.Name
	}
	foundCurrent := false
	for _, entry := range methodAncestorMethods(root, name) {
		if !foundCurrent {
			if sameModuleOrClassValue(method.Owner, entry.owner) {
				foundCurrent = true
			}
			continue
		}
		if methodImplementationEqual(entry.method.Fn, method.Fn) {
			return entry.owner
		}
	}
	return nil
}

func unboundMethodBindCall(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 0 {
		return NewArgumentError("wrong number of arguments")
	}
	bound := unboundMethodBind(receiver, args[0])
	if bound == nil || bound.Type == object.ValueException {
		return bound
	}
	return methodCall(bound, args[1:]...)
}

func methodArity(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver.Type != object.ValueMethod {
		return &object.EmeraldValue{Type: object.ValueInteger, Data: int64(-1), Class: R.Classes["Integer"]}
	}
	method := receiver.Data.(*object.Method)
	if method.DynamicMissing {
		return newInt(-1)
	}
	return &object.EmeraldValue{Type: object.ValueInteger, Data: int64(method.Arity), Class: R.Classes["Integer"]}
}

func methodSourceLocation(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver == nil || receiver.Type != object.ValueMethod {
		return R.NilVal
	}
	return methodSourceLocationValue(receiver.Data.(*object.Method))
}

func methodSourceLocationValue(method *object.Method) *object.EmeraldValue {
	if method == nil {
		return R.NilVal
	}
	fn, ok := method.Fn.(*object.Function)
	if !ok || fn == nil || fn.SourcePath == "" || fn.DefinitionLine <= 0 {
		return R.NilVal
	}
	return sourceLocationArray(fn.SourcePath, fn.DefinitionLine)
}

func methodOwner(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver.Type != object.ValueMethod {
		return R.NilVal
	}
	method := receiver.Data.(*object.Method)
	if method.Owner != nil {
		return method.Owner
	}
	if method.Receiver != nil && method.Receiver.Class != nil {
		return &object.EmeraldValue{Type: object.ValueClass, Data: method.Receiver.Class, Class: R.Classes["Class"]}
	}
	return R.NilVal
}

func methodReceiver(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver.Type != object.ValueMethod {
		return R.NilVal
	}
	method := receiver.Data.(*object.Method)
	if method.Receiver != nil {
		return method.Receiver
	}
	return R.NilVal
}

func methodName(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver.Type != object.ValueMethod {
		return R.NilVal
	}
	method := receiver.Data.(*object.Method)
	return &object.EmeraldValue{
		Type:  object.ValueSymbol,
		Data:  method.Name,
		Class: R.Classes["Symbol"],
	}
}

func methodOriginalName(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver == nil || receiver.Type != object.ValueMethod {
		return R.NilVal
	}
	method := receiver.Data.(*object.Method)
	name := method.OriginalName
	if name == "" {
		name = method.Name
	}
	return &object.EmeraldValue{Type: object.ValueSymbol, Data: name, Class: R.Classes["Symbol"]}
}

func methodMethodHash(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver == nil || receiver.Type != object.ValueMethod {
		return newInt(0)
	}
	method := receiver.Data.(*object.Method)
	hasher := fnv.New64a()
	implementation := reflect.ValueOf(method.Fn)
	if implementation.IsValid() {
		switch implementation.Kind() {
		case reflect.Func, reflect.Pointer:
			_, _ = hasher.Write([]byte(strconv.FormatUint(uint64(implementation.Pointer()), 16)))
		default:
			_, _ = hasher.Write([]byte(fmt.Sprintf("%T:%v", method.Fn, method.Fn)))
		}
	}
	_, _ = hasher.Write([]byte(fmt.Sprintf(":%p", method.Receiver)))
	return newInt(int64(hasher.Sum64()))
}

type methodAncestorEntry struct {
	method *object.Method
	owner  *object.EmeraldValue
}

func methodSuperMethod(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver == nil || receiver.Type != object.ValueMethod {
		return R.NilVal
	}
	current := receiver.Data.(*object.Method)
	root := (*object.Class)(nil)
	if current.Receiver != nil {
		root = existingSingletonClass(current.Receiver)
		if root == nil {
			root = receiverEffectiveClass(current.Receiver)
		}
	}
	if root == nil && current.Owner != nil && current.Owner.Type == object.ValueClass {
		root, _ = current.Owner.Data.(*object.Class)
	}
	if root == nil {
		return R.NilVal
	}
	searchName := current.OriginalName
	if searchName == "" {
		searchName = current.Name
	}
	entries := methodAncestorMethods(root, searchName)
	found := false
	ownerPresent := false
	for _, entry := range entries {
		if current.Owner != nil && sameModuleOrClassValue(current.Owner, entry.owner) {
			ownerPresent = true
			break
		}
	}
	if current.Owner != nil && !ownerPresent {
		found = true
	}
	for _, entry := range entries {
		if !found {
			ownerMatches := current.Owner == nil || sameModuleOrClassValue(current.Owner, entry.owner)
			if entry.method == current || methodImplementationEqual(entry.method.Fn, current.Fn) || ownerMatches && entry.method.Name == current.Name {
				found = true
			}
			continue
		}
		if entry.method == nil || entry.method.Visibility == "undefined" {
			return R.NilVal
		}
		if methodImplementationEqual(entry.method.Fn, current.Fn) {
			continue
		}
		copy := *entry.method
		copy.Name = current.Name
		copy.Owner = entry.owner
		copy.Receiver = current.Receiver
		class := R.Classes["UnboundMethod"]
		if receiver.Class == R.Classes["Method"] {
			class = R.Classes["Method"]
		}
		return &object.EmeraldValue{Type: object.ValueMethod, Data: &copy, Class: class}
	}
	return R.NilVal
}

func methodAncestorMethods(root *object.Class, name string) []methodAncestorEntry {
	entries := []methodAncestorEntry{}
	seenModules := make(map[*object.Module]bool)
	var appendModule func(*object.Module)
	appendModule = func(module *object.Module) {
		if module == nil || seenModules[module] {
			return
		}
		seenModules[module] = true
		for _, prepended := range module.PrependedModules {
			appendModule(prepended)
		}
		if method, exists := module.Methods[name]; exists {
			entries = append(entries, methodAncestorEntry{method: method, owner: &object.EmeraldValue{Type: object.ValueModule, Data: module, Class: R.Classes["Module"]}})
		}
		for index := len(module.IncludedModules) - 1; index >= 0; index-- {
			appendModule(module.IncludedModules[index])
		}
	}
	for class := root; class != nil; class = class.SuperClass {
		for _, prepended := range class.PrependedModules {
			appendModule(prepended)
		}
		if method, exists := class.Methods[name]; exists {
			entries = append(entries, methodAncestorEntry{method: method, owner: &object.EmeraldValue{Type: object.ValueClass, Data: class, Class: R.Classes["Class"]}})
		}
		for index := len(class.IncludedModules) - 1; index >= 0; index-- {
			appendModule(class.IncludedModules[index])
		}
	}
	return entries
}

func methodMethodEqual(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 0 || receiver == nil || args[0] == nil {
		return R.FalseVal
	}
	if receiver.Type == object.ValueMethod && args[0].Type == object.ValueMethod {
		left := receiver.Data.(*object.Method)
		right := args[0].Data.(*object.Method)
		if left.DynamicMissing || right.DynamicMissing {
			return boolValue(left.DynamicMissing && right.DynamicMissing && left.Name == right.Name && methodReceiverEqual(left.Receiver, right.Receiver))
		}
		if methodReceiverEqual(left.Receiver, right.Receiver) && methodImplementationEqual(left.Fn, right.Fn) {
			return R.TrueVal
		}
	}
	if receiver == args[0] {
		return R.TrueVal
	}
	return R.FalseVal
}

func methodReceiverEqual(left *object.EmeraldValue, right *object.EmeraldValue) bool {
	if left == nil || right == nil {
		return left == right
	}
	return left == right || left.Equals(right)
}

func methodImplementationEqual(left interface{}, right interface{}) bool {
	if left == nil || right == nil {
		return left == right
	}
	leftValue := reflect.ValueOf(left)
	rightValue := reflect.ValueOf(right)
	if leftValue.Type() != rightValue.Type() {
		return false
	}
	switch leftValue.Kind() {
	case reflect.Chan, reflect.Func, reflect.Map, reflect.Pointer, reflect.Slice, reflect.UnsafePointer:
		return leftValue.Pointer() == rightValue.Pointer()
	default:
		if leftValue.Type().Comparable() {
			return left == right
		}
		return false
	}
}

func methodMethodToS(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver.Type != object.ValueMethod {
		return &object.EmeraldValue{Type: object.ValueString, Data: "#<Method: nil>", Class: R.Classes["String"]}
	}
	method := receiver.Data.(*object.Method)
	ownerName := cleanMethodDisplayName(namedModuleOrClassValue(method.Owner))
	if receiver.Class == R.Classes["UnboundMethod"] {
		return rubyString("#<UnboundMethod: " + ownerName + "#" + method.Name + ">")
	}
	reference := ownerName
	separator := "#"
	if method.Receiver != nil {
		if method.Owner != nil && method.Owner.Type == object.ValueClass {
			ownerClass := method.Owner.Data.(*object.Class)
			if ownerClass.IsSingleton && ownerClass.SingletonOwner == method.Receiver {
				reference = method.Receiver.Inspect()
				separator = "."
			}
		}
		if separator == "#" {
			receiverName := ""
			switch method.Receiver.Type {
			case object.ValueClass:
				receiverName = "#<Class:" + cleanMethodDisplayName(namedModuleOrClassValue(method.Receiver)) + ">"
			case object.ValueModule:
				receiverName = "#<Class:" + cleanMethodDisplayName(namedModuleOrClassValue(method.Receiver)) + ">"
			default:
				if method.Receiver.Class != nil {
					receiverName = cleanMethodDisplayName(classToS(method.Receiver.Class))
				}
			}
			if receiverName != "" {
				reference = receiverName
				if ownerName != "" && ownerName != receiverName {
					reference += "(" + ownerName + ")"
				}
			}
		}
	}
	return rubyString("#<Method: " + reference + separator + method.Name + ">")
}

func cleanMethodDisplayName(name string) string {
	for strings.HasPrefix(name, "Object::") {
		name = strings.TrimPrefix(name, "Object::")
	}
	return name
}

func namedModuleOrClassValue(value *object.EmeraldValue) string {
	if value == nil {
		return ""
	}
	if name, ok := findRuntimeConstantName(value); ok {
		return name
	}
	switch value.Type {
	case object.ValueClass:
		return classToS(value.Data.(*object.Class))
	case object.ValueModule:
		return moduleToS(value.Data.(*object.Module))
	}
	return ""
}

func findRuntimeConstantName(target *object.EmeraldValue) (string, bool) {
	if target == nil || R == nil {
		return "", false
	}
	best := ""
	for rootName, class := range R.Classes {
		value := &object.EmeraldValue{Type: object.ValueClass, Data: class, Class: R.Classes["Class"]}
		if sameModuleOrClassValue(value, target) && len(rootName) > len(best) {
			best = rootName
		}
		if found, ok := findRuntimeConstantNameInMap(rootName, class.Constants, target, map[*object.EmeraldValue]bool{}); ok && len(found) > len(best) {
			best = found
		}
	}
	return best, best != ""
}

func findRuntimeConstantNameInMap(prefix string, constants map[string]*object.EmeraldValue, target *object.EmeraldValue, visited map[*object.EmeraldValue]bool) (string, bool) {
	best := ""
	for name, value := range constants {
		if value == nil || visited[value] {
			continue
		}
		visited[value] = true
		fullName := prefix + "::" + name
		if sameModuleOrClassValue(value, target) && len(fullName) > len(best) {
			best = fullName
		}
		switch value.Type {
		case object.ValueClass:
			if found, ok := findRuntimeConstantNameInMap(fullName, value.Data.(*object.Class).Constants, target, visited); ok && len(found) > len(best) {
				best = found
			}
		case object.ValueModule:
			if found, ok := findRuntimeConstantNameInMap(fullName, value.Data.(*object.Module).Constants, target, visited); ok && len(found) > len(best) {
				best = found
			}
		}
	}
	return best, best != ""
}

func sameModuleOrClassValue(left, right *object.EmeraldValue) bool {
	if left == nil || right == nil || left.Type != right.Type {
		return false
	}
	switch left.Type {
	case object.ValueClass, object.ValueModule:
		return left.Data == right.Data
	default:
		return false
	}
}

func methodMethodInspect(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	return methodMethodToS(receiver, args...)
}

func bindingValue(receiver *object.EmeraldValue) *object.RBinding {
	if receiver == nil || receiver.Type != object.ValueBinding {
		return nil
	}
	if binding, ok := receiver.Data.(*object.RBinding); ok {
		return binding
	}
	return nil
}

func bindingLocalVariableName(value *object.EmeraldValue) (string, *object.EmeraldValue) {
	name := ""
	switch {
	case value != nil && value.Type == object.ValueString:
		name = strings.TrimPrefix(value.Data.(string), ":")
	case value != nil && value.Type == object.ValueSymbol:
		name = value.Data.(string)
	case value == nil:
		return "", typeError("wrong argument type")
	default:
		if CallMethod == nil {
			return "", typeError("wrong argument type")
		}
		converted := CallMethod(value, "to_str")
		if converted == nil {
			return "", typeError("wrong argument type")
		}
		if converted.Type == object.ValueException {
			return "", converted
		}
		str, ok := converted.Data.(string)
		if !ok {
			return "", typeError("wrong argument type")
		}
		name = strings.TrimPrefix(str, ":")
	}
	if strings.HasPrefix(name, "$") {
		return "", newRuntimeException(R.Classes["NameError"], "wrong local variable name")
	}
	if !isValidLocalVariableName(name) {
		return "", newRuntimeException(R.Classes["NameError"], "wrong local variable name")
	}
	return name, nil
}

func isValidLocalVariableName(name string) bool {
	if len(name) == 0 {
		return false
	}
	first := name[0]
	if first != '_' && (first < 'a' || first > 'z') {
		return false
	}
	for i := 1; i < len(name); i++ {
		ch := name[i]
		if ch == '_' ||
			(ch >= 'a' && ch <= 'z') ||
			(ch >= 'A' && ch <= 'Z') ||
			(ch >= '0' && ch <= '9') {
			continue
		}
		return false
	}
	return true
}

func bindingLocalVariables(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	binding := bindingValue(receiver)
	if binding == nil {
		return &object.EmeraldValue{Type: object.ValueArray, Data: []*object.EmeraldValue{}, Class: R.Classes["Array"]}
	}
	allNames := make([]string, 0, len(binding.LocalNames))
	seen := map[string]struct{}{}
	filter := map[string]struct{}(nil)
	for current := binding; current != nil; current = current.Parent {
		inherited := map[string]struct{}(nil)
		if current.ShareAllLocals && current.Parent != nil {
			inherited = make(map[string]struct{})
			for parent := current.Parent; parent != nil; parent = parent.Parent {
				for _, name := range parent.LocalNames {
					inherited[name] = struct{}{}
				}
				for name := range parent.Locals {
					inherited[name] = struct{}{}
				}
			}
		}
		for _, name := range current.LocalNames {
			if strings.HasPrefix(name, "__rgo_") {
				continue
			}
			if _, inheritedName := inherited[name]; inheritedName {
				continue
			}
			if filter != nil {
				if _, ok := filter[name]; !ok {
					continue
				}
			}
			if _, ok := seen[name]; ok {
				continue
			}
			seen[name] = struct{}{}
			allNames = append(allNames, name)
		}
		extras := make([]string, 0, len(current.Locals))
		for name := range current.Locals {
			if strings.HasPrefix(name, "__rgo_") {
				continue
			}
			if _, inheritedName := inherited[name]; inheritedName {
				continue
			}
			if filter != nil {
				if _, ok := filter[name]; !ok {
					continue
				}
			}
			if _, ok := seen[name]; ok {
				continue
			}
			extras = append(extras, name)
		}
		sort.Strings(extras)
		for _, name := range extras {
			seen[name] = struct{}{}
			allNames = append(allNames, name)
		}
		if current.Parent == nil {
			break
		}
		if current.ShareAllLocals {
			filter = nil
			continue
		}
		if len(current.SharedLocals) == 0 {
			break
		}
		filter = current.SharedLocals
	}
	result := make([]*object.EmeraldValue, 0, len(allNames))
	for _, name := range allNames {
		result = append(result, &object.EmeraldValue{
			Type:  object.ValueSymbol,
			Data:  name,
			Class: R.Classes["Symbol"],
		})
	}
	return &object.EmeraldValue{Type: object.ValueArray, Data: result, Class: R.Classes["Array"]}
}

func bindingLocalVariableDefined(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if binding := bindingValue(receiver); binding != nil {
		if len(args) != 1 {
			return NewArgumentError("wrong number of arguments")
		}
		name, err := bindingLocalVariableName(args[0])
		if err != nil {
			return err
		}
		for current := binding; current != nil; current = current.Parent {
			if _, ok := current.Locals[name]; ok {
				return R.TrueVal
			}
			if bindingHasLocalName(current.LocalNames, name) {
				return R.TrueVal
			}
			if current.Parent == nil {
				break
			}
			if current.ShareAllLocals {
				continue
			}
			if len(current.SharedLocals) == 0 {
				break
			}
			if _, ok := current.SharedLocals[name]; !ok {
				break
			}
		}
	}
	return R.FalseVal
}

func bindingLocalVariableGet(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	binding := bindingValue(receiver)
	if len(args) != 1 {
		return NewArgumentError("wrong number of arguments")
	}
	if binding == nil {
		return R.NilVal
	}
	name, err := bindingLocalVariableName(args[0])
	if err != nil {
		return err
	}
	for current := binding; current != nil; current = current.Parent {
		if value, ok := current.Locals[name]; ok {
			return value
		}
		if bindingHasLocalName(current.LocalNames, name) {
			return R.NilVal
		}
		if current.Parent == nil {
			break
		}
		if current.ShareAllLocals {
			continue
		}
		if len(current.SharedLocals) == 0 {
			break
		}
		if _, ok := current.SharedLocals[name]; !ok {
			break
		}
	}
	return newRuntimeException(R.Classes["NameError"], "undefined local variable `"+name+"'")
}

func bindingLocalVariableSet(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	binding := bindingValue(receiver)
	if len(args) != 2 {
		return NewArgumentError("wrong number of arguments")
	}
	if binding == nil {
		return R.NilVal
	}
	name, err := bindingLocalVariableName(args[0])
	if err != nil {
		return err
	}
	if binding.Locals == nil {
		binding.Locals = map[string]*object.EmeraldValue{}
	}
	if !bindingHasLocalName(binding.LocalNames, name) {
		binding.LocalNames = append([]string{name}, binding.LocalNames...)
	}
	binding.Locals[name] = args[1]
	if SetCapturedBindingLocal != nil {
		SetCapturedBindingLocal(binding, name, args[1])
	}
	propagateSharedBindingLocals(binding)
	return args[1]
}

func bindingReceiver(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	binding := bindingValue(receiver)
	if binding == nil || binding.Self == nil {
		return R.NilVal
	}
	return binding.Self
}

func bindingSourceLocation(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	binding := bindingValue(receiver)
	if binding == nil {
		return R.NilVal
	}
	return sourceLocationArray(binding.Path, binding.Line)
}

// binding helpers are implemented below

func sourceLocationArray(path string, line int64) *object.EmeraldValue {
	return &object.EmeraldValue{
		Type:  object.ValueArray,
		Data:  []*object.EmeraldValue{rubyString(path), &object.EmeraldValue{Type: object.ValueInteger, Data: line, Class: R.Classes["Integer"]}},
		Class: R.Classes["Array"],
	}
}

func bindingDup(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	binding := bindingValue(receiver)
	if binding == nil {
		return R.NilVal
	}
	return &object.EmeraldValue{Type: object.ValueBinding, Data: cloneBindingData(binding), Class: R.Classes["Binding"]}
}

func bindingClone(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	clone := bindingDup(receiver, args...)
	if clone != nil && receiver != nil {
		clone.Frozen = receiver.Frozen
	}
	return clone
}

func bindingHasLocalName(localNames []string, name string) bool {
	for _, localName := range localNames {
		if localName == name {
			return true
		}
	}
	return false
}

func cloneBindingData(binding *object.RBinding) *object.RBinding {
	if binding == nil {
		return &object.RBinding{
			Self:         R.Main,
			Locals:       map[string]*object.EmeraldValue{},
			LocalNames:   nil,
			Constants:    map[string]*object.EmeraldValue{},
			Method:       "",
			InstanceVars: map[string]*object.EmeraldValue{},
			Path:         currentSourcePath(),
			Line:         1,
		}
	}
	clone := &object.RBinding{
		Self:                    binding.Self,
		Block:                   binding.Block,
		AllowAnonymousBlockPass: binding.AllowAnonymousBlockPass,
		EvalReturnTargetID:      binding.EvalReturnTargetID,
		Locals:                  make(map[string]*object.EmeraldValue, len(binding.Locals)),
		LocalNames:              append([]string{}, binding.LocalNames...),
		Constants:               binding.Constants,
		Method:                  binding.Method,
		BacktraceLabel:          binding.BacktraceLabel,
		InstanceVars:            map[string]*object.EmeraldValue{},
		ClassStack:              append([]*object.EmeraldValue(nil), binding.ClassStack...),
		ClassVarScope:           binding.ClassVarScope,
		Refinements:             append([]*object.EmeraldValue(nil), binding.Refinements...),
		Path:                    binding.Path,
		Line:                    binding.Line,
		ShareAllLocals:          false,
		Parent:                  binding,
		SharedLocals:            bindingSharedLocals(binding),
	}
	for name, value := range binding.Locals {
		clone.Locals[name] = value
	}
	for name, value := range binding.InstanceVars {
		clone.InstanceVars[name] = value
	}
	if clone.Locals == nil {
		clone.Locals = map[string]*object.EmeraldValue{}
	}
	if clone.Constants == nil {
		clone.Constants = map[string]*object.EmeraldValue{}
	}
	return clone
}

func cloneBindingDataForEval(binding *object.RBinding) *object.RBinding {
	if binding == nil {
		return &object.RBinding{
			Self:           R.Main,
			Locals:         map[string]*object.EmeraldValue{},
			LocalNames:     nil,
			Constants:      map[string]*object.EmeraldValue{},
			Method:         "",
			InstanceVars:   map[string]*object.EmeraldValue{},
			ClassStack:     nil,
			ClassVarScope:  nil,
			Path:           currentSourcePath(),
			Line:           1,
			ShareAllLocals: true,
		}
	}
	clone := cloneBindingData(binding)
	clone.ShareAllLocals = true
	clone.SharedLocals = nil
	return clone
}

func bindingSharedLocals(binding *object.RBinding) map[string]struct{} {
	if binding == nil || len(binding.LocalNames) == 0 {
		return nil
	}
	names := make(map[string]struct{}, len(binding.LocalNames))
	for _, name := range binding.LocalNames {
		names[name] = struct{}{}
	}
	if len(names) == 0 {
		return nil
	}
	return names
}

func mergeBindingData(dst, src *object.RBinding) {
	if dst == nil || src == nil {
		return
	}
	if dst.Locals == nil {
		dst.Locals = map[string]*object.EmeraldValue{}
	}
	if dst.LocalNames == nil {
		dst.LocalNames = []string{}
	}
	for name, value := range src.Locals {
		dst.Locals[name] = value
		if SetCapturedBindingLocal != nil {
			SetCapturedBindingLocal(dst, name, value)
		}
	}
	existing := make(map[string]struct{}, len(dst.LocalNames))
	for _, name := range dst.LocalNames {
		existing[name] = struct{}{}
	}
	for _, name := range src.LocalNames {
		if _, ok := existing[name]; ok {
			continue
		}
		dst.LocalNames = append(dst.LocalNames, name)
		existing[name] = struct{}{}
	}
	propagateSharedBindingLocals(dst)
	if dst.InstanceVars == nil {
		dst.InstanceVars = map[string]*object.EmeraldValue{}
	}
	for name, value := range src.InstanceVars {
		dst.InstanceVars[name] = value
	}
}

func propagateSharedBindingLocals(binding *object.RBinding) {
	if binding == nil {
		return
	}
	for current := binding; current != nil; current = current.Parent {
		parent := current.Parent
		if parent == nil {
			continue
		}
		if parent.Locals == nil {
			parent.Locals = map[string]*object.EmeraldValue{}
		}
		existing := map[string]struct{}{}
		for _, name := range parent.LocalNames {
			existing[name] = struct{}{}
		}
		if current.ShareAllLocals {
			for name, value := range current.Locals {
				parent.Locals[name] = value
				if SetCapturedBindingLocal != nil {
					SetCapturedBindingLocal(parent, name, value)
				}
				if _, ok := existing[name]; !ok {
					parent.LocalNames = append(parent.LocalNames, name)
					existing[name] = struct{}{}
				}
			}
			continue
		}
		for name := range current.SharedLocals {
			if value, ok := current.Locals[name]; ok {
				parent.Locals[name] = value
				if SetCapturedBindingLocal != nil {
					SetCapturedBindingLocal(parent, name, value)
				}
				if _, ok := existing[name]; !ok {
					parent.LocalNames = append(parent.LocalNames, name)
					existing[name] = struct{}{}
				}
			}
		}
	}
}

func syncSharedBindingLocalsFromParents(binding *object.RBinding) {
	if binding == nil || binding.Parent == nil {
		return
	}
	syncSharedBindingLocalsFromParents(binding.Parent)
	parent := binding.Parent
	if parent == nil {
		return
	}
	if binding.Locals == nil {
		binding.Locals = map[string]*object.EmeraldValue{}
	}
	existing := map[string]struct{}{}
	for _, name := range binding.LocalNames {
		existing[name] = struct{}{}
	}
	for _, name := range parent.LocalNames {
		if !binding.ShareAllLocals {
			if _, shared := binding.SharedLocals[name]; !shared {
				continue
			}
		}
		value, ok := parent.Locals[name]
		if !ok {
			continue
		}
		binding.Locals[name] = value
		if _, ok := existing[name]; !ok {
			binding.LocalNames = append(binding.LocalNames, name)
			existing[name] = struct{}{}
		}
	}
}

func bindingInstanceVariableSet(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	binding := bindingValue(receiver)
	if binding == nil || len(args) < 2 {
		return R.NilVal
	}
	name := specName(args[0])
	if name == "" {
		return typeError("wrong argument type")
	}
	if !strings.HasPrefix(name, "@") {
		name = "@" + name
	}
	if binding.InstanceVars == nil {
		binding.InstanceVars = map[string]*object.EmeraldValue{}
	}
	binding.InstanceVars[name] = args[1]
	return args[1]
}

func bindingInstanceVariableGet(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	binding := bindingValue(receiver)
	if binding == nil || len(args) < 1 {
		return R.NilVal
	}
	name := specName(args[0])
	if name == "" {
		return typeError("wrong argument type")
	}
	if !strings.HasPrefix(name, "@") {
		name = "@" + name
	}
	if binding.InstanceVars == nil {
		return R.NilVal
	}
	if value, exists := binding.InstanceVars[name]; exists {
		return value
	}
	return R.NilVal
}

func bindingInstanceVariables(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	binding := bindingValue(receiver)
	if binding == nil {
		return &object.EmeraldValue{Type: object.ValueArray, Data: []*object.EmeraldValue{}, Class: R.Classes["Array"]}
	}
	names := make([]string, 0, len(binding.InstanceVars))
	for name := range binding.InstanceVars {
		names = append(names, name)
	}
	sort.Strings(names)
	result := make([]*object.EmeraldValue, 0, len(names))
	for _, name := range names {
		result = append(result, &object.EmeraldValue{Type: object.ValueSymbol, Data: name, Class: R.Classes["Symbol"]})
	}
	return &object.EmeraldValue{Type: object.ValueArray, Data: result, Class: R.Classes["Array"]}
}

func bindingEval(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) < 1 {
		return NewArgumentError("wrong number of arguments (given 0, expected 1..3)")
	}
	if len(args) > 3 {
		return NewArgumentError(fmt.Sprintf("wrong number of arguments (given %d, expected 1..3)", len(args)))
	}
	str, converted, viaToStr, coerceErr := evalCoerceToString(args[0])
	if coerceErr != nil {
		return coerceErr
	}
	if !converted {
		return conversionTypeErrorToStringForMode(args[0], viaToStr)
	}
	file := (*object.EmeraldValue)(nil)
	line := (*object.EmeraldValue)(nil)
	if len(args) > 1 {
		file = args[1]
	}
	if len(args) > 2 {
		line = args[2]
	}
	sourceValue := (*object.EmeraldValue)(nil)
	if len(args) > 0 && args[0] != nil && args[0].Type == object.ValueString {
		sourceValue = args[0]
	}
	return evalSourceWithBindingArgs(str, sourceValue, receiver, file, line)
}

func bindingIRB(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	binding, _ := receiver.Data.(*object.RBinding)
	if binding == nil || EvalSourceWithBinding == nil {
		return R.NilVal
	}
	scanner := bufio.NewScanner(os.Stdin)
	for scanner.Scan() {
		line := scanner.Text()
		fmt.Fprintln(os.Stdout, line)
		if strings.TrimSpace(line) == "exit" {
			break
		}
		result := EvalSourceWithBinding(line, binding)
		if result != nil {
			fmt.Fprintln(os.Stdout, result.Inspect())
		}
	}
	return R.NilVal
}

func evalSourceEncoding(source string, sourceValue *object.EmeraldValue) string {
	if commentEncoding := evalSourceMagicEncoding(source); commentEncoding != "" {
		return commentEncoding
	}

	if sourceValue != nil && sourceValue.Type == object.ValueString {
		candidate := stringEncodingName(sourceValue)
		if candidate != "" {
			normalizedCandidate := normalizeEncodingNameForIO(candidate)
			if normalizedCandidate != "" {
				return canonicalEncodingName(normalizedCandidate)
			}
		}
	}

	return "US-ASCII"
}

func SourceEncoding(source string) string {
	if encoding := evalSourceMagicEncoding(source); encoding != "" {
		return encoding
	}
	return "UTF-8"
}

func evalSourceMagicEncoding(source string) string {
	lines := strings.Split(source, "\n")
	if len(lines) == 0 {
		return ""
	}
	line := strings.TrimSpace(lines[0])
	if strings.HasPrefix(line, "#!") {
		if len(lines) < 2 {
			return ""
		}
		line = strings.TrimSpace(lines[1])
	}
	if !strings.HasPrefix(line, "#") {
		return ""
	}
	encodingMatch := evalSourceEncodingCommentPattern.FindStringSubmatchIndex(line)
	if len(encodingMatch) < 4 {
		return ""
	}
	if frozenMatch := evalSourceFrozenStringLiteralPattern.FindStringIndex(line); len(frozenMatch) == 2 && frozenMatch[0] < encodingMatch[2] {
		return ""
	}
	if match := evalSourceEncodingCommentPattern.FindStringSubmatch(line); len(match) > 1 {
		return canonicalEncodingName(normalizeEncodingNameForIO(match[1]))
	}
	return ""
}

func evalSourceSingleExpression(source string) (string, bool) {
	lines := strings.Split(source, "\n")
	var expression string
	found := false
	for _, line := range lines {
		line = strings.TrimSpace(line)
		if line == "" {
			continue
		}
		if strings.HasPrefix(line, "#") {
			continue
		}
		if idx := strings.Index(line, "#"); idx >= 0 {
			line = strings.TrimSpace(line[:idx])
		}
		if line == "" {
			continue
		}
		if found {
			return "", false
		}
		expression = line
		found = true
	}
	if !found {
		return "", false
	}
	return expression, true
}

func evalSourceWithBindingArgs(source string, sourceValue *object.EmeraldValue, bindingValue *object.EmeraldValue, fileArg *object.EmeraldValue, lineArg *object.EmeraldValue) *object.EmeraldValue {
	binding := (*object.RBinding)(nil)
	if bindingValue != nil && bindingValue.Type == object.ValueBinding {
		if value, ok := bindingValue.Data.(*object.RBinding); ok {
			binding = value
		}
	}
	originalBinding := binding
	if binding == nil && CurrentFrameBinding != nil {
		binding = CurrentFrameBinding()
	}
	frames := currentBacktraceFramesOrEmpty()
	callerPath := currentSourcePath()
	callerLine := int64(1)
	if len(frames) > 0 {
		callerPath = frames[0].Path
		callerLine = frames[0].Line
	}
	if callerLine <= 0 {
		callerLine = 1
	}
	evalFile := ""
	fileProvided := false
	if fileArg != nil {
		convertedFile, ok, viaToStr, coerceErr := evalCoerceToString(fileArg)
		if coerceErr != nil {
			return coerceErr
		}
		if !ok {
			return conversionTypeErrorToStringForMode(fileArg, viaToStr)
		}
		evalFile = convertedFile
		fileProvided = true
	}
	if !fileProvided {
		evalFile = fmt.Sprintf("(eval at %s:%d)", callerPath, callerLine)
	}
	evalLine := int64(1)
	if lineArg != nil {
		n, ok := valueToInteger(lineArg)
		if !ok {
			return conversionTypeErrorToInteger(lineArg)
		}
		evalLine = n
	}
	if lineArg == nil && evalLine <= 0 {
		evalLine = 1
	}

	syncSharedBindingLocalsFromParents(binding)
	evalBinding := cloneBindingDataForEval(binding)
	execBinding := evalBinding
	if evalBinding != nil {
		execBinding = cloneBindingWithLocation(evalBinding, evalFile, evalLine)
	}
	evalBinding.Path = evalFile
	evalBinding.Line = evalLine

	trimmed := strings.TrimSpace(source)
	if trimmed == "" {
		return R.NilVal
	}
	if trimmed == "binding" {
		return &object.EmeraldValue{Type: object.ValueBinding, Data: evalBinding, Class: R.Classes["Binding"]}
	}
	if expr, ok := evalSourceSingleExpression(source); ok && expr == "__ENCODING__" {
		return newEncodingValue(evalSourceEncoding(source, sourceValue))
	}
	if trimmed == "__FILE__" {
		return rubyString(evalFile)
	}
	if trimmed == "__dir__" {
		if strings.HasPrefix(evalFile, "(eval at ") {
			return R.NilVal
		}
		return rubyString(evalDirFromFile(evalFile))
	}
	if trimmed == "__method__" || trimmed == "__callee__" {
		if evalBinding.Method == "" {
			return R.NilVal
		}
		return &object.EmeraldValue{Type: object.ValueSymbol, Data: evalBinding.Method, Class: R.Classes["Symbol"]}
	}
	if trimmed == "[__FILE__, __LINE__]" {
		return sourceLocationArray(evalFile, evalLine)
	}
	if lineOffset, ok := evalLineMarkerOffset(source); ok {
		return &object.EmeraldValue{
			Type:  object.ValueInteger,
			Data:  evalLine + lineOffset,
			Class: R.Classes["Integer"],
		}
	}
	if EvalSourceWithBinding == nil {
		return R.NilVal
	}
	previousEvalSourceEncoding := CurrentEvalSourceEncoding
	previousEvalSource := CurrentEvalSource
	CurrentEvalSourceEncoding = evalSourceEncoding(source, sourceValue)
	CurrentEvalSource = true
	result := EvalSourceWithBinding(source, execBinding)
	CurrentEvalSourceEncoding = previousEvalSourceEncoding
	CurrentEvalSource = previousEvalSource
	if execBinding != nil && execBinding != evalBinding {
		mergeBindingData(evalBinding, execBinding)
	}
	if originalBinding != nil && originalBinding != evalBinding {
		mergeBindingData(originalBinding, evalBinding)
	}
	return result
}

func cloneBindingWithLocation(binding *object.RBinding, path string, line int64) *object.RBinding {
	if binding == nil {
		return &object.RBinding{
			Self:         R.Main,
			Locals:       map[string]*object.EmeraldValue{},
			LocalNames:   nil,
			Constants:    map[string]*object.EmeraldValue{},
			Method:       "",
			InstanceVars: map[string]*object.EmeraldValue{},
			ClassStack:   nil,
			Path:         path,
			Line:         line,
		}
	}
	cloned := &object.RBinding{
		Self:                    binding.Self,
		Block:                   binding.Block,
		AllowAnonymousBlockPass: binding.AllowAnonymousBlockPass,
		EvalReturnTargetID:      binding.EvalReturnTargetID,
		Locals:                  make(map[string]*object.EmeraldValue, len(binding.Locals)),
		LocalNames:              append([]string(nil), binding.LocalNames...),
		Constants:               binding.Constants,
		Method:                  binding.Method,
		BacktraceLabel:          binding.BacktraceLabel,
		InstanceVars:            map[string]*object.EmeraldValue{},
		ClassStack:              append([]*object.EmeraldValue(nil), binding.ClassStack...),
		ClassVarScope:           binding.ClassVarScope,
		Refinements:             append([]*object.EmeraldValue(nil), binding.Refinements...),
		Path:                    path,
		Line:                    line,
		ShareAllLocals:          binding.ShareAllLocals,
		Parent:                  binding,
		SharedLocals:            map[string]struct{}{},
	}
	for name := range binding.SharedLocals {
		cloned.SharedLocals[name] = struct{}{}
	}
	for name, value := range binding.InstanceVars {
		cloned.InstanceVars[name] = value
	}
	for name, value := range binding.Locals {
		cloned.Locals[name] = value
	}
	return cloned
}

func evalDirFromFile(path string) string {
	if path == "" {
		return ""
	}
	if idx := strings.LastIndex(path, "/"); idx >= 0 {
		if idx == 0 {
			return "/"
		}
		return path[:idx]
	}
	return "."
}

func conversionTypeErrorToString(value *object.EmeraldValue) *object.EmeraldValue {
	if value == nil || value == R.NilVal {
		return typeError("no implicit conversion of nil into String")
	}
	if value.Class != nil && value.Class.Name != "" {
		return typeError("no implicit conversion of " + value.Class.Name + " into String")
	}
	return typeError("no implicit conversion into String")
}

func conversionTypeErrorToInteger(value *object.EmeraldValue) *object.EmeraldValue {
	if value == nil || value == R.NilVal {
		return typeError("no implicit conversion of nil into Integer")
	}
	if value.Class != nil && value.Class.Name != "" {
		return typeError("no implicit conversion of " + value.Class.Name + " into Integer")
	}
	return typeError("no implicit conversion into Integer")
}

func evalLineMarkerOffset(source string) (int64, bool) {
	lines := strings.Split(source, "\n")
	found := -1
	for i, line := range lines {
		trimmed := strings.TrimSpace(line)
		if trimmed == "" {
			continue
		}
		if strings.HasPrefix(trimmed, "#") {
			continue
		}
		if commentIdx := strings.Index(trimmed, "#"); commentIdx >= 0 {
			trimmed = strings.TrimSpace(trimmed[:commentIdx])
		}
		if trimmed != "__LINE__" {
			return 0, false
		}
		if found >= 0 {
			return 0, false
		}
		found = i
	}
	if found < 0 {
		return 0, false
	}
	return int64(found), true
}

func evalCoerceToString(value *object.EmeraldValue) (string, bool, bool, *object.EmeraldValue) {
	if value == nil {
		return "", false, false, nil
	}
	if value.Type == object.ValueString {
		return stringRawValue(value), true, false, nil
	}
	if CallMethod != nil && receiverHasCallableMethod(value, "to_str") {
		coerced := CallMethod(value, "to_str")
		if coerced != nil && coerced.Type == object.ValueException {
			return "", false, true, coerced
		}
		if coerced != nil && coerced.Type == object.ValueString {
			s, ok := coerced.Data.(string)
			return s, ok, true, nil
		}
		return "", false, true, nil
	}
	if CallMethod != nil && receiverHasCallableMethod(value, "respond_to?") && receiverHasCallableMethod(value, "method_missing") {
		responds := CallMethod(value, "respond_to?", rubySymbol("to_str"), R.TrueVal)
		if responds != nil && responds.IsTruthy() {
			coerced := CallMethod(value, "method_missing", rubySymbol("to_str"))
			if coerced != nil && coerced.Type == object.ValueException {
				return "", false, true, coerced
			}
			if coerced != nil && coerced.Type == object.ValueString {
				s, ok := coerced.Data.(string)
				return s, ok, true, nil
			}
			return "", false, true, nil
		}
	}
	return "", false, false, nil
}

func conversionTypeErrorToStringForMode(value *object.EmeraldValue, convertedByToStr bool) *object.EmeraldValue {
	if !convertedByToStr {
		return conversionTypeErrorToString(value)
	}
	if value == nil || value == R.NilVal {
		return typeError("can't convert nil into String")
	}
	if value.Class != nil && value.Class.Name != "" {
		return typeError("can't convert " + value.Class.Name + " into String")
	}
	return typeError("can't convert into String")
}

func moduleInclude(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver.Type != object.ValueModule && receiver.Type != object.ValueClass {
		return R.NilVal
	}
	if module, ok := receiver.Data.(*object.Module); ok && module.IsRefinement {
		return typeError("Refinement#include has been removed")
	}
	if len(args) == 0 {
		return NewArgumentError("wrong number of arguments")
	}
	for i := len(args) - 1; i >= 0; i-- {
		result := appendFeaturesForInclude(receiver, args[i])
		if result != nil && result.Type == object.ValueException {
			return result
		}
		if hook := callIncludedHook(args[i], receiver); hook != nil && hook.Type == object.ValueException {
			return hook
		}
	}
	return receiver
}

func moduleAppendFeatures(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver == nil || receiver.Type != object.ValueModule || len(args) == 0 {
		return R.NilVal
	}
	target := args[0]
	if target == receiver {
		return NewArgumentError("cyclic include detected")
	}
	if target != nil && target.Frozen {
		return frozenError("can't modify frozen class/module")
	}
	module := receiver.Data.(*object.Module)
	switch target.Type {
	case object.ValueClass:
		if classIncludesModule(target.Data.(*object.Class), module) {
			return NewArgumentError("cyclic include detected")
		}
		target.Data.(*object.Class).Include(module)
	case object.ValueModule:
		targetModule := target.Data.(*object.Module)
		if targetModule == module || moduleIncludesModule(module, targetModule) {
			return NewArgumentError("cyclic include detected")
		}
		targetModule.Include(module)
	default:
		return typeError("wrong argument type")
	}
	return receiver
}

func appendFeaturesForInclude(receiver *object.EmeraldValue, mixin *object.EmeraldValue) *object.EmeraldValue {
	module := moduleFromMixin(mixin)
	if module == nil {
		return typeError("wrong argument type")
	}
	if module.IsRefinement {
		return typeError("Cannot include refinement")
	}
	if CallMethod != nil && mixin.Type == object.ValueModule {
		return CallMethod(mixin, "send", &object.EmeraldValue{Type: object.ValueSymbol, Data: "append_features", Class: R.Classes["Symbol"]}, receiver)
	}
	switch receiver.Type {
	case object.ValueClass:
		receiver.Data.(*object.Class).Include(module)
	case object.ValueModule:
		receiver.Data.(*object.Module).Include(module)
	}
	return mixin
}

func moduleFromMixin(value *object.EmeraldValue) *object.Module {
	if value == nil {
		return nil
	}
	if value.Type == object.ValueModule {
		return value.Data.(*object.Module)
	}
	if value.Type == object.ValueClass {
		if class, ok := value.Data.(*object.Class); ok && class != nil && class.Name == "Kernel" {
			return kernelModuleView
		}
	}
	return nil
}

func classIncludesModule(class *object.Class, module *object.Module) bool {
	if class == nil || module == nil {
		return false
	}
	if module == kernelModuleView && classInheritsFrom(class, R.Classes["Object"]) {
		return true
	}
	for cls := class; cls != nil; cls = cls.SuperClass {
		for _, included := range cls.IncludedModules {
			if included == module || moduleIncludesModule(included, module) {
				return true
			}
		}
	}
	return false
}

func moduleIncludesModule(module *object.Module, target *object.Module) bool {
	if module == nil || target == nil {
		return false
	}
	for _, included := range module.IncludedModules {
		if included == target || moduleIncludesModule(included, target) {
			return true
		}
	}
	return false
}

func moduleIncludePredicate(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) != 1 {
		return NewArgumentError("wrong number of arguments")
	}
	target := args[0]
	targetModule := moduleFromMixin(target)
	if targetModule == nil {
		return typeError("wrong argument type")
	}
	switch receiver.Type {
	case object.ValueClass:
		if classIncludesModule(receiver.Data.(*object.Class), targetModule) {
			return R.TrueVal
		}
	case object.ValueModule:
		if moduleIncludesModule(receiver.Data.(*object.Module), targetModule) {
			return R.TrueVal
		}
	}
	return R.FalseVal
}

func moduleAncestors(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	values := []*object.EmeraldValue{}
	seenClasses := map[*object.Class]bool{}
	addClass := func(class *object.Class) {
		if class == nil || seenClasses[class] {
			return
		}
		seenClasses[class] = true
		values = append(values, &object.EmeraldValue{Type: object.ValueClass, Data: class, Class: R.Classes["Class"]})
	}
	switch receiver.Type {
	case object.ValueModule:
		mod := receiver.Data.(*object.Module)
		seenModules := map[*object.Module]bool{}
		var addModuleChain func(*object.Module)
		addModuleChain = func(current *object.Module) {
			if current == nil || seenModules[current] {
				return
			}
			seenModules[current] = true
			for _, prepended := range current.PrependedModules {
				addModuleChain(prepended)
			}
			values = append(values, &object.EmeraldValue{Type: object.ValueModule, Data: current, Class: R.Classes["Module"]})
			for i := len(current.IncludedModules) - 1; i >= 0; i-- {
				addModuleChain(current.IncludedModules[i])
			}
		}
		addModuleChain(mod)
	case object.ValueClass:
		start := receiver.Data.(*object.Class)
		moduleSingleton := start.IsSingleton && start.SingletonOwner != nil && start.SingletonOwner.Type == object.ValueModule
		for class := start; class != nil; class = class.SuperClass {
			seenModules := map[*object.Module]bool{}
			var addModuleChain func(*object.Module)
			addModuleChain = func(current *object.Module) {
				if current == nil || seenModules[current] {
					return
				}
				seenModules[current] = true
				for _, prepended := range current.PrependedModules {
					addModuleChain(prepended)
				}
				values = append(values, &object.EmeraldValue{Type: object.ValueModule, Data: current, Class: R.Classes["Module"]})
				for i := len(current.IncludedModules) - 1; i >= 0; i-- {
					addModuleChain(current.IncludedModules[i])
				}
			}
			for _, mod := range class.PrependedModules {
				seenModules = map[*object.Module]bool{}
				addModuleChain(mod)
			}
			if !moduleSingleton || class != R.Classes["Class"] {
				addClass(class)
			}
			if class.IsSingleton && class.SingletonOwner != nil {
				switch class.SingletonOwner.Type {
				case object.ValueModule:
					addModuleChain(class.SingletonOwner.Data.(*object.Module))
				case object.ValueClass:
					addClass(class.SingletonOwner.Data.(*object.Class))
				}
			}
			for i := len(class.IncludedModules) - 1; i >= 0; i-- {
				seenModules = map[*object.Module]bool{}
				addModuleChain(class.IncludedModules[i])
			}
			if class == R.Classes["Object"] {
				addClass(R.Classes["Kernel"])
			}
		}
	}
	return &object.EmeraldValue{Type: object.ValueArray, Data: values, Class: R.Classes["Array"]}
}

func moduleClassNesting(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if CurrentModuleNesting == nil {
		return &object.EmeraldValue{Type: object.ValueArray, Data: []*object.EmeraldValue{}, Class: R.Classes["Array"]}
	}
	return &object.EmeraldValue{Type: object.ValueArray, Data: CurrentModuleNesting(), Class: R.Classes["Array"]}
}

func moduleIncludedModules(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	ancestors := moduleAncestors(receiver)
	if ancestors == nil || ancestors.Type != object.ValueArray {
		return ancestors
	}
	values := make([]*object.EmeraldValue, 0)
	for _, ancestor := range ancestors.Data.([]*object.EmeraldValue) {
		if ancestor != nil && (ancestor.Type == object.ValueModule || ancestor.Type == object.ValueClass && ancestor.Data == R.Classes["Kernel"]) && !(receiver.Type == object.ValueModule && ancestor.Data == receiver.Data) {
			values = append(values, ancestor)
		}
	}
	return &object.EmeraldValue{Type: object.ValueArray, Data: values, Class: R.Classes["Array"]}
}

func moduleUsing(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if InMethodScope != nil && InMethodScope() {
		return newRuntimeException(R.Classes["RuntimeError"], "Module#using is not permitted in methods")
	}
	if len(args) != 1 {
		return NewArgumentError("wrong number of arguments")
	}
	for _, arg := range args {
		if arg == nil || arg.Type != object.ValueModule {
			return typeError("wrong argument type")
		}
		if UsingReceiverAllowed != nil && !UsingReceiverAllowed(receiver) {
			return newRuntimeException(R.Classes["RuntimeError"], "using is permitted only at toplevel")
		}
		if ActivateCurrentRefinement != nil {
			ActivateCurrentRefinement(SnapshotRefinement(arg))
		}
	}
	return receiver
}

func SnapshotRefinement(refinery *object.EmeraldValue) *object.EmeraldValue {
	if refinery == nil || refinery.Type != object.ValueModule || refinementModules == nil {
		return refinery
	}
	snapshotModule := object.NewModule("")
	snapshot := &object.EmeraldValue{Type: object.ValueModule, Data: snapshotModule, Class: R.Classes["Module"]}
	copyTargets := make(map[any]*object.EmeraldValue)
	collectRefinementTargets(refinery, copyTargets, map[*object.Module]bool{})
	if len(copyTargets) > 0 {
		refinementModules[snapshot] = copyTargets
	}
	return snapshot
}

func collectRefinementTargets(refinery *object.EmeraldValue, targets map[any]*object.EmeraldValue, seen map[*object.Module]bool) {
	if refinery == nil || refinery.Type != object.ValueModule {
		return
	}
	module := refinery.Data.(*object.Module)
	if module == nil || seen[module] {
		return
	}
	seen[module] = true
	for _, included := range module.IncludedModules {
		collectRefinementModuleTargets(included, targets, seen)
	}
	for target, refinement := range refinementModules[refinery] {
		targets[target] = refinement
	}
}

func collectRefinementModuleTargets(module *object.Module, targets map[any]*object.EmeraldValue, seen map[*object.Module]bool) {
	if module == nil || seen[module] {
		return
	}
	seen[module] = true
	for _, included := range module.IncludedModules {
		collectRefinementModuleTargets(included, targets, seen)
	}
	for refinery, refinements := range refinementModules {
		if refinery != nil && refinery.Type == object.ValueModule && refinery.Data == module {
			for target, refinement := range refinements {
				targets[target] = refinement
			}
			break
		}
	}
}

func moduleClassUsedRefinements(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	values := []*object.EmeraldValue{}
	seen := map[*object.EmeraldValue]bool{}
	if CurrentUsedRefinements != nil {
		for _, refinery := range CurrentUsedRefinements() {
			for _, refinement := range refinementModules[refinery] {
				if !seen[refinement] {
					seen[refinement] = true
					values = append(values, refinement)
				}
			}
		}
	}
	return &object.EmeraldValue{Type: object.ValueArray, Data: values, Class: R.Classes["Array"]}
}

func appendUsedRefinement(receiver, refinement *object.EmeraldValue) {
	var used *[]*object.EmeraldValue
	switch receiver.Type {
	case object.ValueClass:
		used = &receiver.Data.(*object.Class).UsedRefinements
	case object.ValueModule:
		used = &receiver.Data.(*object.Module).UsedRefinements
	default:
		return
	}
	for _, existing := range *used {
		if existing == refinement {
			return
		}
	}
	*used = append(*used, refinement)
}

func RefinedMethod(refinery, receiver *object.EmeraldValue, name string) (*object.Method, bool) {
	if refinery == nil || receiver == nil || refinery.Type != object.ValueModule || refinementModules == nil {
		return nil, false
	}
	byTarget := refinementModules[refinery]
	if byTarget == nil {
		return nil, false
	}
	var target any
	switch receiver.Type {
	case object.ValueClass:
		class := receiver.Data.(*object.Class)
		if class != nil {
			target = class.SingletonClass
		}
	case object.ValueModule:
		module := receiver.Data.(*object.Module)
		if module != nil {
			target = module.SingletonClass
		}
	default:
		target = receiver.Class
	}
	if target == nil {
		return nil, false
	}
	refined := byTarget[target]
	if refined == nil && receiver.Class != nil {
		if method, exists := receiver.Class.Methods[name]; exists && method != nil && byTarget[receiver.Class] == nil {
			return nil, false
		}
		refined = refinementForClassAncestry(byTarget, receiver.Class, map[*object.Class]bool{}, map[*object.Module]bool{})
	}
	if refined == nil || refined.Type != object.ValueModule {
		return nil, false
	}
	method, ok := refined.Data.(*object.Module).GetMethod(name)
	return method, ok
}

func RefinedInstanceMethod(refinery, target *object.EmeraldValue, name string) (*object.Method, bool) {
	if refinery == nil || target == nil || refinery.Type != object.ValueModule || (target.Type != object.ValueClass && target.Type != object.ValueModule) {
		return nil, false
	}
	byTarget := refinementModules[refinery]
	if byTarget == nil {
		return nil, false
	}
	refined := byTarget[target.Data]
	if refined == nil || refined.Type != object.ValueModule {
		return nil, false
	}
	method, ok := refined.Data.(*object.Module).GetMethod(name)
	return method, ok
}

func refinementForClassAncestry(byTarget map[any]*object.EmeraldValue, class *object.Class, seenClasses map[*object.Class]bool, seenModules map[*object.Module]bool) *object.EmeraldValue {
	if class == nil || seenClasses[class] {
		return nil
	}
	seenClasses[class] = true
	if refined := byTarget[class]; refined != nil {
		return refined
	}
	for _, module := range class.PrependedModules {
		if refined := refinementForModuleAncestry(byTarget, module, seenModules); refined != nil {
			return refined
		}
	}
	for index := len(class.IncludedModules) - 1; index >= 0; index-- {
		if refined := refinementForModuleAncestry(byTarget, class.IncludedModules[index], seenModules); refined != nil {
			return refined
		}
	}
	return refinementForClassAncestry(byTarget, class.SuperClass, seenClasses, seenModules)
}

func refinementForModuleAncestry(byTarget map[any]*object.EmeraldValue, module *object.Module, seen map[*object.Module]bool) *object.EmeraldValue {
	if module == nil || seen[module] {
		return nil
	}
	seen[module] = true
	if refined := byTarget[module]; refined != nil {
		return refined
	}
	for index := len(module.IncludedModules) - 1; index >= 0; index-- {
		if refined := refinementForModuleAncestry(byTarget, module.IncludedModules[index], seen); refined != nil {
			return refined
		}
	}
	return nil
}

