func moduleRefine(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if len(args) == 0 {
		return NewArgumentError("wrong number of arguments")
	}
	target := args[0]
	if target == nil || (target.Type != object.ValueClass && target.Type != object.ValueModule) {
		return typeError("wrong argument type")
	}
	if BlockGivenCheck == nil || !BlockGivenCheck() || CurrentBlockValue == nil || CurrentBlockValue() == nil {
		return NewArgumentError("no block given")
	}
	refined := refinementModuleFor(receiver, target)
	appendUsedRefinement(refined, receiver)
	if CallBlockWithSelf != nil {
		if result := CallBlockWithSelf(CurrentBlockValue(), refined); result != nil && result.Type == object.ValueException {
			return result
		}
	}
	return refined
}

func refinementModuleFor(receiver, target *object.EmeraldValue) *object.EmeraldValue {
	if refinementModules == nil {
		refinementModules = make(map[*object.EmeraldValue]map[any]*object.EmeraldValue)
	}
	byTarget := refinementModules[receiver]
	if byTarget == nil {
		byTarget = make(map[any]*object.EmeraldValue)
		refinementModules[receiver] = byTarget
	}
	key := target.Data
	if refined := byTarget[key]; refined != nil {
		return refined
	}
	module := object.NewModule("")
	module.IsRefinement = true
	module.RefinementTarget = target
	module.RefinementOwner = receiver
	refined := &object.EmeraldValue{Type: object.ValueModule, Data: module, Class: R.Classes["Refinement"]}
	byTarget[key] = refined
	return refined
}

func refinementTarget(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver != nil && receiver.Type == object.ValueModule {
		if module, ok := receiver.Data.(*object.Module); ok && module != nil && module.IsRefinement && module.RefinementTarget != nil {
			return module.RefinementTarget
		}
	}
	return R.NilVal
}

func refinementImportMethods(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver == nil || receiver.Type != object.ValueModule {
		return typeError("not a refinement")
	}
	target, ok := receiver.Data.(*object.Module)
	if !ok || target == nil || !target.IsRefinement {
		return typeError("not a refinement")
	}
	for _, arg := range args {
		if moduleFromMixin(arg) == nil {
			name := "Object"
			if arg != nil && arg.Class != nil && arg.Class.Name != "" {
				name = arg.Class.Name
			}
			return typeError("wrong argument type " + name + " (expected Module)")
		}
	}
	for _, arg := range args {
		source := moduleFromMixin(arg)
		if len(source.IncludedModules) > 0 || len(source.PrependedModules) > 0 {
			name := moduleDisplayName(arg)
			_ = builtinWarn(nil, rubyString("warning: "+name+" has ancestors, but Refinement#import_methods doesn't import their methods"))
		}
		for name, method := range source.Methods {
			if refinementMethodComesFromAncestor(source, name, method) {
				continue
			}
			if !refinementRubyMethod(method) {
				return NewArgumentError("Can't import method which is not defined with Ruby code: " + moduleDisplayName(arg) + "#" + name)
			}
			copy := *method
			copy.Name = name
			copy.Owner = receiver
			copy.DispatchOwner = receiver
			if method.Closure != nil {
				closure := *method.Closure
				closure.Refinements = append([]*object.EmeraldValue(nil), method.Closure.Refinements...)
				closure.Refinements = append(closure.Refinements, target.RefinementOwner)
				closure.RefinementsFixed = true
				copy.Closure = &closure
			}
			target.Methods[name] = &copy
		}
	}
	return receiver
}

func moduleRefinements(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	values := []*object.EmeraldValue{}
	if refinementModules != nil {
		for _, refinement := range refinementModules[receiver] {
			values = append(values, refinement)
		}
	}
	return &object.EmeraldValue{Type: object.ValueArray, Data: values, Class: R.Classes["Array"]}
}

func refinementRubyMethod(method *object.Method) bool {
	if method == nil {
		return false
	}
	if method.Closure != nil {
		return true
	}
	_, ok := method.Fn.(*object.Function)
	return ok
}

func refinementMethodComesFromAncestor(module *object.Module, name string, method *object.Method) bool {
	for _, ancestor := range append(append([]*object.Module(nil), module.IncludedModules...), module.PrependedModules...) {
		if inherited, ok := ancestor.GetMethod(name); ok && inherited == method {
			return true
		}
	}
	return false
}

func moduleDisplayName(value *object.EmeraldValue) string {
	if value == nil || value.Type != object.ValueModule {
		return "#<Module>"
	}
	module := value.Data.(*object.Module)
	if module.Name != "" {
		return module.Name
	}
	return value.Inspect()
}

func moduleExtend(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver.Type != object.ValueModule {
		return R.NilVal
	}
	module := receiver.Data.(*object.Module)
	for _, arg := range args {
		if arg.Type == object.ValueModule {
			mixin := arg.Data.(*object.Module)
			if mixin.IsRefinement {
				return typeError("Cannot extend refinement")
			}
			module.Extend(mixin)
		}
	}
	return R.NilVal
}

func moduleExtendObject(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver == nil || receiver.Type != object.ValueModule || len(args) == 0 {
		return R.NilVal
	}
	target := args[0]
	if target == nil {
		return R.NilVal
	}
	if target.Frozen {
		return newRuntimeException(R.Classes["RuntimeError"], "can't modify frozen object")
	}
	module := receiver.Data.(*object.Module)
	switch target.Type {
	case object.ValueObject:
		_, ok := target.Data.(*object.Object)
		if !ok {
			return R.NilVal
		}
		singleton := methodSingletonClass(target)
		if singleton.Type == object.ValueClass {
			cls := singleton.Data.(*object.Class)
			cls.Include(module)
			for name, constant := range module.Constants {
				cls.DefineConstant(name, constant)
			}
		}
	case object.ValueClass:
		class := target.Data.(*object.Class)
		singleton := methodSingletonClass(target)
		if singleton != nil && singleton.Type == object.ValueClass {
			singletonClass := singleton.Data.(*object.Class)
			singletonClass.Include(module)
			class.SingletonClass = singletonClass
		} else {
			class.Extend(module)
		}
		for name, constant := range module.Constants {
			class.DefineConstant(name, constant)
		}
	default:
		singleton := methodSingletonClass(target)
		if singleton == nil || singleton.Type != object.ValueClass {
			return typeError("wrong argument type")
		}
		cls := singleton.Data.(*object.Class)
		cls.Include(module)
		for name, constant := range module.Constants {
			cls.DefineConstant(name, constant)
		}
	}
	return target
}

func modulePrepend(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver.Type != object.ValueModule {
		return R.NilVal
	}
	if module, ok := receiver.Data.(*object.Module); ok && module.IsRefinement {
		return typeError("Refinement#prepend has been removed")
	}
	if len(args) == 0 {
		return NewArgumentError("wrong number of arguments")
	}
	for i := len(args) - 1; i >= 0; i-- {
		result := prependFeaturesForPrepend(receiver, args[i])
		if result != nil && result.Type == object.ValueException {
			return result
		}
		if hook := callPrependedHook(args[i], receiver); hook != nil && hook.Type == object.ValueException {
			return hook
		}
	}
	return receiver
}

func modulePrependFeatures(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver == nil || receiver.Type != object.ValueModule || len(args) == 0 {
		return R.NilVal
	}
	if args[0] == receiver {
		return NewArgumentError("cyclic prepend detected")
	}
	module := receiver.Data.(*object.Module)
	switch args[0].Type {
	case object.ValueClass:
		args[0].Data.(*object.Class).Prepend(module)
	case object.ValueModule:
		target := args[0].Data.(*object.Module)
		if target == module {
			return NewArgumentError("cyclic prepend detected")
		}
		target.Prepend(module)
	default:
		return typeError("wrong argument type")
	}
	return receiver
}

func prependFeaturesForPrepend(receiver *object.EmeraldValue, mixin *object.EmeraldValue) *object.EmeraldValue {
	if mixin == nil || mixin.Type != object.ValueModule {
		return typeError("wrong argument type")
	}
	if mixin.Data.(*object.Module).IsRefinement {
		return typeError("Cannot prepend refinement")
	}
	if CallMethod != nil {
		return CallMethod(mixin, "send", &object.EmeraldValue{Type: object.ValueSymbol, Data: "prepend_features", Class: R.Classes["Symbol"]}, receiver)
	}
	if receiver.Type == object.ValueClass {
		receiver.Data.(*object.Class).Prepend(mixin.Data.(*object.Module))
	}
	return mixin
}

func classInclude(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver.Type != object.ValueClass {
		return R.NilVal
	}
	if len(args) == 0 {
		return NewArgumentError("wrong number of arguments")
	}
	for i := len(args) - 1; i >= 0; i-- {
		result := appendFeaturesForInclude(receiver, args[i])
		if result != nil && result.Type == object.ValueException {
			return result
		}
		if hook := callIncludedHook(args[i], receiver); hook != nil && hook.Type == object.ValueException {
			return hook
		}
	}
	return receiver
}

func callIncludedHook(mixin *object.EmeraldValue, target *object.EmeraldValue) *object.EmeraldValue {
	if CallMethod == nil {
		return nil
	}
	hook := CallMethod(mixin, "send", &object.EmeraldValue{Type: object.ValueSymbol, Data: "included", Class: R.Classes["Symbol"]}, target)
	if hook != nil && hook.Type == object.ValueException && !isNoMethodError(hook) {
		return hook
	}
	return nil
}

func classExtend(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver.Type != object.ValueClass {
		return R.NilVal
	}
	class := receiver.Data.(*object.Class)
	for _, arg := range args {
		if arg.Type == object.ValueModule {
			module := arg.Data.(*object.Module)
			if module.IsRefinement {
				return typeError("Cannot extend refinement")
			}
			singleton := methodSingletonClass(receiver)
			if singleton != nil && singleton.Type == object.ValueClass {
				singletonClass := singleton.Data.(*object.Class)
				singletonClass.Include(module)
				class.SingletonClass = singletonClass
			} else {
				class.Extend(module)
			}
		}
	}
	return R.NilVal
}

func classPrepend(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
	if receiver.Type != object.ValueClass {
		return R.NilVal
	}
	if len(args) == 0 {
		return NewArgumentError("wrong number of arguments")
	}
	for i := len(args) - 1; i >= 0; i-- {
		result := prependFeaturesForPrepend(receiver, args[i])
		if result != nil && result.Type == object.ValueException {
			return result
		}
		if hook := callPrependedHook(args[i], receiver); hook != nil && hook.Type == object.ValueException {
			return hook
		}
	}
	return receiver
}

func callPrependedHook(mixin *object.EmeraldValue, target *object.EmeraldValue) *object.EmeraldValue {
	if CallMethod == nil {
		return nil
	}
	hook := CallMethod(mixin, "send", &object.EmeraldValue{Type: object.ValueSymbol, Data: "prepended", Class: R.Classes["Symbol"]}, target)
	if hook != nil && hook.Type == object.ValueException && !isNoMethodError(hook) {
		return hook
	}
	return nil
}
func NewArgfValue(values []*object.EmeraldValue) *object.EmeraldValue {
	return newArgfValue(values)
}

func argfClassValueInstance() *object.EmeraldValue {
	if argfClassValue != nil {
		return argfClassValue
	}

	argfClass := object.NewClass("ARGF")
	argfClass.SuperClass = R.Classes["Object"]
	argfClass.DefineClassMethod("new", &object.Method{
		Name:  "new",
		Arity: -1,
		Fn: func(receiver *object.EmeraldValue, args ...*object.EmeraldValue) *object.EmeraldValue {
			values := []*object.EmeraldValue{}
			if len(args) == 1 && args[0] != nil && args[0].Type == object.ValueArray {
				for _, value := range args[0].Data.([]*object.EmeraldValue) {
					if value != nil && value.Type == object.ValueString {
						values = append(values, value)
					}
				}
				return newArgfValue(values)
			}
			for _, value := range args {
				if value != nil && value.Type == object.ValueString {
					values = append(values, value)
				}
			}
			return newArgfValue(values)
		},
	})
	argfClassValue = &object.EmeraldValue{
		Type:  object.ValueClass,
		Data:  argfClass,
		Class: R.Classes["Class"],
	}
	R.Classes["ARGF"] = argfClass
	return argfClassValue
}
